def finding_lines(lines) -> list:
    """The finding lines of a refusal as they are COMPARED: whitespace collapsed, a real dispatch id replaced by
    `<dispatch>` (the same findings of the next dispatch are the same findings), blanks dropped, de-duplicated and
    sorted - a set, never a count and never an order. `[]` is "no findings", which is never equal to anything (FR-41)."""
    found = set()
    for raw in lines or []:
        line = " ".join(DISPATCH_ID_RE.sub("<dispatch>", str(raw)).split())
        if line:
            found.add(line)
    return sorted(found)


def finding_key(lines) -> str:
    """The identity of a finding set: the sha256 of its `finding_lines`, `""` for an empty set."""
    found = finding_lines(lines)
    return hashlib.sha256("\n".join(found).encode("utf-8")).hexdigest() if found else ""


def gate_refusal(script: str, code, out: str, expect: str, retry=None) -> "Refusal":
    """THE refusal of a G step (C1-7b, §3.1/§3.6): a factory script that must leave something behind did not (FR-1: what failed, what
    was expected, the door). Marked `known = False`, so the known-refusals table never routes it (`route_known`). An empty `out` reads
    "the step said nothing" (E12). Built here once for `Driver.py(check=True, expect=...)` and for a G step that reads a record before
    it decides (readiness `--require`)."""
    refusal = Refusal(f"the factory step {script} did not complete (exit {code}): expected {expect}. The door: retry runs the "
                      f"same command; the step's own words: {(out or '')[-600:] or 'the step said nothing'}", retry=retry)
    refusal.known = False
    return refusal


def json_record(out: str) -> tuple:
    """THE read of a script's printed record (C1-7b fix round, F-1, FR-14; AR-13): `(the first JSON object in out, the text after it)`.
    `(None, out)` when there is no `{` or what follows it does not parse - an unreadable record is `None`, never a guess and never a
    pass: the caller refuses on it (S0's `readiness.py --require --json`, S8's and gate B's `check_delivery.py --json`). It raises
    nothing. The text after the record is what the script printed behind it (readiness's WARN lines)."""
    text = out or ""
    start = text.find("{")
    if start < 0:
        return None, text
    try:
        doc, end = json.JSONDecoder().raw_decode(text[start:])
    except ValueError:
        return None, text
    return doc, text[start + end:].strip()


class WindowsUnreadable(ValueError):
    """`Driver.s5_open_windows` could not read the windows, the dispatches or a scope (FR-59): the caller treats that as open, never as a
    close. A ValueError for any reader that catches that; its own name so it is told from a programming error."""


class Refusal(Exception):
    """A factory script said no. `text` is its message verbatim; `retry` re-runs the step.

    `dispatch` is the id this refusal is about, when the raiser knows it. An id read back out of
    the message it was just written into is the FR-16 class in miniature — the driver wrote
    "exit gate for S1-qa-scout-2" and then went looking for that id with a regex over its own
    sentence. The field is the answer; the regex stays as the reader of refusals other scripts
    raise, whose text is all there is.
    """

    # `known` (C1-7b, F10): False on a refusal of a G step (`py(check=True, expect=...)`, a gate step that left no product): the
    # known-refusals table never routes it (`route_known` returns None), so words that its script's output happens to hold
    # (`already completed`, `STORY BUDGET`, ...) cannot turn it into `continue` past an unwritten product. A class attribute, so a
    # refusal built before this field existed (or by any other raiser) reads True and keeps its move.
    known = True
    chain = None            # TR3-17: a class default too, so a subclass that does not call `super().__init__` still reads None

    def __init__(self, text: str, retry=None, files=None, dispatch: str = "", findings=None, window_findings=None,
                 title: str = "", close=None):
        super().__init__(text)
        # `close` (C2-8): the mark of a refusal at a place where the CODE closes a stage with no role - `{site, stage, step, ...}`.
        # A non-empty `close` is the whole mark (no second field that could disagree); `handle_refusal` reads it.
        self.close = dict(close or {})
        # `title`: a NAME the raiser gives a refusal the driver must tell from its neighbours (`second_delivery`), so the
        # driver reads the field and never a regex over its own sentence (the anti-pattern this docstring names above).
        self.title = str(title or "")
        self.text = str(text or "").strip()
        self.retry = retry
        self.files = list(files or [])
        self.dispatch = str(dispatch or "")
        # `findings`: the lines the raiser itself judged (the handoff passes the exit gate's errors WHOLE; its `text`
        # is the head + the list as `Driver.listed` shows it - several lines, cut at the byte ceiling with a pointer
        # to the file, C2-1). `window_findings`: the gap lines `window_record.py` printed for this finish, read by the
        # window-round cap ONLY (t-217 C2) - the one-resume record keys on the refusal's own words, never on them,
        # and they are never part of `text`.
        self.findings = [str(x) for x in (findings or [])]
        self.window_findings = [str(x) for x in (window_findings or [])]
        # `chain` (TR3-17): the ChainRecord of the thread that raised this, None on the main thread and on the serial road. The seam's
        # retry on the main thread adopts it (`Driver.adopt_chain`) so `boundary` and `last_dispatch` read the chain's, not main's.
        self.chain = getattr(_CHAIN, "record", None)


@dataclass(frozen=True)
class OpenWork:
    """Work the driver KNOWS is left in a stage when its closing role finishes (t-721 §4.2; created by C1-5b2, used by S7 first):
    a `complete` callable returns it and `Driver.finish` sends `--not-complete --unresolved <unresolved> --reason <reason>`, so the
    stage stays open on a pair the controller accepts. NOT a `tuple` (a tuple there means "complete, with this pair"); a field that
    is empty after stripping makes the plain `--not-complete`."""
    unresolved: str
    reason: str


def open_work_reason(text: str, mark: str, limit: int = 300) -> str:
    """The reason of an `OpenWork`, at most `limit` characters: a longer text is cut and ends with `mark` (`… [list: <path>]`, the
    path of the whole list). The ONE cut of the two stages that return one (S7 `repairs_pending`, S4 `cases_in_repair`); the reason
    stays on the dispatch record after the close, so it is TIMELESS - what was done, never what 'now' is."""
    return text if len(text) <= limit else text[:limit - len(mark)] + mark


class ReworkRefused(Refusal):
    """The CONTROLLER refused to register a rework (or answered with no dispatch id), before any role ran.
    Raised by `Driver.rework` alone and still a `Refusal` for every other caller; the gate-entry repair
    tells it from the refusals the role's own run raises afterwards (a handoff form, a finish), which must
    keep going to `guarded` and its known table."""


class RepairFailed(Exception):
    """A move of the gate-entry repair failed before it did anything: `what` is the command, `text` the
    refusal's own words. Caught by `gate_repair` and by `take_stand_gap_answers` (a container a person named): the round
    is recorded as failed and the conductor gets the command and the end of its output (never a blind second try)."""

    def __init__(self, what: str, text: str):
        super().__init__(what)
        self.what, self.text = what, str(text or "")


class Priced(str):
    """The text of a closed question built by `Driver.closed_question` (C1-3): the str itself, plus `priced` - the tokens, as the
    site wrote them (not normalized), of those of its options that carry a token and their three price lines. `Person` reads it from the text it is given;
    `judge_own_question` checks `offered` and `priced` together; it is NEVER written into `asked.offered` (only the seam's
    questions carry `offered`, so the position invariant of `take_answer` holds)."""
    priced: tuple = ()
    sources: tuple = ()        # `s1_gap` only (C2-9): the source ids the question names / the causes it offers a kind-token for
    classes: tuple = ()
    details: str = ""          # the factory's own words that did not fit the body (the whole list of the sources named)

    def __new__(cls, text, priced=()):
        made = super().__new__(cls, text)
        made.priced = tuple(priced)
        return made


class Person(Exception):
    """The person is needed: kind, the text they read, and the dispatch it concerns.

    `details` is the factory's own words - a refusal, a detector's output - which the person
    may want and must not be handed instead of a question. `ask()` writes it beside the
    question and names the file in the answer block (references/human-questions.md).

    `answer_note` is a line for the answer block itself (t-335 B-n4): a path the person needs and the body must not
    carry - human-questions.md rule 5 allows a path only there, where it is an instruction."""

    def __init__(self, kind: str, text: str, stage: str = "", dispatch: str = "",
                 code: int = EXIT_PERSON, details: str = "", answer_note: str = ""):
        super().__init__(text)
        self.kind, self.text, self.stage, self.dispatch, self.code = kind, text, stage, dispatch, code
        self.details = str(details or getattr(text, "details", "") or "")
        self.answer_note = str(answer_note or "")
        # `s1_gap` (C2-9): what the question named, written into `asked` by `ask()` for that kind ALONE - its tokens close exactly this.
        self.sources, self.classes = tuple(getattr(text, "sources", ())), tuple(getattr(text, "classes", ()))
        # Set by `Driver.no_move` ALONE, and written into `asked` by `ask()`: the tokens this question offers (normalized),
        # `[{token, move}]`, the original words' file (task-root relative), why it was asked, the waivable block code knows.
        self.offered, self.options, self.words_file, self.why, self.block = (), (), "", "", ""
        # C1-7a (B-1): the ids of the owed rows a seam question is about, written into `asked` by `ask()`: the question's identity for
        # the pairing of the person's `go on` (`Driver.mark_rows_word`), never a clock.
        self.rows = ()
        # B-16: the case keys of the S5 probe gap a seam question named (`window_record.probe_gap_cases`); written into `asked` by
        # `ask()`; its `go on` records one `probe gap: <case key>` word for each (`seam_chosen`).
        self.probe_gap_cases = ()
        # t-1968 N5: the case keys of the S5 tests whose probe the code reviewer could not judge (`window_record.probe_judgment_cases`);
        # written into `asked` by `ask()`; its `go on` records one `probe not proved: <case key>` word for each (`seam_chosen`).
        self.probe_judgment_cases = ()
        # Set by `Driver.held_question` ALONE, and written into `asked` by `ask()`: the lead that helper put above the question's body,
        # so the next `held_question` takes exactly that off (the extent of a lead is kept, never read back by its words).
        self.held_lead = ""
        # RN1-9 (P22, FR-48): the question class (`person_owned.py`) this question answers, what the conductor read, and who
        # raised it (`conductor` / `fallback` / `code` / `delivery`); written into `driver-questions.jsonl` by `judge_own_question`.
        self.why_person, self.checked, self.source = "", "", "code"
        # The tokens of the priced options a `closed_question` text carries: checked by `judge_own_question` beside `offered`.
        self.priced = tuple(getattr(text, "priced", ()))
        # RN1-24 (P22): the case ids whose check waits for THIS question's answer, set by the sites that raise a question about
        # some cases (`stand_login_gate`, `gate_a_dry_person`) and read by `Driver.deferrable`. The field is `holds`, never `blocks`
        # (`asked["blocks"]` is the waiver blocks of a conductor question). Empty = the question holds everything: asked at once.
        self.holds = ()


class Stop(Exception):
    """An exit of the run (a usage error, a missing `claude`, a stop the infrastructure forced): nothing is asked, `run()` prints
    the reason and returns the code. The one exception is the conductor's `stop` of a gate or the S1 review (exit 4, not an
    `InfraStop`), which `run()` turns into the priced question. A Stop that carried a `state` for the seam had no producer after
    C1-3 (P01 became a closed question), so the field is gone (F4): code with no producer is a wish, not a mechanism."""

    def __init__(self, code: int, reason: str):
        super().__init__(reason)
        self.code, self.reason = code, reason


class ConductorSpent(Exception):
    """The conductor was called `CONDUCTOR_CALLS_PER_BOUNDARY` times at this boundary. Raised by `Driver.conductor` and caught
    by `Driver.no_move` ALONE: the cap is a reason to enter the seam, never a text of its own."""

    def __init__(self, count: int, refusal: str):
        super().__init__(f"the conductor was called {count} times at this boundary")
        self.count, self.refusal = count, refusal


class InfraStop(Stop):
    """`claude -p` failed for a reason outside the story (`kind`: auth, limit, transient) and the
    retries, where there are any, are spent. Raised by `run_claude` only, and never turned into a
    Refusal or a Person: TP1-13877 turned a login error into a conductor question, and the
    person was asked about a call no role had made. `reason` is the whole message: what happened in
    plain words, then the command that goes on."""

    def __init__(self, kind: str, message: str):
        super().__init__(EXIT_INFRA, message)
        self.kind = kind


def _now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def _answer_note(prefix: str, words: str) -> str:
    """A journal note that carries a person's words: the prefix, then the words WHOLE (FR-8).
    Every later brief reads `human_answer` notes as the person's standing instructions, so a
    silent cut here loses them for every role after it. Only `brief_pack.PERSON_WORDS_MAX` cuts,
    and that cut says so (the one helper, `brief_pack.person_words_whole`)."""
    import brief_pack
    return prefix + brief_pack.person_words_whole(words)


def _sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _read_json(path: Path, default=None):
    """`hooklib.read_json` (the package's one JSON reader) with this driver's direction: a file that is absent or not
    JSON is `{}`, or the caller's own `default`."""
    return hooklib.read_json(path, {} if default is None else default)


def _write_json(path: Path, data) -> None:
    """The driver's JSON writer. Published by `event_store.atomic_json` (the package's one publisher: a unique temp name, and a replace
    that rides out a reader holding the file on Windows), so a reader across processes (`dispatch_liveness`, `story_step`, ...) never
    sees a torn file and never makes the write fail. A publisher that still fails is said in one note and the old in-place write
    follows - the write that worked before; it is never raised from here for a reader's sake."""
    import event_store
    path.parent.mkdir(parents=True, exist_ok=True)
    try:
        event_store.atomic_json(path, data)
    except OSError as exc:
        print(f"note: {path.name} could not be published atomically ({type(exc).__name__}); it is written in place", flush=True)
        path.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")


def _append_jsonl(path: Path, record: dict) -> None:
    """One row appended through the package's ONE appender (AR-15, axis 29): a torn tail gets its `\\n` first, the folder is made, an
    `OSError` reaches the caller. `json.dumps` writes no raw line break, so `append_jsonl_line`'s `ValueError` cannot fire. TR4-11: the
    line ends `\\n` on Windows too (the text-mode write ended `\\r\\n`); every reader splits on `\\n` or takes `\\r` as JSON whitespace."""
    hooklib.append_jsonl_line(path, json.dumps(record, ensure_ascii=False))


def _read_jsonl(path: Path) -> list:
    """Every readable row of a journal. A half-written last line is skipped, never raised: a
    journal is read to decide something, and a crash mid-append must not stop the loop."""
    rows = []
    try:
        for line in path.read_text(encoding="utf-8", errors="replace").splitlines():
            if not line.strip():
                continue
            try:
                row = json.loads(line)
            except ValueError:
                continue
            if isinstance(row, dict):
                rows.append(row)
    except OSError:
        return []
    return rows


def _read_answer(out: str):
    """The ONE reader of a script's answer in `Driver.py` text (t-2020; AR-13, AR-18, AR-28): the LAST line of stdout+stderr that
    parses as a JSON object. A warning a script prints to stderr before or after its answer (a path note, a deprecation) stays in
    the text and does not hide the answer. No such line is `None` - the caller names what came back; it is never an empty answer.
    The reader itself is `hooklib.read_answer`, shared with story_step.py."""
    return hooklib.read_answer(out)


# One source for the machine head above a question: `head_pattern` in references/human-text.json.
# The text hashed here and the text checked by `human_text.problems` lose the same lines. The
# pattern is line-based on purpose: with re.S a `.` in it eats the rest of the document, which is
# how the first version of this hashed every question to the same empty body.
QUESTION_HEAD_RE = human_text.HEAD_RE
ANSWER_BLOCK_RE = re.compile(r"\n---\nAnswer:.*", re.S)
# Refusals one boundary absorbs; the one after them ends in a question. `guarded` and the words of
# `refused_text` both read this, so the text and the cap cannot drift. (The three standing answers every such question
# offers are the `fallback` block of conductor-actions.json, rendered by the seam with their price lines: C1-1.)
REFUSALS_PER_BOUNDARY = 6
# C1-7a (P22, t-1162): a journal row of a person's words (or an FR-4 finding, or a `--warn` line) that its script refused is OWED: it is
# written again before any brief is built (`Driver.owed_rows_step`), and a row refused a second time is the seam's question. The block
# name is the person's `go on` over rows that cannot be written; it is a row of references/block-names.json (reader: `owed_rows_step`).
OWED_ROW_TRIES = 2
JOURNAL_ROWS_BLOCK = "journal rows not written"
# C1-7c (O1, O3; kind T as T1): the invariant of the `halted` stage record written right before `Person("halt")`. ONE text for the two
# sites that run the halt road (`run_role`, `_finish_saved_result`), so the `trace_failed` line and the code say the same thing. The
# question-threshold stop (`question_threshold`, T1) writes the same record with its own `why`: its role IS resumed (F-4 of t-1252).
HALT_RECORD_WHY = ("a halted role's record is a mark the later readers show (the gate brief, the retro); the person is asked about the "
                   "halt either way (the Person is raised next, from the role's own digest) and the role is not run again for it - a "
                   "missed mark is journalled as trace_failed, never silent")


def recorded_earlier(script: str, code: int) -> bool:
    """A row's script exit that means "this finding is already in the journal under that key" (project_decisions.py's own exit code,
    read as a number, never by its words - FR-12). Such a row is WRITTEN: not owed, not run again, no question."""
    return script == "project_decisions.py" and code == project_decisions.RECORDED_EARLIER_EXIT
# A stage the CODE closes with no role (conductor/2 C2-8, t-745; class K3): site id -> (stage, what the code does, in words for a person).
# The closed variety of the factory (FR-13). A refusal raised at one of these sites carries `close` (see `Refusal`), and the driver puts
# it to the person through `Driver.code_close` instead of calling the conductor. The S0 closes are not in the table (the record is made
# before the refusal; B1 of the review).
CODE_CLOSE_SITES = {
    "s6.nothing": ("S6", "there was nothing to run"),
    "s6.results_stand": ("S6", "every automated result still stands, so nothing was run again"),
    "s6.reprobed": ("S6", "the tests ran on their current code, and the live checks of the tests that changed were proved again or left as they were"),
    "s6.manual_close": ("S6", "the checks done by hand are counted"),
    "s6.accepted": ("S6", "the failure analyst accepted the runner's handoff"),
    "s7.accepted": ("S7", "the doc scribe accepted the failure analyst's triage"),
    "s7.no_failures": ("S7", "no test failed, so there is nothing to sort"),
    "s7.pretriaged": ("S7", "every failure already has a state the run recorded"),
    "s7.after_repairs": ("S7", "the repairs of the failed tests ended"),
    "s7.repair_verdicts": ("S7", "the failed tests to repair are named by a description of the factory's own"),
    "s9.skip": ("S9", "the retro is skipped, as you asked"),
    "s9.numbers": ("S9", "the retro is the numbers only, as you asked"),
}
STUCK_REPEATS = 4        # the same `where` answer this many times in a row: the stuck seam (B-20 N5); the lead text names the number
# The deferred record of a stage the code closed (`code_close_step`): at most this many idle turns before the person is asked.
CODE_CLOSE_IDLE_CAP = 2
BY_PERSON = "by: person"     # the quote prefix of a driver accept that a person's word made (`person_pass` writes it, `consumer_close_words` reads it)


def question_body_sha(text: str) -> str:
    """The identity of a question's BODY: its head (timestamp, ids) and its answer block are
    not part of what is being asked, so two asks of the same thing hash the same.

    FR-7 is the rule this serves: a boundary a person has answered is never re-asked with the
    same text. One `resolve_return` packet reached the person three times unchanged in run 5,
    because nothing compared what was being asked with what had already been answered."""
    body = QUESTION_HEAD_RE.sub("", str(text or ""), count=1)
    body = ANSWER_BLOCK_RE.sub("", body)
    return hashlib.sha256(" ".join(body.split()).encode("utf-8")).hexdigest()


def _mechanical(error: str) -> bool:
    """Is this refusal the role's own to close? The refusal says so itself.

    An earlier version of this matched a list of wordings, which is the same mistake the
    known-refusal table already made once: a check added anywhere phrases itself differently and
    falls through to the person. The marker is what scripts put there deliberately (P6), so the
    only thing to read is the marker.
    """
    return REPAIR_MARKER.lower() in str(error or "").lower()


# Who wrote a review comment is a fact in the payload; what it is worth is not. GitLab marks a
# service account `bot`, and this instance's CI posts as `auto_*_vcs` — on !1522 those accounts
# wrote most of the 101 comments, each a pipeline log, and inlining them made a 1.7 MB "digest".
# Code never decides what matters; it decides only what fits in one file. A comment over this
# size moves to a file of its own with its address left behind — a pasted build log and a
# decisive review argument look identical by size, and telling them apart is the reader's work.
BIG_COMMENT_BYTES = 8000


def _is_bot(author: dict) -> bool:
    """Only what the server itself declares. Guessing a service account from its name (`auto_`,
    `_vcs`, `ci`) works on one instance and misnames a person on the next, and the factory runs on
    projects nobody here has seen. Where the server says nothing, size decides instead - and a
    byte is the same fact on every instance."""
    return (author or {}).get("bot") is True


def _note_lines(notes: list) -> list:
    out = []
    for note in notes:
        who = ((note.get("author") or {}).get("name") or "?")
        when = str(note.get("created_at") or "")[:10]
        out += [f"**{who}**" + (f", {when}" if when else "") + ":", "",
                str(note.get("body") or "").strip(), ""]
    return out


def match_known(text: str):
    """(name, action) of the row the refusal matches, or None.

    The marker comes first, and on purpose: the table was written from experience - one regex
    per message this driver had already met - so every refusal a new check adds went wherever
    the default led, which on TP1-13797 meant the conductor read factory sources at $0.88 a
    turn to decide something the refusal itself already knew. A script that knows the answer is
    the role's own work says so in `role_cli.REPAIR_MARKER`, and no row has to be added here
    for the driver to hand it back to the role (P6)."""
    body = text or ""
    if REPAIR_MARKER.lower() in body.lower():
        return "marked_repair", "resume_repair"
    if PERSON_MARKER.lower() in body.lower():
        return "marked_person", "ask_person"
    for name, pattern, action in KNOWN_REFUSALS:
        if re.search(pattern, text or "", re.IGNORECASE | re.DOTALL):
            return name, action
    return None


def route_known(refusal):
    """(name, action) of the ONE row every item of the refusal agrees on, or None (the conductor, with the whole text).

    A refusal that is a LIST (an exit gate's findings, the controller's combined refusal `N problems - the request is
    refused whole, every one is listed:`) is routed item by item: `match_known` over the whole text would let one item's
    phrase or marker lead the rest (K1, t-720 §3.4). INVARIANT: no item is routed by a neighbour's phrase or marker, and
    nothing that goes to the conductor alone today becomes `continue`, `retry` or a resume of the role through another
    item. Items: `refusal.findings` when there are two or more; else the items of the head `split_items` reads from the
    text with the transport taken off (`refusal_text`: the `story_step: refused - ` prefix and the JSON escaping of
    `--operation decision`). No head and fewer than two findings: `match_known` of the text, as before, byte for byte.
    A head that is there but whose items are fewer than two or do not match its count is NEVER matched over the whole
    text: the conductor reads it.

    A G refusal (`known` False, C1-7b F10) is NEVER routed by the table: its text holds a script's own words, and a phrase
    in them (`already completed`, `expected_revision`, `STORY BUDGET`, `event committed;`, `stands in front of gate`) must
    not turn a step that left no product into `continue`, `retry` or `ask_person`. INVARIANT: every such refusal reaches the
    conductor (FR-12: the table never reads a G step's output)."""
    if getattr(refusal, "known", True) is False:
        return None
    items = list(getattr(refusal, "findings", None) or [])
    if len(items) < 2:
        found = DV.split_items(DV.refusal_text(refusal.text))
        if found is None:
            return match_known(refusal.text)
        items = found
        if len(items) < 2:
            return None
    routes = {match_known(item) for item in items}
    return routes.pop() if len(routes) == 1 else None


# --- why a role is resumed, in one line (t-342, B-273) -----------------------------------------------------
# man1 02.10: the S7 analyst was resumed twice and the S8 scribe once - about five minutes of wall in 22 - and the
# driver log said only "witness OK (re-run by the exit gate)". Every resume now names its reason. The classes are the
# factory's OWN refusal families (the rows of `KNOWN_REFUSALS`, reused by name so the two cannot drift, plus the line
# `form_errors` writes), a closed set owned by this code and not a person's or a project's variety (FR-13); a finding
# that matches none is printed as it is, under `unclassified`, so a new family shows up in the log instead of hiding.
KNOWN_PATTERN = {name: pattern for name, pattern, _action in KNOWN_REFUSALS}
RESUME_CLASSES = (
    (KNOWN_PATTERN["handoff_form"], "the role's final message is not the handoff form"),
    (r"^handover form |" + KNOWN_PATTERN["handover_form"], "the handover form is not complete"),
    (KNOWN_PATTERN["form_vocabulary"], "a value of the handover form is outside its closed list"),
    (KNOWN_PATTERN["structured_artifact"], "the controller refused the role's structured artifact"),
    (KNOWN_PATTERN["missing_output"], "a required output of the role is missing"),
)
# The ONE class the driver closes by code instead of resuming (`Driver.assemble_digest`): the exit gate's refusal of
# a final message that is not the handoff form.
FINAL_MESSAGE_FORM_RE = re.compile(r"^digest: your final message is not the handoff form", re.IGNORECASE)


def resume_reason(findings) -> str:
    """One short line naming why a role is resumed, from the findings it is resumed on (a list of lines, or one
    text). Classified findings give their class words, each once, in order; a finding no class knows is quoted
    whole (200 characters) under `unclassified (...)` - with no finding at all the line says so, and is never empty."""
    if isinstance(findings, str):
        findings = [findings]
    lines = [" ".join(str(f).split()) for f in findings or [] if str(f).strip()]
    classes, rest = [], []
    for line in lines:
        for pattern, words in RESUME_CLASSES:
            if re.search(pattern, line, re.IGNORECASE | re.DOTALL | re.MULTILINE):
                if words not in classes:
                    classes.append(words)
                break
        else:
            rest.append(line)
    if rest:
        unknown = f"unclassified ({rest[0][:200]})"
        return "; ".join(classes + [unknown]) if classes else unknown
    return "; ".join(classes) if classes else "unclassified (the exit gate named no finding)"


def parse_next(out: str) -> dict:
    """The `next: {...}` line story_step and controller print."""
    for line in reversed((out or "").splitlines()):
        line = line.strip()
        if line.startswith("next:"):
            try:
                return json.loads(line[len("next:"):].strip())
            except ValueError:
                break
    raise Refusal("no `next:` line in: " + (out or "")[-600:])


READ_BUDGET = object()      # the default of a `budget` argument: none was passed, the repair-limit gate reads the controller's count


def parse_prompt(out: str) -> tuple:
    """(dispatch id, the Agent prompt block) out of `story_step.py start`'s output."""
    match = re.search(r"^dispatched (\S+) \(revision", out or "", re.M)
    dispatch = match.group(1) if match else ""
    lines, inside = [], False
    for line in (out or "").splitlines():
        if line.startswith("--- Agent prompt, verbatim"):
            inside = True
            continue
        if inside and line.startswith("--- the moment the Agent call returns"):
            break
        if inside:
            lines.append(line)
    if not dispatch or not lines:
        raise Refusal("story_step start printed no dispatch and prompt: " + (out or "")[-800:])
    return dispatch, "\n".join(lines).strip()


def mr_record(value) -> str:
    """The delivery verdict's `mr` kept only when it has the SHAPE of a record of an opened MR, else `""` (a shape check, not a
    phrase list: FR-12/13). A record is a link (`scheme://...`), an id token (no spaces, a digit, at most 40 characters: `!42`,
    `#7`, `42`, `MR-42`), or a whole number. `none`, `N/A`, `not opened`, an empty or blank text, a bool or a float is no record:
    the order is then called off `delivered_without_mr`, never closed as done with a word that names no MR."""
    if isinstance(value, int) and not isinstance(value, bool):
        return str(value)
    text = value.strip() if isinstance(value, str) else ""
    if re.match(r"[A-Za-z][A-Za-z0-9+.-]*://\S", text) or (
            len(text) <= 40 and not re.search(r"\s", text) and re.search(r"\d", text)):
        return text
    return ""


def last_json_line(text: str) -> dict:
    """The conductor's verdict: the last line of its answer that is a JSON object."""
    for line in reversed((text or "").splitlines()):
        line = line.strip().strip("`")
        if line.startswith("{") and line.endswith("}"):
            try:
                data = json.loads(line)
                if isinstance(data, dict) and data.get("action"):
                    return data
            except ValueError:
                continue
    return {}


def named_files(text: str, roots: list, limit: int = CONDUCTOR_FILES) -> list:
    """Existing files a refusal names, resolved against the given roots, at most `limit`."""
    found, seen = [], set()
    for raw in PATH_RE.findall(text or ""):
        candidate = raw.strip("`'\"")
        for root in roots:
            path = (Path(candidate) if Path(candidate).is_absolute() else Path(root) / candidate)
            try:
                resolved = path.resolve()
            except OSError:
                continue
            if resolved.is_file() and str(resolved) not in seen:
                seen.add(str(resolved))
                found.append(resolved)
                break
        if len(found) >= limit:
            break
    return found


class RelayCtx(NamedTuple):
    """t-667 D17: what `Driver._relay_note` reads about the answer being relayed - fixed by the time the note is built and never
    changed by it: the form ids of the gaps, the gaps, the rehearsal (None when none ran), the gate letter and the stage a gap with
    none of its own is recorded under. The things the note's builder fills or the caller goes on to use (`out`, `found`) stay
    explicit arguments (E11: a mutable is never put in a context object)."""
    forms: dict
    gaps: list
    rehearsal: dict | None
    gate: str
    default_stage: str


INCOMPLETE_STREAM = ("the Codex event stream ended with no terminal turn event (no turn.completed, no turn.failed), "
                     "so what the call did is not known")
NO_EVENTS_STREAM = ("the Codex CLI printed text but no event under --json, so there is no result to take and what the "
                    "call did is not known")


def parse_codex_jsonl(raw: str, *, resume: str = "") -> dict:
    """The result of a Codex CLI call in the shape `run_claude` reads, from the `--json` event stream of
    `codex exec` (codex-cli 0.158.0: event types `thread.started`, `turn.started`, `turn.completed`,
    `turn.failed`, `error`, `item.started`, `item.updated`, `item.completed`; item type `agent_message`; usage keys
    `input_tokens`, `cached_input_tokens`, `output_tokens` - the names read in the binary, not a live run).

    - `session_id`: the `thread_id` of `thread.started` (any event that carries one), else `resume`.
    - The LAST terminal event (`turn.failed`, `turn.completed`) decides the call (CX1-15 S-7):
      `turn.failed` -> `is_error`, `subtype` `turn_failed`, `result` = ITS message (the failure is what the call says,
      as a failed `claude -p` answers with its error and not with the role's last words; the agent text before it is
      `partial`, and never the result); `turn.completed` -> success, an `error` event before it is a note of the
      stream (`errors`), not a failure (E-5).
    - No terminal event but an `error` event: `is_error`, `subtype` `error_event`, `result` = the messages.
    - No terminal event and no `error`, events read: `is_error`, `subtype` `turn_incomplete`, `result` =
      `INCOMPLETE_STREAM` (E-3, F-10: an unknown outcome is never a success and never a classified failure),
      the agent text `partial`.
    - `resume_mismatch` (E-7): a resumed call whose `thread.started` names ANOTHER thread is `is_error` with the
      session of the request, the new id in `errors`, `num_turns` 0 (the requested thread did no work): a
      continuation never silently becomes a new thread.
    - A success: the text of the LAST `agent_message` item.
    - No event at all: the lines that were not events are `is_error`, `subtype` `no_events`, `result` =
      `NO_EVENTS_STREAM`, the text kept as `partial` (F-4: a stream that ends without a result is never `completed`; a
      `--json` stdout with text and no event is not an answer in another form). An EMPTY stream is "" and not an error
      (E-6: nothing was claimed, as `json.loads("")` is not an error on Claude): the caller names it in a note row.
    - `num_turns`: the count of `item.completed` events (E-21); None when no event was read.
    - `usage`: summed over the `turn.completed` events; `events`: whether any event line was read; `noise`: how many
      non-empty lines were no event (not JSON, or JSON with no `type`/`thread_id`).
    Nothing here raises on a line it cannot read."""
    thread_id, texts, steps, usage, errors, plain, events = "", [], 0, {}, [], [], False
    terminal = ""
    for line in str(raw or "").splitlines():
        line = line.strip()
        if not line:
            continue
        event = None
        if line.startswith("{"):
            try:
                event = json.loads(line)
            except ValueError:
                event = None
        if not isinstance(event, dict) or not (event.get("type") or event.get("thread_id")):
            plain.append(line)
            continue
        events = True
        kind = str(event.get("type") or "")
        thread = event.get("thread") if isinstance(event.get("thread"), dict) else {}
        tid = event.get("thread_id") or thread.get("id")
        if tid and not thread_id:
            thread_id = str(tid)
        if kind == "item.completed":
            steps += 1
            item = event.get("item") if isinstance(event.get("item"), dict) else {}
            if item.get("type") == "agent_message":
                text = item.get("text")
                if text is None:
                    text = item.get("content")
                if isinstance(text, list):
                    text = "".join(str(c.get("text") or "") for c in text if isinstance(c, dict))
                if str(text or "").strip():
                    texts.append(str(text))
        elif kind == "turn.completed":
            terminal = "completed"
            used = event.get("usage")
            if isinstance(used, dict):
                for key, value in used.items():
                    if isinstance(value, (int, float)) and not isinstance(value, bool):
                        usage[key] = usage.get(key, 0) + value
        elif kind in ("turn.failed", "error"):
            detail = event.get("error") if isinstance(event.get("error"), dict) else {}
            message = detail.get("message") or event.get("message") or detail or event.get("error") or json.dumps(event)
            if isinstance(message, (dict, list)):
                message = json.dumps(message, ensure_ascii=False, sort_keys=True)     # an error object with no message: its JSON, not a Python repr
            errors.append(str(message))
            if kind == "turn.failed":
                terminal = "failed"
                failure = str(message)
    partial = texts[-1] if texts else ""
    base = {"num_turns": steps if events else None, "usage": usage, "errors": errors, "events": events,
            "noise": len(plain) if events else 0}
    asked = str(resume or "")
    if asked and thread_id and thread_id != asked:
        return dict(base, session_id=asked, result=("the Codex CLI answered the continuation of thread " + asked
                                                    + " in another thread (" + thread_id + "): the dispatch's own "
                                                    "thread was not continued"),
                    is_error=True, subtype="resume_mismatch", num_turns=0, errors=errors + [thread_id],
                    **({"partial": partial} if partial else {}))
    session = thread_id or asked
    if terminal == "failed":
        return dict(base, session_id=session, result=failure, is_error=True, subtype="turn_failed",
                    **({"partial": partial} if partial else {}))
    if terminal == "completed":
        return dict(base, session_id=session, result=partial, is_error=False, subtype="success")
    if errors:
        return dict(base, session_id=session, result="\n".join(errors), is_error=True, subtype="error_event",
                    **({"partial": partial} if partial else {}))
    if events:
        return dict(base, session_id=session, result=INCOMPLETE_STREAM, is_error=True, subtype="turn_incomplete",
                    **({"partial": partial} if partial else {}))
    if plain:
        # F-4: under `--json` a stdout with text and no event is not an answer in another form, it is a stream that ended
        # with no result: unknown, never `completed`; the text stays as evidence (`partial`, the journal note).
        return dict(base, session_id=session, result=NO_EVENTS_STREAM, is_error=True, subtype="no_events",
                    partial="\n".join(plain), noise=len(plain))
    return dict(base, session_id=session, result="", is_error=False, subtype="", noise=0)


def codex_call_cost(usage: dict, model: str, cost_cfg) -> tuple:
    """(usd or None, text) for one Codex call: its summed `usage` priced by `cost_capture.value_usage`, the ONE pricer.

    The same price list and the same arithmetic the Claude side reads: the project's `cost.rate_overrides`, then the
    bundled `references/model-rates.json` (exact id or alias, OpenAI provider), the long-context tier chosen by the
    sum of the input tokens of the call, as `value_usage` does for one request (a call is read as one request: the
    stream gives a turn's sum, not the size of each request inside it, which `CODEX_COST_LABEL` says). Codex counts
    cached tokens INSIDE `input_tokens` (`codex_usage.scan` splits them the same way): input - cached is billed as
    input, cached as `cache_read`, `output_tokens` includes the reasoning. The text is `CODEX_COST_LABEL` beside a
    number, or `price unknown: <why>` (FR-41: an unknown is never `$0`) with the number None: no tariff for the model,
    a usage that cannot be counted (a bool, a negative, a fractional or unreadable count, a cached count above the
    input, reasoning above the output, any cache write - `codex_usage.scan` refuses the same), or no usage at all."""
    import cost_capture
    from decimal import Decimal
    cfg = cost_cfg if isinstance(cost_cfg, dict) else {}
    usage = usage if isinstance(usage, dict) else {}
    counts = {key: _token_count(usage.get(key, 0)) for key in ("input_tokens", "cached_input_tokens", "output_tokens",
                                                              "reasoning_output_tokens", "cache_write_input_tokens")}
    if (None in counts.values() or counts["cached_input_tokens"] > counts["input_tokens"]
            or counts["reasoning_output_tokens"] > counts["output_tokens"] or counts["cache_write_input_tokens"]):
        return None, f"price unknown: the usage of this call is not countable for {model}"
    if not (counts["input_tokens"] or counts["output_tokens"]):
        return None, f"price unknown: the stream carried no usage for {model}"
    aggregate = {"input": counts["input_tokens"] - counts["cached_input_tokens"],
                 "cache_read": counts["cached_input_tokens"], "output": counts["output_tokens"]}
    valued = cost_capture.value_usage(aggregate, model, cfg, None, "openai", datetime.now(timezone.utc))
    if valued["pricing_coverage"] != "complete":
        if (valued.get("rate_provenance") or {}).get("kind") == "unpriced":
            return None, f"price unknown: no tariff for {model}"
        missing = ", ".join(valued.get("missing_rate_categories") or []) or "a category"
        return None, f"price unknown: no tariff for {model} ({missing})"
    return float(Decimal(valued["subtotal_usd"])), CODEX_COST_LABEL


def codex_running_total(before, call_cost):
    """The thread's running total after a call: `before` (the last usable total of the thread's rows, None when it has none)
    plus the call's price. An unpriced call (`call_cost` None) leaves the total as it was, None when there was none: the
    row's `cost_basis` says the call is not in it. Decimal, so 0.30 + 0.45 is 0.75 and not 0.7500000000000001."""
    from decimal import Decimal
    if call_cost is None:
        return before
    return float(Decimal(repr(before or 0.0)) + Decimal(repr(call_cost)))


def _token_count(value):
    """A token count as an int, or None when it cannot be one: a bool, a negative, a string, an infinity, a fraction. A float
    that is a whole number (`10.0`) is that number; `10.9` is not a count (it was truncated to 10 before)."""
    if isinstance(value, bool):
        return None
    if isinstance(value, float):
        if not value.is_integer():
            return None
        value = int(value)
    return value if isinstance(value, int) and value >= 0 else None


def seam_rank(exc) -> int:
    """The rank of a failed chain's exception at the seam (t-2147 A; was the closure of `s5_seam`): an `InfraStop` first, then a `Stop`,
    then a `Refusal`, then a `Person`. F3: an exception that is none of the domain's (a TypeError, an OSError) is a crash, not a state
    that re-arises from a saved result: it is ranked with `Stop`, ahead of a question."""
    return 0 if isinstance(exc, InfraStop) else 1 if isinstance(exc, Stop) or not isinstance(exc, (Refusal, Person)) \
        else 2 if isinstance(exc, Refusal) else 3


class Driver(DriverChains):
    # TR3-17 (B4 parts 1-2): `boundary` and `last_dispatch` were single slots; they are now per thread AND per driver, under the same
    # names, so the 26 + 57 sites read and write them unchanged. The main thread's value is the one `__init__` and the serial road set.
    # A thread that never set one: `boundary` raises AttributeError (a bug to show, no default); `last_dispatch` reads "" (its only
    # silent default - and `getattr(self, "last_dispatch", "")` keeps answering "").
    boundary = ThreadSlot("boundary", hint="boundary was read on a thread that never set it (a chain starts with `as_chain`)")
    last_dispatch = ThreadSlot("last_dispatch", default="")

    def __init__(self, ns):
        self.task = ns.task
        self.dry = bool(ns.dry_run)
        self.until = ns.until if ns.until in UNTIL_PAST else None
        self.plugin = Path(ns.plugin_dir).resolve() if ns.plugin_dir else HERE.parent
        self.scripts = self.plugin / "scripts"
        self.flags = ns
        self.max_boundaries = int(ns.max_boundaries)
        if ns.project:
            os.environ["CLAUDE_PROJECT_DIR"] = str(Path(ns.project).resolve())
            os.chdir(ns.project)
        import hooklib
        hooklib._PROJECT_ROOT_CACHE = None
        hooklib.require_project("story_run")
        self.project = Path(hooklib.project_root()).resolve()
        os.chdir(self.project)
        os.environ["CLAUDE_PROJECT_DIR"] = str(self.project)
        self.task_root = Path(hooklib.artifacts_dir(self.task))
        self.state_dir = self.task_root / "state"
        self.config = hooklib.load_config() or {}
        if not AF.is_key(self.task, self.config):   # B-405 R14: a warning only (P1) - the run goes on
            print(f"WARN: --task {self.task!r} is not a ticket key of this project: "
                  f"{AF.describe_key_form(self.config)}; going on", flush=True)
        # The host: `--host` first, then `driver.host` of config.json (None/absent is no word; any other value is
        # compared after strip, with its case - an unknown one is refused at the end of this method, by `host_refusal`,
        # naming the hosts there are), else `claude`. `self.claude` is the executable of whichever host runs the roles
        # (the name is kept: every call site reads it). STORY_RUN_CODEX / STORY_RUN_CLAUDE replace it (a `.py` path runs
        # under this interpreter: the tests' stubs).
        driver_cfg = self.config.get("driver")
        driver_notes = []
        if driver_cfg is not None and not isinstance(driver_cfg, dict):
            driver_notes.append("`driver` in config.json is not an object: it is not read")
            driver_cfg = {}
        driver_cfg = driver_cfg or {}
        named_host = getattr(ns, "host", None)
        if named_host:
            self.host = str(named_host).strip()
        elif driver_cfg.get("host") is not None:
            self.host = str(driver_cfg["host"]).strip()
        else:
            self.host = "claude"
        if self.host == "codex":
            raw = os.environ.get("STORY_RUN_CODEX") or shutil.which("codex") or ""
        else:
            raw = os.environ.get("STORY_RUN_CLAUDE") or shutil.which("claude") or ""
        self.claude = [sys.executable, raw] if raw.endswith(".py") else ([raw] if raw else [])
        # The project's say on the Codex call (`driver.codex.sandbox`, `driver.codex.config`), normalised once: a key of
        # the wrong type is ignored with one note (FR-4), the others are passed as given. Read for Codex only.
        self.codex_cfg = {}
        if self.host == "codex":
            codex = driver_cfg.get("codex")
            if codex is not None and not isinstance(codex, dict):
                driver_notes.append("`driver.codex` in config.json is not an object: it is not read")
                codex = {}
            codex = codex or {}
            sandbox = codex.get("sandbox")
            self.codex_cfg["sandbox"] = "" if sandbox is None else str(sandbox).strip()
            overrides = codex.get("config")
            if overrides is not None and not isinstance(overrides, dict):
                driver_notes.append("`driver.codex.config` in config.json is not an object: it is not read")
                overrides = {}
            # `-c key=value` takes a TOML value. A string goes as given, a number / boolean / list as JSON (the same text in
            # TOML); an object has no one-line TOML form and `null` has none at all, so passing them would change the
            # project's word silently (E-17): such a key is left out, and the line says which and why (FR-4).
            kept = {}
            for key, value in (overrides or {}).items():
                if value is None or isinstance(value, dict):
                    driver_notes.append(f"`driver.codex.config.{key}` in config.json is "
                                        f"{'null' if value is None else 'an object'}, which `codex -c` cannot take as one value: "
                                        "it is not passed")
                else:
                    kept[key] = value
            self.codex_cfg["config"] = kept
            if not self.codex_cfg["sandbox"]:
                driver_notes.append("`driver.codex.sandbox` is not set: no `-s` is passed, the project's own "
                                    ".codex/config.toml decides the sandbox")
        # Every child speaks UTF-8: a script that prints a dash or a person's words under the machine's
        # code page (cp1252 on Windows) hands the driver bytes it then decodes as UTF-8 with
        # errors="replace" - the text arrives as replacement characters (B-012, K13). In code, not in
        # a data file: it is not variety, it is how this driver reads every pipe.
        # B-014: `CLAUDE_PLUGIN_ROOT` is this driver's own copy for every child. Hooks get their root
        # from the host, but the Bash tool of a role INHERITS this variable (step 0, R6b: a parent's
        # `C:\fake` reached the role's Bash), so a command in an agent body that says
        # `${CLAUDE_PLUGIN_ROOT}/scripts/...` resolves to the copy the driver runs, never to the
        # copy some other session or the host left in the environment. `QA_FACTORY_RUN_MODE` is the
        # mode `story_step start` stamps into the story (one story, one mode).
        self.env = dict(os.environ, CLAUDE_PROJECT_DIR=str(self.project),
                        CLAUDE_CODE_PRINT_BG_WAIT_CEILING_MS="0", PYTHONDONTWRITEBYTECODE="1",
                        PYTHONUTF8="1", PYTHONIOENCODING="utf-8",
                        CLAUDE_PLUGIN_ROOT=str(self.plugin), QA_FACTORY_RUN_MODE="driver")
        # Factory scripts (`py`) get that environment as it is: one may use a gateway on purpose. Only
        # a `claude -p` child loses what a desktop-app host put in the driver's environment - its
        # proxy address without the per-process token, which made every role answer "Not logged in"
        # on TP1-13877 while a valid login sat in the credentials file. What goes is a data file's
        # list (references/driver-infra.json); `driver.child_env.keep` in config.json is the door back.
        import infra_failure
        self.infra_rules, infra_notes = infra_failure.rules()
        self.claude_env, self.env_removed, env_notes = infra_failure.child_env(
            self.env, self.infra_rules, driver_cfg)
        # The model: Claude - `--model` or `sonnet`; Codex - `--model`, else `default_model.codex` of the data file
        # (the owner's word 20.10.2026: the latest Terra, in data, not in code). The journal rows and the dry run name
        # THIS model, the one the child is given.
        named_model = getattr(ns, "model", None)
        self.model_explicit = named_model not in (None, "")
        default_models = self.infra_rules.get("default_model")
        data_model = default_models.get(self.host) if isinstance(default_models, dict) else None
        data_model = data_model.strip() if isinstance(data_model, str) else ""
        self.model = str(named_model) if self.model_explicit else (data_model if self.host == "codex" else "sonnet")
        for note in infra_notes + env_notes + driver_notes:
            print(f"note: {note}", flush=True)
        self.sleep = time.sleep          # tests replace it: a retry's wait is a decision, not a duration to sit through
        self.boundary = "start"
        self.conductor_calls: dict = {}
        self._in_no_move = False         # the re-entry guard of `no_move`: the seam never recurses
        self.gate_b_ran = set()          # the gate B executors this process started (GB-1b): none is started twice by one process
        self.gate_b_idle = 0             # the passes of `_act_execute_gate_b` in a row that moved no order (the seam is the second)
        self._price_notes = None         # a list while the seam renders a site's own question: price reasons join ONE defect (G8)
        self._answer = None              # the --answer being taken: {"text": raw, "rel": <words file, once written>}
        self.state = _read_json(self.state_dir / "driver-state.json")
        self.state.setdefault("sessions", {})
        self.state.setdefault("pending_words", {})
        self.state.setdefault("asked", {})
        self.state.setdefault("interrupted", {})   # key (a dispatch, or `S8:delivery`) -> the call an infrastructure failure cut off
        self.answer_kind = ""
        self.question_lines_shown = ""   # GW1-34 F4: the lines of that note, as the person reads them
        self.question_lines_note = ""    # GW1-34: the conductor's note on gate A lines about register questions no reader understood
        self.gate_refusal = ""           # the controller's own words when a gate decision did not record (t-214 C3)
        self.package_verdict = False     # B-014: this process has seen one session's hooks match its own root
        self.doors_tried: set = set()    # C2-4: the (dispatch, finding key) pairs the code doors already ran for in this process
        self.in_code_step = False        # C2-4 (t-909 F-2): True while a code step's own retry / nested refusal runs - it is not entered again
        refusal = self.host_refusal()
        if refusal:
            raise Stop(refusal[0], refusal[1])

    def host_refusal(self):
        """`(exit code, text)` when the host of this run cannot start, else None. ONE place decides every start refusal
        of the host (CX1-15), and `__init__` raises the one `Stop` for it. Each text says what is wrong, what was
        expected and the door (FR-1, FR-2); none of them names a path the person cannot use.

        1. `--host` / `driver.host` is not one of `HOSTS` (exit 1; the value as given, the hosts there are).
        2. The Codex host with no `--model` and no `default_model.codex` in `references/driver-infra.json` (an older data
           file): exit 2, never a silent host default - the model of a run is always one the factory can name.
        3. F-5: the story's state holds a session of ANOTHER host (exit 1): an id of one host is never offered to
           `resume` of the other. The door: the host the story started on, or a new story. A state with sessions and
           no `host` key is a Claude story (the key is written for Codex only)."""
        if self.host not in HOSTS:
            return EXIT_ERROR, (f"--host / driver.host {self.host!r} is not one of {', '.join(HOSTS)}. Name one of them "
                                "(`--host claude` or `--host codex`), or remove `driver.host` from qa-factory/config.json.")
        if self.host == "codex" and not self.model:
            models = self.infra_rules.get("default_model")
            named = models.get("codex") if isinstance(models, dict) else None
            problem = "is missing from" if named is None else "is not a model name in"
            return 2, ("The Codex host has no model: `--model` was not given and `default_model.codex` " + problem +
                       " references/driver-infra.json of the package this driver runs, so it would run a model the factory "
                       "cannot name. Pass `--model <name>`, or restore `default_model.codex` in that file.")
        held = bool(self.state.get("sessions")) or any(
            isinstance(r, dict) and r.get("session_id") for r in (self.state.get("interrupted") or {}).values())
        previous = str(self.state.get("host") or "") or ("claude" if held else "")
        if held and previous != self.host:
            # Both hosts are named: the one of the stored sessions (the story's own `host` key, kept by `mark_host` as the
            # sessions change) and the one this run is, from the flag / config - never a word taken from the other.
            return EXIT_ERROR, (f"This story already holds sessions of the {previous} host, and this run is {self.host}: a "
                                f"session id of one host cannot be resumed on the other. Run the story with `--host {previous}` "
                                "to go on, or start a new story for the other host.")
        return None

    # --- plumbing --------------------------------------------------------------------------
    def save_state(self) -> None:
        if not self.dry:
            # TR3-6: published through `_write_json` (`event_store.atomic_json`), so a reader (`story_step`, the dashboard, the watchdog's
            # `dispatch_liveness`) during a released `start` never sees a torn file and never makes the write fail; the caller holds
            # `_book` on the parallel road (one writer at a time)
            _write_json(self.state_dir / "driver-state.json", self.state)

    def waiver_road(self, classed: bool = True) -> tuple:
        """The flags every driver-road `waiver.py` recording call carries (RN1-9 B-1, AR-22): `--by driver` marks the road (so
        `person_owned.share` counts the word on the DRIVER counter, never the interactive one) and `--why-person <id>` carries the
        class of the question the word answers (`asked["why_person"]`, set by `ask()`); no class asked, no flag. `classed=False`:
        the driver's own take-back (a revoke is not an answer to a question) carries the road mark alone."""
        cid = PO.as_class((self.state.get("asked") or {}).get("why_person")) if classed else ""
        return ("--by", "driver") + (("--why-person", cid) if cid else ())

    def py(self, script: str, *args, check: bool = False, expect: str = "") -> tuple:
        """Run one factory script from the project root. (exit code, stdout+stderr).

        `check=True`: a non-zero exit raises `Refusal`, and a TIMEOUT (124, `PY_TIMEOUTS`) is a non-zero exit like any other (C1-7a
        B-4 iii: it was returned before the check and never raised). `expect` (C1-7a, F10): what this step must leave behind, in words
        for the lead. With it the refusal is FR-1 shaped (what failed, what was expected, the door), carries the mark `known = False`
        (see the end of this docstring), and its `retry` carries `expect`
        too (B-4 i: a failing retry is the same kind of refusal, not a plain one). Without `expect` the text is today's, byte for byte.
        `known = False` is the MARK that `route_known` reads (C1-7b) to keep the known-refusals table from routing such a step; the G
        steps of the stage functions (S0, S4, S6, S8, S9) pass `expect`, and a step without one keeps the plain refusal."""
        path = self.scripts / script
        try:
            done = subprocess.run([sys.executable, "-B", str(path), *[str(a) for a in args]],
                                  capture_output=True, text=True, encoding="utf-8", errors="replace",
                                  cwd=str(self.project), env=self.env, timeout=self.PY_TIMEOUTS.get(script))
            code, out = done.returncode, (done.stdout + ("\n" + done.stderr if done.stderr.strip() else "")).strip()
        except subprocess.TimeoutExpired:
            # F4: a script with a ceiling (`PY_TIMEOUTS`) that does not finish is a script that said nothing: 124, as `timeout(1)`
            code, out = 124, f"{script} did not finish within {self.PY_TIMEOUTS.get(script)} seconds"
        if check and code:
            retry = lambda: self.py(script, *args, check=True, expect=expect)      # noqa: E731
            if not expect:
                raise Refusal(f"{script} {' '.join(str(a) for a in args[:6])} (exit {code}):\n{out}", retry=retry)
            raise gate_refusal(script, code, out, expect, retry)
        return code, out

    # --- rows the journal refused (C1-7a, P22): owed, written again first, then the seam ----------------------------------------
    def owed_list(self) -> list:
        """`state["owed_rows"]` as a list. Absent (a story recorded before C1-7a) reads as no rows owed. A value that is not a list is
        set aside with ONE `trace_failed` line and reads as none: a malformed record never blocks the loop and is never dropped
        unsaid (E12)."""
        rows = self.state.get("owed_rows")
        if rows is None:
            return []
        if not isinstance(rows, list):
            self.journal_run({"kind": "trace_failed", "script": "owed_rows", "exit": 0,
                              "why": f"driver-state owed_rows was a {type(rows).__name__}, not a list; read as no rows"})
            self.state["owed_rows"] = []
            return []
        return rows

    def owed_stage(self) -> str:
        """The stage id an owed row is recorded under (`waiver.py --stage` takes S0..S9 only): the boundary's, else the open question's,
        else the ONE stage running, else S0. Never read from a person's words."""
        for stage in (self.boundary.split(":")[0], str((self.state.get("asked") or {}).get("stage") or "")):
            if re.fullmatch(r"S\d", stage):
                return stage
        running = [s for s, held in (self.pipeline().get("stages") or {}).items()
                   if re.fullmatch(r"S\d", str(s)) and isinstance(held, dict) and held.get("status") == "running"]
        return running[0] if len(running) == 1 else "S0"

    def owe_row(self, script: str, *args, what: str, stage: str = "") -> None:
        """THE write of a journal row the story's later roles read (the person's words, an FR-4 finding, a `--warn` line): the script
        runs once; a non-zero exit makes the row OWED (`state["owed_rows"]`, saved), says so in ONE line, and the flow goes on, because
        the executor at hand already holds the words. `owed_rows_step` writes it again before any brief is built; a second failure is
        the seam's question. ERROR DIRECTION: a duplicate row is allowed (a write that landed and still exited non-zero is run again),
        a lost row is not. `what`: the row in words for the lead, written by the caller (never a person's words). Returns None, so the
        census of the audit reads the exit here and sees the callers' result as handled (A27 py-wrapper rule)."""
        code, out = self.py(script, *args)
        if code and recorded_earlier(script, code):
            print(f"journal: {what} was recorded earlier; nothing more to write")
        elif code:
            rows, at = self.owed_list(), _now()
            ident = "row-" + hashlib.sha256(f"{at}|{script}|{args}|{len(rows)}".encode("utf-8")).hexdigest()[:8]
            rows.append({"id": ident, "script": script, "args": [str(a) for a in args], "what": what, "stage": stage or self.owed_stage(),
                         "at": at, "tries": 1, "exit": code, "tail": out[-300:]})
            self.state["owed_rows"] = rows
            self.save_state()
            print(f"journal: {what} is not in the story's journal yet ({script} exit {code}); it is written again before the next step")

    def answer_row(self, prefix: str, words: str, *, what: str, extra=()) -> None:
        """The `human_answer` row of a person's words, owed when the journal refuses it (FR-8: every later brief reads these rows).
        `extra`: arguments between `--task` and `--notes` (the one caller that names its `--by`)."""
        self.owe_row("log_append.py", "--event", "human_answer", "--task", self.task, *extra, "--notes", _answer_note(prefix, words),
                     what=what)

    def py_trace(self, script: str, *args, why: str) -> None:
        """A script nothing decides on (kind T, a `# remains:` door with its reason in the call): `why` is the invariant that makes its failure safe, and it is MANDATORY (an
        empty one is a programming error). A failure is printed in one line and journalled in driver-runs.jsonl as `trace_failed`;
        it never raises and never stops the story."""
        if not isinstance(why, str) or not why.strip():
            raise ValueError("py_trace needs a non-empty `why`: the invariant that makes this failure safe to leave")
        code, _out = self.py(script, *args)
        if code:
            print(f"note: {script} exit {code}; the story goes on ({why})")
            self.journal_run({"kind": "trace_failed", "script": script, "exit": code, "why": why})

    def mark_rows_word(self, asked: dict, stage: str) -> None:
        """The person's `go on` reached the rows of ITS question (B-1): once `pass_block` recorded the pass (the waiver is the durable
        record), each owed row whose id the question carried (`asked["rows"]`) is marked with the stage the word was recorded under
        (`row["word"]`), and the state is saved. The pairing is by IDENTITY, never by clock: a word recorded in the same second as a
        newer question (or before it) marks nothing of that question's rows, because their ids are not in the answered one."""
        ids = {str(i) for i in asked.get("rows") or []}
        for row in self.owed_list():
            if isinstance(row, dict) and str(row.get("id")) in ids:
                row["word"] = stage
        self.save_state()

    def rows_word(self, row: dict) -> bool:
        """Whether the person's `go on` stands for THIS owed row: the row was marked when its own question was answered
        (`mark_rows_word`) and the override of `JOURNAL_ROWS_BLOCK` recorded for that stage is still unrevoked and has words. The
        override is read through `waiver.split_overridden`, the ONE reader of `stage_overrides[]` (AR-13). THE reader of this block
        name (references/block-names.json). The word is the STORY's, like every waiver, and reaches only the rows it was given for."""
        stage = str(row.get("word") or "")
        if not stage:
            return False
        _blocking, passed = waiver.split_overridden([JOURNAL_ROWS_BLOCK], self.pipeline(), stage)
        return bool(passed)

    def owed_rows_step(self) -> None:
        """Write the owed rows again, BEFORE any brief is built (S2, E8): `run()` calls it after the answer is taken and first in every
        loop turn. Nothing owed: nothing happens (no line, no question). Each row runs once; one that writes leaves the list. A row that
        fails `OWED_ROW_TRIES` times in all is the seam's question (`no_move` called here, with the block `JOURNAL_ROWS_BLOCK`, the
        priced fallback and no paid call; its text is row ids and counts, never the person's words - FR-12). The person's `go on`
        (`rows_word`: the rows its own question named, marked by `mark_rows_word` - paired by row id, never by clock) gives those rows
        up (`state["rows_given_up"]`, FR-40) with ONE `rows_given_up` line in driver-runs.jsonl, and from then on a row of the same
        script that fails is given up with no question (D-0043; the word is the story's, kept in `pipeline.json`). POSITION: no step that can dispatch or resume a role runs while a row is owed (S2)."""
        rows = self.owed_list()
        if not rows:
            return
        given = self.state.get("rows_given_up")
        given = self.state["rows_given_up"] = given if isinstance(given, list) else []
        classes = {str(r.get("script")) for r in given if isinstance(r, dict)}
        classes |= {str(r.get("script")) for r in rows if isinstance(r, dict) and self.rows_word(r)}
        kept, failed, dropped = [], [], []
        for row in rows:
            if not (isinstance(row, dict) and row.get("script") and isinstance(row.get("args"), list)):
                self.journal_run({"kind": "trace_failed", "script": "owed_rows", "exit": 0, "why": "an owed row that cannot be read was set aside"})
                continue
            code, out = self.py(str(row["script"]), *row["args"])
            if not code or recorded_earlier(str(row["script"]), code):
                continue
            tries = row["tries"] if isinstance(row.get("tries"), int) else 1
            row = dict(row, tries=tries + 1, exit=code, tail=out[-300:])
            if row["script"] in classes:
                dropped.append(dict(row, given_up=_now()))
            else:
                (failed if row["tries"] >= OWED_ROW_TRIES else kept).append(row)
        if dropped:
            given += dropped
            self.journal_run({"kind": "rows_given_up", "rows": [r["id"] for r in dropped], "scripts": sorted({r["script"] for r in dropped}),
                              "count": len(dropped)})
            print(f"journal: {len(dropped)} row(s) given up on the person's word; they are not in the story's journal")
        self.state["owed_rows"] = kept + failed
        self.save_state()
        if not failed:
            return
        have_pipeline = (self.task_root / "pipeline.json").is_file()
        ids = ", ".join(str(r.get("id")) for r in failed)
        self.boundary = "owed_rows"
        self.no_move({"why": "refusal", "kind": "refusal", "call": False, "stage": str(failed[0].get("stage") or "S0"), "dispatch": "",
                      "block": JOURNAL_ROWS_BLOCK if have_pipeline else "", "fallback": ["retry", "go on", "stop"] if have_pipeline else ["retry", "stop"],
                      "rows": [str(r.get("id")) for r in failed],       # B-1: the ids this question is about; its `go on` marks exactly these
                      "lead": (f"{len(failed)} record(s) of this story could not be written to its journal, even on a second try. The roles that "
                               "run next read that journal, so they would work without " + ("it" if len(failed) == 1 else "them") + ": "
                               + "; ".join(str(r.get("what")) for r in failed) + ". The fault is the factory's own, not yours. Nothing about it "
                               "is filed yet: the records wait and are written again at the next step; if you go on without them, one line in "
                               "the story's run log says so."),
                      "lines": [str(r.get("what")) for r in failed],
                      "text": f"The journal refused {len(failed)} row(s) twice: {ids}. The rows stay owed in the story's state and are written "
                              "again at the next step."})

    def words_file(self, words: str, name: str):
        """Put a person's words in a file, exactly as the driver holds them; the path, or None.

        Every command that records a person's words takes them from a file (`--words-file`, M30):
        on TP2-2406 a three-paragraph answer was recorded as its first paragraph because
        cmd.exe cuts a command line at the first line break. The driver's own argv is not cut (a
        list argv, no cmd), but the Windows command line holds 32767 characters and the conductor,
        a role with only Bash, Read and Grep, cannot make a file of an answer it was handed - so the
        driver makes it, once, here (FR-17: every site that hands words over comes through this).

        `<task root>/state/words/driver-<name>-<millisecond stamp>[-<n>].txt`: UTF-8, no BOM, line
        breaks as given (newline=""), created with "x" so a name that exists is never overwritten.
        `name` is a gate or stage word (`gateA`, `s1review`), never one the secrets guard refuses.
        The file is the audit trail of what was handed over and is never deleted. An empty or
        whitespace-only answer writes nothing and returns None. A write that fails (no folder, a full
        disk) stops the driver with its own error: the words are NOT passed on the command line
        instead - that is the road that cuts them."""
        if not str(words or "").strip():
            return None
        folder = self.state_dir / "words"
        stem = "driver-" + re.sub(r"[^A-Za-z0-9]+", "", str(name or "")) + "-" + str(int(time.time() * 1000))
        path, made = folder / (stem + ".txt"), None
        try:
            folder.mkdir(parents=True, exist_ok=True)
            for number in range(1, 1000):
                try:
                    with open(path, "x", encoding="utf-8", newline="") as stream:
                        made = path
                        stream.write(words)
                except FileExistsError:
                    path = folder / f"{stem}-{number}.txt"
                    continue
                return path
            raise OSError("no unused file name")
        except OSError as exc:
            if made is not None:
                try:
                    made.unlink()                   # half a text must not stand as the person's words
                except OSError:
                    pass
            raise Stop(EXIT_ERROR,
                       f"the driver could not save the person's words to {path} ({exc.strerror or exc}). "
                       "Nothing was recorded: the words are not put on a command line instead, because a "
                       "long or multi-line text would be cut there. Make the folder "
                       f"{folder} writable (or free some disk space), then run the same command again "
                       "with the same --answer file.") from None

    def words_args(self, words: str, name: str) -> list:
        """The arguments that hand a person's words to a command: `--words-file <path>`.

        An empty answer has no file and is passed as it always was, inline and empty, so the
        command gives its own refusal for it and no new stop is invented here."""
        path = self.words_file(words, name)
        return ["--words", words] if path is None else ["--words-file", str(path)]

    def json_file(self, data: dict, name: str):
        """A JSON object in a file under `state/words/` (the driver's one folder for what it hands a command by file), the path."""
        return self.words_file(json.dumps(data, ensure_ascii=False, sort_keys=True), name)

    def gate_answer_told(self, gate: str, out: str) -> dict:
        """The controller's answer (or refusal) of a gate decision, read and TOLD (DC1-19; AR-22, AR-24: what the register, the plan or the
        journal did, or did not do, is printed on this road): the plan lines (`questions.lines`, the manual-agent pass), what was not read
        (`unread`), an id named with no answer recorded (`named_not_recorded`), a recorded answer the plan still branches on
        (`plan_not_changed`), the case tokens a refusal did not apply (`not_applied_yet`), the journal line that was not written
        (`risks.line`). A rework the answers owe (`questions.rework`) goes to `merge_answer_rework` - EXCEPT after a RECORDED `approve as
        is` (`questions.rework_left`, F-4): the person's word wins, S3/S4 are not opened on the plan the approval just hashed, the queued
        item of an earlier refusal is dropped, and the controller's sentence (the door of a later rework) is printed; the rework runs only
        by the person's word. The answer is the last line that is a JSON object; one that is none is printed (200 characters) and the
        decision stands (P1)."""
        answer = _read_answer(out) or {}
        if not answer:
            if str(out or "").strip():
                print(f"gate {gate}: the controller's answer could not be read as JSON: {str(out).strip()[:200]}")
            return {}
        questions = answer.get("questions") if isinstance(answer.get("questions"), dict) else {}
        for line in [*(answer.get("manual_pass") or []), *(questions.get("lines") or [])]:
            print(str(line) if str(line).startswith(f"gate {gate}") else f"gate {gate}: {line}")
        for item in questions.get("unread") or []:
            if isinstance(item, dict):
                print(f"gate {gate}: not recorded - {item.get('line')}: {item.get('why')}")
        for item in questions.get("named_not_recorded") or []:
            if isinstance(item, dict):
                print(f"gate {gate}: {item.get('id')} is named in your words but no answer was recorded for it - {item.get('line')}")
        for item in questions.get("plan_not_changed") or []:
            if isinstance(item, dict):
                print(f"gate {gate}: {item.get('id')} is recorded, but the plan still branches on it in {', '.join(map(str, item.get('rows') or []))}"
                      ": the plan was not changed")
        if questions.get("not_applied_yet"):
            print(f"gate {gate}: not applied (the decision did not record): " + ", ".join(map(str, questions["not_applied_yet"])))
        risks = answer.get("risks") if isinstance(answer.get("risks"), dict) else {}
        if risks.get("line"):
            print(f"gate {gate}: {risks['line']}")
        rework = [r for r in questions.get("rework") or [] if isinstance(r, dict)]
        if questions.get("rework_left"):
            print(f"gate {gate}: {questions['rework_left']}")
            self.drop_record("answer_rework")
        elif rework:
            try:
                self.merge_answer_rework(rework)
            except Exception as exc:
                print(f"note: the rework your answers owe could not be queued ({type(exc).__name__}: {' '.join(str(exc).split())[:160]})")
        return answer

    def step(self, *args) -> str:
        code, out = self.py("story_step.py", *args)
        if code:
            raise Refusal(f"story_step {args[0]} (exit {code}):\n{out}", retry=lambda: self.step(*args))
        return out

    def controller(self, operation: str, *args, input_data=None) -> dict:
        argv = ["--task-root", str(self.task_root), "--operation", operation, *args]
        if input_data is not None:
            path = self.state_dir / "driver-tmp" / f"{operation}-{int(time.time() * 1000)}.json"
            _write_json(path, input_data)
            argv += ["--input", str(path)]
        code, out = self.py("controller.py", *argv)
        if code:
            raise Refusal(f"controller {operation} (exit {code}):\n{out}")
        answer = _read_answer(out)
        if answer is None:
            # t-2020 (AR-28, FR-41): an answer nobody could read is an unknown, never an empty answer a caller would take for "nothing".
            raise Refusal(f"controller {operation}: no line of its output is a JSON object (expected the controller's one-line answer; "
                          f"the text that came back, first 300 characters): {' '.join(str(out).split())[:300] or 'nothing'}")
        return answer

    def where(self) -> dict:
        out = self.step("where", "--task", self.task)
        self.last_where = out
        return parse_next(out)

    def pipeline(self) -> dict:
        return _read_json(self.task_root / "pipeline.json")

    def controller_state(self) -> dict:
        return _read_json(self.state_dir / "controller.json")

    def stages(self) -> dict:
        import hooklib
        return {s["id"]: s for s in hooklib.load_ref_json("stages.json")["stages"]}

    def journal_run(self, record: dict) -> None:
        row = dict(ts=_now(), **record)
        _append_jsonl(self.state_dir / "driver-runs.jsonl", row)
        # TR4-11: the calls THIS process launched and has seen no end row for - `person_stop_record` names them (`cut`). The ends are
        # matched the way `collect_stall._k3_k4` matches them (an outcome row of the same key); a row that was not written is not kept.
        open_calls = once_on(self, "_open_calls", set)
        if row.get("kind") == "launched":
            started = row.get("started_at") if row.get("started_at") is not None else row["ts"]
            open_calls.add((str(row.get("dispatch_id") or row.get("call") or ""), str(started)))
        elif any(k in row for k in ("is_error", "exit_code", "infra")):
            ended = str(row.get("dispatch") or row.get("kind") or "")
            for entry in [e for e in list(open_calls) if e[0] == ended]:
                open_calls.discard(entry)

    def journal_conductor(self, **record) -> None:
        _append_jsonl(self.state_dir / "conductor.jsonl", dict(ts=_now(), boundary=self.boundary, **record))

    def progress_line(self) -> None:
        """`[progress] <where the story stands>`, once per transition (t-310): at the start, before a role is
        launched, after it returns, when a question is posted (a gate is one), when a stage closes by code,
        and at the end. The line is `story_progress.progress` over the records - never this process's memory -
        and it is a courtesy: whatever goes wrong in it is said in the line and never stops the run (P1).
        Flushed per line (FR-43): the log is read while the story runs."""
        try:
            import story_progress
            line = story_progress.progress(self.task_root, fresh_ok=True)["line"]
        except Exception as exc:
            line = f"not available ({type(exc).__name__}: {' '.join(str(exc).split())[:120]})"
        view = getattr(self, "_s5_view", None)
        if view is not None:      # TR3-6: only while the scheduler runs; no key in the state, nothing on the serial road
            running = sorted(r.n for r in self._chains.values() if not r.done)
            line += (f" · windows running: {','.join(str(n) for n in running) or 'none'} of {view['total']}"
                     + (f" · closed {','.join(str(n) for n in sorted(view['closed']))}" if view["closed"] else ""))
        print(f"[progress] {line}", flush=True)

    def stand_remedy(self) -> str:
        """The standing authorization the conductor needs before it touches a stand: the
        selected environment's `bring_up` text says AUTHORIZED, or config.driver says so."""
        driver = self.config.get("driver") or {}
        if driver.get("stand_remedy_authorized") is True:
            return "authorized (config.driver.stand_remedy_authorized)"
        name = self.pipeline().get("environment")
        for env in self.config.get("environments") or []:
            if env.get("name") == name and "AUTHORIZED" in str(env.get("bring_up") or ""):
                return f"authorized for stand `{name}` (config.environments.bring_up carries AUTHORIZED)"
        return "NOT authorized: no standing authorization in config.json — a stand remedy is a question for the person"

    # --- one package generation per run (B-014) ----------------------------------------------
    @staticmethod
    def _root_key(path) -> str:
        """A plugin root as it is compared: resolved, and case-folded where the file system is."""
        try:
            return os.path.normcase(str(Path(str(path)).resolve()))
        except (OSError, ValueError):
            return os.path.normcase(str(path))

    @staticmethod
    def _copy_version(root) -> str:
        try:
            import telemetry_hook
            return telemetry_hook._plugin_version(Path(str(root)))
        except Exception:
            return ""

    def package_check(self, session_id: str, *, stage: str = "", dispatch: str = "") -> None:
        """Did the hooks of this session come from the copy of the package this driver runs?

        The driver loads its own copy (`--plugin-dir`), the project may enable another one, and
        nothing recorded which generation's guards ran under a role: a role could be judged by the
        checks of one version and told its rules by another. `telemetry_hook.py` leaves a receipt
        per session with the plugin roots its hooks ran from (SessionStart fires in `claude -p`,
        measured in step 0), so a session's answer is accepted only when that receipt names this
        driver's root and nothing else. A MISSING receipt is a mismatch too: the checks did not
        report, and a session nobody guarded is not one to accept. Until this process has one
        matching session it asks of every session; after that it stops (one generation per run).

        POSITION INVARIANT: called by `run_claude` right after the journal line and BEFORE its
        caller sees the result - a mixed session's result is never bound, handed over or finished.
        The saved result of the dispatch, if one is there, is set aside as `.mixed.json`, so a rerun
        never reuses it. The person's word passes a root pair (FR-4, `take_answer`), and the same
        pair then passes without a question."""
        if self.package_verdict or not session_id:
            return
        ours = self._root_key(self.plugin)
        path = (self.project / "qa-factory" / "state" / "host-receipts"
                / f"package-{hashlib.sha256(session_id.encode('utf-8')).hexdigest()[:16]}.json")
        receipt = _read_json(path)
        seen: dict = {}
        for row in ((receipt.get("roots") if isinstance(receipt, dict) else None) or []):
            if isinstance(row, dict) and row.get("plugin_root"):
                seen.setdefault(self._root_key(row["plugin_root"]),
                                (str(row["plugin_root"]), str(row.get("version") or "")))
        # A copy from before this receipt existed (0.7.9 on) leaves its root in the host-capability
        # receipts, one file per (session, script, hook), each naming `plugin_root`: any root of this
        # session found there counts too. PARTIAL by nature - both copies write the same receipt key,
        # so the last writer wins and a root can be overwritten by the other copy's - but it sees the
        # generations that never wrote a package receipt at all.
        for other in hooklib.sorted_paths(path.parent.glob("*.json")):
            if other == path:
                continue
            row = _read_json(other)
            if isinstance(row, dict) and row.get("session_id") == session_id and row.get("plugin_root"):
                seen.setdefault(self._root_key(row["plugin_root"]),
                                (str(row["plugin_root"]), self._copy_version(row["plugin_root"])))
        hooks = sorted(seen)
        version = self._copy_version(self.plugin)
        if hooks == [ours]:
            self.package_verdict = True
            self.state["package_check"] = {"ok": True, "root": str(self.plugin), "version": version,
                                           "session": session_id}
            self.save_state()
            return
        passed = self.state.get("package_pass")
        if (isinstance(passed, dict) and passed.get("driver_root") == ours
                and sorted(passed.get("hook_roots") or []) == hooks):
            self.package_verdict = True
            self.state["package_check"] = {"ok": True, "root": str(self.plugin), "version": version,
                                           "session": session_id, "passed_by_person": True}
            self.save_state()
            print(f"package: the hooks of this session came from a different copy than the driver's; "
                  f"passed on the person's word of {passed.get('ts') or 'earlier'} (recorded)", flush=True)
            return
        saved = self.state_dir / "driver-runs" / f"{dispatch}.json" if dispatch else None
        if saved is not None and saved.is_file():
            saved.replace(saved.with_name(saved.stem + ".mixed.json"))
        mine =f"version {version} of the factory" if version else "its own copy of the factory"
        versions = sorted({v for _, v in seen.values() if v})
        if not hooks:
            what = (f"The driver runs {mine}, but the checks that guard each step did not report from "
                    "this session at all, so I cannot tell which copy they came from.")
        elif len(hooks) > 1:
            what = (f"The driver runs {mine}, but the checks that guard each step of this session came "
                    "from more than one copy of the factory" + (f" (versions {', '.join(versions)})." if versions else "."))
        elif versions and versions[0] != version:
            what = (f"The driver runs {mine}, but the checks that guard each step of this session came "
                    f"from another copy, version {versions[0]}.")
        elif versions:
            what = (f"The driver runs {mine}, but the checks that guard each step of this session came "
                    "from another copy of the same version.")
        else:
            what = (f"The driver runs {mine}, but the checks that guard each step of this session came "
                    "from another copy.")
        text = self.closed_question(
            "package.copies",
            what + "\n\nWork done under the checks of another copy is not accepted, so nothing of this "
            "session was accepted (what the role wrote stays) and that step runs again.\n\n"
            "What I need is a decision. Answer with exactly one of these words:",
            [{"answer": "retry", "token": "retry", "says": "you first make sure only one copy of the factory is active for this "
                                                          "project, and I look again",
              "slots": {"what": "make sure only one copy of the factory is active for this project"}},
             {"answer": "go on", "token": "go on", "says": "go on as it is; I record your words as the reason the story "
                                                           "carries, and file the mismatch as a defect of ours"},
             self.STOP_OPTION])
        listed = "; ".join(f"{seen[key][0]} (version {seen[key][1] or 'unknown'})" for key in hooks) or "nothing"
        details = (f"driver package: {self.plugin} (version {version or 'unknown'})\n"
                   f"hook roots reported by session {session_id}: {listed}\n"
                   f"receipt: {path}\n"
                   "To make one copy active: disable or uninstall the other one "
                   "(claude plugin disable qa-factory@<marketplace> --scope project), or start the driver "
                   "with --plugin-dir pointing at the copy the project enables.")
        self.state["package_question"] = {"what": "hooks", "driver_root": ours, "hook_roots": hooks,
                                          "session": session_id, "text": text, "details": details}
        raise Person("package", text, stage, dispatch, details=details)

    def report_gap_class_problem(self) -> None:
        """C2-9 (L-2 V-5 b): after S1 is closed, a record of the person's answers about KINDS of gap that cannot be read does not
        stop the story (G3: what was closed stays closed), and it is not silent either (FR-41): ONE finding of the factory
        (`defect_found`), once per problem text (`state.gap_class_defect`). Read from the controller's own projection, the place
        that first holds it; before S1 is closed the question itself carries the line and no finding is owed."""
        state = self.controller_state()
        closed = ((state.get("stages") or {}).get("S1") or {}).get("status") == "completed"
        problem = str((state.get("source_completeness") or {}).get("gap_class_problem") or "")
        if not closed or not problem or self.state.get("gap_class_defect") == problem:
            return
        self.state["gap_class_defect"] = problem
        self.save_state()
        self.file_defect(self.boundary, f"owner: factory — {problem}. S1 is closed, so every gap point a kind of gap closed stays "
                                        "closed (nothing is asked again), but the record is damaged: restore "
                                        "work/gap-classes.json (or references/source-causes.json) and say so in the report")

    def check_run_mode(self) -> None:
        """B-014, F14-3: a story is run by one mode. `story_step start` stamps `pipeline.run_mode`
        and refuses a switch; the driver asks the same question at the start of a run, as a person's
        question, instead of meeting that refusal at the first stage it dispatches. The stage judged
        is the first one not done (what a run would start next); a story with none left has nothing
        to start and nothing to refuse. A story with no stamp adopts this mode silently."""
        pipeline = self.pipeline()
        stages = pipeline.get("stages") or {}
        stage = next((s for s in (f"S{i}" for i in range(10))
                      if (stages.get(s) if isinstance(stages.get(s), dict) else {}).get("status") != "done"), "")
        if not pipeline or not stage:
            return
        import story_step
        switch = story_step.run_mode_switch(pipeline, stage, "driver")
        if not switch:
            return
        stamped = switch["stamped"]
        text = self.closed_question(
            "package.mode",
            f"This story was started in {stamped.get('mode')} mode, and this run is in driver mode. "
            "Stages of one story are run one way, because each way leaves the story's records under "
            "its own assumptions, and mixing them can leave a stage judged by rules it was not built under.\n\n"
            "What I need is a decision. Answer with exactly one of these words:",
            [{"answer": "desktop", "token": "desktop", "says": "you finish the story in the desktop app; the driver runs "
                                                              "nothing meanwhile", "slots": {"what": "finish the story in the desktop app"}},
             {"answer": "go on", "token": "go on", "says": "go on in driver mode; I record your words as the reason the story "
                                                           "carries"},
             self.STOP_OPTION])
        details = (f"run_mode stamped in pipeline.json: {json.dumps(stamped, ensure_ascii=False)}\n"
                   f"this run: driver, package {self.plugin} (version {self._copy_version(self.plugin) or 'unknown'})\n"
                   "Your answer is recorded by code with: "
                   f"python \"{self.scripts / 'waiver.py'}\" --task {self.task} --stage {stage} "
                   "--block \"mode switch\" --decision \"<your words>\"")      # prose: test_words_doors' inline-door census keys on the literal
        self.state["package_question"] = {"what": "mode", "stage": stage, "text": text, "details": details}
        raise Person("package", text, stage, details=details)

    # --- claude ----------------------------------------------------------------------------
    def claude_cmd(self, prompt: str, *, agent: str = "", resume: str = "", tools: str = ROLE_TOOLS,
                   system_file: Path | None = None, max_turns: int = 0, plugin_agent: bool = True) -> list:
        # The prompt goes through stdin, never argv: a gate packet plus the person's words
        # is longer than a Windows command line (WinError 206 at gate A, driver run 3).
        if self.host == "codex":
            return self.codex_cmd(resume=resume)
        cmd = list(self.claude) + ["-p"]
        if resume:
            cmd += ["--resume", resume]
        cmd += ["--output-format", "json", "--permission-mode", "acceptEdits",
                "--model", self.model, "--allowedTools", tools, "--plugin-dir", str(self.plugin)]
        if agent and not resume:
            cmd += ["--agent", f"qa-factory:{agent}" if plugin_agent else agent]
        if system_file:
            cmd += ["--append-system-prompt-file", str(system_file)]
        if max_turns:
            cmd += ["--max-turns", str(max_turns)]
        return cmd

    # --- codex ------------------------------------------------------------------------------
    def codex_cmd(self, *, resume: str = "") -> list:
        """The Codex CLI call of one role or conductor turn, from `codex exec --help` of codex-cli 0.158.0.

        A fresh session: `codex exec --json -C <project> [-s <sandbox>] --skip-git-repo-check -m <model> [-c key=value
        ...] -` - `--json` is the JSONL event stream `parse_codex_jsonl` reads, `-C` is the project root (the role's
        cwd, as on Claude), `-` reads the prompt from stdin (never argv: the Windows command line is shorter than a
        gate packet). A continuation: `codex exec resume <thread id> --json --skip-git-repo-check -m <model> [-c ...]
        -`: the resume subcommand takes `--json` too, but not `-C` or `-s`: the thread keeps its own cwd and sandbox.
        `-m` is ALWAYS passed: `self.model` is `--model` or the data's `default_model.codex` (refused at start when
        neither exists), never a host default the factory does not name. Codex exec has no `--allowedTools`,
        `--max-turns` or `--agent`: the role's tools are the host's, its turn count is unbounded, and the role's
        instructions travel in the prompt (`host_prompt`). `driver.codex.sandbox` (`read-only`, `workspace-write`,
        `danger-full-access`; any other value is passed as given and Codex refuses it) and `driver.codex.config` (`-c
        key=value` pairs; a value that is not a string is written as JSON, so `true`, `3` and `["a"]` reach Codex as
        TOML reads them; an object or `null` has no such form and is left out at start with a note) are the project's
        say; absent, the project's own `.codex/config.toml` rules (F-6)."""
        cmd = list(self.claude) + ["exec"]
        if resume:
            cmd += ["resume", resume, "--json"]
        else:
            cmd += ["--json", "-C", str(self.project)]
            if self.codex_cfg.get("sandbox"):
                cmd += ["-s", self.codex_cfg["sandbox"]]
        cmd.append("--skip-git-repo-check")
        if self.model:
            cmd += ["-m", str(self.model)]
        overrides = self.codex_cfg.get("config") or {}
        for key in sorted(overrides):
            value = overrides[key]
            cmd += ["-c", f"{key}={value if isinstance(value, str) else json.dumps(value)}"]
        cmd.append("-")
        return cmd

    def host_prompt(self, prompt: str, *, agent: str = "", resume: str = "", system_file: Path | None = None) -> str:
        """What the child reads on stdin. On Claude, the prompt as it is: `--agent` and `--append-system-prompt-file`
        carry the role and the rule layer. On Codex there is no such flag, so a FRESH session gets, in this order, the
        role's own definition (`inject_context.role_block`: the one function of the role's body, which the Codex hook
        also reads, without its Desktop tool block - the child is a CLI), the rule layer the driver built
        (`system_file`: what `--append-system-prompt-file` would append) and the task. A continuation (`resume`) gets
        the prompt alone: the thread already holds its role. A role file that cannot be read adds no block and says so
        in one line (S-8)."""
        if self.host != "codex" or resume:
            return prompt
        parts = []
        if agent:
            import inject_context
            block = inject_context.role_block(agent, self.plugin, desktop_guide=False)
            if block is None:
                print(f"note: no role file for {agent} in {self.plugin}: the Codex prompt carries no role block", flush=True)
            else:
                parts.append(block.strip())
        if system_file is not None:
            try:
                layer = Path(system_file).read_text(encoding="utf-8")
            except OSError as exc:
                layer = ""
                print(f"note: the rule layer {Path(system_file).name} could not be read ({type(exc).__name__}): the Codex prompt "
                      "carries no rule layer", flush=True)
            if layer.strip():
                parts.append("# Rule layer (your system prompt)\n" + layer.strip())
        parts.append("# Task\n" + prompt)
        return "\n\n".join(parts)

    def host_note(self, text: str, *, dispatch: str = "") -> None:
        """A fact about the host's call the person or a later reader should have (a gap, a line that was no event): one
        `note:` line and one `kind: note` row of the driver journal. The row has no `dispatch`, `session_id` or
        `exit_code`, so every reader that binds a session, a price or the end of a dispatch passes it by (the
        `launched` row's shape). A journal that cannot be written is said in the line and never stops the call (P1)."""
        try:
            self.journal_run({"kind": "note", "host": self.host, "dispatch_id": dispatch, "note": text})
            tail = ""
        except OSError as exc:
            tail = f" (and the journal could not be written: {type(exc).__name__})"
        print(f"note: {text}{tail}", flush=True)

    def thread_total(self, session_id: str):
        """The running total of a Codex thread BEFORE the call now ending: the last usable `total_cost_usd` of the rows of
        this task's driver journal that name the thread, read through `driver_journal` (the one reader of that file and of
        what a total means). None when the thread has no row with a usable total (its first call, or only unpriced
        ones) or when the journal cannot be read: the call's price then stands alone, and the row says what it is."""
        import driver_journal
        if not session_id:
            return None
        total = None
        for row in driver_journal.read_rows(self.state_dir / driver_journal.JOURNAL_NAME):
            if row.get("session_id") == session_id:
                usable = driver_journal.usable_total(row.get("total_cost_usd"))
                if usable is not None:
                    total = usable
        return total

    def mark_host(self) -> None:
        """F-5: the story's state names the host its stored sessions belong to - written whenever a session is stored (or
        a cut-off call's session is kept) off Claude, and rewritten whenever the key is already there, so it follows the
        sessions and never outlives them as a stale word (m-1: a Codex thread that was dropped must not leave `codex`
        behind a Claude story). A Claude story with no key keeps its bytes as they were."""
        if self.host != "claude" or "host" in self.state:
            self.state["host"] = self.host

    def host_window_reason(self) -> str:
        """The one reader of the host for the S5 scheduler: "" on Claude, else why S5 windows do not run side by side on this host
        (the hook environment and the receipts of a window are measured on Claude only)."""
        if self.host != "claude":
            return "the host is not Claude, and the hook environment and the receipts of a window are not measured there"
        return ""

    def launch(self, cmd: list, prompt: str, *, dispatch: str = "", resume: str = ""):
        """`_launch` inside the scheduler's launch gate (TR3-6): on a chain thread the session waits for a running session of another
        window that holds a file of its window; off a chain, or with no dispatch (the conductor, the delivery call), nothing changes."""
        with self.session_running(dispatch):
            return self._launch(cmd, prompt, dispatch=dispatch, resume=resume)

    def _launch(self, cmd: list, prompt: str, *, dispatch: str = "", resume: str = ""):
        """Start one `claude -p` process and wait for it: `subprocess.run`'s own steps, taken apart so the process
        id can be written while it runs (B-268: a person, and `dispatch_liveness`, can tell a role at work from a
        record nobody closed). `dispatch` is a ROLE's dispatch id ('' for the conductor and the delivery call:
        liveness is asked per dispatch). The pid exists only once the process has started, so the entry
        `in_flight[<dispatch>] = {dispatch_id, pid, started_at, session_id?}` is written right after the start
        and removed when the call returns by any road (a result, an exception) - an entry still on disk after
        a hard kill is exactly what reads as "the process is gone". The child also gets
        QA_FACTORY_DRIVER_RUN=<dispatch id> in its environment (B-250: the child's own tools can tell they run
        under the driver). A failed state write never stops the run (P1: code informs)."""
        import dispatch_identity
        env = dict(self.claude_env, **{dispatch_identity.DRIVER_RUN_ENV: dispatch}) if dispatch else self.claude_env
        import threading
        import driver_timing
        stop, watcher = threading.Event(), None
        chain = getattr(_CHAIN, "record", None)
        self.stop_if_interrupted()      # B1: the person stopped the run - no new process, whichever road asked (fresh attempt, resume, conductor)
        with subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True,
                              encoding="utf-8", errors="replace", cwd=str(self.project), env=env) as proc:
            try:
                # inside the try (t-335 A-n6): a marking that raised outside it left the child waiting for a prompt
                # nobody sends, and `with` then waited for the child forever
                self.mark_in_flight(dispatch, proc.pid, resume)
                if chain is not None:
                    chain.proc = proc      # the interrupt kills it: a chain thread's own `proc.kill()` would never run on Ctrl-C
                # R1: write first, read second (main: flag, then proc; here: proc, then flag) - one of the two sees the other, so a Ctrl-C that
                # landed during Popen / mark_in_flight never leaves a child nobody kills (the `except` below kills it)
                self.stop_if_interrupted()
                if dispatch:
                    # t-1937 P2-4 (F8 (a)): a silent wait is visible - ONE thread asks the transcript's silence every POLL_S and tells
                    # it once per episode. INVARIANT: it only tells; nothing here kills or signals the process (a role that is
                    # working is never stopped by the driver), and the thread ends with this call (`stop` is set in the `finally`).
                    watcher = threading.Thread(target=driver_timing.watch, args=(self.project, dispatch, stop), daemon=True)
                    watcher.start()
                # TR3-6 (M1): `_book` is given up ONLY while the role's process works; the lock is back (exactly once, even on an exception)
                # before `clear_in_flight` below, which runs under it
                with self.unbooked(dispatch):
                    out, err = proc.communicate(input=prompt)
                # B1: a session the interrupt killed returns here as a plain result; it is never classified, booked or retried.
                # What it leaves is the serial road's own record of a Ctrl-C: a `launched` row with no end row.
                self.stop_if_interrupted()
            except BaseException:
                proc.kill()
                raise
            finally:
                stop.set()
                if watcher is not None:
                    watcher.join(timeout=5)
                self.clear_in_flight(dispatch)
                if chain is not None:
                    chain.proc = None
        return subprocess.CompletedProcess(cmd, proc.returncode, out, err)

    def timed(self, step: str, dispatch: str = "", stage: str = ""):
        """`with self.timed("bind", dispatch, stage):` - one line in `state/driver-timings.jsonl` when the block ends by any road (t-1937
        P2-1). `time.monotonic` for the seconds, `_now()` for the ts; a block that raises still writes its line, with `error: <type>`; the
        exception passes through. The returned object's `.dispatch` may be set inside the block."""
        import driver_timing
        return driver_timing.Timer(self.timing_write, step, dispatch, stage)

    def timing_write(self, step: str, seconds: float, *, dispatch: str = "", stage: str = "", error: str = "") -> None:
        """The ONE writer of `state/driver-timings.jsonl`: one line, one append (`hooklib.append_jsonl_line`, an O_APPEND write under a
        lock - no read-modify-write, so chains writing at once do not lose a line). The console says `note: <step> took N s` only over 20 s,
        flushed (FR-43). A line that cannot be written is said in one note and never stops the run (P1)."""
        import driver_timing
        try:
            stage = stage or str(self.boundary or "").split(":")[0]
            line = driver_timing.row(_now(), stage, dispatch, step, seconds, error)
            hooklib.append_jsonl_line(self.state_dir / driver_timing.CARRIER, json.dumps(line, ensure_ascii=False))
        except Exception as exc:  # noqa: BLE001
            driver_timing.console(f"note: the timing of {step} could not be written ({type(exc).__name__})")
        if seconds > driver_timing.NOTE_OVER_S:
            driver_timing.console(f"note: {step} took {seconds:.0f} s")      # the original stdout: a redirect_stdout window loses nothing

    def mark_in_flight(self, dispatch: str, pid: int, resume: str = "") -> None:
        if not dispatch:
            return
        entry = {"dispatch_id": dispatch, "pid": pid, "started_at": _now()}
        if resume:
            entry["session_id"] = resume
        try:
            self.state.setdefault("in_flight", {})[dispatch] = entry
            self.save_state()
        except OSError:
            pass

    def clear_in_flight(self, dispatch: str) -> None:
        held = self.state.get("in_flight")
        if not dispatch or not isinstance(held, dict) or dispatch not in held:
            return
        held.pop(dispatch, None)
        if not held:
            self.state.pop("in_flight", None)      # no entry, no key: a state with nobody in flight reads as before
        try:
            self.save_state()
        except OSError:
            pass

    def run_claude(self, kind: str, prompt: str, *, role: str = "", dispatch: str = "", stage: str = "",
                   resume: str = "", tools: str = ROLE_TOOLS, system_file: Path | None = None,
                   max_turns: int = 0, plugin_agent: bool = True, resume_key: str = "",
                   resume_reason: str = "") -> dict:
        """One `claude -p` call, and the ONE place an infrastructure failure of it is recognised.

        POSITION INVARIANT (B-012): the classifier runs right after the process exits, before the
        journal line, before the session is stored and before anything is returned, so that no
        caller - `digest_of`, `exit_errors`, the conductor's `last_json_line`, the S8 delivery -
        ever holds an auth, limit or transient result: TP1-13877 read a login error as a
        handoff that was "not in the form", resumed the role on it, called the conductor with it and
        asked the person about it. What comes back is the role's own answer, or a failure no row of
        `driver-infra.json` knows (`unclassified`, exactly as before); the rest raises `InfraStop`.

        `resume_key` names a call that is not a role's dispatch but must be continued the same way
        (`S8:delivery`); a role's own call is keyed by its dispatch. A key with an `interrupted`
        record means the earlier call of that key was cut off: the caller's own resume wins, else the
        session that did work is resumed with the note alone, else a fresh session gets the note
        after the prompt. A transient failure is retried in here, at most twice, by
        `runtime_policy.retry_decision`: a retry is the same call, not a new attempt, so it is never
        counted by `guarded`, the handoff resumes or the conductor's calls.

        `resume_reason` (t-342, B-273): why the CALLER resumes the role's session, in one short line. Every resume
        of a role prints `resume <dispatch>: <reason>` and writes the same words as `resume_reason` into the
        `driver-runs.jsonl` row (a row of a call that is not a resume carries no such key, and a row from before this
        field reads as it always did). A resume the driver itself chooses in here (the session of a call the service
        cut off; a retry after a broken response) names its own reason. A caller that names none gets
        `unclassified (the call named no reason)` - never a silent resume."""
        if not self.claude:
            raise Stop(EXIT_ERROR, f"no `{self.host}` executable on PATH and STORY_RUN_{self.host.upper()} is not set")
        import infra_failure
        import runtime_policy
        key = resume_key or (dispatch if kind == "role" else "")
        interrupted = self.state.setdefault("interrupted", {})
        prior = interrupted.get(key) if key and isinstance(interrupted.get(key), dict) else None
        original_prompt = prompt
        attempt_resume, attempt_prompt, driver_resumed = resume, prompt, False
        why = (resume_reason.strip() or "unclassified (the call named no reason)") if resume else ""
        if prior:
            if resume:
                note = self.continuation_note(kind, role, stage, dispatch, alone=False, known=True)
                attempt_prompt = prompt + ("\n\n" + note if note else "")
            elif prior.get("worked") and prior.get("session_id"):
                attempt_resume, driver_resumed = str(prior["session_id"]), True
                attempt_prompt = self.continuation_note(kind, role, stage, dispatch, alone=True, known=True)
                why = "an earlier call of this dispatch was cut off by the model service; its own session goes on"
            else:
                note = self.continuation_note(kind, role, stage, dispatch, alone=False, known=True)
                attempt_prompt = prompt + ("\n\n" + note if note else "")
        base_resume, base_prompt, base_driver_resumed, base_why = attempt_resume, attempt_prompt, driver_resumed, why
        retries_used, fresh_after_loss = 0, False
        while True:
            self.stop_if_interrupted()      # B1: before the `launched` row and the process, on every attempt of the loop
            cmd = self.claude_cmd(attempt_prompt, agent=role, resume=attempt_resume, tools=tools,
                                  system_file=system_file, max_turns=max_turns, plugin_agent=plugin_agent)
            if attempt_resume and kind == "role" and dispatch:
                print(f"resume {dispatch}: {why}", flush=True)
            started = time.time()
            # t-363 B2 (B-253 g): the call is journalled BEFORE its process starts, not only after it ends. On
            # 02.10 the driver died silently at 05:38 in the middle of a role and the journal held nothing of that
            # launch, so what was running could not be told. The `launched` row is a new KIND of the same file and
            # the same writer as the end row, never a rewrite of one: it names the call (`call`: role / conductor /
            # ...), `dispatch_id` (not `dispatch`: the readers that key on `dispatch` skip it), the stage and
            # `started_at`. It carries NO pid (there is none before the start - `in_flight` is the pid carrier,
            # written right after) and NO `session_id`, `total_cost_usd` or `exit_code`, so every reader that binds
            # sessions, prices or asks how a dispatch ended passes it by: a `launched` row with no end row after it
            # is a call that was running when the driver died, never a completed one. P1: code informs - a journal
            # that cannot be written is said in one line and never stops the call.
            codex = self.host == "codex"
            try:
                self.journal_run({"kind": "launched", "call": kind, "role": role, "dispatch_id": dispatch,
                                  "stage": stage, "started_at": _now(), "model": self.model, "retry": retries_used,
                                  **({"host": self.host} if codex else {})})
            except OSError as exc:
                print(f"note: the launch of this call could not be journalled ({type(exc).__name__}); it goes on", flush=True)
            if codex and role and not attempt_resume and not self.role_has_bash(role):
                # F-8: `codex exec` takes no tool list, so a role whose file lists no Bash runs with the host's tools,
                # and the text written to it names scripts it may not have. Run as is; the gap is named.
                self.host_note(f"{role} lists no Bash in its agent file and `codex exec` takes no tool list: it runs as is, "
                               "with the tools the Codex host gives it", dispatch=dispatch)
            sent = self.host_prompt(attempt_prompt, agent=role, resume=attempt_resume, system_file=system_file)
            done = self.launch(cmd, sent, dispatch=dispatch if kind == "role" else "", resume=attempt_resume)
            self.stop_if_interrupted()      # B1: a call the interrupt cut off is not parsed, journalled or stored
            wall_ms = int((time.time() - started) * 1000)      # t-1937 P2-4: the driver's own clock, next to the CLI's `duration_ms`
            raw = (done.stdout or "").strip()
            if codex:
                data = parse_codex_jsonl(raw, resume=attempt_resume)
                if data["noise"] or (not data["events"] and not data["result"]):
                    if data["subtype"] == "no_events":
                        # F-4: the text is the evidence of a call whose outcome is unknown; its start goes in the row.
                        said = " ".join(str(data.get("partial") or "").split())[:300]
                        what = f"the Codex stream held no event, only {data['noise']} line(s) of text: {said!r}"
                    else:
                        what = ("the Codex stream was empty" if not data["events"] and not data["result"] else
                                f"{data['noise']} line(s) of the Codex stream were not events")
                    self.host_note(what + f" (exit {done.returncode})", dispatch=dispatch)
                if not data["events"] and not data["result"]:
                    data["result"] = done.stderr or ""
            else:
                try:
                    data = json.loads(raw)
                    if isinstance(data, list):  # stream-json style: the result record is last
                        data = next((d for d in reversed(data) if isinstance(d, dict) and d.get("type") == "result"), {})
                    if not isinstance(data, dict):
                        raise ValueError("not a result object")
                except ValueError:
                    data = {"result": raw or done.stderr, "is_error": done.returncode != 0}
            cost, cost_basis, call_cost = data.get("total_cost_usd"), "", None
            if codex:
                # `total_cost_usd` has ONE meaning in every row of every host: the running total of the thread
                # (`driver_journal` reads it so). The CLI reports no price, so the call's own price is worked out
                # (`codex_call_cost`) and ADDED to the thread's earlier rows; the call's price alone is `call_cost_usd`.
                call_cost, cost_basis = codex_call_cost(data.get("usage") or {}, self.model, self.config.get("cost")) \
                    if data["events"] else (None, f"price unknown: the Codex stream carried no usage for {self.model}")
                before = self.thread_total(str(data.get("session_id") or ""))
                cost = codex_running_total(before, call_cost)
                if call_cost is None and before is not None:
                    cost_basis += f"; the thread's total of ${before:.4f} does not include this call"
                print(f"cost {dispatch or kind}: " + (f"${call_cost:.4f} ({cost_basis})" if call_cost is not None else cost_basis), flush=True)
            result = {"session_id": str(data.get("session_id") or ""), "result": str(data.get("result") or ""),
                      "num_turns": data.get("num_turns"), "total_cost_usd": cost,
                      "duration_ms": data.get("duration_ms", int((time.time() - started) * 1000)),
                      "is_error": bool(data.get("is_error")) or done.returncode != 0, "exit_code": done.returncode,
                      "stderr": (done.stderr or "")[-1500:], "subtype": str(data.get("subtype") or ""),
                      # Codex only: a Claude result and its journal row are as they were (the `usage` object of a
                      # `claude -p` record is not copied into them). The usage counts are kept whatever the price says.
                      **({"usage": data.get("usage") or {}, "cost_basis": cost_basis, "call_cost_usd": call_cost} if codex else {})}
            infra = infra_failure.classify(result, self.infra_rules, self.host)
            self.journal_run({"kind": kind, "role": role, "dispatch": dispatch, "stage": stage,
                              "session_id": result["session_id"], "num_turns": result["num_turns"],
                              "total_cost_usd": result["total_cost_usd"], "duration_ms": result["duration_ms"], "wall_ms": wall_ms,
                              "resumed": bool(attempt_resume), "exit_code": done.returncode,
                              "is_error": result["is_error"], "model": self.model,
                              "subtype": result["subtype"], "infra": infra["kind"] if infra else None,
                              "infra_rule": infra["rule"] if infra else None, "retry": retries_used,
                              **({"host": self.host, "usage": result["usage"], "cost_basis": cost_basis,
                                  "call_cost_usd": call_cost} if codex else {}),
                              **({"resume_reason": why} if attempt_resume else {})})
            import driver_timing
            wall_said = driver_timing.wall_note(dispatch or kind, wall_ms, result["duration_ms"])
            if wall_said:
                driver_timing.console(wall_said)   # t-1937 P2-4: one line per call whose own count trails the wall clock by > 120 s
            # B-014, right after the journal line and before anything else sees the result. A call the
            # service cut off (`infra` set, classified or not) is not a session whose answer anyone
            # accepts: it is judged by the paths that already handle it, and a session that never got
            # to run has no hooks to report.
            if not infra:
                self.package_check(result["session_id"], stage=stage, dispatch=dispatch)
            turns = result["num_turns"]
            worked = isinstance(turns, int) and turns > 1
            if infra and infra["kind"] == "unclassified" and driver_resumed and not worked and not fresh_after_loss:
                # A resume the driver chose came back failed after one turn or none: the session is
                # gone (or was never there). ONE fresh attempt with the whole prompt; what it says
                # goes back like any failure of a call.
                note = self.continuation_note(kind, role, stage, dispatch, alone=False, known=True)
                attempt_resume, driver_resumed, fresh_after_loss = "", False, True
                attempt_prompt = original_prompt + ("\n\n" + note if note else "")
                why = ""
                continue
            if infra and infra["kind"] == "transient":
                decision = runtime_policy.retry_decision(infra.get("retry_code") or "", retries_used, 1)
                if decision.get("retry"):
                    delay = decision.get("delay_seconds", 0)
                    print(f"note: the model service answered with a broken response; the same call is tried "
                          f"again in {delay} seconds (retry {retries_used + 1} of 2)", flush=True)
                    with self.unbooked(dispatch):       # TR3-6: a backoff is waiting, not bookkeeping: the other chains go on meanwhile
                        self.sleep(delay)
                    retries_used += 1
                    if worked and result["session_id"]:
                        attempt_resume, driver_resumed = result["session_id"], True
                        attempt_prompt = self.continuation_note(kind, role, stage, dispatch, alone=True,
                                                                known=bool(prior))
                        why = (f"the model service broke the response (retry {retries_used} of 2); the session "
                               "that did the work goes on")
                    elif base_driver_resumed:
                        # The retry falls back to what step (a) chose: the recorded session that did work,
                        # with the note alone - not to a fresh session that would lose it.
                        attempt_resume, driver_resumed, attempt_prompt = base_resume, True, base_prompt
                        why = base_why
                    else:
                        note = self.continuation_note(kind, role, stage, dispatch, alone=False, known=bool(prior))
                        attempt_resume, driver_resumed = base_resume, False
                        attempt_prompt = original_prompt + ("\n\n" + note if note else "")
                        why = base_why if base_resume else ""
                    continue
            break
        if not infra or infra["kind"] == "unclassified":
            changed = False
            if dispatch and result["session_id"]:
                self.state["sessions"][dispatch] = result["session_id"]
                changed = True
                self.mark_host()    # F-5: the host the story's sessions belong to (absent = claude)
            if key and key in interrupted:
                interrupted.pop(key)     # the call that was cut off has been answered: its record leaves
                changed = True
            if changed:
                self.save_state()
            return dict(result, infra=infra)
        # auth, limit, or a transient failure that outlived its retries. The dispatch is NOT stored as
        # a session (a session that hit a wall is not the role's answer) and nothing is saved as a
        # reusable result; what is kept is the fact that this call was cut off, and how far it got.
        if key:
            record = self.interruption(infra, result, kind=kind, stage=stage, role=role, dispatch=dispatch)
            if prior and prior.get("worked") and prior.get("session_id") and not record["worked"]:
                # The record already holds a session that did real work and this stop did none (a login
                # that fails at one turn, a broken answer at one turn): that says nothing about the
                # session, and overwriting the record would make the next rerun start fresh and lose it
                # (13877 rows 2-3: the same session id, resumed, one turn). Only what failed and when is
                # refreshed.
                record.update(session_id=prior["session_id"], num_turns=prior.get("num_turns"), worked=True)
            interrupted[key] = record
            if record.get("session_id"):
                self.mark_host()                      # F-5, as above: a cut-off call's session belongs to this host too
            self.save_state()
        raise InfraStop(infra["kind"], self.infra_message(infra, attempts=retries_used + 1))

    @staticmethod
    def interruption(infra: dict, result: dict, *, kind: str, stage: str, role: str, dispatch: str) -> dict:
        """The record of a call an infrastructure failure cut off: what failed, the session it left, and
        whether that session did real work (more than one turn, and an id to resume it by). The same
        shape is written when a result saved by an older driver turns out to be such a failure."""
        turns = result.get("num_turns")
        session = str(result.get("session_id") or "")
        return {"kind": infra["kind"], "rule": infra.get("rule") or "", "session_id": session, "num_turns": turns,
                "worked": isinstance(turns, int) and turns > 1 and bool(session), "call": kind, "stage": stage,
                "role": role, "dispatch": dispatch, "reset": infra.get("reset") or "", "at": _now()}

    def retire_infra_result(self, saved: Path, result: dict, *, role: str, stage: str, dispatch: str) -> bool:
        """A result this driver saved before B-012 may be an infrastructure failure (the 13877 S3 file:
        a Cloudflare page, 29 turns). It is set aside as `<dispatch>.infra.json`, recorded as the
        dispatch's interruption, and treated as absent: the caller runs the role again, and
        `run_claude` continues the session that worked. False when the result is the role's own (or a
        failure no row knows), which is reused exactly as before."""
        import infra_failure
        infra = infra_failure.classify(result, self.infra_rules)
        if not infra or infra["kind"] == "unclassified":
            return False
        saved.replace(saved.with_name(saved.stem + ".infra.json"))
        self.state.setdefault("interrupted", {})[dispatch] = self.interruption(
            infra, result, kind="role", stage=stage, role=role, dispatch=dispatch)
        self.save_state()
        print(f"[{stage}] {dispatch}: the saved result is a {infra['kind']} failure of the service, not the "
              f"role's answer - set aside as {saved.stem}.infra.json; the role continues", flush=True)
        return True

    # --- what an interrupted call is told, and what the person is told ------------------------
    GENERIC_NOTE = ("Your previous attempt was cut by an infrastructure failure, not by anything you did; "
                    "check what you already did before repeating it, then finish and answer in the form asked.")

    def role_has_bash(self, role: str) -> bool:
        """Does the role's own agent file carry Bash? Unknown role, unreadable file or no `tools:` line: no -
        the one default of every text written to a role (`host_adapter.role_tools`, which reads the line): a door
        the role cannot use is a trap (FR-2), the note names scripts only to a role whose line lists Bash, and
        Edit, the door it names otherwise, is in every role's tools."""
        from host_adapter import role_has_bash
        return role_has_bash(role, self.plugin)

    def written_outputs(self, role: str, stage: str, dispatch: str) -> list:
        """What the role of this stage had already written when its call was cut off: the stage's outputs
        (references/stages.json) whose writer in references/artifact-writers.json is this role, that
        exist - path and bytes, a directory as its file count - plus its handover form."""
        import hooklib
        registry = hooklib.load_ref_json("artifact-writers.json").get("artifacts") or {}
        try:
            outputs = (self.stages().get(stage) or {}).get("outputs") or []
        except Exception:
            outputs = []
        found = []
        for name in outputs:
            entry = registry.get(name)
            if not isinstance(entry, dict) or entry.get("writer") != f"{role} (the role)":
                continue
            path = (self.project / name[len("project:"):]) if name.startswith("project:") else (self.task_root / name)
            if path.is_dir():
                count = sum(1 for p in path.rglob("*") if p.is_file())
                if count:
                    found.append(f"{name} ({count} file{'s' if count != 1 else ''})")
            elif path.is_file():
                found.append(f"{name} ({path.stat().st_size} bytes)")
        form = self.task_root / "work" / "handoffs" / f"{dispatch}.yaml"
        if dispatch and form.is_file():
            found.append(f"work/handoffs/{dispatch}.yaml ({form.stat().st_size} bytes)")
        if dispatch:
            import handoff_check                                   # the one rule for the name of the words waiting beside a form
            values = handoff_check.sibling_values(form)            # the role's words waiting to be applied (SC1-2, F9)
            if values.is_file():
                found.append(f"work/handoffs/{values.name} ({values.stat().st_size} bytes)")
        return found

    def continuation_note(self, kind: str, role: str, stage: str, dispatch: str, *, alone: bool, known: bool) -> str:
        """What a cut-off call is told when it goes on. `alone`: the note is the whole prompt of a resumed
        session (so it ends in the handoff form the role owes); otherwise it follows the original
        prompt. `known`: an `interrupted` record exists. Nothing to say - no outputs on disk, no
        record, not alone - is no note at all: a first call that failed after one turn has nothing to
        continue, and the prompt goes again as it was."""
        if kind != "role":
            return self.GENERIC_NOTE if (alone or known) else ""
        lines = self.written_outputs(role, stage, dispatch)
        if not lines and not (alone or known):
            return ""
        text = ("Your previous attempt at this dispatch was cut by an infrastructure failure, not by anything "
                "you did: this is the same dispatch with the same inputs.")
        if lines:
            text += "\nWhat you had already written:\n- " + "\n- ".join(lines) + "\n"
            if self.role_has_bash(role):
                text += (f"Continue them: keep what parses and passes its check (the plan: `python "
                         f"{self.scripts}/planning_contract.py --kind plan`), repair stale rows "
                         f"(`python {self.scripts}/plan_row.py --task {self.task} --row <id> --set <field>=<value>`), "
                         "add the rest (`--add-row`); set a file aside with `python "
                         f"{self.scripts}/artifact_supersede.py --task {self.task} --path <file> --role {role} "
                         "--reason \"<why nothing in it is usable>\"` only when nothing in it is usable.")
            else:
                text += ("Continue them: keep what parses and passes its check, repair what is stale with Edit "
                         "(one row's own lines, several Edit calls in one turn) and add the rest the same way; "
                         "do not write again whole a file that already holds rows.")
        if alone:
            text += "\n\nYour final message is the handoff form only:\n" + HANDOFF_FORM
        return text

    def continue_command(self, drop_absent=()) -> str:
        """The command that goes on after a stop: the story, the project and every flag this run was
        started with that differs from its default - a rerun with fewer flags is a different run
        (S0 reads `--mr` and the rest; `--until` would run past the gate). `--answer <file>` only while
        the question it answers is still open: an answer already taken is refused as "no question is
        open" when it is offered again. `drop_absent` (t-2181 PC-7 F7): the sides a story WAITS for - their `--side <s>=absent` pair is
        left out, so the packet's restart line (`... --branch <the branch with the code>`) never says a side is absent and real in one
        command; every other pair is repeated as before."""
        ns = self.flags

        def q(value) -> str:
            text = str(value)
            return f'"{text}"' if (not text or re.search(r"\s", text)) else text

        parts = ["python", f'"{self.scripts / "story_run.py"}"', "--task", q(self.task), "--project", f'"{self.project}"']
        if getattr(ns, "plugin_dir", None):
            parts += ["--plugin-dir", q(ns.plugin_dir)]
        if self.host == "codex":
            if self.model_explicit:                  # unnamed, the data's default is read again by the rerun
                parts += ["--model", q(ns.model)]
        elif str(getattr(ns, "model", "") or "sonnet") != "sonnet":
            parts += ["--model", q(ns.model)]
        if getattr(ns, "host", None):                # named by the flag (E-15): a rerun goes on in the same host, `claude` too
            parts += ["--host", q(ns.host)]
        if getattr(ns, "until", None) not in (None, "", "end"):
            parts += ["--until", q(ns.until)]
        for attr, flag in (("mr", "--mr"), ("branch", "--branch"), ("commit", "--commit"),
                           ("ticket_file", "--ticket-file"), ("env", "--env"), ("branch_suffix", "--branch-suffix")):
            if getattr(ns, attr, None):
                parts += [flag, q(getattr(ns, attr))]
        for attr, flag in (("side", "--side"), ("reference", "--reference")):      # t-2181 PC-7: pairs, repeated, as the launch gave them
            for name, word in getattr(ns, attr, None) or ():
                if attr == "side" and word == "absent" and name in drop_absent:
                    continue
                parts += [flag, q(f"{name}={word}")]
        if getattr(ns, "ungrounded", False):
            parts.append("--ungrounded")
        if getattr(ns, "no_trace", False):
            parts.append("--no-trace")
        # `--skip-sources` is NOT repeated: S0 keeps it in `launch` (`s0()`), and a story that is past S0
        # meets the flag on a command line only as the person's own late word, which asks (`skip_sources_late`).
        bound = getattr(ns, "max_boundaries", None)
        if bound not in (None, "") and int(bound) != 80:      # 0 is a value: it runs no stage after S0
            parts += ["--max-boundaries", str(int(bound))]
        if getattr(ns, "answer", None) and self.state.get("asked"):
            parts += ["--answer", q(ns.answer)]
        return " ".join(parts)

    def infra_message(self, infra: dict, *, attempts: int) -> str:
        """What the person reads when the infrastructure stopped the driver: what happened in plain
        words - owner the environment, nothing about the story wrong or lost - then the ONE block where
        a command is allowed to appear (references/human-questions.md, rule 5). Nothing is asked: the
        block says there is nothing to answer, and gives the command that goes on."""
        kind = infra["kind"]
        if kind == "auth":
            body = ("The model service would not let the factory in: this machine is not logged in to it, so "
                    "the step that was running could not start. Nothing about the story is wrong and nothing "
                    "was lost; the step goes on from where it stopped once you are logged in.")
            todo = "log in to the model service on this machine"
        elif kind == "limit":
            reset = str(infra.get("reset") or "").strip()
            body = ("The model service says this account has reached its usage limit, and "
                    + (f"it names this reset time: {reset}." if reset else "the service named no reset time.")
                    + " Nothing about the story is wrong and nothing was lost; the step that was running "
                      "goes on from where it stopped.")
            todo = "wait for the limit to reset" + (f" ({reset})" if reset else "")
        else:
            body = ("The model service returned a broken response"
                    + (f" {attempts} times in a row" if attempts > 1 else "")
                    + ", so the step that was running could not finish. This is the service's fault, not the "
                      "story's: nothing about the story is wrong and nothing was lost; the step goes on from "
                      "where it stopped.")
            todo = "wait a few minutes for the service to recover"
        block = f"\n## How to answer\nNothing to answer: {todo}, then run:\n  {self.continue_command()}"
        if kind == "auth":
            if self.env_removed:
                block += ("\nThe driver started the model without these variables of this shell, which may point at "
                          "a host proxy that gives a child process no token: " + ", ".join(self.env_removed) + ".")
            block += ("\nIf you sign in through a gateway or an API key on purpose, list the variables the model "
                      "must keep as `driver.child_env.keep` in qa-factory/config.json.")
        return body + "\n" + block

    def system_file(self, role: str, dispatch: str, scope: list) -> Path | None:
        """The rule layer inject_context.py delivers on an Agent dispatch: a headless
        `--agent` session has no PreToolUse Agent hook, so the driver hands it over as the
        appended system prompt instead."""
        # RC1-14 step 5 (N5): the driver REFUSES as the hook does, never runs a role with no rule layer (`blocks = []`). Twin of the
        # hook (`inject_context.dispatch`, axis 8): the same kind, the same text, the same denial line, the same packet.
        # State first (S1): the kind comes from THIS dispatch's record; a story with no controller.json is kind `first`.
        import inject_context
        state = self.controller_state()
        if not isinstance(state, dict):
            state = {}
        records = state.get("dispatches")
        record = records.get(dispatch) if isinstance(records, dict) else None
        record = record if isinstance(record, dict) else None
        kind = inject_context.dispatch_kind(record)
        denial_event = {"cwd": str(self.task_root), "tool_input": {"prompt": f"Dispatch id: {dispatch}"}}
        try:
            imap = inject_context.load_map()
            if not imap:
                raise RuntimeError("references/inject-map.json is missing or empty")
            if role not in (imap.get("roles") or {}):
                raise RuntimeError(f"the role {role} has no entry in references/inject-map.json")
            blocks = inject_context.collect_blocks(role, imap, None, kind)
        except ValueError as exc:
            # over budget: the hook's text byte for byte, the hook's denial line (`recover` closes the receipt)
            inject_context.note_denial(denial_event, self.task, None, role, str(exc))
            refusal = Refusal(str(exc), dispatch=dispatch, title="injection_over_budget")
            refusal.known = False
            raise refusal from exc
        except Exception as exc:
            # DIFFERS from the hook, which fails open here (injection is not security-critical): the driver has the conductor
            # seam the hook lacks, so a role is never started with no rules (AR-28, AR-17); the door is the dry run (AR-9)
            text = (f"the injection layer could not be built ({type(exc).__name__}: {exc}); the role was not started; "
                    f"check it with inject_context.py --dry-run --role {role}; the conductor decides a re-run or the person's word")
            inject_context.note_denial(denial_event, self.task, None, role, text)
            refusal = Refusal(text, dispatch=dispatch, title="injection_unbuilt")
            refusal.known = False
            raise refusal from exc
        # t-304 N1 (reader #4): the packet names THIS driver's project and package, resolved now (B-014: the driver's own
        # generation) - the paths the state stored at `initialize` are hints, and a story copied to another worktree kept
        # the old one's. What cannot be resolved is left out with one stderr note (the story is never stopped for it,
        # and never handed the stored paths instead).
        try:
            import runtime_paths
            resolved = runtime_paths.state_paths(state.get("known_paths", {}), self.task_root, project=self.project,
                                                 plugin=self.plugin, python=sys.executable)
            # E10, as the hook: the record's own `known_paths` is resolved the same way and laid over the state's by `task_packet`
            if record is not None and isinstance(record.get("known_paths"), dict) and record["known_paths"]:
                record = dict(record, known_paths=runtime_paths.state_paths(
                    record["known_paths"], self.task_root, project=self.project, plugin=self.plugin, python=sys.executable))
        except Exception as exc:
            # The same line the hook gives (H12): the role is told, the person gets one signal (`inject`) per dispatch.
            resolved = {}
            if record is not None and "known_paths" in record:
                record = dict(record, known_paths={})
            try:
                blocks.append(inject_context.unavailable_block(
                    None, role, "packet-paths",
                    f"the task packet carries no paths: the stored paths could not be resolved ({type(exc).__name__}: {exc}); "
                    f"work from the prompt and name it under blocked"))
            except Exception:
                print(f"note: the stored paths could not be resolved ({type(exc).__name__}: {exc}) - the packet carries none")
        # ONE packet function for the hook and the driver (AR-13): one `known_paths`, the whitelisted `dispatch` with its kind
        packet = inject_context.task_packet(self.task, state, record, resolved, dispatch, role=role, scope=scope)
        blocks.append("\n\n" + inject_context.PACKET_HEADING + " (reuse paths and completed checks)\n" + json.dumps(packet))
        path = self.state_dir / "driver-tmp" / f"{dispatch}.system.md"
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text("".join(blocks), encoding="utf-8")
        return path

    # --- the handoff, checked the way the exit gate checks it ------------------------------
    def exit_errors(self, role: str, digest: str, dispatch: str | None = None) -> list:
        """The exit gate's blocking records for the role's handoff. A check that could NOT run (an `unreadable` record, or
        the gate itself raising) is not the role's work: it used to be a line in the list the role was resumed over, a paid
        resume over the factory's own defect (D14, RH1-5). Now it is ONE `Refusal` (title `gate_unreadable`, `known` False,
        so `route_known` returns None and `handle_refusal` gives it to the conductor, who asks the person and files the
        finding). POSITION: inside this function - the one point every call of the gate passes. INVARIANT: no `assemble_digest`,
        no resume of the role and no `shorten_form` runs over an unknown gate; a record the person's named word already
        passed is in `passed`, not in `blocking`, and raises nothing (E17). The author's own findings that stood next to
        the unreadable ones travel in the same refusal, after them (E2)."""
        crash = ""
        try:
            import exit_gate
            # the dispatch being gated is named to the gate (TR3-13): with two windows running the count cannot say which one it is.
            # It is the PARAMETER (`handoff` has the id), never `last_dispatch` (another window's, or none, on a saved or resumed
            # result). The hold wraps `all_errors` ONLY: it is a process global and `handoff` goes on to `run_claude` (t-2087 F1).
            with exit_gate.holding_dispatch(dispatch):
                blocking, _passed = exit_gate.all_errors(role, self.task, digest)
            blocking = list(blocking)
        except Exception as exc:
            blocking, crash = [], f"the exit gate could not run: {type(exc).__name__}: {exc}"
        unreadable = [r for r in blocking if getattr(r, "kind", "") == "unreadable"]
        if not (crash or unreadable):
            return blocking
        others = [r for r in blocking if getattr(r, "kind", "") != "unreadable"]
        lines = [crash] if crash else [str(r) for r in unreadable]
        try:
            import hooklib
            hooklib.person_signal({"cwd": str(self.task_root)}, "gate_unreadable", f"{role}: " + "; ".join(lines),
                                  task=self.task)
        except Exception:
            pass        # the refusal below is the loud part; a signal that cannot be written never hides it
        listing = self.listed(lines + [str(r) for r in others], "", "handoff")[0]
        refusal = Refusal(f"the exit gate of {role} for {self.task} could not run {len(lines)} check(s), so it does not know "
                          "whether the handoff is acceptable - the factory's own defect, not the role's work; the role is NOT "
                          "resumed and the conductor takes it. Unreadable first, the author's own findings (if any) after:\n"
                          + listing, findings=lines + [str(r) for r in others], title="gate_unreadable")
        refusal.known = False
        raise refusal

    def form_errors(self, dispatch: str) -> list:
        """The handover FORM, checked beside the digest so ONE resume asks for both.

        Only the role can answer what is left after `--fix`, and resuming it is what that
        costs - about $0.60, against $0.45 for a conductor session that cannot answer it at
        all. So the form travels in the same refusal as the exit gate's, and the role repairs
        both in the one resume it already gets.
        """
        return self.form_report(dispatch)[1]

    def form_report(self, dispatch: str, *, shorten: bool = False) -> tuple:
        """`(the handoff_check report or None, the form's error lines)`: the ONE reader of the form check in the driver
        (C2-4: `shorten` adds `--shorten`, the driver's own flag - a role's `--fix` never cuts). `None` when there is no form or
        the check printed no JSON."""
        form = self.task_root / "work" / "handoffs" / f"{dispatch}.yaml"
        if not form.is_file():
            return None, []
        code, out = self.py("handoff_check.py", "--file", str(form), "--task", self.task,
                            "--task-root", str(self.task_root), "--fix", *(["--shorten"] if shorten else []), "--json")
        report = hooklib.read_document(out)  # t-2020: `handoff_check --json` prints a PRETTY object (indent=1): the document reader; a stderr warning does not hide it
        if report is None:
            # an answer nobody could read is an unknown, never a pass of the form gate (AR-28, FR-59), exit 0 or not
            return None, [f"handover form: handoff_check gave no readable answer (exit {code}): {((out or '').splitlines() or ['no output'])[-1][:200]}"]
        required = bool((self.config.get("handoffs") or {}).get("required", True))
        if report.get("untouched") and not required:
            return report, []
        for line in report.get("fixed") or []:
            print(f"note: handover form filled by code: {line}")
        return report, [f"handover form {form.name} - {p['path']}: {p['problem']}"
                        for p in report.get("problems") or []]

    def shorten_form(self, role: str, dispatch: str, digest: str, *, assembly_follows: bool = True) -> int:
        """C2-4 (K9): the number of form fields code cut to their limit (`handoff_check.py --shorten`); 0 when nothing was
        cut - no form, an unreadable answer, or a form with a problem beside the length (the role is woken for that one and says
        it shorter itself, P1). A field over its limit is a count, not a judgement; the role's whole text stays in the form's
        `shortened:` section (I1).

        The guard on the DRIVER's side: the exit gate has nothing to say except, WHERE THE ASSEMBLY FOLLOWS (`assembly_follows`,
        the `handoff` entry), that the last message is not the form (`FINAL_MESSAGE_FORM_RE` - `assemble_digest` answers that, by
        code, on the cut form). Where no assembly follows (the ladder point, after the first resume) that line goes to the role
        with the cut form's words: the exit side must be EMPTY, or the cut leaves the role woken over words code shortened
        (t-919 F-2, edge 6). The guard on the CHECK's side is in `handoff_check.shorten`: it cuts only when every problem of the
        form is a length problem. A failure of either only means "not cut" - today's road, the role."""
        exit_side = self.exit_errors(role, digest, dispatch)
        if any(not (assembly_follows and FINAL_MESSAGE_FORM_RE.search(e)) for e in exit_side):
            return 0
        cut = (self.form_report(dispatch, shorten=True)[0] or {}).get("shortened") or []
        if cut:
            print(f"handoff: {dispatch}: {len(cut)} field(s) over their limit cut by code; the whole text is in "
                  f"work/handoffs/{dispatch}.yaml (shortened) - no resume", flush=True)
        return len(cut)

    def digest_of(self, text: str) -> str:
        """The handoff inside the role's last message: from its header line down. A role that
        says one sentence before the header ("time to finalize the digest and stop") would
        otherwise be refused for a preamble it has already ended, and the resume that follows
        costs a full context (TP1-13797, run 3: the critic was resumed six times)."""
        import role_digest
        lines = role_digest._lines(text)
        if not lines:
            return str(text or "").strip()[:DIGEST_MAX]
        start = 0
        for index, line in enumerate(lines):
            header, error = role_digest._parse_header(line)
            if not error and header.get("verdict"):
                start = index
                break
        digest = "\n".join(lines[start:][-40:])
        return digest[:DIGEST_MAX]

    def s1_person(self, role: str, errors: list, digest: str, stage: str, dispatch: str) -> None:
        """The S1 stops that are a person's, never a resume's and never the conductor's: a source gap, a source review. Raises
        `Person`; returns when the scout's finding set holds neither (and for any other role, and for an EMPTY set - nothing to
        ask). Called twice by `handoff`: on the role's own message (before any resume), and again on the set that is left after the
        ladder's resume (t-809 F-2) - a mixed set (a gap beside a review, a gap beside a form line) that survives the resume keeps
        the road it has always had, instead of a `Refusal` that `route_known` sends to the conductor."""
        if role == "qa-scout" and any(re.search(S1_GAP_RE, e, re.IGNORECASE) for e in errors) \
                and not any(re.search(S1_REVIEW_RE, e, re.IGNORECASE) for e in errors):
            raise Person("s1_gap", self.s1_gap_text("; ".join(errors)), stage, dispatch)
        if role == "qa-scout" and any(re.search(S1_REVIEW_RE, e, re.IGNORECASE) for e in errors):
            # The exit gate names the person, not the role: the source review is the stop the
            # scout's procedure plans, and a repair resume or the conductor can only spend
            # money on it (driver run 3: $0.18 resume + $0.37 conductor per stop).
            raise Person("s1_review", self.s1_review_text(digest), stage, dispatch,
                         answer_note=human_text.onboarding_note(self.pipeline().get("environment"), self.config.get("environments")))

    def handoff(self, role: str, stage: str, dispatch: str, result: dict) -> str:
        """The role's last word, in the form. One resume for the form or a repair the exit
        gate names; what is still wrong after that is a refusal for the table or the
        conductor (a person's waiver passes it, as at the real gate)."""
        if result["is_error"] and not result["result"].strip():
            raise Refusal(f"claude -p for {dispatch} failed (exit {result['exit_code']}): {result['stderr']}",
                          dispatch=dispatch)
        self.revoke_passes_of_dead()    # t-781 m4: before `exit_errors` reads the waiver rows - a dead dispatch's pass is not this one's
        digest = self.digest_of(result["result"])
        errors = self.exit_errors(role, digest, dispatch) + self.form_errors(dispatch)
        # N10 (C2-9): a gap by default whose carrier is a collector receipt is collected again at every scout handover, with
        # or without errors - after the person restores a VPN the merge request simply arrives (FR-57: the door of a default).
        if role == "qa-scout" and (errors or self._defaulted_vcs()) and self.close_vcs_gaps(errors):
            # What code can collect, code collects, and it happens before any branch below decides
            # to ask a person or to resume the role: the material the ladder reaches is simply
            # there on the next read of the gate.
            errors = self.exit_errors(role, digest, dispatch) + self.form_errors(dispatch)
        self.s1_person(role, errors, digest, stage, dispatch)
        # C2-4 (K9): a field over its limit is cut by code, not by a paid session (`shorten_form`). POSITION INVARIANT: AFTER the
        # S1 branches (a person's stop never waits for a cut, I5) and BEFORE the assembly and the resume below - a resume for a
        # count is the cost this removes; the cut happens only when length is the form's sole problem, so a set that also holds
        # judgement still wakes the role once, who can say it shorter itself.
        if errors and self.shorten_form(role, dispatch, digest):
            errors = self.exit_errors(role, digest, dispatch) + self.form_errors(dispatch)
        # t-217 / F-cmp2-23 (FR-42, FR-48): the role is resumed ONCE per finding set on one dispatch+session, across
        # entries and relaunches. The saved result is handed to `handoff` again on every entry (`wait_existing_job`),
        # and every entry used to resume the role again over the same findings (eight resumes in cmp2, 04:27-04:34,
        # and a conductor call between each pair). POSITION INVARIANT: after the S1 branches above (a source gap or
        # review is the person's, never a resume) and BEFORE the resume below; the record is written BEFORE the paid
        # call, so a crash costs one resume and never repeats one. A role that has not seen these findings is still
        # resumed once before anyone else is asked.
        # t-342 (B-273, FR-47/P6): when the ONLY thing wrong is that the role's last message is not the handoff form
        # and the form is all there in what the role already wrote (its handover form, its artifact), the driver
        # assembles the digest by code and does not resume the session for one turn. POSITION INVARIANT: after the S1
        # branches (a person's stop is never assembled over) and BEFORE the resume record is read or written - an
        # assembly is not a resume, and a refused one leaves the resume to happen exactly as before. The assembled
        # digest must pass the SAME exit gate and form check the role's own message would have (all errors gone, or it
        # is not used); anything else wrong beside the digest is the role's to repair, so no assembly is tried then.
        not_assembled = ""
        if errors and all(FINAL_MESSAGE_FORM_RE.search(e) for e in errors):
            assembled, not_assembled = self.assemble_digest(role, stage, dispatch, result)
            if assembled:
                left = self.exit_errors(role, assembled, dispatch) + self.form_errors(dispatch)
                if not left:
                    self.keep_assembled_result(dispatch, result, assembled)
                    print(f"handoff: {dispatch}: the role's final message is not the handoff form; the form is "
                          "assembled by code from its handover form and its artifact (assembled_by: code) - no resume",
                          flush=True)
                    return assembled
                not_assembled = "the assembled form still fails the exit gate: " + " ".join(left[0].split())[:160]
        return self.handoff_ladder(role, stage, dispatch, result, digest, errors, not_assembled)

    def saved_result(self, dispatch: str) -> dict:
        """The dispatch's saved result (`state/driver-runs/<dispatch>.json`): what a resume wrote, {} when there is none."""
        found = _read_json(self.state_dir / "driver-runs" / f"{dispatch}.json")
        return found if isinstance(found, dict) else {}

    EXIT_ASK_HEADS = {"handoff": "The exit gate refused your handoff",
                      "refusal": "The factory refused to close your dispatch",
                      "structured": "The factory refused the structured artifact you handed over"}

    def listed(self, lines: list, dispatch: str, name: str, *, noun: str = "finding") -> tuple:
        """`(the list as a role reads it, whether it was cut, why the whole list is NOT in a file)`: ONE call of
        `detector_verdict.render` - every line whole up to its byte ceiling, past it a count and the path of the file that holds
        the whole list, `state/findings/<dispatch>-<name>.txt` (written by that very call, FR-37). A file left by an earlier call is
        removed first (as `exit_gate._render_saved` does), so a file that exists afterwards is this call's. The third value is `""`
        when nothing was cut or the file was written; else the clause a head may state in place of a promise (`the list is cut at
        N; the whole list could not be saved: <reason>` - a dry run, a blank dispatch or a failed write, FR-10/FR-41). No count of
        lines is a ceiling anywhere (C2-1): the text is the whole list or says where the rest is."""
        lines = [str(line) for line in lines]
        path = None if self.dry or not dispatch else self.state_dir / "findings" / f"{dispatch}-{name}.txt"
        if path is not None:
            try:
                path.unlink(missing_ok=True)
            except OSError:
                pass
        shown, cut = DV.fit(lines)
        text = DV.render(lines, full_path=path, noun=noun, source=f"driver, dispatch {dispatch or 'unknown'}")
        was_cut = bool(cut or len(shown) < len(lines))
        if not was_cut or (path is not None and path.is_file()):
            return text, was_cut, ""
        reason = ("this is a dry run, which writes no file" if self.dry else "the dispatch has no name" if not dispatch
                  else "the file could not be written")
        return text, True, f"the list is cut at {len(shown)}; the whole list could not be saved: {reason}"

    def exit_ask(self, role: str, dispatch: str, errors: list, *, why: str = "handoff") -> str:
        """The words a role is resumed with over the exit gate's refusal: ALL the lines, what code filled in its form, what code
        fetched while the boundary ran, and what to do. ONE text for the handoff's free resume and for the person's paid
        `round` (t-764: a second copy would drift). `why`: the road that reached the seam - the head names the REAL refusal
        (t-781 m5: a finish refusal or a structured-artifact refusal is not "the exit gate refused your handoff"); an unknown
        `why` keeps the handoff's head. The lines go through `listed` (C2-1): the count, every line, and past the byte ceiling the
        file that holds the rest - never the first eight of N."""
        filled = (self.state.get("form_filled") or {}).get(dispatch) or []
        # F14 (E16): a role whose file lists no Bash is never told to run a script - it edits the form with its Edit tool
        seen_fix = ("set it yourself with `handoff_check.py --file <form> --set <path>=<value>`." if self.role_has_bash(role)
                    else f"correct it in work/handoffs/{dispatch}.yaml with your Edit tool (the exit check runs by itself when "
                         "you hand off; its refusal comes back in this session).")
        seen = ("\n\nCode filled these fields of your form from the artifacts they come from, so "
                "you do not retype them. Read them: if one is wrong for your work, "
                + seen_fix + "\n"
                + self.listed(filled, dispatch, "filled", noun="line")[0]) if filled else ""
        got = [line for lines in (self.state.get("collected") or {}).values() for line in lines]
        arrived = ("\n\nWhile this boundary ran, code fetched this material through the factory's "
                   "own authenticated route — it is on disk now; what it means for the story is "
                   "yours to read and say:\n" + self.listed(got, dispatch, "collected", noun="line")[0]
                   ) if got and role == "qa-scout" else ""
        shown, cut, unsaved = self.listed(errors, dispatch, "handoff")
        # the head promises the file ONLY when the file was written (t-809 F-1, FR-10/FR-41): a list cut with no file says so
        reach = unsaved or "they are all listed here" + (" (the rest in the file named at the end of the list)" if cut else "")
        return (self.EXIT_ASK_HEADS.get(why, self.EXIT_ASK_HEADS["handoff"]) + f": {len(errors)} finding(s). Repair every one of "
                "them in this turn - " + reach
                + ":\n" + shown + arrived + seen +
                "\nRepair what it names in the artifact you wrote (never another role's file), "
                "and fill every `handover form` line in work/handoffs/" + dispatch + ".yaml - "
                "the values it names are the only ones your role may write, and what you cannot "
                "fill goes under `blocked`. Then print your handoff in the exact form and "
                "nothing else:\n" + HANDOFF_FORM)

    def handoff_ladder(self, role: str, stage: str, dispatch: str, result: dict, digest: str, errors: list,
                       not_assembled: str) -> str:
        """The resume ladder of `handoff` (t-764 A13: extracted, its body unchanged but for the first branch): a new finding set
        is resumed once (and once more when every error is mechanical); a set the role has already seen, or a role with no
        session, goes to the ONE seam `exit_limit` (the person is asked; a round the person bought is spent there and the
        role's new result is judged again); what is still wrong after the ladder is a `Refusal`."""
        resume_sid = self.refusal_sid(dispatch, result["session_id"])
        resume_key = finding_key(errors) if errors else ""
        if errors and (not result["session_id"] or (resume_key and resume_key in self.resume_record(dispatch, resume_sid))):
            if result["session_id"]:
                print(f"{stage}: {dispatch} was already resumed on these findings; no second resume")
            self.exit_limit(stage, role, dispatch, self.refusal_lines(None, items=errors), sid=result["session_id"] or "", why="handoff",
                            digest=digest)
            return self.handoff(role, stage, dispatch, self.saved_result(dispatch))
        elif errors and result["session_id"]:
            if resume_key:
                self.note_resume(dispatch, resume_sid, resume_key, "handoff")
            ask = self.exit_ask(role, dispatch, errors)
            again = self.run_claude("role", ask, role=role, dispatch=dispatch, stage=stage,
                                    resume=result["session_id"],
                                    resume_reason=resume_reason(errors)
                                    + (f" (not assembled by code: {not_assembled})" if not_assembled else ""))
            if again["result"].strip():
                digest = self.digest_of(again["result"])
                self.keep_resumed_result(dispatch, again, result)
            errors = self.exit_errors(role, digest, dispatch) + self.form_errors(dispatch)
            # C2-4 (K9), POSITION INVARIANT: between the first resume's recompute and the third resume's condition - the third
            # resume is never spent on a length (a count code makes), and a set the cut empties returns the digest below.
            if errors and self.shorten_form(role, dispatch, digest, assembly_follows=False):
                errors = self.exit_errors(role, digest, dispatch) + self.form_errors(dispatch)
            if errors and all(_mechanical(e) for e in errors):
                # A second and last resume, and this one SHOWS the line instead of describing it.
                # TP1-13797, 26.09: after one resume the critic still had two reasons of 81 and
                # 84 characters and an unfilled receipt path — mechanical to the last character —
                # and the refusal went to the conductor ($0.99) and then to the person, who can fix
                # none of it. One more cheap turn at the role is the right move; if it fails too,
                # the refusal travels as before. (The lengths no longer reach here: C2-4 cuts them above; cmp3
                # showed this turn spent on the receipt-binding lines, which are judgement.)
                # F14 (E16): no Bash in the role's file -> its Edit tool, never a script it cannot run
                how = (f"Your handoff form: fix exactly these {len(errors)} line(s), one field at a time, with "
                       "`handoff_check.py --file work/handoffs/" + dispatch + ".yaml --set <path>=<value>` (never rewrite the file):\n"
                       if self.role_has_bash(role) else
                       f"Your handoff form work/handoffs/{dispatch}.yaml: fix exactly these {len(errors)} line(s) with your Edit "
                       "tool, one field at a time (never rewrite the file):\n")
                exact = ("Two things and nothing else. 1) " + how
                         + self.listed(errors, dispatch, "handoff")[0]
                         + "\n2) Then print your digest, in the form, and nothing else:\n" + HANDOFF_FORM)
                third = self.run_claude("role", exact, role=role, dispatch=dispatch, stage=stage,
                                        resume=again.get("session_id") or result["session_id"],
                                        resume_reason="still not repaired after one resume: " + resume_reason(errors))
                if third["result"].strip():
                    digest = self.digest_of(third["result"])
                    self.keep_resumed_result(dispatch, third, again if again["result"].strip() else result)
                errors = self.exit_errors(role, digest, dispatch) + self.form_errors(dispatch)
        # t-809 F-2: the S1 person branches are evaluated AGAIN on the set the resume left (POSITION INVARIANT: after the
        # resume's recompute, BEFORE the `Refusal` - a scout's source gap or review that survives it is the person's, so a mixed
        # set keeps `s1_gap` / `s1_review`; an empty set raises nothing and returns the digest)
        self.s1_person(role, errors, digest, stage, dispatch)
        if errors:
            raise Refusal(f"exit gate for {dispatch} ({role}, {stage}): {len(errors)} finding(s):\n"
                          + self.listed(errors, dispatch, "handoff")[0],
                          files=[str(self.task_root)], dispatch=dispatch, findings=errors)
        return digest

    # --- what the driver itself says to a person, in words ---------------------------------
    def stage_place(self, stage: str) -> str:
        """`the plan stage (S3)`: where the story is, as a person names it (stages.json holds the
        name); `stage S3` when the name is unknown, `this story` when there is no stage."""
        name = ""
        try:
            name = str((self.stages().get(stage) or {}).get("name") or "").strip().lower()
        except Exception:
            pass
        if stage and name:
            return f"the {name} stage ({stage})"
        return f"stage {stage}" if stage else "this story"

    @staticmethod
    def role_words(role: str) -> str:
        """`qa-test-strategist` -> `test strategist`: a role as a person names it."""
        return re.sub(r"^qa-", "", str(role or "")).replace("-", " ").strip() or "role"

    def halt_text(self, stage: str, role: str, digest: str, *, again: bool = False) -> str:
        """What a person reads when a role hands the decision back, in plain words.

        TP1-13877: the halt led with a dispatch id and pasted the role's whole final message
        under it, and the check that reads the form found nothing (FR-6). The body says which
        stage stopped and which role, then one line per row the role reported - the row's id and
        its own reason, never its state word; the message itself goes to the details file
        (`Person.details`). A header that does not parse, or no rows, means the role gave no
        reason we can read, and the text says exactly that (FR-41) instead of guessing one."""
        import role_digest
        # The rows are read from the halting header `is_halting` finds - on ANY line, so prose
        # above it does not hide them; with no halting header there is no row to trust (FR-41).
        rows, digest_lines = [], role_digest._lines(digest)
        for index, line in enumerate(digest_lines):
            header, error = role_digest._parse_header(line)
            if not error and header.get("verdict") in role_digest.HALTING_VERDICTS:
                rows = role_digest.parse("\n".join(digest_lines[index:])).get("rows") or []
                break
        lines = []
        for row in rows:
            if row.get("state") == "ok":
                continue
            reason = " ".join(str(row.get("reason") or "").split())
            lines.append(f"- {row.get('id')} — {reason or 'the report gives no reason'}")
        place = self.stage_place(stage)
        words = self.role_words(role)
        stop = self.STOP_OPTION
        reported = ("What it reported:\n" + "\n".join(lines) if lines else
                    "It gave no reason in its report; its own words are in the file named below.")
        if stage == "S1" and self.s1_has_no_diff():
            # F7: the scout's manifest says no change was found (`implementation.source: none`). Its answers all go to the
            # scout as words (the halt road, kind `halt`; `not built yet` first records the side, see below); the question is phases/s1.md's, priced. Like every halt kind it keeps
            # what the role reported (FR-8/FR-35: the rows are the role's own verdict, the manifest only picks the question) and
            # says `again` when the role stopped a second time.
            return self.closed_question(
                "s1.no_diff",
                f"No implementation was found for {self.task}.{f' The {words} stopped on it again.' if again else ''}\n\n"
                f"{reported}\n\nTesting without grounding is a decision, so pick one:",
                [{"answer": "change", "says": "give me the change: a merge request, a branch or a commit, in your own words",
                  "slots": {"role": f"the {words}", "what": "the merge request, branch or commit"}},
                 {"answer": "lives", "says": "name where it already lives: the stand and the repository in which the change is in "
                                              "place; the tests are grounded on the current code, not on a change",
                  "slots": {"role": f"the {words}", "what": "the stand and the repository"}},
                 {"answer": "ungrounded", "says": self.UNGROUNDED_SAYS, "slots": {"role": f"the {words}"}},
                 # the twin of `s0.no_change` (AR-19): the same answer, the same words (one constant). Its executor is `take_answer`'s
                 # `s1.no_diff` branch (`_answer_s1_not_built`, PC-7 B3): it records `pipeline.sides.product` absent and deliverable.
                 {"answer": "not built yet", "says": self.NOT_BUILT_YET_SAYS, "slots": {"role": f"the {words}"}},
                 stop])
        held, block = self.halt_questions(stage, words)
        asked = self.closed_question(
            "halt",
            f"{place[:1].upper()}{place[1:]} stopped{' again' if again else ''}: the {words} cannot go on without a decision.\n\n"
            + reported + held,
            [{"answer": "words", "says": "answer in your own words ('go on without it' is an answer); the same role continues "
                                         "in its own session with your words", "slots": {"role": f"the {words}"}}, stop])
        # B2 (HF2-7): the "how to answer" block stands BELOW the priced section (a text a person reads obeys the order of
        # human-questions.md); the tokens the text prices are the section's own
        return Priced(str(asked) + ("\n\n" + block if block else ""), asked.priced)

    def halt_questions(self, stage: str, words: str) -> tuple:
        """`(the one-decision line and the cards, the answer block)` of a halt at S2-S4 over a register that has open questions, else
        `("", "")` (B2). The role stopped and the factory also holds questions open: the person is shown them HERE, with how to answer
        them by id, because the halt road records those lines by code (`_unread_halt_or_review`) before the conductor is called (FR-48).
        The cards and the block come from `question_stop` (`open_cards`, `answer_block`: the one builder of each, AR-13/AR-15); at a halt
        the only word read as a whole answer is `stop` (`whole=("stop",)`). A failed read shows the halt as it always was."""
        try:
            import question_register as QR
            import question_stop as QS
            if f"{stage} stop" not in QR.vocabulary()["where"]:
                return "", ""
            cards = QS.open_cards(self.task_root)
            block = QS.answer_block(self.task_root, ("stop",)) if cards else ""
        except Exception as exc:
            print(f"note: the open questions could not be added to the halt ({type(exc).__name__}: {exc}); it is shown without them")
            return "", ""
        if not cards:
            return "", ""
        return ("\n\nThis is one decision: what the " + words + " should do about the stop above. The factory also holds the "
                "questions below open; if your answer settles any of them, put it on its own line by its id (see \"How to answer\" "
                "below); the ones you leave out are asked again later.\n\n" + "\n".join(cards), block.rstrip("\n"))

    def s1_has_no_diff(self) -> bool:
        """Does the scout's context manifest say that no change was found (`implementation.source` / `implementations[].source`
        / `implementation_source` is `none`)? ONE reader (`handoff_check.manifest_impl_source`). Error direction: a manifest that is
        absent or unreadable is False - a misread never invents a special question."""
        try:
            import handoff_check
            return handoff_check.manifest_impl_source(_read_json(self.task_root / "work" / "context-manifest.json")) == "none"
        except Exception:
            return False

    @staticmethod
    def stuck_facts(controller_state, pipeline, stage: str, *, place=None, ids: bool = True) -> list:
        """B-20 (t-1988 N5, AR-22/AR-17): what CODE can read about the stages before `stage` that are not completed - one line per stage:
        its status, what the acceptance of its consumer says (awaited for a dispatch, or standing for it) and the controller's `reason`.
        Pure data, no judgment (AR-29): the lines are facts for the conductor, not a verdict on why the step comes back. An unreadable
        controller state or pipeline gives `[]` (FR-41: an unknown is not reported as a fact), and so does a story with no earlier stage open.
        `ids=True` (default): the factory's own lines, dispatch ids and the raw `reason` included (the conductor's text and the details file).
        `ids=False`: the PERSON's lines (F3, FR-6): the stage named by `place(stage)` (default `stage Sn`) and the role in plain words, no
        dispatch id and no raw reason."""
        import acceptance
        if (not isinstance(controller_state, dict) or not isinstance(controller_state.get("stages"), dict)
                or not isinstance(pipeline, dict) or not pipeline or not re.fullmatch(r"S\d+", stage or "")):
            return []
        lines = []
        for number in range(int(stage[1:])):
            name = f"S{number}"
            entry = controller_state["stages"].get(name)
            status = entry.get("status") if isinstance(entry, dict) else None
            if not isinstance(status, str) or status in ("completed", "skipped"):
                continue        # a stage whose row cannot be read is not reported as a fact
            parts = [f"{name} {status}" if ids else f"{place(name) if place else f'stage {name}'} is {status}"]
            consumer = acceptance.consumer_of(name)
            if consumer:
                who = consumer.removeprefix("qa-").replace("-", " ")
                awaited = acceptance.awaits_acceptance(controller_state, name, pipeline)
                author = acceptance.stage_author_dispatch(controller_state, acceptance.stage_def_of(name))
                role = ((controller_state.get("dispatches") or {}).get(author) or {}).get("role") if author else None
                work = f"the work of the {Driver.role_words(role)}" if role and not ids else "its author's work"
                if awaited:
                    parts.append(f"acceptance by the {who} is awaited for {awaited}; no accept record stands for it" if ids
                                 else f"the {who} has not accepted {work} yet")
                elif author and acceptance.accepted_for(pipeline, name, author):
                    parts.append(f"acceptance by the {who} stands for {author}" if ids else f"the {who} accepted {work}")
                else:
                    parts.append(f"no accept record stands for the {who}'s acceptance" + (f" of {author}" if author else "") if ids
                                 else f"no acceptance by the {who} is recorded")
            if ids and isinstance(entry.get("reason"), str) and entry["reason"].strip():
                parts.append(f"reason: {entry['reason'].strip()[:300]}")
            lines.append("; ".join(parts))
        return lines

    def stuck_facts_for(self, stage: str) -> tuple:
        """`(person lines, factory lines)` of `stuck_facts` for the live story: the first for the text a person reads, the second for the
        conductor's text and the details file. A state that cannot be read gives `([], [])` (facts are an aid, not a gate)."""
        try:
            state, pipeline = self.controller_state(), self.pipeline()
            return (self.stuck_facts(state, pipeline, stage, place=self.stage_place, ids=False),
                    self.stuck_facts(state, pipeline, stage))
        except Exception:  # noqa: BLE001
            return [], []

    def stuck_text(self, stage: str, *, waits_on_person: bool = False, facts=(), answered=None) -> str:
        """The driver asked `where` four times (`STUCK_REPEATS`) and got the same answer: it stops instead of
        asking a fifth. The answer itself (a JSON line) goes to the details file. `facts`: the lines of `stuck_facts`, put under the lead
        instead of "I cannot tell from here" (none: today's lead). `answered`: the record `{answer, at}` of the person's earlier answer to
        this very step (`state["stuck_asked"]`): said as new text, never the same question again (FR-7)."""
        at = f"at {self.stage_place(stage)}" if stage else "on this story"
        holding = ("I cannot tell from here what is holding it. The step's own answer is in the file named below, if you want it.")
        if facts:
            holding = "What the factory can read about the earlier stages:\n" + "\n".join(f"- {line}" for line in facts)
        if waits_on_person:      # t-698 sec. 21 (ii): S7 waits on the person's recorded `open_work`; the caller (the loop) reads it
            holding = ("What holds it: you decided to keep this stage open for more work, so the factory asks you before it closes it; "
                       "it does not close it over your word.")
        again = (f"You answered {answered['answer']} at {answered['at']}; the same step still comes back, so asking the same question again "
                 "would not move it.\n\n" if isinstance(answered, dict) and answered.get("answer") else "")
        return (f"The driver stopped {at}: the same step came back {({4: 'four'}).get(STUCK_REPEATS, STUCK_REPEATS)} times in a row with nothing "
                "changing in between, so I stopped instead of repeating it.\n\n" + again + holding)

    def refused_text(self, stage: str) -> str:
        """Six refusals in a row at one boundary. Each refusal is written for the role or the
        script that met it; the last one goes to the details file, whole."""
        at = f"at {self.stage_place(stage)}" if stage else "on this story"
        # C2-7 §5.5: the story's own words for what is missing. The `cap` is raised at ANY boundary (a gate, a waiting job, a closed story
        # after the retro), so with no stage the lead says nothing about a stage (FR-41): only that the reasons are the factory's own.
        missing = f"{self.stage_place(stage)} has not finished, and the reasons it was" if stage else "the reasons it was"
        facts = self.stuck_facts_for(stage)[0] if stage else []       # B-20 F3: the same person-safe facts as the stuck lead (no ids)
        known = ("\n\nWhat the factory can read about the earlier stages:\n" + "\n".join(f"- {line}" for line in facts)) if facts else ""
        return (f"The driver stopped {at}: {REFUSALS_PER_BOUNDARY + 1} times in a row a check of the factory's own turned "
                "the same move back, so I stopped instead of trying again.\n\n"
                "I cannot put those reasons into the story's own words - they are written for the "
                "script that met them, not for you. The last one is in the file named below, if you "
                "want it.\n\n"
                f"What the story is missing: {missing} turned back are written for the factory's own scripts, "
                f"so I cannot tell which answer {'of that step ' if stage else ''}would move it." + known)

    # --- one role, start to finish ---------------------------------------------------------
    def run_role(self, stage: str, role: str, *, scope=None, extra=(), complete=None, purpose="",
                 rework: dict | None = None, budget=READ_BUDGET, after=None) -> tuple:
        """start -> claude -p -> bind -> handoff -> finish. Returns (digest, next action).
        `complete`: None = the stage's own rule (its last role closes it), True/False forces.
        `rework`: an already-registered rework dispatch {id, scope, reason} instead of `start`.
        `budget`: the repair budget the S5 loop read for this review, handed to the repair-limit gate as it is (t-729 F2).
        `after`: `after(dispatch, result)`, code that runs once the role is over (t-1957 N5s, E5s.1/E5s.2). POSITION INVARIANT: after the result
        exists (fresh or reused; `{}` when the role crashed or raised) and BEFORE `bind`, `handoff`, `question_threshold`, `repair_limit_gate`
        and `finish`, so the dispatch is still `running` when it writes the records the exit check and `finish` read. A `finally`: a role
        that crashes, is refused or returns nothing still gets its `after`. `None` = the run as it was."""
        stages = self.stages()
        scope = [s for s in (scope or []) if s]
        if rework:
            dispatch = rework["id"]
            import story_step
            # A rework dispatch gets its brief too (files, commands, the person's words);
            # without it the role searches, and the plugin is closed to it.
            form_file = self.task_root / story_step.FORM_REL.format(dispatch_id=dispatch)
            card_file = story_step.launch_card.card_path(self.task_root, dispatch)
            if not form_file.is_file() or not card_file.is_file():
                # F1 (B-7, AR-14): the ONE writer of brief + form + card; `keep` never overwrites a file the role may have filled.
                # A differing card is one note and the role still runs (P1: the prompt carries everything).
                try:
                    story_step._write_dispatch_files(self.task, stage, role, dispatch, self.task_root,
                                                     ",".join(rework.get("scope") or scope), [], keep=True)
                except ValueError as exc:
                    print(f"note: {exc}")
                brief = story_step._project_rel(self.task, story_step.BRIEF_REL, dispatch)
            else:
                brief, note = story_step._brief(self.task, stage, role, dispatch, self.task_root)
                if note:
                    print(f"note: {note}")
            # `line` is the whole line when the caller has one (a dispatch continued after an
            # infrastructure interruption is NOT a rework, and saying "Rework reason" would tell the
            # role its work was refused); `reason` is the rework's own.
            prompt = story_step._prompt(self.task, stages[stage], role, dispatch,
                                        [rework.get("line") or f"Rework reason: {rework.get('reason') or ''}"], brief)
        else:
            # TR3-6: POSITION - before `start`; INVARIANT: a drain registers no new dispatch (a chain that gets here while another raised stops)
            self.stop_if_drained()
            self.count_launch()
            args = ["start", "--task", self.task, "--stage", stage, "--role", role]
            if scope:
                args += ["--scope", ",".join(scope)]
            if purpose:
                args += ["--purpose", purpose]
            if stage == "S6" and role == "qa-runner":
                # S6 is two packets: this call runs the automated half (the manual-agent one
                # goes through run_manual_block, which registers its own dispatch).
                args += ["--execution-kind", "automation"]
            if self.on_chain():
                args.append("--parallel-window")        # only the scheduler's chains ask the controller to admit a window beside another
            with self.timed("start", stage=stage) as lap:         # t-1937 P2-1; the dispatch is known once `start` has answered
                if self.on_chain() and role == "qa-code-critic":
                    # a critic's `start` settles its probe debt (up to 90 s): not under `_book`, one settle at a time
                    # F2: the settle mutates test files in place, so for its length the chain counts as RUNNING to the launch gate
                    # (`chain_overlap_running`): a sibling's session on a file of this window waits for it, and is woken at the end
                    record = getattr(_CHAIN, "record", None)
                    record.running = True
                    try:
                        with self.unbooked(settling=True):
                            out = self.step(*args)
                    finally:
                        record.running = False
                        self._cond.notify_all()
                else:
                    out = self.step(*args)
                dispatch, prompt = parse_prompt(out)
                lap.dispatch = dispatch
            import driver_timing
            for part, seconds in driver_timing.parse_lines(out):    # `start`'s own sub-steps: one reader, never printed raw
                self.timing_write(part, seconds, dispatch=dispatch, stage=stage)
            for line in out.splitlines():
                if line.startswith("note:"):
                    print(line)
        self.boundary = f"{stage}:{dispatch}"
        saved = self.state_dir / "driver-runs" / f"{dispatch}.json"
        result = _read_json(saved) if saved.is_file() else {}
        if result.get("result") and self.retire_infra_result(saved, result, role=role, stage=stage, dispatch=dispatch):
            result = {}      # an infrastructure failure saved by an older driver is not a result to reuse
        if after is None:
            # t-2016 F4: the walk hook has ONE site, this one, whoever called: a dispatch with a walk record (`state/walks/<dispatch>.json`) gets
            # its session reopened when it is not ready (a continuation after an infrastructure cut, a launch that never happened) and the
            # same `after` the first launch had. A dispatch with no record is not a walk: `after` stays None and nothing here ran.
            # t-2022 N7: a saved result stands = no role runs = nothing is reopened (the saved result is read FIRST); `after` still runs
            lane, reopened = self.walk_reopen(dispatch, reopen=not result.get("result"))
            if lane:
                after = lambda d, r, lane=lane: self.walk_after(lane, d, r)     # noqa: E731
            elif dispatch in once_on(self, "survey_reopened", set):
                after = self.survey_after       # t-2548 F1 (AR-25): a survey session reopened just above has no lane, but it is closed when the role ends
            if reopened:        # a survey walk has no lane (no `after` of a case) but its reopened session is told to the role (batch 2b D)
                extra = [*extra, reopened]
        # t-1991 U3b (the ONE join point of every S7 triage dispatch; an investigation gets neither): the walk session opens only when the
        # role will run (no saved result) and BEFORE the lines, which name the session or why there is none; it closes in the `finally` below.
        triage = self.s7_is_triage(stage, role, dispatch, purpose)
        opened = triage and not result.get("result") and self.s7_settle_session(dispatch)
        lines = [prompt]
        if scope:
            lines.append("Dispatch scope (one digest line per item): " + ", ".join(scope))
        if triage:
            lines += self.s7_place_lines(dispatch)         # E3b.1: the ONE site, before `extra`; fresh, scribe-reject and seam rework alike
            lines += self.s7_neighbour_lines(dispatch)     # t-2187 N6: the neighbourhood hint, beside the place lines, the same triage dispatches
        lines += list(extra)
        lines.append(f"Plugin root: {self.plugin} — factory scripts are `python {self.scripts}/<name>.py`; "
                     "the rule layer is in your system prompt, do not read the plugin's files.")
        lines.append("Your final message is the handoff form only:\n" + HANDOFF_FORM)
        full_prompt = "\n".join(lines)
        try:
            if not result.get("result"):
                print(f"[{stage}] {role} → {dispatch}" + (f" scope={','.join(scope)}" if scope else ""))
                self.progress_line()
                result = self.run_claude("role", full_prompt, role=role, dispatch=dispatch, stage=stage,
                                         system_file=self.system_file(role, dispatch, scope))
                _write_json(saved, result)
            else:
                print(f"[{stage}] {dispatch}: reusing the saved result of session {result.get('session_id')}")
        finally:
            if opened:
                self.s7_settle_close(dispatch)          # E3b.2: a role that crashes or is refused leaves no session behind
            if after is not None:
                after(dispatch, result)
        if result["session_id"]:
            with self.timed("bind", dispatch, stage):
                code, out = self.py("story_step.py", "bind", "--task", self.task, "--dispatch-id", dispatch,
                                    "--agent-id", result["session_id"])
            if code and not rework:
                raise Refusal(f"story_step bind (exit {code}):\n{out}", dispatch=dispatch)
        self.last_dispatch = dispatch     # the S5 loop reads this critic's typed form (B-007)
        # CX1-14 (F-2 (b)): ONE reader of a declared halt, `story_step._declared_halt`, called twice. BEFORE `handoff`,
        # the FORM alone: a role that wrote `header.verdict: halt` and ended on a message that is not the form is heard
        # without paying the resume `handoff` would spend on it. POSITION INVARIANT (B-1): the scout (S1) is skipped
        # here - its source gaps and reviews (`close_vcs_gaps`, `s1_person`, D-0043) run INSIDE `handoff` and must
        # speak before any generic halt - and a dead run (an error with no words) stays `handoff`'s Refusal. AFTER
        # `handoff`, form + digest for every role, scout included, which covers a halt that arrives after a resume.
        # Both before `question_threshold` and `finish` (t-113 B2).
        import story_step
        form_rel = story_step.FORM_REL.format(dispatch_id=dispatch)
        dead = bool(result["is_error"]) and not result["result"].strip()
        early = role != "qa-scout" and not dead and story_step._declared_halt(self.task_root, form_rel, "")
        if early:
            digest = self.digest_of(result["result"])
        else:
            with self.timed("handoff", dispatch, stage):
                digest = self.handoff(role, stage, dispatch, result)
        if early or story_step._declared_halt(self.task_root, form_rel, digest):
            # O1 (C1-7c, kind T as T1): the halt reaches the person either way (the Person below is raised whatever the write did) and
            # the role is NOT run again; a failed write is journalled as `trace_failed` and the story goes on to the halt's question
            self.py_trace("stage_done.py", "--task", self.task, "--stage", stage, "--status", "halted", "--role", role, "--digest", digest,
                          why=HALT_RECORD_WHY)
            raise Person("halt", self.halt_text(stage, role, digest), stage, dispatch,
                         details=str(digest or "").strip() or "the role's final message was empty")
        if role == "qa-scout" and re.search(r"\bS1\s+review\b", digest):
            raise Person("s1_review", self.s1_review_text(digest), stage, dispatch,
                         answer_note=human_text.onboarding_note(self.pipeline().get("environment"), self.config.get("environments")))
        # POSITION INVARIANT (t-113 B2, R15): after the halting check above, so a role that stopped
        # on its own is asked once by the `halt` road and never twice, and BEFORE `finish`, so the
        # stage cannot be closed over the very questions the person has not yet seen.
        self.question_threshold(stage, role, dispatch)
        # POSITION INVARIANT (t-698 A4): after the threshold and BEFORE `finish`, so a window is never closed over a repair limit,
        # an uncounted budget or a rejection nobody can repair that the person has not answered for this critic dispatch.
        self.repair_limit_gate(stage, role, dispatch, digest, scope or None, budget=budget)
        finished = self.finish(dispatch, digest, complete=complete, role=role, stage=stage)
        self.progress_line()            # the role returned and its work is recorded: where the story stands now
        return finished

    def finish(self, dispatch: str, digest: str, *, complete, role: str, stage: str) -> tuple:
        """`complete` may be a callable of the digest: the critic's verdict decides whether
        its finish closes the stage, and the verdict is known only here."""
        if callable(complete):
            complete = complete(digest)
        # A window the critic could not close: `(word, reason)` (t-201). A tuple is truthy and means
        # complete, so it can never be `--not-complete`; a word or a reason that is empty (or not text)
        # is no pair at all and the finish is today's plain `--complete`.
        unresolved, given, open_pair = (), complete, ()
        if isinstance(complete, OpenWork):      # BEFORE the tuple branch: an OpenWork is "not complete, with this pair"
            pair = tuple(x.strip() if isinstance(x, str) else "" for x in (complete.unresolved, complete.reason))
            open_pair = pair if all(pair) else ()
            complete = False
        elif isinstance(complete, tuple):
            pair = tuple(x.strip() if isinstance(x, str) else "" for x in (list(complete) + ["", ""])[:2])
            unresolved = pair if all(pair) else ()
            complete = True
        args = ["finish", "--task", self.task, "--dispatch-id", dispatch, "--digest", digest]
        window_gaps: list = []      # the gap lines of this finish's window record (exit 1): read by the window-round cap only
        if complete is True:
            args.append("--complete")
            if unresolved:
                args += ["--unresolved", unresolved[0], "--reason", unresolved[1]]
            if stage == "S5" and role == "qa-code-critic":
                # FR-48/FR-5: the controller closes S5 only over a window acceptance record; building
                # it is a routine command, so code runs it and passes the file (no conductor).
                window = f"work/windows/{dispatch}.json"
                stamp = self.file_stamp(self.task_root / window)
                with self.timed("window_record", dispatch, stage):
                    wcode, wout = self.py("window_record.py", "--task", self.task, "--dispatch", dispatch)
                if wcode:
                    window_gaps = self.window_note(dispatch, wcode, wout, stamp, self.file_stamp(self.task_root / window))
                else:
                    args += ["--window", window]
                # The record says the window holds gaps the critic could not close: the finish carries them
                # as `unresolved` + `reason` (state-exits.md: an S5 window accepted as unresolved), the door
                # `story_step.py` names. Only exits 0 and 1 wrote a FRESH record (2 is a crash, and the file
                # on disk may be an older build); a missing or unreadable file is today's behaviour.
                if not unresolved and wcode in (0, 1):
                    found = self.window_gap(self.task_root / window, self.task_root)
                    if found:
                        unresolved = found
                        args += ["--unresolved", found[0], "--reason", found[1]]
                        print(f"S5: the window record of {dispatch} holds gaps the critic could not close "
                              f"({found[0]}); the finish accepts it as unresolved with their words")
                        if wcode:       # exit 1 wrote the record, and this is the record the gap was read from
                            args += ["--window", window]
        elif complete is False:
            args.append("--not-complete")
            if open_pair:
                args += ["--unresolved", open_pair[0], "--reason", open_pair[1]]
            elif stage == "S5" and (self.on_chain() or self._chains):
                # TR3-6 (B3): a finish that does not close S5 while other windows are open says so, so the controller does not refuse it as
                # "no role to close it". Only a process whose scheduler has run passes it (a chain's finish, and the seam's retry of one on
                # the main thread, where the cases come from the controller's record of the dispatch); the serial road's finish is as it was.
                own = self.s5_cases_of(dispatch)
                args +=self.s5_open_flag(own) if own else []
        if stage == "S9":
            # R-212.1: the report is rebuilt as the story's LAST step, and here the retro role has just
            # returned and this call is what closes S9 (`story_step finish` records the stage itself).
            self.rebuild_report()
        with self.timed("finish", dispatch, stage):
            code, out = self.py("story_step.py", *args)
        for line in out.splitlines():
            if line.startswith("note:") or line.startswith("accepted"):
                print(line)
        saved = self.state_dir / "driver-runs" / f"{dispatch}.json"
        if code:
            retry = lambda: self.finish(dispatch, digest, complete=given, role=role, stage=stage)
            if stage == "S9" and f"stage_done refused {stage}" in out:
                # The dispatch is accepted already; only the S9 record was refused, so "again" is that
                # record with the very arguments `story_step` used, never a second acceptance.
                def retry_record():
                    self.py("stage_done.py", "--task", self.task, "--stage", stage, "--status", "done",
                            "--role", role, "--digest", digest, check=True)
                    if saved.is_file():
                        saved.replace(saved.with_suffix(".done.json"))
                retry = retry_record
            # `window_gaps` travels in a field of its own, never in the text: the text is story_step's own words
            # (t-217 §4/C2), and the one-resume record keys on them.
            raise Refusal(f"story_step finish {dispatch} (exit {code}):\n{out}", retry=retry, dispatch=dispatch,
                          window_findings=window_gaps)
        if complete is True and WINDOW_ROUND_STAGES.get(stage) == role:
            # F-cmp2-28c / C1: ONLY the accepted completion of the stage's closing role ends the window's series.
            # An author's finish (`--not-complete`) between two reviews of the same window never does: that is
            # exactly where cmp2-27 (automator-10, accepted) sat between critic-2 and critic-3.
            self.close_window_series(stage, dispatch)
            if stage == "S5":
                self.s5_release_of_dispatch(dispatch)       # Q1: S5 closed - the window that closed it frees its files on EVERY road
        if complete is True and stage == "S5":
            self.s5_release_completed()     # TR4-10 D5: after `story_step finish` exited 0, so the stage status read is the one this finish wrote
        self.revoke_passes_of_dead(dead=(dispatch,))     # t-764 A5: a person's word over its refusal does not outlive the dispatch it was for
        self.forget_resumes(dispatch)       # accepted: its resume record has nothing left to guard
        if saved.is_file():
            saved.replace(saved.with_suffix(".done.json"))
        try:
            return digest, parse_next(out)
        except Refusal:
            return digest, {}

    @staticmethod
    def file_stamp(path):
        """(mtime in ns, size) of a file, or None when it is not there. "This call wrote the file" is judged by this
        before/after pair and never by an exit code: `window_record.py` writes the record first and a later failure is
        caught after the write (t-217 §4)."""
        try:
            path = Path(path)
            stat = path.stat()
            return (stat.st_mtime_ns, stat.st_size) if path.is_file() else None
        except OSError:
            return None

    def window_note(self, dispatch: str, wcode: int, wout: str, before, after) -> list:
        """What the driver says when `window_record.py` exited non-zero, in the words of what is TRUE (FR-37, FR-41):
        `story_step finish` passes `work/windows/<dispatch>.json` by itself when the file is there
        (`story_step.py` S5 block), so "the finish goes without a window record" was false whenever exit 1 had
        written the record. The gap lines are printed; a line carrying a marker is not echoed (cmp2-27: "This is a
        repair, not a question for the person" was printed at the person). PRINT ONLY: the `--window` and
        `--unresolved` decisions of `finish` are unchanged, and the output is never part of a Refusal's text.
        Returns the gap lines of an exit 1 (the window-round cap reads them), else [].

        Four facts, by the file's own stamp: written by this call and exit 1; written and a later error; present
        but not written by this call (an older record, which `story_step` still reads); absent."""
        lines = [line.rstrip() for line in str(wout or "").splitlines()]

        def marked(line: str) -> bool:
            return any(marker.lower() in line.lower() for marker in (REPAIR_MARKER, PERSON_MARKER))

        shown = [line for line in lines if line.startswith("  - ") and not marked(line)]
        if after is None:
            say = (f"S5: window_record.py could not build the record of {dispatch} (exit {wcode}); "
                   "no record exists, the finish goes without one")
        elif after == before:
            say = (f"S5: window_record.py could not build the record of {dispatch} (exit {wcode}); "
                   "an older record is on disk and story_step reads it")
        elif wcode == 1:
            say = (f"S5: found {len(shown)} gap(s) in the window of {dispatch}; the finish passes the record it "
                   "wrote and the controller judges it")
        else:
            say = (f"S5: window_record.py for {dispatch} exited {wcode} after it wrote the record; the finish "
                   "passes the record on disk and the controller judges it")
        echo = shown or [line for line in lines[-6:] if line.strip() and not marked(line)]
        print(say + (":" if echo else ""))
        for line in echo:
            print(line)
        return [line[4:].strip() for line in shown] if wcode == 1 else []

    def close_window_series(self, stage: str, dispatch: str) -> None:
        """The window's rounds end with the closing role's accepted completion: its series leaves the state."""
        held = self.state.get("window_rounds")
        if not isinstance(held, dict):
            return
        gone = [key for key in {self.window_key(stage, dispatch), f"{stage}|{dispatch}"} if held.pop(key, None) is not None]
        if gone:
            self.save_state()

    # The gap kinds an S5 window may be accepted with as `unresolved` (state-exits.md): the critic's two
    # words for a change it could not close, and the handed instances (`acceptance.HANDED_OUTCOME`).
    WINDOW_GAP_KINDS = ("could_not_judge", "fitted_to_code")
    WINDOW_REASON_LIMIT = 300

    @classmethod
    def window_gap(cls, path, root=None) -> tuple:
        """`(word, reason)` for the gaps the critic could not close in the window record at `path`, or `()`.

        The word is the FIRST gap kind in the record's own order (its keys as written: `instances`, then
        `expectation_changes`), the reason names every kind and carries the record's own gap lines, cut at
        WINDOW_REASON_LIMIT characters - the kinds stand first, so the cut never hides one. The gap lines are
        `acceptance`'s (`handed_to_person:<id>`, the vocabulary's sentence per change): nothing is re-worded
        here. A record that is missing, unreadable or holds none of these gaps gives `()`, which is today's
        plain `--complete`: the controller's own refusal then takes the road it always took.

        INVARIANT (t-204 F1): code never accepts a window as `unresolved` over a gap the critic did not name
        as its own. The controller reads `unresolved` as present or not, so a pair covers EVERY gap of the
        window; the record is therefore read through `acceptance.validate_window` (the controller's own
        function, over the task root `root`, by default three levels above the record) and ANY gap other than
        a handed instance's own (`handed_to_person:<id>`) or one of the critic's two kinds (`could_not_judge`,
        `fitted_to_code`) gives `()`, so the controller's refusal stays reachable for that window. A record the
        validation cannot read gives `()` too: the error direction is the refusal."""
        try:
            path = Path(path)
            record = json.loads(path.read_text(encoding="utf-8-sig"))
            if not isinstance(record, dict):
                return ()
            from acceptance import HANDED_OUTCOME, expectation_change_gaps, validate_window
            owned = {text for text, code in expectation_change_gaps(record) if code in cls.WINDOW_GAP_KINDS}
            for gap in validate_window(record, Path(root) if root else path.parent.parent.parent):
                if not (gap.startswith(HANDED_OUTCOME + ":") or gap in owned):
                    return ()
            found = {"instances": [], "expectation_changes": []}
            for item in record.get("instances") if isinstance(record.get("instances"), list) else []:
                if isinstance(item, dict) and item.get("outcome") == HANDED_OUTCOME:
                    found["instances"].append((HANDED_OUTCOME, f"{HANDED_OUTCOME}:{item.get('instance_id') or '?'}"))
            for text, code in expectation_change_gaps(record):
                if code in cls.WINDOW_GAP_KINDS:
                    found["expectation_changes"].append((code, text))
        except Exception:
            return ()
        order = [k for k in record if k in found] + [k for k in found if k not in record]
        gaps = [gap for key in order for gap in found[key]]
        if not gaps:
            return ()
        kinds = list(dict.fromkeys(kind for kind, _text in gaps))
        reason = (", ".join(kinds) + ": " + "; ".join(text for _kind, text in gaps))[:cls.WINDOW_REASON_LIMIT]
        return kinds[0], reason

    def rebuild_report(self) -> bool:
        """`report_facts.py --write` for this story: the code-owned blocks of `test-report.md`, refreshed by
        code (R-212.1). Never a role's call and never a question to the person: a report problem is the
        factory's own, and the door is `--write`, the scribe's rework, or this printed line (FR-3, FR-42).

        A `write` that refuses (`ok: False`: damaged markers, no report, an older contract) is ONE printed line
        with its own lines and the story goes on - the S9 exit checks the report itself and refuses with the
        doors; a `write` that raises is "report rebuild could not run: <type>: <why>" and the story goes on
        (P1). A second write over unchanged facts changes nothing (P7) and its output is not printed again.
        True when the blocks are as they should be."""
        try:
            code, out = self.py("report_facts.py", "--task", self.task, "--write")
        except Exception as exc:
            print(f"report rebuild could not run: {type(exc).__name__}: {str(exc)[:160]}")
            return False
        lines = [line.strip() for line in (out or "").splitlines() if line.strip()]
        if code and any(line.startswith("Traceback (most recent call last)") for line in lines):
            print(f"report rebuild could not run: {lines[-1][:200]}")      # the script's own `<type>: <why>`
            return False
        shown = ("report rebuild refused, the report is as it was: " + " | ".join(lines)) if code else \
                "\n".join("report: " + line for line in lines)
        if code and not lines:
            shown = f"report rebuild refused, the report is as it was: report_facts.py exited {code} and said nothing"
        if shown and shown != getattr(self, "_report_shown", None):
            print(shown)
        self._report_shown = shown
        return not code

    def record_running(self, stage: str, role: str, dispatch: str, *, retry, relaunched: bool = False, rework_of: str = "") -> None:
        """C1-7c (O2, O4, G3, the never-launched start; F-3 of t-1252): the `running` stage record written BEFORE a registered
        dispatch's role starts - kind G. A non-zero exit is a `Refusal` (the factory's own, `known=False`) that names the dispatch
        (E-c8: in the text through `expect`, and in `refusal.dispatch`) and carries `retry`, the caller's whole step (the record, then
        the same run), so a registered dispatch is run once and never a second time behind the refusal.

        B-1 (t-1252): NO record - no write, no refusal - when the controller's stage is already `completed`, or when the dispatch is
        a rework of accepted work (`rework_of`). `stage_done.py` refuses `--status running` over a controller-completed stage by design
        ("already accepted by the controller": it would un-complete it), and the controller keeps a stage `completed` under later work
        (`set_stage`), so a record there is a refusal no retry can cure and the role would never run. The two exemptions are the one
        fact told twice: `rework_of` is the packet's own statement (known without a read), the controller's `completed` is the state
        `stage_done.py` itself refuses on. POSITION INVARIANT: the exemption is checked FIRST; on every stage that is not completed a
        non-zero exit still refuses before the role runs."""
        stages = self.controller_state().get("stages") or {}
        if rework_of or (stages.get(stage) or {}).get("status") == "completed":
            return
        try:
            self.py("stage_done.py", "--task", self.task, "--stage", stage, "--status", "running", "--role", role, check=True,
                    expect=f"{stage} recorded running for the {'relaunched ' if relaunched else ''}dispatch {dispatch}")
        except Refusal as refusal:
            refusal.dispatch = dispatch
            refusal.retry = retry
            raise

    def resume_role(self, stage: str, role: str, dispatch: str, words: str, *, complete=None) -> tuple:
        """The person answered a halt or the S1 review: the same session goes on."""
        sid = self.session_of(stage, dispatch)      # TR3-6: on a chain the dispatch's own session only
        self.boundary = f"{stage}:{dispatch}:resume"
        # t-113 B2 (R17, Q8): the words answer a threshold stop of THIS dispatch - a role that had
        # finished its work and was stopped by code, not one that stopped itself - so it gets its
        # own text, not "continue from where you stopped".
        stop = self.state.get("question_stop") or {}
        by_stop = bool(stop.get("resume")) and stop.get("dispatch") == dispatch
        # O2 (C1-7c, kind G as G3): the running record is written BEFORE the role goes on; a non-zero exit is a `Refusal` (the factory's
        # own) and the role is not resumed over a stage the record does not show as running. POSITION INVARIANT: nothing below has run
        # (the person's words are still in `pending_words`, the session is untouched), so the registered running dispatch is never run
        # a second time behind the refusal: `retry` is THIS resume (record, then the same run; the G1/G3 pattern, F-2 of C1-7b), and a
        # `continue` leaves the words for `_act_wait_existing_job`, which finds the dispatch by the id the refusal carries (E-c8: in its
        # text, through `expect`, and in `refusal.dispatch`). B-1: later work of a controller-completed stage writes no record (see
        # `record_running`), so its resume is never refused over a write `stage_done.py` refuses by design.
        self.record_running(stage, role, dispatch, retry=lambda: self.resume_role(stage, role, dispatch, words, complete=complete))
        if by_stop:
            prompt = self.question_resume_prompt(dispatch, words)
        else:
            prompt = (f"The person answered: \"{words.strip()}\"\nContinue your dispatch {dispatch} from where "
                      "you stopped, on that answer. Everything the person said is recorded already; do not "
                      "record it again. Your final message is the handoff form only:\n" + HANDOFF_FORM)
        if not sid:
            if by_stop:
                return self.question_rework(stage, role, dispatch, words, complete,
                                            f"no session is known for {dispatch}")
            raise Refusal(f"no session is known for {dispatch}; the role cannot be resumed by the driver",
                          dispatch=dispatch)
        # t-1957 N5s (E5s.6): a walk dispatch whose server is not `ready` gets it reopened BEFORE the words go in, and the words name the
        # reopened session. POSITION INVARIANT: after the `sid` checks (a role that cannot be resumed opens nothing), before the role runs:
        # a resumed walker never holds a dead `W`.
        lane, reopened = self.walk_reopen(dispatch)
        if reopened:
            prompt += "\n" + reopened
        # t-1991 U3b (E3b.5): a resumed S7 triage dispatch whose settle session is not ready gets it reopened BEFORE the words go in; the
        # words name the session or why there is none. An investigation, and every other role, opens nothing.
        triage = self.s7_is_triage(stage, role, dispatch)
        opened = triage and self.s7_settle_session(dispatch, resume=True)
        if triage and (said := self.s7_session_line(dispatch)):
            prompt += "\n" + "\n".join(said)
        self.progress_line()            # t-323 B1: a role is launched again (a resume): where the story stands, as at any launch
        result = {}
        try:
            result = self.run_claude("role", prompt, role=role, dispatch=dispatch, stage=stage, resume=sid,
                                     resume_reason=("the person answered the question the role was stopped on"
                                                    if by_stop else "the person answered what the role stopped for"))
        finally:
            if opened:
                self.s7_settle_close(dispatch)
            if lane:        # E5s.1/E5s.6: the same `after` as `run_role`, before the handoff reads the records
                self.walk_after(lane, dispatch, result)
            else:           # t-2548 F1 (AR-25): a survey session reopened for this resume is closed with the role (a no-op for any other dispatch)
                self.survey_after(dispatch, result)
        if by_stop and result.get("is_error") and not str(result.get("result") or "").strip():
            # The session is gone: the same dispatch goes on in a new one, with the words as its reason.
            return self.question_rework(stage, role, dispatch, words, complete,
                                        f"the session of {dispatch} could not be resumed")
        _write_json(self.state_dir / "driver-runs" / f"{dispatch}.json", result)
        # t-764 A12 (F10): the role answered the words in THIS result - spent before the handoff judges it, so a refusal of that
        # handoff never re-sends them on the next entry (a pop after the threshold was never reached on that road). Only a result that
        # CARRIES words consumed them (t-781 m2): an error with no words answered nothing - `handoff` raises on it and the person's
        # words stay for the next entry (edge 11: they reach the role at least once)
        if str(result.get("result") or "").strip():
            self.state["pending_words"].pop(dispatch, None)
            self.save_state()
        digest = self.handoff(role, stage, dispatch, result)
        import story_step
        if story_step._declared_halt(self.task_root, story_step.FORM_REL.format(dispatch_id=dispatch), digest):   # CX1-14 (B-2): the one reader
            if by_stop:
                stop.pop("resume", None)     # the words went in; the role's own halt asks its own question
            raise Person("halt", self.halt_text(stage, role, digest, again=True), stage, dispatch,
                         details=str(digest or "").strip() or "the role's final message was empty")
        # A role that added questions while it answered is checked like any other handoff: the same
        # count does not stop twice (the person's answer was the informed pass), a larger one does.
        self.question_threshold(stage, role, dispatch)
        self.state["pending_words"].pop(dispatch, None)
        if by_stop:
            stop.pop("resume", None)
        self.save_state()
        self.repair_limit_gate(stage, role, dispatch, digest, recovering=True)     # t-698 A4: before `finish`, after the words are spent
        finished = self.finish(dispatch, digest, complete=complete, role=role, stage=stage)
        self.progress_line()            # t-323 B1: the resumed role returned and its work is recorded
        return finished

    # --- the walk session around a manual lane: code before the walker starts and after it ends (t-1957 N5s, spec 3.5; E5s.1-E5s.9) ---------
    # state key `walk_retry`: {case: {"refused": n, "open": bool, "reason": text}} - a build the walk refused is walked ONCE more

    def walk_before(self, lane: list, dispatch: str, assigned=None) -> dict:
        """Before the walker of `lane` starts (spec 3.5): `work/run-report.json` (else `finalize_task.py` over what is on disk, F30/F31), the app
        card (`app_card.py build` rebuilds only when its inputs changed), then `walk_session.py open` for the lane's account. Returns
        `{"walking": bool, "report_last": bool}`. E5s.3: no report and none can be made -> `report_last` (the brief names `finalize_task.py`
        as the walker's last command - its Stop is never refused for a file it cannot make). E5s.4: `open` fails (exit 3), the account cannot
        be named, or anything here raises -> `walking` False, the dead record is removed (no walk record), and the lane runs on today's road
        (FR-57: nothing locks the role). POSITION INVARIANT: runs after the dispatch is registered and before the role starts, so the brief
        the role reads is written with the walk record in place."""
        out = {"walking": False, "report_last": False}
        why = ""
        try:
            report = self.task_root / "work" / "run-report.json"
            if not report.is_file():
                code, text = self.py("finalize_task.py", str(self.task_root))
                if code or not report.is_file():
                    out["report_last"] = True
                    print(f"S6: {dispatch}: there is no run-report.json and finalize_task.py could not make one (exit {code}); "
                          "the walker's last command is finalize_task.py")
            # remains: the card is a courtesy; a failed build is the printed last line, and the walker reads whatever card exists (P1)
            _code, line = self.py("app_card.py", "build", "--task-root", str(self.task_root))
            print(f"S6: {(line.splitlines() or ['app-card: no answer'])[-1]}")
            key = lane_keys(self.task_root, lane).get(lane[0])
            actors: list = []
            if key is None:
                why = f"the accounts of {lane[0]} could not be read from its request"
            elif assigned:
                # TR3-10d item 3: the assigned handles in the key's order; a guest or `obtain:` handle opens as `guest`, an `env:U/S` handle
                # passes as is (the real gate is `sign_in_refusal`). Without an assignment (walkers 1, one lane) the code below is today's.
                import walk_pool as WP
                import walk_session as WS
                actors = list(dict.fromkeys(WP.open_as(handle) for handle in assigned.values()))
                limit = int(WS.data()["max_actors"])
                if not actors or len(actors) > limit:
                    actors, why = [], f"the lane names {len(actors)} accounts ({key}); a walk holds at most {limit}"
            elif key == "":
                actors = ["guest"]
            else:
                actors, why = self.walk_actors(lane[0], key)
            if not why:
                code, text = self.py("walk_session.py", "open", "--task-root", str(self.task_root), "--walk", dispatch,
                                     "--items", ",".join(lane), "--actor", actors[0], *(["--actor2", actors[1]] if len(actors) > 1 else []),
                                     # t-2147 C1 item 4(d): on the parallel road (a chain) the session may share the stand with the other walkers
                                     *(["--max-shared", str(self.s6_walkers_cap())] if self.on_chain() else []))
                out["walking"] = code == 0
                why = "" if code == 0 else (text.splitlines() or [f"exit {code}"])[-1][:300]
                if code == 0:       # TR1-4: a lane that walks leaves the old-road list (an earlier mark would keep it out of the medians)
                    for case in lane:
                        (self.state.get("walk_old_road") or {}).pop(case, None)
        except Exception as exc:        # P1: code informs, it never stops the factory
            why = f"{type(exc).__name__}: {' '.join(str(exc).split())[:200]}"
        if not out["walking"]:
            try:
                (self.task_root / "state" / "walks" / f"{dispatch}.json").unlink()
            except OSError:
                pass
            self.walk_settle_unopened(dispatch)     # TR3-10d R1: the records assigned to this lane's walk have an exit (dirty), never held forever
            print(f"S6: {dispatch}: no walk session ({why}); the lane is walked on the recorder, as before")
            # t-2016 F5: an item that left the walker is marked, so a figure taken from the old road never joins a walker's median
            self.state.setdefault("walk_old_road", {}).update({case: why[:200] for case in lane})
        return out

    def walk_actors(self, case: str, key: str) -> tuple:
        """`([handle, ...], why)` for the account set `key` of a lane (`lane_keys`), at most `walk_session.data()['max_actors']` handles in
        the key's order: ONE account is `manual_capture.auto_actor`'s (its refusals and doors, unchanged); two are each resolved like
        `auto_actor` resolves its one - a `stand_account` role whose note names two keys, or `default` - so `--actor` and `--actor2` are
        the lane's two accounts (the walker acts as either with `--as`). `why` is non-empty when the lane cannot walk: more accounts than
        a walk holds, or an account a machine cannot sign in as (today's road, with the reason). t-2174 TR3-10d (AR-15): the body is
        `walk_pool.lane_handles`, the one copy the pool reads too."""
        import walk_pool as WP
        return WP.lane_handles(self.task_root, case, key)

    def walk_env_pair(self, stand, value: str) -> tuple:
        """`(role, why)` for an account named by ONE key `value` (the login key of `env:<key>`), TR1-4: `walk_pool.walk_env_pair`, the one
        copy (TR3-10d, AR-15). ERROR DIRECTION: a doubt is never another account."""
        import walk_pool as WP
        return WP.walk_env_pair(stand, value)

    def walk_settle_unopened(self, dispatch: str, state: str = "dirty") -> None:
        """TR3-10d R1 (AR-25: a held row always has an exit): the records `walk_pool.assign_entities` held for the walk `dispatch` go to
        `state` (`dirty`: the lane may have run on the recorder) when that walk never opened; a walk with a record is not touched
        (`walk_session.settle_unopened`, the one writer). Never raises (P1): a failure is one printed note."""
        try:
            import walk_session as WS
            _moved, problem = WS.settle_unopened(self.task_root, dispatch, state)
            if problem:
                print(f"note: {problem}")
        except Exception as exc:  # noqa: BLE001 - settling never stops a lane
            print(f"note: the records held for walk {dispatch} were not settled ({type(exc).__name__})")

    def walk_next_id(self, dispatches, start: int, avoid=()) -> str:
        """TR3-10d L1: the first `S6-qa-runner-<n>` from `n = start` that no controller dispatch carries and that is not in `avoid` (the ids other
        lanes reserved). The one chooser: `walk_assign_step` reserves with it and `run_manual_lane` takes the first free number with it."""
        taken = {str(k) for k in dispatches or ()} | {str(v.get("id")) for v in (dispatches or {}).values() if isinstance(v, dict)} | {str(a) for a in avoid}
        number = max(1, int(start))
        while f"S6-qa-runner-{number}" in taken:
            number += 1
        return f"S6-qa-runner-{number}"

    def walk_lane_facts(self, lane) -> dict:
        """TR3-10d (AR-13: the one reader of this entry's assignment): `{"n": the lane's number or None, "handles": {part: handle} - only when
        EVERY part of the lane's key has one (else {}: today's key-based holds and actor, L3), "entries": {item: [entry]}, "id": the walk id
        reserved for the lane or ""}`. Reads the state `walk_assign_step` wrote; an absent or odd key reads as no assignment (FR-59)."""
        out: dict = {"n": None, "handles": {}, "entries": {}, "id": ""}
        cases = [str(c) for c in lane or ()]
        number = (self.state.get("walk_assign_cases") or {}).get(cases[0]) if cases else None
        if not isinstance(number, int) or isinstance(number, bool):
            return out
        name = str(number)
        out["n"] = number
        handles = (self.state.get("walk_assign") or {}).get(name)
        if isinstance(handles, dict) and handles and all(isinstance(h, str) and h for h in handles.values()):
            out["handles"] = dict(handles)
        entries = (self.state.get("walk_entities") or {}).get(name)
        if isinstance(entries, dict):
            out["entries"] = entries
        reserved = (self.state.get("walk_ids") or {}).get(name)
        out["id"] = reserved if isinstance(reserved, str) else ""
        return out

    def walk_account_gap(self, lane: list) -> str:
        """The reason a lane cannot walk for its ACCOUNTS, else "" (TR1-4, B5: ONE road for every shape of the key; the old road is for a
        failed `walk_session.py open` only). It reads `walk_actors`, the one reader `walk_before` opens the session by, so the lane is
        refused here exactly when it could not open there. An empty key is a guest (walkable); a request that cannot be read, or a
        reader that fails, is a reason too (FR-59: an unknown is never a pass). The text carries no flag or command (P9)."""
        case = lane[0]
        try:
            key = lane_keys(self.task_root, lane).get(case)
            if key is None:
                return f"the accounts of {case} could not be read from its request"
            if key == "":
                return ""
            return self.walk_actors(case, key)[1]
        except ValueError:
            return f"the account of {case} is not one a machine can sign in as"
        except Exception as exc:
            return f"the accounts of {case} could not be established ({type(exc).__name__})"

    def refuse_case(self, plan, case: str, reason: str, door: str, by: str, by_first: bool = False) -> bool:
        """TR4-3 (AR-14, AR-15): the ONE writer of `{"refused": {reason, door, by}}` in a case's request.json - the refusal a later reader
        (the report, gate B, the delivery check) finds. With a `plan` the case also joins `plan["refused"]` as `(case, reason)`; `manual_close`
        has no plan (its list is local) and passes None. A write that fails is swallowed: the caller's printed line still names the case and
        the receipt still carries it. Nothing is checked here: an empty `door` or `by` and a case outside the plan are written as given, as
        every caller did before. Returns True when the record was written, False when the write failed (`deferred_decision` says so). `by_first` keeps the key order of the one caller that wrote `by` before `door` (byte-equal records)."""
        import manual_evidence as ME
        if plan is not None:
            plan["refused"].append((case, reason))
        record = {"reason": reason, "by": by, "door": door} if by_first else {"reason": reason, "door": door, "by": by}
        try:
            _write_json(ME.request_path(self.task_root, case), {"refused": record})
        except OSError:
            return False        # the caller's printed line still names the case; a caller that must say it reads the False
        return True

    def walk_refuse_gaps(self, plan: dict) -> None:
        """TR1-4: lanes of `plan["blocks"]` whose account has no pair are NOT walked on the old road: each case is refused `not walked:
        <reason>` (request, `plan["refused"]`, printed), one finding per lane is filed, and the run goes on to the next lane with no
        question. POSITION INVARIANT: before the dispatch of the first lane is registered, so a lane that cannot walk costs no role.

        TR3-10d D3b-2 (item 13, trigger (i) `no_pair`; AR-25, AR-24): where the gap is a ROLE the stand records no pair for, the cases are closed
        exactly as before (the finding unchanged: before an answer the behaviour is today's) and, AFTER the loop, the account question of that
        role is raised (`walk_account_raise`, one per role); it holds the tied cases, so it waits like any case question. It applies at
        `walkers` 1 too (D.5): the one place of Part D that does. The role is read BEFORE the cases are closed (a closed case's request no
        longer carries its key)."""
        kept, asking = [], {}
        for lane in plan["blocks"]:
            why = self.walk_account_gap(lane)
            if not why:
                kept.append(lane)
                continue
            role = self.walk_gap_role(lane) if "no_pair" in WALK_ACCOUNT_TRIGGERS else ""
            if role:
                asking.setdefault(role, []).extend(case for case in lane if case not in asking.get(role, []))
            reason = f"not walked: {why}"
            door = ("record the account's two keys on the stand (credentials_by_role: `<role>: <login key> / <password key>`), "
                    "or check the case yourself")
            for case in lane:
                self.refuse_case(plan, case, reason, door, "left_unchecked", by_first=True)
                print(f"S6: {case}: {reason}")
            self.owe_row("project_decisions.py", "--root", str(self.project), "add-finding",
                         "--essence", f"S6 lane of {', '.join(lane)} not walked: {why}"[:500], "--scope", "local-calibration",
                         "--witness", f"walk lane {lane[0]}", "--idempotency-key", f"walk-account-gap:{self.task}:{lane[0]}",
                         what="the finding about a lane whose account has no pair", stage="S6")
        plan["blocks"] = kept
        if asking:
            self.walk_account_raise(asking)

    def walk_gap_role(self, lane: list) -> str:
        """The ROLE a lane that cannot walk lacks a pair for, else "" (trigger (i) `no_pair`; no guess). Only a one-part key `stand_account:
        <role>` names one; a guest, `env:`, a many-account key, the reserved role `default`, a key that cannot be read, a role the stand
        already records with a pair (the gap is then something else) and any failure are "" - today's close, no question. ERROR DIRECTION:
        a doubt asks nothing."""
        try:
            import config_contract as CC
            import gate_preflight as GP
            import manual_capture as MC
            key = lane_keys(self.task_root, lane).get(lane[0])
            parts = [part for part in key.split("+") if part] if isinstance(key, str) else []
            if len(parts) != 1 or not parts[0].startswith("stand_account:"):
                return ""
            role = parts[0].partition(":")[2].strip()
            if not role or CC.reserved_role(role):
                return ""
            try:
                cfg = MC.load_config(self.task_root)[0]
            except ValueError:
                cfg = {}
            stand = next((e for e in (cfg.get("environments") if isinstance(cfg, dict) else None) or [] if isinstance(e, dict)), {})
            roles = stand.get("credentials_by_role")
            real = GP.account_role(roles, role) if isinstance(roles, dict) else None
            if real is not None and len(GP.account_keys(roles[real])) == 2:
                return ""
            return role
        except Exception:       # noqa: BLE001 - a doubt asks nothing: the lane closes as it always did
            return ""

    def walk_account_raise(self, asking: dict) -> None:
        """TR3-10d D3b-2 (spec item 13; D.5, D.11): ONE `walk_account` question per role of `asking` (`{role: [tied cases]}`), after the
        cases were closed. The row: `walk_ask_once` with the role's pointer `/environments/<stand>/credentials_by_role/<role>` (the pointer
        `project_decisions.py stand-account` writes, so the conductor's `stand-account` reuses this open row and resolves it; FR-7). NOT asked
        again: a role already in `walk_account_asked` / `walk_account_roles` (this story), or one whose cases a deferred `walk_account` item
        holds. An `add` that fails, a stand the registry cannot name or a builder that refuses (a role with a space, non-ASCII) is ONE
        note and today's close: the cases were closed before this runs, so none is left without an outcome. Every question but the last
        is set aside (`defer_question`); the last is raised - or the first that `deferrable` says must be asked at once, the rest unasked
        (their records dropped). INVARIANT: before any answer the behaviour is today's."""
        import manual_capture as MC
        try:
            index = project_decisions._stand_of(MC.load_config(self.task_root)[0])[0]
        except ValueError as exc:
            print(f"note: S6: the account question was not raised ({' '.join(str(exc).split())[:200]}); the checks stay unchecked", flush=True)
            return
        held, seen = self.state.get("walk_account_asked"), self.state.get("walk_account_roles")
        held, seen = held if isinstance(held, dict) else {}, seen if isinstance(seen, dict) else {}
        waiting = {str(case) for item in self.deferred_items() if item.get("kind") == "walk_account" for case in item.get("holds") or []}
        owed = []
        for role, cases in asking.items():
            if role in seen or any(isinstance(v, dict) and v.get("role") == role for v in held.values()) or waiting & set(cases):
                continue
            lines = self.case_lines(cases)
            if not role or not str(role).isascii() or any(ch.isspace() for ch in str(role)):
                # N4: the role is checked BEFORE the registry row is opened - an unaskable role leaves no open row; the same note as
                # below, the same close (the refusal text itself stays in `walk_account_person`, which checks again at the build)
                print(f"note: S6: the question about the {role} account was not raised (walk_account: the role {role!r} cannot be named as "
                      "an account key (it is empty, has a space or a non-ASCII character); the account question was not raised); "
                      "its checks stay unchecked", flush=True)
                continue
            try:
                # remains: the closed question of the person's own account is built by design (item 13), not a state with no move; its executor is `_answer_walk_account`
                build = lambda row, role=role, cases=cases, lines=lines: self.walk_account_person(row, role, cases, lines)
                # remains: the closed question of the person's own account is raised by design (item 13), not a state with no move; its executor is `_answer_walk_account`
                person = self.walk_ask_once(
                    "walk_account", [f"/environments/{index}/credentials_by_role/{project_decisions._ptr(role)}"],
                    f"the account of the role {role} on the stand",
                    str(self.walk_account_text(role, cases, lines)), build)
            except Person:
                raise
            except Exception as exc:    # noqa: BLE001 - D.11: the raise informs, it never stops S6; the cases are already closed
                print(f"note: S6: the question about the {role} account was not raised ({' '.join(str(exc).split())[:200]}); "
                      "its checks stay unchecked", flush=True)
                continue
            if person is not None:
                owed.append((role, person))
        for at, (role, person) in enumerate(owed):
            if at == len(owed) - 1 or not self.deferrable(person):
                for later, _person in owed[at + 1:]:
                    self.state["walk_account_asked"] = {k: v for k, v in self.state["walk_account_asked"].items() if v.get("role") != later}
                    self.state["walk_account_roles"].pop(later, None)
                self.save_state()
                raise person
            self.defer_question(person)

    def walk_reopen(self, dispatch: str, reopen: bool = True) -> tuple:
        """`(items, words)` for a RESUMED dispatch (E5s.6): `items` are the walk's items (`[]` = this is no walk dispatch); `words` is the line
        the resume prompt adds - the walk session reopened (`walk_session.py open`, same walk, same actors; items with a verdict are kept by
        the server), or why it could not be. A server that is `ready` and alive is left alone and `words` is empty. `reopen=False` (a saved
        result stands, so no role will run): the items only, nothing opened (t-2022 N7: a browser, a sign-in and the lease for no role)."""
        record = _read_json(self.task_root / "state" / "walks" / f"{dispatch}.json")
        place = str(record.get("place") or "case") if isinstance(record, dict) else "case"
        if place == "survey":
            # t-2277 batch 2b D (critic t-2513 F2): the survey walk of an optional dispatch (S1 reference window, S3 first look) is no case walk
            # (no items come back, so no case lane is built over it) but the resumed role gets its session back, on the stand the record names.
            # B1 (critic t-2548): a record that never reached `ready` (`open_walk` stamps it `did not start: ...`) is a walk that never began -
            # no session to give back, and the packet of a failed window says "walk nothing" already (FR-10): nothing is reopened, nothing is said
            if str(record.get("state") or "") != "ready" and str(record.get("reason") or "").startswith("did not start"):
                return [], ""
            return [], (self._survey_reopen(dispatch, record) if reopen else "")
        if place != "case":
            return [], ""       # t-2027 F1: a settle or control session's record (place ids as items) is no case walk; `s7_settle_session` reopens its own
        items = [str(i) for i in record.get("items") or [] if str(i).strip()] if isinstance(record, dict) else []
        if not items or not reopen:
            return items, ""
        try:
            shared = int(record.get("max_shared") or 1)      # F4: a record without the field reads 1 (old records, C.12)
        except (TypeError, ValueError):
            shared = 1
        return items, self._walk_reopen_open(dispatch, record, ["--items", ",".join(items)], ["--max-shared", str(shared)] if shared > 1 else [],
                                             said="S6: {d}: the walk session", unwalked="which items you did not walk",
                                             kept="items with a verdict are done; continue with the next.")[0]

    def _walk_reopen_open(self, dispatch: str, record: dict, head: list, tail: list, *, said: str, unwalked: str, kept: str,
                          where: str = "", cannot: str = "") -> tuple:
        """`(line, opened)`: the COMMON body of a walk reopen (critic t-2548 F4), for the case lane (`walk_reopen`) and the survey walk
        (`_survey_reopen`). `""` when the record's server is `ready` and alive; else `walk_session.py open` over the walk's own id with `head`
        (what names the walk: items, place, stand) and `tail` (flags after the actors), the actors of the record (`guest` when it names none),
        and the line the role is told: the failure (`cannot` is a reason known before any call: the open is not made, FR-41) or the reopened
        session (`where` names a stand, `kept` what stays). `said` is the printed line's start (`{d}` = the dispatch). `opened` is True only
        when the session was opened by THIS call. Never raises."""
        try:
            import walk_session as WS
            alive = record.get("state") == "ready" and WS.alive(record)
        except Exception:
            alive = record.get("state") == "ready"
        if alive:
            return "", False
        said = said.format(d=dispatch)
        text, code = "", 0
        if not cannot:
            actors = [str(a) for a in record.get("actors") or [] if str(a).strip()] or ["guest"]
            argv = ["open", "--task-root", str(self.task_root), "--walk", dispatch, *head, "--actor", actors[0],
                    *(["--actor2", actors[1]] if len(actors) > 1 else []), *tail]
            code, text = self.py("walk_session.py", *argv)
        if cannot or code:
            why = cannot or (text.splitlines() or [f"exit {code}"])[-1][:300]
            print(f"{said} could not be reopened ({why})")
            return (f"Your walk session could not be reopened ({why}); its commands will be refused. Stop here and say {unwalked}."), False
        got = _read_answer(text) or {}      # exit 0 and no answer: the sentence below says "not signed in" and lands on the landing page (a hint only)
        signed = "signed in" if got.get("signed_in") else "not signed in"
        print(f"{said} was reopened")
        return (f"Your walk session was reopened{where} ({signed}, landed on {got.get('landed_on') or 'the landing page'}); {kept}"), True

    def _survey_reopen(self, dispatch: str, record: dict) -> str:
        """The line a resumed role of a SURVEY walk is told (`walk_reopen`, t-2277 batch 2b D), or "" when the server is `ready` and alive.
        The walk is opened again as it was (same walk id, place `survey`, the stand and the actors of the record; the items the walk
        already recorded stay on disk). A record that does not name its stand (the server died before it wrote one) cannot be opened on
        a guess: the line says so and the role is told to stop and say what it did not walk (FR-41, AR-28). A session this call opened is
        remembered (`survey_reopened`): the role's end closes it (`survey_after`, AR-25). Never raises."""
        stand = str(record.get("stand") or "").strip()
        items = [str(i) for i in record.get("items") or [] if str(i).strip()] or ["free"]
        line, opened = self._walk_reopen_open(dispatch, record, ["--place", "survey", "--env", stand, "--items", ",".join(items)], [],
                                              said="{d}: the survey walk session", unwalked="what you did not walk",
                                              kept="what you already captured is kept; continue where you stopped.",
                                              where=f" on `{stand}`", cannot="" if stand else "its record names no stand")
        if opened:
            once_on(self, "survey_reopened", set).add(dispatch)
        return line

    def survey_after(self, dispatch: str, result=None) -> None:
        """The close of a survey session this driver REOPENED for a resumed role (critic t-2548 F1, AR-25): `walk_session.py close`, as
        `walk_after` does for a lane, so the stand lease (a `survey` session holds it in walk mode, up to `idle_s`) is let go when the role
        ends. A dispatch whose session was not reopened here is left alone. Never raises: a failure is a printed note."""
        opened = once_on(self, "survey_reopened", set)
        if dispatch not in opened:
            return
        opened.discard(dispatch)
        try:
            # remains: the exit is read on the next line and said; a server that did not close ends by itself (idle/max/parent watchdog)
            code, text = self.py("walk_session.py", "close", "--task-root", str(self.task_root), "--walk", dispatch)
            if code:
                print(f"note: walk_session.py close exit {code}: {(text.splitlines() or [''])[-1][:200]}; the server ends by itself")
        except Exception as exc:
            print(f"note: walk_session.py close raised {type(exc).__name__}; the server ends by itself")

    def walk_pending(self, lane: list) -> bool:
        """True when a case of `lane` was refused by the build of its record (`walk_after`): it is walked once more in a lane of the next
        entry, or closed `left_unchecked` after a second refusal. Either way the lane that carried it never closes the stage (E5s.1)."""
        retry = self.state.get("walk_retry") or {}
        return any(isinstance(retry.get(case), dict) and (retry[case].get("open") or retry[case].get("refused", 0) > 1) for case in lane)

    def walk_after(self, lane: list, dispatch: str, result) -> None:
        """After the walker of `lane` is over (spec 3.5; `run_role` and `resume_role` call it through `after=`, BEFORE `bind`, `handoff` and
        `finish`): `walk_session.py close`; per item `manual_evidence.record_from_walk` over its result record (a walker that ended with no
        verdict gets `walk_session.write_verdict(..., None)`: every Then `inconclusive`, E5s.2); `finalize_task.py`; the form's values
        `work/handoffs/<dispatch>.values.yaml`; the timing end line. A build the record refuses is re-queued ONCE (`walk_retry`, read by
        `manual_plan`), the second refusal writes the case's request as refused `left_unchecked` (the `manual_close` road). IDEMPOTENT: the
        items already handled stand in `work/walks/<W>/after.json` and are skipped, so a reused saved result runs it safely. Never raises
        (P1): a failure is a printed note and the lane goes on to the checks that follow."""
        T = self.task_root
        try:
            # remains: the exit is read on the next line and said; a server that did not close ends by itself (idle/max/parent watchdog)
            code, text = self.py("walk_session.py", "close", "--task-root", str(T), "--walk", dispatch)
            if code:
                print(f"note: walk_session.py close exit {code}: {(text.splitlines() or [''])[-1][:200]}; the server ends by itself")
        except Exception as exc:
            print(f"note: walk_session.py close raised {type(exc).__name__}; the server ends by itself")
        rows: dict = {}
        try:
            self.walk_case_records(lane, dispatch, rows)
        except Exception as exc:
            print(f"note: the records of walk {dispatch} were not all built ({type(exc).__name__}: {' '.join(str(exc).split())[:200]})")
        try:
            # TR3-10d item 5 (D.9, AR-25): a lane that took `obtain:<role>#n` and left no confirmed user of its cases behind. Every case of it
            # WITHOUT a verdict is re-queued as ONE refusal (a second one closes it `left_unchecked` by the rule of `walk_refusal`), and the role
            # gets no obtain lane for the rest of the story (`walk_assign_step` reads `obtain_failed`): no sign-up loop. A case that has a
            # verdict stands. An obtain lane whose user WAS confirmed changes nothing. IDEMPOTENT: a re-queued case is `refused` in `rows`.
            import manual_capture as MC
            obtain = [str(h) for h in self.walk_lane_facts(lane)["handles"].values() if str(h).startswith("obtain:")]
            names = _read_json(MC.created_names_path(T)) if obtain and MC.created_names_path(T).is_file() else {}
            made = [r for r in (names.get("accounts") if isinstance(names, dict) else None) or [] if isinstance(r, dict)]
            if obtain and not any(r.get("case") in lane and not r.get("status") for r in made):
                retry = self.state.setdefault("walk_retry", {})
                for case in lane:
                    row = rows.get(case)
                    if isinstance(row, dict) and row.get("missing") and row.get("state") != "refused":
                        rows[case] = {**self.walk_refusal(case, "its walker could not get an account: the sign-up was not seen to land", retry),
                                      "missing": True}
                _write_json(T / "work" / "walks" / dispatch / "after.json", {"rows": rows})
                failed = self.state.setdefault("obtain_failed", {})
                for handle in obtain:
                    failed[handle[len("obtain:"):].rsplit("#", 1)[0]] = True
                self.save_state()
        except Exception as exc:
            print(f"note: the sign-up of walk {dispatch} could not be checked ({type(exc).__name__}: {' '.join(str(exc).split())[:200]})")
        try:
            # remains: the exit is read on the next line and said; the handoff check after the role refuses a form over a missing report (P1)
            code, text = self.py("finalize_task.py", str(T))
            if code:
                print(f"note: finalize_task.py exit {code}: {(text.splitlines() or [''])[-1][:200]}")
            self.walk_values(dispatch, rows)
            timing = T / "work" / "walks" / dispatch / "timing.jsonl"
            kept = []
            if timing.is_file():
                for line in timing.read_text(encoding="utf-8").splitlines():
                    try:
                        if line.strip() and "after_end" not in json.loads(line):
                            kept.append(line)
                    except ValueError:
                        kept.append(line)       # a broken line is `walk_timing`'s to count and name (FR-41), not ours to drop
            timing.parent.mkdir(parents=True, exist_ok=True)
            import event_store      # Q-new-2: the rewrite is published whole (a reader of the timing never sees a torn file)
            body = "".join(line + "\n" for line in [*kept, json.dumps({"after_end": _now()})])
            try:
                event_store.atomic_text(timing, body)
            except OSError as exc:       # a reader held it past the retries: the write that worked before, with a note (as `_write_json`)
                print(f"note: {timing.name} could not be published atomically ({type(exc).__name__}); it is written in place", flush=True)
                timing.write_text(body, encoding="utf-8", newline="\n")
        except Exception as exc:
            print(f"note: the walk's closing steps did not all run ({type(exc).__name__}: {' '.join(str(exc).split())[:200]})")

    def walk_case_records(self, lane: list, dispatch: str, rows: dict) -> None:
        """The case record of every item of `lane` that has none yet, into `rows` (the state of `work/walks/<W>/after.json`, written after each
        item). An item with no result record gets one for a MISSING verdict (`write_verdict(..., None)`, marked `missing_verdict`). IDEMPOTENT
        and a resume's friend (t-2016 F4): an item stays handled once built, EXCEPT one handled for a missing verdict whose result record is a
        real verdict now (the walker went on after a halt or a cut): that one is built again, its refusal count from the missing verdict
        forgotten. A build the record refuses is re-queued ONCE (`walk_retry`, read by `manual_plan`); the second refusal writes the
        case's request as refused `left_unchecked` (the `manual_close` road)."""
        T = self.task_root
        import manual_capture as MC
        import manual_evidence as ME
        import walk_session as WS
        marker_path = T / "work" / "walks" / dispatch / "after.json"
        marker = _read_json(marker_path)
        rows.update(marker["rows"] if isinstance(marker.get("rows"), dict) else {})
        retry = self.state.setdefault("walk_retry", {})
        for case in lane:
            found = T / "work" / "walks" / dispatch / f"{MC.case_dir_name(case)}.json"
            walk_record = _read_json(found) if found.is_file() else {}
            missing = not walk_record or bool(walk_record.get("missing_verdict"))
            prior = rows.get(case)
            if isinstance(prior, dict) and not (prior.get("missing") and not missing):
                continue
            if isinstance(prior, dict):
                retry.pop(case, None)
            try:
                if not walk_record:
                    walk_record = WS.write_verdict(T, dispatch, case, None)
                built = ME.record_from_walk(T, case, walk_record)
            except Exception as exc:
                built = {"refused": f"{type(exc).__name__}: {' '.join(str(exc).split())[:300]}"}
            if built.get("refused"):
                rows[case] = {**self.walk_refusal(case, str(built["refused"]), retry), "missing": missing}
            else:
                if isinstance(retry.get(case), dict):
                    retry[case]["open"] = False
                word = "unprepared_walk" if built.get("unprepared") else {"pass": "passed", "fail": "failed"}.get(str(built.get("result")), "inconclusive")
                rows[case] = {"state": word, "block": built.get("block"), "evidence": list(built.get("evidence") or []), "missing": missing}
            _write_json(marker_path, {"rows": rows})
            self.save_state()

    def walk_refusal(self, case: str, refused: str, retry: dict) -> dict:
        """Count a build refusal of `case` in `retry` and say it: the first is walked once more, the second closes the case `left_unchecked`.
        Returns its row of `after.json`."""
        entry = retry.get(case) if isinstance(retry.get(case), dict) else {"refused": 0}
        entry = {"refused": int(entry.get("refused") or 0) + 1, "reason": refused[:400]}
        entry["open"] = entry["refused"] == 1
        retry[case] = entry
        if entry["open"]:
            print(f"S6: {case}: the record of its walk was refused ({entry['reason']}); it is walked once more in the next lane")
        else:
            reason = f"not checked by hand: the record of its walk was refused twice - {entry['reason']}"
            self.refuse_case(None, case, reason, "walk the case again after the build is fixed (retry at gate B), or check it yourself",
                             "left_unchecked", by_first=True)
            print(f"S6: {case}: {reason}")
        return {"state": "refused", "reason": entry["reason"], "n": entry["refused"]}

    def walk_values(self, dispatch: str, rows: dict) -> None:
        """`work/handoffs/<dispatch>.values.yaml`: EVERY required field of the form that code owns (a flat `path: value` JSON object, the one
        `handoff_check.py` applies and renames), so the lane does not pay a resume for a form (t-2016 F3). Words of the records only (P27):
        `header.verdict` is `ok` when every case stood and `concerns` otherwise; `header.window` the lane's cases; `run.*` from the stand
        probes of the attempts and the run report; per case a `scope[]` row (its obligations from its request) and, for a built record, a
        `manual_observations[]` row carrying the Thens verbatim from `request.json` and the record's own `actual`, `before_change` and
        `surprises`; the claims code can count; one `tried[]` row from the walk's own figures. A value code cannot know is a named gap (`-`,
        or words that say it was not established), never an invented one (FR-41): the `run.witness` count comes from the records (a
        case with no recorder step was not walked); `scope[].executed` is `none` for a case that did not run. Written when the form is there and no values file was
        applied to it already - or when one was and the rows have changed since (a late verdict rebuilt a record: the form must say what the
        record says, t-2022 N9; `handoff_check --fix` applies the waiting file over the old words); a refused case is a `manual_skipped`
        row with its reason."""
        T = self.task_root
        form = T / "work" / "handoffs" / f"{dispatch}.yaml"
        if not form.is_file() or not rows:
            return
        values = {"header.verdict": "ok" if all(r.get("state") == "passed" for r in rows.values()) else "concerns",
                  "header.window": ", ".join(rows)}
        built = [(case, row) for case, row in rows.items() if row.get("state") != "refused"]
        facts = {case: self.walk_facts(case, row) for case, row in built}
        values.update(self.walk_run_values(dispatch, rows, facts))
        for at, (case, row) in enumerate(rows.items()):
            state = row.get("state")
            values[f"scope[{at}].id"] = case
            values[f"scope[{at}].case"] = case
            values[f"scope[{at}].state"] = "manual_skipped" if state == "refused" else state
            values[f"scope[{at}].reason"] = (f"walked: {state}" if state != "refused" else str(row.get("reason") or f"record refused {row.get('n')}x"))[:80]
            values[f"scope[{at}].evidence"] = row.get("block") or f"work/evidence/manual/{case}/request.json"
            values[f"scope[{at}].obligations"] = ", ".join(facts.get(case, {}).get("obligations") or []) or "-"
            # t-2022 N8: `none` = nothing ran for this row (a refused or never-walked case); it is no evidence, the row's `state` and `evidence` say so
            values[f"scope[{at}].executed"] = "fresh" if facts.get(case, {}).get("steps") else "none"
        for at, (case, row) in enumerate(built):
            fact = facts[case]
            values[f"manual_observations[{at}].case"] = case
            values[f"manual_observations[{at}].then"] = fact["then"]
            values[f"manual_observations[{at}].observed"] = fact["actual"]
            values[f"manual_observations[{at}].before_change"] = fact["before_change"]
            values[f"manual_observations[{at}].result"] = {"passed": "passed", "failed": "failed"}.get(row.get("state"), "inconclusive")
            values[f"manual_observations[{at}].evidence"] = row.get("block") or ""
            values[f"manual_observations[{at}].surprises"] = fact["surprises"]
        text = json.dumps(values, indent=1)
        applied = form.with_name(f"{dispatch}.values.applied.yaml")
        if applied.is_file() and applied.read_text(encoding="utf-8", errors="replace") == text:
            return          # the words the form already holds: nothing changed since they were applied
        form.with_name(f"{dispatch}.values.yaml").write_text(text, encoding="utf-8", newline="\n")

    def walk_facts(self, case: str, row: dict) -> dict:
        """What the built record of `case` says, read from its files: `then` (the Thens of its request, verbatim), `actual`, `before_change`,
        `surprises`, `obligations`, the stand identity of its probes (`environment`, `build`, `probes` = the probes file) and its `steps`. A
        word the files do not hold is a gap in words, never a guess."""
        import manual_capture as MC
        T = self.task_root
        folder = (T / str(row["evidence"][0])).parent if row.get("evidence") else None
        record = _read_json(folder / "record.json") if folder is not None and (folder / "record.json").is_file() else {}
        request = _read_json(MC.case_root(T, case) / "request.json")
        thens = request.get("thens") if isinstance(request.get("thens"), dict) else {}
        start = next((p.get("probe") or {} for p in (MC.jsonl_rows(folder / "probes.jsonl") if folder is not None else []) if p.get("when") == "start"), {})
        change = record.get("before_change")
        surprises = record.get("surprises") if isinstance(record.get("surprises"), list) else []
        ids = ", ".join(str(s.get("id")) for s in surprises[:30] if isinstance(s, dict))
        return {"then": "; ".join(f"{n}. {thens[n]}" for n in sorted(thens, key=lambda k: int(k) if str(k).isdigit() else 0)) or f"no Then is listed in the request of {case}",
                "actual": str(record.get("actual") or "").strip() or "the record holds no `actual`",
                "before_change": json.dumps(change, sort_keys=True) if change is not None else "not_recorded: the record holds no before_change",
                "surprises": f"{len(surprises)} line(s), surprise_detection {record.get('surprise_detection') or 'not recorded'}" + (f"; ids {ids}" if ids else ""),
                "obligations": [str(o) for o in request.get("obligation_ids") or []],
                "environment": str(start.get("environment_id") or ""), "build": str(start.get("observed_runtime_identity") or ""),
                "probes": (folder / "probes.jsonl").relative_to(T).as_posix() if folder is not None and (folder / "probes.jsonl").is_file() else "",
                "steps": len(MC.jsonl_rows(folder / "steps.jsonl")) if folder is not None else 0}

    def walk_run_values(self, dispatch: str, rows: dict, facts: dict) -> dict:
        """The `run.*`, `inputs_read[]`, `claims.*`, `tried[]` and `superseded` values of a walk's form (see `walk_values`). The run report's
        own figures (`execution_status`, `window_totals`) are derived by `handoff_check --fix`; here is what the report cannot say of a manual lane."""
        T = self.task_root
        first = next(iter(facts.values()), {})
        walked = [case for case, fact in facts.items() if fact["steps"]]          # N8: a case with a recorder step was walked; a refused or empty one was not
        gap = "not established: no case record of this lane was built"
        report = _read_json(T / "work" / "run-report.json")
        provenance = sorted((T / "evidence").glob("runtime-provenance-*.json"))
        return {
            "run.witness": f"no automated run in this dispatch: {len(walked)} of {len(rows)} manual case(s) walked with the walk session {dispatch}",
            "run.environment": first.get("environment") or gap,
            "run.application_build": first.get("build") or gap,
            "run.probe_before": first.get("probes") or gap, "run.probe_after": first.get("probes") or gap,
            "run.totals": json.dumps(report.get("totals"), sort_keys=True) if report.get("totals") else "the report counted no automated test: manual walk only",
            "inputs_read[0].version": "-", "inputs_read[0].instances_handed": "-",
            "inputs_read[1].version": "-", "inputs_read[1].manual_cases_handed": str(len(rows)),
            "inputs_read[2].path": f"evidence/{provenance[-1].name}" if provenance else "-",
            "inputs_read[2].version": first.get("build") or "-",
            "claims.every_row_carries_an_evidence_path": all(bool(r.get("block")) for r in rows.values()),
            "claims.every_blocked_row_names_a_remedy_and_the_probe_line": True,             # a walk's form carries no `env_blocked` row
            "claims.no_comparison_was_fabricated_where_before_evidence_is_missing": True,   # `before_change` is built by code from the register
            "claims.handed_and_manual_human_cases_are_absent_by_design": True,              # a manual block holds manual-agent cases only
            "claims.the_report_was_reduced_by_code_not_written": bool(report),
            "superseded[0].row": "none", "superseded[0].superseded_by": "none",         # a manual lane reran no automated instance: no ghost row
            "tried[0].requirement": ", ".join(rows),
            "tried[0].technique": f"walk session {dispatch}: {sum(f['steps'] for f in facts.values())} recorder step(s) over {len(walked)} walked case(s)",
            "tried[0].observation": "; ".join(f"{case} {row.get('state')}" for case, row in rows.items())[:300],
            "tried[0].evidence": f"work/walks/{dispatch}/timing.jsonl"}

    # --- the question threshold: the stop and the resume (t-113 B2: R15, R16, R17, Q8) ---------------
    QUESTION_ANSWER_BY = "person"     # a value of question-vocabulary.json `by`: the words are the person's

    @staticmethod
    def question_when(at) -> str:
        """`2026-09-30 18:05 UTC`: an instant as a person reads it; anything unreadable as written."""
        text = str(at or "").strip()
        try:
            return datetime.fromisoformat(text).astimezone(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
        except ValueError:
            return text

    @staticmethod
    def larger_than_answered(count, share, answered: dict) -> bool:
        """Q8: the person's answer at a stop is the informed pass for THAT count and THAT share; only a
        strictly larger one is a new fact. An unknown (a share that could not be computed) is never
        larger than anything (FR-41) - it neither stops nor is stopped on."""
        was_count, was_share = answered.get("count"), answered.get("share")
        if isinstance(count, int) and isinstance(was_count, int) and count > was_count:
            return True
        return (isinstance(share, (int, float)) and isinstance(was_share, (int, float)) and share > was_share)

    def question_threshold(self, stage: str, role: str, dispatch: str) -> None:
        """R15: after a role's handoff and before `finish`, count the register's open questions; over
        the limit, stop and ask the WHOLE batch. Raises `Person("questions")` or returns.

        Code only counts and renders (FR-47): the role's own stop is the `halt` road, which has run
        before this point. P1: a failure of the count is printed and the stage goes on - code informs,
        it never stops the factory on its own defect. The stop is recorded in the DRIVER's state, not in
        the role's files (Q8): {stage, dispatch, count, share, at, shown, answered}. A person's word
        passes it (`waiver.py --stage S2|S3|S4 --block "question threshold"`, recorded by the waiver, FR-4).

        HF2-7, the owner's word of 24.10: ONE open question that blocks stops the story whatever the count (`question_stop.
        blocking_stop`). POSITION INVARIANT (M1): the blocking check runs AFTER the applying of the recorded answers and BEFORE any
        early return of the count - not `over`, the count the person answered at, the stage's recorded pass for the COUNT - so none of
        those can hide a blocker; it is held only by `answered.blocking_ids` (`{id: the row's hash the person passed}`, written by
        `go on` alone): a blocker whose row changed since is not the one that was passed (H44). The S4 threshold is the case
        designer's alone (H30): the critic's handoff has no stop and no applying, so the plan does not move under a fresh review."""
        try:
            import question_register as QR
            import question_stop as QS
            where = f"{stage} stop"
            if where not in QR.vocabulary()["where"]:
                return                      # no stop is defined for this stage: the vocabulary says which stages
            if stage == "S4" and role != "qa-case-designer":
                return
            plan_lines = self.apply_question_answers(stage)["plan_lines"]
            found = QS.over_threshold(self.task_root, self.config)
            blocking = QS.blocking_stop(self.task_root)
        except Exception as exc:            # a malformed register, a missing thresholds file: told, not stopped on
            print(f"note: the question threshold was not checked at {stage} ({type(exc).__name__}: {exc}); the stage goes on")
            return
        for warning in found.get("warnings") or []:
            print(f"note: {warning}")
        count, share = found.get("count"), found.get("share")
        earlier = self.state.get("question_stop") or {}
        answered = earlier.get("answered") if isinstance(earlier.get("answered"), dict) else None
        hashes = self.register_hashes()
        blocked = self.blockers_to_stop_on(blocking, answered, hashes)
        count_stop = bool(found.get("over")) and self.count_stop_stands(stage, count, share, answered)
        if not count_stop and not blocked:
            return
        reasons = (["blocking"] if blocked else []) + (["over_threshold"] if count_stop else [])
        options = [
            {"answer": "answers", "says": "answer the questions above, one line each; the role goes on in its own session "
                                          "with your answers", "slots": {"role": f"the {self.role_words(role)}"}},
            {"answer": "go on", "token": "go on", "says": "go on with these questions still open; your word is recorded as the pass"},
            self.STOP_OPTION]
        section = self.priced_section("questions.blocking", options) if blocked else self.priced_section("questions", options)
        try:
            reason = "blocking" if blocked and not count_stop else "over_threshold"
            if blocked and count_stop:          # both stand: the blocking words first, then the count's own lines, one reason
                said = QS.defaults()["reason_words"]
                reason = " ".join([said["blocking"].rstrip(".") + ".", said["over_threshold"].rstrip(".") + ".",
                                   *found["reasons"], *found["warnings"]])
            body = QS.batch_text(self.task_root, reason, priced=section,
                                 previous_answer_at=None if answered is None else self.question_when(answered.get("at")))
            if blocked and count_stop and body.strip():
                body = body.rstrip("\n") + "\n" + QS.BLOCKING_NOTE + "\n"
            text = Priced(body, section.priced)
        except Exception as exc:
            text = ""
            print(f"note: the batch of questions could not be written ({type(exc).__name__}: {exc})")
        if not text.strip():
            print(f"note: {stage} is over the question threshold but there is no open question to show; the stage goes on")
            return
        self.state["question_stop"] = {"stage": stage, "dispatch": dispatch, "count": count, "share": share, "at": _now(),
                                       "shown": hashes, "reasons": reasons,
                                       "blocking_ids_shown": {qid: hashes.get(qid, "") for qid in blocking.get("ids") or []}}
        if answered is not None:
            self.state["question_stop"]["answered"] = answered
        if plan_lines:
            self.state.setdefault("question_pass_lines", {})[dispatch] = plan_lines      # H36: the resumed role is told what code changed
        self.state["pending_words"].pop(dispatch, None)      # a stale answer must not resume a NEW question
        self.save_state()
        # T1 (C1-7b): the Person is raised either way; a later running/done write supersedes the record, and a retry after a resume
        # would write a stale halt. F-4 (t-1252): NOT `HALT_RECORD_WHY` - that text says the role is not run again, and on THIS road it
        # is (`resume_role` runs it on the person's answer), so the text names the threshold road in one clause. H29 (m4): the digest
        # says what the stop was for - `halts[].reason` reads it; the `why` is unchanged.
        digest = (f"stopped on {len(blocking.get('ids') or [])} blocking question(s): {', '.join(blocking.get('ids') or [])}"
                  + (f" and {count} open question(s)" if count_stop else "")) if blocked else \
            f"stopped on the question threshold: {count} open question(s)"
        self.py_trace("stage_done.py", "--task", self.task, "--stage", stage, "--status", "halted", "--role", role,
                      "--digest", digest,
                      why="the question-threshold stop (the role finished and code stopped it; it resumes on the person's answer): the Person is "
                          "raised either way; a later running/done write supersedes the record, and a retry after a resume would write a stale halt")
        raise Person("questions", text, stage, dispatch)

    def register_hashes(self) -> dict:
        """`{question id: the hash of its row today}` of the register, `{}` when it cannot be read: what a stop SHOWS and what a
        person's answer is stamped with. An id with no hash here never matches a passed blocker (FR-59)."""
        try:
            import question_register as QR
            return {q["id"]: q.get("row_hash") or "" for q in QR.load(self.task_root)["questions"]}
        except Exception:
            return {}                       # the answer then takes the row's hash as it is when answered

    @staticmethod
    def blockers_to_stop_on(blocking: dict, answered, hashes: dict) -> list:
        """The ids of the open blockers (`question_stop.blocking_stop`) that no `go on` passed ON THESE BYTES: `answered.blocking_ids`
        holds `{id: the row hash that was passed}`, and an id missing there, or with another hash, is stopped on again (H44). A token
        answer never adds to it (H26), so a blocker the person left alone is asked again."""
        if not blocking.get("stop"):
            return []
        passed = (answered or {}).get("blocking_ids")
        passed = passed if isinstance(passed, dict) else {}
        return [qid for qid in blocking.get("ids") or [] if not passed.get(qid) or passed.get(qid) != hashes.get(qid)]

    def count_stop_stands(self, stage: str, count, share, answered) -> bool:
        """Does the COUNT stop the stage? Not when the person answered at this count and share (Q8: their answer is the pass for
        THAT count, only a larger one is a new fact), and not when the stage carries the person's recorded pass of the question
        threshold. Neither early return touches the blocking check (M1)."""
        if answered is not None and not self.larger_than_answered(count, share, answered):
            print(f"{stage}: {count} question(s) are open, as when the person answered at "
                  f"{self.question_when(answered.get('at'))}: their answer is the pass, no second stop")
            return False
        try:
            _blocking, passed = waiver.split_overridden(
                [f"{waiver.QUESTION_THRESHOLD_BLOCK}: {count} open question(s) at {stage}"], self.pipeline(), stage)
        except Exception as exc:
            passed = []
            print(f"note: the person's pass for the question threshold could not be read ({type(exc).__name__}: {exc})")
        if passed:
            print(f"{stage}: the question threshold is passed by the person's word "
                  f"({' / '.join(str(p.get('decision')) for p in passed)[:300]}); the stage goes on")
            return False
        return True

    def question_resume_prompt(self, dispatch: str, words: str) -> str:
        """The text of a role resumed on the person's answers to a threshold stop. H36: when code changed the plan rows to follow those
        answers (`apply_question_answers`), the role is told what changed and to read the plan again - a role that kept its own copy of
        the plan in its context would overwrite the change."""
        told = (self.state.get("question_pass_lines") or {}).pop(dispatch, None)
        changed = ("\n" + "\n".join(str(line) for line in told) + "\nthe plan rows above were changed by code to follow the "
                    "answers; read work/test-plan.json again before you edit it.\n") if told else ""
        return (f"The person answered the open questions: \"{words.strip()}\". Their answers are recorded; "
                f"continue your dispatch {dispatch} on them — do not ask them again. " + changed +
                "Your final message is the handoff form only:\n" + HANDOFF_FORM)

    def question_rework(self, stage: str, role: str, dispatch: str, words: str, complete, why: str) -> tuple:
        """R17, FR-57: no session to resume (or it failed) - the SAME dispatch runs in a new session as a
        rework whose reason is the person's words, verbatim, and the role continues its interrupted
        artifacts. `controller rework` is not the door: it needs an ACCEPTED dispatch of the role and a
        stop comes before `finish`. The saved result is set aside (not deleted): `run_role` would
        otherwise reuse it and the role would never see the words."""
        print(f"{stage}: {why}; the role goes on in a new session with the person's words as the reason")
        saved = self.state_dir / "driver-runs" / f"{dispatch}.json"
        if saved.is_file():
            saved.replace(saved.with_suffix(".stopped.json"))
        stop = self.state.get("question_stop") or {}
        stop.pop("resume", None)
        self.state["pending_words"].pop(dispatch, None)
        self.save_state()
        record = (self.controller_state().get("dispatches") or {}).get(dispatch) or {}
        scope = list(record.get("scope") or [])
        return self.run_role(stage, role, scope=scope, complete=complete,
                             rework={"id": dispatch, "scope": scope, "reason": words})

    def take_question_answer(self, stage: str, dispatch: str, words: str) -> None:
        """R17: the person's words at a threshold stop. Closed tokens (`Q1: a`, `Q2: not needed`) become
        answer records by code, `where` = `<stage> stop`; the whole words go to the role's own session.
        Nothing here calls the conductor (FR-48). It errs toward NOT recording: an id that is not open, a
        letter beyond the readings, two answers for one question stay with the role, which reads meaning
        (FR-12) - and are printed back, so the person is never left guessing (never a dead end).

        The answer is the informed pass (Q8): the count and share the person was shown are kept - and the blockers they were
        passed ON (`blocking_ids`) are kept as they were: only a `go on` adds to them (H26). HF2-7: the lines are read by
        `question_register.record_answers` over the WHOLE register (an `until the report` line is a word too), and the recorded
        answers are applied to the plan by code in the same move (`apply_question_answers`)."""
        stop = self.state.get("question_stop")
        if not isinstance(stop, dict):
            stop = self.state["question_stop"] = {}
        # F11: the WHOLE answer `go on` or `stop` is read before the choices (`go on` inside other words stays the choices
        # road below, FR-12). Neither files the words for the role: `pending_words` stays empty.
        token = self.s0_normalize(words)
        if token in ("go on", "stop"):
            self.answer_row(f"{stage} question stop ({token}): ", words.strip(), what="your answer at the question stop")
            if token == "stop":
                raise self.held_question(self.stop_held("If you want the factory to go on after all, answer the questions or `go on`."))
            # N9 (FR-4): the pass is recorded for what the person was SHOWN. The count's waiver only when the stop they read was for the
            # count (`over_threshold` among its reasons; a stop recorded before the reasons existed was a count's); the blockers they read
            # are passed by `blocking_ids`, each on the bytes it was shown with (H44) - a stop for blockers alone writes no waiver.
            if "over_threshold" in (stop.get("reasons") or ["over_threshold"]):
                code, out = self.py("waiver.py", "--task", self.task, "--stage", stage, "--block", waiver.QUESTION_THRESHOLD_BLOCK,
                                    "--words-file", str(self.task_root / self.answer_file()), *self.waiver_road())
                if code:
                    print(f"{stage}: the pass was not recorded ({out[-300:]}); the question comes back")
                    raise self.held_question("Your word could not be recorded as the pass, so nothing was passed.")
            print(f"{stage}: going on with the questions open, on the person's word; recorded")
            stop["answered"] = {"count": stop.get("count"), "share": stop.get("share"), "at": _now(),
                                "blocking_ids": {**self.passed_blockers(stop), **(stop.get("blocking_ids_shown") or {})}}
            self.state["pending_words"].pop(dispatch, None)
            return
        self.record_question_words(stage, words, stop.get("shown") if isinstance(stop.get("shown"), dict) else {})
        told = self.apply_question_answers(stage)["plan_lines"]
        if told:
            self.state.setdefault("question_pass_lines", {}).setdefault(dispatch, []).extend(told)      # H36: for the resumed role
        stop["answered"] = {"count": stop.get("count"), "share": stop.get("share"), "at": _now(),
                            "blocking_ids": self.passed_blockers(stop)}
        stop["resume"] = True
        self.state["pending_words"][dispatch] = words
        self.answer_row(f"{stage} question stop: ", words, what="your answers at the question stop")

    @staticmethod
    def passed_blockers(stop: dict) -> dict:
        """`{id: row hash}` of the blockers a `go on` of this stop passed, `{}` when none (a stop recorded before they were kept)."""
        passed = (stop.get("answered") or {}).get("blocking_ids") if isinstance(stop.get("answered"), dict) else None
        return dict(passed) if isinstance(passed, dict) else {}

    def record_question_words(self, stage: str, words: str, shown: dict) -> dict:
        """The person's words at a stop of `stage` (the threshold's or a halt's), turned into answer records by `question_register.
        record_answers` - the ONE move (AR-14): `where` = `<stage> stop`, `shown` the row hashes the person was shown, the story's own case
        ids so a `<case id>: manual|automate|accept as blocked` line is the word about a CASE it is (t-261). What was done is PRINTED, so
        the person is never left guessing: the lines recorded, the lines kept open on their word (`until the report`), the lines not
        read and why, an id the register does not hold (FR-59: never a guess), a decision inside a fenced block, a word about a case (a
        stop decides no case, gate A does). Returns `record_answers`' dict; a failure to read the register is printed and gives
        the empty one (`all_tokens` False): the words still go on, a failure to read them is not a dead end."""
        import question_register as QR
        read = {"recorded": [], "unread": [], "unknown_ids": [], "deferred": [], "all_tokens": False, "fenced": []}
        try:
            try:
                import gate_brief
                case_ids = list(gate_brief.story_cases(self.task_root)[0])
            except Exception:
                case_ids = []
            read = QR.record_answers(self.task_root, words, f"{stage} stop", self.QUESTION_ANSWER_BY, shown, case_ids)
            for notice in QR.fence_notices(read):
                print(f"{stage}: {notice}")
            for token in QR.parse_choices(words, QR.load(self.task_root)["questions"], case_ids).get("case_tokens") or []:
                print(f"{stage}: `{token['written']}: {token['decision']}` is a word about a case; a question stop "
                      "decides no case, so it goes to the role with your words; say it again at gate A for it to be applied")
            if read["unknown_ids"]:
                print(f"{stage}: not recognised as open questions, so nothing is recorded for them: "
                      + ", ".join(read["unknown_ids"]))
        except Exception as exc:
            print(f"note: the answers could not be read against the register ({type(exc).__name__}: {exc}); "
                  "the role gets the words whole")
        print(f"{stage}: recorded by code — " + (", ".join(read["recorded"]) if read["recorded"] else "no question answered by a token"))
        if read["deferred"]:
            print(f"{stage}: kept open until the report, on your word: " + ", ".join(read["deferred"]))
        if read["unread"]:
            print(f"{stage}: not read as an answer, so still open: " + "; ".join(read["unread"]))
        return read

    def record_halt_words(self, stage: str, words: str):
        """B2: the person's answer to a HALT at S2-S4 over a register that holds questions, recorded by code before anyone else reads it:
        the lines through `record_question_words` (`where` = `<stage> stop`), the words journalled as a `human_answer` (FR-8, once), the
        recorded answers laid over the plan (`apply_question_answers`). Returns `record_answers`' dict, or None when this is not such a
        halt (a stage with no stop, no register, no question in it, or a register that cannot be read): the halt then goes on its old
        road unchanged. POSITION INVARIANT: before the conductor and the judge are called, so a token the code read never reaches the
        conductor as 'not recorded' (FR-48)."""
        try:
            import question_register as QR
            if f"{stage} stop" not in QR.vocabulary()["where"] or not QR.load(self.task_root)["questions"]:
                return None
        except Exception:
            return None
        read = self.record_question_words(stage, words, {})
        self.answer_row(f"{stage} halt: ", words.strip(), what="your answer at the halt")
        self.apply_question_answers(stage)
        return read

    # --- HF2-7: an answer recorded AFTER the work that rests on the question was written (the owner's word of 24.10) --------------------
    def apply_question_answers(self, stage: str) -> dict:
        """Lay the answers recorded in the register over the plan, by CODE, at a stop of `stage` (S2-S4) or at gate A (`"A"`), and open the
        rework of whoever wrote what still follows the other reading. `planning_contract.apply_recorded_answers` does the applying
        (it patches the plan rows the answer decides, once per record, never an approved plan, never a changed row); what it names
        for an owner goes to `state["answer_rework"]` (`merge_answer_rework`), which `answer_rework_step` carries out from the loop -
        code opens the rework, the conductor is not called (FR-48). Returns `{"opened": a rework is now owed, "plan_lines": what code
        changed in the plan, for the role that holds a copy of it (H36)}`. It never raises: a failure is a line and the next stop tries
        again (P1). INVARIANT (F-13): the callers are the thresholds AFTER their `where` check and `gate_repair("A")` after the
        open-packet and kept-answer returns - never under a gate A packet the person is reading, whose plan must not change."""
        out = {"opened": False, "plan_lines": []}
        label = "gate A" if stage == "A" else stage
        try:
            import planning_contract as PC
            got = PC.apply_recorded_answers(self.task_root, "gate A" if stage == "A" else f"{stage} stop")
            for line in got["lines"]:
                print(f"{label}: {line}")
            if any(isinstance(r, dict) and r.get("rows") for r in got["applied"]):
                out["plan_lines"] = [str(line) for line in got["lines"]]
            # the answer the person gives NOW, per question: a rework still waiting for another answer to it is replaced, never
            # sent (HF3-10, M3). Only an answer the plan was asked to follow counts - not one refused (a changed row, an approved plan).
            intents = [r for r in got["applied"] if PC.plan_intent(r) and isinstance(r.get("id"), str) and isinstance(r.get("answer"), str)]
            current = {r["id"]: r["answer"] for r in intents}
            # own words carry no letter, so only the record of them tells one answer from the next (HF3-10, F6)
            current_at = {r["id"]: str(r.get("record_at") or "") for r in intents if r["answer"] == ""}
            if got["rework"] or current:
                out["opened"] = self.merge_answer_rework(got["rework"], current, current_at)
        except Exception as exc:
            print(f"note: your recorded answers could not be applied to the plan ({type(exc).__name__}: {exc}); "
                  "they are tried again at the next stop")
        return out

    @staticmethod
    def answer_supersede(items: list, current, current_at=None) -> list:
        """HF3-10 (M3): `items` (of `state["answer_rework"]`) with the part that waits for an answer the person no longer gives taken out.
        `current` = {question id: the answer given now}. For each such id the questions of an item with ANOTHER answer go, and the pairs
        of that id with them (unless a question of the id with the current answer stays); a row or case that HAD pairs and has none left
        goes; an item with no question left goes. A row or case of an item written before pairs existed (no pair at all) stays - only its
        questions go (E14). `current_at` = {question id: the register record of the answer given now}, for an answer in the person's
        OWN WORDS only (it has no letter, so the record tells it from the words before): an entry of those words with another
        `record_at` is the earlier words and goes, so words given twice leave ONE line for the question (F6); no `current_at` entry
        for an id: equal answers are the same answer. Pure: a new list, the input is not changed; an empty or no-dict `current` gives
        the input back. INVARIANT: a role is never told an answer the person has since replaced - the caller passes only the items
        nobody has started."""
        if not isinstance(current, dict) or not current:
            return items
        at_of = current_at if isinstance(current_at, dict) else {}

        def without_replaced(questions: list, pairs: list, qid, answer) -> tuple:
            """(questions, pairs) minus the entries of `qid` that hold another answer, and minus the pairs of `qid` once none stays."""
            at = at_of.get(qid) if answer == "" else None

            def same(entry: dict) -> bool:
                return entry.get("answer") == answer and (not at or entry.get("record_at") == at)
            kept = [a for a in questions if a.get("id") != qid or same(a)]
            if len(kept) != len(questions) and not any(a.get("id") == qid for a in kept):
                pairs = [p for p in pairs if p.get("question") != qid]
            return kept, pairs
        out = []
        for item in items:
            pairs = [p for p in item.get("pairs") or [] if isinstance(p, dict)]
            questions = [dict(a) for a in item.get("questions") or [] if isinstance(a, dict)]
            for qid, answer in current.items():
                questions, pairs = without_replaced(questions, pairs, qid, answer)
            if not questions:
                continue
            had = {p.get("where") for p in item.get("pairs") or [] if isinstance(p, dict)}
            left = {p.get("where") for p in pairs}
            fresh = dict(item, questions=questions)
            if "pairs" in item:
                fresh["pairs"] = pairs
            for where in ("rows", "cases"):
                if where in item:
                    fresh[where] = [w for w in item[where] if w not in had or w in left]
            out.append(fresh)
        return out

    def merge_answer_rework(self, rework: list, current=None, current_at=None) -> bool:
        """Put the rework `apply_recorded_answers` named into `state["answer_rework"]["items"]` - ONE item per (stage, role): `{stage, role,
        rows | cases, questions: [{id, answer, record_at, was?}], pairs: [{question, where, seen}], words_file, before}`, the strategist's
        (S3) first, then the designer's (S4) (H40). `before` = the controller's `question_answer` dispatches of that stage already there, so
        the step finds its OWN dispatch (P22); an item whose dispatch is registered but not yet dropped (a crash between the two) is never
        added to or replaced - a new item starts. Returns whether anything was added. The `words_file` is the person's words, whole (C16).

        HF3-10 (H41): FIRST the unregistered items give way to `current` ({id: the answer given now}, `current_at` {id: the record of
        own words}, `answer_supersede`), THEN the new entries are added - a new answer never displaces itself. `pairs` hold, per (question,
        row or case), whether the branch check NAMED that pair when the rework was named (`seen`), on the plan as the applier left it (this
        runs after `apply_recorded_answers`): only a pair seen and later not named lets the step drop the work (`answer_pairs_owed`). The
        check is read ONCE per call, whenever `rework` is not empty; one that could not be read marks every pair unseen (FR-59)."""
        import controller as C
        owners = {owner: (stage, role) for owner, (stage, role, _flag) in C.ANSWER_REWORK_OWNERS.items()}       # the controller's one table (F-12)
        record = self.state.get("answer_rework")
        items = [i for i in (record.get("items") if isinstance(record, dict) else None) or [] if isinstance(i, dict)]
        dispatches = self.controller_state().get("dispatches") or {} if (self.state_dir / "controller.json").is_file() else {}
        gone = [self.answer_rework_registered(i, dispatches) for i in items]       # registered: the controller has it, not touched
        items = [i for i, g in zip(items, gone) if g] + self.answer_supersede([i for i, g in zip(items, gone) if not g], current, current_at)
        registered = sum(gone)                  # the registered items are the first `registered` of `items`; every other one is open to adds
        findings = self.question_branch_findings() if rework else None
        named = {(f.get("question"), f.get("where")) for f in findings or [] if isinstance(f, dict)}
        merged = False
        for entry in rework:
            found = owners.get(entry.get("owner")) if isinstance(entry, dict) else None
            if found is None:
                print(f"note: a rework for {entry.get('owner') if isinstance(entry, dict) else entry!r} is not one the driver can start; "
                      "gate A names it")
                continue
            stage, role = found
            item = next((i for n, i in enumerate(items) if n >= registered and (i.get("stage"), i.get("role")) == found), None)
            if item is None:
                item = {"stage": stage, "role": role, "rows": [], "cases": [], "questions": [], "pairs": [], "words_file": "",
                        "before": sorted(self.answer_rework_dispatches(dispatches, stage))}
                items.append(item)
            where = "rows" if stage == "S3" else "cases"
            if entry["where"] not in item[where]:
                item[where].append(entry["where"])
            pairs = item.setdefault("pairs", [])
            if not any(isinstance(p, dict) and (p.get("question"), p.get("where")) == (entry["question"], entry["where"]) for p in pairs):
                pairs.append({"question": entry["question"], "where": entry["where"], "seen": (entry["question"], entry["where"]) in named})
            asked = {"id": entry["question"], "answer": entry["answer"], "record_at": entry["record_at"]}
            if isinstance(entry.get("was"), str):
                asked["was"] = entry["was"]
            if asked not in item["questions"]:
                item["questions"].append(asked)
            merged = True
        items.sort(key=lambda i: 0 if i.get("stage") == "S3" else 1)
        for item in items:
            item["words_file"] = self.answer_item_words(item)
        if items:
            self.state["answer_rework"] = {"items": items}
            self.save_state()
        elif record is not None:
            # the replacement left nothing owed (E20): no empty record stays. Not `drop_record` (a higher layer, L5): this is the record's owner
            self.state.pop("answer_rework", None)
            self.save_state()
        return merged

    def answer_rework_dispatches(self, dispatches: dict, stage: str) -> dict:
        """The controller's `question_answer` reworks of `stage`, of either origin (the person's words by file, or the driver's own reason)."""
        return {**self.rework_dispatches(dispatches, "question_answer", by_person=True, stage=stage),
                **self.rework_dispatches(dispatches, "question_answer", by_person=False, stage=stage)}

    def answer_rework_registered(self, item: dict, dispatches: dict) -> bool:
        """Has the controller registered THIS item's rework (a `question_answer` dispatch of its stage that is not in its `before`)?"""
        return any(did not in (item.get("before") or []) for did in self.answer_rework_dispatches(dispatches, str(item.get("stage"))))

    def answer_item_words(self, item: dict) -> str:
        """The task-root relative file of the person's words behind an item, whole (FR-8, C16): the words of the records of its questions.
        The answer being taken now is its own file (`answer_file`); words of another time (an answer recorded by the command line) are
        written ONCE (`words_file`) and the file is kept while it holds the same words. '' with no words: the step then gives the role a
        reason of the driver's own (no file is made of nothing)."""
        import question_register as QR

        def flat(text: str) -> str:
            return text.replace("\r\n", "\n").strip()
        by_id = {q["id"]: q for q in QR.load(self.task_root)["questions"]}
        said = []
        for asked in item["questions"]:
            text = str((by_id.get(asked["id"]) or {}).get("words") or "")
            if text.strip() and text not in said:
                said.append(text)
        text = "\n\n".join(said)
        if not text.strip():
            return ""
        if self._answer and flat(str(self._answer.get("text") or "")) == flat(text):
            return self.answer_file()
        old = str(item.get("words_file") or "")
        try:
            if old and flat((self.task_root / old).read_text(encoding="utf-8")) == flat(text):
                return old
        except OSError:
            pass
        path = self.words_file(text, "questionanswer")
        return path.relative_to(self.task_root).as_posix() if path else ""

    def question_branch_findings(self):
        """The findings of the gate rehearsal's question-branch check (`gate_preflight.Rehearsal.check_question_branches`: the ONE reader,
        `planning_contract.variant_errors` under it) over the plan and the cases as they are NOW, as `[finding]`; None when that could
        not be established (the check could not run, or it said it did not check) - an unknown never drops owed work (FR-59)."""
        try:
            import gate_preflight
            rehearsal = gate_preflight.Rehearsal(self.task_root, "A")
            rehearsal.check_question_branches()
        except Exception:
            return None
        if any(f.get("check") == "question_branches" and f.get("class") == gate_preflight.FACTORY_DEFECT for f in rehearsal.findings):
            return None
        if any(i.get("check") == "question_branches" for i in rehearsal.info):
            return None
        return [f for f in rehearsal.findings if f.get("check") == "question_branches"]

    # --- questions for the person ----------------------------------------------------------
    def question_path(self, answered: bool = False) -> Path:
        return self.state_dir / ("driver-question.answered.md" if answered
                                 else "driver-question.md")

    def reconcile_question(self) -> str:
        """The file a person reads and the `asked` flag the loop reads are two halves of one
        fact, and until they were written by one operation a story could hold half of it: a flag
        whose file had been deleted (the loop waits for an answer to a question nobody can read)
        or a file left behind after the answer landed (the person answers it twice). Both halves
        are repaired here, at startup, and the repair is PRINTED - a story silently put back on
        its feet is how the first half went unnoticed in the first place (P6)."""
        asked, path = self.state.get("asked") or {}, self.question_path()
        if not (asked.get("kind") and path.is_file()):
            self.drop_standing()               # E4: no question is open, so no refusal stands (a record a crash left behind)
        if asked.get("kind") and not path.is_file():
            self.state["asked"] = {}
            self.save_state()
            return (f"the open question ({asked.get('kind')} at {asked.get('stage') or '?'}) has "
                    f"no {path.name}: the flag is cleared and that step will run again")
        if path.is_file() and not asked.get("kind"):
            if not self.dry:
                path.replace(self.question_path(answered=True))
            return f"{path.name} was left behind with no question open: filed as answered"
        return ""

    def ask(self, person: Person) -> int:
        path = self.question_path()
        head = [f"# Driver question — {self.task}", f"kind: {person.kind}", f"stage: {person.stage}",
                f"dispatch: {person.dispatch}", f"asked_at: {_now()}", ""]
        tail = ["", "---", "Answer: write your words to a file and run",
                f"  python {self.scripts / 'story_run.py'} --task {self.task} --answer <file>"]
        if person.answer_note.strip():
            tail += ["", person.answer_note.strip()]
        waiting = len(self.deferred_items())            # RN1-24: one line, never the texts (FR-6: one question to a file); `defer_question` asks without it
        if waiting and not getattr(self, "_deferring", False):
            tail += ["", f"{waiting} more question(s) wait; they are asked before gate B."]
        # The factory's own words go beside the question, never instead of it: a refusal is
        # written for the role that called the script, and on TP1-13797 run 5 all twelve
        # questions that carried one reached the person with detector lines, form field paths
        # and an exit code in them (references/human-questions.md, "what the text may never
        # carry"). The file is named here, in the one block where a path is an instruction.
        if person.details.strip():
            details = self.state_dir / "driver-question-details.md"
            details.parent.mkdir(parents=True, exist_ok=True)
            details.write_text(f"# The factory's own words — {self.task}, {person.kind} at "
                               f"{person.stage or 'the story'}\n\nThis is what the check printed, "
                               "in its own vocabulary. It is here because you may want it, not "
                               "because it is the question.\n\n```\n" + person.details.strip() +
                               "\n```\n", encoding="utf-8")
            tail.append("")
            tail.append(f"{self.DETAILS_POINTER}, if you want them: "
                        f"qa-factory/artifacts/{self.task}/"
                        f"{details.relative_to(self.task_root).as_posix()}")
        body = list(head) + [person.text]
        # The question is compared the way `take_answer` hashed it: as the FILE reads, head first. A text that opens with a `# ` title
        # (the gate packet's `# Gate B - T`) lost that line to the head pattern here and kept it in the file, so a gate asked again
        # with the same text never met its own earlier answer (FR-7).
        earlier = self.already_answered("\n".join([*head, person.text]))
        if earlier:
            # FR-7: it either moves or comes back changed. The driver cannot know what the
            # earlier answer failed to settle - if it knew, it would not be asking - so it says
            # what it does know: this is the same question, here is what you said and when, and
            # here is the state it left. One `resolve_return` packet reached the person three
            # times word for word in run 5 because nothing compared the two.
            body += ["", "---", "**You have answered this exact question before** — "
                     f"{earlier.get('ts', 'earlier')}, and it did not settle it:", "",
                     "> " + str(earlier.get("words") or "")[:600].replace("\n", "\n> "), "",
                     "The factory is asking again because the boundary has not moved. If the "
                     "answer above still stands, say what should happen when it is followed and "
                     "the block is still there — including stopping the story."]
        text = "\n".join(body + tail)
        self.judge_own_question(person, text)
        # The flag first, the file second, and the file is what `reconcile_question` trusts: a
        # crash between the two leaves a flag with no file, which is the half it can repair.
        self.state["asked"] = {"kind": person.kind, "stage": person.stage,
                              "dispatch": person.dispatch, "at": _now()}
        if person.offered:
            # A question the seam (`no_move`) raised: `take_answer` reads a token against THESE, and a question of any other
            # origin carries none, so no other answer is captured (C1-1). The delivery flag (set by `delivery` alone for ITS
            # question) is not cleared here: `take_answer` ignores it for a question that carries `offered`, so "no delivery"
            # cannot be taken by the delivery branch as an answer to this one.
            self.state["asked"].update(offered=list(person.offered), options=list(person.options),
                                       words_file=person.words_file, why=person.why, block=person.block)
            if person.rows:
                self.state["asked"]["rows"] = list(person.rows)
            if person.probe_gap_cases:
                self.state["asked"]["probe_gap_cases"] = list(person.probe_gap_cases)
            if person.probe_judgment_cases:
                self.state["asked"]["probe_judgment_cases"] = list(person.probe_judgment_cases)
        if person.kind == "s1_gap":
            # POSITION INVARIANT: this kind ALONE gets the fields (a question of another kind never carries them, so the answer branch
            # of `s1_gap` cannot be reached by one), and a question the seam raised (`offered`) is never an `s1_gap`.
            self.state["asked"].update(sources=list(person.sources), classes=list(person.classes))
        if person.held_lead:
            self.state["asked"]["held_lead"] = person.held_lead
        if person.why_person:
            self.state["asked"]["why_person"] = person.why_person      # the class travels to the word the answer records (`waiver_road`)
        if person.kind in ("conductor", "refusal"):
            # The named blocks of the question (t-217 C8): written for conductor and refusal questions - an EMPTY
            # list until the parser that reads them from `details` lands (t-228). The KEY is what matters now: a
            # question asked by this driver carries it, so `take_answer` never reads a dispatch out of its text,
            # while a question an older driver asked (no key) keeps the legacy text reading.
            self.state["asked"]["blocks"] = []
        # The stand question's answer branch (`take_answer`) is keyed on this flag, so the flag is
        # written HERE and nowhere else: it names the stage for the Person `stand_check` raised, and
        # is gone for every other question. A flag that outlived its question captured the answer
        # to a later one at the same stage (t-037: `retry` to an `environment_job` question was
        # recorded as a stand answer and nothing else happened).
        stand_stage = getattr(person, "stand_stage", "")
        if stand_stage:
            self.state["stand_question"] = stand_stage
        else:
            self.state.pop("stand_question", None)
        # The same rule for the stand-login question (t-292): `take_answer`'s branch for it is keyed on this flag,
        # which is set HERE and nowhere else, from the Person `stand_login_gate` raised, and gone for every other
        # question - so the answer to another question can never be taken as the answer to this one.
        login_cases = getattr(person, "login_cases", None)
        if login_cases:
            self.state["login_question"] = {"stage": person.stage, "cases": list(login_cases)}
        else:
            self.state.pop("login_question", None)
        # And for the stand-BUILD question (t-300 N1b): `take_answer`'s branch for kind `stand_identity` is keyed on this
        # flag, set HERE and nowhere else, from the Person `build_check` raised, and gone for every other question. It
        # carries the whole packet the answer needs (the stand, the profile, the variant, the commits, what was offered).
        build_question = getattr(person, "build_question", None)
        if build_question:
            self.state["build_question"] = dict(build_question)
        else:
            self.state.pop("build_question", None)
        self.save_state()
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
        self.progress_line()            # the question is on record (`asked`): a gate is reached by being asked
        print(text)
        return person.code

    def already_answered(self, question: str) -> dict:
        """The answer this exact question got before, or {}.

        The comparison is the body's hash, written into `driver-answers.jsonl` when the answer
        was taken: the head carries a timestamp and the answer block carries a path, so two asks
        of the same thing differ in both and are the same question."""
        wanted = question_body_sha(question)
        found = {}
        for row in _read_jsonl(self.state_dir / "driver-answers.jsonl"):
            if row.get("question_sha") == wanted:
                found = row
        return found

    def judge_own_question(self, person: Person, text: str) -> list:
        """Does the text we are about to show obey `references/human-questions.md`?

        Never a reason not to ask: our defect is not the person's problem, and a question
        withheld is worse than a question worded badly. It is printed and journalled, so the
        share of questions that break our own rules is a number the next run can read instead
        of an impression (FR-41: the defect is stated, not hidden). Measured on run 5: of the
        twelve questions the conductor wrote, seven obeyed the rules on their own and all
        twelve broke them as the person saw them, because the refusal was glued underneath."""
        try:
            import human_text
            # `offered` UNION `priced`: a question is "own" when either set names the token (G20); `priced` is never in `asked`
            found = human_text.problems(text, offered=list(dict.fromkeys([*person.offered, *getattr(person, "priced", ())])) or None)
        except Exception as exc:  # a missing rules file must never cost a question
            print(f"question rules: not checked ({type(exc).__name__}: {exc})")
            return []
        _append_jsonl(self.state_dir / "driver-questions.jsonl",
                      {"ts": _now(), "kind": person.kind, "stage": person.stage,
                       "dispatch": person.dispatch, "bytes": len(text.encode("utf-8")),
                       "details_file": bool(person.details.strip()),
                       "problems": [p["rule"] for p in found],
                       # RN1-9: the class the question answers (None when it carries none), what was read, who raised it (calibration check 38)
                       "source": person.source, "why_person": person.why_person or None, "checked": person.checked or None,
                       "class_check": PO.status(),
                       # N16 (C2-9): the detector reads the causes a gap question carried, for `s1_gap` ALONE
                       **({"causes": list(person.classes)} if person.kind == "s1_gap" else {})})
        if found:
            print(f"question rules: this text breaks {len(found)} rule(s) of "
                  "references/human-questions.md — asked anyway, recorded as ours:")
            for item in found:
                print(f"  - {item['rule']}: `{item['found'][:80]}`")
        return found

    # --- a question about SOME manual cases waits; the independent work goes on (RN1-24, P22) -----------------------
    # LOCAL-1 (02.11.2026): one question about one manual case stopped the stages that did not depend on it. The question is rendered
    # by `ask()` exactly as a live one (the same text, the same `driver-questions.jsonl` row), kept in `state/deferred-questions/<n>.md`
    # and `state["deferred"]`, and asked one by one before gate B (`deferred_step`; the owner's FK-3 (a): no new reading of words, the
    # executors of the original question answer). The skill road has no code for it yet: s6.md carries the rule (AR-19, SC5-3).
    DEFER_FLAGS = ("login_question", "stand_question", "build_question", "gate_a_dry")      # the flags `ask()` / its Person set for a question

    def deferred_items(self) -> list:
        """The deferred questions in the order they were deferred; `[]` when there is none or the record is not a list (an unreadable
        record is no question: `deferred_step` never invents one)."""
        raw = self.state.get("deferred")
        return [item for item in raw if isinstance(item, dict) and item.get("n") is not None] if isinstance(raw, list) else []

    def deferred_waiting(self, cases) -> list:
        """`[(case, n)]` for the cases of `cases` a deferred question holds (the order of `cases`)."""
        held = {str(case): item["n"] for item in self.deferred_items() for case in item.get("holds") or []}
        return [(case, held[case]) for case in cases if case in held]

    def deferrable(self, person: "Person") -> bool:
        """May this question wait while the independent work goes on? True only when ALL hold: it names cases (`holds`); its kind is not
        a gate (a gate is the stop itself); it is not the conductor's `stop` (exit 4); its cases are not already held by another
        deferred question (E11: one open question per case); and the S6 scope has a case OUTSIDE `holds` (otherwise there is nothing to
        go on with: the question is asked at once, as before). ERROR DIRECTION: every doubt - no scope, an unreadable state - is False,
        a question asked at once, never one withheld.

        TR3-10 D (item 10, edge D.1) POSITION: the FIRST line, before the `holds` test. The two questions that hold NO case (`walk_supply`,
        `data_change`) set `no_hold`; only that kind WITH the flag passes - a `walk_supply` Person without it, and any other Person (a gate
        among them) with the flag set by mistake, fall through to the test below and are asked at once."""
        if getattr(person, "no_hold", False) and person.kind in ("walk_supply", "data_change"):
            return True
        holds = {str(case) for case in getattr(person, "holds", ()) or ()}
        if not holds or person.kind in GATE_KINDS or person.code == EXIT_GAVE_UP:
            return False
        return self.holds_can_wait(holds)

    def holds_can_wait(self, holds) -> bool:
        """The case half of `deferrable`, also read by the sign-in question's text (it says which road it is on): no case of `holds` is
        held by another deferred question (E11) and the S6 scope has a case OUTSIDE `holds`. An unreadable scope is False."""
        holds = {str(case) for case in holds}
        if not holds or any(case in holds for case, _n in self.deferred_waiting(sorted(holds))):
            return False
        try:
            scope = self.controller_state().get("scope")
        except Exception:
            return False
        return isinstance(scope, list) and any(str(case) not in holds for case in scope)

    def manual_holds(self, dispatch: str) -> tuple:
        """The third `holds` site (spec 2.2 p.2): the seam question over a REFUSED manual S6 dispatch waits for the cases that dispatch
        carried (`manual_case_ids` of its controller record, when `execution_kind` is `manual`). `()` (asks at once, as before) for no
        dispatch, another kind, an unreadable state or no ids - ERROR DIRECTION: a question asked, never withheld."""
        if not dispatch:
            return ()
        try:
            record = (self.controller_state().get("dispatches") or {}).get(dispatch)
        except Exception:
            return ()
        ids = record.get("manual_case_ids") if isinstance(record, dict) and record.get("execution_kind") == "manual" else None
        return tuple(dict.fromkeys(str(case) for case in ids)) if isinstance(ids, list) else ()

    def defer_question(self, person: "Person") -> None:
        """Set the question aside: `ask()` renders it (the same text, the same `driver-questions.jsonl` row and its `source`), the
        file moves to `state/deferred-questions/<n>.md`, and the flags `ask()` set are taken off the live state with the question
        (a flag that outlived its question captured the next answer at the same stage, t-037). The record keeps what `deferred_step`
        needs to ask it again as it was."""
        import contextlib
        import io
        n = int(self.state.get("deferred_seq") or 0) + 1
        before = {key for key in self.DEFER_FLAGS if key in self.state}
        self._deferring = True
        try:
            with contextlib.redirect_stdout(io.StringIO()):          # the text is shown at gate B, not now
                self.ask(person)
        finally:
            self._deferring = False
        live = self.question_path()
        text = live.read_text(encoding="utf-8", errors="replace") if live.is_file() else ""
        kept = self.state_dir / "deferred-questions" / f"{n}.md"
        kept.parent.mkdir(parents=True, exist_ok=True)
        kept.write_text(text, encoding="utf-8")
        live.unlink(missing_ok=True)
        flags = {key: self.state[key] for key in self.DEFER_FLAGS if key in self.state}
        for key in self.DEFER_FLAGS:
            if key not in before:
                self.state.pop(key, None)
        holds = sorted({str(case) for case in person.holds})
        self.state["deferred"] = self.deferred_items() + [{
            "n": n, "kind": person.kind, "stage": person.stage, "dispatch": person.dispatch, "holds": holds,
            "asked": dict(self.state.get("asked") or {}), "flags": flags, "at": _now()}]
        self.state["deferred_seq"] = n
        self.state["asked"] = {}
        self.save_state()
        print(f"[progress] {person.stage or 'S6'}: a question about {', '.join(holds)} waits for you; the other work goes on; "
              "it is asked before gate B", flush=True)

    def deferred_step(self) -> None:
        """Called at the top of gate B's entry: the first unanswered deferred question is asked again as it was (its `asked`, its flags,
        its text with one head line `question: k of N, waiting since <stage>` - inside the machine head, so `question_body_sha` is the
        live question's, FR-7) and the run stops with exit 3. The answer goes through `take_answer` unchanged, with the executors of the
        original question; the item is dropped at the END of `take_answer`. Gate B is shown only when nothing is deferred. A text file
        that is gone is a refusal that says so - never a silent drop of a question (AR-28)."""
        items = self.deferred_items()
        if not items:
            self.state.pop("deferred_round", None)
            return
        item = items[0]
        kept = self.state_dir / "deferred-questions" / f"{item['n']}.md"
        try:
            text = kept.read_text(encoding="utf-8")
        except OSError as exc:
            raise Refusal(f"deferred question {item['n']}: its text file {kept} cannot be read ({type(exc).__name__}). The question is "
                          "still owed to the person, and `state/driver-state.json` (`deferred`) holds no text to write it from; answer the "
                          "conductor's question that follows this refusal (it settles how the person is asked).")
        total = max(int(self.state.get("deferred_round") or 0), len(items))
        self.state["deferred_round"] = total
        mark = f"question: {total - len(items) + 1} of {total}, waiting since {item.get('stage') or 'S6'}"
        title, _sep, rest = text.partition("\n")
        text = (title + "\n" + mark + "\n" + rest) if title.startswith("#") else (mark + "\n" + text)
        for key in self.DEFER_FLAGS:
            self.state.pop(key, None)
        self.state.update(item.get("flags") or {})
        self.state["asked"] = dict(item.get("asked") or {}, deferred_n=item["n"])
        self.save_state()
        path = self.question_path()
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
        self.progress_line()
        print(text)
        # remains: the question is the person's, asked again exactly as `ask()` wrote it; exit 3 is `ask()`'s own code (RN1-24)
        raise Stop(EXIT_PERSON, f"{mark.split(': ', 1)[1]} - answer it; gate B follows the last one")

    def deferred_decision(self, item: dict, token: str, words: str, asked: dict, stage: str, rel: str) -> None:
        """`go on` / `by hand` on a deferred question whose stage is closed (P22: the words are executed, not only recorded): the pass of
        the question's block is recorded (`pass_block`, held on a refusal like the live road) and the request.json of each held case is
        rewritten, through the same writer `manual_close` and `stand_login_gate` use, from the waiting reason to the person's decision:
        `by: person_checks` for `by hand` (the typed carrier, as `stand_login_gate` writes it), `left_unchecked` for anything else.
        A case whose request.json is no longer OUR waiting record (it was prepared or run since) is left as it is (AR-28). `rel` is the
        words file of the answer (the caller reads it: `answer_file` sits in a higher layer)."""
        import manual_evidence as ME
        block = str(asked.get("block") or "")
        if block:
            self.pass_block(stage, block, rel, "Your word could not be recorded as the pass, so nothing was passed.")
        said = " ".join(words.replace(self.BOM, "").split())
        by = "person_checks" if token == "by hand" else "left_unchecked"
        reason = f"not checked by an agent: you answered question {item['n']} about it; the person said: \"{said}\""
        door = "fix what that question named; the next run checks it by hand"
        for case in item.get("holds") or []:
            path = ME.request_path(self.task_root, case)
            refused = _read_json(path).get("refused")
            if not (isinstance(refused, dict) and refused.get("by") == "left_unchecked"
                    and str(refused.get("reason") or "").startswith("not checked yet: it waits for your answer")):
                continue
            if not self.refuse_case(None, case, reason, door, by):
                print(f"{case}: the decision could not be written to its request.json; the answer is on record")
            else:
                print(f"S6: {case}: not checked by hand — {reason}")

    def deferred_note(self) -> None:
        """A run that ends with deferred questions still open says so (E9): the list is on the record, never silently left."""
        items = self.deferred_items()
        if items:
            print(f"[progress] {len(items)} question(s) wait for you and are asked before gate B: "
                  + "; ".join(f"{item.get('kind')} about {', '.join(item.get('holds') or [])}" for item in items), flush=True)

    # --- a closed question with its prices (C1-3; references/human-questions.md item 6) ---------------------------
    def priced_section(self, key: str, options: list) -> Priced:
        """"## What each answer costs and does" for the question `key` of references/question-prices.json: `options` are
        `[{answer, token|None, says[, slots]}]` from the site (the words stay in code: they carry names), the three price lines
        come from the data row of each `answer` (`NM.priced_options`, the one resolution). Data or labels that cannot be read:
        the option lines are shown WITHOUT price lines and ONE `defect_found` (owner: factory) says why - a question is never
        withheld for its prices (FR-41)."""
        try:
            verdicts = (hooklib.load_ref_json(NM.VERDICTS_FILE) or {}).get("words") or {}
            priced = NM.priced_options(key, options, NM.data(), verdicts)
            return Priced(NM.render_options(priced, human_text.price_labels()), [o["token"] for o in priced if o["token"]])
        except (NM.DataUnreadable, human_text.LabelsUnreadable) as exc:
            said = f"the prices of the question `{key}` could not be read ({exc}); it was shown without its price lines"
            if self._price_notes is None:
                self.file_defect(self.boundary, f"owner: factory — {said}")
            else:               # inside the seam's fallback: ONE defect per failure, and this reason joins its note (G8)
                self._price_notes.append(said)
            return Priced(NM.render_options([{"token": o.get("token"), "says": str(o.get("says") or "").strip()} for o in options], []))

    def closed_question(self, key: str, lead: str, options: list) -> Priced:
        """The lead, then the priced section of `key` (`priced_section`). The text carries its `priced` tokens."""
        section = self.priced_section(key, options)
        return Priced(str(lead).rstrip() + "\n\n" + section, section.priced)

    # The move each token of a SITE's closed question carries when the site raises it as a seam question (C1-6b, A7): `retry` /
    # `go on` / `stop` are the seam's own moves (`NM.TOKEN_MOVES`, the one table); `by hand` passes the same block as `go on` (its
    # typed record is the site's); `reapprove` is a word only the site reads (`site_door`).
    SITE_MOVES = {**NM.TOKEN_MOVES, "by hand": "go_on_as_is", "reapprove": NM.SITE_DOOR}

    def site_seam_person(self, kind: str, text: "Priced", stage: str, *, block: str = "", details: str = "", answer_note: str = "") -> "Person":
        """A site's own closed question (`text` from `closed_question`) as a SEAM question (A7): the Person carries the tokens the
        text priced, each with its move (`SITE_MOVES`), and the block code knows, so `ask()` writes them into `asked` and
        `take_seam_answer` carries out `retry` / `go on` / `stop` with the seam's own executors."""
        tokens = [token for token in getattr(text, "priced", ()) if token in self.SITE_MOVES]
        person = Person(kind, text, stage, details=details, answer_note=answer_note)
        person.offered = tuple(tokens)      # the SITE_MOVES keys are already the normalized tokens (lower case, one space)
        person.options = [{"token": token, "move": self.SITE_MOVES[token]} for token in tokens]
        person.block = block
        return person

    @staticmethod
    def stop_held(then: str = "") -> str:
        """The first line of a question held after the person said to stop (FR-7: it comes back changed). ONE text for every
        site that holds a question on `stop`; `then` says how to go on after all."""
        return "You said to stop. Nothing runs and nothing is spent." + (" " + then if then else "")

    DETAILS_POINTER = "The factory's own words about this"       # the line `ask()` writes, and `held_question` looks for

    def held_question(self, lead: str, details: str | None = None) -> Person:
        """THE helper that brings the open question back (exit 3) with `lead` above its body: a `stop` (`stop_held`), or a sentence
        that says what could not be done (a pass that failed, an answer that was not read). Built from the question file, still on
        disk while `take_answer` runs, and from `asked` (its kind, stage, dispatch, and for a question the seam raised its tokens,
        options, words file, why and block - so the same tokens read the next answer). `details`: None keeps the details file the
        question points to, a text replaces it. A question that is ALREADY held loses ITS lead before the new one goes on: a second
        `stop`, or an unread answer after an unread answer, never stacks leads (t-684 F7, t-689 F-2). The lead is known by its
        extent, not by its words (FR-12): `ask()` keeps the lead this helper put on the question in `asked["held_lead"]`, and that
        exact text is what comes off the front of the body. Nothing of the lead lives in the question's own body."""
        asked = self.state.get("asked") or {}
        qtext = self.question_path().read_text(encoding="utf-8", errors="replace") if self.question_path().is_file() else ""
        body = QUESTION_HEAD_RE.sub("", ANSWER_BLOCK_RE.sub("", qtext), count=1).strip()
        held = str(asked.get("held_lead") or "").strip()
        if held and body.startswith(held):
            body = body[len(held):].strip()
        if details is None:
            file = self.state_dir / "driver-question-details.md"
            named = file.is_file() and self.DETAILS_POINTER in qtext     # a file the question itself points to
            said = re.search(r"```\n(.*)\n```", file.read_text(encoding="utf-8", errors="replace"), re.S) if named else None
            details = said.group(1) if said else ""
        again = Person(asked.get("kind", ""), lead + "\n\n" + body, asked.get("stage", ""), asked.get("dispatch", ""), details=details)
        again.offered, again.options = tuple(asked.get("offered") or ()), list(asked.get("options") or [])
        again.words_file, again.why, again.block = str(asked.get("words_file") or ""), str(asked.get("why") or ""), str(asked.get("block") or "")
        again.held_lead = lead.strip()
        again.why_person = PO.as_class(asked.get("why_person"))          # the same question keeps its class (`waiver_road`)
        again.rows = tuple(str(i) for i in asked.get("rows") or ())     # the same question: it keeps the rows it was about
        again.probe_gap_cases = tuple(str(c) for c in asked.get("probe_gap_cases") or ())   # the same question keeps the cases it named
        again.probe_judgment_cases = tuple(str(c) for c in asked.get("probe_judgment_cases") or ())   # (t-1968 N5) as the line above
        again.sources, again.classes = tuple(asked.get("sources") or ()), tuple(asked.get("classes") or ())    # an `s1_gap` keeps what it named
        return again

    def pass_block(self, stage: str, block: str, words_file: str, lead: str) -> None:
        """THE write-or-hold of a pass by the person's word (t-698 A13, t-781 m6): ONE `waiver.py` row for `block` at `stage`, the
        words by FILE (`words_file`: task-root relative). A row `waiver.py` refuses - or a `waiver.py` that cannot run at all - is
        printed and HELD (`lead` above the command's own output): nothing is passed in silence. Callers: the exit-limit `go on`
        (`_exit_go_on`), the seam's `go on` with a block (`take_seam_answer`) and the `go on` of a closed-by-code stage
        (`_answer_code_close`); the next one is b1's `_answer_repair_limit` (queued)."""
        code, out = self.py("waiver.py", "--task", self.task, "--stage", stage, "--block", block, "--words-file", str(self.task_root / words_file),
                             *self.waiver_road())
        if code:
            print(f"{stage}: the pass was not recorded ({out[-300:]}); the question comes back")
            raise self.held_question(lead, out)

    def after_close(self, stage: str, words: str) -> None:
        """THE short-circuit of an answer that arrives after its stage is done already: say so and put the person's words on the journal;
        the caller goes on. Callers: `_answer_exit_limit`, `_answer_code_close`, `take_seam_answer` and the conductor/refusal branch of
        `take_answer`. What each caller returns afterwards stays its own."""
        print(f"{stage} is done already; recording the words and going on")
        self.answer_row(f"{stage} (after close): ", words.strip(), what="your answer after the stage was closed")

    def question_from_refusal(self, refusal, stage: str, dispatch: str = "") -> str:
        """The LEAD of the question to ask when nobody wrote one: where the story is and that the reason cannot be put in its own
        words. The options come from the seam (`fallback_person`: the `fallback` block, each with its three price lines, C1-1).

        `ask_person` with an empty `question` came back sixteen times in seventy-six conductor
        sessions of run 5, and the driver turned each into "The conductor needs your word."
        plus the refusal's own text. That is not a question, so the answer was free prose, and
        reading it back cost another conductor session - the most expensive family of the run
        ($9.01 over 21 sessions). The driver cannot translate the refusal, but it does know
        where the story is and what the three standing answers are, and that is a question."""
        stages = {}
        try:
            stages = self.stages()
        except Exception:
            pass
        name = str((stages.get(stage) or {}).get("name") or "").strip().lower()
        where = f"the {name} stage ({stage})" if name and stage else (f"stage {stage}" if stage else "this story")
        done = [f"S{i}" for i in range(10)
                if str(((self.pipeline().get("stages") or {}).get(f"S{i}") or {}).get("status") or "") == "done"]
        return (
            f"The story has reached {where}" + (f", with {len(done)} stage(s) behind it" if done else "") +
            ", and a check of the factory's own refused to let it go on.\n\n"
            "I cannot put that check's reason into the story's own words — it is written for the "
            "role that ran it, not for you. That is a defect of ours and it is recorded as one; "
            "the words themselves are in the file named below, if you want them.")

    @staticmethod
    def s1_exit_gate(text: str) -> str:
        """The scout dispatch an S1 exit-gate refusal names, or '' when the text is not one."""
        m = re.search(S1_DISPATCH_RE, text or "")
        return m.group(1) if m else ""

    def _answer_s1_gap(self, words: str, asked: dict, qtext: str, stage: str, dispatch: str) -> bool:
        """The executor of an answer to the `s1_gap` question (C2-9). Code reads TOKENS and a structural sign (a fence), never a
        phrase (FR-12). True when the answer was taken; False sends it down the road it had (free words, the conductor).
        POSITION INVARIANT: called only for kind `s1_gap`, before the `offered` branch - the question carries no `offered`, and an
        answer to a question of another kind never reaches here. The sources and kinds are the ones the QUESTION named
        (`asked.sources` / `asked.classes`), not whatever the inventory holds now (I4: a kind is written only for what was shown)."""
        inventory = self.task_root / "work" / "source-inventory.json"
        sources, classes = list(asked.get("sources") or []), list(asked.get("classes") or [])
        token = self.s0_normalize(words)
        inv_rel = f"qa-factory/artifacts/{self.task}/work/source-inventory.json"
        if not inventory.is_file():
            return False
        if token in ("skip all like these", "not needed") and not sources:
            print("s1_gap: the question named no source the factory can record the word for; the conductor reads it")
            return False
        if token == "skip all like these" and classes:
            return self._accept_gap_kinds(words, sources, classes, qtext, inv_rel)
        if token == "not needed":
            return self.record_gaps(qtext, words, ids=sources)
        if "```" in (words or ""):
            pasted = self.record_pasted(set(sources), words)
            if pasted:
                self.answer_row("S1 material supplied by the person: " + "; ".join(pasted)[:1500], "", what="the note of the material you supplied")
                return True
        return False

    def _accept_gap_kinds(self, words: str, sources: list, classes: list, qtext: str, inv_rel: str) -> bool:
        """`skip all like these`: the person's word for the KINDS the question offered (one `accept-gap --cause` call), then for the
        points of the named sources that have no cause at all (one `--point` call per source). The first call writes the kinds; a
        refusal of it leaves nothing recorded. A refusal of a later call leaves the kinds ON DISK, and the text says so."""
        import source_inventory as SI
        shown = " ".join(line.strip() for line in qtext.splitlines() if line.startswith("- "))[:1500]
        code, recorded = self.py("ticket_adapter.py", "accept-gap", "--output", inv_rel, "--cause", ",".join(classes),
                                 "--shown-text", shown, *self.words_args(words, "s1gap"))
        if code:
            # remains: the person's own question comes back with the refusal's words, nothing was accepted (FR-59)
            raise self.held_question("Your word could not be recorded as the acceptance, so nothing was accepted.", recorded)
        inv = SI.load_inventory(self.task_root / "work" / "source-inventory.json")
        summary = SI.completeness(inv, **SI.class_kwargs(self.task_root))
        for item in inv.get("sources") or []:
            sid = item.get("source_id")
            open_ids = (summary.get("open_points") or {}).get(sid) or []
            bare = [p["id"] for p in SI.gap_points(item)
                    if p["class"] == SI.POINT_GAP and not SI.point_cause(item, p) and p["id"] in open_ids]
            if sid not in sources or not bare:
                continue
            code, out = self.py("ticket_adapter.py", "accept-gap", "--output", inv_rel, "--source-id", sid,
                                "--point", ",".join(bare), *self.words_args(words, "s1gap"))
            if code:
                # remains: the person's own question comes back with the refusal's words; the kinds are on disk and say so (FR-59)
                raise self.held_question(
                    f"Your word was recorded for the kinds of gap ({', '.join(classes)}) and covers every later one of them, "
                    "but not for the other points of this question.", recorded.strip() + "\n" + out)
        self.answer_row(f"S1 gaps accepted by kind ({', '.join(classes)}): ", words.strip(), what="your word accepting the gaps by kind")
        return True

    def record_gaps(self, text: str, words: str, ids: list | None = None) -> bool:
        """Every source named gets the person's words as its acceptance, by code. The names are `ids` (the sources a question
        `asked`) or, for the exit-gate refusal text of `record_s1`, the ids the gate printed in `text`. False when nothing is named or
        the inventory is missing.

        Content the person pasted is material, not an acceptance: it is recorded first, and only
        what is still missing afterwards becomes an accepted gap. The order matters — a run that
        accepted the gap first would file a source as unreachable in the same breath as receiving
        its content. A fenced answer is content (a structural sign): it is never ALSO an acceptance, and no phrase of the
        person's makes it one (FR-12)."""
        inventory = self.task_root / "work" / "source-inventory.json"
        ids = sorted(set(ids if ids is not None else re.findall(S1_GAP_RE, text or "", re.IGNORECASE)))
        if not ids or not inventory.is_file():
            return False
        pasted = self.record_pasted(set(ids), words)
        if "```" in (words or ""):
            # POSITION INVARIANT (C1-7a, F-1): on the FENCE, not on `pasted`. They answered with the content, not with a decision: a
            # fenced answer is never ALSO an acceptance, whatever `record_pasted` managed to record (no block read, none recorded:
            # the conductor reads the words, `False`).
            if not pasted:
                return False
            self.answer_row("S1 material supplied by the person: " + "; ".join(pasted)[:1500], "", what="the note of the material you supplied")
            return True
        code, out = self.py("ticket_adapter.py", "accept-gap", "--output",
                            f"qa-factory/artifacts/{self.task}/work/source-inventory.json",
                            "--source-id", ",".join(ids), *self.words_args(words, "s1gap"))
        if code:
            print(f"accept-gap failed (exit {code}): {out[-300:]}")
            return False
        self.answer_row(f"S1 gap accepted for {', '.join(ids)}: ", words.strip(), what="your word accepting the gap")
        return True

    def record_s1(self, text: str, words: str) -> bool:
        """An S1 exit-gate refusal answered by the person: the review and the gaps it names
        are recorded by code; the scout resumes on the words. False when the text names
        nothing code can record (the conductor takes over)."""
        did = False
        if re.search(S1_REVIEW_RE, text or "", re.IGNORECASE):
            did = self.record_review(words) or did
        if re.search(S1_GAP_RE, text or "", re.IGNORECASE):
            did = self.record_gaps(text, words) or did
        if not did and self.s1_exit_gate(text) and (self.task_root / "work" / "source-inventory.json").is_file():
            # Nothing left for the person to record: the refusal is the scout's own work
            # (receipts, the form). The words go to the scout as they are.
            self.answer_row("S1: ", words.strip(), what="your answer at the source review")
            did = True
        return did

    def excluded_heads(self) -> list:
        """The head commits of what the person left out before the run (B-231, C2): the full ids
        `source_exclusions.py` holds for a merge request (`target.head_sha`) or a commit word
        (`target.sha`). [] with no list or none resolved: then `git_route` skips nothing.

        A record that exists and cannot be read raises a refusal that names the file: the git door
        must never run past the person's word because the word could not be read."""
        import source_exclusions as SE
        try:
            live = SE.live(self.task_root)
        except SE.ExclusionRecordError as exc:
            raise Refusal(str(exc))
        heads = []
        for exclusion in live:
            target = exclusion.get("target") or {}
            # A null head (the lookup failed) is no head: `str(None)` here once gave the word 'None', and
            # `git_route` then ran a pointless rev-parse of it for every commit it listed.
            value = target.get("head_sha") if target.get("kind") == "mr" else target.get("sha")
            sha = value.strip() if isinstance(value, str) else ""
            if sha and sha not in heads:
                heads.append(sha)
        return heads

    @staticmethod
    def only_from_excluded_head(checkout: Path, commit: str, heads: list) -> bool:
        """Is `commit` reachable from an excluded head and from nothing else (two `git` calls per head).

        INVARIANT: in doubt it is NOT skipped. A head this checkout does not hold, a commit it does not
        hold, an abbreviated id that resolves to nothing, a timeout: all answer False, so the route reads
        what it read before. A commit that a branch such as `main` also carries is not the excluded
        request's own change (an older commit of the same ticket prefix is an ancestor of every branch
        cut after it), so a ref whose tip is not an excluded head makes the answer False."""
        def git(*args):
            return subprocess.run(["git", "-C", str(checkout), *args], capture_output=True, text=True,
                                  encoding="utf-8", errors="replace", timeout=30)
        try:
            full = []
            for head in heads:
                done = git("rev-parse", "--verify", "--quiet", f"{head}^{{commit}}")
                if done.returncode == 0 and done.stdout.strip():
                    full.append(done.stdout.strip())
            if not full or not re.fullmatch(r"[0-9a-fA-F]{7,64}", commit or ""):
                return False
            for head in full:
                if git("merge-base", "--is-ancestor", commit, head).returncode != 0:
                    continue
                tips = git("for-each-ref", "--contains", commit, "--format=%(objectname)")
                found = [line.strip() for line in tips.stdout.splitlines() if line.strip()]
                if tips.returncode == 0 and found and all(tip in full for tip in found):
                    return True
        except (OSError, subprocess.TimeoutExpired):
            return False
        return False

    def git_route(self, url: str, rel: str) -> str:
        """Route 2 for a merge request: the local checkout of the same project. `refs/merge-requests`
        exist only while an MR is open (githost prunes them on merge — 3758 and 3890 are gone while
        the listing runs to 4346), but a merged MR's own commits are in the history, so the CHANGE is
        readable offline. What this route cannot give is the description and the discussions, which
        is why what it produces is recorded `partial` and never `read`. Returns a note naming the
        commits, or "" when this route has nothing either."""
        project = str(url).split("/-/merge_requests/")[0].rsplit("/", 1)[-1]
        # The ticket's PREFIX is the project's own key form (`adapter_forms`, B-405): `MY_PROJ-12` is `MY_PROJ`,
        # and a prefix-less form (a numeric story on GitHub issues) has none. With none, the commits are not searched
        # by `--grep=<prefix>-` (an empty prefix would read `--grep=-`, every commit with a hyphen); the merge-request
        # ref is still asked, and the line says what was skipped.
        form = AF.key_form(self.config, floor=True)
        prefix = (AF.prefix_of(self.task, form)
                  if AF.is_key(self.task, self.config) and not self.s0_is_local() else None)    # `LOCAL-` is no commit prefix (SS1-14 m5)
        if prefix is None:
            print(f"local git route: task {self.task!r} has no project prefix in its key form ({form.source}), "
                  "so the commits are not searched by prefix; only the merge-request ref is asked")
        heads = self.excluded_heads()
        wanted = self.list_tail(project)
        for repo in self.config.get("implementation_repos") or []:
            identity = str(repo.get("remote_identity") or "")
            local = str(repo.get("local_path") or "")
            # The entry is selected by WHOLE tail, as `repo_of_project` does (B-412, critic t-554 F2): by substring
            # `testproject1` was "in" `.../testproject1-ui`, and the first such entry answered for the wrong project.
            if not local or not wanted or wanted != self.list_tail(identity):
                continue
            # B-412: the checkout may be a folder inside a repository (a monorepo); `want` keeps an enclosing
            # repository of ANOTHER project from being asked.
            checkout, _top, why = self.checkout_for(repo, want=wanted)
            if not checkout:
                if why:
                    print(f"local git route: {why}")
                continue
            # The number comes from the regex's own digits: the URL may still carry a trailing `.` or `**`.
            found = re.search(r"/merge_requests/(\d+)", str(url))
            iid = found.group(1) if found else str(url).rstrip("/").rsplit("/", 1)[-1]
            for query in (["ls-remote", "origin", f"refs/merge-requests/{iid}/head"],
                          *([["log", "--all", "--format=%H%x09%s", f"--grep={prefix}-", "--max-count=20"]]
                            if prefix else [])):
                done = subprocess.run(["git", "-C", str(checkout), *query], capture_output=True,
                                      text=True, encoding="utf-8", errors="replace", timeout=120)
                if done.returncode or not done.stdout.strip():
                    continue
                # A commit that only an excluded head carries is the excluded merge request's own change,
                # reached by the git door instead of the API one (t-172 C2: live testproject1-ui keeps MR 1924
                # under a branch name with no "1924" in it, and `--grep=TP1-` lists its commit).
                lines, skipped = [], []
                for line in done.stdout.strip().splitlines():
                    sha = line.split("\t")[0].strip()
                    if heads and self.only_from_excluded_head(checkout, sha, heads):
                        skipped.append(sha)
                    else:
                        lines.append(line)
                for sha in skipped:
                    print(f"local git route: {sha[:12]} is left out: only a merge request you asked me not to "
                          "read carries it")
                if not lines:
                    continue
                done.stdout = "\n".join(lines)
                target = self.task_root / "work" / rel
                target.parent.mkdir(parents=True, exist_ok=True)
                body = [f"# Local git route for {url}", f"checkout: {local}", f"query: git {' '.join(query)}",
                        "", done.stdout.strip(), ""]
                shas = [line.split("\t")[0] for line in done.stdout.strip().splitlines()][:4]
                for sha in shas:
                    show = subprocess.run(["git", "-C", str(checkout), "show", "--stat", "--patch", sha],
                                          capture_output=True, text=True, encoding="utf-8",
                                          errors="replace", timeout=180)
                    body += [f"## git show {sha}", show.stdout[:200000], ""]
                target.write_text("\n".join(body), encoding="utf-8")
                return (f"the local checkout {local} carries the change as "
                        + ", ".join(sha[:9] for sha in shas))
        return ""

    def close_vcs_gaps(self, errors: list) -> bool:
        """A merge-request URL that arrived as ticket material is not a web page for a role to
        open: the factory has an authenticated read-only collector for it (`vcs_evidence.py`), and
        code runs it, not the role.

        TP1-13797, 26.09: four MR pages of the precedent ticket were filed `unavailable` with
        the reason "superseded closed precedent MR; content already captured from ticket text" and
        offered to the person as a gap to accept — while every one of them collects clean through
        the API (16 notes, 16 discussions, 9 diffs, revision pinned). The collector was named only
        for the implementation MR in the S0 phase file; a URL that arrives in a comment goes to
        `external_media`, where a role has two verbs (`read --local-ref`, `unavailable --reason`)
        and no web tool. Nothing between the URL and the script that reads it was code. This is it.
        True when something was collected, so the caller re-reads the gate instead of asking."""
        inventory_rel = f"qa-factory/artifacts/{self.task}/work/source-inventory.json"
        inventory = _read_json(self.task_root / "work" / "source-inventory.json")
        ids = {found for error in errors for found in re.findall(S1_GAP_RE, error or "", re.IGNORECASE)}
        if not ids:
            # The gate complains about material in more than one wording, and only the "unaccepted
            # gap" one carries a source id: "materials not inspected" names none. Material that is
            # merely `pending` is the normal case — four merge requests of the precedent ticket sat
            # `pending` while the ladder waited for a gap to be declared first. With no id to go on,
            # every source is fair game: collecting is idempotent and skips what is already read.
            ids = {str(source.get("source_id")) for source in inventory.get("sources") or []}
        collected = False
        for source in inventory.get("sources") or []:
            if source.get("source_id") not in ids:
                continue
            block = (source.get("materials") or {}).get("external_media") or {}
            for entry in block.get("items") or []:
                url = str(entry.get("url") or "")
                # The inventory keeps the URL as the comment wrote it (markdown escaping and all);
                # the collector needs the real one, and the record is updated by the stored one.
                target = normalize_url(url)
                # `excluded`: the person said before the run not to read it (B-231). This skip sits before
                # `vcs_evidence`, and it holds in the "every source is fair game" branch too.
                if entry.get("status") in ("read", "excluded"):
                    continue
                # B-405: what the link IS comes from `ticket_light.classify_url` (reference-kinds.json), against its PATH
                # only: a merge-request path inside a query string is no request. The number is group 2 of the kind's own
                # rule and must END the path or be followed by `/` (`/-/merge_requests/5/diffs` is request 5, `.../5a` is
                # none). A pull request is not sent to `vcs_evidence`, a GitLab collector: one line says why and the item
                # stays pending. Every error direction is toward "not a request" - never a link collected without a receipt.
                try:
                    kind, _host, found = TL.classify_url(target)
                except TL.TableError as exc:
                    print(f"merge requests are not collected: {exc}")
                    return collected
                if kind not in TL.MR_KINDS or not found or (found.end(2) < len(found.string)
                                                            and found.string[found.end(2)] != "/"):
                    continue
                if kind == "pull_request":
                    print(f"{target} is a pull request: vcs_evidence reads GitLab merge requests only, so it is left "
                          "pending for the person (a GitHub collector is not part of the factory yet)")
                    continue
                iid = found.group(2)
                rel = f"sources/{source['source_id']}/mr-{iid}.json"
                (self.task_root / "work" / rel).parent.mkdir(parents=True, exist_ok=True)
                code, out = self.py("vcs_evidence.py", "--url", target, "--output",
                                    f"qa-factory/artifacts/{self.task}/work/{rel}")
                receipt = _read_json(self.task_root / "work" / rel)
                status, reason = "read", ""
                if code or receipt.get("status") != "read":
                    # Route 1 (the authenticated API) did not answer. Route 2 is the local checkout:
                    # it carries the change, never the discussion, so what it gives is `partial`.
                    cause = str(receipt.get("error") or "")
                    print(f"vcs_evidence could not collect {url}: {cause or out[-200:]}")
                    note = self.git_route(target, f"sources/{source['source_id']}/mr-{iid}-git.md")
                    if not note:
                        # C2-9 (N9): the API did not answer and no local route has the change. When the collector's receipt
                        # carries a code the factory's table knows, the CODE records the verdict, with the receipt as its
                        # carrier (`--probe-ref`) - a role's copy of it is no carrier. A code the table does not know, or no
                        # receipt at all, writes nothing: the item stays pending, the road it had (the unknown is asked).
                        if self.record_unreachable(source, entry, url, rel, cause, inventory_rel):
                            collected = collected or entry.get("probe_code") != cause or entry.get("status") != "unavailable"
                        continue
                    rel = f"sources/{source['source_id']}/mr-{iid}-git.md"
                    status = "partial"
                    reason = (f"partial_route: the API route answered `{cause}`; {note}, which is the "
                              "change only — the MR description and its discussions are not in it")
                    print(f"local git route: {url} -> work/{rel} ({note})")
                elif not receipt.get("complete", True):
                    status = "partial"
                    reason = (f"partial_route: vcs_evidence collected the MR but marked it incomplete "
                              f"({receipt.get('error') or 'complete: false'})")
                code, out = self.py("ticket_adapter.py", "inspect", "--output", inventory_rel,
                                    "--source-id", source["source_id"], "--media-url", url,
                                    "--inspection-status", status, "--local-ref", rel,
                                    *(("--reason", reason) if reason else ()))
                if code:
                    print(f"collected {url} but recording it failed: {out[-200:]}")
                    continue
                digest = self.material_digest(rel, receipt) if status == "read" else ""
                self.state.setdefault("collected", {}).setdefault(str(source["source_id"]), []).append(
                    f"{url} -> work/{rel}" + (f" (+ {digest})" if digest else ""))
                print(f"collected by code ({status}): {url} -> work/{rel}"
                      + (f" (revision {str(receipt.get('revision'))[:12]}, "
                         f"{len(receipt.get('discussions') or [])} discussions"
                         + (f"; digest {digest}" if digest else "") + ")" if status == "read" else ""))
                collected = True
        return collected

    def _defaulted_vcs(self) -> bool:
        """Does the summary hold a gap by default whose carrier is a collector receipt (`host_unreachable`)? False when the
        inventory cannot be read - then nothing is retried that was not retried before."""
        import source_inventory as SI
        try:
            inventory = SI.load_inventory(self.task_root / "work" / "source-inventory.json")
            summary = SI.completeness(inventory, **SI.class_kwargs(self.task_root))
        except Exception:
            return False
        return any(point.get("cause") == "host_unreachable"
                   for points in (summary.get("defaulted_points") or {}).values() for point in points)

    def record_unreachable(self, source: dict, entry: dict, url: str, rel: str, code: str, inventory_rel: str) -> bool:
        """The code writes `unavailable` for a merge request the collector could not reach, with the cause the table of
        references/source-causes.json gives the collector's code and the receipt as `--probe-ref`. False (nothing written) for a
        code the table does not know or none: the item stays pending and is asked - the unknown is never a default."""
        import source_inventory as SI
        try:
            cause = SI.cause_table()["vcs_codes"].get(code) if code else None
        except ValueError:
            cause = None
        if not cause:
            print(f"vcs_evidence answered {code or 'nothing'}, which the factory's table does not know: the item stays pending")
            return False
        done, out = self.py("ticket_adapter.py", "inspect", "--output", inventory_rel, "--source-id", source["source_id"],
                            "--media-url", url, "--inspection-status", "unavailable",
                            "--reason", f"{cause}: vcs_evidence answered {code}", "--probe-ref", rel)
        if done:
            print(f"vcs_evidence answered {code} for {url} but recording it failed: {out[-200:]}")
            return False
        return True

    def record_pasted(self, ids: set, words: str) -> list:
        """The person's own last route: they read the material themselves and paste what matters.
        Text inside a fenced block of their answer becomes material of the source, recorded with
        `provenance: person_pasted` — the record says where it came from instead of implying the
        factory fetched it. Returns one line per file recorded."""
        blocks = [b.strip() for b in re.findall(r"```[a-zA-Z0-9_-]*\n(.*?)```", words or "", re.S) if b.strip()]
        if not blocks:
            return []
        inventory_rel = f"qa-factory/artifacts/{self.task}/work/source-inventory.json"
        inventory = _read_json(self.task_root / "work" / "source-inventory.json")
        done, failed, taken = [], [], set()
        for source in inventory.get("sources") or []:
            if source.get("source_id") not in ids:
                continue
            open_items = [i for i in ((source.get("materials") or {}).get("external_media") or {}).get("items") or []
                          if i.get("status") in {"pending", "unavailable", "partial", None}]
            for index, block in enumerate(blocks, start=1):
                named = [i for i in open_items if str(i.get("url") or "") and str(i["url"]) in (words or "")]
                target_item = named[0] if len(named) == 1 else (open_items[0] if len(open_items) == 1 else None)
                if not target_item:
                    continue
                rel = f"sources/{source['source_id']}/pasted-{index}.md"
                path = self.task_root / "work" / rel
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(f"<!-- pasted by the person on {_now()} for {target_item['url']} -->\n\n"
                                + block + "\n", encoding="utf-8")
                code, out = self.py("ticket_adapter.py", "inspect", "--output", inventory_rel,
                                    "--source-id", source["source_id"], "--media-url", target_item["url"],
                                    "--inspection-status", "read", "--local-ref", rel,
                                    "--provenance", "person_pasted")
                if code:
                    print(f"recording pasted material failed: {out[-200:]}")
                    failed.append((index, f"{target_item['url']} ({out.strip()[-200:] or 'the tool said nothing'})"))
                    continue
                done.append(f"{target_item['url']} <- work/{rel} (pasted by the person)")
                taken.add(index)
                open_items = [i for i in open_items if i is not target_item]
        for line in done:
            print(f"material from the person: {line}")
        # Q1 (C1-7a, F-1): a block that was not recorded - its `inspect` failed, or no open item could be named for it - is the person's own
        # question back, with what IS recorded and what is not. POSITION INVARIANT: inside this function, before it returns to
        # `record_gaps` / `_answer_s1_gap`, so a block that was not recorded never reaches `accept-gap` as if it were a decision.
        lost = [index for index in range(1, len(blocks) + 1) if index not in taken]
        if lost:
            # remains: the person's own question comes back with what is written and what is not (FR-10, the t-366 F2 pattern)
            raise self.held_question(
                f"{len(lost)} of the {len(blocks)} text(s) you pasted could not be recorded, so nothing was recorded for "
                f"{'it' if len(lost) == 1 else 'them'}; your answer was not taken as accepting the gap. "
                + (f"Recorded: {'; '.join(done)}. " if done else "Nothing of what you pasted was recorded. ")
                + "Say which source each text is for (name its link), or answer in your own words.",
                "\n".join(tool for _index, tool in failed) or "no open item of the named sources could be matched to the text")
        return done

    def material_digest(self, rel: str, receipt: dict) -> str:
        """A merge request's own words, unpacked from its receipt — not summarised.

        The API receipt is evidence and it is huge: the precedent's four came back at 79 KB, 183 KB,
        965 KB and **3.8 MB**, nearly all of it diff hunks. A brief that names a 3.8 MB JSON has
        delivered nothing — the guard refuses a whole read at 30 KB and the role would slice blind.

        What code does here is EXTRACTION, never judgement: the title, the state, the branches, the
        revision, the description exactly as its author wrote it, every human review comment in
        full, and the list of files the change touched. Nothing is shortened and nothing is chosen
        as important — choosing is the reading role's work, and the hunks stay one line away in the
        evidence file this names. (The first version of this method capped comments at 25 and cut
        each at 400 characters; on a merge request with 101 discussions that cap is code deciding
        which review thread matters, which is exactly what it must not do.)"""
        meta = receipt.get("metadata") or {}
        if not meta:
            return ""
        target = self.task_root / "work" / rel.replace(".json", ".md")
        lines = [f"# {meta.get('title') or 'merge request'}", "",
                 f"- url: {receipt.get('url')}",
                 f"- state: {meta.get('state')}, merged_at: {meta.get('merged_at')}",
                 f"- branches: {meta.get('source_branch')} -> {meta.get('target_branch')}",
                 f"- revision: {receipt.get('revision')}",
                 f"- evidence (full, machine-readable): work/{rel}", "",
                 "## What its author wrote", "", str(meta.get("description") or "(no description)").strip(), ""]
        notes = [n for n in (receipt.get("notes") or []) if isinstance(n, dict) and not n.get("system")]
        people = [n for n in notes if not _is_bot(n.get("author") or {})]
        machines = [n for n in notes if _is_bot(n.get("author") or {})]
        if people:
            lines += [f"## Review, {len(people)} comment(s) by people, each in full", ""]
            kept, moved = [], []
            for index, note in enumerate(people, start=1):
                body = str(note.get("body") or "")
                if len(body) <= BIG_COMMENT_BYTES:
                    kept.append(note)
                    continue
                # Too big to inline is not the same as unimportant, and code cannot tell the
                # difference: a pasted build log and a decisive design argument look alike by
                # size. So the rule is size alone, and what moves leaves its address behind.
                side = self.task_root / "work" / rel.replace(".json", f"-comment-{index}.md")
                side.write_text("\n".join(_note_lines([note])) + "\n", encoding="utf-8")
                who = ((note.get("author") or {}).get("name") or "?")
                moved.append(f"- **{who}**, {len(body) // 1024} KB — in full: "
                             f"work/{side.relative_to(self.task_root / 'work').as_posix()} "
                             f"(first line: {body.strip().splitlines()[0][:120] if body.strip() else ''})")
            lines += _note_lines(kept)
            if moved:
                lines += [f"### {len(moved)} comment(s) too large to inline — moved whole, "
                          "not shortened and not judged", ""] + moved + [""]
        if machines:
            # Not judged as unimportant — moved, and said so. On !1522 the 101 "comments" were
            # mostly a CI bot pasting pipeline logs: keeping them inline made the digest 1.7 MB,
            # which is the 3.8 MB problem again. The split is by WHO wrote it, which is a fact in
            # the payload, not an opinion about what matters.
            side = self.task_root / "work" / rel.replace(".json", "-machine.md")
            side.write_text(f"# Machine comments on {receipt.get('url')}\n\n"
                            + "\n".join(_note_lines(machines)) + "\n", encoding="utf-8")
            lines += [f"## {len(machines)} comment(s) by machine accounts (CI, bots)", "",
                      f"Moved, not dropped — all of them, in full: work/{side.relative_to(self.task_root / 'work').as_posix()}", ""]
        diffs = [d for d in (receipt.get("diffs") or []) if isinstance(d, dict)]
        if diffs:
            lines += [f"## Files it touched ({len(diffs)})", ""]
            lines += [f"- {d.get('new_path') or d.get('old_path')}" for d in diffs]
        target.write_text("\n".join(lines) + "\n", encoding="utf-8")
        return f"work/{rel.replace('.json', '.md')} ({target.stat().st_size // 1024} KB)"

    def pass_to_person(self, verdict: dict, kind: str, stage: str, dispatch: str) -> None:
        """`ask_person` carries the question; without one it is the conductor failing its own
        contract, not a question. TP1-13797, 26.09: one such answer cost $1.27 and 21 turns,
        recorded nothing (`did` empty) and reached the person as the driver's filler sentence
        "The conductor needs more." — no file, no refusal, no decision in it. The driver does not
        invent the words: the failure is printed and journalled as the factory's own, and the loop
        goes back to `where`. A block that really stands comes back with its own text."""
        question = str(verdict.get("question") or "").strip()
        # RN1-9 (E-8): a question with no class or no `checked` is the same exit as an empty one; `ConductorSpent` bounds the loop.
        rule = PO.question_rule(verdict.get("why_person"), verdict.get("checked")) if question else ""
        if question and not rule:
            person = Person(kind, question, stage, dispatch)
            person.why_person, person.checked, person.source = (PO.normalize(verdict.get("why_person")),
                                                                PO.checked_text(verdict.get("checked")), "conductor")
            raise person
        did = str(verdict.get("did") or "").strip()
        if rule:
            print(f"conductor: ask_person without a class at {stage}:{dispatch} - {rule[:160]}; back to `where`")
            self.file_defect(dispatch, f"owner: factory — the conductor answered `ask_person` without a class of "
                                       f"references/{PO.FILE_NAME} or without what it read at {stage}:{dispatch} "
                                       f"({rule[:300]}); the driver went on instead of asking the person")
            return
        print(f"conductor: ask_person with no question at {stage}:{dispatch} — its own contract "
              f"failure, not a question for the person (did: {did[:120] or 'nothing'}); back to `where`")
        self.file_defect(dispatch, f"owner: factory — the conductor answered `ask_person` with an empty question "
                                   f"at {stage}:{dispatch} (did: {did[:300] or 'nothing'}); the driver went on "
                                   "instead of handing the person a filler sentence")

    GAP_TEXT_MAX = 6000     # bytes of the body of the `s1_gap` question; the rest of the list is in the details file (t-720 F-2)

    def s1_gap_lines(self, ids: list, inventory: dict, summary: dict) -> tuple:
        """`(source_lines, access, sources, causes)` of the points the person is ASKED about: the gap points of the named sources
        that the summary still holds open (a point closed by a word, a kind, or by the factory's own verdict is not one of them).
        `sources` / `causes` are ALL the asked ones, shown or not - the tokens close exactly what was named (C2-9)."""
        import source_inventory as SI
        out, access, sources, causes = [], [], [], set()
        for item in inventory.get("sources") or []:
            sid = item.get("source_id")
            if sid not in ids:
                continue
            key = str(item.get("canonical_ref") or "").rsplit("/", 1)[-1]
            open_ids = set((summary.get("open_points") or {}).get(sid) or [])
            gone = []
            for point in SI.gap_points(item):
                if point["id"] not in open_ids or point["class"] != SI.POINT_GAP:
                    continue
                cause = SI.point_cause(item, point)
                if cause:
                    causes.add(cause)
                if point["id"] == "source:unavailable":
                    gone.append(f"the ticket itself ({item.get('exclusion_or_error') or 'unavailable'})")
                    continue
                if point["kind"] == "block":
                    gone.append(point["id"].split(":")[0])
                    continue
                entry = SI._point_row(item, point) or {}
                # An attachment keeps its name in `filename` and its cause in `analysis_*`; media keep theirs in `url`/`error`.
                # Reading only the media spelling is how the person got "attachment: ? - no cause recorded" about a file whose
                # receipt named both the size and the missing tool.
                name = entry.get("filename") or entry.get("name") or entry.get("url") or "?"
                why = str(entry.get("analysis_reason") or entry.get("error") or entry.get("analysis_cause")
                          or entry.get("cause") or "no cause recorded")
                gone.append(f"{point['kind']}: {name} — {why}")
                if cause in SI.ACCESS_CAUSES:
                    access.append(f"{key}: {name}")
            if gone:
                sources.append(sid)
                out.append(f"- {key} ({sid}): " + "; ".join(gone))
        return out, access, sources, sorted(causes)

    GAP_NAME_MAX = 100      # bytes of one name in the lists of the tail (the access list, the recorded-by-default list)
    GAP_LINE_MAX = 400      # bytes of one source line; the whole line is in the details file
    GAP_NAMES_SHOWN = 5     # names shown in each list of the tail, then `(+K more)`
    GAP_BODY_JOIN = 2       # the blank line between the body and the options: the body of the question is everything before them

    @staticmethod
    def clip_bytes(text: str, limit: int) -> str:
        """`text` cut to at most `limit` bytes of UTF-8 (on a character edge), with `...` when something was cut."""
        raw = str(text).encode("utf-8")
        return str(text) if len(raw) <= limit else raw[:max(limit - 3, 0)].decode("utf-8", "ignore") + "..."

    def name_list(self, names: list) -> str:
        """The first GAP_NAMES_SHOWN names (each clipped to GAP_NAME_MAX bytes), then `(+K more)`: a list of any length is bounded."""
        shown = [self.clip_bytes(name, self.GAP_NAME_MAX) for name in names[:self.GAP_NAMES_SHOWN]]
        return "; ".join(shown) + (f"; (+{len(names) - self.GAP_NAMES_SHOWN} more)" if len(names) > self.GAP_NAMES_SHOWN else "")

    def s1_gap_tail(self, summary: dict, access: list, options: list) -> list:
        """The lines after the source lines of the `s1_gap` question: what the factory recorded by itself, a damaged record of
        kinds, the lost-access paragraph (only when an access cause is ASKED), the routes already spent. Every part is bounded
        (the lists by `name_list`, the record's problem by `clip_bytes`), so the tail never eats the body's limit. The answers it
        refers to are read from `options`, the list the question is built from - by their words and their count, never by a
        position (a position moves when an answer is added in front of it)."""
        tail = []
        defaulted = [str(point["name"]) for points in (summary.get("defaulted_points") or {}).values() for point in points]
        if defaulted:
            tail.append(f"Already recorded as gaps, without a question: the factory established by itself that it cannot reach "
                        f"them - {len(defaulted)}: " + self.name_list(defaulted) + ". The report names each.")
        if summary.get("gap_class_problem"):
            tail.append(f"The record of your earlier answers about kinds of gaps could not be read "
                        f"({self.clip_bytes(summary['gap_class_problem'], 300)}), so every gap is asked again.")
        route = next((str(o["says"]).partition(":")[0] for o in options if o.get("answer") == "route"), "")
        if access:
            tail += ["", "**This reads as lost access, not as a missing source**: " + self.name_list(access)
                     + ". A dropped VPN or an expired login answers exactly this way. Check the access, "
                     f"then give the answer \"{route}\" and the collection runs again. "
                     "Accepting a gap here would put a reachable source on the record as unreachable."]
        count = {2: "Two", 3: "Three", 4: "Four"}.get(len(options), str(len(options)))
        tail += ["", "The factory's own routes are already spent on this: the authenticated API "
                 "(`vcs_evidence.py`) and the local checkouts. It has no browser — a headless role "
                 "cannot hold your session, and the factory does not carry credentials — so the "
                 "browser route belongs to whoever has the session. "
                 f"{count} answers work; anything else you say goes to the scout as it is."]
        return tail

    def s1_gap_more(self, left: int) -> str:
        return f"(+{left} more sources - the whole list is in the file named below)"

    def s1_gap_cap(self, head: list, tail: list, source_lines: list) -> tuple:
        """`(shown, cut)`: the source lines that fit the BODY of the `s1_gap` question - everything before the options, the blank
        line included - at most GAP_TEXT_MAX bytes; a body of exactly GAP_TEXT_MAX is printed whole, one byte more is cut. When
        cut, the printed lines are followed by ONE line `(+K more sources ...)`, whose bytes are reserved exactly; the whole list
        goes to the details file. Each printed line is clipped to GAP_LINE_MAX bytes, so a body with a source at all holds a line."""
        clipped = [self.clip_bytes(line, self.GAP_LINE_MAX) for line in source_lines]
        used = len("\n".join(head + tail).encode("utf-8")) + self.GAP_BODY_JOIN + (1 if clipped else 0)   # + the blank line
        sizes = [len(line.encode("utf-8")) + 1 for line in clipped]
        if used + sum(sizes) <= self.GAP_TEXT_MAX:
            return clipped, clipped != list(source_lines)       # a clipped line is the other reason for the details file
        fit = 0
        for count, size in enumerate(sizes, 1):
            used += size
            if used + len(self.s1_gap_more(len(clipped) - count).encode("utf-8")) + 1 <= self.GAP_TEXT_MAX:
                fit = count
            if used > self.GAP_TEXT_MAX:
                break
        return clipped[:fit] + [self.s1_gap_more(len(clipped) - fit)], True

    def s1_gap_options(self, causes: list) -> list:
        """The answers of the `s1_gap` question, in the order they are offered."""
        role = {"role": f"the {self.role_words('qa-scout')}"}
        kind_words = ", ".join(c.replace("_", " ") for c in causes)
        options = [
            {"answer": "not_needed", "token": "not needed",
             "says": "not needed: it is recorded as an accepted gap in your words"}]
        if causes:
            options.append({"answer": "not_needed_kind", "token": "skip all like these",
                            "says": "not needed, and the same for every later one that fails for the same reason in this story: "
                                    + kind_words})
        options += [
            {"answer": "route", "says": "here is how to reach it: name the route (a token, a CLI, a VPN to reconnect, a "
                                         "connector) and the collection runs again",
             "slots": {**role, "what": "give the route, or restore the access"}},
            {"answer": "content", "says": "here is the content: read it yourself (or have an agent with a browser read it) and "
                                           "paste what matters inside a ``` fence; it is saved as material of that source "
                                           "with `provenance: person_pasted`, so the record says where it came from",
             "slots": {"what": "read the source and paste what matters"}}]
        return options

    def s1_gap_text(self, refusal: str) -> str:
        """What is unavailable and STILL ASKED, per source the exit gate names, read from the inventory's own summary (the points,
        not the raw item statuses). A point the factory itself established as out of reach, or a kind of gap the person
        already answered, is not here: one line says how many are recorded without a question (D-0043)."""
        import source_inventory as SI
        ids = sorted(set(re.findall(S1_GAP_RE, refusal or "", re.IGNORECASE)))
        inventory = _read_json(self.task_root / "work" / "source-inventory.json")
        kinds = SI.class_kwargs(self.task_root)
        summary = SI.completeness(inventory, **kinds) if inventory.get("sources") else {}
        # The sources the gate NAMED are required by definition; the points asked are read for exactly those.
        named = {"sources": [dict(item, required=True) for item in inventory.get("sources") or [] if item.get("source_id") in ids]}
        source_lines, access, sources, causes = self.s1_gap_lines(ids, inventory, SI.completeness(named, **kinds))
        head = [f"Some source material of `{self.task}` cannot be reached:"]
        options = self.s1_gap_options(causes)
        tail = self.s1_gap_tail(summary, access, options)
        shown, cut = self.s1_gap_cap(head, tail, source_lines)
        lines = head + shown + ([""] if shown else []) + tail
        text = self.closed_question("s1.gap", "\n".join(lines), options)
        # What this question named, for its answer (the tokens close exactly this - never what the inventory holds later):
        # `ask()` writes them into `asked` for kind `s1_gap` only. The full list rides in `details` when the body was cut.
        text.sources, text.classes = tuple(sources), tuple(causes)
        text.details = ("The sources this question is about, whole:\n" + "\n".join(source_lines)) if cut else ""
        return text

    def record_review(self, words: str) -> bool:
        """The person's source-review words, recorded by code with the factory's own command.
        False when the inventory is not there to record into (the conductor takes over)."""
        inventory = self.task_root / "work" / "source-inventory.json"
        if not inventory.is_file():
            return False
        code, out = self.py("ticket_adapter.py", "review", "--record", "--output",
                            f"qa-factory/artifacts/{self.task}/work/source-inventory.json",
                            *self.words_args(words, "s1review"))
        if code:
            print(f"review --record failed (exit {code}): {out[-300:]}")
            return False
        self.answer_row("S1 source review: ", words.strip(), what="your source review")
        return True

    def has_left_out_list(self) -> bool:
        """Does this story carry the person's list of sources not to read (a live exclusion)? An unreadable
        record is reported by the writers that refuse over it; the review question is not one of them."""
        import source_exclusions as SE
        try:
            return bool(SE.live(self.task_root))
        except SE.ExclusionRecordError:
            return False

    def s1_review_text(self, digest: str) -> str:
        inventory = self.task_root / "work" / "source-inventory.json"
        code, table = self.py("ticket_adapter.py", "review", "--output",
                              f"qa-factory/artifacts/{self.task}/work/source-inventory.json")
        pipeline = self.pipeline()
        lines = [f"These are the sources I found for `{self.task}` and what I decided about each.", "",
                 table if code == 0 else digest, "",
                 "Kept sources will be read in full — comments, attachments, linked material. Left-out "
                 "ones are not downloaded."]
        if self.has_left_out_list():
            lines.append("The ones marked 'left out by you (before the run)' are not read; to read one after "
                         "all, name it in your answer.")
        # Four cases, exclusive (t-017 D2): a stand that is named and unconfirmed; no name with stands
        # to choose from; no name and none recorded; a stand that is named and confirmed. A story
        # written by the old S0 (`environment: null`, `environment_pending: false`) is the no-name
        # case, the same reading `stand_check` gives it.
        environment = pipeline.get("environment")
        if environment and pipeline.get("environment_pending"):
            lines.append(f"The stand `{environment}` did not answer when I checked it; planning goes "
                         "on, I check it again before the tests run; name another stand here if you "
                         "want one.")
        elif not environment and self.config.get("environments"):
            names = ", ".join(e.get("name", "") for e in self.config["environments"])
            lines.append(f"Which stand do I test on: {names}?")
        elif not environment:
            # t-363 B3, third site of the class: the plugin's command is something to TYPE, so it stands in the answer
            # block (human-questions.md rule 5) - ONE shape for the three sites (`Person.answer_note`, t-373 F7, see
            # `s1_review_note`) - and the body says "the onboarding step named below".
            lines.append("This project records no stand, so nothing is run on one yet; before the "
                         "tests run I will ask again (the onboarding step named below adds one).")
        else:
            lines.append(f"The stand is `{environment}`.")
        if not inventory.is_file():
            lines.append("(work/source-inventory.json is not on disk yet; the digest above is the table)")
        # C2-9: the `unavailable` answer is offered only while something is still ASKED; what the factory itself established as out of
        # reach (or a kind the person answered) is not a question, and one line says so.
        asked_open, defaulted = True, 0
        if inventory.is_file():
            try:
                import source_inventory as SI
                summary = SI.completeness(SI.load_inventory(inventory), **SI.class_kwargs(self.task_root))
                asked_open = bool(summary.get("unavailable") or summary.get("unavailable_materials"))
                defaulted = sum(len(points) for points in (summary.get("defaulted_points") or {}).values())
            except Exception:
                asked_open, defaulted = True, 0         # an inventory that cannot be read: the answer stays offered (the unknown is asked)
        if defaulted and not asked_open:
            lines.append(f"{defaulted} materials the factory cannot reach by itself are recorded as gaps; the report names them.")
        role = {"role": f"the {self.role_words('qa-scout')}"}
        options = [
            {"answer": "agree", "says": "agree with the table: the kept sources are read in full", "slots": role},
            {"answer": "flip", "says": "name a ticket to flip, or to ask about", "slots": role}]
        if asked_open:
            options.append({"answer": "unavailable", "says": "for anything unavailable: get me access, or tell me to go on without it",
                            "slots": {**role, "what": "restore the access, or say to go on without it"}})
        return self.closed_question("s1.review", "\n".join(lines), options)


    # --- the conductor ---------------------------------------------------------------------
    def answer_file(self) -> str:
        """The file of the answer being taken, task-root relative (`state/words/driver-answer-<ms>.txt`), written ONCE per answer
        from the raw bytes of `--answer` (CRLF kept) the first time something needs it; '' with no answer or an empty one."""
        held = self._answer
        if not held:
            return ""
        if held.get("rel") is None:
            path = self.words_file(held["text"], "answer")
            held["rel"] = path.relative_to(self.task_root).as_posix() if path else ""
        return held["rel"]

    def record_answer_row(self, token: str, dispatch: str | None = None) -> None:
        """The audit row of the answer being taken in `state/driver-answers.jsonl`, written ONCE per answer: `take_answer` writes
        it at its end, and the run()-level funnel writes it for an answer whose reading raised a Refusal before that point, so a
        person's word is never lost to the refusal. Nothing to write for an answer `take_answer` has not read far enough."""
        held = self._answer
        if not held or held.get("row") or "kind" not in held:
            return
        held["row"] = True
        _append_jsonl(self.state_dir / "driver-answers.jsonl",
                      {"ts": _now(), "kind": held["kind"], "stage": held["stage"], "dispatch": held["dispatch"] if dispatch is None else dispatch,
                       # The body this answer settled, so the same body cannot come back unchanged
                       # (FR-7). The text itself is not kept here: it is in the question file and
                       # in the journal of questions; what travels is its identity.
                       "question_sha": held["question_sha"], "words": held["words"],
                       # C1-1: the token this answer was ("" when it was not one) and the file that holds it whole
                       "token": token, "words_file": held.get("rel") or ""})

    def settle_unread_answer(self) -> str:
        """For the run()-level funnel: the answer `take_answer` was reading when a Refusal came out of it (read, not yet on the
        record) gets its words file and its row now; its words file (task-root relative), else '' - no answer, or one already on
        the record, which this refusal is not about."""
        held = self._answer
        if not held or held.get("row") or "kind" not in held:
            return ""
        path = self.answer_file()
        self.record_answer_row("")
        return path

    def conductor(self, refusal: str, *, words: str = "", files=None, words_file: str | None = None) -> dict:
        """One conductor session. Called ONLY from `no_move` (I-one). The cap raises `ConductorSpent`, which only `no_move`
        catches; an answer with no JSON line is `{"action": "_unreadable"}`, never the model's raw end shown as a question.
        `words_file`: the task-root-relative file that holds `words` whole (the caller names it; nothing is inferred from the
        text); with none, the driver writes one."""
        key = self.boundary
        count = self.conductor_calls.get(key, 0)
        if count >= CONDUCTOR_CALLS_PER_BOUNDARY:
            raise ConductorSpent(count, refusal)
        self.conductor_calls[key] = count + 1
        try:
            where = self.step("where", "--task", self.task)
        except Refusal as exc:
            where = exc.text
        roots = [self.task_root, self.project, self.plugin]
        # The handover form of the dispatch this boundary is about, always - not only when the
        # refusal happens to name it. It is the state of the boundary: what the role claimed,
        # what code derived, what is `blocked` and in whose words. A conductor deciding without
        # it reads factory sources instead, which is what the fifty-four sessions of
        # TP1-13797 spent their turns on (P6).
        boundary_form = []
        # `<stage>:<dispatch>` and `<stage>:<dispatch>:resume` both name it in the same
        # place; `S0:ticket` and `S5:TC-1,TC-2` name no dispatch and the file check drops them.
        parts = self.boundary.split(":")
        dispatch = parts[1] if len(parts) > 1 else ""
        if dispatch:
            import handoff_check                                   # the one rule for the name of the words waiting beside a form
            form = self.task_root / "work" / "handoffs" / f"{dispatch}.yaml"
            # The order is the priority inside a window of CONDUCTOR_FILES: the boundary's files come BEFORE the refusal's own, so
            # the form (the state of the boundary) is in view in every case; the waiting words come after it, the first to give way.
            for candidate in (handoff_check.sibling_help(form), form, handoff_check.sibling_values(form)):
                if candidate.is_file():
                    boundary_form.append(candidate)
        named = boundary_form + list(files or []) + named_files(refusal, roots)
        shown, seen = [], set()
        for path in named:
            path = Path(path)
            if not path.is_file() or str(path) in seen:
                continue
            seen.add(str(path))
            body = path.read_text(encoding="utf-8", errors="replace")[:CONDUCTOR_FILE_LIMIT]
            shown.append(f"--- {path} ---\n{body}")
            if len(shown) >= CONDUCTOR_FILES:
                break
        # The conductor has Bash, Read and Grep and no way to make a file of the answer below, and a
        # command line cannot carry it whole: the driver writes it and names the path, as one
        # sentence the conductor can act on. No answer, no sentence, and the prompt is as it was.
        words_path = (self.task_root / words_file) if words_file else self.words_file(words, "conductor" + self.boundary.split(":")[0])
        # A rework's `--words-file` is the file of the answer being read in THIS call, never a file that holds a token (C1-2, C2).
        words_note = ([f"The person's words are in {words_path}; pass them as --words-file {words_path}. That is the file of "
                       "the answer you are reading now. For a `rework`, never pass a file that holds only a token."]
                      if words and words_path else [])    # a call with no words (why=chosen) names its file in its own note
        prompt = "\n".join([
            f"Task: {self.task}. Project root: {self.project}. Plugin root: {self.plugin}.",
            f"Task root: {self.task_root}. Boundary: {self.boundary}. Model: {self.model}.",
            f"Stand remedy: {self.stand_remedy()}.",
            f"Driver flags: branch suffix `{self.flags.branch_suffix or ''}`.",
            "", "## The refusal", refusal.strip()[:6000], "", "## `story_step.py where`", where.strip()[:2000],
            "", "## The person's words" if words else "",
            (words.strip()[:NO_MOVE_WORDS_IN_PROMPT]
             + (f"\n(cut; the whole answer is in {words_path})" if len(words.strip()) > NO_MOVE_WORDS_IN_PROMPT else "")) if words else "",
            *words_note,
            "", "## Files the refusal names" if shown else "", "\n\n".join(shown),
            "", "Make your moves with the factory's own commands, then answer with ONE JSON line last: "
                '{"action": "continue|retry|ask_person|stop", "did": "<what you ran>", "question": "<for the person, when ask_person>", '
                f'"why_person": "<a class of references/{PO.FILE_NAME}, with ask_person or stop>", "checked": "<what you read before asking>", '
                '"options": [{"token": "<word>", "move": "<id in moves>", "says": "<what it does>", "factory": "<its cost to the factory>", '
                '"person": "<its cost to the person>", "story": {"unverified": "<what stays unverified>", '
                '"report": "<the open item, or none>", "delivery": "<the move\'s delivery value>"}, '
                '"args": {"stage": "S<n>", "role": "<role>", "cases": ["<id>", ...] | "rows": ["<id>", ...], "cause": "<cause>"}}]} '
                "(`options` go with `ask_person` and `stop`: references/conductor.md, Your answer; `args` goes with the `rework` option only, "
                "from the closed list in \"Moves open here\")"])
        started = time.time()
        result = self.run_claude("conductor", prompt, stage=self.boundary.split(":")[0], tools=CONDUCTOR_TOOLS,
                                 system_file=self.plugin / "references" / "conductor.md",
                                 max_turns=CONDUCTOR_MAX_TURNS)
        verdict = last_json_line(result["result"])
        if not verdict:
            verdict = {"action": "_unreadable", "did": "", "question": ""}
        self.journal_conductor(stage=self.boundary.split(":")[0], refusal=refusal[:2000], action=verdict.get("action"),
                               did=str(verdict.get("did") or "")[:1000], question=str(verdict.get("question") or "")[:1000],
                               why_person=str(verdict.get("why_person") or "")[:60],
                               session_id=result["session_id"], total_cost_usd=result["total_cost_usd"],
                               num_turns=result["num_turns"], duration_ms=int((time.time() - started) * 1000),
                               words=bool(words))
        return verdict

    # --- the one seam "no move" (conductor/1, C1-1; PROJECT.md P22, D-0039) ----------------------------------------------
    def no_move_facts(self, state: dict) -> dict:
        """The facts the moves filter reads, each in its OWN try: a reader that raises leaves its fact `None` and removes only
        the moves that need it. The controller's own statuses and `hooklib.story_closure(C.closure_view(...))` (the one reading of closure), never a second reading."""
        import controller as C
        import hooklib
        facts, dispatch = {}, str(state.get("dispatch") or "")

        def read(name, fn):
            try:
                facts[name] = fn()
            except Exception:
                facts[name] = None

        def held() -> dict:
            found = self.controller_state()
            if not isinstance(found, dict) or not isinstance(found.get("dispatches"), dict):
                raise ValueError("controller.json is not readable")
            return found

        def decided(gate: str) -> bool:
            ctl = held()
            return any(isinstance(d, dict) and d.get("gate") == gate and d.get("status") == "approved"
                       and d.get("source_revision") == ctl.get("source_revision") for d in (ctl.get("decisions") or {}).values())

        def stages_open() -> list:
            # S5-S8 once gate A is decided, S1-S4 before it. "No later stage done" is no rule any more: a rework with the person's
            # words stamps the later stages to run again (`rerun_after`, C1-4a), so a later completed stage does not close this one.
            low, high = (5, 8) if decided("A") else (1, 4)
            accepted = {str(d.get("stage")) for d in held()["dispatches"].values()
                        if isinstance(d, dict) and d.get("status") == "accepted" and re.fullmatch(r"S\d+", str(d.get("stage") or ""))}
            return sorted((s for s in accepted if low <= int(s[1:]) <= high), key=lambda s: int(s[1:]))

        gate = {"gate_A": "A", "gate_B": "B"}.get(str(state.get("kind") or ""), "")     # never read from `asked` (C1-1 F1)
        facts["gate"] = gate

        read("dispatch_status", lambda: held()["dispatches"][dispatch]["status"] if dispatch else None)
        read("session", lambda: bool(held()["dispatches"][dispatch]) and bool(self.state["sessions"].get(dispatch)))
        read("running", lambda: any(isinstance(d, dict) and d.get("status") == "running" for d in held()["dispatches"].values()))
        read("closed", lambda: hooklib.story_closure(C.closure_view(held(), self.pipeline()))["state"] == "closed")
        read("attempts", lambda: len(self.state.get("delivery_attempts") or []))
        read("rework_stages", stages_open)
        # What an option's `args` may name (C2-6 §4.2 p.2): the roles of each stage's accepted work (the `ticket_rework_step` rule),
        # the approved scope, the controller's own causes
        read("rework_roles", lambda: {s: sorted({str(d.get("role")) for d in held()["dispatches"].values()
                                                 if isinstance(d, dict) and d.get("stage") == s and d.get("status") == "accepted" and d.get("role")})
                                      for s in facts["rework_stages"]})
        read("scope", lambda: [str(c) for c in held().get("scope") or []])
        read("causes", lambda: list(C.REPAIR_CAUSES))
        read("gate_decided", lambda: decided(gate) if gate else None)
        read("stand_authorized", lambda: self.stand_remedy().startswith("authorized"))

        def exclusions() -> bool:
            import source_exclusions as SE
            return bool(SE.live(self.task_root))
        read("live_exclusions", exclusions)
        return facts

    def open_moves(self, state: dict, moves, facts: dict | None = None) -> list:
        """The ids of `moves` whose state precondition holds now (`NM.MOVE_FACTS`), over `facts` (read here when not given)."""
        facts = self.no_move_facts(state) if facts is None else facts
        return NM.open_moves(facts, NM.move_ids() if moves is None else moves)

    def file_defect(self, ref: str, notes: str) -> None:
        """One `defect_found` row of the driver's own. `log_append` requires `--ref`: the dispatch the failure belongs to, else the
        boundary (never empty). T2 (C1-7b): a rejected write is said once on stderr WITH the rejection's own words (N12b of
        test_no_move_seam pins that line, which `py_trace` does not print) and journalled as `trace_failed` in driver-runs.jsonl,
        and the run goes on: the journal never stalls it."""
        code, out = self.py("log_append.py", "--event", "defect_found", "--task", self.task, "--by", "driver",
                            "--ref", ref or self.boundary, "--notes", notes)
        if code:
            print(f"defect_found not recorded (log_append exit {code}): {' '.join(out.split())[:300]}", file=sys.stderr)
            self.journal_run({"kind": "trace_failed", "script": "log_append.py", "exit": code,
                              "why": "the defect filer cannot file its own failure; the failure goes to driver-runs.jsonl"})

    def no_move_defect(self, rule: str, did: str = "", ref: str = "") -> None:
        """ONE `defect_found` per failure of the seam (owner: factory), and the `unusable` mark in conductor.jsonl."""
        self.file_defect(ref, f"owner: factory — {rule} at {self.boundary} (did: {str(did or '')[:200] or 'nothing'})")
        self.journal_conductor(stage=self.boundary.split(":")[0], action="unusable", unusable=rule)

    def _person_of(self, state: dict, text: str, options: list, *, code: int = EXIT_PERSON) -> Person:
        stage = str(state.get("stage") or self.boundary.split(":")[0])
        dispatch = str(state.get("dispatch") or "")
        person = Person(str(state.get("kind") or "conductor"), text, stage, dispatch, code=code, details=str(state.get("text") or ""))
        person.offered = tuple(o["norm"] for o in options)
        # `says` (what the option does, C2-6 §4.3) and a `rework` option's `args` (§4.2 p.5) travel with the token and move: the
        # next process reads them back from `asked` (`held_question` restores them whole)
        person.options = [{"token": o["norm"], "move": o["move"], **({"says": o["says"]} if o.get("says") else {}),
                           **({"args": o["args"]} if o.get("args") else {})} for o in options]
        person.words_file, person.why, person.block = str(state.get("words_file") or ""), str(state.get("why") or ""), str(state.get("block") or "")
        person.answer_note = str(state.get("answer_note") or "")
        person.rows = tuple(str(i) for i in state.get("rows") or ())
        person.probe_gap_cases = tuple(str(c) for c in state.get("probe_gap_cases") or ())
        person.probe_judgment_cases = tuple(str(c) for c in state.get("probe_judgment_cases") or ())
        # RN1-9: the class and the reading travel with the question; a priced fallback has none (counted `fallback`, never refused)
        person.why_person, person.checked = PO.normalize(state.get("why_person")), PO.checked_text(state.get("checked") or "")
        person.source = state.get("source") or "fallback"
        if state.get("why") == "refusal":
            person.holds = self.manual_holds(dispatch)       # RN1-24, third `holds` site: a refused MANUAL S6 dispatch holds its own cases
        return person

    def site_person(self, state: dict, lead: str, code: int, rule: str = ""):
        """The SITE's own question (`state["site_fallback"](lead)`, C1-3 G2) as the Person to raise, or None: no site, or the site's
        builder itself failed. A site that asked a CLOSED question (S0, `package`, `ticket_changed`) reads only its own words, so
        every exit of the seam that has no usable conductor answer shows that question again with the unread answer's `lead`, with
        its prices when they rendered and without them when they did not - never the generic `retry` / `go on` its reader cannot
        take. ONE defect_found per failure (G8), filed HERE for every caller (F-7): `rule` (why the seam is at its fallback) and the
        price reasons found while the site renders (`_price_notes`) are ONE note, so a site that renders prices never files a
        second defect for the same cause. `code`: 4 only after a conductor `stop`, else 3 (the fallback's own rule)."""
        again = state.get("site_fallback")
        if not callable(again):
            return None
        self._price_notes = []
        try:
            try:
                person = again(lead)
            except Person as made:
                person = made
            except Exception:                   # a site that cannot rebuild its question falls to the floor (`last_resort`)
                person = None
        finally:
            notes, self._price_notes = self._price_notes, None
        if rule or notes:
            self.no_move_defect("; ".join(part for part in (rule, *notes) if part), ref=str(state.get("dispatch") or ""))
        if not isinstance(person, Person):
            return None
        person.code = code
        return person

    def fallback_person(self, state: dict, rule: str = "", code: int | None = None, conductor_text: str = "") -> Person:
        """The priced fallback question (`fallback` of conductor-actions.json) for a state in which no conductor answer
        exists or is usable - or, when the site asked a closed question (`site_fallback`), THAT question again (`site_person`).
        `rule` (when the answer was unusable) is journalled as the factory's own defect; ONE per failure, with the reasons the
        prices of the site's question could not be read added to it. `conductor_text` (t-1936 F2.2 (a), FR-9, AR-17): the `question` of a
        conductor answer whose options were refused - it reaches the person after the lead (`What the conductor found:`, cut at 1200
        characters, a line for each word it quotes that is not offered), on every road below, the floor included; empty = as before."""
        stage = str(state.get("stage") or self.boundary.split(":")[0])
        lead = str(state.get("lead") or "") or self.question_from_refusal(None, stage)
        if code is None:
            code = EXIT_GAVE_UP if state.get("why") == "stop" else EXIT_PERSON
        spec, site = NM.data(), state.get("site_doors") or ()
        # the answers shown are not known yet on these roads (a site's own question, the floor): the text is shown, no token line is claimed
        unknown = lambda: NM.conductor_lead(lead, conductor_text, None, spec, self.s0_normalize, site=site)
        if callable(state.get("site_fallback")):
            person = self.site_person(state, unknown(), code, rule)       # files the ONE defect (the rule and the price reasons)
            if person is not None:
                return person
            return self.last_resort(dict(state, site_fallback=None), "the question of the site could not be shown again", lead=unknown(), code=code)
        if rule:
            self.no_move_defect(rule, ref=str(state.get("dispatch") or ""))
        verdicts = (hooklib.load_ref_json(NM.VERDICTS_FILE) or {}).get("words") or {}
        try:
            if str(state.get("kind") or "") in GATE_KINDS:
                text, options = self.gate_fallback_question(state, lead, verdicts, conductor_text=conductor_text)
            else:
                options = NM.fallback_options(spec, verdicts, self.s0_normalize, keep=state.get("fallback"))
                facts = self.fallback_facts(state) if str(conductor_text).strip() else {}
                text = NM.render_question(NM.conductor_lead(lead, conductor_text, [o["norm"] for o in options], spec, self.s0_normalize,
                                                            facts=facts, site=site), options, human_text.price_labels())
            return self._person_of(state, text, options, code=code)
        except (NM.DataUnreadable, human_text.LabelsUnreadable, Refusal) as exc:
            return self.last_resort(state, f"the fallback could not be rendered ({exc})", lead=unknown(), code=code)

    NO_APPROVE_WORDS = "To approve, answer this gate in your own words; the choice alone has nothing to record."

    def gate_fallback_question(self, state: dict, lead: str, verdicts: dict, conductor_text: str = "") -> tuple:
        """`(text, options)` of the fallback question AT A GATE (t-722 C2-7 §5.1): the options of the ONE table `GATE_OPTIONS` that are open now (the
        conductor's own prices at this gate read the same rows, `gate_option_rows`, FR-10), each with its executor - `approve` (code,
        the original answer on file), `rework` (no `args`: the answer goes to the conductor with the person's words, which names the
        stage, P1), `retry`, `stop`. An option that is not offered is said in ONE line of the lead (FR-42). A fact that could not be
        read removes its move and is never told as a reason (FR-59). Raises what the caller turns into the floor (`last_resort`).
        `conductor_text` (t-1936 F2.2 (a), E2.5): the conductor's refused `question`, shown after the lead with a line for each word it
        quotes that these options do not carry; it offers nothing, so `go on` stays unoffered at a gate."""
        facts = self.fallback_facts(state)
        open_ids = NM.open_moves(facts, [move for _answer, move, _says, _slots in self.GATE_OPTIONS])
        notes = []
        if "approve_gate" in open_ids and not state.get("words_file"):
            open_ids.remove("approve_gate")
            notes.append(self.NO_APPROVE_WORDS)
        if "rework_stage" not in open_ids:
            notes.append("Sending a stage back is not open now: " + NM.rework_closed_reason(facts) + ".")
        if ((self.state.get("shown_gaps") or {}).get(str(state["kind"])[-1]) or {}).get("gaps"):
            notes.append("Your answers to the stand cards of this gate, one per line as `<case>: <word>`, are read in this answer too.")
        rows = self.gate_option_rows(open_ids, facts)
        priced = NM.priced_options("gate_A" if state["kind"] == "gate_A" else "gate_B", rows, NM.data(), verdicts)
        options = [dict(row_priced, norm=self.s0_normalize(row["token"]), move=row["move"]) for row_priced, row in zip(priced, rows)]
        lead = NM.conductor_lead(lead, conductor_text, [o["norm"] for o in options], NM.data(), self.s0_normalize, facts=facts,
                                 site=state.get("site_doors") or ())
        return NM.render_question("\n\n".join([lead, *notes]), options, human_text.price_labels()), options

    def fallback_facts(self, state: dict) -> dict:
        """`no_move_facts` for the fallback of a gate, `{}` when even that fails: every move that needs a fact is then closed."""
        try:
            return self.no_move_facts(state)
        except Exception:
            return {}

    def last_resort(self, state: dict, rule: str, *, lead: str = "", code: int = EXIT_PERSON) -> Person:
        """The floor of the seam. With a site's question (`site_fallback`) that is the question, shown without prices if they cannot
        be read; otherwise the question with no price lines: the three standing words (TOKEN_MOVES). A site question that is itself
        unreadable ends here, ONCE: the generic words, and nothing below them (G2)."""
        lead = lead or self.question_from_refusal(None, str(state.get("stage") or self.boundary.split(":")[0]))
        if callable(state.get("site_fallback")):
            shown = self.site_person(state, lead, code, rule)         # the rule joins the price reasons: ONE defect (F-7)
            if shown is not None:
                return shown
        elif rule:
            self.no_move_defect(rule, ref=str(state.get("dispatch") or ""))
        at_gate = str(state.get("kind") or "") in GATE_KINDS      # at a gate `go on` passes nothing: only `retry` and `stop` have an executor
        options = [{"token": t, "norm": t, "move": m} for t, m in NM.TOKEN_MOVES.items() if not at_gate or t in GATE_FALLBACK]
        # C2-7 §5.2: `approve` is on the floor of a gate only with the original answer on file and the gate not decided (a fact that
        # cannot be read is no gate that is open: the move is not offered, FR-59)
        approve = at_gate and bool(state.get("words_file")) and bool(NM.open_moves(self.fallback_facts(state), ["approve_gate"]))
        if approve:
            options.insert(0, {"token": "approve", "norm": self.s0_normalize("approve"), "move": "approve_gate"})
        floor = (GATE_TOKEN_ANSWERS_APPROVE if approve else GATE_TOKEN_ANSWERS) if at_gate else TOKEN_ANSWERS
        return self._person_of(state, lead + "\n\n" + floor, options, code=code)

    def _ask_conductor(self, text: str, state: dict) -> dict:
        """THE call (I-one): the only `self.conductor(` of the driver.

        The ONE named exception (C1-6c, F7): the delivery's own session, `Driver.delivery`'s `run_claude("conductor")`, is the second
        conductor call site and there is no third. It is a role-like session (tools, 40 turns, a resume key), not a state the driver has
        no move for; only its QUESTIONS go through the seam helpers (`delivery_person`). `audit_factory.CONDUCTOR_SITES` names both."""
        named = {"words_file": state["words_file"]} if state.get("words_file") else {}      # no file named: the call is as it was
        return self.conductor(text, words=str(state.get("words") or ""), files=state.get("files"), **named)

    def standing_refusal(self, state: dict) -> None:
        """THE writer of `state/standing-refusal.json` (t-722 §3.1, §L-7, class K4): `{stage, lines, doors}` of the refusal the seam is
        called for, which `waiver.py --block` reads (`waiver.read_standing`, the one reader) to refuse a block that is in none of it.
        Only a call that carries `lines` (a non-empty list, built by `refusal_lines`) writes; `unread_answer`, `chosen`, `stop` and
        `by_hand` carry none and leave the file as it is. The last refusal REPLACES the record, never merged. `doors`: the block
        names the refusal printed in its own door, read from the raw `text` (`waiver.door_blocks`) - the lines have lost them.
        The stage is `state["stage"]`; with none (`funnel`) the ONE stage `pipeline.json` holds `running`; no stage or several, no
        record (an unknown is not a fact, FR-59) and the old one goes. A dry run writes and erases nothing; a record that cannot
        be written erases the old one (a refusal that no longer stands is never judged against); the seam goes on either way (P1)."""
        lines = state.get("lines")
        if self.dry or not isinstance(lines, list) or not lines:
            return
        stage = str(state.get("stage") or "").strip().upper()
        if not stage:
            running = [s for s, held in (self.pipeline().get("stages") or {}).items()
                       if isinstance(held, dict) and held.get("status") == "running"]
            stage = running[0] if len(running) == 1 else ""
        if not re.fullmatch(r"S\d+", stage):
            return self.drop_standing()
        try:
            waiver.write_standing(self.task, stage, lines, waiver.door_blocks(state.get("text")))
        except OSError as exc:
            print(f"note: the record of the standing refusal was not written ({exc}); a block is recorded as not verified", file=sys.stderr)
            self.drop_standing()

    def standing_note(self, stage: str) -> str:
        """What the conductor is told about `go on` with no block of code's own (t-722 §3.4): the lines of the refusal the record
        holds for `stage`, whole and numbered, under the writer's ceiling (`waiver.listed`: the same listing as its refusal), or the
        sentence that none is recorded. `waiver.py` refuses a block that is in none of the lines."""
        lines = waiver.read_standing(self.task, stage.strip().upper())["lines"]
        if not lines:
            return "No refusal is recorded as standing here; if their words pass nothing, keep them with --remark."
        return ("The refusal standing here has these lines; record their words only for the lines their words cover, one waiver.py "
                "--block per line, the line whole:\n" + waiver.listed(lines, waiver.standing_path(self.task))
                + "\nwaiver.py refuses a block that is in none of them.")

    def drop_standing(self) -> None:
        """The way out of the record (FR-40), the ONE eraser: E1 `no_move` returned `continue` / `retry`, E2 `guarded` moved on
        (the stage moved, or the refused step went through), E3 `take_answer` closed the question, E4 `reconcile_question` found
        none open. While a `Person` stands the record lives with the question, between processes too. A dry run erases nothing."""
        if self.dry:
            return
        try:
            waiver.drop_standing(self.task)
        except OSError as exc:
            print(f"note: the record of the standing refusal could not be erased ({exc})", file=sys.stderr)

    def no_move(self, state: dict, moves=None) -> str:
        """The ONE seam for a state in which the driver has no move of its own. Returns `continue` / `retry` after a conductor
        move; otherwise raises `Person` with a closed question of at least two options, each followed by its three price lines.
        Never returns silently (I-nosilent).

        `state`: why (refusal, stop, unread_answer, cap, threshold, by_hand, chosen), kind (the Person's kind at this site),
        stage, dispatch, text (the factory's words: the details file only), words, words_file (task-root relative), files, and
        `call` (False: never a paid call here), `block` (the waivable block code knows), `lead` (the site's own words: the
        conductor reads them first, and the fallback shows them as the body), `keep` (strings of the lead the conductor's
        question must carry, else the lead is shown above it), `fallback` (tokens to show),
        `move` (why=chosen: the move id), `token`, `lines` (a refusal's lines from `refusal_lines`: `standing_refusal` records them).
        `moves`: ids of conductor-actions.json (default all), filtered by state."""
        if str(state.get("kind") or "") in GATE_KINDS and "fallback" not in state:
            state = dict(state, fallback=list(GATE_FALLBACK))     # `site_fallback` still wins (it is never set at a gate)
        if self._in_no_move:
            raise self.last_resort(state, "")            # the seam never recurses (and journals nothing: the first failure did)
        self.standing_refusal(state)                     # AFTER the guard: a nested call never rewrites the outer one's record
        self._in_no_move = True
        try:
            action = self._no_move(state, moves)
            self.drop_standing()                         # E1: the conductor moved (`continue` / `retry`); the driver is out of the refusal
            return action
        except Refusal as exc:                           # edge 6: a refusal raised while rendering is caught, nothing else
            raise self.last_resort(state, f"the question could not be rendered ({exc.text[:100]})") from None
        finally:
            self._in_no_move = False

    def _no_move(self, state: dict, moves) -> str:
        kind = str(state.get("kind") or "conductor")
        if state.get("call") is False:                   # F1: before the exclusions - no paid call, no gate branch
            raise self.fallback_person(state, "the refusal cap was reached" if state.get("why") == "cap" else "")
        if kind in NM.EXCLUDED_KINDS:
            return self.no_move_legacy(state, kind)
        facts = self.no_move_facts(state)
        open_ids = self.open_moves(state, moves, facts)
        try:
            site = NM.site_check(state.get("site_doors"), NM.data(), self.s0_normalize)       # a door that is a move's word: unreadable (G7)
        except NM.DataUnreadable as exc:
            raise self.fallback_person(state, str(exc)) from None
        chosen = state.get("why") == "chosen"                     # a call for the token the person chose (t-722 §4.3)
        chosen_move = str(state.get("move") or "") if chosen else ""
        text = self._conductor_text(state, facts, open_ids, site, chosen)
        try:
            verdict = self._ask_conductor(text, state)
        except ConductorSpent:
            raise self.fallback_person(state, "the conductor cap was reached") from None
        while True:
            action = str(verdict.get("action") or "")
            print(f"conductor: {action} — {str(verdict.get('did') or '')[:300]}")
            if action in ("continue", "retry") and not verdict.get("options"):
                return action
            try:
                options, rule, again = self._verdict_rule(verdict, facts, open_ids, site, chosen, chosen_move)
            except NM.DataUnreadable as unreadable:      # F2 (E2.2): a bad column of the move table is the factory's defect; the answer is not used
                options, rule, again = None, f"the table of moves cannot be read ({unreadable})", False
            if not rule:
                break
            # t-1936 F2.2 (a): the question of a conductor that asked or stopped is the person's to read even when its options are refused
            refused_text = str(verdict.get("question") or "") if action in ("ask_person", "stop") and verdict.get("options") else ""   # E2.4: no options, as before
            if not again or state.get("args_refused"):
                # `continue`/`retry` with options keeps the code the state itself gives (`why=stop` -> EXIT_GAVE_UP), as before C2-6
                raise self.fallback_person(state, rule, code=None if action in ("continue", "retry")
                                           else EXIT_GAVE_UP if action == "stop" else EXIT_PERSON, conductor_text=refused_text)
            if chosen:                                  # a malformed answer to the person's CHOICE is the factory's defect, once (§4.3)
                self.no_move_defect(rule, ref=str(state.get("dispatch") or ""))
            state = dict(state, args_refused=1)
            try:
                verdict = self._ask_conductor(text + "\n\n## Your options were refused\n" + rule + "\n" + NM.rework_args_list(facts), state)
            except ConductorSpent:
                raise self.fallback_person(state, rule, conductor_text=refused_text) from None
        dropped = [str(o["token"]) for o in options if o.get("args_dropped")]
        if dropped:                                     # F2 (Fork 3-B): `args` on a move that takes none was dropped, the option kept - said once
            self.journal_conductor(stage=self.boundary.split(":")[0], action="args_dropped", args_dropped=dropped)
        if chosen and len(options) == 1:                # the `rework` decision of the person's choice: recorded, run next turn, no question
            return self.chosen_rework(state, options[0])
        raise self.options_person(state, verdict, options, action == "stop", EXIT_GAVE_UP if action == "stop" else EXIT_PERSON)

    def _conductor_text(self, state: dict, facts: dict, open_ids: list, site, chosen) -> str:
        """The prompt body of the conductor's call: the site's own account (`lead`) first - the conductor decides on what the factory
        found, not on the details file alone - then the moves open here, the factory's words, the gate's priced options, and for a
        token the person chose the paragraph of their choice."""
        lead = str(state.get("lead") or "").strip()
        text = (lead + "\n\n" if lead else "") + NM.moves_section(NM.data(), open_ids, facts, site) + "\n\n" + str(state.get("text") or "")
        if facts.get("gate"):
            text += "\n\n" + self.gate_prices(str(facts["gate"]), open_ids, facts, has_words=bool(state.get("words_file")))
        return text + ("\n\n## The person's choice\n" + self.chosen_note(state, open_ids) if chosen else "")

    def _verdict_rule(self, verdict: dict, facts: dict, open_ids: list, site, chosen: bool, chosen_move: str) -> tuple:
        """`(options, rule, again)` of one conductor answer: `rule` is why it is unusable ("" when it is usable); `again` - the conductor
        may be told the rule once (a bad "args" always, any other malformed answer only to the person's CHOICE: `chosen`, whose move
        is `chosen_move`)."""
        action = str(verdict.get("action") or "")
        verdicts = (hooklib.load_ref_json(NM.VERDICTS_FILE) or {}).get("words") or {}
        try:
            if action in ("ask_person", "stop"):
                options, rule = NM.validate_options(verdict, open_ids, NM.data(), self.s0_normalize, verdicts, site,
                                                    facts=facts, chosen=chosen, chosen_move=chosen_move)
            else:
                options, rule = None, (f"the conductor answered `{action}` with options" if action in ("continue", "retry")
                                       else f"the conductor answered `{action or 'nothing'}`")
            return options, rule, bool(rule) and bool(chosen)
        except NM.ArgsRefused as refused:
            return None, refused.rule, True            # bad "args": the conductor is told the rule and the list ONCE (§4.2 p.4)

    def chosen_note(self, state: dict, open_ids: list) -> str:
        """The paragraph "## The person's choice" of a call for a token the person chose (`why=chosen`, t-722 §4.3): the token, its
        move and what the option says; where the ORIGINAL words are (the prompt carries them whole - the token answer is not the
        instruction); the closed list of lines for `go on` with no block of code's own (§3.4); for `rework` the answer the code can run."""
        token, move, says = (str(state.get(key) or "") for key in ("token", "move", "says"))
        note = f"The person chose `{token}` (move `{move}`)" + (f': "{says}".' if says else ".")
        note += (' Their original words are under "The person\'s words" below; the token answer itself is not the instruction.'
                 if str(state.get("words") or "").strip() else " Their original words were none beyond the token.")
        if move not in open_ids:
            note += f" `{token}` is no longer open: the state it needs has changed; say so in your question."
        if move == "go_on_as_is":          # `go on` with no block of code's own (t-722 §3.4): the closed list of lines
            note += "\n" + self.standing_note(str(state.get("stage") or ""))
        if move == "rework_stage" and move in open_ids:          # a `rework` that is no longer open is not asked for (the order would be refused)
            note += ("\nWhich stage, role and cases is your judgement: answer ask_person with exactly one option, the `rework` option "
                     "carrying \"args\" from the closed list in \"Moves open here\"; the driver records it and runs it with their words "
                     "on its next step, and the person is not asked again. Do not run the rework yourself.")
        return note

    NO_REWORK_WORDS = ("You chose `rework`, and a rework is done with your words as its instruction; none are on file. "
                       "Write what should change, in your own words.")

    def chosen_rework(self, state: dict, option: dict) -> str:
        """The conductor's ONE `rework` option with "args" at a call for the person's choice: the choice is made, so this is a decision
        and not a question (t-722 §4.3, §L-5). Recorded for `seam_rework_step` with the ORIGINAL words; returns `continue`."""
        self.record_seam_rework(option["args"], str(state.get("words_file") or ""))
        return "continue"

    def record_seam_rework(self, args: dict, rel: str, preface=()) -> None:
        """The record `state["seam_rework"]` (t-722 §4.2 p.6): `args` (stage, role, cases|rows, cause), the words file of the person's
        ORIGINAL words, when, and `before` - the controller's dispatches of that stage and cause that are not this rework's, so
        `seam_rework_step` finds its own. No words on file: held, a rework is done with the person's words as its instruction. A
        controller state that cannot be read: held, never a record with an unknown `before` that would take another dispatch for its
        own (FR-59). `preface`: lines the CODE puts in front of the person's words in the rework's reason (the finding the words are
        about, critic t-1592 M-a); kept in the record, absent when there are none."""
        if not rel:
            raise self.held_question(self.NO_REWORK_WORDS)  # remains: the person's own question comes back with the reason (t-722 §4.2 p.6), not a state with no move
        found = self.controller_state()
        dispatches = found.get("dispatches") if isinstance(found, dict) else None
        if not isinstance(dispatches, dict) or not (self.state_dir / "controller.json").is_file():
            # remains: the person's own question comes back with the reason (t-722 §4.2 p.6, FR-59), not a state the driver has no move for
            raise self.held_question("Your choice could not be carried out: the factory could not read where the story stands, so "
                                     "nothing was sent back. Answer again, in your own words or with one of the words offered.")
        before = sorted(self.rework_dispatches(dispatches, args["cause"], by_person=True, stage=args["stage"]))
        self.state["seam_rework"] = {**args, "words_file": rel, "at": _now(), "before": before,
                                     **({"preface": [str(line) for line in preface]} if preface else {})}
        self.save_state()
        print(f"{args['stage']}: the rework you chose is started next, with your words")

    # The options a gate offers, by the move that executes each (C1-4b): the words stay here, the three price lines are DATA
    # (`question-prices.json` `gate_A` / `gate_B`, rendered by the ONE price helper). The prompt carries them so the conductor's own
    # options at a gate are priced the way the data says.
    GATE_OPTIONS = (("rework", "rework_stage", "the role that made this stage's work changes it with your words as its instruction; "
                                               "what follows it runs again and you see this gate again", {}),     # `stages`: built from facts, `gate_option_rows`
                    ("approve", "approve_gate", "the gate is recorded as approved with your answer as you gave it; nothing is changed first", {}),
                    ("retry", "person_does", "you change it yourself, outside the factory, then answer this gate again",
                     {"what": "the change itself, outside the factory"}),
                    ("stop", "stop_here", "stop the story here", {}))

    def gate_option_rows(self, open_ids: list, facts: dict, *, has_words: bool = True) -> list:
        """The rows of `GATE_OPTIONS` whose move is in `open_ids`, as `[{answer, token, says, slots, move}]`: the ONE source of the
        options of a gate - the conductor's prices (`gate_prices`) and the fallback question (`gate_fallback_question`) read it (FR-10).
        The `stages` slot of `rework` is built from the facts (`rework_stages`), in the story's words: the conductor names the stage,
        the person does not (t-722 §5.1). `has_words` False (the question carries no `asked.words_file`): `approve_gate` is not a row -
        its road records the ORIGINAL answer from that file, so there is no such road to show or to price (C4-14, the same rule
        `gate_fallback_question` applies before it asks)."""
        import handoff_check
        open_ids = [move for move in open_ids if has_words or move != "approve_gate"]
        named = [self.stage_place(stage) for stage in (facts.get("rework_stages") or [])]
        listed = handoff_check._or_list(named) if named else ""        # the package's one "A, B or C" joiner
        slots = {"stages": "the stage the conductor names" + (f" — {listed} —" if listed else "") + " and the stages after it up to this gate"}
        return [{"answer": answer, "token": answer, "says": says, "slots": slots if move == "rework_stage" else others, "move": move}
                for answer, move, says, others in self.GATE_OPTIONS if move in open_ids]

    def gate_prices(self, gate: str, open_ids: list, facts: dict, *, has_words: bool = True) -> str:
        """"The price lines of the options open at gate `gate`", from the data rows `gate_A` / `gate_B` (one site per key: the census
        of question ids reads the literal). A row the data lacks shows the option with no price lines and ONE defect (`priced_section`)."""
        options = self.gate_option_rows(open_ids, facts, has_words=has_words)
        section = self.priced_section("gate_A", options) if gate == "A" else self.priced_section("gate_B", options)
        return "## The options at this gate\nWhen you offer one of these, use its lines:\n\n" + str(section)

    def options_person(self, state: dict, verdict: dict, options: list, stopped: bool, code: int) -> Person:
        """The Person for a conductor's usable options. The site's own `lead` goes ABOVE the conductor's prose when the prose
        drops a fact the site marked in `keep` (its record path): what the factory did is never replaced by the conductor's
        wording. Price labels that cannot be read end in the last-resort question and one defect_found, never in unpriced options."""
        prose = ("The conductor stopped the story:\n\n" if stopped else "") + str(verdict["question"]).strip()
        lead = str(state.get("lead") or "").strip()
        if lead and any(str(fact) not in prose for fact in state.get("keep") or ()):
            prose = lead + "\n\n" + prose
        try:
            labels = human_text.price_labels()
        except human_text.LabelsUnreadable as exc:
            return self.last_resort(state, f"the price labels could not be read ({exc})", lead=lead, code=code)
        return self._person_of(dict(state, why_person=verdict.get("why_person"), checked=verdict.get("checked"), source="conductor"),
                               NM.render_question(prose, options, labels), options, code=code)

    def no_move_legacy(self, state: dict, kind: str) -> str:
        """The S1 review until C1-3 gives it an executor (the gates left in C1-4b): today's behaviour. The conductor is called with
        the site's prompt and no options; `ask_person` with a question re-raises it as `kind`, with none it is printed and
        journalled and the loop goes back to `where`; `stop` ends the run (exit 4); the cap raises today's Person."""
        stage = str(state.get("stage") or self.boundary.split(":")[0])
        dispatch = str(state.get("dispatch") or "")
        try:
            verdict = self._ask_conductor(str(state.get("text") or ""), state)
        except ConductorSpent as spent:
            raise Person("conductor", f"The conductor was called {spent.count} times at {self.boundary} and the block "
                         f"stands. Last refusal:\n\n{spent.refusal}\n\nWhat should happen? (your word passes any "
                         "block: it is recorded with waiver.py / release by the conductor)",
                         stage, dispatch) from None
        action = verdict.get("action")
        if action in ("ask_person", "_unreadable"):
            self.pass_to_person(dict(verdict, action="ask_person", question="" if action == "_unreadable" else verdict.get("question")),
                                kind, stage, dispatch)
        elif action == "stop":
            raise Stop(EXIT_GAVE_UP, str(verdict.get("question") or verdict.get("did")))
        return action if action in ("continue", "retry") else "continue"

    # --- t-217: whose refusal it is, one resume per finding set, a cap on a window's rounds ---------------
    def boundary_dispatch(self) -> str:
        """The dispatch the boundary names by its SHAPE, else "": `S5:S5-qa-code-critic-2` and the `:resume` / `:answer`
        forms name one; `S0:ticket`, `gate_A`, `S5:TC-1,TC-2` and `S5:environment:<job>` do not."""
        parts = self.boundary.split(":")
        return parts[1] if len(parts) > 1 and DISPATCH_ID_RE.fullmatch(parts[1]) else ""

    def refusal_dispatch(self, refusal) -> str:
        """The dispatch a refusal is about, for a Person raised from it (F-cmp2-22, FR-16): the refusal's own
        field first, else the boundary's. NEVER an id read out of its text - the same text can quote another
        dispatch (a probe's hint, a critic id placeholder), and a person's words filed into a wrong dispatch
        resume a role that never asked."""
        return str(getattr(refusal, "dispatch", "") or "") or self.boundary_dispatch()

    @staticmethod
    def resumable_head(text: str) -> str:
        """The dispatch id of a refusal whose HEAD is one the role's own resume answers (`RESUMABLE_HEADS`), else "".
        Anchored at the start of the text on purpose (`match`, never `search`)."""
        for pattern in RESUMABLE_HEADS:
            found = pattern.match(str(text or ""))
            if found:
                return found.group(1)
        return ""

    def refusal_sid(self, dispatch: str, fallback: str = "") -> str:
        """The session a dispatch's resume record is keyed by (C3): the one the driver stored for it
        (`sessions[dispatch]`), else `fallback` (the saved result's own). A new session recorded for the same
        dispatch (a rework in a new session, a call continued after an interruption) starts an empty record, and so
        gets its own one resume."""
        return str(self.state["sessions"].get(dispatch) or fallback or "")

    def resume_record(self, dispatch: str, sid: str) -> dict:
        """`{finding key: why}` for one dispatch and session, read-only; {} when nothing was recorded (a state file
        written before t-217 has no `refusal_resumes`: an in-flight story gets one resume)."""
        by_session = (self.state.get("refusal_resumes") or {}).get(dispatch) if isinstance(
            self.state.get("refusal_resumes"), dict) else None
        record = by_session.get(sid) if isinstance(by_session, dict) else None
        return record if isinstance(record, dict) else {}

    def note_resume(self, dispatch: str, sid: str, key: str, why: str) -> None:
        """Write one resume into `refusal_resumes[dispatch][sid][key] = why` (why: handoff | refusal | stand) and
        save it - called BEFORE the paid call, so that a crash costs one resume and never repeats one."""
        held = self.state.get("refusal_resumes")
        if not isinstance(held, dict):
            held = self.state["refusal_resumes"] = {}
        by_session = held.get(dispatch)
        if not isinstance(by_session, dict):
            by_session = held[dispatch] = {}
        record = by_session.get(sid)
        if not isinstance(record, dict):
            record = by_session[sid] = {}
        record[key] = why
        self.save_state()

    def forget_resumes(self, dispatch: str) -> None:
        """The dispatch was accepted: its record leaves (state-exits.md). A dispatch that is released, or never
        accepted, keeps it - it is terminal, and nothing reads it once the dispatch is gone."""
        held = self.state.get("refusal_resumes")
        changed = isinstance(held, dict) and held.pop(dispatch, None) is not None
        limits = self.state.get("exit_limit")
        if isinstance(limits, dict) and not (limits.get(dispatch) or {}).get("passes") and limits.pop(dispatch, None) is not None:
            changed = True          # t-764 A5: the seam's state leaves with it - unless a pass is still to be revoked (the sweep retries)
        if changed:
            self.save_state()

    def dispatch_role(self, dispatch: str) -> str:
        try:
            role = str(((self.controller_state().get("dispatches") or {}).get(dispatch) or {}).get("role") or "")
        except Exception:
            role = ""
        return role or (re.fullmatch(r"S\d+-(qa-[a-z-]+)-\d+", dispatch) or [None, ""])[1]

    RESUME_SENTENCE = ("Repair the named fields in the artifact, change nothing else, then your final "
                       "message is the handoff form only.")

    def resume_with(self, refusal: Refusal, stage: str, dispatch: str, sid: str, lead: str, reason: str = "",
                    sentence: str | None = None) -> None:
        """ONE resume of the role's own session: `lead`, the refusal whole, the sentence. The result is the
        dispatch's saved result from now on (the loop comes back through `where` -> `wait_existing_job` ->
        `handoff` -> `finish` on THIS result, not on the one the refusal was about). A resume that returns an
        error and no words is spent and is the person's: the session is gone, and the ONE seam `exit_limit` says so (t-764
        F-d6, E10: no round - an offered option is never silently unexecutable). `reason` (t-342, B-273) is the line
        the log prints; with none, the refusal's own findings are classified (`resume_reason`). `sentence`: what closes the
        prompt in place of RESUME_SENTENCE (t-764: the paid round's text already says what to do; "" closes with nothing)."""
        closing = self.RESUME_SENTENCE if sentence is None else sentence
        prompt = lead + refusal.text.strip() + (("\n\n" + closing) if closing else "")
        self.progress_line()            # t-323 B1: the role's own session is asked again: a launch like any other
        result = self.run_claude("role", prompt, role=self.dispatch_role(dispatch), dispatch=dispatch, stage=stage,
                                 resume=sid,
                                 resume_reason=reason or "the factory refused to close the dispatch: "
                                 + resume_reason(refusal.findings or refusal.text))
        if result.get("is_error") and not str(result.get("result") or "").strip():
            self.exit_limit(stage, self.dispatch_role(dispatch), dispatch, self.refusal_lines(refusal), sid=sid, why="session_gone",
                            error=str(result.get("stderr") or "")[-600:], text=refusal.text)
        _write_json(self.state_dir / "driver-runs" / f"{dispatch}.json", result)
        self.state["pending_words"].pop(dispatch, None)     # t-764 A12: the role answered them in THIS result, before anyone judges it
        self.save_state()
        self.progress_line()            # t-323 B1: the resume returned and its result is the dispatch's now

    @staticmethod
    def refusal_lines(refusal, items=None) -> list:
        """THE builder of "the lines of the refusal that reached the seam" (t-722 §3.1, N6): the driver's record of the standing
        refusal (`standing_refusal`) and `exit_limit`'s `lines` are this one result. The source: `items` when given (the S5
        window's own set); else the raiser's `findings`; else the items of the controller's combined refusal (`DV.split_items`
        over `DV.refusal_text`, the transport off - the C2-1 reader, no second stripper); else the text below its first line
        (the driver's header `story_step finish <id> (exit N):`); else the text whole. Then `waiver.refusal_parts`, the ONE
        normalisation the writer applies to a block too (the hint and the door cut, the number, the split at `"; "`).
        Never empty for a refusal: a source that normalises to nothing (all code in backticks) is returned as it is. `items` GIVEN
        is the whole source, `refusal` is then not read and may be `None` (`items=[]` is no lines - the caller's lines are
        the caller's, t-842 F3): only `items=None` reads the refusal."""
        if items is None:
            items = list(refusal.findings or [])
            if not items:
                text = DV.refusal_text(refusal.text)
                items = DV.split_items(text) or [line for line in text.splitlines()[1:] if line.strip()] or [text]
        raw = [str(item) for item in items if str(item).strip()]
        return waiver.refusal_parts(raw) or raw

    def assemble_digest(self, role: str, stage: str, dispatch: str, result: dict) -> tuple:
        """(digest, "") or ("", why not): the handoff form built by code from what the role already wrote (t-342, B-273).

        The form is a header (`<role> <stage> <window> · <verdict>`), one row per item (`<id> · <state> · <reason>`)
        and the path of the artifact. All of it is already in the role's HANDOVER FORM (`work/handoffs/<dispatch>.yaml`:
        `header`, `scope[]`) and in its last message or artifacts (the path); nothing here is decided by code - every
        value is the role's own, copied. It is assembled only when EVERY field is there: a verdict that is a real
        non-halting one (a halt is the role's word to the person and is never written for it), every row filled
        (id, state, a reason no longer than the form allows - code never rewrites a role's words; a field `--shorten` cut
        carries its mark and the path to the whole text, C2-4), a path that is a
        file on disk and not absolute, and a digest that fits `DIGEST_MAX` whole (a cut digest would lose its path
        line). Anything missing is the reason returned, and the caller resumes the role as before. The caller then
        judges the result with the same exit gate as a role's own message.

        The last line `assembled_by: code` is the trace (FR-8/P13): it follows the form's path line, so the form is
        read as always and the line is kept as a note of the digest, which is what `finish` records."""
        form = self.task_root / "work" / "handoffs" / f"{dispatch}.yaml"
        if not form.is_file():
            return "", "the role wrote no handover form"
        try:
            import handoff
            import handoff_check
            import role_digest
            doc = handoff_check.form_view(form)      # the form plus its waiting values file (SC1-2, B-1)
        except Exception as exc:
            return "", f"the handover form cannot be read ({type(exc).__name__})"
        if not str(result.get("result") or "").strip():
            return "", "the role's final message is empty"
        # critic t-346 F1 (FR-47): a halt in the role's own message is the role's word to the person - the YAML's `ok`
        # never overwrites it - and so is any header verdict the message states that the form does not.
        message = str(result.get("result") or "")
        if role_digest.is_halting(message):
            return "", "the role's own message halts: a halt is its word to the person and code never writes over it"
        said = ""
        for line in role_digest._lines(message):
            header, error = role_digest._parse_header(line)
            if not error and header.get("verdict"):
                said = {"done": "ok", "review": "concerns"}.get(header["verdict"], header["verdict"])
                break
        verdict = str(doc.get("header.verdict") or "").strip()
        if said and verdict and said != verdict:
            return "", f"the role's message says `{said}` and its form says `{verdict}`: that is the role's to settle"
        window = str(doc.get("header.window") or "").strip()
        if handoff.is_placeholder(verdict) or handoff.is_placeholder(window):
            return "", "the form's header is not filled (verdict or window)"
        if verdict not in role_digest.HEADER_VERDICTS or verdict in role_digest.HALTING_VERDICTS:
            return "", (f"the form's verdict is `{verdict}`: a halt is the role's own word to the person, and a word "
                        "outside the closed list is its own to correct - code writes neither for it")
        rows = []
        for index in doc.rows("scope"):
            row_id = str(doc.get(f"scope[{index}].id") or "").strip()
            state = str(doc.get(f"scope[{index}].state") or "").strip()
            reason = str(doc.get(f"scope[{index}].reason") or "").strip()
            if handoff.is_placeholder(row_id) or handoff.is_placeholder(state):
                return "", f"row {index + 1} of the form is not filled"
            reason = "" if handoff.is_placeholder(reason) else reason
            if len(reason) > role_digest.REASON_MAX:
                return "", f"the reason of {row_id} is {len(reason)} characters, the form allows {role_digest.REASON_MAX}"
            rows.append(f"{row_id} · {state}" + (f" · {reason}" if reason else ""))
        if not rows:
            return "", "the handover form lists no rows"
        # t-363 B5 (B-287, critic t-346 F5): the form's own `artifacts.*` field comes FIRST and the role's PROSE only
        # when the field is empty - structure outranks prose (FR-49, P4); the last existing file named in the prose
        # used to win over the field. INVARIANT of the position: a role's prose never overrides what its own form
        # says, so a field that names a file that is not there is REPORTED missing (FR-37) and the prose path is not
        # used in its place - a wrong form is the role's defect to correct, not a guess for the driver. A field and
        # a prose path that disagree: the field is used and the ignored prose path is named in a `[driver]` note.
        def prose_path() -> str:
            for candidate in reversed(PATH_RE.findall(str(result.get("result") or ""))):
                rel = candidate.replace("\\", "/")
                if rel.startswith("/") or re.match(r"^[A-Za-z]:", rel):
                    continue              # a digest names a path relative to the task or the project, never absolute
                if (self.task_root / rel).is_file() or (self.project / rel).is_file():
                    return rel
            return ""

        fields = [str(node.value or "").strip() for node_path, node in doc.nodes.items()
                  if node_path.startswith("artifacts.") and not handoff.is_placeholder(str(node.value or "").strip())]
        path = ""
        if fields:
            path = next((v for v in fields if not (v.replace("\\", "/").startswith("/") or re.match(r"^[A-Za-z]:", v))
                         and (self.task_root / v).is_file()), "")
            if not path:
                return "", (f"the form's artifact path `{'`, `'.join(fields)}` is not a relative path of a file on disk "
                            "(a path named in the role's message is not used in its place: the form is the role's to correct)")
            ignored = prose_path()
            same = ignored and ({(self.task_root / ignored).resolve(), (self.project / ignored).resolve()}
                                & {(self.task_root / path).resolve()})      # one file spelled two ways is not a disagreement
            if ignored and not same:
                print(f"[driver] {dispatch}: the form's artifact path {path} is used; the path the role's message names "
                      f"({ignored}) is ignored - the form's own field comes first", flush=True)
        else:
            path = prose_path()
        if not path:
            return "", "no artifact path of the role is a file on disk"
        digest = "\n".join([f"{role} {stage} {window} · {verdict}", *rows, path, "assembled_by: code"])
        if len(digest) > DIGEST_MAX:
            return "", f"the assembled form is {len(digest)} characters and the digest limit is {DIGEST_MAX}"
        if len(digest.splitlines()) > 40:        # `digest_of` keeps the last 40 lines of what it reads back
            return "", (f"the assembled form is {len(digest.splitlines())} lines and a digest keeps the last 40 "
                        "(its header would be cut when it is read back)")
        return digest, ""

    def keep_assembled_result(self, dispatch: str, result: dict, digest: str) -> None:
        """The assembled digest is the dispatch's saved result from now on, `assembled_by: code` on the record and the
        role's own last message kept whole beside it (`role_final_message`): a re-entry through `wait_existing_job`
        judges the digest, and nobody has to take the code's word that the role said something else."""
        _write_json(self.state_dir / "driver-runs" / f"{dispatch}.json",
                    dict(result, result=digest, assembled_by="code", role_final_message=str(result.get("result") or "")))

    def keep_resumed_result(self, dispatch: str, resumed: dict, before: dict) -> None:
        """The role's NEW words are the dispatch's saved result from now on (t-217 O1, critic t-244).

        `handoff`'s own in-session resumes (`again`, `third`) used to leave `state/driver-runs/<dispatch>.json` holding the
        FIRST result. After a conductor `continue` on the still-open dispatch, `wait_existing_job` re-judged that stale
        result, found its finding set already in `refusal_resumes`, and raised a false "came back with the same findings"
        question - before the resume record existed another resume would have repaired it. `resume_with` already does
        this for the refusal's resume (its rule: an error with no words is spent and not written); this is the same rule
        at the handoff's two resumes. Callers pass only a non-empty `result`; the session id of the first result stays
        when the resume reports none (a result with no session cannot be bound or resumed again)."""
        if not str(resumed.get("result") or "").strip():
            return
        _write_json(self.state_dir / "driver-runs" / f"{dispatch}.json",
                    dict(resumed, session_id=resumed.get("session_id") or before.get("session_id") or ""))

    def stand_probe(self, dispatch: str):
        """(c)(d): None when the stand clause does not apply; else (answers, the probe's output whole).

        It applies only when the saved result's digest holds a row whose STATE is `blocked_by_env` (a closed
        vocabulary value, never prose - FR-12) and the story names a stand. The probe is `env_probe.py` - the tool
        `stand_check` already uses (FR-17). It answers only when it exits 0 AND prints something: a probe that fails,
        crashes or prints nothing does not answer (FR-41). Nothing is written here."""
        saved = _read_json(self.state_dir / "driver-runs" / f"{dispatch}.json")
        text = saved.get("result") if isinstance(saved, dict) else ""
        environment = str(self.pipeline().get("environment") or "")
        if not isinstance(text, str) or not text.strip() or not environment:
            return None
        try:
            import role_digest
            rows = role_digest.parse(self.digest_of(text)).get("rows") or []
        except Exception:
            return None
        if not any(row.get("state") == "blocked_by_env" for row in rows):
            return None
        try:
            code, out = self.py("env_probe.py", "--env", environment, "--task", self.task)
        except Exception as exc:
            return False, f"the probe could not run: {type(exc).__name__}: {str(exc)[:200]}"
        out = str(out or "").strip()
        return (code == 0 and bool(out)), (out or "the probe printed nothing")

    def code_doors(self, stage: str, role: str, dispatch: str) -> list:
        """C2-4 (K9): run the doors of CODE that a role would otherwise be paid to walk, and return the names of those that WROTE.

        Chosen by (stage, role) and by the file they would change - never by the refusal's words (FR-12): the form (`handoff_check
        --fix --shorten`), the code critic's review receipt (`window_record --review-receipt`; only when the review's findings file
        exists - a receipt is immutable, and the role is woken for the missing findings anyway, t-909 F-10), the scout's source
        receipts (`ticket_adapter receipts`, for a story that began before the writer stamped them). 'Wrote' is a different sha256
        of the target file before and after (`_sha`), not an exit code and not a sentence: `handoff_check --fix` rewrites its file
        on every call. ERROR DIRECTION (I4): a door that errs only fails to write; none ever stamps a window the role did not see
        (`window_record` itself refuses a window with a gap, a stale review or a collision)."""
        root = self.task_root
        doors = []
        if (root / "work" / "handoffs" / f"{dispatch}.yaml").is_file():
            doors.append(("form", root / "work" / "handoffs" / f"{dispatch}.yaml",
                          lambda: self.form_report(dispatch, shorten=True)))
        if stage == "S5" and role == "qa-code-critic":
            import story_step
            if story_step._role_receipts(root, role, dispatch):
                doors.append(("review receipt", root / "work" / "automation-manifest.json",
                              lambda: self.py("window_record.py", "--task", self.task, "--dispatch", dispatch, "--review-receipt")))
        inventory = root / "work" / "source-inventory.json"
        if role == "qa-scout" and inventory.is_file():
            doors.append(("source receipts", inventory,
                          lambda: self.py("ticket_adapter.py", "receipts", "--output", str(inventory))))
        wrote = []
        for name, target, run in doors:
            before = _sha(target) if target.is_file() else ""
            run()
            if (_sha(target) if target.is_file() else "") != before:
                wrote.append(name)
        return wrote

    def close_by_doors(self, refusal: Refusal, stage: str, dispatch: str) -> str | None:
        """C2-4 (K9, I2): the step BEFORE every resume of `resume_on_refusal` - what code can write, code writes, and the refused
        call is made again. `"continue"` when the retry went through; `None` when nothing was closed by code (today's road, over
        the refusal as it was).

        POSITION INVARIANT: the caller puts this before the branches ('no dispatch', 'no session', the first resume, the stand,
        'already resumed'), so none of them sees a refusal the code closed - and NOT inside `key not in record`, where the
        'already resumed' branch would never meet it. It is not a resume: no `note_resume`, the 'once per finding set' of the role
        is untouched (I3). BOUNDS: once per (dispatch, finding key) in this process (a door that rewrites its file on every pass
        cannot loop it), and never from inside its own retry (`in_code_step`, t-909 F-2): a NEW refusal the retry raises takes
        the whole road of `handle_refusal` (t-721 F-17), but that road's `resume_on_refusal` skips this step, so a chain of
        refusals with changing keys cannot recurse here - `guarded`'s cap counts the turns it sees."""
        if not dispatch or not refusal.retry or self.in_code_step:
            return None
        key = finding_key(self.refusal_lines(refusal))
        if (dispatch, key) in self.doors_tried:
            return None
        self.doors_tried.add((dispatch, key))
        wrote = self.code_doors(stage, self.dispatch_role(dispatch), dispatch)
        if not wrote:
            return None
        self.in_code_step = True
        try:
            try:
                refusal.retry()
            except Refusal as again:
                if finding_key(self.refusal_lines(again)) == key:
                    return None
                print(f"refusal: {dispatch}: code wrote ({', '.join(wrote)}) and the refusal changed; it takes the whole road")
                return self.handle_refusal(again)
        finally:
            self.in_code_step = False
        self.drop_standing()            # E2: the refused step went through
        print(f"refusal: {dispatch} closed by code ({', '.join(wrote)}) - no resume")
        return "continue"

    def resume_on_refusal(self, refusal: Refusal, stage: str, head: str) -> str:
        """(c) A refusal of the role's handoff or of its `finish` (exit 3) answered after the role's session ended.
        Returns "continue" (the role was resumed once; the loop goes on from its new result) or raises Person.

        INVARIANTS: a role is never resumed twice for the same finding set on one dispatch+session, across entries and
        relaunches (`refusal_resumes`, written BEFORE the call); a role that has not seen these findings is resumed
        once before anyone else is asked; the stand is looked at once per dispatch+session, never per set; the
        CONDUCTOR is never asked about an IDENTICAL finding set (fork 3: a second identical refusal is a fact the factory
        already knows and a $0.3 call can add nothing - F-cmp2-11, -16, -27): the person gets the priced fallback question
        (C1-1). No dispatch or no session, and a stand that does not answer: the seam calls the conductor once."""
        dispatch = self.refusal_dispatch(refusal) or head
        sid = self.refusal_sid(dispatch) if dispatch else ""
        closed = self.close_by_doors(refusal, stage, dispatch)      # C2-4: before EVERY branch below (I2)
        if closed:
            return closed

        def person(lead: str, details: str = "", call: bool = False) -> str:
            # The seam (C1-1). No session and a stand that does not answer CALL the conductor (it has moves for them: the
            # stand, a restart); the repeat of an identical finding set does not (t-217 fork 3: no paid repeat on the same set
            # - the person gets the priced fallback question; D-0039 weighs this and the owner's answer is open).
            return self.no_move({"why": "refusal", "kind": "refusal", "call": call, "stage": stage, "dispatch": dispatch,
                                 "lead": lead + self.question_from_refusal(refusal, stage), "text": details or refusal.text,
                                 "lines": self.refusal_lines(refusal)})

        if not dispatch:
            print("refusal: no session of the role is known; the person is asked")
            return person("", call=True)
        if not sid:
            # t-764 E9 (FR-42): the dispatch is known and no session of it is - the one seam says so, with no `round`
            print("refusal: no session of the role is known; the person is asked")
            self.exit_limit(stage, self.dispatch_role(dispatch), dispatch, self.refusal_lines(refusal), sid="", why="refusal", text=refusal.text)
        key = finding_key(self.refusal_lines(refusal))
        record = self.resume_record(dispatch, sid)
        if key not in record:
            self.note_resume(dispatch, sid, key, "refusal")
            print(f"refusal: {dispatch} is resumed in its own session with the refusal, once")
            self.resume_with(refusal, stage, dispatch, sid, "The factory refused to close your dispatch "
                             + dispatch + ":\n\n")
            return "continue"
        if "stand" not in record.values():
            probe = self.stand_probe(dispatch)
            if probe is not None:
                answers, out = probe
                if not answers:
                    print("refusal: the role reported its work blocked by the stand and the stand does not answer; "
                          "the person is asked")
                    return person("The stand did not answer when I looked at it just now, so what the role was "
                                  "stopped by has not changed.\n\n",
                                  refusal.text + "\n\nWhat the probe of the stand printed:\n" + out, call=True)
                self.note_resume(dispatch, sid, key, "stand")
                print(f"refusal: the stand answers now; {dispatch} is resumed with the probe's words, once")
                self.resume_with(refusal, stage, dispatch, sid,
                                 "The stand answers now:\n" + out + "\n\nThe factory refused to close your dispatch "
                                 + dispatch + ":\n\n",
                                 reason="the role reported its work blocked by the stand and the stand answers now; "
                                 + resume_reason(refusal.findings or refusal.text))
                return "continue"
        print(f"refusal: {dispatch} was already resumed on these findings; the person is asked")
        # t-764 E8: the ONE seam (the finish refusals `story_step finish (exit 3)` reach only this site); a round the person
        # bought is spent there and the loop judges the role's new result
        self.exit_limit(stage, self.dispatch_role(dispatch), dispatch, self.refusal_lines(refusal), sid=sid, why="refusal", text=refusal.text)
        return "continue"

    def window_key(self, stage: str, dispatch: str) -> str:
        """`<stage>|<the dispatch's scope, sorted and joined by commas>` from the controller's dispatch record
        (the S5 window's cases); the dispatch's own id when the record or its scope cannot be read (then the series
        cannot accumulate across dispatches and the conductor's per-boundary cap is the only bound, as before);
        "" with neither."""
        try:
            record = (self.controller_state().get("dispatches") or {}).get(dispatch) or {}
            scope = sorted({str(item) for item in (record.get("scope") or []) if item})
        except Exception:
            scope = []
        if scope:
            return self.window_id(stage, scope)
        return f"{stage}|{dispatch}" if dispatch else ""

    PROBE_GAP_LEAD_LIMIT = 10

    @classmethod
    def probe_gap_lead(cls, pairs) -> str:
        """B-16: the LEAD of the S5 seam question that offers the probe-gap word, in `human-questions.md` form (what the factory did, why
        it cannot decide, whose gap, one question; no field, script, path or dispatch id). `pairs` = `window_record.probe_gap_cases`:
        `[(case key, [instance ids])]`. The text is the owner's (05.11.2026 19:00): it says the word covers the whole CLASS of tests whose
        check the tool could not read, because that is what the record does (`contract.probe_gap_class_word`). At most
        `PROBE_GAP_LEAD_LIMIT` cases are listed, then `, and <k> more`; every case is still recorded by `seam_chosen`."""
        shown = [f"{case} (the test \"{(ids or [''])[0]}\")" for case, ids in list(pairs)[:cls.PROBE_GAP_LEAD_LIMIT]]
        more = len(pairs) - len(shown)
        listed = "; ".join(shown) + (f", and {more} more" if more > 0 else "")
        return (f"The review of this window of tests is finished. {len(pairs)} test case(s) ran green, but for each of them the factory "
                "could not run the check that proves the test would catch a broken product, because its own tool cannot read these "
                f"tests: {listed}. That is a gap in the factory's tool, not a flaw in the tests, and only you can accept it.\n\n"
                "If you answer `go on`, the factory records your words once for each case named above. From then on your words cover "
                "every test of this story whose check the tool could not read: the tests named here, other tests of the same cases, "
                "and tests in later windows of this story. The tests themselves are not changed; they are only not checked that way.")

    PROBE_JUDGMENT_LEAD_LIMIT = 10
    PROBE_JUDGMENT_STATEMENT_LIMIT, PROBE_JUDGMENT_WHY_LIMIT = 120, 160

    @classmethod
    def probe_judgment_lead(cls, pairs) -> str:
        """t-1968 N5: the LEAD of the S5 seam question for tests whose probe the code reviewer could not judge, in `human-questions.md`
        form (what the factory did, why it cannot decide, whose decision, the answers; no field, script, path or dispatch id). `pairs` =
        `window_record.probe_judgment_cases`: `[(case key, [{iid, line, statement_inverted, statement_after, printed, why, ...}])]`. The text is the spec's
        (the owner's word 05.11.2026): it covers THESE cases only and says an earlier answer about tooling does not cover them. One entry per
        TEST: the case, the test, the line of the broken check and the statement (at most 120 characters), what it printed (the lines
        `window_record` kept) and the reviewer's reason (at most 160); at most `PROBE_JUDGMENT_LEAD_LIMIT` tests are listed, then `, and <k> more`.
        An entry's missing datum is said plainly, never invented and never a crash. Pure."""

        def cut(text, limit):
            one = " ".join(str(text or "").split())
            return one if len(one) <= limit else one[:limit - 1] + "…"

        entries = [(str(case), item) for case, items in pairs for item in items or [] if isinstance(item, dict)]
        shown = []
        for case, item in entries[:cls.PROBE_JUDGMENT_LEAD_LIMIT]:
            # the person reads the check as the plain inversion (`statement_inverted`), never the written statement with the factory's own
            # marker expression in it (F5); a detail with no inversion text (a probe that wrote no marker) wrote the plain statement
            line = item.get("line")
            statement = cut(item.get("statement_inverted") or item.get("statement_after"),
                            cls.PROBE_JUDGMENT_STATEMENT_LIMIT).replace("`", "'")
            where = f"the check broken at line {line}" if line not in (None, "") else "the check it broke"
            printed = cut(item.get("printed"), 10 ** 6)
            said = cut(item.get("why"), cls.PROBE_JUDGMENT_WHY_LIMIT)
            shown.append(f"{case}: the test \"{item.get('iid') or ''}\", {where}" + (f" (`{statement}`)" if statement else "")
                         + (f", it printed \"{printed}\"" if printed else ", it printed nothing the factory kept")
                         + f"; the reviewer said: {said or 'no reason was given'}")
        more = len(entries) - len(shown)
        listed = "; ".join(shown) + (f", and {more} more" if more > 0 else "")
        return (f"The review of this window of tests is finished, but for {len(pairs)} test case(s) the factory could not prove that a "
                "test would catch a broken product. It broke one check in each test and ran it; the test failed, and the code reviewer "
                "could not tell whether it failed because of that check or for another reason: "
                f"{listed}. Only you can decide what happens to these tests.\n\n"
                "Answer `go on` to accept them as not proved: your words are recorded for these cases only, and the report lists them as "
                "not proved. Answer `rework` to send them back to their author with your words. An earlier answer about tests the "
                "factory's tool could not read does not cover these.")

    def window_round_gate(self, refusal: Refusal, stage: str) -> None:
        """F-cmp2-28c: a cap on the rework rounds the CONDUCTOR may start over one window. Returns to let the
        conductor have it, or raises Person.

        The loop was unmatched refusal -> conductor -> rework -> new dispatch -> new boundary -> three fresh conductor
        calls (the per-boundary cap lives in memory, keyed by the boundary): cmp2 spent 11 automators and 4 critics on
        one window over the same five gap lines ($7.28). A round is written to `window_rounds` BEFORE the paid call,
        and the series bounds itself: a finding set equal to an earlier round's, or a third round, is the person's.

        POSITION INVARIANT: after every known row of `handle_refusal` (they act first and are never counted);
        `gate_repair`'s `hand_to_conductor` calls `conductor_round` directly and never meets this. A set that
        differs from every earlier round and is within the cap always reaches the conductor. EDGES: no findings
        (an empty set) is never recorded and never "equal" (FR-41); a stage not in WINDOW_ROUND_STAGES passes; the
        person's answer clears nothing - the same set afterwards asks again, with `ask()`'s FR-7 block.
        DC1-21: the round's kind (`cause`) is `window` when the set is the window record's gap lines
        (`window_findings`), else `refusal` (the factory's own refusal of the call); each kind has its own cap of
        `WINDOW_ROUND_CAP`; `same_set` is judged across both; a record with no or an unknown `cause` counts as
        `window` (an unknown is never free: FR-59)."""
        if stage not in WINDOW_ROUND_STAGES:
            return
        dispatch = self.refusal_dispatch(refusal)
        key = self.window_key(stage, dispatch)
        source = (refusal.window_findings or refusal.findings
                  or [line for line in refusal.text.splitlines()[1:] if line.strip()])
        found = finding_lines(source)               # the COMPARISON form (`<dispatch>` for ids): never what the record is built from
        if not key or not found:
            return
        cause = "window" if refusal.window_findings else "refusal"
        held = self.state.get("window_rounds")
        if not isinstance(held, dict):
            held = self.state["window_rounds"] = {}
        series = held.get(key)
        if not isinstance(series, list):
            series = held[key] = []
        rounds = [r for r in series if isinstance(r, dict) and r.get("outcome") == "to_conductor"]

        def kind(r):
            return "refusal" if r.get("cause") == "refusal" else "window"

        mine = [r for r in rounds if kind(r) == cause]
        scope = key.split("|", 1)[1]
        same = next((i for i, r in enumerate(rounds, 1) if r.get("set") == found), None)
        reason = "same_set" if same is not None else ("cap" if len(mine) >= WINDOW_ROUND_CAP else "")
        if reason:
            if not any(isinstance(r, dict) and r.get("set") == found and r.get("outcome") == reason for r in series):
                series.append({"at": _now(), "dispatch": dispatch, "set": found, "outcome": reason, "cause": cause})
                self.save_state()
            if reason == "same_set":
                print(f"{stage} window {scope}: round {len(rounds) + 1} came back with the same {len(found)} "
                      f"finding(s) as round {same} — no further rework; the person is asked")
                if cause == "refusal":
                    lead = (f"The factory's own checks refused this window again with the same reasons as round {same}. "
                            "Nothing was reworked: the reasons are not about its tests. Tell me how to go on.\n\n")
                else:
                    lead = (f"This window came back with the same findings as round {same}; the driver does not "
                            "rework it again.\n\n")
            elif cause == "refusal":
                print(f"{stage} window {scope}: {WINDOW_ROUND_CAP} rounds over refusals that are not about the "
                      "window's tests are spent - the person is asked")
                lead = (f"The factory's own checks refused this window {len(mine)} times for reasons that are not "
                        "about its tests, and the driver does not hand it on again.\n\n")
            else:
                print(f"{stage} window {scope}: the cap of {WINDOW_ROUND_CAP} rounds is spent — the person is asked")
                lead = (f"The driver has sent this window back for rework {len(mine)} times already and does "
                        "not do it again.\n\n")
            state = {"why": "threshold", "kind": "refusal", "call": False, "stage": stage, "dispatch": dispatch,
                     "lead": lead + self.question_from_refusal(refusal, stage), "lines": self.refusal_lines(refusal, items=source),
                     "text": refusal.text + "\n\nThe findings of this round:\n- " + "\n- ".join(found)}
            if stage == "S5" and dispatch:
                # B-16: the window's green tests whose probe the tool could not read: the question names their case keys and carries
                # them in `asked` (the `rows` pattern); `seam_chosen` records `probe gap: <case key>` for each on `go on`. The record
                # on disk is the one the driver rebuilt at the finish. No such case (red only, never run, no record): today's question.
                import window_record
                record = _read_json(self.task_root / "work" / "windows" / f"{dispatch}.json")
                # t-1968 N5: the tests whose probe the code reviewer could not judge are read FIRST (the person's own question, the owner's
                # word 05.11.2026); the probe-gap question below runs only when there are none. ONE question per seam (AR-16): the other
                # kind comes at the next refusal, and no word is recorded for a token the person did not choose.
                judged = window_record.probe_judgment_cases(record, self.task_root)
                pairs = [] if judged else window_record.probe_gap_cases(record, self.task_root)
                if judged:
                    state["probe_judgment_cases"] = [case for case, _items in judged]
                    state["lead"] = self.probe_judgment_lead(judged)
                elif pairs:
                    state["probe_gap_cases"] = [case for case, _ids in pairs]
                    state["lead"] = self.probe_gap_lead(pairs)
            self.no_move(state)
        series.append({"at": _now(), "dispatch": dispatch, "set": found, "outcome": "to_conductor", "cause": cause})
        self.save_state()
        number = len(mine) + 1
        if cause == "refusal":
            print(f"{stage} window {scope}: refusal round {number} of {WINDOW_ROUND_CAP} goes to the conductor - the "
                  "refusal is not about the window's tests; the window's own rounds stay "
                  f"{sum(1 for r in rounds if kind(r) == 'window')} of {WINDOW_ROUND_CAP}")
            return
        print(f"{stage} window {scope}: round {number} of {WINDOW_ROUND_CAP} goes to the conductor"
              + (" (the findings changed)" if number > 1 else ""))

    def handle_refusal(self, refusal: Refusal, *, words: str = "") -> str:
        """Returns 'continue' or 'retry'; raises Person / Stop when the loop must end."""
        stage = self.boundary.split(":")[0]
        if refusal.title == "second_delivery":
            # P49: a second hand-over of the delivery in one process cannot add anything a paid call would (it could create the
            # branch and the merge request twice): no call, the priced question with the two answers that mean something.
            # Keyed on the TITLE the raiser gave, never on a regex over the sentence; BEFORE `match_known` on purpose.
            return self.no_move({"why": "refusal", "kind": "refusal", "call": False, "stage": stage, "dispatch": "",
                                 "fallback": ["retry", "stop"], "lead": self.question_from_refusal(refusal, stage),
                                 "text": refusal.text, "lines": self.refusal_lines(refusal)})
        known = route_known(refusal)
        committed, recover_failed = False, ""
        if known and known[0] == "gate_stage":
            # t-211 / C9: the row lets the driver go on ONLY over a stage the controller has already closed
            # (story_step accepts, and only then calls stage_done). An open stage is not this refusal's
            # case: it falls to the conductor, as it did before the row existed. What the refused finish
            # skipped (S4's case appendix, S8's report rebuild) is owed at gate entry (C10).
            if not self.stage_completed(stage):
                known = None
            else:
                owed = self.state.setdefault("gate_entry_owed", {})
                owed[stage] = _now()
                self.save_state()
        if known and known[0] == "s0_receipt" and stage != "S0":
            # C2-8 B2 (measured t-763): the row answers with the move of S0 (`code_only("S0")`) and so only a refusal raised ON THE
            # BOUNDARY OF S0. The same door at S1-S9 (the retro's record at S9) is not S0's: the receipt would be refused inside this
            # method and the run would end in `funnel`. ERROR DIRECTION: too few moves of code is allowed (the S0 boundary under another
            # name goes to the conductor), the move of S0 on another stage is forbidden. Exact stage equality, never a prefix.
            known = None
        if known:
            name, action = known
            if action in ("resume_handoff", "resume_repair") and re.search(STRUCTURED_RE, refusal.text, re.IGNORECASE | re.DOTALL):
                # INVARIANT: one text with a form problem AND a structured-artifact problem resumes the role
                # ONCE, with the whole text. The rows above (and the marker) only say "the role site resumed
                # already" - true for `handoff`, never for a `finish` refusal - so the first match must not win.
                name, action = "structured_artifact", "resume_structured"
            self.journal_conductor(stage=stage, refusal=refusal.text[:2000], action="known:" + name, did=action)
            print(f"refusal: known `{name}` → {action}")
            if action == "ask_person":
                return self.no_move({"why": "refusal", "kind": "refusal", "call": False, "stage": stage,
                                     "dispatch": self.refusal_dispatch(refusal), "lines": self.refusal_lines(refusal),
                                     "lead": self.question_from_refusal(refusal, stage), "text": refusal.text,
                                     # RN1-9 (E-20): a code-raised question's class is its `code_routes` row; None when it has none
                                     "why_person": PO.code_route(name), "source": "code"})
            if action in ("s1_review", "s1_gap"):
                parts = self.boundary.split(":")
                dispatch = parts[1] if len(parts) > 1 and parts[1].startswith("S1-") else ""
                # The field first, the sentence only for a refusal some other script raised.
                m = re.search(S1_DISPATCH_RE, refusal.text)
                dispatch = dispatch or refusal.dispatch or (m.group(1) if m else "")
                if action == "s1_gap" and self.close_vcs_gaps([refusal.text]):
                    # Collected through the factory's own authenticated route: the gate reads the
                    # inventory again instead of the person answering about material we now have.
                    return "retry"
                text = (self.s1_review_text(refusal.text) if action == "s1_review"
                        else self.s1_gap_text(refusal.text))
                raise Person(action, text, stage, dispatch,
                             answer_note=(human_text.onboarding_note(self.pipeline().get("environment"), self.config.get("environments"))
                                          if action == "s1_review" else ""))
            if action == "retry":
                return "retry"
            if action == "recover":
                try:
                    self.controller("recover")
                    if name == "committed_event" and self.stage_completed(stage):
                        # A finish refused over a stage the controller has CLOSED (the event is in the journal)
                        # skipped the stage's tail exactly as `gate_stage` does: S4's case appendix, S8's report
                        # rebuild. The same mark, so the gate entry runs what a normally closed stage ran - once
                        # (one key per stage). A stage that is not completed is not marked.
                        self.state.setdefault("gate_entry_owed", {})[stage] = _now()
                        self.save_state()
                    return "continue"
                except Refusal as again:
                    # `recover` itself said no. That is a refusal no row here answers, so it
                    # goes where an unknown one goes - the conductor - and `recover` is not run
                    # a second time. The conductor is shown BOTH texts: what was refused first
                    # and what recover said about it, because it has to judge the pair.
                    recover_failed = again.text
                    if name == "committed_event":
                        committed = True
            if action == "code_only_s0":
                self.code_only("S0", "preflight green: S0 closed on a task initialized before it",
                               ["pipeline.json"])
                return "continue"
            if action == "initialize":
                self.initialize()
                return "continue"
            if action == "error":
                raise Stop(EXIT_ERROR, refusal.text)
            if action == "rebuild_report":
                # R-S9.1 / FR-42: the driver's own move on the S9 exit's report check, ONCE per boundary:
                # `--write`, then the very call that was refused, again. The count lives in the state file
                # under the boundary (`S9`, or `S9:<dispatch>`), so a driver started again after an exit 3
                # meets it too and cannot go write -> refuse -> write for ever. A refusal with no call to
                # repeat, or the same refusal a second time, is the conductor's - never the person's.
                done = self.state.setdefault("report_rebuilds", {})
                if refusal.retry and not done.get(self.boundary):
                    done[self.boundary] = 1
                    self.save_state()
                    self.rebuild_report()
                    return "retry"
                print("refusal: the report check refused again after the rebuild; the conductor is called")
            elif action == "resume_structured":
                # FR-42 / FR-48: the role's own session gets the refusal, ONCE per dispatch; the count lives
                # in the state file (survives an exit-3 relaunch). Never the conductor, never a fresh session.
                # The same refusal again, or no session to resume, is the person's (the refusal beside, whole).
                parts = self.boundary.split(":")
                dispatch = refusal.dispatch or (parts[1] if len(parts) > 1 and re.fullmatch(r"S\d+-[\w-]+-\d+", parts[1]) else "")
                if not dispatch:
                    m = re.search(r"story_step finish (S\d+-[\w-]+-\d+) \(exit", refusal.text)
                    dispatch = m.group(1) if m else ""
                sid = self.state["sessions"].get(dispatch) if dispatch else ""
                done = self.state.setdefault("structured_resumes", {})
                if not sid or done.get(dispatch):
                    print("refusal: the structured artifact is refused again (or no session is known); the person is asked")
                    if dispatch:
                        # t-764 F-d6 (E11): the same class as the handoff's - one resume spent, the dispatch not accepted. The key of
                        # the set is `finding_key` of the refusal's lines (`structured_resumes` is per dispatch), so a round the person
                        # buys is counted for THIS set; a round is spent there and the loop judges the role's new result
                        self.exit_limit(stage, self.dispatch_role(dispatch), dispatch, self.refusal_lines(refusal), sid=sid or "",
                                        why="structured", text=refusal.text)
                        return "continue"
                    return self.no_move({"why": "refusal", "kind": "refusal", "call": False, "stage": stage,
                                         "dispatch": self.refusal_dispatch(refusal), "lines": self.refusal_lines(refusal),
                                         "lead": self.question_from_refusal(refusal, stage), "text": refusal.text})
                done[dispatch] = 1
                self.save_state()
                try:
                    role = str(((self.controller_state().get("dispatches") or {}).get(dispatch) or {}).get("role") or "")
                except Exception:
                    role = ""
                role = role or (re.fullmatch(r"S\d+-(qa-[a-z-]+)-\d+", dispatch) or [None, ""])[1]
                print(f"refusal: {dispatch} is resumed in its own session with the refusal, once")
                self.run_claude("role", "The factory refused to close your dispatch " + dispatch + ":\n\n" + refusal.text.strip()
                                + "\n\nRepair the named fields in the artifact, change nothing else, then your final "
                                  "message is the handoff form only.", role=role, dispatch=dispatch, stage=stage, resume=sid,
                                resume_reason=resume_reason(refusal.findings or refusal.text))
                return "retry"
            elif action in ("resume_handoff", "resume_repair"):
                # t-217 / F-cmp2-23: a refusal of the role's handoff or of its `finish` (exit 3) is answered by the
                # role's OWN session, once per finding set, then the stand, then the PERSON - never the conductor
                # (a declared change of the old "the role site already resumed once; below it is the conductor's").
                # Any other refusal with such a marker (a refusal of the CALL class, a text that only quotes a head)
                # stays on the conductor road below.
                head = self.resumable_head(refusal.text)
                if head:
                    return self.resume_on_refusal(refusal, stage, head)
            elif action == "continue":
                return "continue"
        if refusal.close and not recover_failed and not (known and known[0] == "report_check"):
            # C2-8 (K3): a stage the CODE closes with no role - there is no role to resume and no point in a paid call about the text.
            # POSITION INVARIANT: after the known rows that have a move of code (I1: `story_budget`, `already_done`, the first
            # `report check:`), so none of them is taken from code; the SECOND `report check:` (R-S9.1: never the person's) and a
            # refusal whose own `recover` refused (both texts to the conductor) are the conductor's, as before; before
            # `window_round_gate` (no S5 window refusal carries `close`).
            return self.code_close(refusal)
        self.window_round_gate(refusal, stage)
        return self.conductor_round(refusal, stage, words=words, recover_failed=recover_failed,
                                    committed=committed)

    def conductor_round(self, refusal: Refusal, stage: str, *, words: str = "", recover_failed: str = "",
                        committed: bool = False) -> str:
        """The conductor call an unmatched refusal gets, and what its verdict means: 'continue' or 'retry',
        or a Person / Stop. Split out of `handle_refusal` (t-211) so the gate-entry repair can hand its list
        over through the SAME call without passing the text through `match_known`: the table matches
        anywhere in a text, and a finding that happens to hold `already completed` or `expected_revision`
        would turn into `continue` or `retry` and loop (the list is the factory's own words, not a refusal).

        `recover_failed` is what the controller's `recover` said when a known row ran it and it refused
        too (the conductor is shown both texts); `committed` says the refused event is already in the
        journal, so a `retry` verdict is read as `continue`. The gate-entry caller (`hand_to_conductor`)
        passes neither: its behaviour is the table-less call it always was."""
        shown = refusal.text
        if recover_failed:
            shown = (refusal.text + "\n\n## `controller.py --operation recover` was run for it and "
                     "refused too\n" + recover_failed)
        action = self.no_move({"why": "refusal", "kind": "conductor", "stage": stage, "dispatch": self.refusal_dispatch(refusal),
                               "text": shown, "words": words, "files": refusal.files, "lines": self.refusal_lines(refusal)})
        if committed and action == "retry":
            # The event of this refusal is IN the journal: running the action again would write
            # it twice (`story_step start` would dispatch a second time). `retry` has no meaning
            # here, so it is read as the nearest thing that does: back to `where`. Any other
            # row keeps what `retry` means - its action was refused, nothing was committed.
            print("conductor: `retry` of a committed event is read as `continue` - the action is not repeated")
            return "continue"
        # `continue` / `retry` after a conductor move; anything else was a Person raised by the seam (never a silent return).
        # An `ask_person` with no question, or no usable options, is not an answer and the refusal is not pasted in place of
        # one: the seam renders the priced fallback question and journals the factory's own defect (once).
        return action

    # --- S0 by code ------------------------------------------------------------------------
    def quality_check_ids(self) -> list:
        ids = []
        for item in self.config.get("quality_checks") or []:
            ids.append(item.get("id") if isinstance(item, dict) else str(item))
        for profile in self.config.get("profiles") or []:
            gates = (profile or {}).get("quality_gates") or []
            if isinstance(gates, dict):
                gates = gates.get("checks") or gates.get("ids") or []
            for gate in gates:
                ids.append(gate.get("id") if isinstance(gate, dict) else str(gate))
        return [i for i in dict.fromkeys(ids) if i]

    # The artifacts a role reaches for by name, keyed the way a role would ask. Measured on run
    # 5: **129 of 644 reads missed**, and the top of that list is this table's subject - the
    # human plan tried at both levels (`test-plan.md` 8 times, `work/test-plan.md` 5, the same
    # file), the context manifest 7, the bundle 4, the readiness 3. Every path is resolved
    # through the registry that the writers use, never spelled here (FR-15, FR-37).
    # t-304 N1: the table and the map built from it live in `runtime_paths` (the READERS of the stored map resolve it
    # through the same table); the name stays here as an alias, and the map is the writer's body unchanged (Q2).
    import runtime_paths as _rp
    KNOWN_ARTIFACTS = _rp.KNOWN_ARTIFACTS
    del _rp

    def known_paths(self) -> dict:
        import runtime_paths
        return runtime_paths.known_paths(self.task_root, project=self.project, plugin=self.plugin, log=print)

    def initialize(self) -> None:
        # The controller's source_revision is the hash of the story's ONE ticket snapshot: the
        # JSON is the canon; a story begun before that keeps hashing the `.md` it wrote; with
        # neither on disk the seed is the task and the time, as it always was.
        work = self.task_root / "work"
        snapshot = next((p for p in (work / "ticket-snapshot.json", work / "ticket-snapshot.md")
                         if p.is_file()), None)
        seed = snapshot.read_bytes() if snapshot else (self.task + _now()).encode("utf-8")
        state = self.controller_state()
        request = {"source_revision": hashlib.sha256(seed).hexdigest(), "scope": [],
                   "known_paths": self.known_paths(), "required_quality_checks": self.quality_check_ids(),
                   "coverage_contract_version": 2, "plan_contract_mode": "new",
                   "source_inventory_required": True, "expected_revision": state.get("revision", 0),
                   "idempotency_key": f"initialize:{self.task}:driver"}
        self.controller("initialize", input_data=request)
        print("controller initialized")

    def code_only(self, stage: str, reason: str, evidence: list) -> str:
        """The code-only receipt of `stage`; returns its id (the receipt a deferred record is tied to, C2-8 I4). The refusal for missing
        evidence carries the title `code_only_evidence`, so `close_receipt` tells it from the controller's own refusal by the field."""
        refs = []
        for rel in evidence:
            path = self.task_root / rel
            if path.is_file():
                refs.append({"path": rel, "sha256": _sha(path)})
        if not refs:
            raise Refusal(f"code-only {stage}: none of {evidence} exists to stand as evidence", title="code_only_evidence")
        state = self.controller_state()
        n = len([e for e in (state.get("dispatches") or {}) if str(e).startswith(f"{stage}-code-only")]) + 1
        receipt = f"{stage}-code-only-{n}"
        self.controller("code_only", input_data={"id": receipt, "stage": stage, "reason": reason,
                                                 "evidence_refs": refs, "expected_revision": state.get("revision", 0),
                                                 "idempotency_key": f"code_only:{stage}:{n}"})
        self.progress_line()            # the stage is closed by code, not by a role
        return receipt

    def close_receipt(self, site: str, stage: str, reason: str, evidence: list) -> str:
        """`code_only` at a site of `CODE_CLOSE_SITES` (C2-8): the same call, a refusal it raises is marked `close` with the step that
        failed - `evidence` (a file the receipt stands on is missing) or `receipt` (the controller said no). Returns the receipt id."""
        try:
            return self.code_only(stage, reason, evidence) or ""
        except Refusal as refusal:
            if site:
                refusal.close = {"site": site, "stage": stage, "step": "evidence" if refusal.title == "code_only_evidence" else "receipt"}
            raise

    def record_close(self, site: str, stage: str, *args, tail=(), receipt: str = "") -> None:
        """THE record of a stage the code closed (C2-8): `stage_done --stage <stage> <args>`, then the `tail` (lists of `log_append`
        arguments, e.g. the `dispatch_skipped` row). A refusal is marked `close` (step `record`, with what a deferred record needs) and
        its `retry` repeats the WHOLE record - the write and the tail - never the write alone. A record that goes through drops the stage's
        `code_close` facts (I8: the next episode of the stage starts clean - its own `recover`, no stale `passed`)."""
        try:
            self.py("stage_done.py", "--task", self.task, "--stage", stage, *args, check=True)
        except Refusal as refusal:
            if site:
                refusal.close = {"site": site, "stage": stage, "step": "record", "receipt": receipt,
                                 "args": [str(a) for a in args], "tail": [[str(a) for a in line] for line in tail]}
            refusal.retry = lambda: self.record_close(site, stage, *args, tail=tail, receipt=receipt)
            raise
        for line in tail:
            self.py("log_append.py", *line)     # remains: a tail row is a `dispatch_skipped` of a close that is already recorded (M3, t-1214: the only two callers that pass a tail; no `human_answer` rides one); a failed row is no state to ask about
        if site and (self.state.get("code_close") or {}).pop(stage, None) is not None:
            self.save_state()                   # I8: a later episode of this stage starts clean (no stale `recovered` / `passed` / `filed`)

    # --- S0: the story's one ticket snapshot, and a door on every stop (t-017 D1) ------------
    #
    # B-008 / FR-49. The snapshot is `work/ticket-snapshot.json`: the stdout of
    # `ticket_adapter get <T> [--ticket-file F] --json`, byte for byte, and nothing else (t-267: but for the
    # `disagreements[]` a person's text carries when the tracker was read beside it, `s0_compare`). It used
    # to be written as `.md` from the glued stdout+stderr of that call, while the scout's brief
    # (`brief_pack`) names `.json` - so the brief never carried the snapshot the story was
    # built on, and a warning on stderr ended up inside the file.
    #
    # B-004 / FR-4. Every stop S0 raises used to promise "answer `go on`" and then never read
    # the answer: `take_answer` sent it to a conductor that could not act on it (there is no
    # pipeline.json for `waiver.py` to write into), and S0 met the same block again. Now an
    # answer is stored, the step is entered again, and s0 reads it (`s0_read_word`): only the
    # tokens the stop itself offered, or a configured stand's name, or a pasted ticket. Anything
    # else comes back as a question with a CHANGED body (FR-7); nobody parses the person's
    # wording (FR-12) and no conductor is called for it (FR-48).
    SNAPSHOT = "ticket-snapshot.json"
    QUOTE_LIMIT = 300
    CUT = chr(0x2026)                       # the ellipsis that marks a quote cut at the limit
    # What a pass is called in the story's own record: the pipeline warning gate A shows.
    S0_PASS_NAMES = {"ticket_incomplete": "the criteria-reading check", "ticket_title": "the ticket-title check",
                     "stand": "the stand question", "readiness": "the readiness check",
                     "source_list": "the list of sources not to read", "key_form": "the ticket key form check"}
    # Any non-empty text is taken and the ticket reader decides what it found (t-267 C9: the old check
    # of the exact shape was a phrase list, FR-12). The shape below is what lets the reader find the
    # criteria and the comments; the header between the dashes is welcome and not required. The text is
    # read by the same parser as a description fetched from the tracker (t-281 F1): a section named like the
    # criteria, then a list - any bullet or number.
    PASTE_SHAPE = ("paste the ticket here as text: the title on the first line (a line that starts with `# ` is "
                   "taken as the title wherever it stands), then the description, then a section named "
                   "`Acceptance criteria` with a list - bullets or numbers - and then a `## Comments` section "
                   "with one line per comment as `- **author** (date): text`, if the ticket has any; a header "
                   "between two lines of three dashes (key, type, status, parent) is welcome and not required")
    # The `stop` option of every priced closed question (S0, the halt, the threshold, the package questions): ONE definition.
    STOP_OPTION = {"answer": "stop", "token": "stop", "says": "stop the story here; nothing runs"}
    # The `says` of the `ungrounded` and `not built yet` answers: the twins `s0.no_change` and `s1.no_diff` (AR-19) use ONE text.
    UNGROUNDED_SAYS = ("go on with the requirements only, on the code the stand runs now; a test that goes red is judged like any red")
    NOT_BUILT_YET_SAYS = ("the code for this story is not written yet: the tests are written now from the requirements, using what the "
                          "project already has (page objects, locators of similar pages), and what cannot be known yet gets a "
                          "named placeholder; the story stops after the tests are written and reviewed and tells you what is missing, "
                          "and when the code exists you start the same story again with the merge request, branch or commit")
    # The one reality word of a side that code reads as "real" (t-2181 PC-2): it must be in `references/side-realities.json`
    # `realities` (test_no_mr_entry.py pins it). QUEUE: fold it into `contract` beside `PARKING_REALITY` once PC-3 is closed to it.
    SIDE_REAL = "real"
    # The paste door of every S0 question that takes the ticket as text: ONE definition (t-684 F6). It has no token - the text
    # itself is the answer (`s0_is_text`) - and its price row is `paste`.
    PASTE_OPTION = {"answer": "paste", "says": f"{PASTE_SHAPE} - I use that instead", "slots": {"what": "paste the ticket"}}
    # The words every S0 stop takes as a door (the tokens of its blocks, see `s0_stop`): a one-word answer that
    # is one of them is the person's word to a stop, never a ticket (a `go on` pasted into `ticket_read`).
    S0_DOOR_WORDS = ("go on", "retry", "not needed", "read", "skip", "mr", "branch", "commit", "no ticket", "current code", "change",
                     "ungrounded", "not built yet", "ours", "another team's", "stop")

    def py_stdout(self, script: str, *args, echo: bool = True, timeout: float | None = None) -> tuple:
        """(exit code, stdout, stderr) of one factory script, the two streams kept apart.

        `py()` glues them, which is right for a refusal that a person or a conductor reads and
        wrong for a script whose stdout is a contract (FR-14): the snapshot was written from the
        glued text. stderr is printed here - it is the driver's log - and is never part of what
        the caller writes to a file.

        `timeout` (seconds, B-364 R15): None, the default, is no ceiling - every caller that passes none is
        byte-identical to what it was. The freshness calls pass one, because a tracker that never answers must not
        hold a resumed story without a word; a script that does not finish says so as `py` does, exit 124 (as
        `timeout(1)`) and an empty stdout, so the caller reads it as "nothing was said", never as a result."""
        path = self.scripts / script
        try:
            done = subprocess.run([sys.executable, "-B", str(path), *[str(a) for a in args]],
                                  capture_output=True, text=True, encoding="utf-8", errors="replace",
                                  cwd=str(self.project), env=self.env, timeout=timeout)
        except subprocess.TimeoutExpired:
            return 124, "", f"{script} did not finish within {timeout} seconds"
        if echo and done.stderr.strip():
            print(done.stderr.strip())
        return done.returncode, done.stdout, done.stderr

    @staticmethod
    def json_object(text: str):
        """The JSON object in `text`, or None - a list, a scalar and prose are not a ticket."""
        try:
            data = json.loads(text)
        except ValueError:
            return None
        return data if isinstance(data, dict) else None

    def ticket_get(self, *extra, echo: bool = True) -> tuple:
        """`ticket_adapter get <T> <extra> --json`: (exit code, stdout, ticket or None, what it said, failure).

        Exit 0 with a stdout that is not one JSON object is a refusal that names the call and the
        head of what it printed, and nothing is written: a snapshot of prose would be read as a
        ticket by every stage after it. It is never a halt for the person (nothing they could
        answer would mend an adapter that printed something else). `echo=False`: the adapter's
        stderr is not printed (the comparison read says its own ONE line, `s0_compare`).

        A non-zero exit carries `failure`, the adapter's error OBJECT (`ticket_failure`): the owner decides the
        move and `retry_at` is read from it, not from the sentence. "What it said" is then the human sentence
        on stderr (the object is its own carrier)."""
        code, out, err = self.py_stdout("ticket_adapter.py", "get", self.task, *extra, "--json", echo=echo)
        both = (out + ("\n" + err if err.strip() else "")).strip()
        ticket = self.json_object(out) if code == 0 else None
        if code == 0 and ticket is None:
            raise Refusal(f"ticket_adapter get {self.task} {' '.join(str(e) for e in extra)} --json "
                          f"exited 0 but printed no JSON object, so no ticket snapshot was written. "
                          f"Expected: the ticket as one JSON object on stdout. It began: "
                          f"{out.strip()[:300]!r}")
        failure = None
        if code:
            failure = self.ticket_failure(code, out, err)
            if failure["from_object"]:
                both = err.strip() or failure["message"]
        return code, out, ticket, both, failure

    NO_ERROR_OBJECT = "the adapter printed no error object"

    def ticket_failure(self, code: int, out: str, err: str) -> dict:
        """The failure of a `ticket_adapter get --json` as `{owner, status, retry_at, message, file, from_object}`.
        The adapter prints ONE error object on stdout on any non-zero exit (FR-14: the machine carrier, so no
        sentence is matched). Exit 5 is auth whatever stdout holds. An exit with no readable object (an older
        adapter, a crash before it printed) is the FACTORY's: it says so in words and is never a question - a
        question to the person cannot mend an adapter that printed something else (FR-3).
        The owner words an object may carry are the adapter's own list, `ticket_adapter.OWNERS` (t-329 item 6: a
        literal copy here had four of the five, so the adapter's `person` - a ticket or paste file that is missing or
        empty - read as "no error object" and turned the person's own missing file into a factory refusal)."""
        import ticket_adapter
        obj = self.json_object(out)
        if obj is not None and obj.get("ok") is False and obj.get("owner") in ticket_adapter.OWNERS:
            return {"owner": obj["owner"], "status": obj.get("status"), "retry_at": obj.get("retry_at") or None,
                    "message": " ".join(str(obj.get("message") or "").split()), "file": obj.get("file") or None,
                    "from_object": True}
        if code == ticket_adapter.EXIT_AUTH_LOST:
            return {"owner": "auth", "status": None, "retry_at": None, "message": " ".join(str(err or "").split()),
                    "file": None, "from_object": False}
        return {"owner": "factory", "status": None, "retry_at": None, "message": self.NO_ERROR_OBJECT,
                "file": None, "from_object": False}

    def ticket_is_factory_fault(self, code: int, failure: dict | None) -> bool:
        """Exit 4, or an object that names the factory as the owner: the factory's own fault, not the tracker's."""
        import ticket_adapter
        return code == ticket_adapter.EXIT_FACTORY_FAULT or bool(failure and failure.get("owner") == "factory")

    def ticket_factory_refusal(self, code: int, failure: dict, said: str = "") -> "Refusal":
        """The factory's own fault while reading the story's ticket: REPORTED, never put to the person as a choice
        (FR-3). Names the file or the config key the adapter named, what was expected and how to restore it
        (FR-1); when the adapter named nothing (no error object) it says so and quotes what the adapter printed."""
        named = failure.get("file")
        what = (f"`{named}` is missing or not usable. " if named else "")
        head = f" It printed: {' '.join(str(said or '').split())[:300]!r}." if failure.get("message") == self.NO_ERROR_OBJECT and said else ""
        return Refusal(
            f"ticket {self.task} could not be read, and the cause is the factory's own - not the tracker's, not "
            f"your ticket: {what}The adapter said: {failure.get('message')} (exit {code}).{head} Expected: the "
            f"factory's own data and settings in order. {'Restore ' + named if named else 'Restore what the message names'}"
            " - a data file from the plugin package, a setting from qa-factory/config.json - and run the same command "
            "again; nothing was asked of you and nothing was written for this story.")

    def write_snapshot(self, out: str) -> None:
        target = self.task_root / "work" / self.SNAPSHOT
        target.parent.mkdir(parents=True, exist_ok=True)
        # bytes, not write_text: the file is the adapter's stdout and must not pick up the
        # host's newline translation on the way to disk.
        target.write_bytes(out.encode("utf-8"))

    def adopt_legacy_snapshot(self) -> None:
        """A story begun before the JSON canon has `work/ticket-snapshot.md` and no `.json`: the
        scout's brief would say "not written yet" for the rest of it. The `.md` (whatever it
        holds - the markdown shape, or the adapter's JSON with a stderr tail, which is what the
        old driver wrote) is read by the adapter and its stdout becomes the `.json`. The `.md`
        stays; an existing `.json` is never overwritten; a failure is one line and writes
        nothing."""
        work = self.task_root / "work"
        legacy, canon = work / "ticket-snapshot.md", work / self.SNAPSHOT
        if not (self.task_root / "pipeline.json").is_file() or canon.is_file() or not legacy.is_file():
            return
        code, out, err = self.py_stdout("ticket_adapter.py", "get", self.task, "--ticket-file",
                                        str(legacy), "--json", echo=False)
        if code == 0 and self.json_object(out) is not None:
            self.write_snapshot(out)
            print(f"{self.task}: work/ticket-snapshot.md is now also work/ticket-snapshot.json, the "
                  "form the scout's brief reads (the old file stays)")
        else:
            why = (err.strip() or out.strip() or "no output")[:200].replace("\n", " ")
            print(f"{self.task}: work/ticket-snapshot.md could not be turned into work/ticket-snapshot.json "
                  f"(the ticket reader exited {code}: {why}); nothing was written and the scout's brief "
                  "will say the snapshot is not written yet")

    # -- the ticket moves while the story waits (B-364 = B-259, D-0027) -----------------------------------
    # ONE command with ONE trigger on both paths, the skill's and the driver's (phases/s0.md section 2b): when the
    # last comparison is older than the freshness window, or unknown, `ticket_adapter.py freshness` reads the ticket
    # now, compares it with the baseline and journals `ticket_changed` itself. The rule is the adapter's
    # (`TA.check_is_due`), never re-stated here; what the driver adds is WHERE it runs (a resumed story, and before
    # gate B is asked), how each answer of the adapter is branched (as the skill branches it), the one question the
    # person gets when the requirements moved, and what each of the three answers does. The branch's driver code
    # (commit 0275882) is the input; the 0.8.1 snapshot reader and the words-by-file doors are what it is built on.
    FRESHNESS_TIMEOUT_S = 300           # a tracker that never answers must not hold a resumed story without a word (R15)

    @staticmethod
    def ticket_field_words(names: list) -> str:
        """Field names -> the plain words a person reads, `a, b and c` (the adapter's own `FIELD_WORDS`). "" for no names
        (an unreadable file, an adapter that named none): the caller says its own fallback - this never raises, because
        a crash here with the question open would meet the person on every run and every answer (FR-40/42)."""
        import ticket_adapter as TA
        said = [TA.FIELD_WORDS.get(name, str(name).replace("_", " ")) for name in names or []]
        if len(said) < 2:
            return said[0] if said else ""
        return ", ".join(said[:-1]) + " and " + said[-1]

    def ticket_changed_text(self, changed: list, pasted: bool, first: str = "") -> str:
        """The body of the changed-ticket question, in the story's words: what changed, that the old text is kept and the new one
        set aside, then the three answers with what each costs and does (`fresh.ticket_changed` of question-prices.json; the
        priced section ends the text). No path, no command and no field name in the body (references/human-questions.md): the file
        of a pasted story goes in the answer block (`answer_note`). `first`: what a re-ask says before all of it (FR-7)."""
        what = self.ticket_field_words(changed) or "something in the requirements"
        lead = (f"The ticket text you gave me for {self.task} changed after the plan of this story was made."
                if pasted else f"The ticket {self.task} was edited in the tracker after the plan of this story was made.")
        return self.closed_question(
            "fresh.ticket_changed",
            f"{first}{lead} What changed: {what}.\n\n"
            "The factory kept the text the story was built on and set the new text aside, so nothing has been "
            "replaced yet. It cannot tell by itself which text the story should follow: the requirements, the "
            "test plan and the test cases were all written from the old one.\n\n"
            f"What should happen? {TICKET_CHANGED_OPTIONS}\n"
            "(S2 is the step where the requirements are written down from the ticket, S3 the test plan.)",
            [{"answer": "new text", "token": "new text", "slots": {"stages": "the requirements and the test plan (S2 and S3)"},
              "says": "re-run the requirements and the plan against the new text"},
             {"answer": "old text", "token": "old text",
              "says": "continue on the old text with that stated as a known gap; anything you write after the first line is kept "
                      "with your answer for gate B"},
             self.STOP_OPTION])

    def ticket_changed_person(self, changed: list, detail=None, revisions=None, lead: str = "") -> "Person":
        """The changed-ticket question as a `Person`: the details file carries what moved in the adapter's own
        words, and a pasted story names the person's own file in the answer block (FR-15: the path is given, in
        the one place a path is an instruction). `lead` is what a re-ask says first (FR-7: it comes back changed)."""
        ticket_file = self.s0_flags()["ticket_file"]
        return Person("ticket_changed", self.ticket_changed_text(changed, bool(ticket_file), lead), "S0",
                      details=json.dumps({"changed": changed, "detail": detail, "revisions": revisions},
                                         indent=2, ensure_ascii=False),
                      answer_note=(f"The ticket text you gave me is read from: {self.s0_rel_path(ticket_file)}"
                                   if ticket_file else ""))

    def ticket_changed_from_files(self, lead: str = "") -> "Person":
        """The question again, rebuilt from the two files on disk and never from the tracker: the baseline the story
        was built on against the new text that waits beside it. A file that cannot be read still gets the question
        (the person decides), with what moved left unnamed and the factory's own reason in the details."""
        import ticket_adapter as TA
        found = TA.find_baseline(self.task_root, self.task)
        _, waiting_path, _ = TA.snapshot_paths(self.task_root)
        waiting, why = TA.read_stored_snapshot(waiting_path, self.task)
        if found["ticket"] is None or waiting is None:
            return self.ticket_changed_person([], {"unreadable": found["problem"] or why}, None, lead)
        moved = TA.diff_objects(found["ticket"], waiting)
        return self.ticket_changed_person(
            moved["changed"], moved["detail"],
            {key: moved[key] for key in ("old_revision", "new_revision", "old_fetched_at", "new_fetched_at")}, lead)

    def ticket_unchecked(self, reason: str, now=None) -> str:
        """The look did not come (a tracker that does not answer, a protection service, a check that did not finish):
        ONE line, the story goes on with the text it was built on - an informed pass (FR-4), never a stop - and
        `ticket_unchecked` goes to the journal at most once per freshness window. An unknown is not a change (FR-41):
        its own event. The adapter stamped nothing, so the check stays due; only the journal line is throttled, and
        a throttle stamp from the future (a clock that was wrong) reads as unknown: the line is journaled."""
        import ticket_adapter as TA
        reason = " ".join(str(reason or "").split())[:300]
        print(f"ticket not checked: {reason}; the story goes on with the text it was built on")
        moment, last = now or datetime.now(timezone.utc), self.state.get("ticket_unchecked_at")
        if TA.baseline_is_stale(last, moment) or TA.stamp_is_ahead(last, moment):
            code, _ = self.py("log_append.py", "--event", "ticket_unchecked", "--task", self.task, "--notes", reason)
            if not code:                        # a journal that did not take the line is tried again at the next one
                self.state["ticket_unchecked_at"] = TA.now_iso(moment)
                self.save_state()
        return "unchecked"

    def ticket_look_failed(self, code: int, out: str, err: str, now=None) -> str:
        """A non-zero exit of `freshness`, branched as phases/s0.md section 2b branches it; "unchecked" or a raise.
        Exit 124 (the check did not finish, R15) is read as exit 3. Exit 5 whose error object names owner
        `intermediary` (B-408: a protection service answered, not the tracker, the token was NOT judged) is the exit-3
        class too and is read BEFORE the lost login below, from the object's field and never from a sentence;
        every other exit 5, or owner `auth`, stops the run with the door named. A fault of the factory is reported,
        never an informed pass."""
        import ticket_adapter as TA
        if code == 124:
            return self.ticket_unchecked(err or "the ticket check did not finish", now)
        failure = self.ticket_failure(code, out, err)
        said = " ".join((err.strip() or failure["message"] if failure["from_object"] else (out + "\n" + err)).split())
        if code == TA.EXIT_AUTH_LOST and failure["owner"] == "intermediary":
            return self.ticket_unchecked("a protection service in front of the tracker answered, not the tracker "
                                         f"({failure['message']})", now)
        if code == TA.EXIT_AUTH_LOST or failure["owner"] == "auth":
            raise self.ticket_auth_person(said)
        if code == TA.EXIT_USAGE or self.ticket_is_factory_fault(code, failure):
            raise self.ticket_factory_refusal(code, failure, said)
        if code == TA.EXIT_NOT_CONFIGURED or (code == TA.EXIT_NOT_FOUND and failure["owner"] == "tracker"):
            return self.ticket_unchecked(failure["message"] or said, now)
        if code == TA.EXIT_NOT_FOUND:           # another owner (the person's own file is gone, a setting): its refusal, said, not journaled
            print(f"ticket not checked: {failure['message'] or said}")
            return "unchecked"
        raise self.ticket_factory_refusal(code, dict(failure, owner="factory"), said)

    def ticket_freshness(self, now=None) -> str:
        """Look at the ticket when the story stood still, and say what the adapter found.

        Returns "skipped" (not due: no subprocess, no print), "baseline_written", "none", "context", "declined" or
        "unchecked", or raises: the changed-ticket `Person`, a lost login (the `ticket_auth` `Person`), a fault of the factory
        (`Refusal`). Only the adapter's `result` decides, never this driver's reading of a ticket:
          baseline_written - the story had none; one line.
          none             - silence (stamped; the baseline is not rewritten).
          context          - one line naming what changed; the baseline is replaced and the story goes on.
          requirements     - the person's question; the baseline is kept, the new text waits beside it. A text the
                             person already declined (`already_answered`) is one line, never asked again (FR-7).
        On a story launched with `--ticket-file` the same file is passed: the adapter re-reads that file alone."""
        import ticket_adapter as TA
        if not TA.check_is_due(self.task_root, now):
            return "skipped"
        ticket_file = self.s0_flags()["ticket_file"]
        code, out, err = self.py_stdout("ticket_adapter.py", "freshness", self.task, "--task-root", str(self.task_root),
                                        "--json", *(["--ticket-file", ticket_file] if ticket_file else []),
                                        echo=False, timeout=self.FRESHNESS_TIMEOUT_S)
        if code:
            return self.ticket_look_failed(code, out, err, now)
        if err.strip():
            print(err.strip())                  # what the adapter said beside its result (an unreadable record, a stale file)
        result = self.json_object(out) or {}
        kind, changed = result.get("result"), result.get("changed") or []
        if kind == "baseline_written":
            print("ticket snapshot: the story had none to compare with; the ticket as it stands is now the baseline")
        elif kind == "context":
            print(f"ticket {self.task} changed while the story waited ({self.ticket_field_words(changed) or 'something'}); "
                  "the story goes on")
        elif kind == "requirements" and result.get("already_answered"):
            print(f"ticket {self.task}: the new text ({self.ticket_field_words(changed) or 'the requirements'}) is the one declined on "
                  f"{str(result.get('declined_at') or '')[:10] or 'an earlier date'}; the story goes on with the old text")
            return "declined"
        elif kind == "requirements":
            raise self.ticket_changed_person(changed, result.get("detail"), result.get("revisions"))
        elif kind != "none":
            said = (f"it answered result {kind!r}, which the driver does not know" if result
                    else "it exited 0 but printed no JSON object")
            raise self.ticket_factory_refusal(0, {"owner": "factory", "message": said, "file": None, "from_object": False}, out)
        return kind

    def ticket_freshness_entry(self) -> str:
        """The doors in front of `ticket_freshness`, in the order that keeps each invariant; the word is why it did not run.
        Another question open: never stacked (an open `ticket_changed` is the exception: it is asked again from the
        files, with no tracker read). The run that carries the changed-ticket answer: no second look - the person
        has just chosen. No `state/controller.json`: silent, the loop's own `initialize` repairs first and
        `source_revision` is the hash of the S0 snapshot - a rewrite before it would make `initialize` hash the new
        text. The person's word that the ticket is not needed (`launch.ticket_not_needed`, written by S0 before its
        answers were popped): one line, no look. A closed story: one line, no look (the controller's one reading)."""
        import controller as C
        import ticket_adapter as TA
        asked = str((self.state.get("asked") or {}).get("kind") or "")
        if self.answer_kind == "ticket_changed" or (asked and asked not in ("ticket_changed", "ticket_auth")):
            return "held"
        if not (self.state_dir / "controller.json").is_file():
            return "no_controller"
        if (self.state.get("launch") or {}).get("ticket_not_needed"):
            print(f"{self.task}: you said the ticket is not needed, so it is not looked at again")
            return "not_needed"
        import hooklib
        if hooklib.story_closure(C.closure_view(self.controller_state(), self.pipeline()))["state"] != "open":      # executing too: gate B is decided (GB-1b)
            print(f"{self.task}: this story is closed, so its ticket is not looked at again")
            return "closed"
        passed = (self.state.get("s0_answers") or {}).get("fresh.ticket_auth")
        if passed == "go on":
            # G3 (FR-7, FR-4): the person said to go on without the look. It holds for the freshness window - measured from the
            # `ticket_unchecked` stamp their word left - and is asked again only when the window has run out or the stamp is not
            # readable as a past time (an unknown is not a fresh one, FR-41).
            moment, last = datetime.now(timezone.utc), self.state.get("ticket_unchecked_at")
            if not TA.baseline_is_stale(last, moment) and not TA.stamp_is_ahead(last, moment):
                print(f"{self.task}: you said to go on without looking at the ticket, so it is not looked at again until the check "
                      "is due again")
                return "unchecked"
            self.state["s0_answers"].pop("fresh.ticket_auth", None)
            self.save_state()
        if asked == "ticket_auth":
            # Open and unanswered by a plain rerun: the check runs again - a token that works clears the question, one that does not
            # raises it again from `ticket_look_failed`; never a silent pass (G3).
            self.state["asked"] = {}
            self.save_state()
            print(f"{self.task}: the tracker login is checked again; {self.reconcile_question()}")
        if asked == "ticket_changed":
            if TA.snapshot_paths(self.task_root)[1].is_file():
                raise self.ticket_changed_from_files()
            # The new text no longer waits (an adopt or a newer check settled it): nobody can answer about it. The flag
            # is cleared the way `reconcile_question` clears one, and the ticket is looked at as usual.
            self.state["asked"] = {}
            self.save_state()
            print(f"{self.task}: the new ticket text no longer waits; {self.reconcile_question()}")
        return self.ticket_freshness()

    def ticket_record_words(self, stage: str, how: str, words: str, what: str = "ticket changed") -> None:
        """The person's answer to the changed-ticket question (`what`: or to the lost-login one) on the journal's record, WHOLE
        (FR-8): every later brief reads a `human_answer` note as their standing instruction. `how` says which road it took."""
        self.answer_row(f"{stage} {what} ({how}): ", words.strip(), what="your answer about the ticket")

    def ticket_ask_again(self, words: str, qtext: str, stage: str, lead: str, *, unread: bool = False) -> None:
        """The answer could not be carried out, or was not one of the three: the words are recorded FIRST (FR-8: the
        journal's `human_answer` and `driver-answers.jsonl`, whole), then the question comes back changed (FR-7) -
        `lead` says what the answer did not settle - rebuilt from the files, never from the tracker. `unread`: the words are
        not a token, so the seam reads them first (D-0041; its doors are the three tokens, its fallback this same question). A
        conductor `continue` / `retry` brings the question back too - never `--adopt`: an unread answer adopts nothing (G1)."""
        self.ticket_record_words(stage, "asked again", words)
        _append_jsonl(self.state_dir / "driver-answers.jsonl",
                      {"ts": _now(), "kind": "ticket_changed", "stage": stage, "dispatch": "",
                       "question_sha": question_body_sha(qtext), "words": words})
        if unread:
            self.unread("ticket_changed", stage, "", qtext, words=words, doors=TICKET_CHANGED_TOKENS, lead=lead.strip(),
                        again=lambda said: self.ticket_changed_from_files(said + "\n\n"))
        raise self.ticket_changed_from_files(lead)

    def take_ticket_auth_answer(self, words: str, qtext: str, stage: str, dispatch: str) -> None:
        """The answer to the `ticket_auth` question of the freshness check (FR-9: each token has an executor): `retry` - the words
        are recorded and the check runs again in this process (a token that still fails raises the question again); `go on` - the
        words are recorded, `ticket_unchecked` says the look was skipped (the informed pass, FR-4) and the word is kept as
        `s0_answers["fresh.ticket_auth"]`, honoured by `ticket_freshness_entry` for the freshness window (FR-7: a later process within
        it does not ask again); `stop` - the question is held (exit 3). Anything else is new words the code cannot read: the seam
        (D-0041) with `retry` / `go on` as its doors; a conductor `continue` / `retry` leaves the check to run again, which decides."""
        token = self.s0_normalize(words)
        self.ticket_record_words(stage, token if token in ("retry", "go on", "stop") else "unread", words, "ticket login lost")
        if token == "stop":
            raise self.held_question(self.stop_held("If you want the factory to go on after all, answer `retry` or `go on`."))
        if token == "go on":
            self.ticket_unchecked("the tracker login is lost and the person said to go on without the look")
            self.state.setdefault("s0_answers", {})["fresh.ticket_auth"] = "go on"
            self.save_state()
        elif token == "retry":
            print(f"{stage}: nothing is passed; the ticket is looked at again")
        else:
            lead = self.unread_lead(words)
            self.unread("ticket_auth", stage, "", qtext, words=words, doors=("retry", "go on"), lead=lead,
                        again=lambda said: self.held_question(said))

    def take_ticket_answer(self, words: str, qtext: str, stage: str, dispatch: str) -> None:
        """The answer to the changed-ticket question: the FIRST non-empty line is a token (`s0_normalize`: BOM,
        quotes, a full stop, case and spaces only), and each of the three has an executor (FR-9):
          old text - `freshness --decline` with the WHOLE answer as the words (kept as a remark of S0, shown at gate B);
          new text - `freshness --adopt`, the words recorded, then S2 and S3 owed again (`ticket_rework_step`, R12);
          stop     - the words recorded, nothing runs, the question comes back.
        Any other answer is recorded and asked again, quoted (FR-7). The adapter's refusals: exit 2 (nothing waits any
        more) is printed and the story goes on; any other non-zero exit asks again, saying that the choice could not be
        carried out. Nothing here reads what the person MEANT (FR-12); `dispatch` is unused (the question names none)."""
        first = next((line for line in str(words).splitlines() if line.strip()), "")
        token = self.s0_normalize(first)
        if token not in TICKET_CHANGED_TOKENS:
            self.ticket_ask_again(words, qtext, stage, self.unread_lead(words) + "\n\n", unread=True)
        if token == "stop":
            self.ticket_ask_again(words, qtext, stage, self.stop_held("Answer `new text` or `old text` when you decide.") + "\n\n")
        import ticket_adapter as TA
        flags = ["--decline", *self.words_args(words, "ticketdecline")] if token == "old text" else ["--adopt"]
        code, out, err = self.py_stdout("ticket_adapter.py", "freshness", self.task, "--task-root", str(self.task_root),
                                        *flags, "--json", echo=False, timeout=self.FRESHNESS_TIMEOUT_S)
        failure = self.ticket_failure(code, out, err) if code else {}
        said = " ".join((err.strip() or failure.get("message") or f"the adapter exited {code}").split()).removeprefix(
            "ticket_adapter: ")[:300]
        if code == TA.EXIT_USAGE:
            # Nothing waits any more (the text was settled by a later look) or the adapter refused its arguments: the
            # words are on the record all the same (FR-8), the story goes on, and the next look decides what is owed.
            print(f"{self.task}: {said}")
            self.ticket_record_words(stage, f"{token}, nothing waited", words)
            return
        if code:
            self.ticket_ask_again(words, qtext, stage, f"Your choice could not be carried out: {said}\n\n")
        if token == "old text":
            print(f"{self.task}: the story goes on with the old ticket text; your words are kept for gate B and the "
                  "new text is not asked about again")
            return
        self.ticket_record_words(stage, "new text", words)
        state = self.controller_state()
        owed = [s for s in ("S2", "S3") if (((state.get("stages") or {}).get(s) or {}).get("status")) == "completed"]
        if not owed:
            print(f"{self.task}: the new ticket text is adopted; the requirements and the plan are not finished yet, "
                  "so they are made from it when they run")
            return
        self.state["ticket_rework"] = {"stages": owed, "words": words, "at": _now(),
                                       "before": sorted(self.rework_dispatches(state.get("dispatches") or {}, "ticket_changed", by_person=False))}
        self.save_state()
        print(f"{self.task}: the new ticket text is adopted; the requirements and the plan are made again from it")

    def ticket_rework_step(self) -> bool:
        """One move of the ticket rework the person chose (`state["ticket_rework"]`), or False when none is owed.

        S2 and S3 go back over their accepted work with cause `ticket_changed` and `complete=True` (the plan baseline
        is re-captured, so the re-run's changes are never later counted as the person's overrides), ONE stage at a time:
        the controller refuses a second running dispatch, so S3 is registered only after S2's was accepted. A stage with
        no accepted work gets no rework and one line. The rework is found by the cause on the stage's dispatch that is
        NOT in `before` (the ones a former answer made), so a second ticket change is owed its own rework. It acts
        only when the controller holds no running dispatch; a dispatch of its own that is not accepted is the loop's to
        resolve (`where`); one that was set aside (released, superseded, stale: the controller's `DISCOUNTED`) ends the
        re-runs with one line and the gate A move still follows.
        When the list is empty gate A is asked again (`ticket_reopen_gate_a`). True: this turn moved something, ask
        `where` on the next one - nothing `where` could say may come before what is owed."""
        owed = self.owed_rework("ticket_rework")
        if owed is None:
            return False
        pending, dispatches = owed
        import controller as C
        set_aside = C.DISCOUNTED - {C.NEVER_STARTED}
        stages = list(pending.get("stages") or [])
        while stages:
            stage = stages[0]
            mine = [d for did, d in self.rework_dispatches(dispatches, "ticket_changed", by_person=False, stage=stage).items()
                    if did not in (pending.get("before") or [])]
            status = mine[-1].get("status") if mine else None
            if status == "accepted":
                stages.pop(0)
                pending["stages"] = stages
                self.save_state()
                continue
            if mine and status in set_aside:
                # The controller's own vocabulary (`DISCOUNTED` less `never_started`, which `where` relaunches), never a
                # literal: a person's release (`released_by_person`), a retry that took its place (`superseded`, written by
                # code) or an invalidation (`stale`). The re-run will not happen, so the rest of the list is dropped, but the
                # person's choice of the new text stands: gate A is still asked again (below), never left on the old text.
                print(f"{self.task}: the re-run of {stage} was set aside before it was accepted (a person's word, a retry that "
                      "took its place, or an invalidation); nothing more is made again, and gate A is still asked again")
                stages = []
                pending["stages"] = stages
                self.save_state()
                break
            if mine:
                return False
            roles = [d.get("role") for d in dispatches.values() if d.get("stage") == stage and d.get("status") == "accepted"
                     and (stage != "S3" or d.get("role") == "qa-test-strategist")    # a first look accepted after the strategist is not the author
                     # B2 (critic t-2548): the S1 twin - the reference window's runner, accepted after the scout, is not the author either; the
                     # scout is reworked and `rework` re-enters the window. A story with no reference has only the scout here: as before
                     and (stage != "S1" or d.get("role") == (self.stages().get("S1", {}).get("roles") or [""])[0])]
            if roles and stage == "S3":
                # G1-11: ONE paid dispatch labels and plans (a rework of S3 is never two); the table is prepared first
                # (a pre-node S3 with no table gets it built), and the dispatch closes through the one S3 completion.
                self.s3_prepare()
                self.rework(stage, str(roles[-1]), [], str(pending.get("words") or ""), cause="ticket_changed",
                            complete=self.s3_ticket_completion(),
                            extra=self.s3_strategist_lines({"repair_cause": "ticket_changed"}))
                return True
            if roles:
                self.rework(stage, str(roles[-1]), [], str(pending.get("words") or ""), cause="ticket_changed", complete=True)
                return True
            print(f"{self.task}: {stage} has no accepted work to make again; skipped")
            stages.pop(0)
            pending["stages"] = stages
            self.save_state()
        self.ticket_reopen_gate_a(pending)
        self.drop_record("ticket_rework")
        return True

    def seam_rework_step(self) -> bool:
        """One move of the rework the person CHOSE at the seam (`state["seam_rework"]`, written by `record_seam_rework`; t-722 §4.2
        p.7), or False when none is owed. Run at the start of each turn of the loop after `ticket_rework_step`, before `where`: nothing
        `where` could say goes ahead of what the person chose. INVARIANT (P22): the record lives until the controller has REGISTERED
        the rework and is dropped only after; a crash anywhere neither loses the choice nor registers it twice. Order: no record or
        no controller state -> False; a dispatch running -> False (`where` leads it); the record's OWN dispatch (stage and cause
        match, id not in `before`) already registered -> the record goes, False; a dry run says so ONCE, touches nothing, False; the
        person's words (`original_words`) gone -> the record goes and the seam hears it; else `rework` with the words by file,
        `complete=False` (the stage opens again: on S5 the window's reviewer is dispatched again) and `purpose` by default
        (`repair_verify`, as `ticket_rework_step`); a refusal to register drops the record and goes to the conductor."""
        owed = self.owed_rework("seam_rework")
        if owed is None:
            return False
        pending, dispatches = owed
        stage, role, cause = (str(pending.get(key) or "") for key in ("stage", "role", "cause"))
        if any(did not in (pending.get("before") or [])           # the record's OWN dispatch: the person's origin, never a `ticket_changed` one
               for did in self.rework_dispatches(dispatches, cause, by_person=True, stage=stage)):
            self.drop_record("seam_rework")
            return False
        if self.dry:
            print("dry run: the rework the person chose is not started")
            return False             # nothing moved: a True here would spin the loop `max_boundaries` times over the same line
        rel = str(pending.get("words_file") or "")
        given = self.original_words({"words_file": rel})
        if not given or not given[1].strip():
            self.drop_record("seam_rework")
            self.seam_rework_refused(stage, f"the words file of the person's rework is gone: {self.task_root / rel}", "", "", [])
            return True
        preface = [str(line) for line in pending.get("preface") or [] if str(line).strip()]
        reason = "\n".join(preface + [given[1]]) if preface else given[1]       # the code's preface, then the person's words VERBATIM
        try:
            self.rework(stage, role, list(pending.get("cases") or []), reason, cause=cause, rows=list(pending.get("rows") or []),
                        words_file=rel, complete=self.s3_rework_completion() if (stage, role) == ("S3", "qa-test-strategist") else False)
        except ReworkRefused as exc:
            self.drop_record("seam_rework")                     # nothing was registered and nothing will be (§4.2 p.7 step 7)
            self.seam_rework_refused(stage, exc.text, given[1], rel, self.refusal_lines(exc))
            return True
        self.drop_record("seam_rework")
        return True

    def answer_rework_step(self) -> bool:
        """One move of the rework the person's recorded answers owe (`state["answer_rework"]`, written by `apply_question_answers`), or False
        when none is owed. Run each turn of the loop after `seam_rework_step`, before `code_close_step` and `where`. The rework is opened by CODE:
        `Driver.rework(cause="question_answer")` - the conductor is not called (FR-48). INVARIANT (P22, as the seam's): an item lives until the
        controller has REGISTERED its rework and goes only after, so a crash neither loses it nor registers it twice. Order of the checks:
        no record / no controller state / a dispatch running -> False (`where` leads it); the item's OWN dispatch (this stage, cause
        `question_answer`, id not in its `before`) already registered -> the item goes, False (H42 b, d); a dry run says so ONCE and moves
        nothing; the work is already done (H41: the plan and the cases of the item follow its answers - the same reader as the gate A
        rehearsal) -> the item goes with one line, no paid repeat (FR-55); else `rework` with `complete=None` (N1: the stage's own rule
        closes it; S3 closes by its projection, `s3_window_completion`), the person's words by file, or the driver's own reason when
        there are none or the file is gone (C16, H42 g); a refusal of the controller drops the item and goes to the conductor WITH the
        words (H42 c). The strategist's item (S3) is first: the plan before the cases (H40)."""
        owed = self.owed_rework("answer_rework")
        if owed is None:
            return False
        pending, dispatches = owed
        items = [i for i in pending.get("items") or [] if isinstance(i, dict) and i.get("stage") and i.get("role")]
        if not items:
            self.drop_record("answer_rework")
            return False
        item = items[0]
        stage, role = str(item["stage"]), str(item["role"])
        if self.answer_rework_registered(item, dispatches):
            self.finish_answer_item(item)
            return False
        if self.dry:
            print("dry run: the rework your recorded answers owe is not started")
            return False             # nothing moved: a True here would spin the loop `max_boundaries` times over the same line
        owed_item = self.answer_item_still_owed(item)
        if owed_item is None:
            ids = ", ".join(str(a.get("id")) for a in item.get("questions") or [])
            print(f"{stage}: the {self.role_words(role)} already made the {'plan' if stage == 'S3' else 'cases'} follow your answer to "
                  f"{ids}; no further rework is started")
            self.finish_answer_item(item)
            return False
        rel = str(owed_item.get("words_file") or "")
        given = self.original_words({"words_file": rel})
        words = given[1] if given is not None and given[1].strip() else ""
        rel = rel if words else ""
        reason = words or ("The person answered " + ", ".join(str(a.get("id")) for a in owed_item["questions"])
                           + " after your work was written; make the " + ("rows" if stage == "S3" else "cases")
                           + " named in this rework follow the answers.")
        extra = self.answer_rework_lines(owed_item) + (self.s3_strategist_lines({"repair_cause": "question_answer"}) if stage == "S3" else [])
        complete = self.s3_window_completion({"repair_cause": "question_answer"}) if stage == "S3" else None
        try:
            self.rework(stage, role, list(owed_item.get("cases") or []), reason, cause="question_answer",
                        rows=list(owed_item.get("rows") or []), words_file=rel, extra=extra, complete=complete)
        except ReworkRefused as exc:
            self.finish_answer_item(item)                       # nothing was registered and nothing will be
            self.seam_rework_refused(stage, exc.text, words, rel, self.refusal_lines(exc))
            return True
        self.finish_answer_item(item)
        return True

    def finish_answer_item(self, item: dict) -> None:
        """The item `answer_rework_step` is done with goes out of `state["answer_rework"]`; the record goes with the last item."""
        record = self.state.get("answer_rework")
        left = [i for i in (record.get("items") if isinstance(record, dict) else None) or [] if i is not item]
        if left:
            self.state["answer_rework"] = {"items": left}
            self.save_state()
        else:
            self.drop_record("answer_rework")

    def answer_item_still_owed(self, item: dict):
        """H41: the part of `item` the plan and the cases still do NOT follow, or None when nothing is left (the role already did it, e.g.
        it was resumed with the answers) - `answer_pairs_owed` over the branch check as it reads NOW. When the check cannot be read the item
        is returned as it is: an unknown never drops owed work (FR-59)."""
        return self.answer_pairs_owed(item, self.question_branch_findings())

    @staticmethod
    def answer_pairs_owed(item: dict, findings):
        """HF3-10 (H41, M1): the part of `item` still owed, given `findings` (`question_branch_findings`: [finding] or None). The item's
        `pairs` are (question, row or case) as the check saw them when the rework was named (`seen`). A pair is owed unless it was SEEN
        (`seen is True` - anything else, a missing field included, is unseen) and the check no longer names it: the check's silence about
        a row it never saw branching on the question is not proof that the row follows the answer (the code patched the branch off for the
        first answer). A row or case is kept while ANY of its pairs is owed, or when it has no pair at all (an item of an older state);
        a question is kept while it has an OWED pair at a row or case that stays (a pair of it that is done is not told to the role), or no
        pair at all; if rows or cases stay and no question does, all the questions stay. Nothing left -> None; `findings` None -> the item as it is. ERROR DIRECTION: an extra rework, never
        a dropped one - the only input that drops work is a seen pair the check no longer names. Pure."""
        if findings is None:
            return item
        named = {(f.get("question"), f.get("where")) for f in findings if isinstance(f, dict)}
        pairs = [p for p in item.get("pairs") or [] if isinstance(p, dict)]

        def owed(pair: dict) -> bool:
            return pair.get("seen") is not True or (pair.get("question"), pair.get("where")) in named

        def stays(where) -> bool:
            theirs = [p for p in pairs if p.get("where") == where]
            return not theirs or any(owed(p) for p in theirs)
        rows = [r for r in item.get("rows") or [] if stays(r)]
        cases = [c for c in item.get("cases") or [] if stays(c)]
        if not rows and not cases:
            return None
        asked = [a for a in item.get("questions") or [] if isinstance(a, dict)]
        questions = [a for a in asked
                     if not any(p.get("question") == a.get("id") for p in pairs)
                     or any(p.get("question") == a.get("id") and p.get("where") in rows + cases and owed(p) for p in pairs)]
        return dict(item, rows=rows, cases=cases, questions=questions or asked)

    def answer_rework_lines(self, item: dict) -> list:
        """What the owner is told, one line per answer (the role reads them before the work): which question, what the person answered
        and when, and that the rows or cases named in the rework do not follow it yet. An answer in the person's own words is said so
        (no letter); an id the register no longer holds is told without the time. An answer that CHANGED (`was`, HF3-10) also says what
        it was before: the rows or cases still follow that one (FR-38: the role knows what to move away from)."""
        import planning_contract as PC
        import question_register as QR
        try:
            where_of = {q["id"]: q.get("where") for q in QR.load(self.task_root)["questions"]}
        except Exception:
            where_of = {}
        out = []
        for asked in item.get("questions") or []:
            answer = str(asked.get("answer") or "")
            said = ("answered in the person's own words" if not answer else "marked as not needed" if answer == "not_needed"
                    else f"answered `{answer}`")
            when = f" {QR.where_words(where_of.get(asked.get('id')))}" if asked.get("id") in where_of else ""
            parts = "rows" if item.get("stage") == "S3" else "cases"
            if isinstance(asked.get("was"), str):               # `was` "" is the person's own words: a changed answer all the same
                was_words = PC._answer_words(asked["was"])
                out.append(f"{asked.get('id')} is {said}{when}; it was {was_words} before, and the {parts} named in this rework "
                           "still follow that - make them follow the new answer")
                continue
            out.append(f"{asked.get('id')} is {said}{when}; the {parts} named in this rework do not follow it yet - make them follow it")
        return out

    def owed_rework(self, key: str):
        """The start both rework steps share (`ticket_rework_step`, `seam_rework_step`): `(record, the controller's dispatches)` when the
        record `state[key]` may be acted on now, else None - no record, no controller state, or a dispatch running (`where` leads it)."""
        pending = self.state.get(key)
        if not isinstance(pending, dict) or not (self.state_dir / "controller.json").is_file():
            return None
        dispatches = self.controller_state().get("dispatches") or {}
        if any(d.get("status") == "running" for d in dispatches.values()):
            return None
        return pending, dispatches

    @staticmethod
    def rework_dispatches(dispatches: dict, cause: str, *, by_person: bool, stage: str = "") -> dict:
        """`{id: dispatch}` of the reworks of `cause` (on `stage`, when given) of ONE ORIGIN: `by_person` - the person's words reached the
        controller by file (the record's `person_words`, `build_rework_request`), else the driver's own reason (`ticket_rework_step`).
        A rework of the other origin is never counted, so a `ticket_changed` rework is never taken for the person's and the other way."""
        return {did: d for did, d in dispatches.items()
                if isinstance(d, dict) and d.get("repair_cause") == cause and (not stage or d.get("stage") == stage)
                and (d.get("person_words") is True) == by_person}

    def drop_record(self, key: str) -> None:
        """Drop the record `state[key]` and save: the step that owed it is done with it (or can never do it)."""
        self.state.pop(key, None)
        self.save_state()

    def seam_rework_refused(self, stage: str, text: str, words: str, rel: str, lines: list) -> None:
        """The controller refused the rework the person chose (or its words are gone): the refusal goes to the conductor WITH the
        person's words and the closed list of what `args` may name, so it can offer another `rework` or ask (t-722 §4.2 p.8)."""
        facts = self.no_move_facts({"stage": stage})
        self.no_move({"why": "refusal", "kind": "conductor", "stage": stage, "dispatch": "",
                      "text": text + "\n\n" + NM.rework_args_list(facts), "words": words, "words_file": rel, "lines": lines})

    def ticket_reopen_gate_a(self, pending: dict) -> None:
        """After S2 and S3 were made again from the new text: a gate A decision given on the old requirements does not
        survive the person's choice (R17, F9 a). `semantic_reopen` stales it and returns S4 to pending - nothing more
        of the work is lowered (a completed stage is never lowered by later work, `controller.set_stage`) - so the accepted
        dispatches of S5-S8 on the story's scope are invalidated too (whatever the stage's status), the controller's own
        move for it, and the stages are redone on the new plan: no test or report built on the old requirements survives.
        A completed stage code cannot set aside (no dispatch of the scope names it) is NAMED in a line and at gate A's top.
        Each step is recorded in `ticket_rework` as it lands, so a restart goes on where it stopped. No approved gate A,
        or no scope: one line, no reopen. `expected_revision` is the controller's `revision`, read right before each call.
        What the driver does when the S4 re-run meets 'cumulative packet budget reached' (the S4 designer's budget is
        story-wide): nothing of its own - the refusal takes the existing road (the conductor, then the person)."""
        state = self.controller_state()
        revision = state.get("source_revision")
        approved = any(d.get("gate") == "A" and d.get("status") == "approved" and d.get("source_revision") == revision
                       for d in (state.get("decisions") or {}).values())
        scope = list(state.get("scope") or [])
        if not pending.get("reopened") and not (approved and scope):   # once reopened the decision is stale: that is no absence
            print(f"{self.task}: no approved gate A to ask again; the story goes on from the new text")
            return
        reason, key = "the person chose the changed ticket text: " + str(pending.get("words") or "")[:1500], pending.get("at")
        if not pending.get("reopened"):
            self.controller("semantic_reopen", input_data={"reason": reason, "affected_scope": scope,
                                                           "idempotency_key": f"semantic_reopen:ticket:{key}",
                                                           "expected_revision": state.get("revision", 0)})
            pending["reopened"] = True
            self.save_state()
        # The accepted work of S5-S8 on the story's scope is set aside WHATEVER the stage's status: a half-done S5 (pending,
        # with accepted windows) keeps windows built on the old plan as surely as a completed one. A dispatch already `stale`
        # still counts as covering its stage, so a restart after the invalidate names the same stages.
        late_stages = ("S5", "S6", "S7", "S8")
        mine = {did: d for did, d in (state.get("dispatches") or {}).items()
                if d.get("stage") in late_stages and d.get("status") in ("accepted", "stale") and set(d.get("scope") or []) & set(scope)}
        stale = [did for did, d in mine.items() if d.get("status") == "accepted"]
        if stale and not pending.get("invalidated"):
            self.controller("invalidate", input_data={"reason": reason, "affected_scope": scope, "dispatch_ids": stale,
                                                      "decision_ids": [], "idempotency_key": f"invalidate:ticket:{key}",
                                                      "expected_revision": self.controller_state().get("revision", 0)})
        pending["invalidated"] = True
        self.save_state()
        # A completed stage with no such dispatch (a stage closed by code, or one whose dispatches carry no scope) cannot be
        # set aside by code: it is NAMED, in the line and at the top of gate A, never left silent (FR-41).
        covered = {d.get("stage") for d in mine.values()}
        names = self.stages()
        left = [f"{str((names.get(s) or {}).get('name') or s).lower()} ({s})" for s in late_stages
                if (((state.get("stages") or {}).get(s) or {}).get("status")) == "completed" and s not in covered]
        note = "Gate A is asked again: you chose the new ticket text, and the requirements and the plan were made again from it."
        if left:
            kept = f"what {', '.join(left)} hold was made from the old text, and nothing here could set it aside"
            print(f"{self.task}: {kept}")
            note += f" Note that {kept}."
        self.state.setdefault("gate_note", {})["A"] = note
        print(f"{self.task}: gate A is asked again on the requirements and the plan made from the new text")

    # -- the doors of S0 ---------------------------------------------------------------------
    # Built from code points, so that the source stays plain ASCII (a literal BOM or curly quote
    # in a source file is invisible in review): the pairs a person's editor puts round a word.
    _PEEL = (("`", "`"), ('"', '"'), ("'", "'"), (chr(0x201C), chr(0x201D)), (chr(0x2018), chr(0x2019)))
    BOM = chr(0xFEFF)

    @classmethod
    def s0_normalize(cls, words: str) -> str:
        """The answer, reduced to what it would be if the person had typed exactly a token:
        BOM out, the quotes or backticks they wrapped it in off, ONE closing `.` or `!` off,
        lower case, runs of white space one space. It decides nothing about meaning (FR-12) -
        it only makes a BOM, a pair of quotes and a full stop around `Go on` the same characters
        as `go on`."""
        def peel(text: str) -> str:
            again = True
            while again and len(text) >= 2:
                again = False
                for opening, closing in cls._PEEL:
                    if text[0] == opening and text[-1] == closing:
                        text, again = text[1:-1].strip(), True
                        break
            return text
        text = peel(str(words or "").replace(cls.BOM, "").strip())
        if text[-1:] in (".", "!"):
            text = text[:-1].strip()
        # a curly apostrophe INSIDE a word (`another team’s`: the default of a phone or Word keyboard) is the ASCII one, after the
        # pairs are peeled (code points, as `_PEEL`)
        return " ".join(peel(text).replace(chr(0x2019), "'").replace(chr(0x2018), "'").split()).lower()

    def s0_quote(self, words: str) -> str:
        """The person's words as one line, at most QUOTE_LIMIT characters; a cut shows as an ellipsis."""
        one = " ".join(str(words or "").split())
        return one if len(one) <= self.QUOTE_LIMIT else one[:self.QUOTE_LIMIT] + self.CUT

    def unread_lead(self, words: str) -> str:
        """THE sentence that says an answer was not read (F-6): the lead of every closed question that comes back after words it
        does not take (S0, `package`, `ticket_changed`, `ticket_auth`). The words are quoted, cut like any quote (`s0_quote`)."""
        return f'Your answer "{self.s0_quote(words)}" is not one of the answers this question takes, so nothing has moved yet.'

    def s0_note_launch(self) -> None:
        """First entry into s0: what the command line said is kept, so that a later entry - the
        one that follows an answer, run with no flags - starts from the same launch."""
        if "launch" in self.state:
            return
        ns = self.flags
        given = {"mr": getattr(ns, "mr", None), "branch": getattr(ns, "branch", None),
                 "commit": getattr(ns, "commit", None), "ticket_file": getattr(ns, "ticket_file", None),
                 "env": getattr(ns, "env", None), "ungrounded": bool(getattr(ns, "ungrounded", False)),
                 # t-2181 PC-2: `--side <name>=<reality>` and `--reference <side>=<stand>` (pairs, repeated), kept as {name: word}
                 "side": dict(getattr(ns, "side", None) or ()), "reference": dict(getattr(ns, "reference", None) or ())}
        self.state["launch"] = {key: value for key, value in given.items() if value}
        self.save_state()

    def s0_keep_late_launch(self) -> None:
        """A launch word on a LATER entry is kept in `launch` too (t-586 F-1): `s0_note_launch` writes once, so the `--mr` of the
        restart the no-change question prints (the `change` door) was lost, and a later process with no flags told the scout
        `Launch flags: none` and asked the same question again (FR-7). The person's answers (`keep`, `mr_dropped`) are applied
        by `s0_flags` AFTER this, so a kept word is never undone here."""
        ns, launch = self.flags, self.state.setdefault("launch", {})
        changed = False
        for key in ("mr", "branch", "commit"):
            value = getattr(ns, key, None)
            if value and launch.get(key) != value:
                launch[key] = value
                changed = True
        if getattr(ns, "ungrounded", False) and not launch.get("ungrounded"):
            launch["ungrounded"] = True
            changed = True
        # t-2181 PC-2: a side or a reference word on a LATER entry (the relaunch that tells the factory a side is real now) is
        # kept as the restart's own word, name by name: a later word for a name replaces the earlier one, the other names stay.
        for key in ("side", "reference"):
            given = dict(getattr(ns, key, None) or ())
            if given and any((launch.get(key) or {}).get(name) != word for name, word in given.items()):
                launch[key] = {**(launch.get(key) or {}), **given}
                changed = True
        if changed:
            self.save_state()

    def launch_flags(self) -> dict:
        """The launch flags, this command line first, else what S0 kept in `launch` (`s0_note_launch`): a PURE reader - nothing is
        written, no answer is applied. The one place the two sources are joined: `s0_flags` builds on it, and the scout's
        "Launch flags" line (`role_lines`) reads it, so an `--answer` process names the kept `--mr` (F8)."""
        ns, kept = self.flags, self.state.get("launch") or {}
        flags = {key: getattr(ns, key, None) or kept.get(key) or None
                 for key in ("mr", "branch", "commit", "ticket_file", "env")}
        flags["ungrounded"] = bool(getattr(ns, "ungrounded", False) or kept.get("ungrounded"))
        # SS1-13: the person's answer to the no-change question (`s0_read_word`); no command-line flag carries it, only `launch`.
        flags["implementation_source"] = kept.get("implementation_source") or None
        # t-2181 PC-2: the sides the person named at launch (this command line over what was kept, name by name) and the answer
        # `not built yet` (`s0_read_word`); never None, so a reader asks `if flags["side"]`.
        for key in ("side", "reference"):
            flags[key] = {**(kept.get(key) or {}), **dict(getattr(ns, key, None) or ())}
        flags["not_built_yet"] = bool(kept.get("not_built_yet"))
        # `--side product=absent` IS the person's `not built yet` in flag form (F1): no change is read, so the scout does not halt on
        # the missing diff and the no-change question is not asked (FR-7). With a change named it is only a record of the side.
        import contract   # late, as the other uses in this file
        if (flags["side"].get("product") == contract.PARKING_REALITY
                and not (flags["mr"] or flags["branch"] or flags["commit"])):
            flags["ungrounded"] = True
        return flags

    def s0_flags(self) -> dict:
        """The launch flags as they stand: this command line first, else what was kept; then what
        the person has answered on top (their word is later than the flag it corrects)."""
        ns, kept = self.flags, self.state.get("launch") or {}
        flags = self.launch_flags()
        flags["skip_sources"] = getattr(ns, "skip_sources", None) or kept.get("skip_sources") or None
        answers = self.state.get("s0_answers") or {}
        if answers.get("keep"):
            for key in ("mr", "branch", "commit"):
                if key != answers["keep"]:
                    flags[key] = None
        if answers.get("mr") == "skip":
            flags["mr"] = None        # the person chose the list's word over the flag's (`source_list` question)
        for key in ("env", "ticket_file"):
            if not answers.get(key):
                continue
            cli = getattr(ns, "ticket_file", None) if key == "ticket_file" else None
            if cli and "ticket_file_cli" in answers and cli != answers["ticket_file_cli"]:
                # t-281 F2: a `--ticket-file` on THIS command line that is not the flag the stored paste was
                # answered under is the person's newer word: it wins, and the older paste is dropped so that a
                # later entry with no flag does not go back to it. The same flag repeated beside the answer
                # (`continue_command` repeats every launch flag) is NOT a newer word: the paste, typed after it,
                # stays - else a pasted answer would be discarded by the very command that carries it. A paste
                # stored by an older driver (no `ticket_file_cli`) keeps its old precedence (builder rule 9).
                for stale in ("ticket_file", "ticket_file_cli"):
                    answers.pop(stale, None)
                self.state.setdefault("launch", {})["ticket_file"] = cli
                self.save_state()
                continue
            if cli and answers[key] != cli:
                # t-287 item 6: the stored paste wins over the SAME flag repeated beside it; say so once on entry,
                # with the file that will be read and the door that replaces it
                print(f"reading the ticket text you gave earlier ({self.s0_rel_path(answers[key])}); "
                      "give a different --ticket-file to replace it")
            flags[key] = answers[key]
        return flags

    def s0_rel_path(self, path) -> str:
        """The file as a person finds it from the project: relative to the project root, forward slashes; a path
        outside the project (a ticket file the person keeps elsewhere) is shown as it was given."""
        try:
            return Path(str(path)).resolve().relative_to(self.project).as_posix()
        except (OSError, ValueError):
            return str(path)

    def s0_stop(self, block: str, kind: str, text: str, doors: dict, details: str = "",
                problems: list | None = None, paste: bool = False, answer_note: str = "") -> None:
        """Raise the person's question for one S0 block, with what `s0_read_word` needs to read
        the answer: the block's key, its text and the tokens it offers (token -> the value it
        stands for), stored BEFORE the raise. The text is kept whole so that an answer this
        question does not take can be met with the same question and one changed sentence in
        front of it, without repeating the work that led here."""
        doors = self.s0_doors(doors)
        self.state["s0_block"] = block
        self.state["s0_ask"] = {"kind": kind, "text": text, "details": details, "doors": doors,
                                "problems": list(problems or []), "paste": paste, "answer_note": answer_note}
        self.save_state()
        raise Person(kind, text, "S0", details=details, answer_note=answer_note)

    @staticmethod
    def s0_doors(doors) -> dict:
        """The tokens an S0 stop takes: the block's own plus `stop` (C1-3: every S0 question offers it, and a whole-answer `stop`
        has an executor in `s0_read_word`). Added at READ time as well, so an `s0_ask` stored by an older driver takes it too."""
        return {"stop": "stop", **(doors or {})}       # a door the block already holds under `stop` is never silently replaced (F4)

    def s0_again(self, block: str, ask: dict, lead: str) -> Person:
        """The S0 question of `ask` kept for the next answer (`s0_block` / `s0_ask` stored again) and returned as the Person to raise,
        with `lead` in front of its whole text: the one form of an S0 re-ask (an answer it does not take, or a `stop`)."""
        self.state["s0_block"], self.state["s0_ask"] = block, ask
        self.save_state()
        return Person(ask.get("kind") or "halt", lead + "\n\n" + str(ask.get("text") or ""), "S0",
                      details=str(ask.get("details") or ""), answer_note=str(ask.get("answer_note") or ""))

    def s0_offered(self, ask: dict, with_stop: bool = True) -> list:
        """The answers of a stored S0 question as a person reads them: each door's token once, backquoted, then the paste when the
        question takes the ticket as text. `with_stop` False leaves the `stop` door out (the sentence after a `stop` names the others)."""
        doors = self.s0_doors(ask.get("doors"))
        offered = [f"`{value}`" for value in dict.fromkeys(doors.values()) if with_stop or value != "stop"]
        return offered + (["the ticket itself as text"] if ask.get("paste") else [])

    def s0_read_word(self) -> None:
        """The answer to the S0 stop this run is entered after, if there is one.

        Only what the stop offered acts: `retry` changes nothing (the step simply runs again);
        `go on` becomes a pass for THAT block only; a stand's name or a kept launch source
        corrects the launch; a pasted ticket becomes the ticket file; the whole answer `stop`
        holds the question (exit 3, nothing runs). Anything else is not guessed at by code (FR-12): it is NEW words the code cannot
        read, so it goes to the conductor (D-0041, FR-48: a problem, not a command - the seam `unread` with the question's own
        doors), and the question comes back changed and priced when the conductor cannot answer (FR-7). The signal to the callers
        is None: "nothing is decided - run the step again" (a conductor `continue` / `retry` leaves no block stored); a question
        raised by that road stores the block again, ONLY on a raise (`except Person`), never store-then-clear."""
        pending = self.state.setdefault("pending_words", {})
        words = pending.pop("S0", None)
        # The block is open only until THIS entry: cleared on every entry, answered or not, and set
        # again by `s0_stop` or by the re-ask below. A block that outlived an entry with no answer
        # would capture the answer to a LATER, unrelated stop at S0 (the env_probe halt, a refusal)
        # and show the old question again.
        ask, block = self.state.pop("s0_ask", None) or {}, self.state.pop("s0_block", None) or ""
        if not words or not block or not ask:
            self.save_state()
            return
        door = self.s0_doors(ask.get("doors")).get(self.s0_normalize(words))
        answers = self.state.setdefault("s0_answers", {})
        launch = self.state.setdefault("launch", {})
        if door == "stop":
            # The WHOLE answer `stop` (C1-3, FR-9: no question offers a decision nobody executes). It has its executor here, like the
            # halt's: the question is held with a changed first line (FR-7), exit 3, no conductor, nothing run or spent. `stop please`
            # is not this door - it takes the re-ask below like any other words.
            raise self.s0_again(block, ask, self.stop_held(
                "If you want the factory to go on after all, answer " + " or ".join(self.s0_offered(ask, False)) + "."))
        elif door == "retry":
            if block == "ticket_read":              # P01: the earlier `not needed` is dropped, the ticket is read again. ONLY at the
                answers.pop("ticket_read", None)    # ticket's own question: at any other block it is a word that must survive (G19)
        elif door == "go on":
            self.state.setdefault("s0_passes", {})[block] = {
                "words": words, "at": _now(), "problems": list(ask.get("problems") or []),
                # What the person was shown, cut to 300 characters on one line: the finding's
                # witness. Kept here so that it is the same text every time the pass is applied.
                "witness": " ".join(str(ask.get("text") or "").split())[:300] or f"S0 {block}"}
        elif block == "source_list" and door in ("read", "skip"):
            # The two words of one person that disagree (t-172 C5b): `read` drops the line of the list,
            # `skip` drops the flag (kept apart from `keep`, which chooses among --mr/--branch/--commit).
            answers["mr"] = door
            if door == "skip":
                dropped = launch.pop("mr", None) or getattr(self.flags, "mr", None)
                if dropped:
                    launch["mr_dropped"] = dropped
        elif block == "flags" and door:
            answers["keep"] = door
            for key in ("mr", "branch", "commit"):
                if key != door:
                    launch.pop(key, None)
        elif block == "stand" and door:
            answers["env"] = launch["env"] = door
        elif block == "key_form" and door == "no ticket":
            # The key is made by a command, not in this process (a key changed in a live process would leave every launch word
            # under the old name): the command is printed and the question is held (FR-9: its executor is the command).
            raise self.s0_again(block, ask, self.NO_TICKET_LEAD)  # remains: the person's own question comes back with the command printed (FR-9); nothing was accepted
        elif block == "no_change" and door == "change":
            # SS1-13: the change is given on the command line of a NEW entry (`--mr`, `--branch`, `--commit`); there is no executor
            # in this process (a flag cannot be added to a running command), so the command is printed and the question is held (FR-9).
            raise self.s0_again(block, ask, self.NO_CHANGE_LEAD)  # remains: the person's own question comes back with the command printed (FR-9); nothing was accepted
        elif block == "no_change" and door in ("current code", "ungrounded", "not built yet"):
            # SS1-13: the answer goes straight into `launch` (as the stand's `env`): `s0_note_launch` keeps only the FIRST entry's flags,
            # and the entry after this answer asks nothing again because the value is there (FR-7). The readers: `launch_flags`
            # (`ungrounded`), `role_lines` (the scout's line) and `s0_rest` (`pipeline.json`'s `implementation_source`).
            if door == "current code":
                launch["implementation_source"] = "current-code"
            else:
                launch["ungrounded"] = True     # no change is read: the scout does not halt on the missing diff
                if door == "not built yet":
                    launch["not_built_yet"] = True      # `s0_sides_sets` records the side `absent` (t-2181 PC-2)
        elif block.startswith("deliverable:") and door in ("ours", "another team's"):
            # t-2181 PC-2 (F-12): whose a non-real side is; the block names the side (`deliverable:<side>`, the name is open, AR-2).
            self._keep_sides_answer(block.partition(":")[2], door)
        elif block in ("ticket_read", "ticket_auth") and door == "not needed":
            # F3: the story's own ticket is "not needed". What that does is decided where the ticket is read
            # (`s0_ticket`): it goes on with a snapshot that is already there, and ends honestly without one.
            answers["ticket_read"] = "not needed"
        elif ask.get("paste") and self.s0_is_text(words):
            # Any non-empty text (t-267 C9): the ticket reader decides what it found, and no-criteria is the
            # `ticket_incomplete` question, not a refusal of the paste. Kept as typed: a tidied ticket is a
            # paraphrase of the requirements (references/templates/ticket-snapshot.md).
            target = self.state_dir / "driver-tmp" / f"ticket-{self.task}.md"
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(words, encoding="utf-8")
            answers.pop("ticket_read", None)        # G19: a pasted ticket is read; an earlier `not needed` must not set `ticket_not_needed`
            answers["ticket_file"] = launch["ticket_file"] = str(target)
            # the flag on the command line that carried this answer: a later `--ticket-file` that DIFFERS from it
            # is a newer word than the paste (`s0_flags`); the same flag repeated is not
            answers["ticket_file_cli"] = str(getattr(self.flags, "ticket_file", None) or "")
        else:
            doors = self.s0_doors(ask.get("doors"))
            lead = self.unread_lead(words)
            try:
                self.unread(ask.get("kind") or "halt", "S0", "", str(ask.get("text") or "") + "\n\n" + str(ask.get("details") or ""),
                            words=words, doors=tuple(doors), lead=lead, again=lambda said: self.s0_again(block, ask, said))
            except Person:
                # G1: the block is stored ONLY on a raise path, here, beside the `stop` branch - never stored first and cleared on a
                # return (a `Stop` / `InfraStop` out of `run_claude` would leave it alive past this entry, and a later S0 question
                # would be read against these doors). A conductor `continue` / `retry` returns: no key stored, the step runs again.
                self.state["s0_block"], self.state["s0_ask"] = block, ask
                self.save_state()
                raise
        self.save_state()

    LOCAL_KEY_COMMAND = "`ticket_adapter.py local-key --words-file <file>` (the file holds the story's text) prints a key"
    NO_TICKET_LEAD = ("The key is made by a command, not in this process: the command is in the answer block below. "
                      "Nothing was started under this name.")

    NO_CHANGE_LEAD = ("The change is given on the command line of a new start, not in this process: the story is started again with the same "
                      "command and one more flag, --mr <link>, --branch <name> or --commit <sha>. Nothing has been started on it yet.")

    def s0_is_local(self) -> bool:
        """Is this story local (SS1-14)? The ONE reader is `local_keys.is_local` (AR-13); it never raises, and False is the safe side."""
        import local_keys
        return local_keys.is_local(self.task, self.project)

    def s0_local_file(self, ticket_file):
        """The ticket file of S0: the one given, else - for a local story - its text file `qa-factory/local-tickets/<KEY>.md`."""
        if ticket_file or not self.s0_is_local():
            return ticket_file
        import local_keys
        return str(local_keys.ticket_path(self.task, self.project))

    def s0_key_form(self) -> None:
        """SS1-14 (M6): a NEW story whose launch key is not a key of this project's tracker is the person's question, before anything
        is read (CART-1 lost 38 minutes to `ADD-TO-CART`). Only a new story is checked: a `pipeline.json` or a snapshot on disk is an
        older story, which goes on under any name. ERROR DIRECTION: a false question costs one answer; a false pass costs the whole
        story under a name its cases are never recognised by. The same `AF.key_refused` as `ticket_adapter get --output` (AR-15, AR-19);
        a guess of the tracker's form is no refusal (`key_refused` says so). The pass is asked LAST (`s0_passed` records a use)."""
        if not AF.key_refused(self.task, self.config):
            return
        if (self.task_root / "pipeline.json").exists() or (self.task_root / "work" / self.SNAPSHOT).exists():
            return
        if self.s0_passed("key_form"):
            return
        # The commands and the setting's name are INSTRUCTIONS: they stand in the answer block (human-questions.md rule 5, FR-6), the
        # options say the same thing in the story's words.
        options = [{"answer": "no ticket", "token": "no ticket",
                    "says": "the story has no ticket: its text gets a key made by the factory, and you start the story again under that key"}]
        doors = {"no ticket": "no ticket", "go on": "go on"}
        note = f"To get a key for the text: {self.LOCAL_KEY_COMMAND}, then start again with --task <that key>."
        if AF.key_pattern_honoured(self.config):
            options.append({"answer": "key_pattern", "token": "retry",
                            "says": "tell the factory the shape of this project's keys (the setting is named below), then answer retry"})
            doors["retry"] = "retry"
            note += " The setting: adapters.ticket.key_pattern in qa-factory/config.json is the shape of one key."
        options += [{"answer": "go on", "token": "go on", "says": "cases under this name will not be recognised"}, self.STOP_OPTION]
        # The body gives the example only: the pattern (`[A-Z0-9]`...) reads as an internal id to the person (human-text `refusal_id`);
        # the whole description goes beside the question, in the details.
        example = AF.key_form(self.config, floor=True).example
        shape = f"a key looks like {example}" if example else AF.describe_key_form(self.config)
        self.s0_stop(
            "key_form", "halt",
            self.closed_question(
                "s0.key_form",
                f"`{self.task}` is not a key of this project's tracker: {shape}. "
                "Nothing has been read or written yet.\n\nWhat I need from you is one of these:", options),
            doors, details=f"launch key: {self.task}\nThe tracker's key form: {AF.describe_key_form(self.config)}", answer_note=note)

    def s0_references_allow_no_change(self) -> bool:
        """Condition 2 of the no-change question (SS1-13): `work/ticket-references.json` is readable and holds NO row whose kind is a change
        to the code (`ticket_light.change_kinds`, the table's `is_change`). ERROR DIRECTION: a file that is absent or unreadable, rows that
        are not a list, or a kinds table that cannot be read is False - no question, the old road (the scout's cascade, `s1.no_diff`): a
        wrong question asked of a story whose text DOES point at a change costs a person's answer, a missed one only an extra dispatch."""
        try:
            kinds = TL.change_kinds()
            rows = _read_json(self.task_root / "work" / "ticket-references.json").get("rows")
        except Exception:
            return False
        if not isinstance(rows, list):
            return False
        return not any(isinstance(row, dict) and row.get("kind") in kinds for row in rows)

    def s0_no_change_entry(self, flags: dict) -> None:
        """SS1-13 (owner, 31.10.2026: a real ticket with no merge request - the scout looks itself, no question; t-526 section 5): a LOCAL
        story started with no change to ground on is the person's question BEFORE the scout is dispatched. Asked when ALL hold: (1) no
        `--mr` / `--branch` / `--commit` / `--ungrounded` and no answer already in `launch` (`implementation_source`); (2) the story's
        references name no merge or pull request (`s0_references_allow_no_change`); (3) the story is local (`local_keys.is_local`) -
        ONLY that: a real ticket with no flags goes the old road, because the scout's cascade finds the change the text did not name.
        THE CALL STANDS OUTSIDE `if not kept` in `s0`: the entry after the answer finds the snapshot kept, and the answer is already in
        `launch` (FR-7: the question is not asked twice). Four answers (`current code` only where `code_repos` records a repository)."""
        if (flags.get("mr") or flags.get("branch") or flags.get("commit") or flags.get("ungrounded")
                or flags.get("implementation_source") or flags.get("not_built_yet")):
            return
        if not self.s0_is_local() or not self.s0_references_allow_no_change():
            return
        repos = bool(self.config.get("code_repos"))
        options = []
        doors = {"change": "change", "ungrounded": "ungrounded", "not built yet": "not built yet"}
        if repos:
            options.append({"answer": "current code", "token": "current code",
                            "says": "(Recommended) test the feature as it is now: what the code does is shown as how it behaves now, "
                                    "never as the expected value"})
            doors["current code"] = "current code"
        options += [{"answer": "change", "token": "change",
                     "says": "give me the change: a merge request, a branch or a commit, and start the story again with it"},
                    {"answer": "ungrounded", "token": "ungrounded", "says": self.UNGROUNDED_SAYS},
                    # t-2181 PC-2 (D2): the code is not written yet. Its twin is the `not built yet` option of `halt_text` (`s1.no_diff`, AR-19).
                    {"answer": "not built yet", "token": "not built yet", "says": self.NOT_BUILT_YET_SAYS},
                    self.STOP_OPTION]
        why = ("" if repos else " This project records no code repository, so there is no code in place to test the story against.")
        self.s0_stop(
            "no_change", "halt",
            self.closed_question(
                "s0.no_change",
                f"No merge request, branch or commit was given for {self.task}, and its text holds no link to one. It is a local story, "
                f"so no tracker holds a change tied to it.{why} Nothing has been run for it yet.\n\n"
                "Testing without a change to ground on is a decision, so pick one:", options),
            doors, details=f"local story {self.task}: no --mr, --branch, --commit or --ungrounded; work/ticket-references.json holds no row "
                           "of a kind that is a change",
            answer_note="To give the change: start the story again with --mr <link>, --branch <name> or --commit <sha>.")

    def _sides_entries(self, env=None) -> dict:
        """`{"entries": {side name: {reality, source[, deliverable][, settles_by][, reference]}}, "problem": str, "names": [...],
        "product_rows": bool}`.
        `entries` is what the registry (t-2181 PC-1b: `contract.registry_sides`, for the stand SELECTED at S0 (`env`), else the one
        the launch named with `--env`; later wins) and the person's launch words name, or {} when nothing makes a record owed (S13: an all-real launch with no reference
        writes nothing, and every reader derives the default). `problem` is why the registry leg could not be read or holds a
        malformed side row ("" when it read; those sides are left out of `entries`, never read as real); `names` are the side names
        the registry records on any stand, for the case check (C15)."""
        import contract   # late, as the other uses in this file
        flags = self.launch_flags()
        answers = (self.state.get("launch") or {}).get("sides_answers") or {}
        read = contract.registry_sides(self.project, env or flags.get("env"))
        entries = {}
        for name, row in read["sides"].items():
            if not row["reality"]:
                continue
            entry = {"reality": row["reality"], "source": "registry"}
            if row["deliverable"] is not None:
                entry.update(deliverable=row["deliverable"], settles_by=row["settles_by"])
            if row["reference"]:
                entry["reference"] = row["reference"]
            entries[name] = entry
        for name, word in flags["side"].items():
            entries.setdefault(name, {})
            entries[name].update(reality=word, source="launch")
        if flags["not_built_yet"]:
            entries["product"] = {"reality": contract.PARKING_REALITY, "deliverable": True, "source": "person"}
        for name, stand in flags["reference"].items():
            entries.setdefault(name, {"reality": self.SIDE_REAL, "source": "launch"})["reference"] = stand
        for name, ours in answers.items():
            if name in entries:
                entries[name].update(deliverable=bool(ours), source="person")
        if not any(entry["reality"] != self.SIDE_REAL or entry.get("reference") for entry in entries.values()):
            entries = {}
        return {"entries": entries, "problem": read["problem"], "names": read["names"], "product_rows": read["product_rows"]}

    def s0_write_sides(self, environment=None) -> None:
        """t-2181 PC-2: the question of the story's sides - `sides.deliverable` for a non-real side whose `deliverable` nothing says,
        on a story that names a side other than `product` (a single-side story is never asked: the default is true). Called in `s0`,
        after the stand is selected (`environment`, so a side known only from that stand's row is asked, never silently deliverable):
        the question must stand BEFORE `pipeline.json`. The record itself is `s0_sides_sets`
        (built into `pipeline.json` by `s0_rest`). Sides come from `--side <name>=<reality>`, `--reference <side>=<stand>`, the answer
        `not built yet` and the answers kept by `_keep_sides_answer`; the registry's rows come first (PC-1b), so a side whose
        `deliverable` a `product.sides` row says is not asked again (the second story of a project).
        C15 (INVARIANT: a side is one name everywhere, so `UI` never lives beside a recorded `ui`): a `--side` / `--reference` name that
        is not a recorded side name but equals one but for letter case is REFUSED, naming the recorded name; the offending name is
        dropped from the kept launch first, so the corrected flag on the next start is the door (it is not met again)."""
        got = self._sides_entries(environment)
        entries = got["entries"]
        flags = self.launch_flags()
        recorded = set(got["names"])
        for key in ("side", "reference"):
            for name in flags[key]:
                twins = sorted(r for r in recorded if r != name and r.casefold() == name.casefold()) if name not in recorded else []
                if twins:
                    launch = self.state.setdefault("launch", {})
                    (launch.get(key) or {}).pop(name, None)
                    self.save_state()
                    raise Refusal(f"the side `{name}` given with --{key} is not a side of this project, but `{twins[0]}` is, and side "
                                  f"names are compared exactly, so they would be two sides. Start again with --{key} using `{twins[0]}`, "
                                  f"or have the conductor record `{name}` as a new side (project_knowledge.py side --name {name} "
                                  "--deliverable yes|no --words-file <file>). Nothing was run for the story.")
        if not entries or all(name == "product" for name in entries):
            return
        for name in sorted(entries):
            if entries[name]["reality"] == self.SIDE_REAL or "deliverable" in entries[name]:
                continue
            self.s0_stop(
                f"deliverable:{name}", "halt",
                self.closed_question(
                    "sides.deliverable",
                    f"You started {self.task} with the side `{name}` marked as `{entries[name]['reality']}`. Whether this story "
                    f"delivers `{name}` or another team does decides what the story waits for and what the report hands to whoever "
                    "makes it real. Nothing has been run for it yet.\n\nWhose is it?",
                    [{"answer": "ours", "token": "ours",
                      "says": f"this story delivers `{name}`: the checks that need the real one wait until it exists"},
                     {"answer": "another team's", "token": "another team's",
                      "says": f"another team makes `{name}` real: this story does not wait for it, and the report lists what was not "
                              "checked against it"},
                     self.STOP_OPTION]),
                {"ours": "ours", "another team's": "another team's"},
                details=f"side {name}: reality {entries[name]['reality']}; no record says whether this story delivers it")

    def s0_sides_sets(self, environment=None) -> dict:
        """`{"sides.<name>.<attribute>": value}` for `pipeline.sides` - or {} when no record is owed (S13) - each value validated by the
        writer's own check (`stage_done.coerce_value`, never a second validator). `s0_rest` applies it to the `pipeline` dict
        (`stage_done.apply_facts`) BEFORE `pipeline.json` is written, so the file is born with its sides in ONE write and S0 is never
        recorded done without them: a refused value is a `Refusal` there and S0 replays whole (INVARIANT: a side the person marked
        non-real is recorded before any stage after S0 can read it, never recorded as real by this function, AR-28).
        When the launch names a side and does not name `product`, the record also carries `product: real, deliverable: true,
        source: default` so no reader loses the implicit side (the Lead's call, t-2378 (b))."""
        import stage_done
        got = self._sides_entries(environment)
        entries, sets, now = got["entries"], {}, _now()
        if got["problem"]:
            # PC-1b (S12): a registry that could not be read, or a malformed side row, is written down as `sides_unknown` - the
            # stamp carries it and the ledger never reads those Thens as proved; the unknown side itself is never recorded as real
            try:
                sets = {"sides_unknown.at": stage_done.coerce_value("sides_unknown.at", now),
                        "sides_unknown.why": stage_done.coerce_value("sides_unknown.why", got["problem"])}
            except ValueError as exc:
                raise Refusal(f"the story's sides cannot be recorded: {exc}") from exc
        if not entries:
            return sets
        if not got["product_rows"]:     # once a `product.sides` row exists `product` is not implied (as story_sides(root=) reads it)
            entries.setdefault("product", {"reality": self.SIDE_REAL, "deliverable": True, "source": "default"})
        try:
            for name in sorted(entries):
                entry = entries[name]
                raw = {"reality": entry["reality"], "deliverable": "true" if entry.get("deliverable", True) else "false",
                       "source": entry["source"], "at": now}
                if entry.get("settles_by"):
                    raw["settles_by"] = entry["settles_by"]
                if entry.get("reference"):
                    raw["reference"] = entry["reference"]
                for attr, value in raw.items():
                    key = f"sides.{name}.{attr}"
                    sets[key] = stage_done.coerce_value(key, value)
        except ValueError as exc:
            raise Refusal(f"the story's sides cannot be recorded: {exc}") from exc
        return sets

    def _keep_sides_answer(self, name: str, door: str, words: str = "", where: str = "") -> list:
        """t-2181 PC-2 (writer 2 of the sides): the person's answer to `sides.deliverable` for the side `name` is kept in the launch
        record (`launch.sides_answers`), the one place that outlives the S0 stop; `s0_sides_sets` carries it into
        `pipeline.sides` with `source: person`. The question is asked once per side, because the next entry finds the answer here.
        t-2559 (W2 B3): `words` (the person's own words, default the closed answer) and `where` (what the answer was to) let the S5
        hold's `not ours` answer use this ONE writer; `door == "ours"` is the only true. Returns the lines of this call that say the
        registry did not take the answer (t-2562 F-1: the S5 caller carries them to `pipeline.warnings`, `s0_rest` reads the launch list)."""
        launch = self.state.setdefault("launch", {})
        launch.setdefault("sides_answers", {})[name] = (door == "ours")
        self.save_state()
        said: list = []

        def not_kept(line: str) -> None:
            # the line goes to stdout AND to `launch.sides_not_kept`, which `s0_rest` turns into `pipeline.warnings` (a carrier the
            # report and gate A read; stdout is lost once the process ends)
            print(line)
            said.append(line)
            lines = launch.setdefault("sides_not_kept", [])
            if line not in lines:
                lines.append(line)
            self.save_state()
        # PC-1b, writer 2 of the registry (`by: driver`, `source: person`): the project keeps the answer, so the next story is not
        # asked. An experiment (`--no-trace`) records nothing (P8): the answer stays in this story's `pipeline.sides`, and one line
        # says so. The words are the closed answer the person gave (the caller hands over the door, not the raw text).
        if getattr(self.flags, "no_trace", False) or launch.get("no_trace"):
            not_kept(f"your answer about {name} was kept for this story only (an experiment leaves no trace)")
            return said
        try:
            import project_knowledge as PK
            row, problem, _ = PK.record(self.project, key=PK.SIDES_KEY, environment="", element=name, state=PK.KNOWN, scope="project",
                                        value={"deliverable": door == "ours", "settles_by": ""}, words=words or door, source="person",
                                        story=self.task, by="driver",
                                        where=where or "the answer to sides.deliverable at the start of the story")
            if row is None:
                not_kept(f"your answer about {name} was kept for this story only: the project's record of sides did not take it ({problem})")
        except Exception as exc:    # the answer is kept in the story either way; the registry is a convenience for the next one
            not_kept(f"your answer about {name} was kept for this story only: the project's record of sides could not be written "
                     f"({type(exc).__name__})")
        return said

    def s0_is_text(self, words: str) -> bool:
        """Is this answer a ticket pasted as text? Any non-empty text is (C9) - but a bare word that is a door
        of some S0 stop (`go on`, `retry`, a stand's name ...) is the person's word to a stop, never a ticket:
        `go on` typed at the `ticket_read` question must not become a one-word ticket (t-267 K6, negative).
        A closed list of the factory's own tokens is matched, never a person's wording (FR-12)."""
        one = self.s0_normalize(words)
        if not one:
            return False
        stands = {self.s0_normalize(str(e.get("name"))) for e in self.config.get("environments") or []
                  if isinstance(e, dict) and e.get("name")}
        return one not in self.S0_DOOR_WORDS and one not in stands

    def s0_passed(self, block: str, problems: list | None = None) -> bool:
        """Has the person's word already passed this block? A pass belongs to ONE block: `go on`
        on the incomplete ticket does not pass the readiness check, and a `go on` on readiness is
        a pass of its own. The incomplete-ticket pass holds only while what the check finds now
        is what the person was shown - a new problem raises the block again and names it."""
        saved = (self.state.get("s0_passes") or {}).get(block)
        if not saved:
            return False
        if problems is not None and not set(problems) <= set(saved.get("problems") or []):
            return False
        self._s0_passed.append((block, saved["words"]))
        if not saved.get("recorded"):
            self.s0_file_pass(block, saved)
        print(f"S0: {self.S0_PASS_NAMES.get(block, block)} passed by the person's word")
        return True

    def s0_file_pass(self, block: str, saved: dict, *, essence: str = "", key: str = "") -> None:
        """A pass is written down (FR-4): the block, the words, and - because every S0 block is
        the factory's own check - a finding in the person's words. The key makes it once per
        story and block. A failure is printed and never blocks the story.

        `essence` and `key` (both) file the same finding for a stop that is not a pass: the factory's
        own reader losing a criteria section (`s0_criteria_stop`, D-0050) is its defect from the moment
        it is shown, whatever the person then says - ONE filing call, not a second inline copy of it.
        `saved["witness"]` is the finding's witness; `saved["recorded"]` is set for a pass only."""
        # A refused filing is OWED (C1-7a, FR-4): the idempotency key makes the second write safe, and `recorded` below means "filed or owed"
        # (the ladder writes it again before the next brief; it ends in the seam's question, never in a print).
        self.owe_row(
            "project_decisions.py", "--root", str(self.project), "add-finding",
            "--essence", essence or f"S0 {block} passed by the person's word: {self.s0_quote(saved['words'])}",
            "--scope", "local-calibration", "--witness", saved.get("witness") or f"S0 {block}",
            "--idempotency-key", key or f"s0-pass:{self.task}:{block}",
            what=f"the finding about {'the lost read' if key else 'the pass'} at the start of the story")
        if not key:
            saved["recorded"] = True
            self.save_state()

    # --- the ticket by REST, in a light form (t-267, D-06) -----------------------------------------------
    # The tracker agent is a WRITE channel and not a data source: S0 reads the story's ticket with
    # `ticket_adapter get --raw-dir`, one call, no model. What it cannot read is the person's question
    # (`ticket_read`, FR-50's three answers); a login the tracker stopped accepting is an infrastructure
    # stop (exit 5, the door named), never a question about a ticket the person did nothing to. What the
    # parser found in what came back is judged by ONE structural check, `s0_criteria`: a title the reader took
    # from the first line and a criteria section the reader lost (a heading with text under it and no criteria
    # read, D-0050) are the person's questions (F2, F5), an empty title from the tracker is a refusal; a ticket
    # with no criteria section at all is a line in the story's record, never a question (P23); nothing reads the
    # words of the ticket for a phrase (FR-12).
    # A read that fails has one of FOUR owners, said by the adapter's exit code and error object (t-281 F3, t-287):
    # the tracker's (the `ticket_read` question; `retry_at` is read from the object), the project's setting (owner
    # `config`, the same question with the adapter's sentence verbatim), the factory's (a refusal that names the
    # file or the setting) and the login's (a stop; it also covers a token variable the shell lacks). No sentence
    # is matched.
    # The label a snapshot already on disk is reported under (K11, temporal): the route that wrote it, as
    # that snapshot named it. `jira_direct_api` is the label before t-267; `file` is the file adapter's and
    # the paste of before D-06 (the route is unknown); `agent` is the removed relay.
    SNAPSHOT_ROUTES = {"fetched": "fetched", "person_pasted": "person_pasted",
                       "jira_direct_api": "fetched (older label)",
                       "file": "file (route before D-06 unknown)",
                       "agent": "agent (route removed by D-06)"}

    def direct_api_usable(self) -> bool:
        """Is the tracker read by REST in this project? The adapter's own test (`ticket_adapter` decides what
        `usable` means, so it never drifts from what `get` really requires): a Jira adapter with a recorded
        `direct_api` whose address, auth type and secret reference are complete."""
        try:
            import ticket_adapter
            kind, adapter_cfg = ticket_adapter.resolve_adapter(self.config)
            return kind == "jira" and bool(adapter_cfg.get("direct_api")) and ticket_adapter.has_usable_direct_api(adapter_cfg)
        except Exception:               # a config nobody can read is "not usable": the question names the way on
            return False

    def tracker_door(self) -> str:
        """The environment variable that holds the tracker's token, as the project's own config names it."""
        direct = (((self.config.get("adapters") or {}).get("ticket") or {}).get("direct_api")) or {}
        return str(direct.get("secret_ref") or "").removeprefix("env:") or "the tracker token variable"

    def ticket_auth_lead(self) -> str:
        """The body both `ticket_auth` questions open with: what happened, in the story's words - no variable name, no command (the
        variable stands in the answer block, human-questions.md rule 5)."""
        return (f"The tracker no longer accepts this machine's token, so ticket {self.task} could not be looked at. Nothing about the "
                "story is wrong and nothing was recorded as not found.")

    def ticket_auth_note(self) -> str:
        return (f"The token the tracker reads is held in the environment variable {self.tracker_door()}; "
                "the shell the factory runs from needs it.")

    def s0_ticket_auth_question(self, said: str) -> None:
        """The tracker stopped accepting the token while S0 read the ticket (the adapter's exit 5, owner `auth`): the closed question
        `ticket_auth` (C1-3 F3 a; FR-50: access the work needs from outside is asked for, and the person can renew it, paste the
        ticket, or say the ticket is not needed). It is NOT the infrastructure of `claude -p` (`InfraStop`, exit 5): the person has
        something to decide, so a question exists (exit 3)."""
        line = " ".join(str(said or "").split())[:300]
        self.s0_stop(
            "ticket_auth", "halt",
            self.closed_question(
                "s0.ticket_auth",
                f"{self.ticket_auth_lead()} Nothing after this point was tried.\n\nWhat I need from you is one of these:",
                [{"answer": "retry", "token": "retry", "says": "renew the token the tracker accepts, and I read the ticket again",
                  "slots": {"what": "renew the tracker token"}},
                 {"answer": "not needed", "token": "not needed",
                  "says": "the story can go without this ticket: if I already hold part of it the story goes on with that part "
                          "and says so, and if I hold nothing the story ends here, because there is nothing to build it from"},
                 self.PASTE_OPTION, self.STOP_OPTION]),
            {"retry": "retry", "not needed": "not needed"},
            details=f"Ticket {self.task}: the tracker refused the token.\nThe tracker adapter said:\n{line or 'nothing'}",
            problems=["ticket_auth"], paste=True, answer_note=self.ticket_auth_note())

    def ticket_auth_person(self, said: str) -> "Person":
        """The same loss met by the freshness check of a story already running (`ticket_look_failed`): kind `ticket_auth`, three
        answers - `retry` (look again), `go on` (the story goes on with the text it was built on; `ticket_unchecked`, and the pass
        is kept for the freshness window, FR-4) and `stop`."""
        line = " ".join(str(said or "").split())[:300]
        text = self.closed_question(
            "fresh.ticket_auth",
            f"{self.ticket_auth_lead()} The story has its text from before, and the look at the ticket is only a check that the "
            "requirements have not moved.\n\nWhat I need from you is one of these:",
            [{"answer": "retry", "token": "retry", "says": "renew the token the tracker accepts, and I look at the ticket again",
              "slots": {"what": "renew the tracker token"}},
             {"answer": "go on", "token": "go on",
              "says": "go on with the text the story was built on, without the check; that is recorded, and I ask again only after "
                      "the check would be due again"},
             self.STOP_OPTION])
        return Person("ticket_auth", text, "S0", details=f"Ticket {self.task}: the tracker refused the token.\n"
                      f"The tracker adapter said:\n{line or 'nothing'}", answer_note=self.ticket_auth_note())

    def s0_kept_snapshot(self):
        """`(ticket, the file's text)` of the snapshot an earlier entry of S0 (or an earlier route) left, or
        None. It is read as it is and never rewritten: its sha256 is the story's `source_revision`, and a
        second REST read would change `fetched_at` and with it the hash (K11, temporal). S0 never rewrites it;
        after S0 only `ticket_adapter.py freshness` does (a `context` change, or `--adopt` after the person chose
        the new text - `Driver.ticket_freshness`, B-364), and `source_revision` stays the value `initialize` took
        (phases/s0.md section 2b): no decision goes stale silently."""
        path = self.task_root / "work" / self.SNAPSHOT
        try:
            text = path.read_bytes().decode("utf-8")
        except (OSError, UnicodeDecodeError):
            return None
        ticket = self.json_object(text)
        return (ticket, text) if ticket is not None else None

    def s0_ticket(self, ticket_file) -> tuple:
        """`(ticket, the snapshot's text, "from the ticket file" | "through the tracker", kept)`: the story's one
        ticket. A snapshot already on disk is the ticket (read as it is, labelled by the route that wrote it);
        else the person's file or paste (`--ticket-file`) - the requirement, with the tracker read BESIDE it
        for a comparison when REST is set up (F27); else the tracker, by REST. A LOCAL story's text file
        (`qa-factory/local-tickets/<KEY>.md`) is its ticket file (SS1-14)."""
        ticket_file = self.s0_local_file(ticket_file)
        how = "from the ticket file" if ticket_file else "through the tracker"
        kept = self.s0_kept_snapshot()
        if kept:
            ticket, text = kept
            route = str(((ticket.get("provenance") or {}).get("source")) or "")
            label = self.SNAPSHOT_ROUTES.get(route, f"{route} (older label)" if route else "unknown (no provenance recorded)")
            word = ("; you said the ticket is not needed, so the story goes on with it"
                    if (self.state.get("s0_answers") or {}).get("ticket_read") == "not needed" else "")
            print(f"S0: work/{self.SNAPSHOT} is already there ({label}); it is read as it is and not written again{word}")
            return ticket, text, how, True
        if ticket_file:
            # The person's text, parsed by the adapter with the same parser as a fetched description. With the raw
            # folder named, a read with no tracker beside it still leaves `work/ticket-references.json` (F4).
            code, out, ticket, both, failure = self.ticket_get("--ticket-file", ticket_file, *self.s0_raw_flags())
            if code:
                if self.ticket_is_factory_fault(code, failure):
                    raise self.ticket_factory_refusal(code, failure, both)
                if (failure or {}).get("owner") == "person":
                    # t-335 B-n4: the person's own file is missing or empty - theirs to supply. A raw `Refusal` here
                    # reached the conductor with the adapter's words; it is the same `ticket_read` question the
                    # tracker's failure raises, with the path in the answer block only.
                    self.s0_ticket_read_question(code, both, failure, own_file=True)
                raise Refusal(f"ticket_adapter get {self.task} (exit {code}):\n{both}")
            return ticket, self.s0_compare(ticket, out), how, False
        ticket, out = self.s0_rest_read()
        return ticket, out, how, False

    def s0_raw_flags(self) -> list:
        """The one place that builds the raw-folder flags of S0's reads (t-281 F4): the REST read of the story and
        the comparison read beside a pasted ticket pass the same `--raw-dir work/ticket-raw`, so the raw folder, the
        line view and the references exist on both legs and a paste-only read names the same folder."""
        return ["--raw-dir", str(self.task_root / "work" / "ticket-raw")]

    def s0_rest_read(self) -> tuple:
        """The ticket by REST, one call: `ticket_adapter get <T> --json --raw-dir work/ticket-raw` (the adapter
        leaves the raw responses, the line view, the references and the seeds S1 reuses beside the light
        snapshot it prints). A lost login (exit 5) is the `ticket_auth` question; any other failure is the person's
        `ticket_read` question - unless they already said the ticket is not needed, which ends the story here."""
        if (self.state.get("s0_answers") or {}).get("ticket_read") == "not needed":
            # P01 (C1-3 F2 a): not an exit with a command to run by hand but the question again, with the way on in it: `retry`
            # (the earlier `not needed` is dropped and the ticket is read again), the text itself, or `stop`.
            self.s0_stop(
                "ticket_read", "halt",
                self.closed_question(
                    "s0.ticket_read.not_needed_empty",
                    f"You said ticket {self.task} is not needed, and nothing of it was read, so there is no text to build "
                    "requirements, a plan or test cases from. The story cannot go on like this and nothing was written."
                    "\n\nWhat I need from you is one of these:",
                    [{"answer": "retry", "token": "retry",
                      "says": "I drop your earlier `not needed` and read the ticket again", "slots": {"what": "make the ticket readable"}},
                     self.PASTE_OPTION, self.STOP_OPTION]),
                {"retry": "retry"}, details=f"Ticket {self.task}: `not needed` was answered and no snapshot of the ticket exists.",
                problems=["ticket_read"], paste=True)
        code, out, ticket, both, failure = self.ticket_get(*self.s0_raw_flags())
        if code == 0 and ticket is not None:
            self.state.pop("s0_rest_failed", None)       # the tracker answers now: a later comparison reads it again
            return ticket, out
        import ticket_adapter
        if code == ticket_adapter.EXIT_AUTH_LOST and (failure or {}).get("owner") != "intermediary":
            # B-408 (E23): exit 5 with owner `intermediary` is NOT a lost login - something between this machine and the
            # tracker answered, the token was not judged - so it falls through to the `ticket_read` question below
            # (the owner is read as a field, never from the sentence, E24). Every other exit 5 is the `ticket_auth` question (F3 a).
            self.s0_ticket_auth_question(both)
        if self.ticket_is_factory_fault(code, failure):
            # The factory's own data or setting, not the tracker's: reported with the file named, never a question
            # about the network (F3, FR-3). Nothing is written for the story and no question is left open.
            raise self.ticket_factory_refusal(code, failure, both)
        self.s0_ticket_read_question(code, both, failure)

    def s0_ticket_read_question(self, code: int, said: str, failure: dict | None = None, own_file: bool = False) -> None:
        """The read did not come: the `ticket_read` question, FR-50's three answers, in the story's words. The
        text names every route tried and why it failed; the adapter's own words go to the details file. The
        register keys a repeat by this block and the story's key, and a retry that fails the same way comes back
        as the same question with the earlier answer shown (FR-7, `ask`). The time the tracker asked to be tried
        again at is `failure["retry_at"]`, the adapter's error object (t-281 F3) - no sentence is searched.
        `own_file`: the read was of the file the person NAMED (`--ticket-file`), so the project's folder of ticket
        files is not what was looked at, and the tracker was not read at all (no `s0_rest_failed` mark for the
        comparison that follows a paste)."""
        adapter = (self.config.get("adapters") or {}).get("ticket") or {}
        kind = str(adapter.get("kind") or adapter.get("name") or "").strip().lower()
        retry_at = str((failure or {}).get("retry_at") or "")
        note = ""
        if (failure or {}).get("owner") == "config":
            # t-287 item 2: the adapter said the project's own direct-API setting is incomplete (owner `config`); the
            # three answers stay (FR-50: the person may paste the ticket instead). Never "Restore what the message
            # names". t-363 B3 (B-256 g): its sentence - which keys, and the onboarding command - is an INSTRUCTION, so
            # it goes to the person WHOLE (FR-8) but into the answer block (human-questions.md rule 5), where a key
            # path and a command may stand; the body says "the setting named below" and stays answerable without them.
            tried = ("What stands in the way: the way this project reads tickets from the tracker directly is not set "
                     "up completely - the setting named below is missing or cannot be used.")
            fix = "record the setting named below for this project"
            named = " ".join(str((failure or {}).get("message") or "").split())
            note = ("The setting this is about, in the factory's own words: "
                    + (named or "the adapter named none; the onboarding step records the tracker's settings "
                       "(/qa-factory:qa-onboarding)"))
        elif kind == "file" and not own_file:
            tried = (f"I looked for the file {self.task}.md in the folder of ticket files this project names, and it "
                     "is not there or cannot be read.")
            fix = "put the ticket file in that folder"
        elif (failure or {}).get("owner") == "person":
            # t-329 item 6: the adapter said the ticket text the PERSON gave or keeps is missing or empty (owner
            # `person`), and the answer is theirs to give: the file at that path, or the text pasted (the three
            # answers stay, FR-50). The same kind of question as the `file` branch above, for a read that is not a
            # project folder's. t-335 B-n4: the path is an instruction, so it stands in the answer block and nowhere
            # in the body (human-questions.md rule 5); an adapter that names no file (an older one) is relayed as it was.
            named = str((failure or {}).get("file") or "")
            if named:
                tried = "The ticket text you gave me is missing or empty: the file named under \"How to answer\" below holds no ticket."
                fix = "put the ticket text in that file"
                note = f"The ticket file I looked for: {named}"
            else:
                tried = f"What stands in the way: {failure.get('message')}"
                fix = "put the ticket text in the file the message names"
        elif (failure or {}).get("owner") == "intermediary":
            # B-408: the adapter said what answered was not shown to be the tracker's own (owner `intermediary`: a
            # firewall, a proxy, a protection service, or an answer that could not be read) and that the token was NOT
            # judged. The body asserts no author and no token claim (FR-41); the title and the check go in the answer
            # block (`answer_note`, human-questions.md rule 5) in the factory's own words, never in the body. The three
            # answers stay (FR-50): `retry` after the check, `not needed`, or the pasted ticket.
            tried = (f"I asked the tracker for {self.task} through its web interface, and the answer did not come "
                     "from the tracker in a form I can read: something between this machine and the tracker (a "
                     "firewall, a proxy or a protection service) answered instead, or the answer could not be read. "
                     "I could not check whether the account's token works.")
            fix = ("check the tracker's address from this machine, outside the factory, with the command below: if it "
                   "answers 200 with application/json, the protection lets your machine through but not the factory's "
                   "requests — ask whoever runs it to let them through; if it does not, the network or the VPN is in "
                   "the way")
            direct = adapter.get("direct_api") if isinstance(adapter.get("direct_api"), dict) else {}
            base = str(direct.get("base_url") or "").strip()
            import http_client
            note = ("What answered, in the factory's own words: " + " ".join(str((failure or {}).get("message") or "").split())
                    + (("\nCheck: " + http_client.curl_line(f"{base.rstrip('/')}/rest/api/{direct.get('api_version') or '2'}/serverInfo"))
                       if base else ""))
        elif self.direct_api_usable():
            tried = (f"I asked the tracker for {self.task} through its web interface, with the account recorded for "
                     "this project, "
                     + ("and it answered that there is no such ticket, or that this account may not see it."
                        if code == 1 else "and it did not answer in a way I can use"
                        + (f": it asked to be asked again at {retry_at}." if retry_at else ".")))
            fix = ("fix what is in the way (the network or the VPN, this account's access to the ticket, the key "
                   "itself)")
        else:
            tried = ("No way to read a ticket is set up for this project: the tracker's web interface has no complete "
                     "address and token recorded, and the Jira assistant is not used to read tickets - it only "
                     "writes to them.")
            fix = "record the tracker's address and token for this project (onboarding does it)"
        # SS1-15: a tracker the role reads by a recorded route: the route stands in the answer block (human-questions.md rule 5),
        # the question and its three answers are the same (FR-50, FR-7)
        import ticket_adapter
        from source_inventory import tracker_route
        route = tracker_route(self.config)
        if route and ticket_adapter.reads_by_role(self.config):
            note = ((note + "\n") if note else "") + (
                f"The project's recorded route: {route['method'] + ', ' if route['method'] else ''}{route['ref']}. The conductor "
                "reads the ticket by it, saves the text and answers with the ticket file.")
        if not own_file:
            self.state["s0_rest_failed"] = (" ".join(str(said or "").split()).removeprefix("ticket_adapter: ")[:200]
                                            or f"the read ended with code {code}")
        self.s0_stop(
            "ticket_read", "halt",
            self.closed_question(
                "s0.ticket_read",
                f"I tried to read ticket {self.task} and could not, so I have no ticket text to build the story from. "
                f"{tried}\n\nI did not fill the gap with a guess: the requirements, the test plan and every test case "
                "are built from that text.\n\nWhat I need from you is one of these:",
                [{"answer": "not needed", "token": "not needed",
                  "says": "the story can go without this ticket: if I already hold part of it the story goes on with that part "
                          "and says so, and if I hold nothing the story ends here, because there is nothing to build it from"},
                 {"answer": "retry", "token": "retry", "says": f"{fix}, and I read the ticket again", "slots": {"what": fix}},
                 self.PASTE_OPTION, self.STOP_OPTION]),
            {"retry": "retry", "not needed": "not needed"},
            details=f"Ticket {self.task}: the read by code did not come.\nThe tracker adapter said:\n{(said or '').strip() or 'nothing'}",
            problems=["ticket_read"], paste=True, answer_note=note)

    def s0_compare(self, ticket: dict, out: str) -> str:
        """F27 / C6: the person's ticket (`--ticket-file`, or the paste) is the requirement; when REST is set up
        the tracker is read BESIDE it, never instead. Both present: `compare_person_vs_rest` -> ONE line (FR-25:
        which record is authoritative, and the gap) and `disagreements[]` in the snapshot. The tracker FAILING
        prints ONE line and never asks: the person gave the text because the tracker was not the way, and a
        question here would loop. A story whose read failed a moment ago is not asked again (one line, no call).
        A LOCAL story (SS1-14): no tracker holds its key, so there is nothing to compare and no call is made."""
        if self.s0_is_local():
            print("local story: no tracker holds this key, nothing to compare")
            return out
        if not self.direct_api_usable():
            return out
        failed = self.state.get("s0_rest_failed")
        if failed:
            print(f"the tracker could not be read for comparison: it could not be read a moment ago either ({failed})")
            return out
        try:
            code, rest_out, rest, both, failure = self.ticket_get(*self.s0_raw_flags(), echo=False)
        except Refusal as refusal:
            code, rest, both, failure = 1, None, refusal.text, None
        if code or rest is None:
            why = " ".join(str(both or "").split()).removeprefix("ticket_adapter: ")[:240] or f"the read ended with code {code}"
            if self.ticket_is_factory_fault(code, failure):
                # The factory's own fault is REPORTED here, in the one line: the person's text is the requirement
                # and the story goes on with it (C6: the comparison never stops the paste, never asks).
                named = f" `{failure['file']}`" if failure and failure.get("file") else ""
                why = f"the factory's own data or setting{named} is not usable ({why})"
            print(f"the tracker could not be read for comparison: {why}")
            return out
        self.s0_label_compare_view()
        import ticket_light
        found = ticket_light.compare_person_vs_rest(ticket, rest)
        print(found["line"])
        ticket["disagreements"] = found["disagreements"]
        import ticket_adapter
        return ticket_adapter.snapshot_text(ticket)       # one format function for the snapshot (L3, t-428)

    COMPARE_VIEW_LINE = ("The tracker's text, read for comparison; the story's requirement is the text the person gave "
                         "(ticket-snapshot.json)")

    def s0_label_compare_view(self) -> None:
        """The comparison read leaves `work/ticket-view.md` of the TRACKER's text beside the person's snapshot; a role
        reading it must not take it for the requirement. ONE first line says what it is (the REST leg's view is the
        story's own text and carries none). Said once: a view that already begins with it is left as it is."""
        view = self.task_root / "work" / "ticket-view.md"
        try:
            text = view.read_bytes().decode("utf-8")        # bytes: the tracker's CRLFs stay as they are
            if not text.startswith(self.COMPARE_VIEW_LINE):
                view.write_bytes((self.COMPARE_VIEW_LINE + "\n" + text).encode("utf-8"))
        except (OSError, UnicodeDecodeError):
            pass                    # no view (an older adapter): nothing to label, and the comparison goes on

    def s0_criteria(self, ticket: dict, how: str, source_file=None) -> str | None:
        """The ONE structural check of the ticket (F2, F4, F5): a title the reader took from the FIRST LINE of a
        text (no `# ` line in it) is the person's question once - `go on` keeps it, `retry` reads the file again
        after they added a title line - and the pass is written down (FR-4); a ticket read with no title at all
        (an empty summary from the tracker, a ticket file with none) is a refusal. Criteria (D-0050, P23): a ticket
        that read criteria goes on; one with NO criteria section goes on too and the return value is the line for
        the story's record (`pipeline.warnings`, the FIRST of them - gate A shows five), never a question; the only
        stop is a criteria section with text under it that the reader read nothing from (`s0_criteria_stop`: the
        factory's reader failed, not the ticket). Nothing here reads the text for a word; the parser found a
        title and a list, a heading and its lines, or it did not. The error direction is "a false question
        rather than a silent pass over a section with text in it" (I4).

        `source_file` (t-287 item 6): the file this ticket was actually read from - the person's file or the paste
        the driver stored (`driver-tmp/ticket-<T>.md`) - so that the question names the file the answer is read
        from, relative to the project; None when nothing was read from a file (the tracker, a kept snapshot)."""
        title = str((ticket.get("title") or "")).strip()
        where = f" (the file `{self.s0_rel_path(source_file)}`)" if source_file else ""
        read = f"from the ticket file `{self.s0_rel_path(source_file)}`" if source_file else how
        at_top = f"at the top of the file `{self.s0_rel_path(source_file)}`" if source_file else "at the top of your text"
        if (ticket.get("provenance") or {}).get("title_from") == "first_line":
            problems = ["title taken from the first line"]
            wiki = (ticket.get("provenance") or {}).get("markup") == "wiki"
            if wiki:
                # a text with `h2.`-style headings: `# ` is a list item there, so the title is a `title:` line of the header
                found = ("its header has no `title:` line, and a line that starts with `# ` is a list item in this kind "
                         "of text, never a title. I took this line as the title")
                put = (f"in a header {at_top}: a line `title: <the title>` between two lines of three dashes")
                seen = "no `title:` line in the header; this line was taken as the title: "
            else:
                found = "no line starts with `# `. I took its first line as the title"
                put = f"on a line that starts with `# ` {at_top}"
                seen = "no line starting with `# `; the first line was taken as the title: "
            if not self.s0_passed("ticket_title", problems):
                self.s0_stop(
                    "ticket_title", "halt",
                    self.closed_question(
                        "s0.ticket_title",
                        f"I read the ticket you gave me for {self.task}{where} and could not find a title in it: "
                        f"{found}: \"{self.s0_quote(title)}\". Nothing in "
                        "your text was changed, and the criteria and the comments are read from it as they stand."
                        "\n\nWhat I need from you is one of these:",
                        [{"answer": "go on", "token": "go on",
                          "says": "that line will do as the title; the story then carries a line saying that you accepted it"},
                         {"answer": "retry", "token": "retry", "says": f"put the title {put}, and I read it again",
                          "slots": {"what": "put the title in the ticket"}},
                         {"answer": "paste", "says": "paste the ticket again with a title - I use that instead",
                          "slots": {"what": "paste the ticket with a title"}},
                         self.STOP_OPTION]),
                    {"retry": "retry", "go on": "go on"},
                    details=f"Ticket {self.task}, read {read}.\nWhat the reader found:\n- {seen}{title}",
                    problems=problems, paste=True)
        elif not title or title == self.task:
            # P05 (C1-3 F2 a): a ticket with no title at all is the person's question - the paste door reads the ticket, which a
            # seam-raised refusal question would not (no `s0_block` is set there) - never "run the story again".
            self.s0_stop(
                "ticket_no_title", "halt",
                self.closed_question(
                    "s0.ticket_no_title",
                    f"I read ticket {self.task} {read} and it carries no title. The story needs a ticket with a title: a ticket "
                    "file holds it on a line that starts with `# `, and the tracker's summary is it for a fetched ticket. Nothing "
                    "was written.\n\nWhat I need from you is one of these:",
                    [{"answer": "retry", "token": "retry", "says": "put the title in the ticket (or the file), and I read it again",
                      "slots": {"what": "put a title in the ticket"}}, self.PASTE_OPTION, self.STOP_OPTION]),
                {"retry": "retry"}, details=f"Ticket {self.task}, read {read}.\nWhat the reader found:\n- no title",
                problems=["no title"], paste=True)
        if ticket.get("acceptance_criteria"):
            return None
        return self.s0_criteria_gap(ticket, read)

    S0_LINE_LIMIT = 180                   # gate A shows the first five warnings, each cut here (gate_brief): the line must fit whole

    def s0_criteria_scan(self, ticket: dict) -> dict:
        """What the ONE criteria-heading scanner (`ticket_light.criteria_section`) finds in the stored text of a ticket
        that read no criteria: `lost` - the first section with text under it (its heading line, line count, first line),
        `empty` - the first heading with nothing under it, `headings` - the names looked for; `unreadable` when the
        list of names cannot be built (the table is stale: nothing is established, FR-59). The text is scanned under
        BOTH markups, wiki and markdown, because a snapshot does not always say which it was (a REST one never does),
        and with the title line put back when the reader took it from the first line (the heading may be the line the
        title consumed): the scan may find a section the reader did not (a false stop), never miss one it found (I4)."""
        import ticket_adapter
        import ticket_light
        text = str(ticket.get("description") or "")
        provenance = ticket.get("provenance") or {}
        if provenance.get("title_from") == "first_line":
            text = str(ticket.get("title") or "") + "\n" + text
        lost = empty = None
        # two owners, told apart by WHICH call fails and never by the wording of the error (FR-12): the factory's own table
        # (`load_fields_table`) is the factory's, the project's `config.json` key (`acceptance_headings_for` with the table in hand) is the project's
        try:
            table = ticket_light.load_fields_table()
        except Exception as err:        # noqa: BLE001 - a table that cannot be read establishes nothing; the caller stops
            return self.s0_scan_unreadable("factory", err)
        try:
            heads = ticket_adapter.acceptance_headings_for(self.config, table)
        except Exception as err:        # noqa: BLE001 - the project's own key; the error names the key and its fix
            return self.s0_scan_unreadable("config", err)
        try:
            for markup in (("markdown", "wiki") if provenance.get("markup") == "markdown" else ("wiki", "markdown")):
                for section in ticket_light.criteria_section(text, headings=heads, section_names=table["section_names"], markup=markup)["sections"]:
                    if section["content_lines"]:
                        lost = lost or section
                    else:
                        empty = empty or section
        except Exception as err:        # noqa: BLE001 - the factory's reader failing on the text establishes nothing either
            return self.s0_scan_unreadable("factory", err)
        return {"headings": heads, "lost": lost, "empty": empty, "unreadable": False, "owner": "", "said": ""}

    @staticmethod
    def s0_scan_unreadable(owner: str, err: Exception) -> dict:
        """The scan result when the list of names cannot be built: `owner` is `config` (the project's key) or `factory` (its own file or
        reader); `said` is the error's own sentence, which names the key or the file and how to restore it (FR-1) - relayed whole (FR-8)."""
        return {"headings": None, "lost": None, "empty": None, "unreadable": True, "owner": owner, "said": " ".join(str(err).split())}

    S0_LOST_READ = "criteria section unread"                # the problem word of a section the reader lost (a pass on it covers only that)
    S0_HEADINGS_UNREADABLE = "criteria headings unreadable"  # a DIFFERENT fact: the list of names cannot be built. One word per fact:
    # a `go on` given to one stop never covers the other (`s0_passed`: "a new problem raises the block again and names it")

    def s0_criteria_gap(self, ticket: dict, read: str) -> str | None:
        """A ticket that read NO criteria (D-0050, P23). A criteria section with text under it that the reader read nothing
        from is the FACTORY's failure (FR-46): ONE closed question that says so, whose answers are only roads - paste the
        ticket again, go on with the description whole, stop (no `retry`: the reader is deterministic, the same text reads the
        same, FR-2) - and a finding the moment it is shown. A list of names that cannot be built is a stop too (FR-59: an unknown
        is not a pass), but its owner is told (the project's `config.json` key, or the factory's own file), it has its OWN problem
        word, and it never offers the paste: the same list would stop the same ticket again (FR-2). Anything else goes on: the
        return value is the line for `pipeline.warnings` (gate A), saying what was looked for, never "there are no
        requirements" (FR-41). `None` when a stored pass of the person covers the stop, the pass line being theirs to write
        (`s0_passed`; the legacy problem word of a pass stored before D-0050 covers a lost read too, FR-14)."""
        scan = self.s0_criteria_scan(ticket)
        if not (scan["lost"] or scan["unreadable"]):
            return self.s0_criteria_line(scan)
        lost = scan["lost"]
        problems = [self.S0_LOST_READ if lost else self.S0_HEADINGS_UNREADABLE]
        if self.s0_passed("ticket_incomplete", problems) or (lost and self.s0_passed("ticket_incomplete", ["no acceptance criteria"])):
            return None
        go_on = {"answer": "go on", "token": "go on",
                 "says": "go on: the requirements are read from the whole description, where that text stays; "
                         "the story then carries a line saying that you accepted it"}
        note = ""
        if lost:
            found = (f"I read ticket {self.task} {read} and found a section named `{lost['heading']}` in it, and read no "
                     "criteria from it - this is the factory's reader failing on that section, not your ticket. "
                     f"The section begins: \"{self.s0_quote(lost['first_line'])}\". Nothing in your text was changed.")
            saw = f"a section named `{lost['heading']}` with {lost['content_lines']} line(s) under it and no criteria read from it"
            witness = f"S0 {self.task}: {saw}: {self.s0_quote(lost['first_line'])}"
            essence = (f"S0: the reader found the criteria section `{lost['heading']}` in ticket {self.task} and read no "
                       "criteria from it - the factory's reader, not the ticket")
            key, paste, options = f"s0-criteria-unread:{self.task}", True, [self.PASTE_OPTION, go_on, self.STOP_OPTION]
        else:
            # the paste is NOT offered: it reads the same text against the same broken list and comes back to this stop (FR-2)
            fix_stop = {"answer": "stop", "token": "stop",
                        "says": "stop the story here; nothing runs, and you start it again once what is named below is fixed"}
            saw = "the list of names the criteria sections are looked for under could not be built"
            witness = f"S0 {self.task}: {saw}"
            key, paste, options = f"s0-headings-unreadable:{self.task}", False, [go_on, fix_stop]
            if scan["owner"] == "config":
                found = (f"I read ticket {self.task} {read}, but this project's setting for the names of the sections the criteria are "
                         "looked for under cannot be used, so I cannot tell whether the ticket has such a section. This is the "
                         "project's setting, not your ticket. Nothing in your text was changed.")
                essence = f"S0: the project's setting for the criteria heading names could not be used for ticket {self.task} - the project's config, not the ticket"
                note = "The setting this is about, in the factory's own words: " + (scan["said"] or "the adapter named none")
            else:
                found = (f"I read ticket {self.task} {read}, but I could not read the list of section names the criteria are "
                         "looked for under (a file of the factory's own is not usable), so I cannot tell whether the ticket "
                         "has such a section. This is the factory failing, not your ticket. Nothing in your text was changed.")
                essence = f"S0: the list of criteria heading names could not be built for ticket {self.task} - the factory's file, not the ticket"
                note = "The file this is about, in the factory's own words: " + (scan["said"] or "the reader named none")
        self.s0_file_pass("ticket_incomplete", {"witness": witness}, essence=essence, key=key)
        self.s0_stop(
            "ticket_incomplete", "halt",
            self.closed_question("s0.ticket_incomplete", found + "\n\nWhat I need from you is one of these:", options),
            {"go on": "go on"},
            details=f"Ticket {self.task}, read {read}.\nWhat the check found:\n- {saw}\n{self.s0_headings_looked_for()}",
            problems=problems, paste=paste, answer_note=note)

    def s0_criteria_line(self, scan: dict) -> str:
        """The line for `pipeline.warnings` of a ticket whose criteria section is absent or empty: what was looked for, in at most
        S0_LINE_LIMIT characters; the names are cut, not the sentence."""
        tail = "; the requirements are read from its description, comments, attachments and linked tickets"
        if scan["empty"]:
            heading = scan["empty"]["heading"]
            room = self.S0_LINE_LIMIT - len(f"S0: ticket {self.task} has a section `` with nothing under it{tail}")
            return (f"S0: ticket {self.task} has a section `{heading if len(heading) <= room else heading[:max(room - 3, 1)] + '...'}` "
                    f"with nothing under it{tail}")
        shown = list(scan["headings"])
        while True:
            line = f"S0: ticket {self.task} has no section named {', '.join(shown)}{' ...' if len(shown) < len(scan['headings']) else ''}{tail}"
            if len(line) <= self.S0_LINE_LIMIT:
                return line
            if len(shown) > 1:
                shown.pop()
            elif len(shown[0]) <= 4:          # nothing left to cut: the task id itself is the length
                return line
            else:                             # one name alone is too long (a long task id, a long project heading): cut the name
                shown = [shown[0][:max(len(shown[0]) - (len(line) - self.S0_LINE_LIMIT) - 3, 1)] + "..."]

    def s0_headings_looked_for(self) -> str:
        """The sentence that says where the criteria were looked for (t-281 F5): the headings verbatim, from the
        same merged list the reader used (the table of the light form plus the project's own), and the setting
        that adds a name. It states what was searched, not that nothing exists: a section named otherwise is the
        likely cause, and the person can name it. A list that cannot be built (the table is unreadable) says that
        in words; the adapter has refused the same table before this point, so this is the stale-file case."""
        import ticket_adapter
        try:
            names = ticket_adapter.acceptance_headings_for(self.config)
        except Exception:                # noqa: BLE001 - a text for a person is never lost to a table fault
            return ("I looked for a section named like the acceptance criteria, but the list of those names could not "
                    "be read.")
        return ("I looked for a section named one of: " + ", ".join(names) + ". If your ticket names that section "
                "otherwise, the name can be added to `direct_api.acceptance_headings` in `qa-factory/config.json`, "
                "and then I find it.")

    # -- the person's list of sources not to read (B-231, t-172) --------------------------------
    # `--skip-sources FILE` is the person's word given BEFORE the run: one source per line and why it is
    # left out. S0 reads it (before anything is fetched), asks about what it cannot use, and writes
    # `work/source-exclusions.json`; from then on every inventory write and every fetch door marks or
    # refuses what the record names (source_exclusions.py, source_inventory.py, ticket_adapter.py).
    SOURCE_LIST_SHOWN = 10          # problem lines one question lists; the rest read "and N more"
    LS_REMOTE_SECONDS = 10          # one ask of the remote per merge request; a slow remote is not waited for

    @staticmethod
    def list_tail(text: str) -> str:
        """The last path segment of a repository or project, lower case, without a `.git`."""
        last = [part for part in re.split(r"[/:]", str(text or "").strip().strip("/")) if part][-1:] or [""]
        return last[0].removesuffix(".git").lower()

    def checkout_for(self, repo: dict, want: str = "") -> tuple:
        """`(checkout, top, why)` for one `implementation_repos[]` entry: the folder to ask git in, the top level of
        the repository it lies in, and, when the entry cannot be used, ONE sentence for the person that carries its
        own door (the callers add only their consequence). `(None, None, "")` is an entry with no `local_path`.

        A `local_path` may name a folder INSIDE a repository (the application of a monorepo, or `.` when the code
        sits next to the project). The old test, a `.git` in that very folder, skipped such an entry without a word
        (B-412). The INVARIANT is the direction of error: git never asks a repository the config does not name.
        When the top level IS the folder, nothing more is checked (today's behaviour, worktrees and initialised
        submodules included). When the top level is ABOVE it, the repository's origin must be the one
        `remote_identity` names (host and path when both parse, the last segment otherwise) and, when `want` is
        given, the merge request's own project; anything else, or an unknown, is not used and says why. Shown
        origins are `host/path` or the last segment, never the raw URL: a remote may carry a token."""
        import test_repo_base as TRB
        import http_client
        import ticket_light
        local = str(repo.get("local_path") or "")
        if not local:
            return None, None, ""
        rid = str(repo.get("repo_id") or repo.get("name") or "the repository")
        door = f"; point `local_path` of {rid} in `qa-factory/config.json` at a checkout of that repository"
        try:
            checkout = (self.project / local).resolve()
            present, folder = checkout.exists(), checkout.is_dir()
        except (OSError, ValueError):
            return None, None, f"`{local}` cannot be read as a path{door}"
        if not present or not folder:
            return None, None, f"`{local}` " + ("is not a folder" if present else "does not exist") + door
        if shutil.which("git") is None:
            return None, None, "git is not on PATH; install git or put it on PATH"
        found = TRB._top_and_prefix(checkout)
        if found is None:
            if TRB._inside_a_repository(checkout):
                return None, None, f"git could not answer in `{local}`; `git -C {local} status` shows what git says"
            return None, None, f"`{local}` is not inside a git repository{door}"
        top = found[0]
        if TRB._same_dir(top, checkout):
            return checkout, top, ""
        try:
            where = os.path.relpath(top, self.project).replace(os.sep, "/")
        except ValueError:                # another drive: the last segment names it, and a line never crashes
            where = Path(top).name
        lead = f"`{local}` lies in the repository at `{where}`"
        identity = str(repo.get("remote_identity") or "")
        if not identity:
            return None, None, (f"{lead} and `remote_identity` of {rid} is empty; set `remote_identity` of {rid}, or "
                                "point its `local_path` at a checkout of that repository")
        origin = TRB._git(top, "config", "--get", "remote.origin.url") or ""

        def clean(text):
            """No userinfo, query or fragment: a remote may carry a credential in any of the three (E14). URLs go
            through `http_client.safe_url`; the other forms (scp `user@host:path`, a local path) are cut at the last
            `@` and at the first `?` or `#`. Every comparison and every printed value is made on this form."""
            text = str(text or "").strip()
            if "://" in text:
                return http_client.safe_url(text)
            return re.split(r"[?#]", text, maxsplit=1)[0].rsplit("@", 1)[-1]

        def parsed(text):
            host, path = ticket_light.split_remote_identity(clean(text))
            return (host.lower(), path.lower()) if host and path else None

        def shown(text):
            both = parsed(text)
            return f"{both[0]}/{both[1]}" if both else (self.list_tail(clean(text)) or "not set")

        got, named = parsed(origin), parsed(identity)
        tail = self.list_tail(clean(origin))
        if not ((got == named) if got and named else (bool(tail) and tail == self.list_tail(clean(identity)))):
            return None, None, (f"{lead} whose origin is `{shown(origin)}`, not `{shown(identity)}` that "
                                f"`remote_identity` of {rid} names in `qa-factory/config.json`; if that repository "
                                "is the right one, set `remote_identity` to its origin, otherwise point "
                                "`local_path` at a checkout of the right repository")
        if want and tail != want:
            return None, None, (f"{lead} whose origin `{tail or 'not set'}` is not the merge request's project "
                                f"`{want}`; point `local_path` of {rid} at a checkout of `{want}`")
        return checkout, top, ""

    def repo_of_project(self, project: str, why: list | None = None):
        """(repo name, checkout path) of the configured implementation repository whose remote or id ends with
        `project`'s last path segment, or None. The tail is compared WHOLE (`testproject1` is not `testproject1-ui`):
        asking the wrong project's remote for `refs/merge-requests/<iid>/head` would name the head of a
        different request with the same number. An entry that matches but cannot be used (`checkout_for`) is
        skipped, and its sentence is appended to `why` when the caller passed a list: the return shape stays."""
        wanted = self.list_tail(project)
        for repo in self.config.get("implementation_repos") or []:
            local = str(repo.get("local_path") or "")
            if not wanted or not local:
                continue
            if wanted not in (self.list_tail(repo.get("remote_identity")), self.list_tail(repo.get("repo_id"))):
                continue
            checkout, _top, reason = self.checkout_for(repo)
            if checkout:
                return str(repo.get("repo_id") or repo.get("name") or wanted), checkout
            if reason and why is not None:
                why.append(reason)
        return None

    def s0_resolve_head(self, entry: dict) -> None:
        """Best effort: the head commit of an excluded merge request, written into the entry's target
        (`head_sha`) so that a citation by commit is the same source as one by number (t-172 C2). One
        `git ls-remote` per request, LS_REMOTE_SECONDS at most. A failure is PRINTED and the word is kept
        without a commit (`head_sha` stays null): the exclusion holds by its number regardless."""
        target = entry["target"]
        target["head_sha"] = None
        name = entry["as_written"]
        unusable = []
        found = self.repo_of_project(target.get("project") or "", why=unusable)
        if not found and unusable:
            # An entry that names the project but cannot be asked is not "no checkout configured" (B-412).
            print(f"{name}: " + "; and ".join(unusable) + "; so the head commit of this merge request is not looked "
                  "up, and the word holds by the number")
            return
        if not found:
            print(f"{name}: no local checkout of `{self.list_tail(target.get('project'))}` is configured, so the "
                  "head commit of this merge request is not looked up; the word holds by the number, and a "
                  "line naming a commit or `branch:<name>` names it another way")
            return
        _label, checkout = found
        head, why = self.ls_remote_head(checkout, f"refs/merge-requests/{target['iid']}/head",
                                        "the merge request is not listed there (a merged or closed one is pruned)")
        if not head:
            print(f"{name}: the head commit of this merge request could not be looked up ({why}); the word holds "
                  "by the number")
            return
        target["head_sha"] = head

    def ls_remote_head(self, checkout, ref: str, missing: str = "the name is not listed there") -> tuple:
        """THE one ask of a remote for one ref (AR-15): `git -C <checkout> ls-remote origin <ref>`, LS_REMOTE_SECONDS at most, no prompt.
        `(sha, "")` or `("", why)`. Only the row of `ref` itself counts (`ls-remote` matches a pattern from the end of a name) and only
        when it is a 40-hex commit id; a failed command gives the first line of git's own words, a clean answer with no such row gives
        `missing`. The WORDS of `why` are the caller's to show or to put in plain words (a person never reads them as they are)."""
        try:
            done = subprocess.run(["git", "-C", str(checkout), "ls-remote", "origin", ref], capture_output=True, text=True,
                                  encoding="utf-8", errors="replace", timeout=self.LS_REMOTE_SECONDS,
                                  env=dict(self.env, GIT_TERMINAL_PROMPT="0"))
        except subprocess.TimeoutExpired:
            return "", f"the remote did not answer within {self.LS_REMOTE_SECONDS} seconds"
        except OSError as exc:
            return "", f"git could not be run ({type(exc).__name__})"
        rows = [line.split()[0] for line in done.stdout.splitlines() if re.fullmatch(r"[0-9a-f]{40}\s+" + re.escape(ref), line.strip())]
        if done.returncode or not rows:
            return "", (done.stderr.strip().splitlines() or [missing])[0][:160]
        return rows[0], ""

    def s0_resolve_branch(self, entry: dict) -> None:
        """Best effort: the commit a `branch:<name>` word stands for, written into its target (`sha`), so that
        `git_route` and the manifest detector see the branch's head too: a branch word alone did nothing there
        (B-231, critic t-192). The word names no project, so every configured implementation repository with a
        local checkout is asked, `git ls-remote origin refs/heads/<name>`, LS_REMOTE_SECONDS at most each. The
        INVARIANT is the direction of error: the commit is kept only when the answers agree on ONE id; none,
        a failure, or two different ids (the same branch name in two repositories) leave `sha` null, print one
        line, and the word holds by the branch name. Never a refusal. A word that already carries a commit, or
        names no branch, is left as it is."""
        target = entry["target"]
        branch = target.get("branch")
        if target.get("sha") or not branch:
            return
        target["sha"] = None
        name = entry["as_written"]
        import test_repo_base as TRB
        checkouts, tops, with_path = [], [], False
        for repo in self.config.get("implementation_repos") or []:
            if not str(repo.get("local_path") or ""):
                continue
            with_path = True
            checkout, top, reason = self.checkout_for(repo)
            if not checkout:
                print(f"{name}: {reason}; the word holds by the branch name")
                continue
            # One repository counts once, however many folders of it are configured: the "agree on ONE id" rule
            # below counts repositories (B-412).
            if not any(TRB._same_dir(top, seen) for seen in tops):
                checkouts.append(checkout)
                tops.append(top)
        if not checkouts:
            if not with_path:
                print(f"{name}: no local checkout of an implementation repository is configured, so the commit of "
                      "this branch is not looked up; the word holds by the branch name")
            return
        found, why = [], ""
        ref = f"refs/heads/{branch}"
        for checkout in checkouts:
            head, said = self.ls_remote_head(checkout, ref, "the branch is not listed there")
            if not head:
                why = why or said
                continue
            found.append(head)
        if len(set(found)) == 1:
            target["sha"] = found[0]
            return
        if found:
            why = "the branch has a different commit in each repository that lists it"
        print(f"{name}: the commit of this branch could not be looked up ({why}); the word holds by the branch name")

    @staticmethod
    def mr_conflicts(mr: str, entries: list) -> list:
        """The entries of the list that name the merge request the launch flag `--mr` names (F10). A bare `!N`
        or `N` has no project and is equal by number alone: asking too often costs one answer, a silent
        choice between two words of one person is the defect."""
        import source_exclusions as SE
        text = str(mr or "").strip()
        bare = re.fullmatch(r"!?(\d+)", text)
        short = None if bare else re.fullmatch(r"([\w.][\w./-]*)!(\d+)", text)
        hits = []
        for entry in entries:
            target = entry.get("target") or {}
            if target.get("kind") != "mr":
                continue
            iid = str(target.get("iid") or "").lstrip("0")
            if bare:
                hit = bare.group(1).lstrip("0") == iid
            elif short:
                mine, theirs = short.group(1).lower(), str(target.get("project") or "").lower()
                hit = short.group(2).lstrip("0") == iid and (
                    mine == theirs or mine.endswith("/" + theirs) or theirs.endswith("/" + mine))
            else:
                hit = SE.matches(entry, url=text)
            if hit:
                hits.append(entry)
        return hits

    @staticmethod
    def merge_list_entries(clean: list, loose: list) -> list:
        """The clean entries and the ones a problem line carried (their TARGET read, their reason did not:
        none, or it starts like a target), in line order. Dropping them would read what the person named
        (t-172 C5c). The same thing named twice keeps one entry, every reason and every line number."""
        import source_exclusions as SE
        merged = [dict(entry) for entry in clean]
        for entry in loose:
            same = next((m for m in merged if SE._identity(m["target"]) == SE._identity(entry["target"])), None)
            if same is None:
                merged.append(dict(entry))
                continue
            if entry.get("reason"):
                same["reason"] = (same["reason"] + " | " if same["reason"] else "") + entry["reason"]
            lines = same["line"] if isinstance(same["line"], list) else [same["line"]]
            same["line"] = lines + (entry["line"] if isinstance(entry["line"], list) else [entry["line"]])
        first = lambda e: e["line"][0] if isinstance(e["line"], list) else e["line"]
        return sorted(merged, key=first)

    def s0_source_list(self, flags: dict) -> None:
        """Read the person's list of sources not to read, before anything is fetched (P4, C1, C5).

        Without the flag: nothing is written and nothing is printed - a story with no list is today's story.
        A story whose inventory already exists: the list cannot apply (a source already read cannot be left
        out before the run), so the person is asked, never told in passing. A file that is missing, too large,
        not text, or has a line the code cannot use: a question with `retry` and `go on`; `go on` applies the
        lines whose TARGET read and never the others. The launch's `--mr` naming the same request as a line:
        its own question (`read` / `skip`)."""
        listed = flags.get("skip_sources")
        if not listed:
            return
        import source_exclusions as SE
        work = self.task_root / "work"
        # An inventory that S0's OWN read seeded (the REST read leaves `field_ids` and `prefix_probes` there,
        # t-267 C3) or marked (`auth_stop`) is no source collected: when the record of THIS list - the same
        # bytes - is already written, the list was applied before anything was read and a later entry of S0
        # (after a stand or readiness answer) must not ask "too late". A list not yet applied, or other bytes
        # than the record holds, still meets the question: what was read cannot be left out afterwards.
        if (work / "source-inventory.json").is_file() and not self.s0_list_applied(Path(listed)):
            self.s0_list_too_late()
            return
        data, problems, entries, loose, parsed = None, [], [], [], []
        try:
            data = Path(listed).read_bytes()
        except OSError as exc:
            problems.append(("file", f"I cannot open `{listed}` ({type(exc).__name__}): nothing is there to read."))
        if data is not None:
            entries, parsed = SE.parse_bytes(data, self.task)
            problems += [(f"line {p['line']}: {p['code']}", p["message"]) for p in parsed]
            loose = [p["entry"] for p in parsed if p.get("entry")]
        applied = self.merge_list_entries(entries, loose)
        keys = [key for key, _ in problems]
        if problems and not self.s0_passed("source_list", keys):
            shown = [message for _key, message in problems[:self.SOURCE_LIST_SHOWN]]
            more = len(problems) - len(shown)
            usable = len(applied)
            # The two kinds of problem are told apart by COUNT (FR-10: what the text says is what `go on` does):
            # a line whose source I could not read is never applied; a line whose source I read but which has a
            # problem of its own (no reason, a second source after it) IS applied on `go on`. The counts are of
            # ALL the lines, not of the ones shown.
            unread = sum(1 for p in parsed if not p.get("entry"))
            flawed = sum(1 for p in parsed if p.get("entry"))
            plural = lambda n, one, many: one if n == 1 else many
            parts = []
            if data is None:
                parts.append("The list itself could not be opened, so no source of it is left out.")
            if unread:
                parts.append(f"{unread} {plural(unread, 'line names', 'lines name')} no source I can read: "
                             f"{plural(unread, 'it is', 'they are')} not applied, so "
                             f"{plural(unread, 'that source', 'those sources')} would be read like any other.")
            if flawed:
                parts.append(f"{flawed} {plural(flawed, 'line names', 'lines name')} a source I can read but "
                             f"{plural(flawed, 'has', 'have')} a problem of {plural(flawed, 'its', 'their')} own (no "
                             f"reason, or a second source after it): if you answer `go on`, "
                             f"{plural(flawed, 'it is', 'they are')} applied anyway and the problem is noted.")
            parts.append(f"{usable} {'line' if usable == 1 else 'lines'} of the list I can use.")
            self.s0_stop(
                "source_list", "halt",
                self.closed_question(
                    "s0.source_list",
                    f"Before starting {self.task} I read the list of sources you asked me not to read ({listed}), "
                    f"and {len(problems)} {'problem' if len(problems) == 1 else 'problems'} stopped me:\n\n"
                    + "\n".join("- " + message for message in shown)
                    + (f"\n- and {more} more (all of them are in the file named below)" if more else "")
                    + "\n\nNothing has been read or fetched yet. " + " ".join(parts)
                    + "\n\nWhat I need from you is one of these:",
                    [{"answer": "retry", "token": "retry", "says": "fix the file, and I read it again",
                      "slots": {"what": "fix the list file"}},
                     {"answer": "go on", "token": "go on",
                      "says": "start the story with the lines I could read; a line I could not read is not applied, and the "
                              "story carries a line saying that you accepted it"},
                     self.STOP_OPTION]),
                {"retry": "retry", "go on": "go on"},
                details="\n".join(f"{key}: {message}" for key, message in problems), problems=keys)
        if data is None:
            print(f"S0: {listed} could not be read; the story starts without a list of sources not to read")
            return
        answers = self.state.get("s0_answers") or {}
        mr = flags.get("mr")
        if mr and answers.get("mr") != "skip":
            hits = self.mr_conflicts(mr, applied)
            if hits and answers.get("mr") == "read":
                applied = [entry for entry in applied if entry not in hits]
                for entry in hits:
                    print(f"{entry['as_written']}: you chose to read it, so its line of the list is not applied")
            elif hits:
                first = hits[0]
                self.s0_stop(
                    "source_list", "halt",
                    self.closed_question(
                        "s0.source_list.conflict",
                        f"You started {self.task} with a merge request to take the code from ({mr}), and your list of "
                        f"sources not to read names the same one: {first['as_written']} - \"{SE.clip(first['reason'])}\". "
                        "The two cannot both stand, because the story's code comes from that merge request.\n\n"
                        "Nothing has been read or fetched yet. Which of your two words stands?",
                        [{"answer": "read", "token": "read",
                          "says": "the story starts from that merge request, and its line of the list is dropped"},
                         {"answer": "skip", "token": "skip",
                          "says": "it stays on the list, and the story starts without that merge request named; the "
                                  "implementation is then looked for another way"},
                         self.STOP_OPTION]),
                    {"read": "read", "skip": "skip"}, details=f"--mr: {mr}\nlist line: {first['as_written']}")
        self.s0_write_list(SE, applied, listed, data, dropped=answers.get("mr") == "read")

    def s0_list_applied(self, listed: Path) -> bool:
        """Does this story's exclusion record hold exactly the bytes of the list file now on disk? A record that
        cannot be read, or a list that cannot be opened, is not "applied"."""
        import source_exclusions as SE
        try:
            record = SE.read_record(self.task_root / "work")
            return bool(record) and record.get("list_sha256") == hashlib.sha256(listed.read_bytes()).hexdigest()
        except (SE.ExclusionRecordError, OSError):
            return False

    def s0_write_list(self, SE, applied: list, listed: str, data: bytes, dropped: bool = False) -> None:
        """Write the record once per list: the same bytes on a later entry are a no-op (the heads are not
        asked for again); other bytes replace an unrevoked record (S0 is the only writer and nothing has been
        read yet), and a record that holds a revocation is kept as it is, with a line saying so."""
        work = self.task_root / "work"
        try:
            record = SE.read_record(work)
        except SE.ExclusionRecordError as exc:
            raise Refusal(str(exc))
        digest = hashlib.sha256(data).hexdigest()
        if record is not None:
            if record.get("list_sha256") == digest:
                return
            if any(e.get("revoked_at") for e in record.get("exclusions") or []):
                print(f"S0: {listed} changed, but the record of this story holds a word you took back, so it is "
                      "kept as it is")
                return
            SE.record_path(work).unlink()
        for entry in applied:
            if entry["target"]["kind"] == "mr":
                self.s0_resolve_head(entry)
            elif entry["target"]["kind"] == "ref":
                self.s0_resolve_branch(entry)
        record = SE.write_record(self.task_root, applied, listed, data)
        for exclusion in record["exclusions"]:
            print(SE.console_line(exclusion))
        if not record["exclusions"] and not dropped:
            print("the list names no source")

    def s0_list_too_late(self) -> None:
        """`--skip-sources` on a story whose sources were already collected (C1): the question, unless the
        person already passed it. `go on` ignores the list; the way to leave a source out now is the source
        review, and the person is told so."""
        if self.s0_passed("source_list", ["inventory_exists"]):
            print("the list of sources not to read is ignored for this story")
            return
        inventory = self.task_root / "work" / "source-inventory.json"
        try:
            day = datetime.fromtimestamp(inventory.stat().st_mtime, timezone.utc).strftime("%Y-%m-%d")
        except OSError:
            day = "earlier"
        import source_exclusions as SE
        try:
            reviewed = SE.s1_completed(self.task_root)
        except Exception:               # a pipeline nobody can read is today's text: the review may still be ahead
            reviewed = False
        if reviewed:
            # The source review is over: promising it would be a door that is shut. What the person can still do
            # is say so in their own words at gate A, where a word of theirs is recorded; nothing already read
            # is un-read, and the record of the list is not written (there is none).
            way = ("the story goes on and the list is ignored. Nothing that was already read "
                   "is un-read; if you still want a source treated as left out, say so in your own words at gate "
                   "A (the review of the plan and the test cases), where your word is recorded and shown in "
                   "the report")
            details = ("Recording a person's word about a source to leave out (references/conductor.md; the gate decision itself is "
                       "never recorded by the conductor): "
                       + person_words.door(f"waiver.py --task {self.task} --remark --stage S0"))
        else:
            way = ("the story goes on and the list is ignored; at the source review you can name "
                   "the sources you do not want read, and they are not read after that")
            details = ""
        self.s0_stop(
            "source_list", "halt",
            self.closed_question(
                "s0.source_list.late",
                f"You started this run with a list of sources not to read, but the sources of {self.task} were already "
                f"collected on {day}, and a source that has been read cannot be left out before the run. So the list "
                "cannot apply to this story, and I have changed nothing.\n\nWhat I need from you is one of these:",
                [{"answer": "go on", "token": "go on", "says": way},
                 {"answer": "stop", "token": "stop",
                  "says": "stop here and start the story again from a fresh copy, where the list is read before anything is fetched",
                  "slots": {"what": "start the story again from a fresh copy"}}]),
            {"go on": "go on"}, details=details, problems=["inventory_exists"])

    def skip_sources_late(self) -> None:
        """`--skip-sources` on a command line of a story whose S0 is over, and the answer to the question
        that raises (C1 replaces edge 8's "printed only" for a story with an inventory). The list is never
        read here: only a story that STARTS reads it. No inventory yet: one printed line says so. An inventory:
        the question of `s0_list_too_late`, whose answer is read here because S0 is not entered again."""
        if not (self.task_root / "pipeline.json").is_file():
            return
        listed = getattr(self.flags, "skip_sources", None)
        answered = bool((self.state.get("pending_words") or {}).get("S0")) and self.state.get("s0_block") == "source_list"
        if not listed and not answered:
            return
        self.boundary = "S0:source_list"
        self._s0_passed = []
        self.s0_read_word()
        if listed:
            if (self.task_root / "work" / "source-inventory.json").is_file():
                self.s0_list_too_late()
            else:
                started = str((((self.pipeline().get("stages") or {}).get("S0") or {}).get("started")) or "")[:10]
                print(f"{self.task}: the list of sources not to read is read only when a story starts; this story "
                      f"started {started or 'earlier'}; at the source review, name the sources to leave out")
        elif self.s0_passed("source_list", ["inventory_exists"]):
            print("the list of sources not to read is ignored for this story")
        for block, words in self._s0_passed:
            # The pipeline is written already, so the pass joins its warnings through the one command that
            # appends one (it never records the same line twice): gate A shows it. A refused line is owed (FR-4, C1-7a).
            self.owe_row("stage_done.py", "--task", self.task, "--warn",
                         f"S0: {self.S0_PASS_NAMES.get(block, block)} passed by the person's word: "
                         f"\"{self.s0_quote(words)}\"", what="the warning about the pass you gave at the start of the story", stage="S0")

    def s0(self) -> None:
        self.boundary = "S0"
        self._s0_passed = []
        self.s0_note_launch()
        self.s0_keep_late_launch()
        self.s0_read_word()
        flags = self.s0_flags()
        # t-017 D3 (B-003): an experiment is decided at the launch and must survive the S0 stops -
        # the entry that follows an answer runs with no flags, and pipeline.json is written only at
        # the end of S0. `s0_note_launch` (just above) made `launch`; the flag is kept in it, next
        # to the sources the person may still correct.
        launch = self.state.setdefault("launch", {})
        no_trace = bool(getattr(self.flags, "no_trace", False) or launch.get("no_trace"))
        if no_trace and not launch.get("no_trace"):
            launch["no_trace"] = True
            self.save_state()
        # The same for the list of sources not to read (t-172 C5a): `s0_note_launch` keeps only the FIRST
        # entry's flags, and the entry that follows an answer runs with whatever its command line says.
        listed = getattr(self.flags, "skip_sources", None)
        if listed and launch.get("skip_sources") != listed:
            launch["skip_sources"] = listed
            self.save_state()
        # SS1-14 (M6): the launch key is checked HERE and nowhere earlier. INVARIANT of the position: every launch word (`--no-trace`,
        # the source list) is kept above, before the first stop of S0; and nothing is read or written for the story below this
        # line - only the driver's state, which holds the question.
        self.s0_key_form()
        given = [key for key in ("mr", "branch", "commit") if flags[key]]
        if len(given) > 1:
            names = {"mr": "a merge request", "branch": "a branch", "commit": "a commit"}
            self.s0_stop(
                "flags", "halt",
                self.closed_question(
                    "s0.flags",
                    f"You started the story for {self.task} with more than one place to take the code "
                    "from: " + ", ".join(f"{names[key]} (`{key}`)" for key in given) + ". I can work "
                    "from only one of them, and which one is the right one is your call - nothing here "
                    "tells them apart. Nothing has been read or written yet.\n\nWhich one should I keep?",
                    [{"answer": key, "token": key, "says": f"keep {names[key]} and drop the other "
                                                           f"{'one' if len(given) == 2 else 'ones'}"} for key in given]
                    + [self.STOP_OPTION]),
                {key: key for key in given}, details="\n".join(f"{key}: {flags[key]}" for key in given))
        # After the more-than-one-source check and before the first fetch (`ticket_get`): the person's word
        # about sources comes first, so nothing it names is ever fetched (B-231).
        self.s0_source_list(flags)
        # The story's ONE ticket (t-267, D-06): a snapshot already on disk, else the person's file or paste,
        # else the tracker by REST. No model is asked at any point of it.
        ticket_file = self.s0_local_file(flags["ticket_file"])       # a local story's text file is its ticket file (SS1-14)
        ticket, out, how, kept = self.s0_ticket(ticket_file)
        criteria_line = self.s0_criteria(ticket, how, None if kept else ticket_file)
        parent =str(ticket.get("parent") or "").split()[0] if ticket.get("parent") else None
        (self.task_root / "work" / "evidence").mkdir(parents=True, exist_ok=True)
        (self.task_root / "work" / "proposals").mkdir(parents=True, exist_ok=True)
        (self.task_root / "work" / "bug-drafts").mkdir(parents=True, exist_ok=True)
        if not kept:
            self.write_snapshot(out)
        # SS1-13: OUTSIDE `if not kept` - the entry after the person's answer finds the snapshot kept (the question is in `launch` by then).
        # After `work/ticket-references.json` is written (by the read above), before the stand and before any dispatch of the scout.
        self.s0_no_change_entry(flags)
        print("QA Factory v0 covers functional testing only. Non-functional checks (performance, security, "
              "accessibility, localization, compatibility, privacy) are out of scope in this version.")
        sel_args = ["--config", "qa-factory/config.json"] + (["--requested", flags["env"]] if flags["env"] else [])
        code, out = self.py("environment_selection.py", *sel_args)
        # a deliberate `raw`: no readable answer is the NAMED status `unknown` (never a pass), handled below like any other status
        selection = _read_answer(out) or {"status": "unknown", "raw": out}
        status = selection.get("status")
        # t-017 D2 (B-005): `environment_pending` is true until a stand has ANSWERED the check -
        # "no stand is confirmed as usable", whether there is no name at all or a name whose probe
        # failed. A stand is confirmed only by a probe that exits 0 (below) or by a word of the
        # person's (`stand_check`, before S5/S6); S0 itself never stops on a stand.
        environment, pending, warnings = None, True, []
        if status == "selected":
            environment = selection.get("environment_id")
        elif status == "question_required":
            if selection.get("no_environments_configured"):
                print("this project records no stand; /qa-factory:qa-onboarding adds one")
        elif self.s0_passed("stand"):
            # The person said to go on without a stand for now: the same state as a project that
            # records none - pending, and asked again before any test is run.
            pending = True
        else:
            names = [str(e.get("name")) for e in self.config.get("environments") or [] if e.get("name")]
            # G7: a stand named like a word of the factory's own (`stop`, `retry`, `go on`, `restart` ...) cannot be a door: one word
            # would have two readings and code never guesses which one was meant. It is left out of the doors and the options, and a
            # finding names it (owner: environment, the project's setting); the rest of the stands are offered as usual, and the question
            # itself names the left-out stand(s) and says they need renaming (FR-3, FR-41: never "no stand configured" when there are some).
            reserved = NM.reserved_tokens(NM.data(), self.s0_normalize)
            clash = [name for name in names if self.s0_normalize(name) in reserved]
            left_out = ""
            if clash:
                many = len(clash) > 1
                left_out = (f"{'These stands are' if many else 'This stand is'} named like an answer to this question, so "
                            f"{'they cannot' if many else 'it cannot'} be chosen by name: " + ", ".join(f"`{name}`" for name in clash)
                            + f". {'They need' if many else 'It needs'} renaming in the project's list of stands.")
                self.file_defect(self.boundary, "owner: environment — the stand(s) " + ", ".join(f"`{name}`" for name in clash)
                                 + " are named like an answer of the factory, so they cannot be chosen by name at S0; rename them in "
                                   "qa-factory/config.json")
                names = [name for name in names if name not in clash]
            doors = {self.s0_normalize(name): name for name in names}
            doors["go on"] = "go on"
            self.s0_stop(
                "stand", "halt",
                self.closed_question(
                    "s0.stand",
                    f"I could not settle which stand the tests of {self.task} should run on: "
                    + ("the stand named at launch could not be matched to one this project has configured. "
                       "The configured stands are " + ", ".join(f"`{name}`" for name in names) + "."
                       if names else ("none of the stands this project has configured can be chosen by name." if clash
                                      else "this project has no stand configured."))
                    + (" " + left_out if left_out else "")
                    + " Everything before the tests - the ticket, the requirements, the plan - can go on "
                    "without one, and I will ask again before any test is run.\n\nWhat I need from you:",
                    [{"answer": "stand", "token": name, "says": "run the tests of this story on that stand; it is checked when "
                                                               "the stage starts"} for name in names]
                    + [{"answer": "go on", "token": "go on", "says": "go on without a stand for now"}, self.STOP_OPTION]),
                doors, details=f"environment selection answered: {out.strip()[-600:]}")
        # t-2181 PC-2: the `sides.deliverable` question (the record is written in `s0_rest`). POSITION (PC-1b F2): after the stand is
        # selected, so a side known only from that stand's `environments.sides` row is asked; INVARIANT: the question still stands
        # BEFORE `pipeline.json` (written in `s0_rest`), and a side is never silently `deliverable: true`.
        self.s0_write_sides(environment)
        # An experiment hands the flag to BOTH calls: neither probes the tracker's write right
        # (readiness.py --no-trace), so S0 asks a tracker nothing it is not going to be sent (FR-36).
        trace = ["--no-trace"] if no_trace else []

        def readiness_then_rest() -> None:
            # G1 (C1-7b): `state/readiness.json` is read by gate_preflight, gate_brief, stage_guard, story_step and more; a stale or
            # absent file is an unwritten product. The refusal's retry runs THIS function (B-4 ii): a successful retry CONTINUES the
            # rest of S0 (the requirement check, the stand probe, pipeline.json, stage_done S0, initialize) and never returns to
            # the caller with the rest unrun. INVARIANT: S0 does not close over a readiness file the check did not write.
            try:
                self.py("readiness.py", "--write", "--probe-vcs", *trace, check=True,
                        expect="state/readiness.json rewritten")
            except Refusal as refusal:
                refusal.retry = readiness_then_rest
                raise
            self.s0_rest(environment, pending, warnings, parent, criteria_line, no_trace, trace)
        readiness_then_rest()

    def s0_rest(self, environment, pending, warnings: list, parent, criteria_line: str, no_trace: bool, trace: list) -> None:
        """The rest of S0 after the readiness file is written (split out of `s0` for C1-7b B-4 ii: the retry of G1 runs it).
        R3 / F6: the required capabilities are read from `readiness.py --require ... --json` - the record, never the exit code
        alone (FR-46, FR-59). A `missing` capability is the person's question (`s0_stop`); a record with none missing goes on; no
        record, or an exit outside {0, 1}, or an exit 1 that names no missing capability, is the FACTORY's own fault (a crash or a
        usage error) and a G refusal - never put to the person as "something required is missing", never a pass.
        ERROR DIRECTION: one question too many is allowed; a crash read as an answer is not."""
        import readiness as RD
        warnings = list(warnings)
        # A local story has no tracker to reach (SS1-14): the tracker route is not a capability it needs. The error direction:
        # a real key is never local (`is_local` is False on any doubt), so a tracker story still requires its route.
        wanted = ["test_repo", "vcs", "config_schema"] if self.s0_is_local() else ["ticket_adapter", "test_repo", "vcs", "config_schema"]
        code, out = self.py("readiness.py", "--require", ",".join(wanted), "--json", *trace)
        doc, after = json_record(out)
        caps = doc.get("capabilities") if isinstance(doc, dict) else None
        missing = ([name for name in wanted if isinstance((caps or {}).get(name), dict) and caps[name].get("status") == RD.MISSING]
                   if isinstance(caps, dict) else [])
        if code not in (0, 1) or not isinstance(caps, dict) or (code == 1 and not missing):
            raise gate_refusal("readiness.py", code, out, "the statuses of the capabilities the story needs (a readiness record)",
                               retry=lambda: self.s0_rest(environment, pending, warnings, parent, criteria_line, no_trace, trace))
        report = "\n".join(f"{name}: {caps[name].get('status')} - {caps[name].get('note')} (owner: {caps[name].get('owner')})"
                           for name in wanted if isinstance(caps.get(name), dict))
        out = after                                                       # the lines after the record: the WARN lines
        if missing and not self.s0_passed("readiness"):
            self.s0_stop(
                "readiness", "refusal",
                self.closed_question(
                    "s0.readiness",
                    f"Before starting {self.task} I checked that the project has what the story needs - "
                    "access to the ticket, the tests folder, version control and valid settings - and "
                    "something required is missing. The check's own report says which one; it is in the "
                    "file named below.\n\nWhat I need from you is one of these:",
                    [{"answer": "retry", "token": "retry", "says": "fix what the report names, and I check again",
                      "slots": {"what": "fix what the report names"}},
                     {"answer": "go on", "token": "go on",
                      "says": "start the story anyway; that is recorded as your decision, and the story carries a line saying so"},
                     self.STOP_OPTION]),
                {"retry": "retry", "go on": "go on"}, details=report + ("\n" + out if out else ""))
        warnings += [line.strip() for line in out.splitlines() if line.strip().startswith("WARN")]
        if environment:
            code, out = self.py("env_probe.py", "--env", environment, "--task", self.task)
            if code == 0:
                pending = False
            else:
                # A stand that does not answer is not a reason to stop the ticket, the requirements
                # or the plan: only what RUNS on it is blocked, and `stand_check` asks before that
                # (the old halt here cost a person's word for a story that had not touched the
                # stand yet). Any exit but 0 leaves it unconfirmed - a crashed probe confirms
                # nothing (FR-41). The name stays, so the check before the tests probes THIS stand.
                warnings.append(
                    f"stand {environment}: it did not answer the check ({self.probe_reason(out)}); "
                    "the story goes on and the stand is checked again before tests run")
                print(f"stand `{environment}` did not pass the check; the probe said:\n{out}")
            warnings += [line.strip() for line in out.splitlines()
                         if line.strip().startswith("data_cleanup") and "available" not in line]
        # Each block the person's word passed is a line of the story's own record, and gate A
        # shows the warnings: a pass is never a silent one (FR-4).
        warnings += [f"S0: {self.S0_PASS_NAMES.get(block, block)} passed by the person's word: "
                     f"\"{self.s0_quote(words)}\"" for block, words in self._s0_passed]
        # SS1-13: the person's `current code` answer (kept in `launch` by `s0_read_word`) is the story's `implementation_source` (a value
        # `stage_done.py` allows) and a line of its record: gate A shows the first five warnings, and this one goes right after the criteria line.
        source = (self.state.get("launch") or {}).get("implementation_source") or None
        if source:
            warnings.insert(0, "no change to ground on: tests are grounded on the current code, how it behaves now, not what is expected "
                               "(the person's word)")
        if criteria_line:
            # FIRST of the story's own lines (D-0050, t-957 F-6): gate A shows the first five warnings, and a ticket that carried no
            # criteria section is what the person should see before the probes' lines. Only the experiment line below goes before it.
            warnings.insert(0, criteria_line)
        env_word = ((environment + (" (not confirmed)" if pending else "")) if environment else "pending")
        if no_trace:
            # FIRST: gate A shows the first five warnings, and this is the one that says what the run is.
            warnings.insert(0, "this run is an experiment: nothing leaves the project — no merge request, "
                               "no tracker write; bugs stay as files")
        # t-2181 PC-1b (F5): the lines of a side answer the registry did not take are lines of the story's record, right after the
        # experiment line and the criteria line (gate A shows the first five warnings)
        for offset, line in enumerate((self.state.get("launch") or {}).get("sides_not_kept") or []):
            warnings.insert((1 if no_trace else 0) + (1 if criteria_line else 0) + offset, line)
        pipeline = {"ticket": self.task, "parent_feature": parent, "size": None, "environment": environment,
                    "environment_pending": pending, "implementation_source": source, "warnings": warnings,
                    "stages": {"S0": {"status": "done", "started": _now(), "finished": _now(), "role": None,
                                      "digest": f"preflight green, env={env_word}"}},
                    "gates": {}, "halts": []}
        if no_trace:
            pipeline["no_trace"] = True   # the record every reader of the experiment reads (closed_by_run)
        # t-2181 PC-2 (B2): the story's sides are built into the dict BEFORE the file is written - `pipeline.json` is born with its
        # sides, so S0 is never done without them; a refused value raises here and S0 replays whole (the writer's own functions, one writer)
        sides = self.s0_sides_sets(environment)
        if sides:
            import stage_done
            stage_done.apply_facts(pipeline, sides, [])
        _write_json(self.task_root / "pipeline.json", pipeline)
        # S0 is over: what it kept for the answers of its own stops goes. `launch` stays - it is
        # what the story was started with, as the person corrected it.
        # B-364 (R13): the person's word that the ticket is not needed outlives S0 - it is written to `launch` BEFORE
        # `s0_answers` is popped below, because the freshness check (`ticket_freshness_entry`) reads it there and
        # would otherwise look at a ticket the person said not to read.
        if (self.state.get("s0_answers") or {}).get("ticket_read") == "not needed":
            self.state.setdefault("launch", {})["ticket_not_needed"] = True
        for key in ("s0_block", "s0_ask", "s0_passes", "s0_answers", "s0_rest_failed"):
            self.state.pop(key, None)
        self.state["pending_words"].pop("S0", None)
        self.save_state()
        self.py("stage_done.py", "--task", self.task, "--stage", "S0", "--status", "done",
                "--digest", f"preflight green, env={env_word}", check=True)
        self.initialize()

    # --- stages ----------------------------------------------------------------------------
    def left_out_lines(self) -> list:
        """The scout's line about the person's list of sources not to read (B-231, FR-38: the requirement
        a check will judge - the manifest detector, the library fetch doors - is stated BEFORE the work).
        [] with no list. A list that exists and cannot be read is a refusal naming the file."""
        import source_exclusions as SE
        try:
            live = SE.live(self.task_root)
        except SE.ExclusionRecordError as exc:
            raise Refusal(str(exc))
        if not live:
            return []
        parts = []
        for exclusion in live:
            target = exclusion.get("target") or {}
            head = target.get("head_sha") if target.get("kind") == "mr" else target.get("sha")
            parts.append(f"{exclusion.get('as_written')} (\"{SE.clip(exclusion.get('reason') or '')}\""
                         + (f"; head commit {str(head)[:12]}" if head else "") + ")")
        return ["Left out by the person's word before the run - do not read, collect, cite as a source, "
                "precedent or existing coverage: " + "; ".join(parts) + ". A citation of one of them by its "
                "merge request number, link, branch or head commit is the same source; the exit gate checks "
                "your manifest and your receipts for it. If you think one is needed, say so in your handoff: "
                "the person decides at the source review."]

    S3_PLAN_LINE = ("Write work/test-plan.json as {\"rows\": [...]} with the first few rows, then append the "
                    "remaining rows with Edit a few at a time (each edit replaces the closing `]}`); the same "
                    "for test-plan.md. A single Write of the whole plan hits the output cap.")
    # GW1-41: the register fence reaches the strategist BEFORE the work (FR-38, AR-10); window 1 does not get it (the plan is
    # not written there). `skills/qa-story/phases/s3.md` carries the same sentence.
    S3_FENCE_LINE = ("Every id of the `## Register` table reaches a row: name it in `requirements` in work/test-plan.json and in the `R` column of "
                     "test-plan.md. A requirement waiting for a gate A question: `disposition: unverifiable`, `question_refs`, and `if_answered` with a patch "
                     "that sets a disposition; one that should not be checked: `disposition: skip` with the reason. `not_planned` holds only `K-n` and `B-n`.")
    # The fields window 1 fills (agents/qa-test-strategist.md «Two windows» names the same list; test W10 pins both against GT).
    S3_WINDOW1_FIELDS = ("rows[].label, .requirements, .risks[{id: K-n, hypothesis}], .question, .reason, .hunks (the all:<repo>:<file> "
                         "grouping); requirements[].state, .hunks, .where, .question; blast_radius.areas[].matters, .why, .text_says, "
                         ".regression, .add_tests; claims[]. A question is prose of at most 300 characters; write before/now values "
                         "in double quotes")
    # The claims text the role cannot read in the plugin (run_role tells it not to open plugin files): the quoted block of
    # skills/qa-story/phases/s3.md («Tell the role, verbatim»), its "> " markers stripped, the lines joined with a space. Test W10 pins the
    # two byte-equal (G1-11 fix round B1, FR-38 / AR-10 / AR-19).
    S3_CLAIMS_LINE = ("**A behaviour the register does not hold.** When a `behaviour_change` row of `work/grounding.yaml` shows behaviour no requirement of "
                      "`work/requirements-register.md` states, write it as one entry of `claims` in `work/grounding.yaml` (never in the register: its writer is the "
                      "requirements tester, and the code copies your claim into it after this window). Fields: `r` (the next free `R-<n>` — the register's ids "
                      "and every other claim are taken), `row` (that row's id), `requirement` (one verifiable statement), `impact` (the project's scale), `before` "
                      "and `before_ref` (what the code did before the change and where you read it — `diff:-<path>:<line>`, `base:<rev>:<path>:<line>` from the "
                      "base slice, `absent` for a new path, or `before: \"unknown\"` when nothing shows it — never a guess), `now` and `now_ref` (`diff:<path>:<line>`), "
                      "`differs` (yes / no / unknown), `question: raise`, and `ask` (`question`, `source_says`, `severity`, `owner_role`: what the person is asked). "
                      "Put every text value in double quotes. A claim is a statement about the code for the person to confirm, never the expected value of a test.")

    def s3_labelling_of(self, record) -> bool:
        """Is `record` window 1 of S3? The ONE driver reader: the controller's word through `controller.s3_window_of`, or the driver's own
        synthetic `{"window": "labelling"}` record that a caller with no controller record yet passes."""
        import controller as CT
        record = record if isinstance(record, dict) else {}
        return CT.s3_window_of(record) == "labelling" or record.get("window") == "labelling"

    def s3_strategist_lines(self, record) -> list:
        """The strategist's lines for the window `record` names (G1-11, FR-38: the fields reach the role BEFORE the work). `record` is the
        controller record, a packet, or `{"window": ...}` / `{"repair_cause": ...}` from a caller that has no record yet. ONE producer."""
        import grounding_table as GT
        import handoff as H
        base = f"qa-factory/artifacts/{self.task}/"
        record = record if isinstance(record, dict) else {}
        labelling = self.s3_labelling_of(record)
        ticket = record.get("repair_cause") == "ticket_changed"
        reach = ("work/grounding.yaml is the labelled table: every `K-n` and every area with `matters: yes` reaches a row "
                 "(`risk_source_refs: grounding:K-n` / `blast:B-n`) or a `not_planned` entry with `ref`.")
        # The claim fields (S3_CLAIMS_LINE) travel in the dispatch text: the role is told not to read the plugin's files (B1).
        labelling_lines = [f"Fill only: {self.S3_WINDOW1_FIELDS}.",
                           f"labels: {', '.join(H.allowed('grounding_labels'))}; requirement states: "
                           f"{', '.join(H.allowed('requirement_grounding_states'))}.",
                           "The base slice (`base_slice[]`), when present, shows the code before the change.",
                           self.S3_CLAIMS_LINE,
                           "End with the handoff form; the code checks the table (the check lists only fields you fill)."]
        if labelling:
            return [f"This is window 1 of S3 (labelling): write NO plan row; your work is {base}work/grounding.yaml."] + labelling_lines
        if ticket:             # ONE dispatch labels, then plans (B3): no line may tell it to write no plan
            return (["This dispatch labels work/grounding.yaml first (the fields below), then writes the plan over it."]
                    + labelling_lines + [self.S3_PLAN_LINE, self.S3_FENCE_LINE, reach])
        lines = [self.S3_PLAN_LINE, self.S3_FENCE_LINE]
        try:
            diff_world = GT.source_state(self.task_root)[0] == "diff"
        except Exception:
            diff_world = False          # an unreadable state adds no line: today's text alone
        if diff_world:
            lines.append(reach)
            lines += self.s3_counted_lines()
        return lines

    def s3_counted_lines(self) -> list:
        """What the code counted over the table, for the window-2 strategist (G2-2, FR-38): the requirement coverage (and the person's word
        for a stop, when there is one) and, per exit of the blast radius with a command, the line to put into `## Recommended regression`.
        Never raises: a measure that cannot be made adds no line (the stop question is the driver's, not the role's)."""
        import grounding_table as GT
        import planning_contract as PC
        lines: list = []
        try:
            cov = GT.coverage_of(self.task_root)
            if cov["road"] != "unknown":
                text = f"Code counted: {cov['implemented'] + cov['partial']} of {cov['n']} requirements are covered by the change ({cov['percent']}%)."
                if cov["road"] == "stop":
                    word = GT.stop_word(self.pipeline(), GT.COVERAGE_STOP_BLOCK, GT.coverage_digest(self.task_root, cov))
                    text += " The person decided to go on." if word is not None else " No person's word stands for this yet."
                lines.append(text)
            doc, _problem = PC.read_grounding(self.task_root)
            for entry in PC.regression_from_blast(doc) if doc is not None else []:
                if entry.get("command"):
                    tokens = ", ".join(f"blast:{a.strip()}" for a in str(entry["area"]).split(","))   # a merged area "B-1, B-3": ONE token per area (BLAST_TOKEN reads one)
                    lines.append(f"{entry['area']} {entry['command']} - name these tests as items of `## Recommended regression` "
                                 f"(the command goes on its `Command:` line), each item signed with {tokens}.")
        except Exception:
            return lines
        return lines

    def role_lines(self, stage: str, role: str, record=None) -> list:
        pipeline = self.pipeline()
        env = pipeline.get("environment") or ("pending" if pipeline.get("environment_pending") else "none")
        if pipeline.get("environment") and pipeline.get("environment_pending"):
            # A name that no check has answered for is not "the environment" (FR-41): a role that
            # reads `Environment: local` starts on it as if it were known to be up.
            env = f"{env} (not confirmed yet)"
        base = f"qa-factory/artifacts/{self.task}/"
        if role == "qa-scout":
            # An `--mr` the person gave up at S0 (the list of sources not to read named the same request and
            # they chose to skip it) is still on a later command line: the scout is not told it.
            # The launch is read from the KEPT launch too (F8): a process started with `--answer` carries no `--mr`, and the scout
            # must not be told "none" for a story that was launched with one. `launch_flags` is pure - no state is written here.
            launch = self.launch_flags()
            dropped = (self.state.get("launch") or {}).get("mr_dropped")
            mr = launch["mr"] if launch["mr"] and launch["mr"] != dropped else None
            flags = " ".join(f for f in [f"--mr {mr}" if mr else "", f"--branch {launch['branch']}" if launch["branch"] else "",
                                         f"--commit {launch['commit']}" if launch["commit"] else "",
                                         "--ungrounded" if launch["ungrounded"] else ""] if f) or "none"
            repos = ", ".join(f"{r.get('name')}={r.get('path')}" for r in self.config.get("code_repos") or [])
            repos = (repos + ", " if repos else "") + f"tests={self.config.get('tests_root') or '.'}"
            source = ("local text, key made by the factory; no tracker holds it: "
                      f"collect {self.task} --relation task records it, no network; do not peek it" if self.s0_is_local()
                      else '--ticket-file ' + launch['ticket_file'] if launch['ticket_file'] else 'the configured ticket adapter')
            # SS1-15: a tracker the factory holds no client for is read by the route onboarding recorded (`reads_by_role`)
            import ticket_adapter
            from source_inventory import tracker_route_lines
            by_role = ticket_adapter.reads_by_role(self.config)
            if by_role and source == 'the configured ticket adapter':
                source = "the project's tracker, by the route below; the task's text is the snapshot S0 made"
            # SS1-13: the person's `current code` answer reaches the scout BEFORE its work (FR-38): without the line step 4 of the role halts.
            grounding = ([f"implementation_source: {launch['implementation_source']}"] if launch.get("implementation_source") else [])
            # OH3-39: the places the project keeps requirements (config.json `requirements_sources`) reach the scout before its work (FR-38)
            from source_inventory import requirement_source_lines
            return ([f"Launch flags: {flags}"] + grounding + [f"Environment: {env}", f"Ticket source: {source}"]
                    + tracker_route_lines(self.config, by_role=by_role)
                    + [f"Repositories: {repos}", f"pipeline.json: {base}pipeline.json"]
                    + requirement_source_lines(self.config, local=self.s0_is_local(), by_role=by_role) + self.left_out_lines())
        if role == "qa-requirements-tester":
            return [f"implementation_source: {pipeline.get('implementation_source') or 'unknown'}",
                    f"context-bundle.json (read first): {base}work/context-bundle.json",
                    f"context-manifest.json (only referenced detail): {base}work/context-manifest.json",
                    f"impl-diff.txt: {base}work/impl-diff.txt (absent when ungrounded or current-code)"]
        if role == "qa-test-strategist":
            return self.s3_strategist_lines(record) if stage == "S3" else [self.S3_PLAN_LINE]
        if role == "qa-runner":
            return [f"Environment: {env}"]
        if role == "qa-failure-analyst":
            import controller as CT
            analyst = [f"run-report.json: {base}work/run-report.json · automation-manifest.json: {base}work/automation-manifest.json · evidence: {base}work/evidence/",
                       f"test-plan.md (each row's oracle): {base}test-plan.md", f"Environment: {env}"]
            # P2 M3: an investigation dispatch (a live gate call or a controller RECORD on a restart road) also gets its targets, caps and form note
            return analyst + self.investigation_lines() if CT.s7_part_of(record or {}) == "investigation" else analyst
        if role == "qa-doc-scribe":
            ext = self.config.get("external_writes") or {}
            channels = (f"Bugs channel: {ext.get('bugs', 'markdown')} · Cases channel: {ext.get('cases', 'markdown')}"
                        if not self.no_trace() else
                        "Bugs channel: markdown (closed for this run: experiment) · "
                        "Cases channel: markdown (closed for this run: experiment)")
            return [f"ledger.json, ledger.md, test-plan.md, automation-manifest.json, run-report.json, triage.json, bug-drafts/: under {base}work/ (test-plan.md at {base}test-plan.md)",
                    channels]
        if role == "qa-retro-analyst":
            feedback = self.state.get("retro_feedback") or "declined"
            return ["THE NUMBERS ARE ALREADY COMPUTED: work/retro-numbers.md (rendered) and work/retro-numbers.json (facts). Do not open journal.jsonl or state/cost/.",
                    f"pipeline.json, test-plan.md, context-manifest.json: {base}pipeline.json, {base}test-plan.md, {base}work/context-manifest.json",
                    f"Human feedback, verbatim: \"{feedback}\"",
                    "Do NOT move the artifact folder and do NOT set pipeline.json archived."]
        return []

    def stage_simple(self, stage: str) -> None:
        role = self.stages()[stage]["roles"][0]
        # S-c (t-2181 PC-9b): S1 of a story whose side carries a `reference` has ONE more dispatch after the scout, the runner's walk of the
        # old version (`optional_dispatches` of references/stages.json, read through `stage_guard.optional_rows`, the ONE reader; purpose
        # `reference_walk`). A story with no reference reads no stand name and takes the line below, byte for byte as before.
        if stage != "S1":
            return self.run_role(stage, role, extra=self.role_lines(stage, role))
        window = self.s1_window_owed(stage)
        if not window:
            return self.run_role(stage, role, extra=self.role_lines(stage, role))
        import controller as CT
        import exit_gate
        try:
            mine = {k: v for k, v in (self.controller_state().get("dispatches") or {}).items()
                    if isinstance(v, dict) and v.get("role") == role and v.get("status") not in CT.DISCOUNTED}
            scout = exit_gate.stage_dispatch(mine, stage)
        except Exception as exc:  # noqa: BLE001 - unreadable state: the scout runs again (the dearer direction), said once (N4)
            print(f"S1: reference window: the scout's dispatch could not be read ({type(exc).__name__}); the scout runs again")
            scout = None
        if not (scout and scout.get("status") == "accepted"):
            # the scout does NOT close S1 here: the runner's window is the stage's last dispatch (complete=True below)
            self.run_role(stage, role, extra=self.role_lines(stage, role), complete=False)
        self.s1_reference_window(stage, window)

    def s1_window_owed(self, stage: str, role: str | None = None):
        """`{"row", "references"}` when the S1 reference window is owed - the stage declares an optional `reference_walk` dispatch
        (`stage_guard.optional_rows`) AND the story's sides carry a reference stand (`stand_identity.reference_stands`) - else None.
        The ONE test of "has this story a window", read by `stage_simple` (the first make of S1), by `rework`, by the relaunch road
        of a rework of the S1 scout and by `completion_for` (t-2277 batch 2b D): a story with no reference gets None and every road stays
        as it was. `role` (N1, critic t-2548): when given, the window is owed only for the stage's AUTHOR (its first role, the scout) -
        any other role of the stage gets None - so the one test of "the scout" lives here, not at each caller."""
        if stage != "S1":
            return None
        if role is not None and role != (self.stages().get(stage, {}).get("roles") or [""])[0]:
            return None
        import controller as CT
        import stage_guard as SG
        rows = [r for r in SG.optional_rows(self.stages()[stage]) if r["purpose"] == CT.REFERENCE_WALK]
        if not rows:
            return None
        import stand_identity as SI
        references = SI.reference_stands(self.project, self.task)
        return {"row": rows[0], "references": references} if references else None

    def s1_reference_window(self, stage: str, window: dict) -> None:
        """The runner's walk of the OLD version (the S1 reference window), after the scout's run: dispatch, survey walk on the reference
        stand, the runner's `put` (with `--replace` over an old snapshot). The closing dispatch of S1 (`complete=True`). Whether the
        scout's dispatch was ACCEPTED is checked by `stage_simple` (it runs the scout only when no accepted one exists); `rework` and
        `_act_relaunch` call this right after `run_role` returned, whatever the scout's status is (N2, critic t-2548): this method itself
        checks no status."""
        import controller as CT
        import stage_guard as SG
        import event_store
        row, references = window["row"], window["references"]
        runner, purpose = row["role"], row["purpose"]
        # one reference per story (the snapshot has one `reference_env`): the first by name is walked, every other is NAMED as a gap (F6, AR-28)
        reference = sorted(references)[0]
        unwalked = [f"the reference `{stand}` of the `{references[stand]}` side was not walked: one reference per story"
                    for stand in sorted(references)[1:]]
        for line in unwalked:
            print(f"S1: reference window: {line}")
        controller = CT.Controller(self.task_root, wait_seconds=event_store.LIFECYCLE_WAIT_SECONDS)
        state = controller.state()
        number = 1 + len([d for d in (state.get("dispatches") or {}).values() if isinstance(d, dict) and d.get("stage") == stage and d.get("role") == runner])
        dispatch_id = f"{stage}-{runner}-{number}"
        try:
            # the purpose goes into `prepare` too: the controller admits a qa-runner packet with no `execution_kind` only by the purpose of an
            # optional row of the stage (`controller.runner_kind_required`, B1) - the window runs no half of a plan
            packet = controller.prepare({"stage": stage, "role": runner, "id": dispatch_id, "scope": [], "purpose": purpose})
            controller.apply("dispatch", dict(packet["dispatch_request"], purpose=purpose))
        except Exception as exc:
            raise Refusal(f"{stage} reference window dispatch refused: {type(exc).__name__}: {exc}")
        # the walk session of the OLD version: `survey` place on the reference stand, opened after the dispatch is registered and before the
        # role starts (the record names the stand; `reference_snapshot.py put` takes the walk by code from the newest `reference_walk` dispatch).
        # The actors are `first_look.walk_actors` - the ONE reader of the account list (F7, AR-13): accounts first, `guest` in a slot left over
        import first_look as FL
        import walk_session as WS
        who = FL.walk_actors(self.project, self.config, reference, WS.data()["max_actors"])
        actors = who["actors"]
        code, text = self.py("walk_session.py", "open", "--task-root", str(self.task_root), "--walk", dispatch_id, "--place", "survey",
                             "--env", reference, "--items", "free", "--actor", actors[0], *(["--actor2", actors[1]] if len(actors) > 1 else []))
        out_rel = (SG.optional_outputs(row) or ("work/reference-snapshot.yaml",))[0]
        replace = (self.task_root / out_rel).is_file()      # the story is made again over an old snapshot: `put` replaces it
        put = (f"python \"{self.scripts}/reference_snapshot.py\" put --task-root {self.task_root} --reference {reference} --items-file <items.yaml>"
               + (" --replace" if replace else ""))
        shape = ("The file is block YAML: `items:` - one mapping per behaviour: id (plain id), area, user_path, observed, evidence (a list of "
                 "{path, quote} from a capture of THIS walk) and/or old_test (<file>:<line>), locators_portable (yes | no | unknown) - and a "
                 "`gaps:` list of lines. The snapshot contract - every key, the evidence form and what `put` refuses - is "
                 f"`{self.plugin / 'references' / 'artifact-contract-reference.md'}`.")
        extra_gaps = (" Put these lines in `gaps:`: " + "; ".join(f"\"{g}\"" for g in unwalked) + ".") if unwalked else ""
        if code:
            why = ((_read_answer(text) or {}).get("reason") or (text.splitlines() or [f"exit {code}"])[-1]).strip()[:300]
            gaps = [f"the old version at {reference} could not be reached: {why}", *unwalked]
            try:
                import reference_snapshot as RS
                RS.put_gap(self.task_root, reference, gaps, replace=replace)       # F5: the line is the driver's own, so the driver writes it
                written = True
            except Exception as exc:  # noqa: BLE001 - the runner writes it as before (P1)
                print(f"S1: reference window: the gap-only snapshot was not written by the driver ({type(exc).__name__}); the runner writes it")
                written = False
            if written:
                extra = [f"Reference window: the old version at `{reference}` could not be reached ({why}). The driver has already written "
                         f"{out_rel} with that one gap line: walk nothing, write nothing, ask no one - hand over your form (S1 closes with this dispatch)."]
            else:
                extra = [f"Reference window: the old version at `{reference}` could not be reached: {why}. Walk nothing and ask no one: write the "
                         f"snapshot with `items: []` and the gap line \"the old version at {reference} could not be reached: {why}\": `{put}`." + extra_gaps]
        else:
            who_line = (f"You walk as {', '.join(actors)}" + (f" (accounts not opened, the walk holds {len(actors)}: {', '.join(who['left'])})" if who["left"] else "")
                        + ("; as `guest` you are not signed in" if "guest" in actors else "") + ". ")
            extra = [f"Reference window: walk the OLD version at `{reference}` in walk session `{dispatch_id}` (place survey; items are ids you choose, "
                     "plain letters, digits, - and _), the behaviours the story's requirements say must stay as they are. " + who_line
                     + "Capture with the walk commands of your brief. Then write what you saw ONCE: `" + put + "`. " + shape + extra_gaps]

        def record_then_role() -> None:
            self.record_running(stage, runner, dispatch_id, retry=record_then_role)
            self.run_role(stage, runner, complete=True, extra=extra, purpose=purpose,
                          rework={"id": dispatch_id, "scope": [], "reason": "reference window"},
                          after=(None if code else (lambda d, r: self.py("walk_session.py", "close", "--task-root", str(self.task_root), "--walk", dispatch_id))))
        record_then_role()

    # --- S3 in two windows (G1-11, grounding/1) --------------------------------------------------------------------------------
    def stage_S3(self) -> None:
        """S3 as two strategist dispatches: window 1 (`purpose: s3_labelling`) labels work/grounding.yaml and writes no plan, window 2
        writes the plan. Window 2 is NOT chained here: after window 1's acceptance the loop asks `where` again, the controller answers
        `prepare_stage S3`, and this method finds `between` - one road for the live run and for a restart (I3). Off the diff world
        there is nothing to label: one window as before, after the preparation wrote the null outcome."""
        import controller as CT
        import grounding_table as GT
        self.first_look_step()       # t-2277 FL-5: before `s3_prepare` and window 1 of THIS pass; no strategist dispatch is registered ahead of it
        role = self.stages()["S3"]["roles"][0]
        critic = bool(self.stage_acceptor("S3"))
        if critic and self.s3_author_done():
            return self.stage_critic_route("S3", role)       # X2-7: the author's exit window is accepted; the stage critic is next
        if GT.source_state(self.task_root)[0] != "diff":
            self.s3_prepare()
            self.run_role("S3", role, extra=self.role_lines("S3", role), complete=self.s3_window_completion({"window": "exit"}))
            if critic:
                self.stage_critic_route("S3", role)
            return
        if self.s3_window() == "between":
            back = self.s3_fresh_for_window2()          # step 8: "" or why window 1 runs again (R5 was prepared there)
            if not back:
                self.s3_between_windows()
                self.run_role("S3", role, extra=self.role_lines("S3", role, {"window": "exit"}),
                              complete=self.s3_window_completion({"window": "exit"}))
                if critic:
                    self.stage_critic_route("S3", role)       # never after window 1 (labelling): a plan nobody wrote is not judged
                return
            print(f"S3: window 1 runs again - {back}")
        else:
            self.s3_prepare()                           # BEFORE `start`: the table exists before window 1 writes a byte
        self.run_role("S3", role, purpose=CT.S3_LABELLING, extra=self.role_lines("S3", role, {"window": "labelling"}),
                      complete=self.s3_window_completion({"window": "labelling"}))

    def first_look_step(self) -> None:
        """The first look at the new version on the stand, before the plan (t-2277 FL-5; `first_look.py` is the one reader and writer of the
        record, `walk_session.py` the walk, AR-14/AR-15). POSITION: the first call of `stage_S3`, before `s3_prepare` and window 1. INVARIANT:
        no strategist dispatch of this pass is registered before the first look is decided - walked, skipped with a named reason, or answered.
        1. `first_look.due` false WITH a reason -> `put --null <reason>` (a specific null already written for these heads is kept, never
           replaced by the generic `walk_not_opened`), one line, the plan as today; false with none -> one line "already on these heads".
           2. True -> `_first_look_walk`: the survey walk is opened for the register's requirements (`--env` of the story's stand; the
           actors are `first_look.walk_actors`: accounts first, `guest` in a slot left over, J-18), THEN the optional dispatch of
           stages.json S3 (`qa-runner`, purpose `first_look`) is registered and run (a failed open leaves no registered dispatch for the
           controller to close): an open that fails ends the attempt, removes the walk record and writes the null reason, and the plan is
           made as today (FR-57, no question). 3. Accepted = the dispatch closed by the controller AND `first_look.read` gives a fresh,
           non-empty record of THIS walk (`_first_look_accepted`); not accepted -> the attempt keeps what it is (`written` stays; one
           that is still `walking` ends `nothing_written`), a gap line, and S3 AT ONCE: no question over unaccepted work, the dispatch is
           not repeated on these heads (`due`). 4. `_first_look_question`: an ACCEPTED record whose `first_look.share` is below the floor,
           with something counted, no `continue` for these heads and register and no answer yet to this walk -> `first_look.dead`.
           Never raises for a doubt (P1): what code cannot establish is one printed line and the plan as today."""
        import first_look as FL
        T = self.task_root
        say = lambda text: print(f"S3: first look: {text}")      # noqa: E731
        try:
            pipeline = self.pipeline()
            due, reason, why = FL.due(T, pipeline, self.config)
        except Exception as exc:  # noqa: BLE001 - P1
            say(f"the question whether to walk could not be asked ({type(exc).__name__}); the plan is made as before")
            return
        if not due:
            if reason:
                self._first_look_null(FL, reason, why)
            else:
                say(f"on these heads there was already one: {FL.read_attempt(T).get('outcome') or 'recorded'}")
        elif not self._first_look_walk(FL, pipeline):
            return              # not walked or not accepted: S3 at once (B3), nothing is asked over work nobody accepted
        self._first_look_question(FL)

    def _first_look_null(self, FL, reason: str, why: str) -> None:
        """`put --null <reason>`, one line. A specific null of these heads (`no_reachable_surface`, `profile_not_chosen`) is not overwritten by
        the generic `walk_not_opened` a later entry reaches through `due` (t-2277 FL-5 m3, AR-27): the reason the person reads is the
        first one found."""
        T = self.task_root
        if reason == "walk_not_opened":
            held = FL.read(T)
            if held["null"] and held["null"] != reason and not held["stale"]:
                print(f"S3: first look: none ({held['null'].replace('_', ' ')}): kept; {why}")
                return
        # remains: the exit code is read on the next lines - a record that was not written is printed with the reason, and the plan is made as before (P1)
        code, out = self.py("first_look.py", "put", "--task-root", str(T), "--null", reason)
        print(f"S3: first look: none ({reason.replace('_', ' ')}): {why}"
              + (f"; the record of that was not written ({(str(out).strip().splitlines() or ['no output'])[-1][:200]})" if code else ""))

    def _first_look_accepted(self, FL) -> bool:
        """THE reader of "the first look of these heads was accepted" (AR-13): the attempt says `written`, the controller's dispatch of that
        attempt is `accepted`, and `first_look.read` gives a current, non-null, non-empty record of THAT walk. A record `put` wrote under a
        dispatch that was not accepted is not accepted work: it asks nothing and counts for nothing. Anything unreadable: False."""
        try:
            attempt = FL.read_attempt(self.task_root)
            got = FL.read(self.task_root)
            state = (self.controller_state().get("dispatches") or {}).get(attempt.get("dispatch")) or {}
            return bool(attempt.get("outcome") == "written" and state.get("status") == "accepted" and not got["problem"] and not got["null"]
                        and not got["stale"] and got["rows"] and got["walk"] == attempt.get("dispatch"))
        except Exception:  # noqa: BLE001 - an unreadable state is not an acceptance (AR-28)
            return False

    def _first_look_give_up(self, FL, dispatch: str, null: str, said: str, *, refused: bool) -> None:
        """The walk did not open (FR-57): the dead walk record goes and the null reason is written. The attempt ends `open_failed` (the next
        entry may try once more) - except for a REFUSED cause (`walk_session.REFUSED_CAUSES`: the project has no surface), which cannot get
        better by trying again and ends `nothing_written` (settled: `due` repeats nothing, m3)."""
        T = self.task_root
        # remains: the attempt's end is bookkeeping of a walk that is given up (P1): the plan is made as before whether or not it was written
        self.py("first_look.py", "end", "--task-root", str(T), "--outcome", "nothing_written" if refused else "open_failed")
        try:
            (T / "state" / "walks" / f"{dispatch}.json").unlink()
        except OSError:
            pass
        # remains: the null record only explains the missing look in the next line (P1): the plan is made as before whether or not it was written
        self.py("first_look.py", "put", "--task-root", str(T), "--null", null)
        print(f"S3: first look: none ({null.replace('_', ' ')}): the walk was not opened ({said}); the plan is made as before")

    def _first_look_walk(self, FL, pipeline: dict) -> bool:
        """Steps 2-3 of `first_look_step`: open the walk, register and run the optional dispatch, accept or not. True = ACCEPTED."""
        import controller as CT
        import grounding_table as GT
        import stage_guard as SG
        import walk_session as WS
        T = self.task_root
        say = lambda text: print(f"S3: first look: {text}")      # noqa: E731
        last = lambda out: (str(out).strip().splitlines() or ["no output"])[-1][:200]      # noqa: E731
        model = SG.stage_model()
        stage = next((st for st in model.get("stages") or [] if st.get("id") == "S3"), {})
        row = next((r for r in SG.optional_rows(stage) if r["purpose"] == CT.FIRST_LOOK), None)
        if row is None:     # the one source of the dispatch's role and purpose is stages.json; without its row there is nothing to register
            say("stages.json S3 names no optional dispatch of purpose first_look (gap); the plan is made as before")
            return False
        role, purpose = row["role"], row["purpose"]
        stand = str(pipeline.get("environment") or "")
        items = sorted(GT.register_info(T).ids, key=lambda r: (len(r), r))
        known = (self.controller_state().get("dispatches") or {})
        number = 1
        while f"S3-{role}-{number}" in known:
            number += 1
        dispatch = f"S3-{role}-{number}"
        who = FL.walk_actors(self.project, self.config, stand, WS.data()["max_actors"])
        actors = who["actors"]
        code, out = self.py("first_look.py", "begin", "--task-root", str(T), "--dispatch", dispatch, "--env", stand)
        if code:
            self._first_look_give_up(FL, dispatch, "walk_not_opened", f"first_look.py begin: {last(out)}", refused=False)
            return False
        code, out = self.py("walk_session.py", "open", "--task-root", str(T), "--walk", dispatch, "--place", "survey", "--env", stand,
                            "--items", ",".join(items), "--actor", actors[0], *(["--actor2", actors[1]] if len(actors) > 1 else []))
        if code:
            cause = str((_read_answer(out) or {}).get("cause") or "")
            self._first_look_give_up(FL, dispatch, cause if cause in (FL.data().get("null_reasons") or []) else "walk_not_opened", last(out),
                                     refused=cause in WS.REFUSED_CAUSES)
            return False

        def close_walk(done: str, _result=None) -> None:
            # remains: the exit code is read on the next line and printed as a note; the walk's server ends by itself
            code2, out2 = self.py("walk_session.py", "close", "--task-root", str(T), "--walk", done)
            if code2:
                print(f"note: walk_session.py close exit {code2}: {last(out2)}; the server ends by itself")
        try:
            from controller import Controller
            import event_store
            controller = Controller(T, wait_seconds=event_store.LIFECYCLE_WAIT_SECONDS)
            packet = controller.prepare({"stage": "S3", "role": role, "id": dispatch, "purpose": purpose})
            controller.apply("dispatch", dict(packet["dispatch_request"], purpose=purpose))
        except Exception as exc:  # noqa: BLE001 - nothing was registered or the registration failed: the walk is not left open
            close_walk(dispatch)
            self._first_look_give_up(FL, dispatch, "walk_not_opened",
                                     f"the dispatch was not registered: {type(exc).__name__}: {' '.join(str(exc).split())[:160]}", refused=False)
            return False
        self.boundary = f"S3:{dispatch}"
        if who["problem"]:
            say(f"the record of project knowledge could not be read fully ({who['problem'][:120]}); the accounts it has are used")
        print(f"S3: first look: {dispatch} walks {len(items)} requirement(s) on `{stand}` as {', '.join(actors)}"
              + (f"; accounts not opened (the walk holds {len(actors)}): {', '.join(who['left'])}" if who["left"] else ""))

        def launch() -> None:
            self.record_running("S3", role, dispatch, retry=launch)
            self.run_role("S3", role, scope=[], complete=False, after=close_walk,
                          extra=self.role_lines("S3", role),
                          rework={"id": dispatch, "scope": [], "reason": "first look",
                                  "line": f"First look: survey walk {dispatch} on {stand} is open; your brief has the commands and the form."})
        launch()
        if self._first_look_accepted(FL):
            return True
        if FL.read_attempt(T).get("outcome") == "walking":      # the role wrote nothing; a record `put` wrote keeps its `written` (B3)
            # remains: bookkeeping of an attempt that wrote nothing (P1): the line below says the plan is made without the look
            self.py("first_look.py", "end", "--task-root", str(T), "--outcome", "nothing_written")
        say(f"{dispatch} was not accepted with a record of this walk (gap); the plan is made without it and the look is not repeated on these heads")
        return False

    def _first_look_question(self, FL) -> None:
        """Step 4 of `first_look_step`: `first_look.dead` over an ACCEPTED record below the floor, not yet continued and not yet answered."""
        say = lambda text: print(f"S3: first look: {text}")      # noqa: E731
        T = self.task_root
        try:
            if not self._first_look_accepted(FL) or FL.asked(T):
                return
            share = FL.share(T, self.config)
            if not share["below"] or FL.continued(T, self.pipeline()):
                return
            record = FL.read(T)
            import contract
            sides = {n: s["reality"] for n, s in contract.story_sides(self.pipeline()).items() if s["reality"] != "real"}
        except Exception as exc:  # noqa: BLE001 - P1: an unreadable look asks nothing
            say(f"the share could not be read ({type(exc).__name__}); the plan is made as before")
            return
        import interim_packet
        lines = [f"Before planning I looked at the stand `{record.get('stand') or self.pipeline().get('environment')}` once. It showed "
                 f"{share['reachable']} of {share['counted']} requirements ({share['share']}%), under the {share['floor']}% from which I go on "
                 f"by myself. Every requirement, by what the stand answered: {interim_packet.status_counts(record['rows'])}."]
        stuck = [r for r in record["rows"] if r.get("status") not in (FL.data().get("reachable") or [])]
        if stuck:
            shown = [f"- {r.get('req')}: {' '.join(str(r.get('why') or 'no reason given').split())[:140]}" for r in stuck[:self.GROUNDING_NAMED_MAX]]
            if len(stuck) > self.GROUNDING_NAMED_MAX:
                shown.append(f"- and {len(stuck) - self.GROUNDING_NAMED_MAX} more")
            lines.append("The stand did not show:\n" + "\n".join(shown))
        if sides:
            lines.append("Parts of the product that are not the real thing yet: " + ", ".join(f"{n} ({w})" for n, w in sides.items()) + ".")
        if record.get("stand_build") == "not_established":
            lines.append("Nobody has confirmed which build is on the stand, so the feature may be missing only because the build there is old.")
        lines.append("What I need from you is one of these:")
        options = [{"answer": "continue", "token": "continue",
                    "says": "write the plan anyway; the plan reads what the stand showed as an observation, not as the truth"},
                   {"answer": "stop", "token": "stop",
                    "says": "stop the story here and wait until the build you want checked is on the stand; nothing runs. You can also tell me "
                            "in your own words what to do instead"}]
        # remains: a closed question over the story's own state, not a state without a move: every answer has an executor (`_first_look_answer`)
        raise Person("first_look_dead", self.closed_question("first_look.dead", "\n\n".join(lines), options),
                     "S3", answer_note="Write `continue`, `stop`, or your own words (the conductor reads them).")

    def s3_author_done(self) -> bool:
        """True when the newest S3 strategist dispatch that counts is ACCEPTED and is not window 1 (labelling): the plan is written and the
        stage critic's route is next (a restart of the process, or the author's repair round). Unreadable state: False."""
        import exit_gate
        try:
            mine = exit_gate.s3_strategist_records(self.controller_state().get("dispatches") or {})
        except Exception:
            return False
        newest = exit_gate.stage_dispatch(mine, "S3")
        return bool(newest) and newest.get("status") == "accepted" and not self.s3_labelling_of(newest)

    def s3_window(self) -> str:
        """`"between"` when the newest S3 strategist dispatch that counts is an ACCEPTED window 1, else `"w1"`. The word is read through
        `controller.s3_window_of` (never the top of the record) and the status only; the table is not consulted (I4). A set-aside dispatch
        (the controller's DISCOUNTED) does not count; an unreadable controller state is `w1`. `old` never appears at entry."""
        import controller as CT
        import exit_gate
        try:
            mine = exit_gate.s3_strategist_records(self.controller_state().get("dispatches") or {})
        except Exception:
            return "w1"
        newest = exit_gate.stage_dispatch(mine, "S3")
        if newest and CT.s3_window_of(newest) == "labelling" and newest.get("status") == "accepted":
            return "between"
        return "w1"

    def s3_fresh_for_window2(self) -> str:
        """Step 8: `""` when window 2 may run over the table, else the reason window 1 runs again. `GT.check` in-process; only R0, R1, R2
        and R5 send back (R3, R4, R8 are the exit's), minus the findings a person's recorded word passed (`waiver.split_overridden`).
        R5 (the register or diff moved) and R0 owned by the driver prepare the table first; a finding owned by the role goes back to
        window 1. A finding owned by the driver or the conductor that the preparation does not cure (R1/R2 of the diff or the register,
        R0 of a table the conductor's door must rewrite), or a check that raises, is a Refusal - never window 2, never window 1 again
        over it (FR-59, AR-25)."""
        import grounding_table as GT
        try:
            findings = GT.check(self.task_root)
        except Exception as exc:
            raise Refusal(f"S3 step 8: the grounding check could not run ({type(exc).__name__}: {exc}). Window 2 is not started over a "
                          "table that was not checked. Way on: the conductor (P22).", dispatch="")
        pipeline = self.pipeline()
        standing = [f for f in findings if f.rule in ("R0", "R1", "R2", "R5")
                    and not waiver.split_overridden([f.text], pipeline, "S3")[1]]
        if not standing:
            return ""
        # A finding window 1 cannot cure is a Refusal, raised BEFORE any window-1 dispatch is registered (nothing is paid): window 1's exit
        # keeps only the role's findings, so it would accept, this step would send it back, and the loop has no door (B2, AR-17 / AR-25).
        # What the prepare road cures (R5; R0 owned by the driver) and what the role fills (any `role` finding) is not in this class.
        stuck = [f for f in standing if f.who != "role" and not (f.rule == "R5" or (f.rule == "R0" and f.who == "driver"))]
        if stuck:
            raise Refusal(f"S3 step 8: {stuck[0].text} Window 1 cannot cure this ({stuck[0].rule}, owner: {stuck[0].who}), so window 2 is "
                          "not started over the table and window 1 is not run again. Way on: the conductor (P22).", dispatch="")
        if any(f.rule == "R5" or (f.rule == "R0" and f.who == "driver") for f in standing):
            self.s3_prepare()
        return f"{standing[0].rule}: {' '.join(standing[0].text.split())[:160]}"

    def s3_prepare(self) -> None:
        """The ONE preparation of the grounding table; every road that refreshes it calls this. Diff world: `blast_radius.py` (the index) ->
        `grounding_table.py --refresh` (== the skeleton when no table exists; off the diff it writes the null outcome) -> `base_slice.py`.
        POSITION: the index before the table, both before `start` - a window is never labelled over another index generation or another
        diff; the slice after the table (it reads `hunks[]`). The first two failing are a `Refusal` (nothing after them ran; no dispatch is
        registered); the slice failing is a recorded warning line and the window runs (its `before` is then `unknown`, G1-8)."""
        import grounding_table as GT
        diff = GT.source_state(self.task_root)[0] == "diff"
        first = lambda out: next((ln.strip() for ln in str(out).splitlines() if ln.strip()), "no output")      # noqa: E731
        if diff:
            code, out = self.py("blast_radius.py", "--task", self.task)
            if code:
                raise Refusal(f"S3 preparation: blast_radius.py exited {code}: {first(out)}. The grounding table is not built over a "
                              "missing or stale index; nothing else ran. Way on: the conductor (P22).", dispatch="")
        code, out = self.py("grounding_table.py", "--refresh", "--task", self.task)
        if code:
            raise Refusal(f"S3 preparation: grounding_table.py --refresh exited {code}: {first(out)}. The slice and the window did not "
                          "run. Way on: the conductor (P22).", dispatch="")
        if diff:
            code, out = self.py("base_slice.py", "--task", self.task)
            if code:
                code2, out2 = self.py("stage_done.py", "--task", self.task, "--warn",
                                      f"base_slice: unknown - S3 preparation: base_slice.py exited {code} ({first(out)[:160]}): no base slice for this story; the planner "
                                      "reads before: unknown")
                if code2:
                    raise Refusal(f"S3 preparation: base_slice.py exited {code} and the warning could not be recorded (stage_done.py exited "
                                  f"{code2}: {first(out2)}). The window did not run. Way on: the conductor (P22).", dispatch="")

    def s3_between_windows(self) -> None:
        """The slot between the windows (G2-2): the measures are written afresh over the table as it is now (`grounding_table.py --share`),
        the questions the strategist wrote on grounding rows join the question register (`claim_projector.project_row_questions`), then
        the two stops are judged (`grounding_stop`: coverage first). POSITION: after step 8 and before window 2 - the stop is never asked
        over a table step 8 would send back to window 1, and window 2 never starts over a stop nobody has answered. A measure or a
        projection the code cannot make is a refusal to the conductor, never a silent pass (FR-59)."""
        import claim_projector as CP
        code, out = self.py("grounding_table.py", "--share", "--task", self.task)
        if code:
            raise Refusal(f"S3: grounding_table.py --share exited {code} ({next((ln.strip() for ln in str(out).splitlines() if ln.strip()), 'no output')[:200]}), "
                          "so the coverage of the requirements cannot be judged and window 2 did not start. Way on: the conductor repairs "
                          "the table or the register (P22).", dispatch="")
        result = CP.project_row_questions(self.task_root)
        if result.problems:
            raise Refusal("S3 questions of the grounding table (claim_projector.py): " + "\n".join(f"- {p}" for p in result.problems),
                          dispatch=getattr(self, "last_dispatch", "") or "", retry=None)
        self.grounding_stop()

    GROUNDING_NAMED_MAX = 12                  # requirements a stop question names; the rest is a count

    def _stop_requirements(self, rows: list) -> list:
        """The lines that name requirements in a stop question: the register's own statement of each, in the person's words (no table
        field names), at most `GROUNDING_NAMED_MAX`."""
        import grounding_table as GT
        texts = GT.register_info(self.task_root).texts
        lines = [f"- {o['r']}: {' '.join(str(texts.get(o['r']) or 'no statement in the register').split())[:160]}" for o in rows[:self.GROUNDING_NAMED_MAX]]
        return lines + ([f"- and {len(rows) - self.GROUNDING_NAMED_MAX} more"] if len(rows) > self.GROUNDING_NAMED_MAX else [])

    def grounding_stop(self) -> None:
        """The two stops before window 2 (G2-2): requirement coverage FIRST, then the refactoring share. A stop with a person's word for
        its exact present digest (`grounding_table.stop_word`: the ONE reader) passes; one without is raised as a seam question
        (`_coverage_person`, `_refactoring_person`) and the refactoring one is asked only when coverage passed. A road the code cannot
        measure (`unknown`) is a refusal to the conductor, never a card for the person (FR-3) and never a pass (FR-59)."""
        import grounding_table as GT
        cov = GT.coverage_of(self.task_root)
        if cov["road"] == "unknown":
            raise Refusal(f"S3: the requirement coverage cannot be measured ({cov.get('reason') or 'no reason given'}), so window 2 did not start. "
                          "Way on: the conductor repairs the table, the register or the policy (P22).", dispatch="")
        if cov["road"] == "stop":
            digest = GT.coverage_digest(self.task_root, cov)
            if GT.stop_word(self.pipeline(), GT.COVERAGE_STOP_BLOCK, digest) is None:
                # remains: the coverage stop is a seam question (priced, `offered`): go on / stop have the seam's executors, other words go to the seam
                raise self._coverage_person(cov, digest)
        result = GT.share_of(self.task_root)
        if result["road"] == "unknown":
            raise Refusal(f"S3: the refactoring share cannot be measured ({result.get('reason') or 'no reason given'}), so window 2 did not start. "
                          "Way on: the conductor repairs the table or the policy (P22).", dispatch="")
        if result["road"] == "stop":
            digest = GT.refactoring_digest(self.task_root, result)
            if GT.stop_word(self.pipeline(), GT.REFACTORING_STOP_BLOCK, digest) is None:
                # remains: the refactoring stop is a seam question (priced, `offered`): go on / stop have the seam's executors, other words go to the seam
                raise self._refactoring_person(result, digest)

    GROUNDING_STOP_OPTION = {"answer": "stop", "token": "stop", "slots": {"what": "decide what the change is to do about these requirements"},
                             "says": "stop the story here; nothing runs. You can also tell me in your own words what to do instead, for "
                                     "example that this is the wrong merge request"}

    def _coverage_person(self, cov: dict, digest: str) -> "Person":
        """The coverage stop as a closed question: the requirements the change does not meet (`not implemented`, `outside the diff`
        with no place, absent from the table) and, as a paragraph of their own, those the factory could not establish (`unknown`)."""
        import grounding_table as GT
        import planning_contract as PC
        policy = (PC.grounding_policy()[0] or {}).get("coverage_stop_below_percent", "the configured")
        known = [o for o in cov.get("outside") or [] if o.get("state") != "unknown"]
        unknown = [o for o in cov.get("outside") or [] if o.get("state") == "unknown"]
        covered = cov["implemented"] + cov["partial"]
        if cov.get("reading") == "nothing_asked":
            lead = ("This merge request asks nothing of the story: every requirement is either left to the implementation itself or met "
                    "somewhere else, so there is nothing for the change to be checked against. Before the plan is written I need your word.")
        elif unknown and not known:   # F-5: nothing is known to be missing; the count of the numerator is not a statement about the change
            lead = (f"I could not establish whether the change implements these {len(unknown)} requirements of the story, so I cannot tell how much of "
                    f"it the change covers; {policy}% is the mark from which I go on by myself.\n\nI could not establish whether the change implements:\n"
                    + "\n".join(self._stop_requirements(unknown)) + "\nThe questions about them reach you at gate A.")
        else:
            lead = (f"The change implements {covered} of {cov['n']} requirements of the story ({cov['percent']}%), under the {policy}% "
                    "from which I go on by myself.")
            if known:
                lead += "\n\nThe change does not implement:\n" + "\n".join(self._stop_requirements(known))
            if unknown:
                lead += ("\n\nI could not establish whether the change implements:\n" + "\n".join(self._stop_requirements(unknown))
                         + ("\nThe questions about them reach you at gate A." if not known else ""))
        lead += "\n\nWhat I need from you is one of these:"
        go_on = {"answer": "go on", "token": "go on",
                 "says": "go on and write the plan anyway; the report carries these requirements as they stand, in your words"}
        options = [go_on, dict(self.GROUNDING_STOP_OPTION)]
        block = f"{GT.COVERAGE_STOP_BLOCK} {digest}"
        details = "The requirements outside the count: " + (", ".join(f"{o['r']} ({o['state']})" for o in cov.get("outside") or []) or "none")
        if cov.get("reading") == "nothing_asked":
            return self.site_seam_person("grounding_stop", self.closed_question("s3.grounding_coverage.nothing_asked", lead, options), "S3",
                                         block=block, details=details)
        if unknown and not known:
            return self.site_seam_person("grounding_stop", self.closed_question("s3.grounding_coverage.not_known", lead, options), "S3",
                                         block=block, details=details)
        return self.site_seam_person("grounding_stop", self.closed_question("s3.grounding_coverage", lead, options), "S3",
                                     block=block, details=details)

    def _refactoring_person(self, result: dict, digest: str) -> "Person":
        """The refactoring stop as a closed question: how much of the changed production code the table calls refactoring."""
        import grounding_table as GT
        import planning_contract as PC
        policy = (PC.grounding_policy()[0] or {}).get("stop_above_percent", "the configured")
        lead = (f"{result['percent']}% of the changed production lines ({result['refactoring']} of {result['total']}) are refactoring, "
                f"past the {policy}% from which I go on by myself. A change that mostly moves code gives the plan little to check "
                "against the story.\n\nWhat I need from you is one of these:")
        options = [{"answer": "go on", "token": "go on", "says": "go on and write the plan anyway; the report says the moved code is not checked beyond the plan"},
                   dict(self.GROUNDING_STOP_OPTION)]
        return self.site_seam_person("grounding_stop", self.closed_question("s3.grounding_refactoring", lead, options), "S3",
                                     block=f"{GT.REFACTORING_STOP_BLOCK} {digest}",
                                     details=f"Refactoring lines: {result['refactoring']}; changed production lines: {result['total']}")

    def s3_rework_completion(self):
        """The completion of an S3 strategist REWORK (a person's seam choice, the S4 rehearsal's route, a recovered dispatch; RN1-2 B-1):
        the plan projection alone (the revision mark and the `new:<n>` questions - the role writes neither), and the closing outcome stays
        `False`: a rework never closes S3 by itself. The one callable of `completion_for` and `seam_rework_step`."""
        def reworked(digest):
            self.s3_project(claims=False)
            return False
        return reworked

    def s3_project(self, claims: bool = True, reopening: bool = False) -> None:
        """The planner's claims into the register (G1-13): project -> refresh the table when the projection wrote -> done. A problem of the
        ROLE's is the role's to fix (the dispatch stays running and the S3 refusal road resumes it); a driver or conductor problem is not
        the role's and carries no repair marker. Then the PLAN's own projection (RN1-2, `planning_contract.project_plan`): the revision
        mark and the questions the rows declared as `new:<n>`, written AFTER the claims (the claims' register rows come first). Its
        problems are the conductor's, never the role's (no repair marker: the role's plan was accepted at the exit). `claims=False`
        is the `old` road (no grounding table, so no claims) - the plan projection alone."""
        dispatch = getattr(self, "last_dispatch", "") or ""
        if claims:
            import claim_projector as CP
            result = CP.project(self.task_root)
            problems = list(result.problems)
            if problems:
                lines = "\n".join(f"- {p}" for p in problems)
                if any(p.who == "role" for p in problems):
                    raise Refusal(f"S3 claims (claim_projector.py): {lines}\n{REPAIR_MARKER}: fix claims[] in work/grounding.yaml as the "
                                  "lines say.", dispatch=dispatch, retry=None)
                raise Refusal(f"S3 claims (claim_projector.py): {lines}", dispatch=dispatch, retry=None)
            if result.wrote:
                self.py("grounding_table.py", "--refresh", "--task", self.task, check=True)
        import planning_contract as PC
        planned = PC.project_plan(self.task_root, reopening=reopening)
        if planned.problems:
            raise Refusal("S3 plan projection (planning_contract.project_plan): " + "\n".join(f"- {p}" for p in planned.problems),
                          dispatch=dispatch, retry=None)

    def s3_window_completion(self, record):
        """The completion of an S3 strategist dispatch, decided in ONE place for the live road, the recovery road and the ticket rework
        (I3). `record`: the controller record or `{"window": ...}`. Window 1 (labelling) is accepted OPEN with `plan_pending`; a window
        that closes S3 projects the claims first. An `old` dispatch - the diff world, no `work/grounding.yaml`, no word on the record
        (started one-window before this node, finished after it) - closes as it always did (None)."""
        import grounding_table as GT
        record = record if isinstance(record, dict) else {}
        if self.s3_labelling_of(record):
            def window_one(digest):
                self.s3_project()
                return OpenWork("plan_pending", open_work_reason(
                    "window 1 (labelling) is accepted; the plan is written by window 2 over work/grounding.yaml", "…"))
            return window_one
        try:
            old = GT.source_state(self.task_root)[0] == "diff" and not (self.task_root / "work" / "grounding.yaml").is_file()
        except Exception:
            old = False
        if old:
            # RN1-2 (B-5b): the plan is stamped on this road too - the role writes no mark any more, and an `old` dispatch closes
            # S3 with nothing else that would. No claims here (there is no grounding table); the closing outcome stays None.
            def closing_old(digest):
                self.s3_project(claims=False)
                return None
            return closing_old

        def closing(digest):
            self.s3_project()
            self.py("grounding_table.py", "--share", "--task", self.task, check=True)      # the saved measures follow the bytes the role left (R3)
            return None
        return closing

    def s3_ticket_completion(self, closes: bool = True):
        """The ticket re-run of S3 closes COMPLETE (the plan baseline is re-captured): project -> refresh-if-wrote -> True. With
        `closes=False` (a stage that has an acceptor, X2-7) the same side steps run and the finish does not close: the stage critic does."""
        def closing(digest):
            self.s3_project(reopening=True)      # gate A's approval is on the old text; `ticket_reopen_gate_a` reopens it right after (B-2)
            self.py("grounding_table.py", "--share", "--task", self.task, check=True)
            return True if closes else None
        return closing

    def stage_S4(self) -> None:
        self.stages()
        state = self.controller_state()
        accepted = [d for d in (state.get("dispatches") or {}).values() if d.get("stage") == "S4" and d.get("status") == "accepted"]
        if not any(d.get("role") == "qa-case-designer" for d in accepted):
            self.run_role("S4", "qa-case-designer", extra=self.role_lines("S4", "qa-case-designer"))
        self.pin_cases()
        self.revise_plan()
        scope = self.critic_scope()
        # The rounds already spent are the controller's count from the journal, not a local number
        # (B-007); a budget nobody can read closes the stage's review without a round.
        budget = self.budget_or_none("S4", "qa-case-designer", scope)
        counted, cap = (budget or {}).get("counted"), (budget or {}).get("cap")
        last_round = not (isinstance(counted, int) and isinstance(cap, int) and counted < cap)

        # t-919 F-1: a critic accepted with `cases_in_repair` whose repair round nobody registered (its finish went through the
        # recovery road or a refused-then-continued finish, not through this method's tail) is owed its round NOW, from the
        # data - the shape of S7 reading `work/triage.json` - never a new paid critic over the same cases. Needs the findings
        # file and a round left (the very conditions the OpenWork was given under); otherwise the road below, a fresh critic.
        if not last_round and self.s4_findings() and self.s4_repair_owed(state.get("dispatches")):
            print("S4: the case critic was accepted with cases sent back and no repair round is registered; the round starts now, "
                  "no new critic")
            return self.s4_after_critic("concerns", scope, counted, cap, last_round)
        # the critic's finish closes S4 unless its verdict sends cases back and a round is left (`s4_critic_completion`: the one
        # rule of the live stage and of the recovery road, `completion_for`)
        digest, _next = self.run_role("S4", "qa-case-critic", scope=scope,
                                      complete=self.s4_critic_completion(scope, counted, cap),
                                      extra=["Review only the pinned versions; your roll-call names every case in scope."])
        self.s4_after_critic(self.case_verdict(digest), scope, counted, cap, last_round)

    @staticmethod
    def stage_repair_owed(dispatches, stage: str, author: str, critic: str, word: str) -> bool:
        """True when the NEWEST dispatch of the stage critic in `stage` is accepted with the open-work word `word` and no dispatch of
        `author` (a registered rework, whatever its state) follows it - a repair round the critic's finish promised and nobody
        registered. Read from the controller's dispatch records, in their creation order; a record whose `unresolved` is absent or
        of another word, or a state that is no mapping, is "not owed" (the road below is a fresh critic: costly, never a silent
        close of the stage). ONE rule for S2, S3 and S4 (X2-7)."""
        rows = [d for d in (dispatches.values() if isinstance(dispatches, dict) else []) if isinstance(d, dict) and d.get("stage") == stage]
        critics = [i for i, d in enumerate(rows) if d.get("role") == critic]
        if not critics:
            return False
        last = rows[critics[-1]]
        return (last.get("status") == "accepted" and word in json.dumps(last.get("unresolved"))
                and not any(d.get("role") == author for d in rows[critics[-1] + 1:]))

    @staticmethod
    def s4_repair_owed(dispatches) -> bool:
        """The S4 reading of `stage_repair_owed` (word `cases_in_repair`): a repair round the case critic's finish promised and nobody
        registered."""
        return Driver.stage_repair_owed(dispatches, "S4", "qa-case-designer", "qa-case-critic", "cases_in_repair")

    # --- X2-7: the stage critic's route for S2 and S3 (queue: X2-7 -> X6-1, the map of the driver moves it) ----------------------
    def stage_acceptor(self, stage: str) -> str:
        """The role that accepts `stage` by meaning (`acceptance_by` in references/stages.json), or "" when the stage has none."""
        return str((self.stages().get(stage) or {}).get("acceptance_by") or "")

    # --- X7-6 / X7-6b / X7-6c: a stage accepted by its CONSUMER role - S6 by the failure analyst (who works in S7), S7 by the doc scribe (who works
    # in S8). ONE table and ONE helper set (t-1860 Q8): the two stages differ only in the data below, so every fix is made once. ------------
    CONSUMER_ROUTES = {
        "S6": {"consumer_stage": "S7", "author": "qa-runner", "who": "failure analyst", "what": "the runner's handoff",
               "closes_when": lambda closes: closes is True,
               "awaits": "the runner stopped; S6 awaits the acceptance of {consumer}, which judges the run report and the case records from its own form",
               "rework_complete": lambda driver: driver.consumer_awaits("S6", True)},
        "S7": {"consumer_stage": "S8", "author": "qa-failure-analyst", "who": "doc scribe", "what": "the analyst's handoff",
               "closes_when": lambda closes: closes is None,
               "awaits": "the failure analyst stopped; S7 awaits the acceptance of {consumer}, which judges the triage and the bug drafts from its own form",
               # read AFTER the role wrote: repairs still owed keep S7 open
               "rework_complete": lambda driver: (lambda digest: driver.consumer_awaits("S7", driver.s7_open_work()))},
    }

    def consumer_awaits(self, stage: str, closes):
        """The author's `complete` under a consumer: a finish that WOULD close `stage` (the table's `closes_when`) is the open-work word
        `stage_awaits_acceptance` instead (POSITION: the author never closes the stage, §3); anything else is passed through as it was.
        With no consumer `closes` comes back unchanged (temporal: older pipelines behave as today)."""
        import acceptance
        consumer, route = acceptance.consumer_of(stage), self.CONSUMER_ROUTES.get(stage) or {}
        if consumer and route and route["closes_when"](closes):
            return OpenWork(acceptance.AWAITS_WORD, open_work_reason(route["awaits"].format(consumer=consumer), ""))
        return closes

    def consumer_pending(self, stage: str) -> bool:
        """True when `stage` has a consumer, is not completed, its author ran, and an `accept` record stands for the author's LAST dispatch of
        the current life: the stage is owed its close (a restart between the consumer's record and the close lands here)."""
        import acceptance
        if not acceptance.consumer_of(stage):
            return False
        state = self.controller_state()
        if ((state.get("stages") or {}).get(stage) or {}).get("status") == "completed":
            return False
        return acceptance.accepted_for(self.pipeline(), stage, acceptance.stage_author_dispatch(state, acceptance.stage_def_of(stage)))

    def consumer_close_words(self, stage: str) -> tuple:
        """B-20 N4 (AR-27, FR-35): `(reason, digest)` of the close of a stage judged by its consumer, from the acceptance RECORD - never from a
        refusal's words. A driver accept whose quote starts `by: person` for the author's LAST dispatch is the person's pass: the words say a
        person's word accepted it. Any other record (the consumer role's own) and no record give the default words (`CODE_CLOSE_SITES`,
        the consumer's name). INVARIANT: a person's pass is never reported as a role's verdict. An unreadable state gives the default."""
        import acceptance
        route = self.CONSUMER_ROUTES.get(stage) or {}
        reason = CODE_CLOSE_SITES.get(f"{stage.lower()}.accepted", ("", "the consumer accepted the handoff"))[1]
        digest = f"accepted by the {route.get('who', 'consumer')}"
        try:
            pipeline = self.pipeline()
            author = acceptance.stage_author_dispatch(self.controller_state(), acceptance.stage_def_of(stage))
            record = acceptance.stage_acceptance(pipeline, stage) or {}
            by_person = (acceptance.accepted_for(pipeline, stage, author, acceptor=acceptance.DRIVER_ACCEPTOR)
                         and str(record.get("quote") or "").startswith(BY_PERSON))
        except Exception:  # noqa: BLE001 - a record that cannot be read names nobody: the default words
            by_person = False
        if by_person:
            return f"a person's word passed the acceptance of {route.get('what', 'the handoff')}", "accepted by a person's word"
        return reason, digest

    def consumer_word_step(self) -> bool:
        """B-20 (AR-24): the person's `stage acceptance` word reaches a stage that awaits its consumer from ANY driver position, before `where`
        reads on. For each stage of `CONSUMER_ROUTES` that `acceptance.awaits_acceptance` names (the author's last dispatch is accepted and no
        record stands - a dispatch that is running or was superseded awaits nothing, so no word binds to it), a live word that was written AFTER
        that dispatch was accepted passes it through `consumer_person_pass` (the one writer, AR-14). A time that cannot be read is not honoured
        (FR-4: a word never accepts work the person never saw). True when a pass was recorded (the turn is spent); False and nothing written
        otherwise. It never asks and never stops the driver. Census: shape, owner intent - it carries a word, it does not read its meaning."""
        import acceptance
        moved = False
        for stage in self.CONSUMER_ROUTES:
            author = acceptance.awaits_acceptance(self.controller_state(), stage, self.pipeline())
            if author and self.consumer_person_pass(stage, author):
                moved = True
        return moved

    def accepted_at(self, author: str) -> str:
        """When the dispatch `author` was last accepted, as `controller.stamp_utc` (the last `accept` event of the controller's store); `""`
        when it cannot be read (no event, no store). The ONE reader of that time (B-20 F1): a word dated before it was said about work the
        person had not yet seen."""
        try:
            from controller import Controller, stamp_utc
            times = [e.get("created_at") for e in Controller(self.task_root).store.read()
                     if e.get("type") == "accept" and (e.get("payload") or {}).get("id") == author]
            return stamp_utc(times[-1]) if times else ""
        except Exception:  # noqa: BLE001 - an acceptance time that cannot be read is the safe side: the word is not honoured
            return ""

    def consumer_person_pass(self, stage: str, author: str, answer: str = "") -> bool:
        """P13 (M3 of t-1860): the person's word moves the factory. True when an `accept` record stands for `author` already, or when a
        person's word passes the acceptance - `answer` (the words of a recorded `close` answer, given by the caller) or a live
        `waiver.py --block` of the stage-acceptance phrase (`acceptance.STAGE_ACCEPTANCE_PHRASE`) of this stage (`waiver.split_overridden`, the one reader) - and then the pass is RECORDED
        first: `stage_done.py --acceptance <the author's form> --acceptor driver --verdict accept --quote "by: person - <words>"`, the one
        writer, so every reader of the record (the close sites, `awaits_acceptance`, `stage_done`) sees it. False: nothing passes it.
        B-20 F1 (FR-4), at EVERY site: a live waiver is honoured only when its `at` is LATER than the acceptance of `author` (`accepted_at`);
        a time that cannot be read is not honoured. `answer` is a fresh word (given by the caller this turn) and is exempt. A Refusal of the
        recording carries the WHOLE pass as its `retry`, so the finding is filed after a retry too (P13)."""
        import acceptance
        if not author:
            return False
        if acceptance.accepted_for(self.pipeline(), stage, author):
            return True
        line = f"{acceptance.STAGE_ACCEPTANCE_PHRASE}: no accept record stands for {author}"
        since = ""
        if not " ".join(str(answer or "").split()):
            since = self.accepted_at(author)
            if not since:
                return False
        try:
            heard = self.person_pass(stage, author, line, answer, since=since)
        except Refusal as refusal:
            refusal.retry = lambda: self.consumer_person_pass(stage, author, answer)
            raise
        if not heard:
            return False
        # P13: a pass by the person's word is a finding, filed once per stage and author dispatch (the key makes a second write safe)
        self.owe_row("project_decisions.py", "--root", str(self.project), "add-finding",
                     "--essence", f"{stage} acceptance of {author} passed on the person's word: {str(heard.get('decision') or '')[:500]}",
                     "--scope", "local-calibration", "--witness", f"{stage} person's word at {heard.get('at') or ''}",
                     "--idempotency-key", f"stage-acceptance-pass:{self.task}:{stage}:{author}",
                     what="the finding about the stage acceptance you passed", stage=stage)
        return True

    def person_pass(self, stage: str, author: str, line: str, answer: str = "", since: str = "") -> dict:
        """The body of the pass (F3, B-6): the person's word - `answer` (given by the caller) or a live `waiver.py --block` that passes `line`
        (`waiver.split_overridden`, the ONE reader, AR-13) - is RECORDED as the driver accept of `author` for `stage` (the one writer,
        `stage_done.py --acceptance`), and then True. `since` (non-empty): a waiver is honoured only when its `at` is LATER than `since` -
        both read through `controller.stamp_utc`; an `at` or a `since` that cannot be read is not honoured (a word never accepts an author
        dispatch the person never saw, FR-4). Returns the honoured entry (`{"decision": <words>, "at": <when or "">}`) once the pass is
        recorded, `{}` when nothing passes: no `author` -> `{}`, no accept record without an author dispatch."""
        import acceptance
        if not author:
            return {}

        def stamp(value) -> str:
            """One normal form for an `at` / `since`: `controller.stamp_utc` of the epoch second; `""` when it is no time (or has no zone)."""
            from datetime import datetime
            from controller import stamp_utc
            if isinstance(value, str):
                try:
                    moment = datetime.fromisoformat(value.strip().replace("Z", "+00:00"))
                    return stamp_utc(moment.timestamp()) if moment.tzinfo is not None else ""
                except (ValueError, OverflowError, OSError):
                    return ""
            return "" if isinstance(value, bool) or value is None else stamp_utc(value)
        words = " ".join(str(answer or "").split())
        heard = {}
        if not words:
            import waiver
            _blocking, passed = waiver.split_overridden([line], self.pipeline(), stage)
            if passed and since and not (stamp(passed[0].get("at")) > stamp(since) > ""):
                passed = []
            heard = dict(passed[0]) if passed else {}
            words = " ".join(str(heard.get("decision") or "").split())
        if not words:
            return {}
        if getattr(self, "dry", False):      # B-20 F2: `--dry-run` runs nothing and writes nothing - the pass is only said
            print(f"{stage}: dry run - a person's word would pass the acceptance of {author}; nothing is recorded")
            return {}
        self.py("stage_done.py", "--task", self.task, "--stage", stage, "--acceptance", f"work/handoffs/{author}.yaml",
                "--acceptor", acceptance.DRIVER_ACCEPTOR, "--verdict", "accept", "--quote", f"{BY_PERSON} - " + words[:500], check=True,
                expect=f"the person's pass recorded as the acceptance of {stage} for {author}")
        print(f"{stage}: a person's word passes the acceptance of {author}; recorded as a driver accept (by: person)")
        return {"decision": words, "at": heard.get("at") or ""}

    def consumer_need_record(self, stage: str, site: str) -> None:
        """The close sites of a stage with a consumer (S6: `s6_reentry`, `s6_reprobed_close`, `manual_close`; S7: `s7_close`): with an author that
        ran, a close needs the `accept` record of the author's LAST dispatch - or a person's pass (`consumer_person_pass`, M3). A Refusal names
        the missing record and the door (FR-1, FR-2); with no consumer, no author dispatch, or the stage completed already, nothing."""
        import acceptance
        consumer = acceptance.consumer_of(stage)
        if not consumer:
            return
        state = self.controller_state()
        if ((state.get("stages") or {}).get(stage) or {}).get("status") == "completed":
            return
        author = acceptance.stage_author_dispatch(state, acceptance.stage_def_of(stage))
        if not author or self.consumer_pending(stage) or self.consumer_person_pass(stage, author):
            return
        raise Refusal(f"{stage} cannot be closed at {site}: no accept record of {consumer} stands for {author}. The consumer judges "
                      f"{(self.CONSUMER_ROUTES.get(stage) or {}).get('what', 'the handoff')} from its own form (`stage_done.py --task {self.task} "
                      f"--stage {stage} --acceptance work/handoffs/<{consumer} dispatch>.yaml`), or a person's word passes it (`waiver.py "
                      f"--task {self.task} --stage {stage} --block \"{acceptance.STAGE_ACCEPTANCE_PHRASE}\"`).")

    def consumer_counts(self, stage: str, reviewed: str) -> tuple:
        """`(counted, cap)` of the author's repair rounds on the dispatch the consumer REVIEWED, as the controller counts them (`prepare` carries
        `repair_budget` for `REPAIR_LOOP_ROLES`; the packet is asked for the reviewed dispatch's own scope and half, so the ledger key is the
        first dispatch's). Read ONLY after a verdict `reject` is known (B1). `(None, None)` when the controller cannot say."""
        dispatch = (self.controller_state().get("dispatches") or {}).get(reviewed) or {}
        extra = ({"execution_kind": str(dispatch.get("execution_kind") or ""), "manual_case_ids": [str(c) for c in dispatch.get("manual_case_ids") or []]}
                 if stage == "S6" else {})
        budget = self.budget_or_none(stage, self.CONSUMER_ROUTES[stage]["author"], list(dispatch.get("scope") or []), ref=reviewed, **extra) or {}
        return budget.get("counted"), budget.get("cap")

    def consumer_exhausted(self, stage: str, record: dict, dispatch: str, form: str, counted, cap):
        """A `reject` with no round left, or none that can be counted: the ONE seam (`stage_review_exhausted`), never a code decision. The text says
        which of the two it is (FR-41: an unknown is not «no round is left»)."""
        route = self.CONSUMER_ROUTES[stage]
        text = ""
        if not (isinstance(counted, int) and isinstance(cap, int)):
            text = (f"the {route['who']} rejected {stage} and the factory could not count the repair rounds of {route['author']}, so none is "
                    f"started: {record.get('quote') or ''}")
        return self.stage_review_exhausted(stage, route["author"], dispatch, record, form, text=text)

    def consumer_completion(self, stage: str, inner, dispatch_id=None):
        """The `complete` callable of the consumer's finish while `stage` awaits it (the shape of `stage_critic_completion`): write the record from
        the consumer's form FIRST (`stage_acceptance_write`, the one writer), then `accept` -> the consumer's own completion `inner` (a VALUE: a
        callable is called); `reject` with a round left -> `OpenWork("stage_superseded")` (its work is stale, E-24); `reject` with none left (or
        none countable) -> the conductor through the ONE seam. A verdict word the table does not know goes to the same seam. The repair budget
        is read only on a reject (B1)."""
        import acceptance
        route = self.CONSUMER_ROUTES[stage]

        def complete(digest: str):
            def own():
                return inner(digest) if callable(inner) else inner       # a VALUE: `finish` takes no callable from a callable
            dispatch = str(getattr(self, "last_dispatch", "") or "") if dispatch_id is None else str(dispatch_id or "")
            form = f"work/handoffs/{dispatch}.yaml" if dispatch else ""
            if not dispatch or not self.stage_verdict_known(form):
                return self.stage_review_exhausted(stage, route["author"], dispatch, None, form, unreadable=True)
            self.stage_acceptance_write(stage, dispatch)
            record = acceptance.stage_acceptance(self.pipeline(), stage) or {}
            if record.get("verdict") == "accept":
                return own()
            counted, cap = self.consumer_counts(stage, str(record.get("reviewed_dispatch") or ""))
            if isinstance(counted, int) and isinstance(cap, int) and counted < cap:
                return OpenWork(acceptance.SUPERSEDED_WORD, open_work_reason(
                    f"the {route['who']} sent {route['what']} back: {record.get('quote') or ''}", f"... [list: {form}]"))
            outcome = self.consumer_exhausted(stage, record, dispatch, form, counted, cap)
            return own() if outcome is None else outcome
        return complete

    def consumer_settled(self, stage: str, state: dict, awaiting: str, done: bool, ran: bool = False) -> bool:
        """What follows the consumer's finish while `stage` awaited it, and the recovery of a restart. True = this entry is done.
        - an `accept` record for `awaiting`: `stage` closes by it on the loop's next entry; True on a recovery entry, False right after the
          consumer ran (`ran`: its own stage is still to finish).
        - a `reject` record: a person's pass (`consumer_person_pass`) takes it as the accept; else the author's repair round NOW, ONCE per
          round, in a fresh context (`rework`: the controller reads the scope from the record, B2), within the repair cap (read only here, B1);
          no round left -> the conductor through the ONE seam (`consumer_exhausted`); True.
        - no record but an accepted, not superseded consumer dispatch CREATED AFTER `awaiting` (the finish died after the dispatch, M2): the
          record is written from its form, then the cases above. Otherwise False: the consumer is still to be dispatched."""
        import acceptance
        route, consumer = self.CONSUMER_ROUTES[stage], acceptance.consumer_of(stage)
        record = acceptance.stage_acceptance(self.pipeline(), stage) or {}
        mine = acceptance.consumer_dispatch(state, route["consumer_stage"], consumer, awaiting)
        if record.get("reviewed_dispatch") != awaiting and done:
            if not mine:
                return False
            self.stage_acceptance_write(stage, mine)
            record = acceptance.stage_acceptance(self.pipeline(), stage) or {}
        if record.get("reviewed_dispatch") != awaiting:
            return False
        if record.get("verdict") == "accept" or self.consumer_person_pass(stage, awaiting):
            return not ran
        form = f"work/handoffs/{mine or getattr(self, 'last_dispatch', '')}.yaml"
        counted, cap = self.consumer_counts(stage, awaiting)
        if not (isinstance(counted, int) and isinstance(cap, int) and counted < cap):
            self.consumer_exhausted(stage, record, mine, form, counted, cap)      # the ONE seam; a driver accept stands as a record
            return True
        self.rework(stage, route["author"], [], f"{route['who']}, acceptance record of {stage} for {awaiting}: " + str(record.get("quote") or ""),
                    cause="test_defect", complete=route["rework_complete"](self),
                    extra=[f"Repair round {counted + 1} of {cap}: the {route['who']}'s verdict is in {form}; change only what it names."])
        return True

    def stage_S2(self) -> None:
        """S2: the tester, then the stage critic's route. A stage with no acceptor (the world before `acceptance_by`) stays `stage_simple`.
        An accepted author dispatch is not dispatched again (a restart, or the author of a repair round): the route goes straight on."""
        role = self.stages()["S2"]["roles"][0]
        if not self.stage_acceptor("S2"):
            return self.stage_simple("S2")
        accepted = [d for d in (self.controller_state().get("dispatches") or {}).values()
                    if isinstance(d, dict) and d.get("stage") == "S2" and d.get("role") == role and d.get("status") == "accepted"]
        if not accepted:
            self.run_role("S2", role, extra=self.role_lines("S2", role))
        self.stage_critic_route("S2", role)

    def stage_raise_questions(self, stage: str, author: str) -> list:
        """X2-6 on the route (t-1815 F2): the questions of the stage's critic were raised into the register by `stage_acceptance_write`
        (the critic's form is the one that declares `questions[]`; no author contract does), so here the conductor only settles what is
        still open (`settle_role_questions`). Returns the rows that carry a person class."""
        return self.settle_role_questions(stage)

    def stage_critic_route(self, stage: str, author: str) -> None:
        """The route of the stage critic after the author's stop (S2, S3): questions, the ONE repair counter (`budget_or_none`), a round owed
        by an earlier promise, then the critic's dispatch whose finish writes the acceptance record BEFORE the controller accepts it
        (`stage_critic_completion`). A rejected stage goes back to the author in a FRESH context (`rework`, `rework_mode: fresh`) with the
        artifact and the verdict; a budget nobody can read (None) gives no round and the critic still runs once."""
        critic = self.stage_acceptor(stage)
        self.stage_raise_questions(stage, author)
        scope: list = []
        budget = self.budget_or_none(stage, author, scope)
        counted, cap = (budget or {}).get("counted"), (budget or {}).get("cap")
        last_round = not (isinstance(counted, int) and isinstance(cap, int) and counted < cap)
        if not last_round and self.stage_repair_owed(self.controller_state().get("dispatches"), stage, author, critic, "stage_in_repair"):
            print(f"{stage}: the stage critic was accepted with the stage sent back and no repair round is registered; the round starts now, "
                  "no new critic")
            return self.stage_after_critic(stage, author, scope, counted, cap, last_round)
        self.run_role(stage, critic, scope=scope, complete=self.stage_critic_completion(stage, author, scope, counted, cap),
                      extra=[f"You accept or return {stage} by meaning: the author's artifact, its handoff form and "
                             f"work/advice-{stage}.json are in the brief; the verdict is `header.verdict` of your form."])
        self.stage_after_critic(stage, author, scope, counted, cap, last_round)

    def stage_after_critic(self, stage: str, author: str, scope, counted, cap, last_round: bool) -> None:
        """What follows the stage critic's accepted finish: a `reject` record with a round left starts the author's round (fresh context, the
        critic's form as the only extra). An `accept`, or no round left (the conductor already settled it inside `complete`), does nothing."""
        import acceptance
        self.stage_raise_questions(stage, author)        # the critic's questions were raised inside its finish; the conductor settles them now
        record = acceptance.stage_acceptance(self.pipeline(), stage) or {}
        if record.get("verdict") != "reject" or last_round:
            return
        form = self.stage_critic_form(stage)
        self.rework(stage, author, scope, "stage critic: " + str(record.get("quote") or ""), cause="test_defect",
                    extra=[f"Repair round {counted + 1} of {cap}: the stage critic's verdict is in {form}; change only what it names."])

    def stage_critic_form(self, stage: str) -> str:
        """The task-relative handoff form of the newest accepted dispatch of the stage critic of `stage`, or the form of the one running."""
        critic = self.stage_acceptor(stage)
        found = [str(d.get("id")) for d in (self.controller_state().get("dispatches") or {}).values()
                 if isinstance(d, dict) and d.get("stage") == stage and d.get("role") == critic]
        dispatch = found[-1] if found else getattr(self, "last_dispatch", "")
        return f"work/handoffs/{dispatch}.yaml"

    def stage_acceptance_write(self, stage: str, dispatch: str) -> None:
        """THE call of the writer (`stage_done.py --acceptance`, X2-5) for the stage critic's form of `dispatch`; a refusal of the writer is a
        `Refusal` on the standard road. Called inside `complete(digest)`, BEFORE `story_step finish` accepts the critic (E-X2-7d).
        First the critic's own `questions[]` are raised into the register (t-1815 F2; `check=True`: a refused form is a `Refusal` whose text
        names the entries, so no question is lost in silence; a form with no questions raises nothing; idempotent by `raised_from`)."""
        if (self.task_root / "work" / "handoffs" / f"{dispatch}.yaml").is_file():
            self.py("question_register.py", "--task", self.task, "--raise", "--stage", stage, "--asked-by", self.stage_acceptor(stage),
                    "--from-handoff", f"work/handoffs/{dispatch}.yaml", check=True,
                    expect=f"the questions[] of work/handoffs/{dispatch}.yaml raised into the register (none when the form has none)")
        self.py("stage_done.py", "--task", self.task, "--stage", stage, "--acceptance", f"work/handoffs/{dispatch}.yaml", check=True,
                expect=f"the stage acceptance of {stage} recorded in pipeline.json from work/handoffs/{dispatch}.yaml")

    def stage_critic_completion(self, stage: str, author: str, scope, counted, cap, dispatch_id=None):
        """The `complete` callable of the stage critic's finish (S2, S3): write the record, then (a) `accept` closes the stage (None), (b)
        `reject` with a round left keeps it open by `OpenWork("stage_in_repair")` (the controller accepts the pair), (c) `reject` on the last
        round, or a verdict word the table does not know, goes to the conductor (`stage_review_exhausted`) BEFORE the finish. Direction of
        error: never `None` without an `accept` record or a person's word. `dispatch_id` (t-1815 F1): the id of the critic dispatch
        this finish closes. The recovery road (`completion_for`) passes the saved RECORD's id ("" when it carries none: the seam gets the
        reason, never a guess); the live road passes None and `run_role` has set `last_dispatch` just before `finish`."""
        import acceptance
        last_round = not (isinstance(counted, int) and isinstance(cap, int) and counted < cap)

        def complete(digest: str):
            dispatch = str(getattr(self, "last_dispatch", "") or "") if dispatch_id is None else str(dispatch_id or "")
            form = f"work/handoffs/{dispatch}.yaml" if dispatch else ""
            if not dispatch:
                return self.stage_review_exhausted(stage, author, dispatch, None, form, unreadable=True,
                                                   text="the saved result of the stage critic carries no dispatch id, so its form cannot be found")
            if not self.stage_verdict_known(form):
                return self.stage_review_exhausted(stage, author, dispatch, None, form, unreadable=True)
            self.stage_acceptance_write(stage, dispatch)
            record = acceptance.stage_acceptance(self.pipeline(), stage) or {}
            if record.get("verdict") == "accept":
                return None
            quote = str(record.get("quote") or "")
            if not last_round:
                return OpenWork("stage_in_repair", open_work_reason(f"the stage critic sent {stage} back: {quote}", f"… [list: {form}]"))
            return self.stage_review_exhausted(stage, author, dispatch, record, form)
        return complete

    def stage_verdict_known(self, form: str) -> bool:
        """True when the form's `header.verdict` is a word of the acceptance table (`vocabulary.stage_acceptance_verdicts`). Reads only."""
        import acceptance
        import handoff
        try:
            data = handoff.parse((self.task_root / form).read_text(encoding="utf-8")).data
            return bool(acceptance.stage_acceptance_verdict(((data or {}).get("header") or {}).get("verdict")))
        except (OSError, ValueError, AttributeError):
            return False

    def stage_review_exhausted(self, stage: str, author: str, critic_dispatch: str, record, form: str, unreadable: bool = False,
                               text: str = ""):
        """F-X2-7: the stage critic rejected the stage on the last round (or its verdict word is unreadable): the conductor decides, through
        the ONE seam, BEFORE the critic's finish. The moves are the conductor's existing commands: accept with the gap
        (`stage_done.py --acceptance <form> --acceptor driver --verdict accept --quote "<gap>"`), one more round on the person's words
        (`rework --reason`, a cause that is not `test_defect`), or a question to the person with the price of each. Afterwards the facts are
        read: a `driver` accept for this author dispatch -> `None`; a new author dispatch -> `OpenWork`; neither -> the seam's `Person`."""
        import acceptance
        quote = "" if record is None else str(record.get("quote") or "")
        who = acceptance.consumer_of(stage) or "the stage critic"      # FR-37: the acceptor that judged, not always a stage critic (M1)
        text = text or (f"the verdict word of {who} is unreadable" if unreadable else
                        f"{who} rejected {stage} and no repair round is left: {quote}")
        files = ([self.task_root / form] if form else []) + [self.task_root / n for n in (self.stages()[stage].get("outputs") or [])
                                          if isinstance(n, str) and not n.startswith("project:") and (self.task_root / n).is_file()]
        line = f"{acceptance.STAGE_ACCEPTANCE_PHRASE}: {text}"      # F3: the line `waiver.py --block` is verified against
        state = {"why": "stage_review_exhausted", "kind": "conductor", "stage": stage, "dispatch": critic_dispatch, "text": text,
                 "lead": text + f". Decide: accept {stage} with the gap, one more round on words you ground, or ask the person.",
                 "files": [f for f in files if f.is_file()], "lines": [line]}
        # F3 (B-6): a person's `go on` recorded AFTER this critic dispatch started closes the stage with a finding. No journalled start of the
        # critic dispatch (`since == ""`) -> the pass is not consulted at all (the conductor / the person is asked).
        try:
            from controller import Controller, stamp_utc
            since = stamp_utc(Controller(self.task_root)._dispatch_starts().get(critic_dispatch))
        except Exception:  # noqa: BLE001 - a start that cannot be read is the safe side: no pass
            since = ""

        def person_closes(author_dispatch: str) -> bool:
            heard = self.person_pass(stage, author_dispatch, line, since=since) if since and author_dispatch else {}
            if not heard:
                return False
            self.owe_row("project_decisions.py", "--root", str(self.project), "add-finding",
                         "--essence", f"{stage} closed on the person's word over: {line}", "--scope", "local-calibration",
                         "--witness", f"{stage} person's word {str(heard.get('decision') or '')[:200]!r} at {heard.get('at')}",
                         "--idempotency-key", f"stage-review-pass:{self.task}:{stage}:{critic_dispatch}",
                         what="the finding about the stage review you passed", stage=stage)
            return True
        author_last = acceptance.stage_author_dispatch(self.controller_state(), acceptance.stage_def_of(stage))
        if person_closes(author_last):
            return None
        self.no_move(state)
        pipeline = self.pipeline()
        author_last = acceptance.stage_author_dispatch(self.controller_state(), acceptance.stage_def_of(stage))
        if acceptance.accepted_for(pipeline, stage, author_last, acceptor=acceptance.DRIVER_ACCEPTOR):
            return None
        if person_closes(author_last):
            return None
        # M1: «after» is anchored on the acceptor's OWN dispatch among ALL dispatches in creation order (a consumer's dispatch belongs to the
        # next stage, so the stage's own list never held it); with none readable, on the reviewed author dispatch the record names.
        every = [d for d in (self.controller_state().get("dispatches") or {}).values() if isinstance(d, dict)]
        ids = [str(d.get("id")) for d in every]
        anchor = critic_dispatch if critic_dispatch in ids else str((record or {}).get("reviewed_dispatch") or "")
        after = ids[ids.index(anchor) + 1:] if anchor in ids else []
        if any(d.get("stage") == stage and d.get("role") == author and str(d.get("id")) in after for d in every):
            word = "cases_in_repair" if stage == "S4" else "stage_in_repair"       # S4 keeps its own word (s4_repair_owed reads it)
            return OpenWork(word, open_work_reason(f"the conductor sent {stage} back for one more round", f"… [list: {form}]"))
        # The conductor made no move: the SEAM shows the priced fallback question (`call=False`: it was just asked, no second paid call).
        return self.no_move(dict(state, call=False, text=state["text"] + ". The conductor made no move on the exhausted stage review."))

    def s4_after_critic(self, verdict: str, scope, counted, cap, last_round: bool) -> None:
        """What follows the S4 case critic's accepted finish: the roll-call, the designer's repair round (verdict sends cases back,
        a round is left, a findings file exists) or the case appendix. ONE tail for the live road and the owed-round road."""
        if self.stage_acceptor("S4"):
            self.settle_role_questions("S4")         # t-1815 F2: the case critic's questions were raised inside its finish
        findings = self.s4_findings()
        fixes =bool(findings and re.search(r"approve_with_fixes", findings.read_text(encoding="utf-8", errors="replace")))
        # t-261 (O4, t-227): the same command also raises the questions the designer (no Bash) could only name - and it
        # does so with or without a findings file, so a pinned case that still says `raise` is reason enough to run it:
        # a critic who wrote `approve` otherwise left the Then with no question for gate A to show.
        if fixes or self.unraised_cases():
            # remains: R1 (C1-7b) - gate A's entry repair runs the same command when gate_preflight finds `unraised_questions` (GATE_REPAIRS -> `raise_move`, a failure -> `RepairFailed`), so no gate A packet is shown with a question this call could have raised
            self.py("critic_rollcall.py", *([str(findings)] if findings else []), "--apply-fixes",
                    "--task-root", str(self.task_root))
            self.pin_cases()
        if verdict in ("concerns", "review") and not last_round and findings:
            reason = findings.read_text(encoding="utf-8", errors="replace")[:1200]
            self.rework("S4", "qa-case-designer", scope, "critic round: " + reason, cause="test_defect",
                        extra=[f"Repair round {counted + 1} of {cap}: the critic's findings are in "
                               f"{findings.relative_to(self.task_root).as_posix()}; change only what they name."])
            self.pin_cases()
            return  # the loop comes back to S4 and dispatches the critic again
        # the stage is closed by the critic's finish; the appendix embeds the pinned cases
        self.render_appendix()

    @staticmethod
    def case_verdict(text: str) -> str:
        import role_digest
        return (role_digest.parse(text).get("header") or {}).get("verdict", "")

    def s4_findings(self) -> Path | None:
        """The case critic's findings file the S4 repair round reads (the newest `critic-findings*.md` under
        `work/test-cases/`), or None. Never the S5 files `work/test-code/critic-findings-*.md` (AR-13, AR-22)."""
        import findings_path
        return self.newest(findings_path.S4_PATTERN)      # through `self.newest`: the slow story tests stand in for it

    def s4_critic_completion(self, scope, counted, cap, dispatch_id=None):
        """The `complete` callable of the S4 case critic's finish - the live stage and `completion_for` (the recovery road) call
        THIS one rule (t-909 F-4; the shape of `s7_open_work`).

        `None` (the critic's finish closes S4) unless its verdict sends cases back AND a round is left. Then, by the rule of
        `stage_S4`'s rework branch: with a findings file the round WILL run, so the finish says it by `OpenWork` (`--not-complete
        --unresolved --reason`, a pair the controller accepts - no silent `False`, no resume of the critic for a record the driver
        owns, C2-4 K9-4). POSITION INVARIANT (t-909 F-3): `OpenWork` only when that branch runs; with no findings file the
        old `False` stays - one resume of the critic, who writes the findings (judgement).

        INVARIANT, on ANY road (t-919 F-1): an accepted `cases_in_repair` is never followed by a NEW paid critic over unchanged
        cases. The round is registered by `stage_S4`'s tail on the live road; on the recovery road (`_finish_saved_result`,
        `resume_role`) and after a refused finish that came back as `continue` no tail ran, so the next `stage_S4` entry derives
        the owed round from the dispatch records (`s4_repair_owed`) and starts it instead of a critic."""
        last_round = not (isinstance(counted, int) and isinstance(cap, int) and counted < cap)

        def complete(digest: str):
            # X2-7 (a): the acceptance record is written FIRST, from the critic's own form, before the controller accepts the critic (E-X2-7d)
            dispatch = str(getattr(self, "last_dispatch", "") or "") if dispatch_id is None else str(dispatch_id or "")      # F1, as the S2/S3 rule
            form = f"work/handoffs/{dispatch}.yaml" if dispatch else ""
            if self.stage_acceptor("S4"):
                if not dispatch:
                    return self.stage_review_exhausted("S4", "qa-case-designer", dispatch, None, form, unreadable=True,
                                                       text="the saved result of the S4 case critic carries no dispatch id, so its form cannot be found")
                if not self.stage_verdict_known(form):
                    return self.stage_review_exhausted("S4", "qa-case-designer", dispatch, None, form, unreadable=True)
                self.stage_acceptance_write("S4", dispatch)
            if self.case_verdict(digest) not in ("concerns", "review"):
                return None
            if last_round:
                # X2-7 point 7, the ONE changed line of S4: a critic that sends cases back on the last round no longer closes the stage in
                # silence - the conductor decides through the seam (accept with the gap / one more round / ask the person), F-X2-7
                if not self.stage_acceptor("S4"):
                    return None
                import acceptance
                return self.stage_review_exhausted("S4", "qa-case-designer", dispatch,
                                                   acceptance.stage_acceptance(self.pipeline(), "S4") or {}, form)
            findings = self.s4_findings()
            if not findings:
                return False
            import role_digest
            # the cases the critic REJECTED, by the closed state word of its own rows - not its whole scope (t-919 F-3); an
            # unreadable set prints no number (FR-41)
            cases = [str(r["id"]) for r in role_digest.parse(digest).get("rows") or []
                     if str(r.get("state") or "").split(":")[0] == "rejected"]
            lead = (f"the case critic sent {len(cases)} case(s) back for repair" if cases else "the case critic sent work back for repair")
            path = findings.relative_to(self.task_root).as_posix()
            text = (lead + "; S4 was kept open for the repair round" + (": " + ", ".join(cases) if cases else "")
                    + f"; its findings: {path}")
            return OpenWork("cases_in_repair", open_work_reason(text, f"… [list: {path}]"))
        return complete

    def render_appendix(self) -> None:
        """`render_case_appendix.py`: the case appendix, from the pinned cases. S4's last step, and (t-211,
        C10) the gate-entry step that runs it when the critic's refused finish skipped it.
        G2 (C1-7b): a non-zero exit is a `Refusal` (the factory's own, `known = False`): on the normal path nothing runs this again
        (`gate_entry_steps` only when `gate_entry_owed`), and gate A's packet embeds the appendix. The conductor can rerun it (`retry`)."""
        self.py("render_case_appendix.py", "--task-root", str(self.task_root), "--output",
                str(self.task_root / "work/case-appendix.md"), "--plan", str(self.task_root / "test-plan.md"), check=True,
                expect="work/case-appendix.md rendered from the pinned cases")

    def pin_cases(self) -> None:
        _code, out = self.py("case_versions.py", "--task-root", str(self.task_root), "--all", check=True)
        # HF8-6: `--all` records the approved scope itself; what it could not record it says in `scope_note`. Only printed here:
        # the sites that call `revise_plan()` next get the controller's own refusal, the others (a repair round) leave the
        # judging to the critic's start and gate A.
        # `py` joins stdout and stderr, so a stderr line may come last: take the last line that parses as an object.
        note = ""
        for line in reversed(out.strip().splitlines()):
            try:
                answer = json.loads(line)
            except ValueError:
                continue
            if isinstance(answer, dict):
                note = str(answer.get("scope_note") or "")
                break
        if note:
            print("S4: " + note)
        self.py("case_versions.py", "--task-root", str(self.task_root), "--verify", check=True)

    def pinned_cases(self) -> list:
        """The case ids that are pinned: the controller's own reading (`_pinned_links`: a link with a case id AND a version),
        so the driver never sends the critic or a dispatch a case the controller does not count as pinned (CX2-17, AR-13)."""
        from controller import Controller
        return sorted({str(link["case_id"]) for link in Controller(self.task_root)._pinned_links()})

    def unraised_cases(self) -> list:
        """The case files that still hold a Then `unknown` with the ref `raise` (the question was named, never raised).

        Read from the structured `then_oracles` field through `contract` - the reader `gate_preflight.
        check_unraised_questions` uses - never by a phrase (FR-12). [] when nothing says so or the cases cannot be read:
        a reader that cannot read says nothing (P1) and the rehearsal at gate A names what is left."""
        try:
            import contract
            found = []
            for path in contract.case_files(self.task_root):
                entries, _why = contract.then_oracles_from_text(Path(path).read_text(encoding="utf-8", errors="replace"))
                if any(isinstance(e, dict) and str(e.get("ref") or "").strip() == contract.RAISE_REF for e in entries or []):
                    found.append(Path(path).stem)
            return found
        except Exception:
            return []

    def critic_scope(self) -> list:
        """Cases of the plan rows that require independent design review; all pinned cases
        when the plan names none (a critic with no scope reviews whatever it reads)."""
        import case_versions
        return case_versions.review_scope(self.task_root, state=self.controller_state(), pinned=self.pinned_cases())

    def revise_plan(self) -> None:
        """Record the pinned cases as the approved scope, unless the controller already holds exactly them (CX1-11).

        HF8-6: the request is built by `case_versions.scope_request`, the one function `case_versions.py --all` calls too,
        so `--all` has usually recorded the scope already and this call is then a no-op; it stays the stage's own step so a
        failed record is the controller's `Refusal` here (the sites that only pin print the note instead).

        The controller writes the scope in the spelling the case index keys (`TC-001`, `<area>/TC-003` for a number two
        areas hold), so "already holds them" is a comparison of KEYS, by the controller's own rule (`_scope_membership`,
        which reads `_pinned_links`: ONE filter of "pinned", D-2). The idempotency key is the story's REVISION plus the
        scope's KEYS (`content_hash`, N-5; the payload carries the bare ids, the key hashes the keys they resolve to): a
        count replayed an area dropped at the same number, and a content hash alone replayed A -> B -> A (the store
        holds B, the third call returned the first event). An index that cannot be built counts as "not equal" (N-6):
        the bare ids go to the controller, which refuses with its own words (`Refusal`, never a crash of the driver)."""
        import case_versions
        notes: list = []
        request = case_versions.scope_request(self.task_root, notes=notes)    # the one builder; `--all` calls the same (HF8-6)
        for note in notes:
            print("S4: " + note)
        if request is None:
            return
        # CX2-17 C-2 (E43a): the driver takes the orchestrator lease itself at a rollover (`session = driver:<task>:<revision>`) and
        # `Driver.controller` adds no owner, so after a rollover the controller refused this request for a lease it had just
        # handed the driver. The owner is read from the record, as `handoff` does at the rollover (one line, no new method)
        owner = ((self.controller_state().get("leases") or {}).get("orchestrator") or {}).get("owner_session_id")
        self.controller("revise_plan", input_data=dict(request, owner_session_id=owner) if owner else request)

    def rework(self, stage: str, role: str, cases: list, reason: str, *, cause: str,
               purpose: str = "repair_verify", extra=(), complete=False, budget=READ_BUDGET, on_request=None,
               rows=(), words_file: str = "") -> tuple:
        """`on_request(id)`: called with the controller's dispatch id the moment `rework` has it, before any role runs (the S7 loop
        records it, t-698 §20 N9). `cause` has no default: a round's cause is the reviewer's typed word (repair_route), and
        a default here is how every repair once went out as `test_defect`. A round that is not
        about the test says what it was for - the receipt is the only place the retro learns it.
        `complete`: the closing flag of the author's dispatch; a mechanical round on the last
        window is the one that may close S5 (the reviewer is not dispatched again).
        `words_file` (C2-6 §4.2 p.9): the task-root relative file of a PERSON's words, whole (FR-8): the controller gets
        `--words-file` INSTEAD of `--reason` (no `[:1500]`; `reason` is that file's text), and a reason longer than 1500 reaches
        the role as the file's path. `rows`: the plan rows an S1-S3 rework goes back over."""
        if cause != "test_defect" and not str(reason or "").strip():
            raise ValueError(f"rework: a {cause} round needs a non-empty reason - one sentence of what "
                             "happened; it spends none of the repair cap, and the receipt is where the retro reads why")
        words_path = str(self.task_root / words_file) if words_file else ""
        args = ["--stage", stage, "--role", role, *(["--words-file", words_path] if words_path else ["--reason", reason[:1500]]),
                "--purpose", purpose, "--cause", cause]
        if cases:
            args += ["--cases", ",".join(cases)]
        if rows:
            args += ["--rows", ",".join(rows)]
        # TR3-6: POSITION - before `controller rework`; INVARIANT: a drain registers no new dispatch
        self.stop_if_drained()
        self.count_launch()
        if self.on_chain():
            args.append("--parallel-window")
        try:
            packet = self.controller("rework", *args)
        except Refusal as exc:
            raise ReworkRefused(exc.text, retry=exc.retry, files=exc.files, dispatch=exc.dispatch) from exc
        request = packet.get("request") or {}
        if not request.get("id"):
            raise ReworkRefused("rework returned no dispatch id: " + json.dumps(packet)[:600])
        if on_request:
            on_request(request["id"])
        given = {"id": request["id"], "scope": cases, "reason": reason}
        if words_path and len(reason) > 1500:        # the role is told WHERE the whole words are, never a cut of them (FR-8)
            given["line"] = (f"Rework reason: the person's words ({len(reason)} characters) are in {words_path}; "
                             "read the whole file before you start.")
        # t-2277 batch 2b D (critic t-2513 F1): `rework S1` of a story with a reference stand re-enters the reference window - the scout's
        # rework does not close S1 (the window is its last dispatch), then the runner walks the old version again and `put` replaces the
        # snapshot (`--replace`, the file exists). POSITION: after the controller registered the rework, in the ONE method every code road of
        # a rework passes. INVARIANT: a story with no reference (`s1_window_owed` None) runs `run_role` exactly as before.
        window = self.s1_window_owed(stage, role)
        done = self.run_role(stage, role, scope=list(request.get("scope") or cases), extra=list(extra),
                             complete=False if window else complete, rework=given, budget=budget)
        if window:
            self.s1_reference_window(stage, window)
        return done

    def repair_budget(self, stage: str, role: str, scope, **packet) -> dict:
        """The window's rounds as the controller counts them from the journal itself: counted, cap,
        mechanical, mechanical_cap. The driver keeps no counter of its own - a local one reset on every
        restart (B-007). Raises Refusal when the controller cannot answer; the caller closes the
        window instead of guessing a number. `packet`: the extra `prepare` options of a role whose packet needs them (the new-mode `qa-runner`:
        `execution_kind`, and `manual_case_ids` of a manual block; X7-6c) - empty values are left out."""
        options = {"stage": stage, "role": role, "scope": list(scope or []), **{k: v for k, v in packet.items() if v}}
        packet = self.controller("prepare", input_data=options)
        budget = packet.get("repair_budget")
        if not isinstance(budget, dict):
            raise Refusal(f"controller prepare for {stage} {role} carries no repair_budget: " + json.dumps(packet)[:400])
        return budget

    def budget_or_none(self, stage: str, role: str, scope, ref: str = "", **packet) -> dict | None:
        """`repair_budget`, or None after saying so: the loops read None as "no round, close" and never
        substitute a number of their own. The controller that cannot count is the factory's own
        defect, so it is printed and filed (owner factory; `--ref` is mandatory in log_append)."""
        try:
            return self.repair_budget(stage, role, scope, **packet)
        except Exception as exc:
            error = " ".join(str(getattr(exc, "text", "") or exc).split())[:300] or type(exc).__name__
            seen = getattr(self, "_budget_unknown", None)       # ONE defect per window per process: the loop and the seam's gate both read
            if seen is None:
                seen = self._budget_unknown = set()
            if (stage, role, tuple(scope or [])) in seen:
                return None
            seen.add((stage, role, tuple(scope or [])))
            print(f"repair budget unknown: {error}")
            # T4 (C1-7b): the window is closed with no round either way (the return below), and the line above already said so
            self.py_trace("log_append.py", "--event", "defect_found", "--task", self.task, "--by", "driver",
                          "--ref", ref or getattr(self, "last_dispatch", "") or f"{stage}-{role}",
                          "--notes", f"owner: factory - the repair budget of {stage} {role} could not be read "
                                     f"({error}); the window was closed with no repair round",
                          why="the window closes with no repair round whether or not the defect row lands, and no decision of this story reads the row")
            return None

    def settle_role_questions(self, stage: str) -> list:
        """X2-6 (E-B6, E-B7): the questions the roles of `stage` raised into the register (`question_register.py --raise --from-handoff`,
        rows with `asked_by`) that nobody has answered. Each is given to the conductor through the seam (P22) with the paths the role read; a
        question whose answer lies on disk is CLOSED by the conductor with `question_register.py --answer ... --by driver --where "stage ran"`
        and the source (`<path>#<anchor>: <the answer>`) in the words - never sent to a person. WHETHER the answer is on disk is the
        conductor's judgment: this method closes nothing itself. Returns the rows still open that carry a `why_person` class: only those
        reach a person, batched at the next gate (gate A, gate B), and the role goes on by its `recommendation` meanwhile. A row left open
        with no class is printed as a gap and is NOT returned: a question with no class never reaches a person. Nothing open: `[]`, no call."""
        import question_register as QR

        def mine() -> list:
            return [q for q in QR.load(self.task_root)["questions"]
                    if q.get("asked_by") and q.get("stage") == stage and QR.is_open(q) and q.get("status") != "with_designer"]

        waiting = mine()
        if not waiting:
            return []
        shown, files = [], []
        for q in waiting:
            shown.append(f"- {q['id']} (asked by {q['asked_by']}, class: {q.get('why_person') or 'none'}; row_hash {q.get('row_hash')}): "
                         f"{q.get('question')}\n  read: {', '.join(q.get('read') or []) or 'nothing named'}\n"
                         f"  the role goes on with: {q.get('recommendation') or 'nothing stated'}\n  answers: "
                         + "; ".join(f"{QR.LETTERS[i]}) {r.get('reading')}" for i, r in enumerate(q.get("readings") or []) if isinstance(r, dict)))
            for ref in q.get("read") or []:
                for base in (self.task_root, self.project):
                    candidate = base / str(ref).split("#", 1)[0]
                    if candidate.is_file():
                        files.append(candidate)
                        break
        lead = (f"Questions the roles of {stage} raised while they worked. For each: read the paths it names; if the answer is THERE, close it "
                "now with `question_register.py --task " + self.task + " --answer <id> --reading <letter> --by driver --where \"stage ran\" "
                "--register-hash <its row_hash> --words \"<path>#<anchor>: <the answer you found>\"` (the words name the source). Close nothing "
                "you cannot ground in a file. A question that stays open goes to the person only when it has a class (`why_person`), at the "
                "next gate; ask the person now only for `access`. The role's work does not wait.\n\n" + "\n".join(shown))
        self.no_move({"why": "refusal", "kind": "conductor", "stage": stage, "dispatch": "", "text": lead, "lead": lead, "files": files})
        left = mine()
        for q in left:
            if not q.get("why_person"):
                print(f"role question {q['id']} ({stage}, {q['asked_by']}) has no person class and no answer on disk: left as a gap, not asked")
        return [q for q in left if q.get("why_person")]

    def newest(self, pattern: str) -> Path | None:
        files = [p for p in self.task_root.glob(pattern) if p.is_file()]
        return max(files, key=lambda p: p.stat().st_mtime) if files else None

    def stage_scope(self, stage: str, kind: str = "") -> dict:
        data = {"stage": stage}
        if kind:
            data["execution_kind"] = kind
        return self.controller("stage-scope", input_data=data)

    # --- the stand: asked ONCE, before anything runs on it (t-017 D2: B-005, owner D-0014) ----------
    #
    # S0 used to halt the whole story on a stand that did not answer - a stop, and a person's word,
    # for a story that had read no stand yet - and a project with no stand at all sailed to S5 and
    # stopped there in a phase file's prose. Now S0 only records the fact (`environment_pending`,
    # the name kept), and the ONE place that asks is `stand_check`, at the entry of the two stages
    # that put something on a stand. A person's word passes S5 and S6 together: it is recorded for
    # the stage that asked and read for both, so the second stage never asks again.
    STAND_STAGES = ("S5", "S6")

    def stand_names(self) -> list:
        """The stands the project's config records, by name."""
        return [str(e.get("name")) for e in self.config.get("environments") or []
                if isinstance(e, dict) and e.get("name")]

    @staticmethod
    def probe_reason(out: str) -> str:
        """The first line `env_probe.py` gives as the reason the stand cannot be used, on one line,
        cut at 200 characters. It reads our own script's output shape (the list under `THE
        ENVIRONMENT CANNOT BE USED`, or the one-line `ENVIRONMENT: not configured`), never
        anybody's words (FR-12); nothing found is said as nothing found (FR-41)."""
        lines = [line.strip() for line in str(out or "").splitlines()]
        found = ""
        for index, line in enumerate(lines):
            if line.startswith("THE ENVIRONMENT CANNOT BE USED"):
                found = next((item[2:].strip() for item in lines[index + 1:] if item.startswith("- ")), "")
                break
        found = found or next((line for line in lines if line.startswith("ENVIRONMENT:")), "")
        found = found or next((line for line in reversed(lines) if line), "") or "the probe printed nothing"
        return found if len(found) <= 200 else found[:200] + Driver.CUT

    STAND_STEPS = {"S5": "writing the automated tests and running them",
                   "automation": "running the automated tests",
                   "manual": "carrying out the manual checks",
                   "both": "running the automated tests and carrying out the manual checks"}

    def stand_question_text(self, stage: str, environment: str, names: list, kind: str = "") -> str:
        """The question (references/human-questions.md): what was done, why the stand cannot be
        derived, one question, the closed answers. Nothing in it is the probe's own vocabulary -
        that goes in the details file. `kind` is what the stage is about to do on the stand
        (S6: automation, manual, or both) - a manual-only S6 must not say "automated tests"."""
        task = self.task
        step = self.STAND_STEPS["S5" if stage == "S5" else (kind if kind in self.STAND_STEPS else "automation")]
        head = (f"The requirements, the test plan and the test cases for {task} are done. The next "
                f"step is {step}, and for that I need a stand I can trust. I could not confirm one: ")
        if environment:
            head += (f"the stand `{environment}` did not answer when I checked it just now. ")
        elif names:
            head += "no stand has been chosen for this story yet. "
        else:
            head += "this project records no stand, so there is nothing to run them on yet. "
        head += ("I have not run anything on a stand and I have not switched to another one on my "
                 "own: which stand the tests may touch is your decision.")
        options = []
        if environment:
            options.append({"answer": "retry", "token": "retry", "slots": {"what": f"bring `{environment}` up, or fix what stops it answering"},
                            "says": f"bring `{environment}` up, or fix what stops it answering; I check it again"})
        elif not names:
            # t-363 B3 (the Lead's second site of the class): the plugin's command is something to TYPE, so it stands in
            # the answer block (human-questions.md rule 5), never in the body; the body names it as "the onboarding step
            # named below". ONE shape with the other sites (t-373 F7): `stand_check` passes it as `Person.answer_note`
            # (`stand_answer_note`), which `ask()` renders in the one `---/Answer:` block.
            options.append({"answer": "retry", "token": "retry", "slots": {"what": "record a stand with the onboarding step named below"},
                            "says": "record a stand with the onboarding step named below; I ask again with the stands that are then recorded"})
        others = [name for name in names if name != environment]
        if others:
            options.append({"answer": "stand name",
                            "says": ("answer with the name of another configured stand: " if environment
                                     else "answer with the name of the stand to use: ")
                                    + ", ".join(f"`{name}`" for name in others) + "; I check that one"})
        options.append({"answer": "go on", "token": "go on",
                        "says": "go on without a stand" + ("; the tests are still written, but none is run on a stand" if stage == "S5" else "")
                                + ", and the story carries a line saying it was your decision"})
        # C1-6b (S6, A7): the priced section replaces the lettered list; the site's own words stay in `says`, the three price lines are
        # the data row of `s6.stand_confirm`
        return self.closed_question("s6.stand_confirm", head + "\n\nWhat I need from you is one of these:", options)

    def stand_check(self, stage: str, kind: str = "") -> None:
        """Before S5/S6 puts anything on a stand: is one confirmed for this story?
        (`kind`: what S6 is about to run - automation, manual or both - for the question's words.)

        Returns at once for a confirmed stand (a name, and `environment_pending` false) - a stand
        confirmed at S0 is NOT probed again (owner decision F4). Otherwise: a person's word that
        passes the block `stand not confirmed` (recorded on S5 or S6 - one word covers both) lets
        the stage go on without one; else, when a name is recorded, the stand is probed and a
        probe that exits 0 confirms it; else the person is asked. A legacy story whose pipeline
        says `environment: null, environment_pending: false` is asked too - that pair was what the
        old S0 wrote for a project with no stand.

        INVARIANT (why this stands where it does): it is called only by a stage that has something
        to run - after S5's two refusals and S6's "nothing to execute" close - and before its first
        role, so no S5/S6 role starts on an unconfirmed stand that no word has passed, and a
        stage with nothing to run never asks. A dispatch registered but never launched
        (`relaunch`, and `wait_existing_job` on one the driver never started) STARTS a role, so it
        comes through here too; a dispatch already begun and resumed with the person's words
        (`resume_checkpoint`, `resolve_return`, `wait_existing_job` with a saved answer) does not
        and is not gated.

        The flag `stand_question` is set in ONE place, `ask()`, from the Person this raises: the
        answer branch of `take_answer` takes only the answer to THIS question, never the answer
        to another question of the same stage (`environment_job` asks kind `environment` at S5 too)."""
        pipeline = self.pipeline()
        environment = str(pipeline.get("environment") or "")
        if self.state.pop("stand_question", None):      # set again below only when a question is raised
            self.save_state()                           # so a stale one can never claim another question's answer
        if environment and not pipeline.get("environment_pending"):
            return
        block = (f"{waiver.STAND_NOT_CONFIRMED_BLOCK}: " + (f"stand `{environment}` is not confirmed as usable"
                                                            if environment else "no stand is confirmed for this story"))
        for owner in self.STAND_STAGES:
            _blocking, passed = waiver.split_overridden([block], pipeline, owner)
            if passed:
                print(f"{stage}: {block} - passed by the person's word "
                      f"\"{self.s0_quote(passed[0].get('decision'))}\"; going on without a confirmed stand")
                return
        details = "no stand is recorded for this story (environment: none)"
        if environment:
            code, out = self.py("env_probe.py", "--env", environment, "--task", self.task)
            if code == 0:
                self.py("stage_done.py", "--task", self.task, "--set", "environment_pending=false", check=True)
                print(f"{stage}: stand `{environment}` answered the check; it is confirmed")
                return
            details = out or "the probe printed nothing"
        # A7 (C1-6b): a seam question - `retry` / `go on` carry the seam's own moves (`person_does`, `go_on_as_is` + the block), so
        # `take_seam_answer` executes them; the stand's NAME is the site's own door (`_take_stand_answer`)
        # remains: the stand question is a seam question (priced, `offered`): retry / go on run the seam's executors, the name has its own, other words go to the seam
        person = self.site_seam_person("environment", self.stand_question_text(stage, environment, self.stand_names(), kind), stage,
                                       block=waiver.STAND_NOT_CONFIRMED_BLOCK, details=details,
                                       answer_note=human_text.onboarding_note(environment, self.stand_names()))
        person.stand_stage = stage       # read by `ask()`, which sets the flag - and clears it for every other Person
        raise person

    # --- the BUILD the stand runs: asked once the stand itself is confirmed (t-300 N1b) -----------------------------
    #
    # `stand_check` settles WHICH stand; `build_check` settles whether that stand runs the build THIS story is about. It
    # follows `stand_check` at the same four sites (the two stage entries, a never-launched dispatch, a relaunch), so it
    # runs only for a stage that has something to run, before its first role. The ladder that READS the stand is the
    # probe's (runtime_probe.py, through the project's registered probe argv, as a rehearsal: `--no-evidence`, and
    # `--task-root` so the story's own word is the one read); the driver reads the FIELDS of its record, never a sentence
    # (FR-12). A question is raised only when the record says so (`asks_person`, or a proven `mismatched`) - the ladder
    # always runs first (FR-50) - and the five variants of its text, the closed answers and the executor commands are
    # DATA (references/build-identity-methods.json, FR-13).
    BUILD_DISPOSITIONS = {"automation": ("automate",), "manual": ("manual-agent",), "both": ("automate", "manual-agent"),
                          "": ("automate", "manual-agent")}
    BUILD_ANSWER_STUB = "\n---\nAnswer: write your words to a file and run\n  python story_run.py --task T --answer <file>\n"
    BUILD_FRAGMENT_RULES = ("filler", "too_short", "no_how_to_answer")      # whole-question rules a one-line status never meets
    BUILD_SHA = re.compile(r"[0-9a-f]{40}")

    @staticmethod
    def build_join(value) -> str:
        return "\n".join(str(item) for item in value) if isinstance(value, list) else str(value)

    def build_fit(self, template: str, slots: dict, plain: dict, whole: bool) -> str:
        """The template with its slots filled - and, when what was filled in breaks a rule of references/human-questions.md
        (a quoted command or a file name with a flag or a script name in it, a docker message), the same text with the
        `plain` words in those places instead (FR-6: the details go to the details file). `whole`: a question, so the
        answer block is under it when it is checked; a status line is checked for the shape rules only."""
        import human_text

        def broken(text: str) -> list:
            found = human_text.problems(text + self.BUILD_ANSWER_STUB if whole else text)
            return [p for p in found if whole or p["rule"] not in self.BUILD_FRAGMENT_RULES]
        text = template.format(**slots)
        if broken(text):
            text = template.format(**dict(slots, **plain))
        return text

    def build_profiles(self, stage: str, kind: str, cases) -> list:
        """The profiles of what this stage is about to run, in the project's profile order: S5 asks about the cases of the
        WINDOW it is entering (an e2e-ui question never blocks an api-only window), S6 about the dispatch's own kind (and
        scope); `cases` None means the whole stage. Never `all`: a kind the driver does not know reads as both halves, but a
        scope that is empty names nothing (INVARIANT: a question about a profile this dispatch does not run is a question
        nobody can use)."""
        import gate_preflight
        wanted = ("automate",) if stage == "S5" else self.BUILD_DISPOSITIONS.get(kind, self.BUILD_DISPOSITIONS[""])
        found = gate_preflight.stand_profiles(self.config, self.task_root, wanted)
        keep = None if cases is None else {str(case) for case in cases}
        order = list(dict.fromkeys(str(p.get("profile_id")) for p in self.config.get("profiles") or [] if isinstance(p, dict)))
        return [name for name in order if name in found and (keep is None or keep & {str(c) for c in found[name].get("cases") or []})]

    def build_run_probe(self, profile: str, derive: bool = False, stand: str = "") -> tuple:
        """(record, why, said): the project's registered probe for this profile, run as a rehearsal (`runtime_probe.rehearsal_argv`:
        `--task-root` and `--no-evidence`, the factory's own script only - a project's own script is never handed a flag it
        does not know, AE16). `why` is a key of `question.lines` when there is no record: no probe is registered, or it did
        not finish, could not start, failed, or printed no JSON object (FR-3: the factory's, never a question). `derive`
        (EP1-28, S6 manual only): with no registered probe, the default one over the profile's checkout
        (`execution_request.stand_probe_spec`); `said` is then why there is none (three causes: no checkout, two repositories,
        two stands), else ""."""
        import execution_request
        from runtime_probe import rehearsal_argv
        if derive:
            spec, said = execution_request.stand_probe_spec(self.config, profile, stand)
        else:
            spec, said = execution_request.registered_probe(self.config, profile), ""
        if spec is None:
            return None, "no_probe", said
        try:
            done = subprocess.run(rehearsal_argv(spec["argv"], self.task_root), cwd=str(self.project / spec["cwd"]), env=self.env,
                                  capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=spec["timeout_s"])
        except subprocess.TimeoutExpired:
            return None, "why_timeout", ""
        except OSError:
            return None, "why_start", ""
        if done.returncode != 0:
            return None, "why_failed", ""
        try:
            record = json.loads(done.stdout)
        except ValueError:
            return None, "why_no_json", ""
        return (record, "", "") if isinstance(record, dict) else (None, "why_no_json", "")

    def build_check(self, stage: str, kind: str = "", cases=None) -> None:
        """After `stand_check`: does the confirmed stand run the build this story is about? One rehearsal per profile of what
        is about to run; a verdict that needs nobody is ONE printed line; a verdict that needs the person is a `Person`
        (kind `stand_identity`) - ONE per call, the first profile that needs it (the next is asked at the next entry).

        INVARIANT (why it stands where it does): it runs only after a stand is confirmed or passed by a person's word, and
        before the first role; a stand passed by word (no stand name, or `environment_pending` still true) has nothing to
        read, so it returns at once; a stage with nothing to run never reaches it; a dispatch already begun and resumed
        with the person's words is not gated. The flag `build_question` is set in ONE place, `ask()`, from the Person this
        raises, and is gone for every other question (t-037). ERROR DIRECTION: a doubt is a line, never a question and
        never a silent pass - the run path still refuses a build nobody could prove."""
        if self.state.pop("build_question", None):      # set again below only when a question is raised
            self.save_state()
        pipeline = self.pipeline()
        stand = str(pipeline.get("environment") or "")
        if not stand or pipeline.get("environment_pending"):
            return
        import stand_identity as SI
        lines = SI.data()["question"]["lines"]      # every console line of this check is data (FR-13); the raw error text goes to stderr
        try:
            profiles = self.build_profiles(stage, kind, cases)
        except Exception as exc:      # a doubt about WHICH profiles is a line (the run path decides), never a stop
            print(f"story_run: build check, profiles: {type(exc).__name__}: {' '.join(str(exc).split())[:300]}", file=sys.stderr)
            print(lines["check_broke_profiles"].format(stage=stage, stand=stand))
            return
        if not profiles:
            print(lines["no_profiles"].format(stage=stage))
            return
        import surfaces
        for profile in profiles:
            try:
                # EP1-41c: the stand is the PROFILE's own (surfaces.stand_of_profile, the one reader). A project that names no
                # `surface` gets `stand` back unchanged (the web road); a profile with no stand of its own is a line and no
                # question - nobody is asked about a build that no stand of this project runs. The question's `environment`
                # is then the profile's stand, so the word lands on the key the probe reads (`task_confirmation`).
                stand_p = surfaces.stand_of_profile(self.config, profile, stand)
                if not stand_p:
                    print(lines["no_profile_stand"].format(stage=stage, stand=stand, profile=profile))
                    continue
                # F-1: only the manual half of S6 derives a probe nobody registered; S5 and automation keep the line
                # `no_probe` (the S5 door writes the entry, EP1-24)
                record, why, said = self.build_run_probe(profile, derive=stage == "S6" and kind != "automation", stand=stand_p)
                line, person = self.build_outcome(stage, kind, stand_p, profile, record, why, said)
            except Exception as exc:      # the check itself broke: said, and the run goes on (the run path still decides)
                print(f"story_run: build check, {profile}: {type(exc).__name__}: {' '.join(str(exc).split())[:300]}", file=sys.stderr)
                print(lines["check_broke"].format(stage=stage, stand=stand, profile=profile))
                continue
            if line:
                print(line)
            if person is not None:
                raise person

    def build_method_words(self, q: dict, row, name: str) -> str:
        """The words for the way a build was read: the registry row's own when it is the row's method (a `command` names its
        line), else the data's for the method (FR-13)."""
        import stand_identity as SI
        if not name:
            return q["method_unknown"]
        return SI.method_words(row if isinstance(row, dict) and row.get("method") == name else {"method": name})

    @staticmethod
    def build_names(files, q: dict) -> str:
        """File names for a line of the build question: the first `limits.files_shown` in code spans, the rest counted
        (`files_more`). The ONE spelling for the mismatch question, the not-compared line and the accepted-files line."""
        names = [str(n) for n in files or []]
        cap = int(q["limits"]["files_shown"])
        return ", ".join(f"`{n}`" for n in names[:cap]) + (" " + q["files_more"].format(more=len(names) - cap)
                                                           if len(names) > cap else "")

    def build_outcome(self, stage: str, kind: str, stand: str, profile: str, record, why: str, said: str = "") -> tuple:
        """(line, person) for one profile's probe record, chosen by FIELDS: `result`, `asks_person`, `differing_files`,
        `deployed_source_revision`, `not_shipped_files` (a `matched` that did not compare some files), `accepted_files` and
        the confirmation's `kind` (a person's `test as is`). Exactly one of the two is set."""
        import stand_identity as SI
        q = SI.data()["question"]
        row = SI.state(self.project)["in_force"].get((stand, profile))
        base = {"stage": stage, "stand": stand, "profile": profile, "method": "", "date": "", "error": "", "why": ""}

        def line(key: str, **slots) -> str:
            return self.build_fit(q["lines"][key], dict(base, **slots), q["plain_line"], whole=False)
        if record is None:
            if why == "no_probe":
                # EP1-28: when the default probe could not be worked out, the line says why (the three causes of `None`)
                # a person reads the refusal's plain half (no flag in it, FR-6); the whole of it is the role's
                return (line("no_probe_said", why=str(getattr(said, "plain", said))) if said else line("no_probe")), None
            return line("probe_failed", why=q["lines"][why]), None
        result = record.get("result")
        prov = record.get("provenance") if isinstance(record.get("provenance"), dict) else {}
        if result in ("matched", "person_confirmed", "not_applicable"):
            import profile_contract
            if not profile_contract.acceptable_provenance(record, profile_contract.ACCEPTS, rehearsal=True):
                return line("probe_unrecognised"), None
            if result == "not_applicable":
                return line("not_applicable"), None
            if result == "person_confirmed":
                at = str((record.get("person_confirmation") or {}).get("at") or "")[:10] or q["no_date"]
                if (record.get("person_confirmation") or {}).get("kind") == "content_accepted":
                    # FB-8: ONE line for this kind, in place of the two base lines (no sentence claims an image binding that
                    # did not happen, and none says the build was confirmed: the person accepted the files as they are)
                    names = self.build_names(record.get("accepted_files"), q)
                    return line("person_content", date=at, files=names), None
                no_image = str(record.get("observed_runtime_identity") or "").startswith("person-confirmed:")
                return line("person_confirmed_no_image" if no_image else "person_confirmed", date=at), None
            name = str(prov.get("identity_kind") or ("sources" if prov.get("source_linkage") == "verified_content" else ""))
            not_shipped = record.get("not_shipped_files")
            if isinstance(not_shipped, list) and not_shipped:
                # FB-8: a build input the container does not hold was not compared - never shown as a plain verified build
                return line("matched_not_shipped", method=self.build_method_words(q, row, name),
                            files=self.build_names(not_shipped, q)), None
            return line("matched", method=self.build_method_words(q, row, name)), None
        if result == "unknown":
            asks = record.get("asks_person")
            if asks in ("how", "confirm"):
                # EP1-28: `how` on a record that names no container is the stand nobody runs in one (a host process): the
                # question is "is that commit there", not "how do I read the image" - chosen by the FIELD (FR-12)
                no_container = asks == "how" and not str(record.get("container") or "").strip()
                # EP1-41e: `how` on a DEVICE stand (the field `device_stand`, set by the probe) is "is this build the one", chosen
                # BEFORE the container test: a device has no container, so the `no_container` words would not fit it
                device = asks == "how" and record.get("device_stand") is True
                return "", self.build_person(stage, kind, stand, profile, record, row,
                                             "confirm" if asks == "confirm" else "device_build" if device
                                             else "no_container" if no_container else "how")
            if row and row.get("method") == "person_confirms":
                # docker did not answer on a stand the person checks themselves: nothing to ask (their word is already
                # there, FR-7) and nothing to read - said as a status, never a question
                return line("docker_down_confirms", date=str(row.get("recorded_at") or "")[:10] or q["no_date"],
                            method=SI.method_words(row)), None
            return line("unread", error=str(record.get("error") or q["no_error"])), None
        if result == "mismatched":
            sources = bool(record.get("differing_files")) or prov.get("deployed_source_revision") == "content_mismatch"
            return "", self.build_person(stage, kind, stand, profile, record, row, "mismatched_sources" if sources else "mismatched")
        return line("probe_unrecognised"), None

    def build_person(self, stage: str, kind: str, stand: str, profile: str, record: dict, row, variant: str) -> Person:
        """The question for one profile: the variant's text with its slots filled from the record's FIELDS, the prefixes the
        record asks for on top (`registry_error`, `registry_method_failed`, `voided`: FR-7 - the text moves when the
        situation moved), the factory's own words in the details file, and the packet `ask()` turns into the flag."""
        import stand_identity as SI
        q = SI.data()["question"]
        prov = record.get("provenance") if isinstance(record.get("provenance"), dict) else {}

        def sha(value) -> str:
            return value if isinstance(value, str) and self.BUILD_SHA.fullmatch(value) else ""
        expected = sha(record.get("expected_source_revision"))
        deployed = sha(prov.get("deployed_source_revision")) or sha(record.get("build_sha"))
        identity = str(record.get("observed_runtime_identity") or "")
        image = identity if re.fullmatch(r"image:sha256:[0-9a-f]{64}", identity) else ""
        if not image:
            # FB-8: a content mismatch names no build, but the probe read the image that held the bytes: the word binds to it
            seen = str(record.get("observed_image") or "")
            image = seen if re.fullmatch(r"image:sha256:[0-9a-f]{64}", seen) else ""
        voided = record.get("voided") if isinstance(record.get("voided"), dict) else {}
        failed = str(record.get("registry_method_failed") or "")
        files = [str(name) for name in record.get("differing_files") or []]
        names = self.build_names(files, q)
        docker = ""
        if variant == "no_container":
            # EP1-28 (H-7): what docker runs on this machine, so the person can say the application is in one of them. No
            # line when docker is absent, silent or runs nothing (never an error); at most `limits.containers_shown`
            # names, the rest counted. `deployed` stays the person's word; a name they give is checked by the conductor's
            # move before anything is recorded.
            try:
                import runtime_probe
                running = [str(name) for name, _image in runtime_probe.containers()]
            except Exception:
                running = []
            if running:
                cap = int(q["limits"]["containers_shown"])
                shown = ", ".join(f"`{n}`" for n in running[:cap]) + (" " + q["files_more"].format(more=len(running) - cap)
                                                                     if len(running) > cap else "")
                docker = "\n" + q["no_container_docker_line"].format(containers=shown) + "\n"
        tried = [str(t.get("outcome")) for t in record.get("tried") or [] if isinstance(t, dict) and t.get("outcome")]
        more = record.get("tried_more") if isinstance(record.get("tried_more"), int) else 0
        tried_words = ("; ".join(tried) + (f"; {q['tried_more'].format(more=more)}" if more else "")) if tried else q["no_tried"]
        repo = SI.repo_for(self.config, profile)
        name = str(prov.get("identity_kind") or "")
        slots = {"task": self.task, "step": self.STAND_STEPS["S5" if stage == "S5" else (kind if kind in self.STAND_STEPS else "automation")],
                 "stand": stand, "profile": profile, "code": q["code"]["named" if repo else "unnamed"].format(repo=repo),
                 "short": expected[:12], "tried": tried_words, "registry": SI.registry_rel(), "deployed_short": deployed[:12],
                 "method": self.build_method_words(q, row, name), "files": names, "count": len(files), "what": str(voided.get("what") or ""),
                 "docker": docker,
                 "why": failed, "error": str(record.get("error") or ""),
                 "date": (str(row.get("recorded_at") or "")[:10] if row else "") or str(voided.get("earlier_at") or "")[:10] or q["no_date"],
                 "failed_date": (str(row.get("recorded_at") or "")[:10] if row else "") or q["no_date"],
                 "failed_method": SI.method_words(row) if row else q["plain"]["failed_method"],
                 "voided_date": str(voided.get("earlier_at") or "")[:10] or q["no_date"]}
        prefixes = []
        if record.get("registry_error"):
            prefixes.append(q["prefixes"]["registry_error"])
        if failed and row:
            prefixes.append(q["prefixes"]["method_failed"])
        if voided.get("what"):
            prefixes.append(q["prefixes"]["voided"])
        spec = q["variants"][variant]
        plain = {key: value.format(count=len(files)) for key, value in q["plain"].items()}
        if variant == "device_build":
            # EP1-41e: what the device holds, and what voids the word - both in words of the variant's own data. A promise is made
            # only about what the code can see: with the file hashed, a different build voids the word; with the hash unread, only
            # a different version does (the record's `limitation`); with no build read at all, nothing ties the word to a build.
            seen = str(record.get("observed_device_build") or "")
            kind_of = "voids_unseen" if not seen else "voids_version" if record.get("limitation") else "voids_build"
            slots.update({"device_build": spec["device_has"].format(line=seen) if seen else spec["device_unread"],
                          "device_voids": spec[kind_of]})
            plain["device_build"] = spec["device_unread"]
        template = " ".join(prefixes) + ("\n\n" if prefixes else "") + self.build_join(spec["text"])
        text = self.build_fit(template, slots, plain, whole=True)
        details = [f"stand `{stand}`, {profile} tests - what the check said: {record.get('error') or 'nothing'}"]
        details += [f"tried - {t.get('method')}: {t.get('outcome')}" for t in record.get("tried") or [] if isinstance(t, dict)]
        details += [f"{label}: {record[field]}" for label, field in (("remedy", "remedy"), ("the record of ways", "registry_error"),
                                                                       ("the way you gave", "registry_method_failed")) if record.get(field)]
        if files:
            details.append("files that differ: " + ", ".join(files))
        person = Person("stand_identity", text, stage, details="\n".join(details))
        person.build_question = {"stage": stage, "kind": kind, "environment": stand, "profile": profile, "variant": variant,
                                 "revision": expected, "image": image, "deployed": deployed, "method_words": slots["method"],
                                 "differing_files": files, "content": str(record.get("content_identity") or ""),
                                 "checkout": str(record.get("checkout") or ""),
                                 "answers": list(spec["answers"]), "text": text, "reasked": False}
        return person

    @classmethod
    def build_peel(cls, text: str) -> str:
        """The answer without a BOM and without the pairs of quotes or backquotes a person's editor put round it (case kept)."""
        text = str(text or "").replace(cls.BOM, "").strip()
        again = True
        while again and len(text) >= 2:
            again = False
            for opening, closing in cls._PEEL:
                if text[0] == opening and text[-1] == closing:
                    text, again = text[1:-1].strip(), True
                    break
        return text

    @classmethod
    def build_read_answer(cls, words: str, offered: list, forms: dict) -> dict:
        """The answer as ONE line that is exactly one form of the data (`answers.forms`): `{"form": name, "arg": text}`, or
        `{"form": "", "why": ...}` for anything else - empty, several lines, prose, another language, a form this question
        did not offer. The code reads the form word (case and the closing `.`/`!` do not matter) and what the form says may
        follow it; it never reads a meaning (FR-12). A commit after `deployed` or `test deployed` must LOOK like one (7 to 40
        hex characters): other words after the form are the person's own, and are not read. The same holds for every form that
        takes a value: its shape is `answers.forms.<form>.value` (a label is one word, a path is one word that starts with
        `/`, a command is the rest of the line); a value that misses it makes the answer NOT this form (t-366 F3)."""
        lines = [line.strip() for line in cls.build_peel(words).splitlines() if line.strip()]
        if not lines:
            return {"form": "", "why": "the answer is empty"}
        if len(lines) > 1:
            return {"form": "", "why": "the answer has more than one line"}
        line = cls.build_peel(lines[0])
        for name in sorted(forms, key=len, reverse=True):
            spec = forms[name]
            word = str(spec.get("word") or name)
            found = re.fullmatch(r"(?is)" + r"\s+".join(re.escape(w) for w in word.split()) + r"(?P<stop>[.!]?)(?:\s+(?P<arg>.*))?", line)
            if not found:
                continue
            kind, arg = str(spec.get("arg") or "none"), (found.group("arg") or "").strip()
            if (found.group("stop") and arg) or (kind == "none" and arg):
                continue
            if kind == "commit" and arg:
                arg = arg.rstrip(".!").lower()
            if kind in ("optional", "required") and spec.get("peel_arg"):
                arg = cls.build_peel(arg)
            # t-366 F3: the shape of the value is DATA (`value`, as a whole): prose where a label or a path belongs is not this
            # form - the whole answer goes to the conductor, never into a registry row (a label that is a sentence)
            if arg and spec.get("value") and not re.fullmatch(str(spec["value"]), arg):
                continue
            if name not in offered:
                return {"form": "", "why": f"`{name}` is not one of the answers this question offers", "named": name}
            return {"form": name, "arg": arg}
        return {"form": "", "why": "the words are not one of the answers"}

    @staticmethod
    def build_expand(argv: list, slots: dict) -> list:
        """An executor template with its slots filled. A `?--flag` followed by its value is dropped when the value is empty
        (no image digest was read; `label` with no name)."""
        out, index = [], 0
        while index < len(argv):
            token = str(argv[index])
            if token.startswith("?"):
                value = str(argv[index + 1]).format(**slots) if index + 1 < len(argv) else ""
                if value.strip():
                    out += [token[1:], value]
                index += 2
                continue
            out.append(token.format(**slots))
            index += 1
        return out

    def build_commit_of(self, pending: dict, name: str) -> str:
        """The full commit of THIS story's checkout that `name` (7 to 40 hex characters) stands for, or '' when it is not a
        commit of it (git says so, git cannot be run, or the packet names no checkout). ERROR DIRECTION: toward ''."""
        checkout = str(pending.get("checkout") or "")
        if not checkout:
            return ""
        try:
            done = subprocess.run(["git", "-C", str(self.project / checkout), "rev-parse", "--verify", "--quiet", f"{name}^{{commit}}"],
                                  capture_output=True, text=True, timeout=20)
        except (OSError, subprocess.TimeoutExpired):
            return ""
        found = done.stdout.strip()
        return found if done.returncode == 0 and self.BUILD_SHA.fullmatch(found) else ""

    def build_answer_slots(self, pending: dict, words: str, arg: str) -> dict:
        return {"task": self.task, "stand": str(pending.get("environment") or ""), "profile": str(pending.get("profile") or ""),
                "revision": str(pending.get("revision") or ""), "deployed": str(pending.get("deployed") or ""),
                "image": str(pending.get("image") or ""), "content": str(pending.get("content") or ""), "words": words,
                "arg": arg}

    def take_build_answer(self, words: str, qtext: str, stage: str, dispatch: str) -> None:
        """The answer to `build_check`'s question - and only to it (`ask()` sets the flag from that Person alone).

        CLOSED forms, read by code (`build_read_answer`, the forms are `answers.forms` of the data file): the driver runs the
        form's executor commands ITSELF (FR-48) - the person is never shown a script name, a flag or an exit code (FR-6) -
        and records the person's words whole in the journal (FR-8). Anything it does not read as a form - prose, another
        language, a form this question did not offer, an answer for a stand the config no longer has - goes to the conductor
        with the key and the table of forms and their commands (the rule of gate B's stand-gap answers), never silently
        dropped. A form with its value missing, or a commit the answer is not about, is asked again naming what is wrong
        (FR-1): the commit once, then the conductor. `stop` is held: the words are journaled, the question stays open
        (nothing is passed), the story stops. A second recording answer for one stand and profile in one story: the last
        counts, the log says so, and the record quotes the earlier line. An executor that fails: the question comes back
        changed, naming that nothing was recorded, the factory's words in the details file."""
        import contract as C
        import stand_identity as SI
        pending = self.state.pop("build_question", None) or {}
        stand, profile = str(pending.get("environment") or ""), str(pending.get("profile") or "")
        data = SI.data()
        q, forms = data["question"], data["answers"]["forms"]
        offered = [name for name in pending.get("answers") or [] if name in forms]
        said = words.replace(self.BOM, "").strip()
        base = str(pending.get("text") or QUESTION_HEAD_RE.sub("", ANSWER_BLOCK_RE.sub("", qtext), count=1)).strip()
        where = f"stand build at {stage} ({stand}, {profile} tests)"

        def journal(what: str = "") -> None:
            self.answer_row(f"{where}{f' ({what})' if what else ''}: ", said, what="your answer about the stand build")

        def again(text: str, details: str = "", **keep) -> None:
            person = Person("stand_identity", text + "\n\n" + base, stage, dispatch, details=details)
            person.build_question = dict(pending, **keep)
            raise person

        def conductor(why: str) -> None:
            journal("not read as one of the answers, sent to the conductor")
            slots = dict(self.build_answer_slots(pending, '"<their words, verbatim>"', "<their value>"))
            commands = []
            for name in offered:
                spec = forms[name]
                runs = ["python " + str(self.scripts / "stand_identity.py") + " " + " ".join(self.build_expand(argv, slots))
                        for argv in spec.get("runs") or []]
                if spec.get("hold"):
                    commands.append(f"- `{name}`: run nothing; the story stops here. Answer `ask_person` with a question that says it "
                                    "is stopped and that the answers above still go on.")
                elif not runs:
                    commands.append(f"- `{name}`: run nothing; the stand is checked again when the stage starts.")
                else:
                    commands.append(f"- `{name}`" + ("" if spec.get("arg") == "none" else " <value>") + ":\n  " + "\n  ".join(runs))
            self.unread(
                "stand_identity", stage, dispatch,
                f"The person answered the driver's question about which build stand `{stand}` runs (the {profile} tests of story "
                f"{self.task}, at {stage}), and their words are below. The driver reads only the closed answers of that question "
                f"and these words were not read as one of them ({why}), so nothing was recorded.\n"
                f"The key: stand `{stand}`, test profile `{profile}`, story {self.task}. The project's record of how each stand's "
                f"build is read: {SI.registry_rel()}.\n"
                "If their words mean one of the answers below, record it with exactly those command lines and nothing else, the "
                "person's words verbatim in --words:\n" + "\n".join(commands) + "\n"
                + MOVES_RULE + " " + OWN_TOKEN_RULE + "\n\n## The question\n" + qtext[:6000], words=words)
        read = self.build_read_answer(said, offered, forms)
        missing = SI.in_config(self.config, stand, profile) if stand and profile else "the question names no stand or test profile"
        if not read["form"] or missing:
            return conductor(missing or read["why"])
        form, arg = read["form"], str(read.get("arg") or "")
        spec = forms[form]
        if spec.get("arg") == "required" and not arg:
            journal("a value is missing, asked again")
            again(q["reasks"]["missing_arg"].format(form=form, needs=spec.get("needs", ""), example=spec.get("example", form)))
        if spec.get("arg") == "commit" and arg:
            full = self.build_commit_of(pending, arg)
            wanted = str(pending.get("revision") or "") if form == "deployed" else str(pending.get("deployed") or "")
            problem = "not_a_commit" if not full else ("" if full == wanted else
                                                       ("wrong_story_commit" if form == "deployed" else "wrong_deployed_commit"))
            if problem and pending.get("reasked"):
                return conductor(f"it named the commit {arg}, which is not the commit this answer is about, a second time")
            if problem:
                journal("the commit it names is not the one asked about, asked again")
                again(q["reasks"][problem].format(sha=arg, short=str(pending.get("revision") or "")[:12], stand=stand,
                                                  deployed_short=str(pending.get("deployed") or "")[:12]), reasked=True)
        lines = q["lines"]
        shown = {"stage": stage, "stand": stand, "profile": profile, "said": self.s0_quote(said)}     # the slots of the console lines
        if spec.get("hold"):
            journal("stop; owner: environment")
            print(lines["answer_stop"].format(**shown))
            again(q["held"]["stop"].format(stand=stand))
        key = f"{stand}|{profile}"
        recorded = self.state.setdefault("stand_identity_answers", {})
        earlier = recorded.get(key) if spec.get("runs") else None
        line = said
        if earlier:
            print(lines["answer_repeated"].format(**shown))
            line = said + C.replaces_tail([earlier])
        slots = self.build_answer_slots(pending, line, arg)
        done = 0
        for argv in spec.get("runs") or []:
            code, out = self.py("stand_identity.py", *self.build_expand(argv, slots))
            if code:
                if done:
                    # t-366 F2: an earlier step of this answer IS written (`always confirm`: the person's decision for the
                    # stand), so the question must not say "nothing was recorded" (FR-10): it says what is written and what
                    # is not, and offers what is still open. The factory's own words go to the details file only.
                    recorded[key] = shown["said"]
                    journal("partly recorded, asked again")
                    print(lines["answer_partly"].format(**shown))
                    partly = q["partly_recorded"]
                    text = self.build_fit(self.build_join(partly["text"]), {"stand": stand, "profile": profile}, {}, whole=True)
                    person = Person("stand_identity", text, stage, dispatch, details=out)
                    person.build_question = dict(pending, variant="partly_recorded", answers=list(partly["answers"]), text=text,
                                                 reasked=False)
                    raise person
                journal("not recorded, asked again")
                print(lines["answer_not_recorded"].format(**shown))
                again(q["reasks"]["not_recorded"], details=out)
            done += 1
        if spec.get("runs"):
            recorded[key] = shown["said"]
        journal()
        print(lines["answer_recorded" if spec.get("runs") else "answer_retry"].format(**shown))

    def s5_window_files(self, cases) -> set:
        """The project-relative test files (`window_files.key_of` keys) of a window: the claims it holds, and the `tests[].file` of the
        manifest rows that cover one of its cases (and the files such a row was generated from). The launch gate's one reader. An
        unreadable manifest is the claims alone (the guard still stands)."""
        import window_files
        from probe_debt import bare_case_id
        found = set(window_files.files_of(self.task_root, window_files.window_id("S5", cases)))
        try:
            import contract as C
            import proof_level as PL
            manifest = C.load_json(C.artifact(self.task_root, "automation-manifest.json"))
            mine = {bare_case_id(c) for c in cases if bare_case_id(c)}
            for test in C.manifest_tests(manifest) if isinstance(manifest, dict) else []:
                if mine & {bare_case_id(c) for c in C.manifest_test_links(test)}:
                    generated = test.get("generated_from")
                    for name in [PL.test_file_of(test)] + ([f for f in generated if isinstance(f, str)] if isinstance(generated, list) else []):
                        if name:
                            found.add(window_files.key_of(name.replace("\\", "/").strip("/")))
                    from probe_debt import record_files      # t-2180 B: what a replay of the row's recorded probe mutates
                    for name in record_files(self.task_root, test):
                        found.add(window_files.key_of(name.replace("\\", "/").strip("/")))
        except Exception:       # noqa: BLE001 - the claims stand alone
            pass
        return found

    def s5_parallel_cap(self) -> int:
        """`dispatch.parallel_windows` through `config_contract.parallel_windows` (the one reader, AR-13); a bad value reads the default
        with its note, printed once per story (`state["noted"]`)."""
        import config_contract
        value, note = config_contract.parallel_windows(self.config)
        if note:
            self.say_once("parallel_windows", note)
        return value

    def say_once(self, key: str, text: str) -> None:
        """Print `text` once per story: the mark is `state["noted"]` (the one list the findings notes use), and never a stop (P5)."""
        noted = self.state.setdefault("noted", [])
        mark = f"{key}|{text}"
        if mark in noted:
            return
        noted.append(mark)
        print(text, flush=True)
        self.save_state()

    # The two reasons that are a state AT ENTRY and fall away once the windows they name have settled (spec 3.6, last row); every other
    # reason (the host, `run.parallel`, a limit, an old story, an unreadable state) holds for the whole run.
    S5_SETTLE_RUNNING = "dispatches of S5 are running or stopped at entry; they settle first and the rest goes side by side after"
    S5_SETTLE_OWED = "a repair round or a debt is owed; it runs first"

    def s5_settling_windows(self, windows: list) -> list:
        """The windows among `windows` that the entry-state reasons name: those whose scope meets a running, blocked or paused S5
        dispatch, and the window of an owed round or a debt. Empty when a dispatch names no case or meets no window (nothing is then
        known to settle, and the caller keeps the whole run serial). Raises with the readers (the caller treats that as serial)."""
        import dispatch_identity
        from controller import s5_part_of
        ctl = self.controller_state()
        rows = dispatch_identity.records(ctl.get("dispatches") if isinstance(ctl, dict) else None)
        scopes = [{str(c) for c in r.get("scope") or [] if c} for r in rows
                  if r.get("stage") == "S5" and r.get("status") in ("running", "blocked", "paused") and s5_part_of(r) != "plan"]
        if any(not s for s in scopes):
            return []
        named = [w for w in windows if any({str(c) for c in w.get("scope") or []} & s for s in scopes)]
        for window in (self.repair_owed(windows)[1], self.repair_debt_pending(windows)[1]):
            if window is not None and window not in named:
                named.append(window)
        return named

    def s5_serial_reason(self, windows: list) -> str:
        """"" when S5 windows may run side by side, else the one reason they run one at a time (spec 3.6). Direction of error: it may say
        serial needlessly on doubt; it must never let two windows run where a row below holds. The project's own word
        (`parallel_windows: 1`) is not this function's: that is the old road itself."""
        import dispatch_identity
        host_reason = self.host_window_reason()
        if host_reason:
            return host_reason
        run = self.config.get("run")
        if isinstance(run, dict) and run.get("parallel") is True:
            return ("the project runs its tests in parallel (`run.parallel: true`) and `test-results/` is shared; with "
                    "`run.parallel: false` the runs queue on the stand and the windows go side by side")
        if getattr(self, "_s5_cap_one", False):
            return "the model service limited one window earlier in this run"
        try:
            ctl = self.controller_state()
            rows = dispatch_identity.records(ctl.get("dispatches") if isinstance(ctl, dict) else None)
        except Exception:       # noqa: BLE001
            return "the state of the S5 dispatches cannot be read"
        if any(r.get("stage") == "S5" and r.get("status") in ("running", "blocked", "paused") for r in rows):
            return self.S5_SETTLE_RUNNING
        if self.repair_owed(windows)[0] or self.repair_debt_pending(windows)[0]:
            return self.S5_SETTLE_OWED
        root = self.task_root / "work"
        legacy = (root / "test-code" / "critic-findings.md").is_file() or (root / "probe-debt.json").is_file()
        per_dispatch = any((root / "test-code").glob("critic-findings-*.md")) or any((root / "probe-debt").glob("*.json"))
        if legacy and not per_dispatch and any("qa-code-critic" in (w.get("accepted_by") or {}) for w in windows):
            return "this story began before the windows kept their findings and probe debt per dispatch; its remainder reads the old files"
        try:
            self.s5_open_windows(())
        except Exception:       # noqa: BLE001
            return "the state or the scope of a window cannot be read"
        return ""

    def s5_open_windows(self, excluding=()) -> list:
        """The case lists of the S5 windows that are still open, other than the window meeting `excluding`. Open = no accepted critic, OR
        a running dispatch of the stage meets its scope, OR a round or a debt is owed for it, OR a live chain of this driver holds it, OR
        the LAST non-discounted S5 dispatch meeting its scope came back `returned_unaccepted` (TR4-10 Q2: `_s5_last_round`; a later
        accepted dispatch of the window closes it again, a person's release is dropped with the other discounted statuses), OR that last
        round is an ACCEPTED qa-automator round whose stored cause is not `mechanical` (TR4-13: `_s5_author_awaits_critic`; its critic
        has not reviewed it yet, and a mechanical round is closed by the author's own green run).
        Read fresh. RAISES when the windows, the dispatches or a scope cannot be read (FR-59): the caller treats that as open and never as
        a close; a returned S5 dispatch that names no cases is such a case. Callers: the close predicate of `s5_review` and
        `s5_mechanical_round`, `completion_for` at `parallel_windows` != 1, the old body of `stage_S5` at `parallel_windows` != 1, and the
        finish's `--open-windows`. At N == 1 the serial road does not read this function; a returned last round there is settled by the
        controller's own return road (a named residual, D2)."""
        import dispatch_identity
        import controller as CT
        from controller import s5_part_of
        own = {str(c) for c in (excluding or ()) if c}
        windows = self.stage_scope("S5").get("windows")
        if not isinstance(windows, list):
            raise WindowsUnreadable("stage-scope returned no list of windows")
        ctl = self.controller_state()
        dispatches = ctl.get("dispatches") if isinstance(ctl, dict) else None
        if not isinstance(dispatches, (dict, list)):
            raise WindowsUnreadable("the controller record holds no list of dispatches")
        rows = dispatch_identity.records(dispatches)
        running = [r for r in rows if r.get("stage") == "S5" and r.get("status") == "running" and s5_part_of(r) != "plan"]
        if any(not r.get("scope") for r in running):
            raise WindowsUnreadable("a running dispatch of S5 names no cases, so no window can be told from it")
        if any(r.get("stage") == "S5" and r.get("status") == CT.RETURNED and s5_part_of(r) != "plan" and not r.get("scope") for r in rows):
            raise WindowsUnreadable("a returned dispatch of S5 names no cases, so no window can be told from it")
        live = [r for r in self._chains.values() if not r.done]
        out = []
        for window in windows:
            if not isinstance(window, dict):
                raise WindowsUnreadable("a window of stage-scope is not an object")
            cases = {str(c) for c in window.get("scope") or [] if c}
            if not cases:
                raise WindowsUnreadable("a window of stage-scope names no cases")
            if cases & own:
                continue
            owed = self.repair_owed([window])[0] or self.repair_debt_pending([window])[0]       # F4: the two predicates, not a copy
            last_round = self._s5_last_round(rows, cases)
            if ("qa-code-critic" not in (window.get("accepted_by") or {})
                    or any(cases & {str(c) for c in r.get("scope") or []} for r in running)
                    or owed or any(cases & {str(c) for c in r.cases} for r in live)
                    or (last_round is not None and last_round.get("status") == CT.RETURNED)
                    or self._s5_author_awaits_critic(last_round)):
                out.append(sorted(cases))
        return out

    @staticmethod
    def _s5_author_awaits_critic(last_round) -> bool:
        """TR4-13 (FR-40, AR-25): True when the window's LAST round (`_s5_last_round`) is an ACCEPTED, non-mechanical author round: no
        critic has looked at it, so the window is open and the critic reviews it next, though an earlier accepted critic is still in
        `accepted_by`. The cause is read through the controller's one reader `repair_cause` (an absent or unknown cause is `test_defect`).
        Error direction: a `mechanical` round completes the window as before; anything else costs one more critic entry, never a close
        over an unreviewed round. ONE predicate for `s5_open_windows` and `s5_todo`."""
        import controller as CT
        return (isinstance(last_round, dict) and last_round.get("status") == "accepted" and last_round.get("role") == "qa-automator"
                and CT.repair_cause(last_round) != "mechanical")

    def s5_todo(self, windows: list) -> list:
        """The windows `stage_S5` works next: those with no accepted critic, and those whose last round is an accepted author round no
        critic has seen (`_s5_author_awaits_critic`, the clause `s5_open_windows` reads too). At `parallel_windows` == 1 nothing is read
        (the frozen N == 1 road, a named residual of TR4-10), and a record that cannot be read leaves today's list."""
        import dispatch_identity
        todo = [w for w in windows if "qa-code-critic" not in (w.get("accepted_by") or {})]
        if self.s5_parallel_cap() == 1:
            return todo
        try:
            ctl = self.controller_state()
            rows = dispatch_identity.records(ctl.get("dispatches") if isinstance(ctl, dict) else None)
            return [w for w in windows if w in todo or self._s5_author_awaits_critic(self._s5_last_round(rows, w.get("scope") or []))]
        except Exception:       # noqa: BLE001 - unreadable: today's list, the refusal below stays reachable
            return todo

    @staticmethod
    def _s5_last_round(rows: list, cases) -> dict | None:
        """The LAST S5 window dispatch (not the plan) among `rows` (`dispatch_identity.records`, the controller's order = dispatch order)
        whose scope meets `cases`, once the statuses in `controller.DISCOUNTED` are dropped; None when there is none. ONE walk for the
        returned clause of `s5_open_windows` and for every reader of "what came back last in this window" (TR4-10)."""
        import controller as CT
        mine = {str(c) for c in (cases or ()) if c}
        found = None
        for row in rows:
            if (row.get("stage") == "S5" and CT.s5_part_of(row) != "plan" and row.get("status") not in CT.DISCOUNTED
                    and mine & {str(c) for c in row.get("scope") or [] if c}):
                found = row
        return found

    def s5_last_fn(self, cases):
        """The close predicate of a chain's window, as a callable: True only when no other window is open. Unreadable is open."""
        def last() -> bool:
            try:
                return not self.s5_open_windows(excluding=cases)
            except Exception:       # noqa: BLE001 - FR-59
                return False
        return last

    def s5_open_flag(self, cases) -> list:
        """`["--open-windows", <cases>]` for a finish that does not close S5 while other windows are open, else []. Unreadable windows:
        the raw list of the other windows; if even that cannot be read, nothing (the controller refuses and the seam gets it)."""
        try:
            opened = self.s5_open_windows(excluding=cases)
        except Exception:       # noqa: BLE001
            try:
                own = {str(c) for c in cases}
                opened = [sorted({str(c) for c in w.get("scope") or []}) for w in self.stage_scope("S5").get("windows") or []
                          if isinstance(w, dict) and not own & {str(c) for c in w.get("scope") or []}]
            except Exception:       # noqa: BLE001
                return []
        names = sorted({c for w in opened for c in w})
        return ["--open-windows", ",".join(names)] if names else []

    def s5_release(self, cases) -> None:
        """A window that closed frees its test files (`window_files.release`, under `_book` on a chain). With `parallel_windows: 1`
        nothing was claimed and nothing is touched. A release that fails is a note; the entry sweep tries again."""
        import config_contract
        import window_files
        if config_contract.parallel_windows(self.config)[0] == 1:
            return
        window = window_files.window_id("S5", cases)
        left, why = [], ""
        try:
            window_files.release(self.task_root, window)
            left = window_files.files_of(self.task_root, window)      # `release` never raises: a claim it could not remove is still there (F7)
        except Exception as exc:       # noqa: BLE001
            why = f" ({type(exc).__name__})"
        if left or why:
            print(f"note: the test files of window {', '.join(cases)} could not be released{why or f' ({len(left)} claim(s) left)'}; "
                  "the next entry tries again")

    def s5_cases_of(self, dispatch: str) -> list:
        """The cases of an S5 dispatch: this chain's record, else the controller's record of `dispatch` ([] when it holds none). The ONE
        reader (R3, AR-13) for `finish`'s open-windows flag and the release of a closing window."""
        own = list(getattr(getattr(_CHAIN, "record", None), "cases", ()) or ())
        if own:
            return own
        from dispatch_identity import records as _records
        ctl = self.controller_state()
        return next((list(r.get("scope") or []) for r in _records(ctl.get("dispatches") if isinstance(ctl, dict) else None)
                     if r.get("id") == dispatch), [])

    def s5_release_of_dispatch(self, dispatch: str) -> None:
        """Q1: the window of the S5 critic `dispatch` whose finish just closed the stage frees its files. The chain road and the old body
        release when `s5_window` returns; the road through the person's gate answer (`s5_close_debt`, the recovery finish, `guarded`) never
        returns there, and a completed S5 is not entered again, so its claims would stay and refuse a later rework's automator. The
        cases come from this chain's record, else from the controller's record of the dispatch. Costs nothing when nothing was claimed;
        never stops the run (P1)."""
        import window_files
        folder = self.task_root / window_files.SUBDIR
        if not folder.is_dir() or not any(folder.glob("*.json")):
            return
        try:
            cases = self.s5_cases_of(dispatch)
            if cases:
                self.s5_release([str(c) for c in cases])
        except Exception as exc:       # noqa: BLE001
            print(f"note: the test files of the window of {dispatch} could not be released ({type(exc).__name__}); the next entry tries again")

    def s5_release_completed(self) -> None:
        """TR4-10 Q1 (D4, D5): S5 is `completed` - every claim of the stage is freed, whichever finish closed it. `s5_release_of_dispatch`
        frees the window of the critic that closed S5; this frees the rest: a recovery process that finished window B's saved critic
        `--not-complete` and then the last window A's `--complete` (B's claims stay: S5 is never entered again), and the live mechanical
        round's finish. Called ONLY after `story_step finish` exited 0, so the stage status read is the one that finish wrote.
        INVARIANT: a claim of a window that can still write is never freed: nothing is freed unless `stages.S5.status == "completed"` AND
        no S5 dispatch is `running`, in `controller.STOPPED` or `controller.RETURNED` (a retry or a resume of the same role writes in
        the same window). Absent or unreadable state, a status that is not text: nothing is freed (late is safe, early is two windows
        on one file). At `parallel_windows: 1` nothing was claimed and nothing is read. A claim left behind is a note, never a stop (P1)."""
        import config_contract
        import controller as CT
        import dispatch_identity
        import window_files
        if config_contract.parallel_windows(self.config)[0] == 1:
            return
        folder = self.task_root / window_files.SUBDIR
        if not folder.is_dir() or not any(folder.glob("*.json")):
            return
        try:
            ctl = self.controller_state()
            if not isinstance(ctl, dict):
                return
            stages = ctl.get("stages")
            stage = stages.get("S5") if isinstance(stages, dict) else None
            if not isinstance(stage, dict) or stage.get("status") != "completed":
                return
            dispatches = ctl.get("dispatches")
            if not isinstance(dispatches, (dict, list)):
                return
            busy = {"running"} | CT.STOPPED | {CT.RETURNED}
            for row in dispatch_identity.records(dispatches):
                status = row.get("status")
                if row.get("stage") == "S5" and (not isinstance(status, str) or status in busy):
                    return
            window_files.release_stage(self.task_root, "S5")
            # only a claim this release meant to free (a readable claim of a window of stage S5): a young empty claim `release` keeps on
            # purpose, and any other stage's claim, are not "left"; `window_files.read_claim` is the claims' own reader
            left = sum(1 for path in folder.glob("*.json")
                       if window_files.window_of_stage((window_files.read_claim(path) or {}).get("window"), "S5"))
        except Exception as exc:       # noqa: BLE001
            print(f"note: the test files of S5 could not be released ({type(exc).__name__}); the next entry tries again")
            return
        if left:
            print(f"note: the test files of S5 could not be released ({left} claim(s) left); the next entry tries again")

    def s5_release_closed(self) -> None:
        """The restart sweep: claims of windows that are closed (not in `s5_open_windows`) are released; it costs nothing when the story has
        claimed nothing. An unreadable state releases nothing."""
        import window_files
        folder = self.task_root / window_files.SUBDIR
        if not folder.is_dir() or not any(folder.glob("*.json")):
            return
        try:
            opened = {tuple(w) for w in self.s5_open_windows(())}
            windows = self.stage_scope("S5").get("windows") or []
        except Exception as exc:       # noqa: BLE001
            print(f"note: the claims of closed windows were left in place: the windows could not be read ({type(exc).__name__})")
            return
        for window in windows:
            cases = sorted({str(c) for c in window.get("scope") or [] if c})
            if cases and tuple(cases) not in opened:
                self.s5_release(cases)

    def s5_notes_line(self) -> str:
        """The line that tells a window which notes of the earlier windows to read first: the old `work/s5-notes.md` (a story from before)
        and the per-dispatch folder `work/s5-notes/`, each named only when it holds something."""
        base = f"qa-factory/artifacts/{self.task}/work"
        parts = []
        if (self.task_root / "work" / "s5-notes.md").is_file():
            parts.append(f"{base}/s5-notes.md")
        if any((self.task_root / "work" / "s5-notes").glob("*.md")):
            parts.append(f"every file of {base}/s5-notes/")
        return f"Read {' and '.join(parts)} first." if parts else ""

    # The door the guard's refusal of a claimed test file names (`guard_pre_tool.window_file_check`), written ONCE for both ownership lines.
    S5_OWN_FILE_DOOR = ("put your test in a new file in the same directory; where a test lives stays your choice, "
                        "and a test in a new file is judged the same.")

    def s5_auto_extra(self, window: dict, cases: list, chain: bool = False) -> list:
        """The lines every dispatch of an S5 window carries. On the parallel road (`chain`) two more tell the role what the scheduler
        makes true: another window may own a test file, and a busy stand is not its failure. TR4-10 Q4 (D6): wherever the guard enforces
        the claims (`config_contract.parallel_windows` != 1, the guard's own reader) the role is told of the ownership rule on the serial
        body too, in a variant without the sentence that is false there (no other window is written at the same time); the stand line
        stays `chain`-only. At N == 1 with `chain` False the list is as it was."""
        import config_contract
        cfg = getattr(self, "config", None)
        enforced = config_contract.parallel_windows(cfg if isinstance(cfg, dict) else {})[0] != 1
        extra = [f"Window: {', '.join(cases)} — {window.get('surface', 'other')} surface.",
                 "Runs go through run_suite.py --mine <CASE>; the manifest is written with manifest_put.py. "
                 "A test written to an approved case that fails against the implementation is handed over "
                 "RED with unresolved reason contradicts_requirement, never adjusted to the code."]
        notes = self.s5_notes_line()
        if notes:
            extra.append(notes)
        if chain:
            extra.append("Other windows of this story are written at the same time. A test file one of them wrote first refuses your "
                         "Write or Edit: " + self.S5_OWN_FILE_DOOR)
        elif enforced:
            extra.append("A test file another window of this story wrote first refuses your Write or Edit: " + self.S5_OWN_FILE_DOOR)
        if chain:
            extra.append("A run that answers `stand busy` after some minutes waited for the stand queue: it is not a failure of your "
                         "tests. Say so in your digest and run again.")
        return extra

    def s5_chain_kind(self) -> "ChainKind":
        """What the scheduler's console and gate call an S5 chain (t-2147 A): a window, holding files; the gate reads `s5_window_files`
        at call time, so a rig's override is seen."""
        return ChainKind("S5", "window", "a file", lambda cases: self.s5_window_files(cases))

    def s5_seam(self, records: list, cap: int) -> None:
        """The seam after the drain (B4): see `run_chains`. A model-service `limit` in one chain, with more than one chain allowed, is not
        a stop: the rest finished and booked, this run goes on at one window at a time (F13), said once. Any other kind stops as today."""
        pick = self.chain_pick(records, self.s5_chain_kind(), seam_rank)
        if pick is None:
            return
        exc = pick.exception
        if isinstance(exc, InfraStop) and exc.kind == "limit" and cap > 1 and not getattr(self, "_s5_cap_one", False):
            self._s5_cap_one = True
            print("note: the model service limited a window; the others finished and are booked, and S5 goes on one window at a time "
                  "for the rest of this run", flush=True)
            return
        self.adopt_chain(pick)
        raise exc

    def s5_launchable(self, record) -> bool:
        """The gate at a chain's start: no running chain's window holds a file of this one."""
        mine = self.s5_window_files(record.cases)
        if not mine:
            return True
        return not any(mine & self.s5_window_files(r.cases) for r in self._chains.values() if r is not record and not r.done)

    def s5_window_chain(self, record, window: dict) -> None:
        """One window's chain, on its own thread: the stand and build checks (a Person there re-arises, state unchanged), the author when
        it has not been accepted, then the loop `s5_window` runs; the window's files are freed when it closed."""
        self.stop_if_drained()
        cases = list(window["scope"])
        self.boundary = "S5:" + ",".join(cases)
        with self.timed("stand_check", stage="S5"):
            self.stand_check("S5")
        with self.timed("build_check", stage="S5"):
            self.build_check("S5", cases=cases)
        auto_extra = self.s5_auto_extra(window, cases, chain=True)
        if "qa-automator" not in (window.get("accepted_by") or {}):
            self.run_role("S5", "qa-automator", scope=cases, complete=False, extra=auto_extra)
        self.s5_window(window, self.s5_last_fn(cases), auto_extra, None)
        self.s5_release(cases)
        view = getattr(self, "_s5_view", None)
        if view is not None:
            view["closed"].add(record.n)

    def run_s5_windows(self, windows: list, todo: list, cap: int) -> None:
        """The parallel road of `stage_S5`: one chain per open window, `cap` at a time."""
        number = {tuple(sorted(w["scope"])): i + 1 for i, w in enumerate(windows)}
        items = [(number[tuple(sorted(w["scope"]))], list(w["scope"]), w) for w in todo]
        held = {tuple(sorted(w["scope"])) for w in todo}       # a window `s5_todo` holds (an accepted author round owed its critic) is not closed
        self._s5_view = {"total": len(windows), "closed": {number[tuple(sorted(w["scope"]))] for w in windows
                                                        if "qa-code-critic" in (w.get("accepted_by") or {})
                                                        and tuple(sorted(w["scope"])) not in held}}      # `todo` may be a part of the open windows (F6)
        try:
            self.run_chains(items, self.s5_launchable, self.s5_window_chain, cap, kind=self.s5_chain_kind(), seam=self.s5_seam)
        finally:
            self._s5_view = None

    def session_of(self, stage: str, dispatch: str):
        """The stored session of `dispatch`; off a chain, else the stage's agent of the pipeline (the old fallback). On a chain the
        per-dispatch record only: absent means no resume, a fresh attempt by today's rule (the stage's agent may be another window's)."""
        sid = self.state["sessions"].get(dispatch)
        if sid or self.on_chain():
            return sid
        return (self.pipeline().get("stages", {}).get(stage, {}) or {}).get("agent_id")

    def stage_S5(self) -> None:
        with self.timed("stage_scope", stage="S5"):
            scope = self.stage_scope("S5")
        windows = scope.get("windows") or []
        if not scope.get("scope"):
            raise Refusal("S5: stage-scope returned no automate cases: " + json.dumps(scope)[:800])
        todo = self.s5_todo(windows)
        owed, owed_window = self.repair_owed(windows)       # a round the person chose at the repair limit and not run yet (t-698 A4)
        # t-733: a `debt` that consumed an owed round leaves its critic's finish (`--not-complete`) to be completed; no role runs, so no stand or
        # build check is owed. POSITION INVARIANT: before the L5 refusal (which has no door for it) and before any review (a fresh critic would
        # be asked the same question again), never while a round is owed (that round runs first). The critic is finished only while it can
        # be: still running (the controller refuses a bare `--not-complete` accept of the stage's closing critic, so it stays so and its
        # window is in `todo`) or, with nothing else waiting, accepted.
        pending, pending_window = ({}, None) if owed else self.repair_debt_pending(windows)
        if pending and (not todo or "qa-code-critic" not in (pending_window.get("accepted_by") or {})):
            self.s5_close_debt(pending, pending_window)
            return
        if not todo and not owed and self.s5_parallel_cap() != 1:
            # TR4-10 D3 (Lead, option b): a window held open by a returned LAST round (`s5_open_windows` reads it open) is not "every window is
            # accepted": the refusal below names the wrong door for it. The controller's `next` HIDES such a return behind later S5 work, so
            # `_act_resolve_return` never runs for it: this block is the whole road. No words filed: the EXISTING `resolve_return` packet
            # (`resolve_return_refusal`, the one builder `_act_resolve_return` raises too) names the dispatch and goes through the one seam to
            # the conductor, who settles it or asks the person. Words filed for THAT dispatch: the stage resumes the role itself
            # (`resume_with_filed_words`, the one move `_act_resolve_return` makes too; `resume_role` consumes the words) and the stage
            # re-enters - the same packet is never raised twice for words already filed (AR-24). The resumed author's round completes by its
            # repair cause, as the live road does (AR-28): a MECHANICAL round (the critic itself routed it, no critic follows) by the
            # window's own rule, `s5_last_fn` (`s5_mechanical_round`); any other author round (`test_defect`, an absent or unknown cause,
            # read through the controller's one reader `repair_cause`) never completes S5 - its critic reviews it first (`s5_author_round`
            # passes `rework`'s default False). Error direction: False costs one more critic entry, True would close S5 over an
            # unreviewed round. Any other role by `completion_for`.
            # POSITION INVARIANT: before the refusal below, which stays reachable when no window has a returned last round, when the state is
            # unreadable, or when the returned record is gone at the resume. Words filed for ANOTHER dispatch are not used.
            returned, window_scope = None, []
            try:
                import controller as CT
                import dispatch_identity
                ctl = self.controller_state()
                rows = dispatch_identity.records(ctl.get("dispatches") if isinstance(ctl, dict) else None)
                for w in windows:
                    last_row = self._s5_last_round(rows, w.get("scope") or [])
                    if last_row is not None and last_row.get("status") == CT.RETURNED:
                        returned, window_scope = last_row, list(w.get("scope") or [])
                        break
            except Exception:       # noqa: BLE001
                returned = None
            if returned is not None and (self.state.get("pending_words") or {}).get(returned.get("id")):
                def complete_for(stage, role, record):
                    if role == "qa-automator":
                        if CT.repair_cause(record) != "mechanical":
                            return False
                        window_last = self.s5_last_fn(window_scope)
                        return lambda _digest: bool(window_last())
                    return self.completion_for(stage, role, record)
                stage_boundary = getattr(self, "boundary", "S5")
                if self.resume_with_filed_words(str(returned.get("id")), complete_for):
                    return
                # the record is gone: the old refusal below, raised under the STAGE's boundary (the helper set `<stage>:<id>` for
                # `_act_resolve_return`'s packet, which the conductor reads; nothing resumed here, so it is put back - Lead, option A)
                self.boundary = stage_boundary
                returned = None
            if returned is not None:
                from contract import retry_reason_for
                raise self.resolve_return_refusal({
                    "action": "resolve_return", "dispatch_id": returned.get("id"), "stage": returned.get("stage"),
                    "role": returned.get("role"), "dispatch_status": returned.get("status"),
                    "digest": returned.get("returned_digest") or "", "options": ["accept", "checkpoint", "rework"],
                    "retry_reason": retry_reason_for(returned),
                    "reason": returned.get("reason") or "the role stopped without acceptance; accept its evidence, record the block, or send "
                                                        "the work back"})
        if not todo and not owed:
            raise Refusal("S5: every window is accepted by its author and its critic and S5 is still open. That is the "
                          "factory's own state, not a gap in the tests: run `controller.py --operation recover` first and "
                          "read what the controller holds.")
        # TR3-6: the default is 3 windows at a time. `parallel_windows: 1`, ONE open window and an owed round take the body below, verbatim
        # (no thread, no scheduler, no new state key): the owed round runs first through today's one-window code and the stage re-enters,
        # so the remainder then goes side by side. The claims of closed windows are freed first (the restart sweep, F3 b).
        parallel = self.s5_parallel_cap()
        if parallel != 1:
            self.s5_release_closed()
            if len(todo) >= 2 and not owed:
                reason = self.s5_serial_reason(windows)
                if reason:
                    self.say_once("s5-windows", f"note: S5 windows run one at a time: {reason}")
                if reason in (self.S5_SETTLE_RUNNING, self.S5_SETTLE_OWED):
                    # F6 (spec 3.6, last row): a reason that is a state AT ENTRY lasts only while it holds. The windows it names run one
                    # at a time FIRST; when they have settled the reason is read again and the rest goes side by side in this same stage.
                    # A reason that is not about the entry state (the host, `run.parallel`, a limit, an old story) keeps the whole run
                    # serial, as does one that names no window. One round only: a dispatch that never settles cannot loop the stage.
                    try:
                        first = self.s5_settling_windows(todo)
                    except Exception:       # noqa: BLE001 - unreadable: the whole run stays serial
                        first = []
                    if first and len(first) < len(todo):
                        self.run_s5_windows(windows, first, 1)
                        windows = self.stage_scope("S5").get("windows") or []
                        todo = self.s5_todo(windows)
                        if len(todo) < 2:
                            return      # the stage re-enters: no window left, or one, which takes today's body
                        reason = self.s5_serial_reason(windows)
                        if reason:
                            self.say_once("s5-windows", f"note: S5 windows run one at a time: {reason}")
                return self.run_s5_windows(windows, todo, 1 if reason else min(parallel, len(todo)))
        window = owed_window if owed else todo[0]       # a pure choice: above the checks, so each stand check is followed at once by its build check
        with self.timed("stand_check", stage="S5"):
            self.stand_check("S5")      # every window comes through here; a confirmed or passed stand costs no probe
        with self.timed("build_check", stage="S5"):
            self.build_check("S5", cases=list(window.get("scope") or []))     # t-300: the build of THIS window's profiles
        if owed:
            # POSITION INVARIANT (t-729 F3): AFTER the two checks (either can raise a Person and the owed round must still be owed on the
            # next entry) and BEFORE the first dispatch of the round (a crash costs one round, never two).
            owed["executed"] = True
            self.save_state()
        last = (not [w for w in todo if w.get("scope") != window.get("scope")]) if owed else len(todo) == 1
        if last and parallel != 1:
            # TR4-10 D1: at N != 1 the old body reads the same close rule as the chain road: no other window open (a running dispatch, an
            # owed round, a live chain, a LAST round that came back unaccepted). Unreadable is open (FR-59). At N == 1 nothing is read.
            last = self.s5_last_fn(window.get("scope") or [])()
        cases = list(window["scope"])
        self.boundary = "S5:" + ",".join(cases)
        auto_extra = self.s5_auto_extra(window, cases)      # TR3-6: the notes line names the per-dispatch notes too, not only the old file
        if "qa-automator" not in (window.get("accepted_by") or {}):
            self.run_role("S5", "qa-automator", scope=cases, complete=False, extra=auto_extra)
        before = getattr(self, "last_dispatch", "")
        try:
            self.s5_window(window, last, auto_extra, owed)
            self.s5_release(cases)          # the window closed: its test files are free for a later one (a no-op at `parallel_windows: 1`)
        except ReworkRefused:
            if owed and getattr(self, "last_dispatch", "") == before:
                # t-760 (t-758 finding 3): the controller refused to START the owed round (no role ran, `last_dispatch` is unchanged), so the
                # mark above is taken back - on a non-last window the critic is accepted and the person's round would be lost in silence
                owed["executed"] = False
                self.save_state()
            raise

    S5_CRITIC_BRIEF = ["Static review first, then probe_by_code.py once per instance, every check of the test: "
                       "red_sandbox.py --probe (only when you doubt the check looks at the product, with the reason "
                       "in your findings) proves only the one check it names, the others stay owed; a probe of unchanged "
                       "bytes and the same entries is answered `already_probed`; write your findings file and the review_receipt_ref "
                       "on the manifest bindings; `cause:` on each finding."]

    def s5_window(self, window: dict, last: bool, auto_extra: list, owed: dict | None = None) -> None:
        """One S5 window from its review to its close: the critic reviews, the route says what follows (an author round, a mechanical
        round, the close), and a round the person chose at the repair limit (`owed`) runs first. The gate of the seam sits in
        `run_role`, before the critic's finish: a limit, an unreadable count or a rejection nobody can repair is asked there."""
        import repair_route
        cases = list(window["scope"])
        after_round, step = None, owed      # `after_round`: `counted` when the last test_defect round was dispatched
        while True:
            # the rounds spent are the controller's count, read fresh before every review
            budget = self.budget_or_none("S5", "qa-automator", cases)
            if after_round is not None and isinstance(budget, dict) and isinstance(budget.get("counted"), int) \
                    and isinstance(budget.get("cap"), int) and budget["counted"] <= after_round:
                # the loop's only bound is the ledger growing with every round; a ledger that did not count
                # the round just run would send the same review back for ever
                print(f"S5: the controller did not count the round just run ({budget['counted']} of {budget['cap']}); "
                      "no further repair round is dispatched for this window")
                # the count is UNKNOWN now (L3, t-698 §2): the gate of this very review reads this budget (it is passed, not re-read),
                # so the window closes over the seam reason `unknown` - asked, never in silence - and a debt is recorded if chosen
                budget = dict(budget, counted=None)
            if step and step["token"] in ("round", "route"):
                # the person's round (`owed`, token `round`), or the ordinary round a recovery finish left owed (token `route`): the
                # critic's rejection stands, the author repairs it (on the passes the answer wrote, for `round`)
                critic, digest = step["dispatch"], ""
                form = repair_route.read_form(self.task_root / "work" / "handoffs" / f"{critic}.yaml") if step["token"] == "route" else None
                route = {"action": step.get("action") or "test_defect", "reason": "the person's round" if step["token"] == "round"
                         else step.get("reason") or "an owed round", "not_rounds": [], "note": "", "code": ""}
                if route["action"] == "test_defect" and not self.repair_countable(budget):
                    # t-732: the round is announced as "n of cap" and the loop is bounded by that count - with no count it is not run
                    # blind. It stays owed (the mark `stage_S5` wrote is taken back) and the seam asks `unknown`, never a TypeError.
                    step["executed"] = False
                    self.save_state()
                    self.repair_limit_raise(self.repair_limit_facts(critic, cases, dict(route, action="close", code="unknown"), form, budget))
            else:
                digest, critic, route, form = self.s5_review(cases, last, budget, step)
            step = None
            self.s5_note_findings(route, form, critic)
            forms = f"work/handoffs/{critic}.yaml"
            if route["action"] == "test_defect":
                after_round = self.s5_author_round(cases, budget, digest, forms, auto_extra, critic)
                continue        # the loop dispatches the critic again on the new bytes
            if route["action"] == "mechanical":
                self.s5_mechanical_round(cases, last, critic, form, auto_extra)
                break           # the reviewer is not dispatched again after a mechanical round
            print(f"S5: {critic} closes the window with no further round: {route['reason']}")
            break

    def route_of(self, text: str, budget, dispatch: str = "") -> tuple:
        """(route, form): where the review `text` of the critic `dispatch` sends its window, read from the critic's typed form and
        the controller's budget (B-007, FR-47). The form is the file the handoff gate has just checked; `dispatch` defaults to
        `last_dispatch` (run_role sets it). ONE reader for the loop, the seam's gate and the close predicate."""
        import repair_route
        import role_digest
        verdict = (role_digest.parse(text).get("header") or {}).get("verdict", "")
        form = repair_route.read_form(self.task_root / "work" / "handoffs" / f"{dispatch or getattr(self, 'last_dispatch', '')}.yaml")
        return repair_route.route(verdict, form, budget), form

    @staticmethod
    def s5_window_closed(route: dict, answer: dict) -> bool:
        """THE close predicate of an S5 window (t-698 A3), shared by the loop and `completion_for`: the route closes it, and when
        the route closes over a seam reason (`code`) the person's answer for THAT critic dispatch is `debt`. A close over a seam
        reason with no answer is not a close: the gate asks first, so this is False only on a road that skipped the gate.
        A `debt` that consumed an owed round (`owed`, t-733) is a close whatever the route now reads: the round it replaced is never run."""
        if answer.get("token") == "debt" and answer.get("owed"):
            return True
        return route.get("action") == "close" and (not route.get("code") or answer.get("token") == "debt")

    def s5_review(self, cases: list, last: bool, budget, step: dict | None) -> tuple:
        """(digest, critic, route, form): ONE review of the window. `step` (the person's answer `fixed` / `review`) is a critic
        dispatch with the cause the answer names, which spends none of the cap; otherwise the plain critic dispatch. The route is
        known BEFORE the critic's finish: the last window's critic closes S5 only when `s5_window_closed` says so - never while its
        author is owed a (mechanical) round, never over a seam reason the person has not answered."""
        def closes(text: str, dispatch: str = "") -> bool:
            # TR3-17: the critic dispatch is read ONCE and handed to both readers; `finish` calls with the digest alone, so the default is
            # this thread's `last_dispatch` (the serial road's value, byte for byte as before).
            dispatch = dispatch or getattr(self, "last_dispatch", "")
            route, _form = self.route_of(text, budget, dispatch)
            # TR3-6: on the parallel road `last` is a callable (no other window open), read HERE, at the finish, under `_book`
            return bool((last() if callable(last) else last) and self.s5_window_closed(route, self.repair_answer(cases, dispatch)))
        if step and step.get("cause"):
            digest, _next = self.rework("S5", "qa-code-critic", cases, step.get("reason") or "the person asked for a new review",
                                        cause=step["cause"], complete=closes, extra=self.S5_CRITIC_BRIEF, budget=budget)
        else:
            digest, _next = self.run_role("S5", "qa-code-critic", scope=cases, complete=closes, extra=self.S5_CRITIC_BRIEF, budget=budget)
        critic = getattr(self, "last_dispatch", "")
        route, form = self.route_of(digest, budget, critic)
        return digest, critic, route, form

    def s5_note_findings(self, route: dict, form, critic: str) -> None:
        """What is said about findings nobody repairs: each is printed, a tooling one is also the factory's own defect (FR-3). ONCE per
        critic dispatch and finding, across roads and processes (`state["noted"]`): the seam's gate calls this before it asks, the
        loop calls it after the review, and a window closed through the gate's question never reaches the loop again (t-729 F1)."""
        import repair_route
        typed = {f["id"]: f for f in repair_route.findings(form)} if form else {}
        noted = self.state.setdefault("noted", [])
        fresh = []
        for entry in route["not_rounds"] + ([{"id": "", "cause": "note"}] if route["note"] else []):
            mark = f"{critic}|{entry['id']}|{entry['cause']}"
            if mark not in noted:
                noted.append(mark)
                fresh.append(entry)
        for entry in fresh:
            if entry["cause"] == "note":
                print(f"S5: {route['note']}")
                continue
            print(f"S5: finding {entry['id']} of {critic} ({entry['cause']}) is nobody's round: no author is "
                  "dispatched for it; it stays in the review's unverified rows")
            if entry["cause"] == "tooling":
                # T5 (C1-7b): the finding was printed above and stays in the review's unverified rows; the defect row is the factory's note
                self.py_trace("log_append.py", "--event", "defect_found", "--task", self.task, "--ref", critic,
                              "--by", "driver", "--notes", f"owner: factory — tooling finding {entry['id']}: "
                              f"{(typed.get(entry['id']) or {}).get('problem') or 'no problem line in the form'}",
                              why="the finding is printed and stays in the review's unverified rows; the defect row is the factory's own note and no decision of this story reads it")
        if fresh:
            self.save_state()

    def s5_author_round(self, cases: list, budget, digest: str, forms: str, auto_extra: list, critic: str = ""):
        """The author's test_defect round over the critic's findings (`critic`: the dispatch whose review sent the window back);
        returns the `counted` it was dispatched at. The findings are that critic's file `work/test-code/critic-findings-<critic>.md`,
        else the one file of a story from before findings went one per dispatch (`critic-findings.md`), else the digest: never "the
        newest on disk" and never `work/**` (with two windows that was the other window's file, or the S4 critic's; t-1937 TR3-5)."""
        import findings_path
        found = findings_path.resolve(self.task_root, critic)
        findings = (self.task_root / found) if found else None
        reason = (findings.read_text(encoding="utf-8", errors="replace")[:1200] if findings else digest)
        self.rework("S5", "qa-automator", cases, "critic round: " + reason, cause="test_defect",
                    extra=[f"Repair round {budget['counted'] + 1} of {budget['cap']}: the critic's form is {forms} and "
                           f"its findings are in "
                           f"{findings.relative_to(self.task_root).as_posix() if findings else 'the critic digest'}; "
                           "re-run only the instances whose code changed; a comment/docstring/marker-only "
                           "fix keeps its run (the factory answers `reused`)."] + auto_extra)
        return budget["counted"]

    def s5_mechanical_round(self, cases: list, last: bool, critic: str, form, auto_extra: list) -> None:
        """The author's mechanical round over the critic's mechanical findings; no critic is dispatched after it."""
        import repair_route
        ids = ", ".join(f["id"] for f in repair_route.findings(form) if f["blocking"] and f["cause"] == "mechanical")
        forms = f"work/handoffs/{critic}.yaml"
        self.rework("S5", "qa-automator", cases, f"mechanical fixes of review {critic}: {ids}",
                    cause="mechanical", complete=((lambda _digest: bool(last())) if callable(last) else last),
                    extra=[f"Mechanical round of the review {critic} (its form is {forms}): fix only the findings "
                           f"{ids}; no critic is dispatched after it - your green run on the new bytes closes the "
                           f"round. Write `mechanical_round` on the window record with window_record.py "
                           f"(reviewer dispatch {critic}); re-run only the instances whose code changed; a "
                           "comment/docstring/marker-only fix keeps its run (the factory answers "
                           "`reused`)."] + auto_extra)

    # --- the S5 repair limit through the one seam (C1-5b1, t-698 §4) ----------------------------------------------------
    # A window's critic result that closes over a SEAM REASON (`route["code"]`: the cap is spent, the count cannot be read, the
    # blocking findings are nobody's round, the verdict names none) is asked, never closed in silence (I1). The question is the
    # site's own, closed and priced (`call=False`, D-0041): the conductor reads only words code cannot. The gate sits in
    # `run_role`, `_finish_saved_result` and `resume_role` BEFORE the critic's finish, so the stage is never closed over it.
    CAUSE_WORDS = {"test_defect": "about the test itself", "mechanical": "a technical fix to the test",
                   "environment": "the stand got in the way", "reviewer_error": "the critic's own review is in doubt",
                   "tooling": "a fault in the factory's own tools"}
    NOBODY_ORDER = ("environment", "reviewer_error", "tooling")      # the most demanding cause first (t-698 A5)

    @staticmethod
    def window_id(stage: str, cases) -> str:
        """`<stage>|<the cases, sorted and joined by commas>`: THE window key - the conductor's per-window round cap (`window_key`)
        and the repair-limit answers (`repair_key`) share this one formatter (t-729 S2), so b2's S7 asks the same way. The
        formatter is `window_files.window_id` (the claim files of TR3-16 name windows by it too: one reader)."""
        import window_files
        return window_files.window_id(stage, cases)

    @classmethod
    def repair_key(cls, cases, stage: str = "S5") -> str:
        return cls.window_id(stage, cases)

    def repair_answer(self, cases, dispatch: str) -> dict:
        """The person's answer for THIS window and THIS critic dispatch, or {} (an answer for an earlier dispatch is none)."""
        found = (self.state.get("repair_limit") or {}).get(self.repair_key(cases)) or {}
        return found if isinstance(found, dict) and found.get("dispatch") == dispatch else {}

    def repair_owed(self, windows: list) -> tuple:
        """(the answer, its window) of a round the person chose (`round` / `fixed` / `review`) and the loop has not run yet, else
        ({}, None): the critic's finish took the window back (`--not-complete`) and the stage re-enters here. `executed` is set by
        `stage_S5`, after its stand and build checks (t-729 F3)."""
        return self.repair_entry(windows, lambda entry: entry.get("token") in self.OWED_TOKENS and not entry.get("executed"))

    def repair_debt_pending(self, windows: list) -> tuple:
        """(the answer, its window) of a `debt` that consumed an owed round (`owed`) and whose critic finish is not completed yet, else
        ({}, None) (t-733)."""
        return self.repair_entry(windows, lambda entry: entry.get("token") == "debt" and entry.get("owed") and not entry.get("finished"))

    def repair_entry(self, windows: list, wanted) -> tuple:
        """(the first kept answer `wanted` accepts, its window among `windows`), else ({}, None): the one PREDICATE scan of `repair_limit`.
        The other readers (`repair_answer`, `owe_route`, the answer executor) look ONE window up by its key."""
        for entry in (self.state.get("repair_limit") or {}).values():
            if isinstance(entry, dict) and wanted(entry):
                window = next((w for w in windows if sorted(w.get("scope") or []) == sorted(entry.get("cases") or [])), None)
                if window:
                    return entry, window
        return {}, None

    def s5_close_debt(self, entry: dict, window: dict) -> None:
        """The critic of `entry` was left open by an owed round and the person then chose `debt` instead of the round:
        finish it by the SAME close predicate as the gate's debt (`completion_for` -> `s5_window_closed`), so the window closes
        over the debt (the review-debts entry was written with the answer). Marked `finished` once the finish went through, so a
        refused finish is made again by the next entry and a finished one never twice (t-733)."""
        cases, critic = list(window.get("scope") or []), entry["dispatch"]
        print(f"S5: the person left the tests of {', '.join(cases)} rejected instead of another round; {critic} closes the window")
        digest = f"qa-code-critic S5 {', '.join(cases)} · concerns\nthe window is closed by the person's choice; the tests stay rejected (review debt)"
        self.finish(critic, digest, complete=self.completion_for("S5", "qa-code-critic", {"id": critic, "scope": cases}),
                    role="qa-code-critic", stage="S5")
        entry["finished"] = True
        self.save_state()

    OWED_TOKENS = ("round", "fixed", "review", "route")     # `route`: a recovery finish left an ordinary round owed (t-729 F4)

    def owe_route(self, dispatch: str, cases: list, route: dict) -> None:
        """A recovery road (`_finish_saved_result`, `resume_role`) finished a critic dispatch whose route still owes the AUTHOR a round
        (a test_defect or a mechanical one, no seam reason): the loop that would run it is not on the stack, so the round is recorded as
        owed and `stage_S5` runs it on the next entry - before the L5 refusal, which cannot name a door for it (t-698 A4, FR-1/FR-2).
        One record per window and critic dispatch (a repeated finish writes nothing new)."""
        if route.get("code") or route.get("action") not in ("test_defect", "mechanical"):
            return
        owed = self.state.setdefault("repair_limit", {})
        if (owed.get(self.repair_key(cases)) or {}).get("dispatch") == dispatch:
            return
        owed[self.repair_key(cases)] = {"dispatch": dispatch, "token": "route", "cases": list(cases), "key": "", "at": _now(),
                                        "words_file": "", "cause": "", "reason": route.get("reason") or "", "executed": False,
                                        "action": route["action"]}
        self.save_state()

    @staticmethod
    def repair_countable(budget) -> bool:
        """True when the budget carries both numbers a round is announced with (`counted`, `cap`)."""
        return isinstance(budget, dict) and isinstance(budget.get("counted"), int) and isinstance(budget.get("cap"), int)

    @staticmethod
    def repair_passes(budget):
        """{role: key} of `repair_budget.passes`, or None when the budget does not carry both keys (an older controller, A3)."""
        passes = budget.get("passes") if isinstance(budget, dict) else None
        ok = isinstance(passes, dict) and all(isinstance(passes.get(r), str) and passes[r] for r in ("qa-automator", "qa-code-critic"))
        return {r: passes[r] for r in ("qa-automator", "qa-code-critic")} if ok else None

    def repair_limit_gate(self, stage: str, role: str, dispatch: str, digest: str, scope=None, *, budget=READ_BUDGET,
                          recovering: bool = False) -> None:
        """Between a critic's handoff and its finish: the seam question when the review closes the window over a seam reason and
        the person has not answered for THIS dispatch. Acts only for (S5, qa-code-critic). POSITION INVARIANT: before `finish`, on
        all three roads that finish a critic - the stage is never closed over the question. Allowed error: asking when not
        needed; forbidden: closing without asking. A budget the controller cannot count is the seam reason `unknown`.
        `budget`: the one the S5 loop read for this very review (its forced `unknown` included) - passed, never re-read; the
        recovery roads pass none and the gate reads the controller's count. `recovering`: this road has no loop behind it, so a
        round the route still owes the author is recorded as owed for `stage_S5` (`owe_route`). Findings nobody repairs are told
        and the factory's own defect filed here on every road, once (`s5_note_findings`)."""
        if (stage, role) != ("S5", "qa-code-critic"):
            return
        if scope is None:
            scope = ((self.controller_state().get("dispatches") or {}).get(dispatch) or {}).get("scope") or []
        cases = list(scope)
        if budget is READ_BUDGET:
            budget = self.budget_or_none("S5", "qa-automator", cases, ref=dispatch)
        route, form = self.route_of(digest, budget, dispatch)
        self.s5_note_findings(route, form, dispatch)
        if not route.get("code") or self.repair_answer(cases, dispatch):
            if recovering:
                self.owe_route(dispatch, cases, route)
            return
        if route["code"] not in ("unknown", "untyped") and self.repair_passes(budget) is None:
            self.repair_older_controller("S5", dispatch, budget, "were sent back")
        self.repair_limit_raise(self.repair_limit_facts(dispatch, cases, route, form, budget))

    def repair_older_controller(self, stage: str, dispatch: str, budget, said: str) -> None:
        """An older controller: the keys a `round` needs are not in its record, and the driver never rebuilds them (A3) - the question
        of `stage` is a refusal naming the missing key, never a `round` the driver could not record. Always raises (the seam)."""
        self.no_move({"why": "threshold", "kind": "refusal", "call": False, "stage": stage, "dispatch": dispatch,
                      "lead": f"The tests of this step {said} and the factory cannot say how many more rounds they "
                              "may have: its controller does not report them. Which of these should happen?",
                      "text": f"controller prepare for S5 qa-automator carries no repair_budget.passes: {json.dumps(budget)[:400]}"})

    def repair_limit_facts(self, dispatch: str, cases: list, route: dict, form, budget) -> dict:
        """The facts of the question, kept in the driver's state while it is open (the answer reads them): which key, which answers
        are offered, the passes a `round` / `fixed` will record, and the lead in a person's words (A6: no id, no cause token)."""
        import repair_route
        code = route["code"]
        blocking = [f for f in repair_route.findings(form) if f["blocking"]] if form else []
        causes = {f["cause"] for f in blocking}
        counted = budget.get("counted") if isinstance(budget, dict) else None
        cap = budget.get("cap") if isinstance(budget, dict) else None
        round_counted, round_cap = counted, cap       # what a `round` spends: the test_defect counter, whatever the reason (t-729 S1)
        if code == "mech_cap":
            counted, cap = budget.get("mechanical"), budget.get("mechanical_cap")      # the reason's own numbers (the opening, the debt)
        key, offer, cause = "s5.repair_limit", ["round", "debt", "fixed", "stop"], ""
        if code == "nobody":
            first = next((c for c in self.NOBODY_ORDER if c in causes), "tooling")
            key, offer, cause = {"environment": ("s5.nobody_environment", ["fixed", "debt", "stop"], "environment"),
                                 "reviewer_error": ("s5.nobody_review", ["review", "debt", "stop"], "reviewer_error"),
                                 "tooling": ("s5.nobody_tooling", ["debt", "stop"], "")}[first]
        elif code == "unknown":
            offer = ["debt", "stop"]
        elif code == "untyped":
            # F4 (d): the verdict sent the window back and the form holds no typed finding - the existing closed question
            # `s5.nobody_review` (no new key, no conductor call); `review` spends none of the repair limit
            key, offer, cause = "s5.nobody_review", ["review", "debt", "stop"], "reviewer_error"
        where = ", ".join(cases)
        opening = {
            "cap": f"For {where}: the critic sent the tests back {counted} times; the factory's limit for that is {cap} rounds, "
                   "and it is used up.",
            "mech_cap": f"For {where}: the critic asked for technical fixes to the tests {counted} times; the factory's limit for "
                        f"that is {cap} rounds, and it is used up.",
            "unknown": f"For {where}: the critic sent the tests back, and the factory could not count how many rounds they have "
                       "already had, so it will not start another on its own; starting a round and asking for one more are both "
                       "left out of the answers below.",
            "sent_back": f"For {where}: the critic sent the tests back without naming a blocking finding, so there is nothing "
                         "specific for the test writer to repair.",
            "untyped": f"For {where}: the critic sent the tests back but wrote no finding the test writer can act on; the critic "
                       "can review again and name them.",
            "nobody": {"environment": f"For {where}: the critic could not finish judging the tests because the stand got in the "
                                      "way, and the test writer cannot repair a stand.",
                       "reviewer_error": f"For {where}: the critic sent the tests back, but the doubt is about the critic's own review, "
                                         "not about the tests, and the test writer cannot repair a review.",
                       "tooling": f"For {where}: the critic sent the tests back over a fault in the factory's own tools, and the "
                                  "test writer cannot repair a tool."}.get(cause or "tooling")}[code]
        # A6: "<test> - <problem in the critic's words>" (the cause in words after it); a finding naming no test says so
        lines = [f"- {f['file'] or '(no test named)'} — {f['problem'] or 'the critic gave no reason'} "
                 f"({self.CAUSE_WORDS.get(f['cause'], f['cause'])})" for f in blocking]
        lead = "\n".join([opening, *(["", "What the critic still asks for:", *lines] if lines else []), "", "Which of these should happen?"])
        passes = self.repair_passes(budget)     # None is refused by the gate before this point, except for `unknown` (which offers no `round`)
        reason = next((f["problem"] for f in blocking if f["cause"] == cause), "") if cause else ""
        # the review debt's reason is the ledger's closed list (`ledger.DEBT_REASONS`, which holds `untyped`)
        return {"dispatch": dispatch, "cases": cases, "key": key, "offer": offer, "code": code,
                "lead": lead, "cause": cause,
                "passes": passes or {}, "counted": counted, "cap": cap, "round_counted": round_counted, "round_cap": round_cap,
                "reason": reason, "by_cause": (budget.get("by_cause") if isinstance(budget, dict) else None) or {}}

    def repair_limit_raise(self, ask: dict) -> None:
        """Keep the facts and raise the site's own question through the seam (`call=False`: no paid call; the doors are the
        question's own answers, so a word that is none of them goes to the conductor once)."""
        self.state["repair_ask"] = ask
        self.save_state()
        self.no_move({"why": "threshold", "kind": "repair_limit", "call": False, "stage": ask.get("stage", "S5"), "dispatch": ask["dispatch"],
                      "lead": ask["lead"], "site_doors": tuple(t for t in ask["offer"] if t != "stop"),
                      "site_fallback": lambda said: self.repair_limit_person(ask, said)})

    def repair_limit_person(self, ask: dict, said: str = "") -> Person:
        """The question from its facts: `said` (an unread answer's lead, else the account itself) above the account, then the priced
        answers of the key. One literal `closed_question` per key (the census of question ids reads them)."""
        lead = ask["lead"] if not said.strip() or said.strip() == ask["lead"].strip() else said.strip() + "\n\n" + ask["lead"]
        cases = ", ".join(ask["cases"])
        says = {"round": ("the test writer repairs what the critic rejected, then the critic reviews the tests again; this is round "
                          f"{(ask.get('round_counted', ask['counted']) or 0) + 1} and the factory's limit is "
                          f"{ask.get('round_cap', ask['cap'])}", {"role": "the test writer"}),
                "debt": (f"the window closes now; the tests for {cases} stay rejected and the report lists each with what the "
                         "critic asked", {}),
                "fixed": (("answer this once you have fixed the stand; the critic then reviews the tests again", {"what": "the stand"})
                          if ask["key"] == "s5.nobody_environment" else
                          ("answer this once you have changed the tests yourself; the critic then reviews them again",
                           {"what": "the changes the critic asked for"})),
                "review": ("the critic reviews the window again; this round spends none of the repair limit", {"role": "the critic"})}
        if ask["key"] == "s7.repair_limit":
            says = self.s7_says(ask)
        options = [dict(self.STOP_OPTION) if a == "stop" else
                   {"answer": a, "token": a, "says": says[a][0], "slots": says[a][1]} for a in ask["offer"]]
        if ask["key"] == "s7.repair_limit":
            text = self.closed_question("s7.repair_limit", lead, options)
        elif ask["key"] == "s5.nobody_review":
            text = self.closed_question("s5.nobody_review", lead, options)
        elif ask["key"] == "s5.nobody_environment":
            text = self.closed_question("s5.nobody_environment", lead, options)
        elif ask["key"] == "s5.nobody_tooling":
            text = self.closed_question("s5.nobody_tooling", lead, options)
        else:
            text = self.closed_question("s5.repair_limit", lead, options)
        return Person("repair_limit", text, ask.get("stage", "S5"), ask["dispatch"])

    @staticmethod
    def s7_says(ask: dict) -> dict:
        """The code-side words of the S7 answers (the price lines come from the data): no critic reviews an S7 repair, so `round` is the
        author's one more session and a new run of the test; `debt` leaves the test failing and listed."""
        return {"round": (f"the test writer repairs {ask['name']} once more and the test is run again; this is round "
                          f"{(ask.get('round_counted') or 0) + 1} and the factory's limit is {ask.get('round_cap')}", {"role": "the test writer"}),
                "debt": ((f"the repairs of {ask['name']} stop now; it stays failing and the report lists it with the reason the run failed"
                          if ask.get("bound", True) else
                          f"the repairs of {ask['name']} stop now; it stays failing and is recorded under the run's own name; it is "
                          "not yet listed in the report"), {})}

    @staticmethod
    def repair_pass_keys(token: str, ask: dict, stage: str) -> list:
        """The waiver keys an answer records, from the controller's own `passes` (never rebuilt): `round` the author's and, at S5, the
        critic's (an S7 repair has no critic); `fixed` the critic's only, and only for the cap question; every other token none."""
        passes = ask["passes"]
        if token == "round":
            return [passes["qa-automator"]] + ([] if stage == "S7" else [passes["qa-code-critic"]])
        return [passes["qa-code-critic"]] if token == "fixed" and ask["key"] == "s5.repair_limit" else []

    def _answer_repair_limit(self, words: str, qtext: str, stage: str, dispatch: str) -> None:
        """The answer to the repair-limit question (FR-9: each token has an executor; FR-12: tokens only). `round` records the two
        passes of the controller's own keys (the author's and the critic's, one answer; the author's alone at S7); `fixed` the critic's
        pass only (or none, for the stand); `review` none; `debt` the window in `work/review-debts.json` through THE writer; `stop` holds
        the question. The choice is kept per window and critic dispatch (S7: per test and count), so the gate lets exactly that review
        (that round) through; any other word goes to the seam."""
        ask = self.state.get("repair_ask") or {}
        token = self.s0_normalize(words)
        kept = self.state.get(self.repair_store_name(stage)) or {}
        if token == "debt" and ask.get("dispatch") != dispatch and any(
                isinstance(e, dict) and e.get("dispatch") == dispatch and e.get("token") == "debt" for e in kept.values()):
            # t-733 edges 1 and 3: the same `debt` again (its question is answered already, the window perhaps closed): nothing new is written
            print(f"{stage}: the answer `debt` is recorded already; nothing more is written")
            return
        if ask.get("dispatch") != dispatch or token not in ask.get("offer", ()):
            self.unread("repair_limit", stage, dispatch, qtext, words=words, doors=tuple(ask.get("offer") or ("stop",)),
                        lead=self.unread_lead(words), again=lambda said: self.repair_limit_person(ask, said) if ask else self.held_question(said))
            return
        spent = ask.get("round_counted", ask.get("counted"))
        surplus = token == "round" and isinstance(spent, int) and isinstance(ask.get("round_cap", ask.get("cap")), int) \
            and spent < ask.get("round_cap", ask.get("cap"))
        # the Lead's answer 5 (t-716): a surplus round is acceptable ONLY because the person bought it by this token - the record says so
        self.answer_row(f"{stage} repair limit ({token}{', round bought on a cap not spent' if surplus else ''}): ", words.strip(),
                        what="your answer at the repair limit")
        if token == "stop":
            raise self.held_question(self.stop_held("If you want the factory to go on after all, answer one of the other answers."))
        if stage == "S7" and not ask.get("life"):       # N10: under life "" nothing is written and nothing is trusted (FR-59)
            raise self.held_question("The factory could not read which triage run this question belongs to, so your answer was not "
                                     "recorded and nothing was passed.")
        file = self.answer_file()
        for key in self.repair_pass_keys(token, ask, stage):
            code, out = self.py("waiver.py", "--task", self.task, "--stage", "S5", "--block", key, "--words-file", str(self.task_root / file),
                                *self.waiver_road())
            if code:
                print(f"{stage}: the pass was not recorded ({out[-300:]}); the question comes back")
                raise self.held_question("Your word could not be recorded as the pass for another round, so nothing was passed.", out)
        if token == "debt" and not self.record_repair_debt(ask, file):
            raise self.held_question("Your choice could not be recorded: the record of the earlier answers of this kind cannot be read, "
                                     "so the window stays open and nothing is closed.")
        slot = dispatch if stage == "S7" else self.repair_key(ask["cases"])      # S7: one record per test and count, the dispatch IS the slot
        before = kept.get(slot) or {}
        # t-733: a `debt` to the question of an OWED round (the round of this very critic dispatch) consumes it: `stage_S5` completes the finish
        consumed = before.get("token") if token == "debt" and before.get("dispatch") == dispatch and before.get("token") in ("round", "route") else ""
        self.state.setdefault(self.repair_store_name(stage), {})[slot] = {
            "dispatch": dispatch, "token": token, "cases": ask["cases"], "key": ask["key"], "at": _now(), "words_file": file,
            "cause": ask["cause"] if token in ("fixed", "review") and ask["key"] != "s5.repair_limit" else "", "reason": ask["reason"],
            "executed": token == "debt", **({"owed": consumed} if consumed else {}), **({"tests": ask["tests"], "life": ask["life"], "ident": ask["ident"]} if stage == "S7" else {})}
        self.state.pop("repair_ask", None)
        self.save_state()
        print(f"{stage}: the person's answer `{token}` is recorded for {ask.get('name') or ', '.join(ask['cases'])}")

    @staticmethod
    def repair_store_name(stage: str) -> str:
        """The driver-state key that keeps the answers of the repair-limit question: the S5 windows' (`repair_limit`, matched by their
        cases) and the S7 tests' (`repair_limit_s7`, one per test and count) are two stores, so no S5 reader meets an S7 record."""
        return "repair_limit_s7" if stage == "S7" else "repair_limit"

    def record_repair_debt(self, ask: dict, words_file: str) -> bool:
        """The window as a review debt, through THE writer (`ledger.write_review_debt`); False when the writer could not record it.
        An S7 window names its TESTS (instance ids) and no critic or form; a record of S5 for the same cases is another window."""
        import ledger
        s7 = ask.get("stage") == "S7"
        form = f"work/handoffs/{ask['dispatch']}.yaml"
        window = {"stage": "S7" if s7 else "S5", "cases": ask["cases"], "tests": ask["tests"] if s7 else [],
                  "critic_dispatch": "" if s7 else ask["dispatch"],
                  "form": form if not s7 and (self.task_root / form).is_file() else "", "reason": ask["code"],
                  "rounds": {"counted": ask["counted"], "cap": ask["cap"], "by_cause": ask["by_cause"]},
                  "choice": {"token": "debt", "words_file": words_file, "at": _now()}}
        return ledger.write_review_debt(self.task_root, window) is not None

    # --- TR3-10 D (t-2283): the way question of S6, `walk_supply` (spec t-2174 Part D items 9-11, section 4, L5) -----------------------
    # The site's own closed question: asked once per project, set aside (`no_hold`: it holds no case) and put to the person at gate B.
    # Built like `repair_limit_person` (a priced `closed_question`, NO `offered`); a token has an executor, any other word goes to the
    # conductor once through `unread`. The raise site writes the registry row first and hands its id to `walk_supply_person`.
    # The tokens and the sentence each one records (the `answer` ids of `s6.walk_supply` in question-prices.json; insertion order = option order).
    WALK_SUPPLY_SENTENCES = {
        "the app makes them": ("each extra walker signs up a new user on the app's own sign-up page and makes the records it changes "
                               "through the app, on stands the project's settings allow the factory to change"),
        "one at a time": ("use only the accounts already recorded; checks that share an account or a record run one after another"),
        "I will add accounts": ("the person adds more accounts to the project's environment file and names their keys; until they are "
                                "recorded, checks that share an account run one after another")}

    def walk_supply_text(self, short: list) -> "Priced":
        """The way question (spec section 4; `human-questions.md`): what the factory did, why it cannot decide, one question, the three
        priced answers of `s6.walk_supply`; no option is recommended (the choice is the person's intent). `short` is `walk_pool.short_parts`'s
        list `[(part, lanes waiting, pool size)]`; a part is named by the role as the stand lists it (`default` is the stand's main
        account). Empty `short` (a data shortage raised it): the same question about records alone."""
        shared = []
        for part, waiting, _size in short or []:
            who = "the stand's main account" if part in ("", "default") else f"the stand's {part} account"
            shared.append(f"{who}: {waiting} group{'' if waiting == 1 else 's'} of checks had to wait for another")
        what = ("sign in as the same account (" + "; ".join(shared) + "), so they ran one after another — two walkers in one account would "
                "see each other's work" if shared else "work on the same records, so they ran one after another — two walkers changing "
                "one record would disturb each other's work")
        lead = (f"Some manual checks of this story {what}. Nothing was skipped; this story's checks already ran, only slower. Your "
                "project's settings do not say how it gets more test accounts, or which records walkers may share, and the factory does "
                "not guess. Your answer is kept for this project, so you are asked this once.\n\n"
                "How should walkers get their own accounts and records on this project?")
        sentences = self.WALK_SUPPLY_SENTENCES
        return self.closed_question("s6.walk_supply", lead, [
            {"answer": "the app makes them", "token": "the app makes them",
             "says": sentences["the app makes them"] + "; from the next story these checks run side by side, and the users they make "
                     "are named in the report and left on the stand"},
            {"answer": "one at a time", "token": "one at a time",
             "says": sentences["one at a time"] + "; manual checks keep taking longer"},
            {"answer": "I will add accounts", "token": "I will add accounts", "slots": {"what": "adding the accounts to the project's environment file"},
             "says": ("you put more accounts in the project's environment file and tell me, in your own words, the names of their keys (and, "
                      "if you like, which records walkers may share); until they are recorded the checks run one after another")}])

    def walk_supply_person(self, row_id: str, short: list) -> Person:
        """The way question as a `Person` (kind `walk_supply`, stage S6): NO `offered` (L5), `holds = ()` and `no_hold = True` (read by
        `deferrable`: it waits, holds no case and is put at gate B). `row_id` is the registry row the raise site opened; it is kept in
        `state["walk_supply_asked"]` (the one producer of what `_answer_walk_supply` reads) together with the roles of the short parts
        (`state["walk_supply_roles"]`, what `the app makes them` records). `ask()` saves the state."""
        self.state["walk_supply_asked"] = str(row_id)
        self.state["walk_supply_roles"] = list(dict.fromkeys(str(part) for part, _waiting, _size in short or [] if str(part).strip()))
        person = Person("walk_supply", self.walk_supply_text(short), "S6", answer_note=(
            "Write one of `the app makes them`, `one at a time`, `I will add accounts`, or your own words "
            "(they are read by the conductor and recorded for the project)."))
        person.holds, person.no_hold = (), True
        return person

    def _resolve_decision_row(self, kind: str, row: str, values: dict) -> None:
        """The ONE body of "resolve a registry row with the person's words" (AR-15; the S6 account/data questions share it): runs
        `project_decisions.py resolve` with the answer's words file and the pointer -> value map. No words file, or an exit != 0, is a
        `Refusal` naming the row and the exit: the question stays and the words are on record in `driver-answers.jsonl` (FR-41)."""
        file = self.answer_file()
        if not file:
            raise Refusal(f"{kind}: the answer has no words file, so row {row} was not resolved; the question stays")
        code, out = self.py("project_decisions.py", "--root", str(self.project), "resolve", "--id", row, "--words-file", str(self.task_root / file),
                            "--resolution-ref", f"{self.task} S6", "--field-values", json.dumps(values, ensure_ascii=False))
        if code:
            raise Refusal(f"{kind}: project_decisions.py resolve of row {row} failed (exit {code}); the question stays and the person's "
                          f"words are on record in driver-answers.jsonl:\n{out[-300:]}")

    def _answer_walk_supply(self, words: str, qtext: str, stage: str, dispatch: str) -> None:
        """The answer to the way question (FR-9: each token has an executor; FR-12 / AR-2: the three tokens are the whole closed set, code
        never parses any other word). A token runs `project_decisions.py resolve` on the registry row with the person's words file; the
        value at each pointer is the project's CURRENT object there with only this answer's keys replaced (merge on write: a hand-added
        `more_accounts` survives). Any other words - empty, none of the tokens, words that name a password - go to the conductor ONCE,
        whole, with the registry row named. A failed `resolve` is a `Refusal` naming the row and the exit: the question stays (FR-41),
        the words are on record in `driver-answers.jsonl`."""
        row = str(self.state.get("walk_supply_asked") or "")
        by_norm = {self.s0_normalize(token): (token, sentence) for token, sentence in self.WALK_SUPPLY_SENTENCES.items()}
        picked = by_norm.get(self.s0_normalize(words))
        if picked is None or not row:
            note = f"This question is row {row} of the project's decision registry (the id the recording command takes).\n\n" if row else ""
            self.unread("walk_supply", stage, dispatch, note + qtext, words=words, doors=tuple(self.WALK_SUPPLY_SENTENCES),
                        lead=self.unread_lead(words), again=lambda said: self.held_question(said))
            return
        token, sentence = picked
        said = words.replace(self.BOM, "").strip()
        recorded = f"{sentence}. The person answered: \"{said}\""
        import manual_capture as MC
        try:
            config = MC.load_config(self.task_root)[0]
        except ValueError as exc:
            raise Refusal(f"walk_supply: the project's settings cannot be read ({exc}), so row {row} was not resolved; the question stays")

        import config_contract as CC
        raw = CC.walk_supply_raw(config)        # the raw objects, used only to write them back whole (the deciding readers use `walk_supply`)

        def merged(slot: str, **keys) -> dict:
            return {**raw[slot], **keys}
        # TR3-10d D3b-2 (item 2): `walk_supply_roles` holds PART names (`stand_account:user`, `default`, `env:<login key>`); `self_sign_up.roles` is
        # read back as ROLE names (`walk_pool.obtain_roles_of`). A part is reduced by the readers that exist - the role after `stand_account:`,
        # `default`, the role `walk_pool.walk_env_pair` finds for an `env:` login key - and one none of them reads is left out and NAMED, never guessed.
        sign_up, left_out = [], []
        if token == "the app makes them":
            import walk_pool as WP
            stand = next((e for e in (config.get("environments") if isinstance(config, dict) else None) or [] if isinstance(e, dict)), {})
            for part in (str(p) for p in self.state.get("walk_supply_roles") or []):
                kind, _, value = part.partition(":")
                if part == "default" or (kind == "stand_account" and value.strip()):
                    role = "default" if part == "default" else value.strip()
                else:
                    role = WP.walk_env_pair(stand, value)[0] if kind == "env" and value.strip() else ""
                if not role:
                    left_out.append(part)
                elif role not in sign_up:
                    sign_up.append(role)
        accounts = {"words": recorded, **({"self_sign_up": {"roles": sign_up}} if token == "the app makes them" else {})}
        names = CC.walk_supply_keys()
        values = {f"/manual/{names['accounts']}": merged("accounts", **accounts), f"/manual/{names['data']}": merged("data", words=recorded)}
        self._resolve_decision_row("walk_supply", row, values)
        self.state.pop("walk_supply_roles", None)
        self.answer_row("S6 walk supply: ", said, what="your answer about how walkers get their accounts and records")
        print(f"S6: the answer `{token}` is recorded for this project")
        if left_out:
            print(f"S6: these accounts could not be read as roles of the stand, so they are not on the list of roles a walker may sign up as: "
                  f"{', '.join(left_out)}")
        if token == "I will add accounts":
            print("S6: you said you will add accounts; until they are in the project's settings the checks that share an account run "
                  "one after another")

    # --- TR3-10 D3a step 2 (t-2290): the data-change question `data_change` (spec t-2174 Part D item 12) -------------------------------
    # Whether the factory may make and remove records on the stand for the pools; asked once per project, set aside like `walk_supply`
    # (`no_hold`), a token has an executor (`_answer_data_change`), any other word goes to the conductor once. The raise site writes the
    # registry row first and hands its id to `data_change_person`. The keys ARE the three sentences `config_contract.DATA_MAY_OPTIONS` reads
    # back (the `answer` ids of `s6.data_change`; a test pins the two together); the value is what the option means to the person.
    DATA_CHANGE_SAYS = {
        "only use what exists": ("the factory never makes or removes records; checks that need their own record run one after another, "
                                 "and these checks keep taking longer"),
        "may create, never delete": ("a walker makes its own record for such a check; the record stays on the stand and the report names it; "
                                     "later each such walker spends a few steps making a record"),
        "may create and delete": ("a walker makes its own record for such a check and removes it when the check is done; a few more steps "
                                  "per such check")}

    def data_change_text(self, kinds: list, may_change: bool = True) -> "Priced":
        """The data-change question (spec item 12; `human-questions.md`): the kinds in the story's words (empty `kinds`: "a record"),
        that the answer applies to the stand the person's settings name, that this story's checks already ran one after another (D.4),
        and - when `may_change` is False - that the settings do not mark the stand as one that may be changed. No option is recommended."""
        names = [str(k).strip() for k in kinds or [] if str(k).strip()]
        things = [("an " if n[0].lower() in "aeio" else "a ") + n for n in names] or ["a record"]
        what = things[0] if len(things) == 1 else ", ".join(things[:-1]) + " and " + things[-1]
        stand = ("" if may_change else " Your settings do not mark this stand as one that may be changed, so until you answer the factory "
                                         "only uses what exists.")
        lead = (f"Some manual checks of this story change {what} that other checks also use, and the project's list has no free one for each "
                "walker, so those checks ran one after another; nothing was skipped and this story's checks already ran, only slower. "
                f"Your answer applies to the stand your settings name.{stand} Your answer is kept for this project, so you are asked this once.\n\n"
                "May the factory make records on the stand for them, and remove them afterwards?")
        return self.closed_question("s6.data_change", lead, [
            {"answer": token, "token": token, "says": says} for token, says in self.DATA_CHANGE_SAYS.items()])

    def data_change_person(self, row_id: str, kinds: list, may_change: bool = True) -> Person:
        """The data-change question as a `Person` (kind `data_change`, stage S6): NO `offered`, `holds = ()`, `no_hold = True` (read by
        `deferrable`). `row_id` is the registry row the raise site opened; it is kept in `state["data_change_asked"]` (the one producer of
        what `_answer_data_change` reads, and the raise site's "once per story" test). `ask()` saves the state."""
        self.state["data_change_asked"] = str(row_id)
        person = Person("data_change", self.data_change_text(kinds, may_change), "S6", answer_note=(
            "Write one of `only use what exists`, `may create, never delete`, `may create and delete`, or your own words "
            "(they are read by the conductor and recorded for the project)."))
        person.holds, person.no_hold = (), True
        return person

    def _answer_data_change(self, words: str, qtext: str, stage: str, dispatch: str) -> None:
        """The answer to the data-change question (FR-9: each token has an executor; FR-12 / AR-2: the three tokens are the whole closed
        set, code never parses another word). A token runs `project_decisions.py resolve` with `{"/manual/data_way/may": <the sentence>}`;
        any other words go to the conductor ONCE, whole, the registry row named. No `data_change_asked` in state, or a failed `resolve`,
        is a `Refusal` naming what is missing / the row and the exit: the question stays."""
        row = str(self.state.get("data_change_asked") or "")
        if not row:
            raise Refusal("data_change: the state has no `data_change_asked` (the registry row of this question), so the answer cannot be "
                          "recorded; the question stays and the person's words are on record in driver-answers.jsonl")
        picked = {self.s0_normalize(token): token for token in self.DATA_CHANGE_SAYS}.get(self.s0_normalize(words))
        if picked is None:
            self.unread("data_change", stage, dispatch,
                        f"This question is row {row} of the project's decision registry (the id the recording command takes).\n\n" + qtext,
                        words=words, doors=tuple(self.DATA_CHANGE_SAYS), lead=self.unread_lead(words), again=lambda said: self.held_question(said))
            return
        self._resolve_decision_row("data_change", row, {"/manual/data_way/may": picked})
        self.answer_row("S6 data change: ", words.replace(self.BOM, "").strip(), what="your answer about what the factory may do with records")
        print(f"S6: the answer `{picked}` is recorded for this project")

    # --- TR3-10 D (t-2291): the account question of S6, `walk_account` (spec t-2174 item 13; sibling of `stand_login_gate`, AR-15) ----------
    # Asked for the data of ONE account the project does not have, one question per role; it holds the tied cases (deferrable through the
    # EXISTING rule: no `no_hold`). Built like `walk_supply_person` (a priced `closed_question`, NO `offered`). `by hand` / `go on` are carried
    # out here as `stand_login_gate` does; `added` and every other word go to the conductor (it records key NAMES, code never parses words).
    def walk_account_text(self, role: str, cases: list, lines: list) -> "Priced":
        """The account question (`human-questions.md`): what is missing, in the project's words, what the factory did (the other checks go
        on), one question, the three priced answers of `s6.walk_account`. `lines` are the formed case lines (`case_lines`: title and id);
        `role` is named as the stand lists it. No key path and no file of ours in the body: the project's environment file is the person's
        own and is named only because the question asks them to edit it."""
        who = "main" if role in ("", "default") else role
        lead = (f"These checks need a {who} account that the project's settings do not have yet:\n" + "\n".join(lines)
                + f"\nI have not started {'it' if len(cases) == 1 else 'them'}. Nothing else waits for it: the other checks go on. "
                "Put the account's login and password in your project's environment file (never in this chat) and tell me the names "
                "of the two keys.\n\nWhat should happen with these checks?")
        return self.closed_question("s6.walk_account", lead, [
            {"answer": "added", "token": "added", "slots": {"what": "adding the account's login and password to your project's environment file"},
             "says": ("you put the account's login and password in the environment file and tell me the names of the two keys; I record the "
                      "names, check that the account signs in, and the next run of the story checks these cases")},
            {"answer": "by hand", "token": "by hand", "slots": {"what": "the checks named above"},
             "says": "you will check these yourself; I leave them out and the report says so, in your words"},
            {"answer": "go on", "token": "go on",
             "says": "leave them unchecked; the report carries them as not checked"}])

    def walk_account_person(self, row_id: str, role: str, cases: list, case_lines: list) -> Person:
        """The account question as a `Person` (kind `walk_account`, stage S6): NO `offered` (L5), `holds` = the tied cases and NO `no_hold`
        (`deferrable` sets it aside through its existing case test). `case_lines` are the lines the raise site formed (it lives above
        `Driver.case_lines`' layer). The one producer of `state["walk_account_asked"][row_id] = {"role", "cases"}`, which
        `_answer_walk_account` reads. A role the code cannot hand to the conductor as a key (empty, with a space, non-ASCII), no tied case or no
        registry row is a `Refusal` that says what is missing: nothing is asked, nothing guessed."""
        role, row_id = str(role or ""), str(row_id or "")
        tied = [str(case) for case in cases or [] if str(case).strip()]
        if not role or not role.isascii() or any(ch.isspace() for ch in role):
            raise Refusal(f"walk_account: the role {role!r} cannot be named as an account key (it is empty, has a space or a non-ASCII "
                          "character); the account question was not raised")
        if not tied:
            raise Refusal(f"walk_account: no case is tied to the {role} account, so the question has nothing to hold; it was not raised")
        if not row_id:
            raise Refusal(f"walk_account: no registry row for the {role} account was given, so the answer could not be recorded; the question "
                          "was not raised")
        held = self.state.get("walk_account_asked")
        self.state["walk_account_asked"] = held = held if isinstance(held, dict) else {}
        # TR3-10d D3b-2 (fix a): ONE live row per role - a stale row of this role under another id goes, so a later answer never meets two
        for stale in [key for key, val in held.items() if key != row_id and isinstance(val, dict) and val.get("role") == role]:
            held.pop(stale)
        held[row_id] = {"role": role, "cases": tied}
        seen = self.state.get("walk_account_roles")
        self.state["walk_account_roles"] = seen = seen if isinstance(seen, dict) else {}
        seen[role] = row_id        # kept for the story (never popped): the raise site asks a role once per story
        person = Person("walk_account", self.walk_account_text(role, tied, [str(line) for line in case_lines or []]), "S6", answer_note=(
            "Write `added` and the two key names (for example `added: <LOGIN KEY> and <PASSWORD KEY>`; never the password itself), "
            "`by hand` or `go on`, or your own words (they are read by the conductor)."))
        person.holds = tuple(tied)
        return person

    def _answer_walk_account(self, words: str, qtext: str, stage: str, dispatch: str) -> None:
        """The answer to the account question (FR-9: each token has an executor; FR-12 / AR-2: three tokens, never a phrase). `by hand` ->
        `refuse_case(..., "person_checks")`, `go on` -> `refuse_case(..., "left_unchecked")` for every tied case, as `stand_login_gate`
        does. A BARE `added` (no key name for the conductor to record) is asked again ONCE (`state["walk_account_again"][role]`) with the
        reason "you said the account is added, but did not name the two keys" (D3b-2: not "the keys you named are not in the environment
        file" - that is for a probe that found no keys), then treated as `go on` (one recorded decision per class, P5). `added`
        with names and every other word go to the conductor ONCE, whole: it records key names. The words are never copied into a text
        built here (a password may stand in them). The question's role and cases come from `state["walk_account_asked"]`: the entry whose
        cases are the deferred item's `holds`, else the only entry; none or several that cannot be told apart is a `Refusal`."""
        entries = self.state.get("walk_account_asked")
        entries = {str(key): val for key, val in entries.items() if isinstance(val, dict) and val.get("role") and val.get("cases")} \
            if isinstance(entries, dict) else {}
        if not entries:
            raise Refusal("walk_account: the record of this question (its role and tied cases, `walk_account_asked`) is missing, so the "
                          "answer was not carried out; the question stays and the person's words are on record in driver-answers.jsonl")
        asked = self.state.get("asked") or {}
        chosen = None
        if asked.get("deferred_n") is not None:
            item = next((i for i in self.deferred_items() if i["n"] == asked["deferred_n"]), None)
            held = sorted(str(case) for case in (item or {}).get("holds") or [])
            same = [key for key, val in entries.items() if sorted(str(case) for case in val["cases"]) == held]
            chosen = same[0] if len(same) == 1 else None
        if chosen is None and len(entries) == 1:
            chosen = next(iter(entries))
        if chosen is None:
            raise Refusal("walk_account: " + str(len(entries)) + " account questions are recorded and none of them is the one answered, so "
                          "the answer was not carried out; the question stays and the person's words are on record in driver-answers.jsonl")
        row, role, cases = chosen, str(entries[chosen]["role"]), [str(case) for case in entries[chosen]["cases"]]
        again = self.state.get("walk_account_again")
        self.state["walk_account_again"] = again = again if isinstance(again, dict) else {}
        token = self.s0_normalize(words)
        reason = ""
        if token == "added" and not again.get(role):
            again[role] = 1
            # remains: the person's own question comes back once with what is missing (the two key names); a second "added" closes as `go on`
            raise self.held_question("You said the account is added, but did not name the two keys. Tell me the names of the two variables "
                                     "in your environment file that hold its login and password, or answer `by hand` or `go on`.")
        if token == "added":
            token, reason = "go on", "you said the account is added but did not name its two keys, after you were asked twice"
        if token in ("by hand", "go on"):
            by = "person_checks" if token == "by hand" else "left_unchecked"
            reason = ("not checked by an agent: the " + role + " account it needs is not in the project's settings"
                      + (f"; you answered `{token}`" if not reason else f"; {reason}"))
            door = "put the account's login and password in the project's environment file and name the keys; the next run checks it by hand"
            for case in cases:
                if self.refuse_case(None, case, reason, door, by):
                    print(f"S6: {case}: not checked by hand — {reason}")
                else:
                    print(f"S6: {case}: the decision could not be written to its request.json; the answer is on record")
            entries_left = self.state.get("walk_account_asked")
            entries_left.pop(row, None)
            again.pop(role, None)
            self.answer_row("S6 walk account: ", token, what=f"your answer about the {role} account")
            return
        note = (f"This question is row {row} of the project's decision registry (the id the recording command takes). It asks for the "
                f"account of the role `{role}` (the key of the account in the project's settings) for these cases: {', '.join(cases)}.\n\n")
        self.unread("walk_account", stage, dispatch, note + qtext, words=words, doors=("added", "by hand", "go on"),
                    lead=self.unread_lead(words), again=lambda said: self.held_question(said))

    # --- an exit-gate refusal that survives the resume limit: the ONE seam (conductor/1, C1-5d; t-698 §12-§14, t-764) -----------
    # The class (FR-42, P22): the role was resumed once on this finding set (t-217) and the set came back; `rework` has nothing to
    # rework because no dispatch of the role is accepted. Five callers reach `exit_limit`: the handoff ladder (E3/E6), the refusal
    # road (E8, E9), a resume whose session is gone (E10) and the structured-artifact repeat (E11). It asks the person directly
    # (`call=False`: the conductor reads only words code cannot), with four answers whose executors are `_answer_exit_limit`'s.
    EXIT_SOURCES_SHOWN = 12         # sources the lead lists; the rest is counted (the GATE_TOP_LIMIT precedent)

    def exit_record(self, dispatch: str) -> dict:
        """`state["exit_limit"][dispatch]`: `lines` (the set that reached the seam), `key`, `rounds` ({key: {granted, spent,
        words_file, at}}), `ask` (the question's facts), `passes` (the waiver rows `go on` wrote), `fresh_line`."""
        held = self.state.get("exit_limit")
        if not isinstance(held, dict):
            held = self.state["exit_limit"] = {}
        rec = held.get(dispatch)
        if not isinstance(rec, dict):
            rec = held[dispatch] = {}
        return rec

    def revoke_passes_of_dead(self, dead=()) -> None:
        """t-764 A5 (F3): ONE sweep that revokes the waiver rows `go on` wrote for every dispatch the controller no longer holds
        live (accepted, released, superseded, stale ... - `NM.LIVE_STATUSES` is the live set; `dead`: dispatches known dead before
        the controller's record shows it). A row outlives its dispatch only until the next call of this sweep, which stands at the
        top of `handoff` (t-781 m4: a dispatch the conductor's `restart` released passes nothing to the relaunch's `exit_errors`),
        at the seam's entry, at `finish` and after the seam's own `release`. A dispatch the controller does not know is not dead
        (FR-41); a revoke that fails keeps its row for the next sweep. No row anywhere: it returns at once, reads and writes nothing."""
        held = self.state.get("exit_limit")
        if not isinstance(held, dict) or not any(isinstance(r, dict) and r.get("passes") for r in held.values()):
            return
        try:
            known = self.controller_state().get("dispatches") or {}
        except Exception:
            known = {}
        changed = False
        for dispatch, rec in held.items():
            passes = rec.get("passes") if isinstance(rec, dict) else None
            status = (known.get(dispatch) or {}).get("status") if isinstance(known.get(dispatch), dict) else None
            if not passes or not (dispatch in dead or (isinstance(status, str) and status not in NM.LIVE_STATUSES)):
                continue
            import stand_gaps
            left = []
            for row in passes:
                # t-781 m3: the take-back is the DRIVER's act, in the driver's own words (the gate-A revoke precedent) - never the words
                # of the person's grant, which would read as the person taking their own pass back
                code, out = self.py("waiver.py", "--revoke", "--task", self.task, "--stage", row["stage"], "--block", row["block"],
                                    *stand_gaps.words_args(self.words_file, f"{dispatch} ended ({status or 'released'}): the driver takes "
                                                                            "the pass over the exit gate back", "revoke"), *self.waiver_road(False))
                if code:
                    print(f"{row['stage']}: the person's pass over the exit gate could not be taken back ({out[-160:]}); the next sweep tries again")
                    left.append(row)
            rec["passes"], changed = left, True
        if changed:
            self.save_state()

    def exit_limit(self, stage: str, role: str, dispatch: str, errors: list, *, sid: str, why: str, digest: str = "", error: str = "",
                   text: str = "") -> None:
        """The ONE seam for an exit-gate refusal that survives the resume limit. `errors`: the lines that reached it, already the
        caller's `refusal_lines` (normalised ONCE there, never again here; `None` / `[]` = no lines: the generic question, no record); `text`: the
        refusal's own words, whole, when it has them (they are the details file). `sid`: the
        role's session ('' = none). `why`: handoff | refusal | structured | session_gone. Returns ONLY after a paid round the
        person bought (the caller judges the role's new result); every other way out raises `Person` through `no_move`
        (`call=False`): the question is the site's own, closed and priced. POSITION INVARIANT: after the free resume, the
        mechanical third turn and the S1 person branches (callers), before any `finish` - a stage is never closed over this
        question. The sweep runs first; the person's words the role already answered are spent (F-d8)."""
        self.revoke_passes_of_dead()
        lines = [str(e) for e in (errors or []) if str(e).strip()]      # the caller's `refusal_lines`, normalised ONCE there (t-842 F3)
        key = finding_key(lines)
        rec = self.exit_record(dispatch)
        rec.update(lines=lines, key=key, stage=stage, role=role)
        self.state["pending_words"].pop(dispatch, None)
        self.save_state()
        bought = (rec.get("rounds") or {}).get(key) or {}
        if sid and key and why != "session_gone" and bought.get("granted", 0) > bought.get("spent", 0):
            return self.exit_round(stage, role, dispatch, lines, sid, rec, key, why)
        ask = self.exit_limit_facts(stage, role, dispatch, lines, sid=sid, why=why, digest=digest, error=error, text=text)
        rec["ask"] = ask
        self.save_state()
        self.no_move({"why": "threshold", "kind": "exit_limit", "call": False, "stage": stage, "dispatch": dispatch,
                      "lead": ask["lead"], "text": ask["details"], "lines": lines, "site_doors": tuple(t for t in ask["offer"] if t not in NM.TOKEN_MOVES),
                      "site_fallback": lambda said: self.exit_limit_person(ask, said)})

    def exit_round(self, stage: str, role: str, dispatch: str, lines: list, sid: str, rec: dict, key: str, why: str = "handoff") -> None:
        """The paid round the person bought (`round`, once per answer): spent BEFORE the call (the `note_resume` rule - a crash
        costs one round and never repeats one), in the role's own session, with the check's exact lines and the person's words
        WHOLE (FR-8) as its instruction. The result is the dispatch's saved result (`resume_with`)."""
        taken = rec["rounds"][key]
        taken["spent"] = taken.get("spent", 0) + 1
        self.save_state()
        try:
            words = (self.task_root / taken["words_file"]).read_bytes().decode("utf-8", "replace").strip() if taken.get("words_file") else ""
        except OSError:
            words = ""
        print(f"{stage}: {dispatch} gets one more turn in its own session on the person's answer (round {taken['spent']} of this set)")
        refusal = Refusal(self.exit_ask(role, dispatch, lines, why=why), dispatch=dispatch, findings=lines)
        self.resume_with(refusal, stage, dispatch, sid,
                         "A person has answered what to do about the refusal below. Their words, whole, are your instruction for "
                         "this turn:\n\n" + (words or "(they gave no words beyond the choice)") + "\n\n",
                         reason=f"paid round {taken['spent']} on the person's answer: " + resume_reason(lines), sentence="")

    def s1_open_work(self) -> list:
        """The sources of the S1 inventory with open points of the factory's own work (`source:not_inspected` ...), from the
        inventory's own readers (`completeness`, `gap_points`): `[{source_id, key, text, points}]`, [] when there is none. A reader
        that cannot read the inventory raises - the caller says the structured reader failed and falls to the count (FR-12)."""
        import source_inventory as SI
        inventory = SI.load_inventory(self.task_root / "work" / "source-inventory.json")
        opened = SI.completeness(inventory).get("open_points") or {}
        rows = []
        for item in inventory.get("sources") or []:
            sid = item.get("source_id")
            work = [p for p in SI.gap_points(item) if p["id"] in set(opened.get(sid) or []) and p["class"] == SI.POINT_WORK]
            if work:
                rows.append({"source_id": sid, "key": SI._key(item), "text": "; ".join(p["text"] for p in work),
                             "points": [p["id"] for p in work]})
        return rows

    def exit_missing(self, stage: str, role: str, lines: list) -> tuple:
        """(what is still missing, in words; the S1 rows or []). Structured readers first, the gate's text is never parsed: at S1
        with a readable inventory one line per source with open work, `{ticket key} — {point text}` (at most EXIT_SOURCES_SHOWN,
        then `(+k more)`); otherwise a count and the details file (the unreadable inventory is this branch too)."""
        rows = []
        if stage == "S1":
            try:
                rows = self.s1_open_work()
            except Exception:
                rows = []
        if rows:
            shown = [f"- {r['key']} — {r['text']}" for r in rows[:self.EXIT_SOURCES_SHOWN]]
            more = len(rows) - self.EXIT_SOURCES_SHOWN
            return "\n" + "\n".join(shown + ([f"(+{more} more)"] if more > 0 else [])), rows
        count = f" in {len(lines)} place(s)" if lines else ""
        return f"the {self.role_words(role)}'s handover is not complete{count}; the check's own words are in the file named below", rows

    def exit_next_gate(self, stage: str) -> str:
        """The gate that comes after `stage`, from stages.json `gate_before` (the first LATER stage that names one), in words."""
        try:
            stages = self.stages()
            later = sorted((s for s in stages if re.fullmatch(r"S\d+", s) and int(s[1:]) > int(stage[1:])), key=lambda s: int(s[1:]))
            gate = next((stages[s].get("gate_before") for s in later if stages[s].get("gate_before")), "")
        except Exception:
            gate = ""
        return {"A": "the plan gate (gate A)", "B": "the delivery gate (gate B)"}.get(str(gate), "the retro")

    def exit_fresh_blocked(self, stage: str, facts: dict) -> str:
        """Why `fresh` cannot be offered, in words ('' when it can): the stage is closed, the story is closed (S9 would reopen it),
        or the dispatch is not one `release` frees (`NM.LIVE_STATUSES`). An unreadable fact blocks it (FR-41)."""
        try:
            closed_stage = ((self.controller_state().get("stages") or {}).get(stage) or {}).get("status") in ("completed", "skipped")
        except Exception:
            closed_stage = True
        if closed_stage:
            return "this step is already closed"
        if facts.get("closed") is not False:
            return "the story is closed" if facts.get("closed") else "the factory could not read the state of the story"
        if facts.get("dispatch_status") not in NM.LIVE_STATUSES:
            return "its work can no longer be set aside"
        return ""

    def exit_limit_facts(self, stage: str, role: str, dispatch: str, lines: list, *, sid: str, why: str, digest: str, error: str,
                         text: str = "") -> dict:
        """The facts of the question, kept in the driver's state while it is open (the answer reads them): the lead in the story's
        words (A9: conditional - no session, structured, the paid count only when above 0), the options offered and what each says,
        the details file. Every option that is absent is SAID (FR-42)."""
        who = "the " + self.role_words(role)
        up = who[0].upper() + who[1:]
        spent = sum(r.get("spent", 0) for r in (self.exit_record(dispatch).get("rounds") or {}).values())
        try:
            form = self.form_errors(dispatch)
        except Exception:
            form = []
        facts = self.no_move_facts({"dispatch": dispatch, "kind": "exit_limit"})
        absent, fresh_why = {}, self.exit_fresh_blocked(stage, facts)
        if not sid:
            absent["round"] = f"{up}'s session cannot be resumed, so it cannot be given another turn."
        elif why == "session_gone":
            absent["round"] = f"{up}'s session no longer answers, so it cannot be given another turn."
        if fresh_why:
            absent["fresh"] = f"Starting it again is not possible here: {fresh_why}."
        if form:
            turns = " or ".join(w for w, token in (("give it another turn", "round"), ("start it again", "fresh")) if token not in absent)
            absent["go on"] = (f"{up}'s handover form is not complete in {len(form)} place(s); only {who} can fill it"
                               + (f" — {turns}." if turns else "."))
        missing, rows = self.exit_missing(stage, role, lines)
        place = self.stage_place(stage)
        again = "" if not spent else (", and once more after your answer" if spent == 1 else f", and again {spent} times after your answers")
        if not sid:
            sent = f"{up}'s session cannot be resumed, so it could not be sent back."
        elif why == "session_gone":
            sent = f"{up} was sent back over it, but its session no longer answers."
        elif why == "structured":
            sent = f"{up} was sent back once over its structured handover and came back with the same gaps{again}."
        else:
            sent = f"{up} was sent back once with exactly what the check named, and came back with the same gaps{again}."
        try:
            import role_digest
            halting = bool(digest) and role_digest.is_halting(digest)
        except Exception:
            halting = False
        lead = "\n".join([
            f"The story is at {place}. {up} finished its work there, and the factory's own check of that work refused to let the stage "
            f"go on. {sent}" + (f" {up} also says it cannot go on; its own words are in the file named below." if halting else ""),
            "", "What is still missing:" + (missing if missing.startswith("\n") else " " + missing), *(["", *[absent[t] for t in ("round", "fresh", "go on") if t in absent]] if absent else []), "",
            "The factory cannot finish this step by itself. Which of these should happen?"])
        keys = ", ".join(r["key"] for r in rows)
        consequence = (f"the {self.role_words('qa-scout')}'s reading notes on {keys} are not written; the next roles read those tickets as fetched; "
                       "the plan gate (gate A) lists them among what you decided" if rows and stage == "S1" else
                       f"what the check named stays undone and is kept with your words; {self.exit_next_gate(stage)} lists it among what you decided")
        shown = "the step closes as it is: " + consequence
        halt = self.halt_key(digest) if halting and sid and why != "session_gone" else ""
        says = {"round": (f"{who} gets one more turn in its own session, with the check's exact words and your answer as its instruction; "
                          "then the check looks again", {"role": who}),
                "fresh": (f"{who}'s session is set aside and the role starts this step again from its brief, with the check's words and your "
                          "answer; what it wrote stays on disk for it to read", {"stages": f"{who}'s whole work at {place}"}),
                "go on": (shown, {})}
        if halt:
            says["go on"] = (shown + f"; first {who} reads your words once in its own session and hands its work over again, because it "
                             "also said it cannot go on", {"role": who})
        offer = [t for t in ("round", "fresh", "go on") if t not in absent] + ["stop"]
        options = [dict(self.STOP_OPTION) if t == "stop" else {"answer": t, "token": t, "says": says[t][0], "slots": says[t][1]} for t in offer]
        details = (text.strip() or "The check's lines, whole:\n- " + "\n- ".join(lines)) + (f"\n\nThe resume's own error:\n{error}" if error else "")
        details += f"\n\nThe role's last words:\n{digest.strip()}" if digest.strip() else ""
        return {"stage": stage, "dispatch": dispatch, "lead": lead, "options": options, "offer": offer, "shown": shown,
                "details": details, "form": len(form), "halt": halt}

    @staticmethod
    def halt_key(digest: str) -> str:
        """The identity of the halt a person was shown: a hash of the digest's words (whitespace-normalised); "" for no digest."""
        norm = " ".join(str(digest or "").split())
        return hashlib.sha256(norm.encode("utf-8")).hexdigest()[:16] if norm else ""

    def exit_limit_person(self, ask: dict, said: str = "") -> Person:
        """The question from its facts: `said` (an unread answer's lead, else the account itself) above the account, then the priced
        answers of `exit.resume_limit`. ONE literal `closed_question` (the census of question ids reads it)."""
        lead = ask["lead"] if not said.strip() or said.strip() == ask["lead"].strip() else said.strip() + "\n\n" + ask["lead"]
        text = (self.closed_question("exit.resume_limit_halted", lead, ask["options"]) if ask.get("halt")
                else self.closed_question("exit.resume_limit", lead, ask["options"]))
        return Person("exit_limit", text, ask["stage"], ask["dispatch"], details=ask["details"])

    def _answer_exit_limit(self, words: str, qtext: str, stage: str, dispatch: str, *, words_file: str = "") -> bool:
        """The answer to the exit-limit question (FR-9: each token has an executor; FR-12: tokens only). `round` records the one
        round the answer buys (the paid call is spent inside `exit_limit`, on the next entry); `fresh` sets the work aside through
        the controller's `release` and the relaunch carries the check's lines; `go on` passes the lines that REACHED the seam
        (S1: the sources' open work first) and files the factory finding; `stop` holds the question. Any other word goes to the
        conductor once. `words_file`: the person's ORIGINAL words (the conductor road); else this answer's file. True = a token."""
        rec = (self.state.get("exit_limit") or {}).get(dispatch) or {}
        ask = rec.get("ask") or {}
        token = self.s0_normalize(words)
        if not ask or token not in ask.get("offer", ()):
            self.unread("exit_limit", stage, dispatch, qtext, words=words, doors=tuple(ask.get("offer") or ("stop",)),
                        lead=self.unread_lead(words), again=lambda said: self.exit_limit_person(ask, said) if ask else self.held_question(said))
            return False
        if (self.pipeline().get("stages") or {}).get(stage, {}).get("status") == "done":
            self.after_close(stage, words)      # edge 8: no executor runs on a dispatch no longer live
            return True
        file = words_file or self.answer_file()
        self.answer_row(f"{stage} exit gate ({token}): ", words.strip(), what="your answer at the exit gate")
        if token == "stop":
            raise self.held_question(self.stop_held("If you want the factory to go on after all, answer one of the other answers."))
        if token == "round":
            taken = rec.setdefault("rounds", {}).setdefault(rec["key"], {"granted": 0, "spent": 0})
            taken.update(granted=taken.get("granted", 0) + 1, words_file=file, at=_now())
        elif token == "fresh":
            self._exit_fresh(rec, stage, dispatch, file)
        else:
            self._exit_go_on(rec, stage, dispatch, file, words)
        self.save_state()
        print(f"{stage}: the person's answer `{token}` is recorded for {dispatch}")
        return True

    def _exit_fresh(self, rec: dict, stage: str, dispatch: str, file: str) -> None:
        """`fresh`: the dispatch is released by the controller's own operation (by code, no paid call) with the person's words, and
        the relaunch is told why: the check's lines and the files the first attempt left (`relaunch_reason`). A refusal of the release
        is held as it is (FR-1); the rows `go on` may have written for D are revoked by the one sweep."""
        code, out = waiver.run_release(self.task_root, dispatch, words_file=str(self.task_root / file), env=self.env)      # N4: the ONE release caller
        if code:
            raise self.held_question("Your choice could not be carried out: the factory could not set the work aside, so nothing was changed.", out)
        lines = list(rec.get("lines") or [])
        form = f"work/handoffs/{dispatch}.yaml"
        kept = list(dict.fromkeys(([form] if (self.task_root / form).is_file() else [])
                                  + [p for p in PATH_RE.findall("\n".join(lines)) if (self.task_root / p).is_file()]))
        rec["fresh_line"] = (f"A first attempt at this step ({dispatch}) was set aside by the person after the factory's own check refused it "
                             "twice. What the check named:\n- " + "\n- ".join(lines)
                             + ("\nEverything that attempt wrote stays on disk for you to read, among it: " + ", ".join(kept) if kept else
                                "\nEverything that attempt wrote stays on disk for you to read.")
                             + "\nStart this step again from your brief and repair what the check names.")
        self.revoke_passes_of_dead(dead=(dispatch,))

    def _exit_go_on(self, rec: dict, stage: str, dispatch: str, file: str, words: str) -> None:
        """`go on`: S1 first closes the sources' open work through the adapter's own door (`accept-gap --point`, the controller's S1
        check reads it), then ONE waiver row per line that reached the seam, the block = the whole line (never a keyword). The rows
        are kept for the sweep (`revoke_passes_of_dead`); the pass is filed as the factory's finding (FR-4, the `s0_file_pass`
        pattern). A command that fails is held with its output: nothing is passed in silence."""
        if stage == "S1":
            try:
                rows = self.s1_open_work()
            except Exception as exc:
                raise self.held_question("Your word could not be recorded: the sources of this step cannot be read, so nothing was passed.",
                                         f"{type(exc).__name__}: {exc}") from None
            for row in rows:
                code, out = self.py("ticket_adapter.py", "accept-gap", "--output", f"qa-factory/artifacts/{self.task}/work/source-inventory.json",
                                    "--source-id", row["source_id"], "--point", ",".join(row["points"]),
                                    "--shown-text", str((rec.get("ask") or {}).get("shown") or ""), "--words-file", str(self.task_root / file))
                if code:
                    raise self.held_question("Your word could not be recorded as the pass for the sources, so nothing was passed.", out)
        passes = rec.setdefault("passes", [])
        for line in rec.get("lines") or []:
            if any(p["block"] == line and p["stage"] == stage for p in passes):
                continue
            self.pass_block(stage, line, file, "Your word could not be recorded as the pass, so nothing was passed.")
            passes.append({"stage": stage, "block": line, "words_file": file})
        self.owe_row("project_decisions.py", "--root", str(self.project), "add-finding",
                     "--essence", f"exit gate refusal of {dispatch} passed by the person's word: {self.s0_quote(words)}; "
                                  "lines: " + "; ".join(rec.get("lines") or [])[:600],
                     "--scope", "local-calibration", "--witness", f"exit gate {dispatch}: " + str((rec.get("lines") or [""])[0])[:200],
                     "--idempotency-key", f"exit-pass:{self.task}:{dispatch}:{str(rec.get('key'))[:12]}",
                     what="the finding about the exit gate you passed", stage=stage)
        shown = (rec.get("ask") or {}).get("halt")
        if shown and shown == self.halt_key(self.digest_of(self.saved_result(dispatch).get("result") or "")):
            try:
                said = (self.task_root / file).read_text(encoding="utf-8").strip()
            except OSError:
                said = ""
            self.state["pending_words"][dispatch] = said or words
            print(f"{stage}: {dispatch} also said it cannot go on; it reads your words once in its own session, and the question it "
                  "stopped on is not asked again")

    def stage_S6(self) -> None:
        import acceptance
        auto = self.stage_scope("S6", "automation")
        manual = self.stage_scope("S6", "manual")
        for kind, got in (("automation", auto), ("manual", manual)):
            if not isinstance(got.get("scope"), list):
                # t-2020 (AR-28, FR-41): an answer without a scope is an UNKNOWN scope, not an empty one; "nothing to execute" below
                # is a close by code and is reached only over a scope the controller said was empty.
                raise Refusal(f"S6: the controller's stage-scope answer for the {kind} half has no `scope` list (expected "
                              f"`{{\"scope\": [...]}}`; got keys: {', '.join(sorted(map(str, got))) or 'none'}); the stage is not closed "
                              "over a scope nobody could read - run the step again, and if it repeats, read the controller's output")
        state = self.controller_state()
        done = [d for d in (state.get("dispatches") or {}).values() if d.get("stage") == "S6" and d.get("status") == "accepted"]
        auto_done = any(d.get("execution_kind") == "automation" or not d.get("execution_kind") for d in done)
        auto_scope, manual_scope = list(auto.get("scope") or []), list(manual.get("scope") or [])
        if self.consumer_pending("S6") and not manual_scope and "s6_probe_after" not in self.state:
            # X7-6. POSITION: the consumer's `accept` record stands and nothing more is owed to S6 (no live check to prove again, no manual
            # half): S6 closes HERE, by the record - never by the runner's own finish. A mark `s6_probe_after` or a manual half left
            # falls through to the flow below, whose close sites find the record (`consumer_need_record`).
            reason, digest = self.consumer_close_words("S6")        # N4: who accepted, from the record (the analyst, or the person's word)
            self.close_by_code("S6", reason, ["work/run-report.json"], finalize=False, site="s6.accepted", digest=digest)
            return
        if not auto_scope and not manual_scope:
            # t-305 N1 (Q19 a): the reduction comes FIRST, as in the freshness branch below and in `manual_close` -
            # S7 reads the run report of THIS close (`execution_status: not_executed`, accepted after an S6 code-only
            # receipt by `failures_to_triage`), and a close over a report nobody could build is refused, not recorded.
            # (The controller's projection reduces again after the receipt; this call fixes the ORDER and the refusal.)
            code, out = self.py("finalize_task.py", str(self.task_root))
            if code:
                raise Refusal(f"S6 nothing to execute: finalize_task.py exit {code}: " + (out.splitlines()[-1] if out else ""))
            self.close_by_code("S6", "nothing to execute: the approved plan names no automate or manual-agent case",
                               ["work/automation-manifest.json", "work/test-plan.json"], finalize=False, site="s6.nothing",
                               digest="nothing to execute")
            return
        # only a stage that has something to run asks about the stand - and says what it will run
        running_auto = bool(auto_scope) and not auto_done
        run_kind = "both" if running_auto and manual_scope else ("automation" if running_auto else "manual")
        self.stand_check("S6", run_kind)
        self.build_check("S6", run_kind, cases=(auto_scope if running_auto else []) + manual_scope)    # t-300
        no_stand = self.s6_no_stand()
        if auto_scope and not auto_done:
            fresh = self.s6_freshness(auto_scope)
            probes, attempted = fresh.get("probes") or {}, False
            if fresh["decided"] and not fresh["run"] and not manual_scope:
                # Every automated instance holds a result on its current bytes, on this stand and version:
                # nothing is launched and no runner is dispatched (t-043 D1, F2 a). A red result that
                # stands is not lost: `finalize_task` reduces the whole story, run-report.json says
                # `failed`, and S7 triages it. The code-only receipt closes the whole stage, so this
                # branch is taken only when no manual half is still to run (see `s6_freshness`).
                # The reduction comes FIRST: the receipt closes the stage, so it is written only over a
                # run-report.json the reducer just wrote. A reducer that fails (a corrupt run block) is
                # a doubt like any other: the runner is dispatched as today and told why.
                if probes:
                    # HF2-11b: the runs stand, the live checks of some changed tests do not - proved again here,
                    # BEFORE the reduction (invariant: a probe is never next to code that has no run on its current bytes)
                    attempted = True
                    code = self.s6_reprobed_close(probes, auto_scope, no_stand=no_stand, unrun=[], strict=False, reason=(
                        "every automated test has a result on its current bytes, on the same stand and version: "
                        f"{fresh['passed']} passed, {fresh['failed']} failed - reused, nothing re-run"),
                        base="every automated result stands; nothing re-run")
                    if not code:
                        return
                    fresh = dict(fresh, decided=False, why=f"finalize_task exit {code}")
                else:
                    code, out = self.py("finalize_task.py", str(self.task_root))
                    if code:
                        print(f"S6: finalize_task.py exit {code}: " + (out.splitlines()[-1] if out else ""))
                        fresh = dict(fresh, decided=False, why=f"finalize_task exit {code}")
                    else:
                        self.close_by_code("S6", "every automated test has a result on its current bytes, on the same "
                                           f"stand and version: {fresh['passed']} passed, {fresh['failed']} failed - "
                                           "reused, nothing re-run", ["work/automation-manifest.json", "state/execution-jobs"],
                                           finalize=False, site="s6.results_stand", digest="every automated result stands; nothing re-run")
                        return
            # HF2-11b: with live checks to prove again the runner does NOT close the stage - this driver closes it on its
            # return (`s6_reentry`), after the proofs, so a probe never comes before the runs of the current bytes
            owed = bool(probes) and not manual_scope and not no_stand and not attempted
            held = "s6_probe_after" in self.state
            if owed:
                self.state["s6_probe_after"] = ""        # set before the runner: a crash mid-run still owes the close
            elif held:
                del self.state["s6_probe_after"]         # a mark of an earlier life of S6 is not this one's
            if owed or held:
                self.save_state()
            left = []
            if no_stand:            # K4: no run, no probe - what changed is left for a run on a stand, and the digest says how many
                changed = [i for i, row in self.s6_changed(auto_scope).items() if "stale" in (row["run"][0], row["probe"]["state"])]
                left = [self.S6_LEFT.format(n=len(changed))] if changed else []
                for line in left:
                    print(f"S6: {line}")
            # X7-6: with a consumer the final runner window (no manual half) stops AWAITING its acceptance, `owed` included (the proofs
            # then run in `s6_reentry` after the record, whose close site finds it); `consumer_awaits` is the identity with no consumer.
            self.run_role("S6", "qa-runner", scope=auto_scope,
                          complete=(self.consumer_awaits("S6", True) if not manual_scope else False) if acceptance.consumer_of("S6") else (not manual_scope and not owed),
                          extra=["Execution kind: automation — run only instances whose evidence is missing or stale; "
                                 "reuse fresh receipts; then `finalize_task.py <task root>` writes run-report.json."]
                                + self.s6_freshness_lines(fresh) + left + self.role_lines("S6", "qa-runner"))
            if owed:
                self.state["s6_probe_after"] = str(getattr(self, "last_dispatch", "") or "")
                self.save_state()
            if manual_scope:
                self.state["s6_manual_runner"] = str(getattr(self, "last_dispatch", "") or "")    # HF8-18: read, then dropped, by N2
                self.save_state()
                return  # the loop comes back for the manual block
        elif auto_scope and not manual_scope:
            self.s6_reentry(auto_scope, no_stand)       # `auto_done`: the runner came back (HF2-11b)
        elif auto_scope and not self.manual_done():
            self.s6_reprove_before_manual(auto_scope, no_stand)     # HF8-18: the runner is accepted, no manual block yet
        if manual_scope:
            self.run_manual_block(manual_scope)

    def s6_freshness(self, cases: list) -> dict:
        """What the story already holds of the automated cases of S6, decided by code (t-043 D1).

        `{"decided": bool, "why": str, "stand": [instance ids], "run": {instance id: why},
        "passed": n, "failed": n, "probes": {instance id: replay}}`. `run` empty and `decided` True means every
        instance has a result that stands (`execution_request.fresh_evidence`, the builder `--mine` uses, AND
        `proof_level.staleness`: a result the evidence function keeps but the run row's own per-test shas say ran
        other code - a helper module `helper_files` does not name - moves from `stand` to `run`, so S6 and the
        ledger decide freshness by ONE predicate, HF2-11b). `probes` holds each instance whose live check is stale
        (`probe_freshness`), with its `replay` (what `probe_by_code.py` needs) or None when code cannot replay it. It is passed no
        `collect`, so ids come from the source, not from a real collection: a test with parameters
        can read `missing` here where `--mine` would answer `reused`. That is the safe side - one
        extra runner dispatch, never a stage closed on a guess.

        ERROR DIRECTION (a doubt never closes a stage): anything the driver cannot settle - no budget
        data, a stand nobody could look at, an evidence function that raises, an empty answer, a
        state or outcome it does not know - is `decided: False` with the reason, and the runner is
        dispatched exactly as before and told why (P1: code informs, it does not stop the factory;
        FR-41: an unknown is not reported as a fact). It reads and writes nothing of the story."""
        def undecided(why: str) -> dict:
            return {"decided": False, "why": why, "stand": [], "run": {}, "passed": 0, "failed": 0, "probes": {}}

        try:
            import execution_request
            import run_suite
            found = execution_request.fresh_evidence(self.project, self.task, list(cases), cfg=self.config,
                                                     probe=run_suite.probe_runtime)
        except Exception as exc:
            text = " ".join(str(exc).split())
            return undecided(f"{type(exc).__name__}: " + (text if len(text) <= 200 else text[:200] + self.CUT))
        instances = found.get("instances") if isinstance(found, dict) else None
        if not isinstance(instances, dict):
            return undecided("the evidence came back in a shape this driver does not know")
        if found.get("observed") is not True:
            first = next((r.get("why") for r in instances.values() if isinstance(r, dict) and r.get("why")), "")
            return undecided(str(found.get("why") or first or "the stand's version was not observed"))
        if not instances:
            return undecided("no test of these cases could be listed")
        try:
            held = self.s6_changed(cases, list(instances), strict=True)
        except Exception as exc:
            text = " ".join(str(exc).split())
            return undecided(f"{type(exc).__name__}: " + (text if len(text) <= 200 else text[:200] + self.CUT))
        stand, run, passed, failed = [], {}, 0, 0
        for instance, row in instances.items():
            state = row.get("state") if isinstance(row, dict) else None
            ran = (held.get(instance) or {}).get("run") or ("unknown", "")
            if state == "result" and row.get("outcome") in ("passed", "failed") and ran[0] == "stale":
                run[instance] = str(ran[1] or "its run is of other code")      # the evidence keeps it; the run row's shas do not
            elif state == "result" and row.get("outcome") in ("passed", "failed"):
                stand.append(instance)
                passed, failed = passed + (row["outcome"] == "passed"), failed + (row["outcome"] == "failed")
            elif state in ("stale", "missing"):
                run[instance] = str(row.get("why") or state)
            else:
                return undecided(f"{instance}: state `{state}` with outcome `{(row or {}).get('outcome')}` "
                                 "is not one this driver knows")
        probes = self.s6_probes(held)
        return {"decided": True, "why": "", "stand": stand, "run": run, "passed": passed, "failed": failed, "probes": probes}

    def s6_freshness_lines(self, fresh: dict) -> list:
        """The runner's extra lines for what `s6_freshness` found: which results stand and which
        instances are to run (with why), or - when code could not decide - the note saying so."""
        if not fresh["decided"]:
            return [f"The factory could not decide freshness ({fresh['why']}): decide per instance."]
        if not fresh["stand"]:
            return []
        run = "; ".join(f"{iid} ({why})" for iid, why in fresh["run"].items())
        return ["Results that stand: " + ", ".join(fresh["stand"]) + "; run only: " + (run or "nothing") + "."]

    # --- HF2-11b: the live checks of the tests that changed after their run are proved again by code, before S6 closes ------
    # The runs are the runner's (as before); the new move is ONE: `probe_by_code.py` per stale live check, run by the driver
    # (FR-33, FR-48: not the conductor, not a person), AFTER every automated run stands on the current bytes and BEFORE the last
    # `finalize_task.py` (invariants: a probe is never next to code that has no run on its current bytes; the reducer and the
    # ledger read the new receipt; S6 is not closed over a stale live check that could have been proved). No ceiling on how many
    # (F-7 a): the time they took is in the digest. Every failure is a digest line, never a question to a person (P1).
    # With no S6 dispatch running the probe goes in the close context of S6 (`--s6-close`, HF3-6): the tool allows it only
    # when the controller would take the S6 code-only receipt, and the receipt names each probe record.
    S6_LEFT = "{n} tests changed after their run are left for a run elsewhere"

    def s6_no_stand(self) -> bool:
        """The stage goes on WITHOUT a confirmed stand, on a person's word: no stand is confirmed and the word
        `stand not confirmed` is recorded for S5 or S6 - the carrier is the recorded word (`waiver.split_overridden`,
        the reader `stand_check` itself uses), not the answer that was given. A confirmed stand is never "no stand"."""
        pipeline = self.pipeline()
        environment = str(pipeline.get("environment") or "")
        if environment and not pipeline.get("environment_pending"):
            return False
        block = (f"{waiver.STAND_NOT_CONFIRMED_BLOCK}: " + (f"stand `{environment}` is not confirmed as usable"
                                                            if environment else "no stand is confirmed for this story"))
        return any(waiver.split_overridden([block], pipeline, owner)[1] for owner in self.STAND_STAGES)

    def s6_changed(self, cases, ids=None, *, strict: bool = False) -> dict:
        """`proof_level.staleness` over `ids` (default: the instances of the automation manifest that prove `cases`):
        `{instance id: {"run": (state, why), "probe": {"state", "why", "replay"}}}`. Reads only. `strict` lets an exception
        out (`s6_freshness` turns it into `undecided`); otherwise it is printed and nothing is known, so nothing is proved."""
        try:
            import contract as C
            import proof_level
            manifest = self.s6_manifest()
            if ids is None:
                wanted = {str(case) for case in cases}
                ids = [C.test_instance_id(t) for t in C.manifest_tests(manifest) if wanted & {str(c) for c in C.manifest_test_links(t)}]
            return proof_level.staleness(self.task_root, manifest, list(ids))
        except Exception as exc:
            if strict:
                raise
            print(f"S6: what the tests changed since their run could not be read ({type(exc).__name__}); nothing is proved again")
            return {}

    def s6_manifest(self):
        """The task's automation manifest as read (`work/` first, then the task root), or what `_read_json` gives for none."""
        return (_read_json(self.task_root / "work" / "automation-manifest.json")
                or _read_json(self.task_root / "automation-manifest.json"))

    @staticmethod
    def s6_probes(changed: dict) -> dict:
        """`{instance id: replay or None}` of the instances of `s6_changed` whose live check is `stale` - the ONE comprehension."""
        return {i: (row.get("probe") or {}).get("replay") for i, row in changed.items() if (row.get("probe") or {}).get("state") == "stale"}

    @staticmethod
    def s6_unrun(changed: dict, here: bool) -> list:
        """The instances with no run on their current bytes, next to which no probe goes: a `stale` run always; one that is not `fresh`
        (`unknown`: the row recorded no identity) unless `here` - the runner that has just run it is accepted (the ONE expression of
        `s6_reentry` and `s6_reprove_before_manual`; an unknown is never a license without the runner, FR-59)."""
        return [i for i, row in changed.items() if row["run"][0] == "stale" or (row["run"][0] != "fresh" and not here)]

    def s6_accepted(self, dispatch) -> bool:
        """Is the dispatch `dispatch` (an id; "" or None = none) accepted in the controller's state?"""
        return bool(dispatch) and ((self.controller_state().get("dispatches") or {}).get(str(dispatch)) or {}).get("status") == "accepted"

    def s6_reprove(self, probes: dict, cases, *, no_stand: bool, unrun: list) -> tuple:
        """`(digest lines, n proved, seconds, probe record paths)` for `probes` (`{instance id: replay or None}`). In this
        order, the first that applies: no stand (the word `stand not confirmed`) - no probe, `S6_LEFT`; a test with no run on
        its current bytes (`unrun`) - no probe, said; else the context (HF3-6): an S6 dispatch that is `running` and covers the
        cases - the tool is called with `--dispatch <id>` (it accepts only a `running` one); none - with `--s6-close`, the
        close context of S6, which opens no dispatch and which the tool itself refuses (one digest line, S6 still closes)
        unless the controller would take the S6 code-only receipt. Each `replay` goes to `probe_by_code.py` (`--oracle` when
        the record had one); an exit other than 0 or a verdict other than `intended_failure` is one line, no question, and the
        others go on. A `replay` of None names the instance. The last element names the probe records this pass went through
        (`work/probes/<...>.json` or, for an `already_probed` answer by a product record, `work/probes/product/<...>.json`,
        from the tool's own output) - the evidence of the close receipt. An `already_probed` answer answers only over the
        SAME bytes, so its standing record is exactly what the close stands on for that instance (decided, t-1277)."""
        if not probes:
            return [], 0, 0.0, []
        if no_stand:
            return [self.S6_LEFT.format(n=len(probes))], 0, 0.0, []
        if unrun:
            return [f"re-probe skipped: {len(unrun)} tests have no run on their current bytes ({', '.join(unrun[:5])}"
                    + (self.CUT if len(unrun) > 5 else "") + ")"], 0, 0.0, []
        running = [d for d in (self.controller_state().get("dispatches") or {}).values()
                   if isinstance(d, dict) and d.get("stage") == "S6" and d.get("status") == "running" and d.get("id")]
        covering = [d for d in running if {str(c) for c in cases} <= {str(s) for s in d.get("scope") or []}]
        dispatch = str(((covering or running) or [{}])[0].get("id") or "")
        context = ["--dispatch", dispatch] if dispatch else ["--s6-close"]
        records = []

        def cut(text) -> str:
            text = " ".join(str(text or "").split())
            return text if len(text) <= 200 else text[:200] + self.CUT
        lines, proved, tried, started = [], 0, 0, time.monotonic()
        for iid, replay in probes.items():
            if not replay:
                lines.append(f"{iid}: not proved again - the probe cannot be replayed by code (it recorded no test or mutation, or "
                             "the probe's line anchor moved with the edit); place it again by hand")
                continue
            tried += 1
            args = ["--task", self.task, *context, "--test", replay["test"], "--instance", replay["instance"],
                    "--mutation", replay["mutation"], "--json"] + (["--oracle", replay["oracle"]] if replay.get("oracle") else [])
            code, out = self.py("probe_by_code.py", *args)
            record = hooklib.read_document(out) or {}      # t-2020: pretty-printed answer; a warning with a `{` in it is skipped
            path = record.get("record")
            if isinstance(path, str) and re.fullmatch(r"work/probes/(?:product/)?[^/\\]+\.json", path) and path not in records:
                records.append(path)
            if not code and record.get("verdict") == "intended_failure":
                proved += 1
            elif record.get("verdict") == "incomplete" and record.get("cause") == "judgment":
                # t-1968 N2 (R6, E2.11): no critic window follows the S6 close, so nobody judges this record; it is said as NOT
                # proved (FR-41), asks no question, and S6 still closes. The delivery reason is `check_delivery`'s (`PL.reached`)
                lines.append(f"{iid}: the probe failed at the mutated line with a text the factory cannot read; nobody judges it at "
                             "the S6 close, so the test is not proved again")
            elif code:
                lines.append(f"{iid}: not proved again (probe_by_code exit {code}): "
                             + cut(record.get("error") or (out.splitlines()[-1] if out else "") or "it printed nothing"))
            else:
                lines.append(f"{iid}: the probe gave `{record.get('verdict') or 'no verdict'}`, not `intended_failure`: "
                             + cut(record.get("words") or "no words"))
        seconds = time.monotonic() - started
        if tried:
            lines.insert(0, f"re-proved {proved} probes after the tests changed ({seconds:.0f} s)")
        return lines, proved, seconds, records

    def s6_reprobed_close(self, probes: dict, cases, *, no_stand: bool, unrun: list, strict: bool, reason: str, base: str) -> int:
        """Prove the live checks again (`s6_reprove`), THEN reduce (`finalize_task.py`), THEN close S6 by code (site
        `s6.reprobed`, the digest `base` plus the lines). 0 when closed; else the reducer's exit code (`strict`: a Refusal,
        the way the other closes of S6 refuse - the runner is no longer to come). The mark `s6_probe_after` is dropped.
        The receipt's evidence is the manifest, the jobs and each probe record this pass went through (HF3-6: the close
        names what it stands on)."""
        self.consumer_need_record("S6", "s6_reprobed_close")        # X7-6: BEFORE the proofs, so a refusal leaves nothing proved for nothing
        lines, _proved, _seconds, records = self.s6_reprove(probes, cases, no_stand=no_stand, unrun=unrun)
        for line in lines:
            print(f"S6: {line}")
        code, out = self.py("finalize_task.py", str(self.task_root))
        if code:
            tail = out.splitlines()[-1] if out else ""
            if strict:
                raise Refusal(f"S6 close after the live checks: finalize_task.py exit {code}: {tail}")
            print(f"S6: finalize_task.py exit {code}: {tail}")
            return code
        self.close_by_code("S6", "; ".join([reason] + lines), ["work/automation-manifest.json", "state/execution-jobs"] + records,
                           finalize=False, site="s6.reprobed", digest="; ".join([base] + lines))
        if self.state.pop("s6_probe_after", None) is not None:
            self.save_state()
        return 0

    def s6_reentry(self, cases, no_stand: bool) -> None:
        """`auto_done`, no manual half: the automation runner is back (the proofs go under a running S6 dispatch when
        there is one, else in the close context of S6, `s6_reprove`). When this driver launched it with `complete=False`
        (the mark `s6_probe_after`, set when stale live checks were owed) the close is owed HERE whatever the proofs came to -
        nobody else closes S6 now. Without the mark nothing is owed, and the close happens only for stale live checks while
        every run stands on the current bytes (`staleness.run` fresh everywhere: `auto_done` is not scoped to this life of S6, an
        `invalidate` leaves earlier dispatches accepted). With the mark and the runner accepted in this life, a run the
        row recorded no identity for (`unknown`) counts as standing, as the runner has just run it; a `stale` run never does."""
        owed = "s6_probe_after" in self.state
        changed = self.s6_changed(cases)
        probes = self.s6_probes(changed)
        if owed or probes:
            self.consumer_need_record("S6", "s6_reentry")      # X7-6: a close below needs the consumer's record (a no-op with no consumer)
        unrun = self.s6_unrun(changed, self.s6_accepted(self.state.get("s6_probe_after")))
        if not owed and (not probes or unrun):
            return
        self.s6_reprobed_close(probes, cases, no_stand=no_stand, unrun=unrun, strict=True, base="the automated tests ran on their current bytes",
                               reason="every automated test ran on its current bytes; the live checks of the tests that changed were proved again or left as they were")

    def s6_reprove_before_manual(self, auto_scope, no_stand: bool) -> None:
        """HF8-18 (N2): with a manual half to come, the live checks that went stale are proved again HERE - after the
        automation runner is accepted, before the first manual block - because nothing else would (the code close of S6
        belongs to the no-manual path, `s6_reentry`). Once per byte state: the mark `s6_reproved` is `{instance id:
        input_hash}` of the attempts, so a second life of S6 with other bytes is tried again, the same bytes are not
        (D-0018: an `already_probed` answer is the tool's); a mark of the old shape (a string) reads as "none yet". The
        mark's value is the byte state `proof_level.same_test` judges - the test file's `input_hash` AND the per-test
        `instance_content_sha`, which moves with a conftest or a helper the test reaches - so an edited fixture is tried
        again, though the test file is the same.
        Invariants: a probe never runs next to code with no run on its current bytes (`unrun`: a `stale` run always;
        an `unknown` one - no identity recorded - only when `here`: the runner of THIS life of S6 is accepted, the mark
        `s6_manual_runner` that `stage_S6` sets when the runner returns and this method drops on its way out, so a
        later life has none), and never while a role works (`stage_S6`'s `where` sends a running dispatch to
        `wait_existing_job` before this is reached - by reading, no test pins it; `s6_reprove` would take `--dispatch <running>`,
        not refuse it).
        This closes nothing: the manual block closes S6 as before, the proofs are in no close receipt. Every
        failure is a digest line (P1); an exception is printed and the manual block still comes (AR-28)."""
        runner = self.state.get("s6_manual_runner")
        try:
            changed = self.s6_changed(auto_scope)
            probes = self.s6_probes(changed)
            if not probes:
                return
            rows = self.s6_rows()
            marked = self.state.get("s6_reproved")
            marked = marked if isinstance(marked, dict) else {}
            keys = {i: self.s6_bytes_key(rows[i]) for i in probes if i in rows}
            todo = {i: replay for i, replay in probes.items() if not (keys.get(i) and marked.get(i) == keys[i])}
            if not todo:
                return
            unrun = self.s6_unrun(changed, self.s6_accepted(runner))
            lines, _proved, _seconds, _records = self.s6_reprove(todo, auto_scope, no_stand=no_stand, unrun=unrun)
            for line in lines:
                print(f"S6: {line}")
            if not no_stand and not unrun:
                self.state["s6_reproved"] = dict(marked, **{i: keys[i] for i in todo if keys.get(i)})
                self.save_state()
        except Exception as exc:
            print(f"S6: the live checks of the changed tests could not be proved again before the manual half "
                  f"({type(exc).__name__}); the manual half goes on")
        finally:
            if self.state.pop("s6_manual_runner", None) is not None:
                self.save_state()

    def s6_rows(self) -> dict:
        """`{instance id or alias: manifest row}` of the automation manifest (`proof_level._row_ids`, the one spelling reader)."""
        import contract as C
        import proof_level
        manifest = self.s6_manifest()
        rows = {}
        for entry in C.manifest_tests(manifest if isinstance(manifest, dict) else {}):
            for alias in proof_level._row_ids(entry):
                rows.setdefault(alias, entry)
        return rows

    def s6_bytes_key(self, entry) -> str:
        """The byte state of a manifest row's test as `proof_level.same_test` reads it: `<input_hash>:<instance_content_sha>`
        (the second part empty when no run measured one), "" when the test file cannot be read (then nothing is marked)."""
        import proof_level
        now = proof_level.instance_identity(entry, self.task_root)
        raw = str(now.get("input_hash") or "")
        return f"{raw}:{(now.get('instance_identity') or {}).get('instance_content_sha') or ''}" if raw else ""

    # --- the manual half of S6: prepare by code, windows of `MANUAL_WINDOW_CASES` (one case; a block's ceiling is five) (t-250 §1, C2, C4; t-261) -----------------------
    # TP1-15045 (cmp2): `run_manual_block` sent ALL manual cases in one dispatch while the controller refuses a manual
    # block of more than five (`validate_manual_runner_block`), and `manual_evidence.prepare` refused every case because no
    # obligation was executable. Now the DRIVER prepares each case before anything is dispatched: a case `prepare`
    # refuses is NOT dispatched (its reason, in words, stands in `work/evidence/manual/<case>/request.json` for the
    # report), the others go in blocks of at most MANUAL_BLOCK_MAX in plan-row order, ONE dispatch per entry (the loop
    # comes back for the next). What is already done is read from the controller (the accepted manual dispatches'
    # `manual_case_ids`), so a crash between blocks re-dispatches nothing.
    # t-329 (B-270 g): not a second literal - the controller's own `MANUAL_WINDOW_CASES` (SC2-38 item 3: one case per window;
    # the ceiling `MANUAL_BLOCK_CASES` is what `validate_manual_runner_block` refuses above, and `story_progress` counts the
    # windows left by the window size). The name stays: tests set it on an instance.
    MANUAL_BLOCK_MAX = MANUAL_WINDOW_CASES

    def manual_done(self) -> set:
        """The cases an ACCEPTED manual runner dispatch already carried (`manual_case_ids`)."""
        return manual_done_cases(self.controller_state())

    def manual_order(self, cases: list) -> list:
        """The cases in the plan's row order (then as given); as given when the plan or the cases cannot be read."""
        given = list(dict.fromkeys(str(case) for case in cases))
        try:
            import contract
            from coverage_contract import plan_rows
            position = {str(row.get("id")): i for i, row in enumerate(plan_rows(self.task_root)) if isinstance(row, dict)}
            index = contract.case_index(self.task_root)
            return sorted(given, key=lambda case: (position.get(str((index.get(case) or {}).get("plan_row") or ""),
                                                                len(position)), given.index(case)))
        except Exception:
            return given

    def manual_prepare(self, case: str) -> tuple:
        """([obligation ids], "", "") for a case the agent may check by hand, ([], the refusal in words, "") otherwise, and
        (ids, "", <reason>) for a case the FACTORY failed to prepare (F5(c): it is walked unprepared, never dropped).
        The body is `manual_evidence.prepare_for_block`, which `story_step.py start` calls too (FB-9, AR-15)."""
        import manual_evidence as ME
        return ME.prepare_for_block(self.task_root, case)

    def manual_plan(self, cases: list, skip=()) -> dict:
        """{"blocks": [[case, ...], ...], "refused": [(case, words), ...], "unprepared": [(case, reason), ...]} for the cases not
        yet done (and not in `skip`). Prepares each of them (see `manual_prepare`); the blocks are the prepared ones AND the
        unprepared ones (F5(c): the factory never stands - an unprepared case is walked, listed beside its block), plan-row
        order, at most MANUAL_BLOCK_MAX each (the window: 3), the cases of one account set together (`walk_lanes`: guests form one lane;
        a case whose request cannot be read is a lane of one). Four guest cases -> [3, 1]; with a size of 5: 6 -> [5, 1]; none
        prepared -> no block."""
        # t-1957 N5s: a case whose walk record the build refused once stands in an accepted lane and is walked once more (`walk_after`)
        again = {case for case, entry in ((getattr(self, "state", None) or {}).get("walk_retry") or {}).items()
                 if isinstance(entry, dict) and entry.get("open")}
        gone = (self.manual_done() - again) | {str(c) for c in skip}
        ready, refused, unprepared = [], [], []
        for case in [c for c in self.manual_order(cases) if c not in gone]:
            got = self.manual_prepare(case)
            why, walk = got[1], got[2]
            if why:
                refused.append((case, why))
            else:
                ready.append(case)
                if walk:
                    unprepared.append((case, walk))
        # t-1957 N5s (E5s.8, E5s.9): the lanes - one account set to a lane, plan-row order, at most MANUAL_BLOCK_MAX - by the one function
        # the door and the progress line use; a request that cannot be read leaves its case a lane of one
        return {"blocks": walk_lanes(ready, lane_keys(getattr(self, "task_root", None), ready), self.MANUAL_BLOCK_MAX),
                "refused": refused, "unprepared": unprepared}

    GATE_A_DRY_BLOCK = "gate A recorded dry"       # a name `references/block-names.json` holds (reader: `manual_gate_note`)

    def manual_gate_note(self) -> None:
        """One line when the plan has manual rows and NOT ONE of their obligations is executable: gate A was recorded
        dry (a dry run skips `apply_gate_answers`, the step that makes them so), or the plan was approved before that
        step existed. Said once per entry (FR-41, FR-57), and then - C1-6b, P22 - the person is ASKED (`gate_a_dry_person`:
        `reapprove` / `go on` / `stop`), unless their word already passes the block `gate A recorded dry` (`waiver.py --stage S6`):
        a passed question is not asked again, the line stays."""
        try:
            from coverage_contract import plan_rows
            rows = [r for r in plan_rows(self.task_root) if isinstance(r, dict) and r.get("disposition") == "manual-agent"]
            executable = [o for r in rows for o in r.get("coverage_obligations") or []
                          if isinstance(o, dict) and o.get("decision") == "manual-agent"]
        except Exception:
            return
        if rows and not executable:
            print(f"S6: gate A was recorded dry; the plan has {len(rows)} row(s) checked by an agent by hand and none of "
                  "their obligations says so, so no case can be checked by hand (a dry run skips the step that makes "
                  "them executable, and a plan approved before it keeps them as planned); until gate A is approved again "
                  "or your word passes it, the cases stand as not checked by hand")
            if not waiver.split_overridden([self.GATE_A_DRY_BLOCK], self.pipeline(), "S6")[1]:
                # remains: the dry-gate question is a seam question (priced, `offered`): reapprove has the site's executor, go on / stop the seam's, other words go to the seam
                raise self.gate_a_dry_person(rows)

    def gate_a_dry_person(self, rows: list) -> "Person":
        """The `s6.gate_a_dry` question (C1-6b, S7 of the inventory): the manual rows' cases cannot be checked, gate A having been
        recorded without the step that makes them checkable. `reapprove` is OFFERED only when its executor can run: this run does not
        itself record gates dry (`self.dry` - a `--dry-run` would skip the same step again), no dispatch runs (the `running` fact of
        the seam), the controller holds an approved gate A on the current source revision (what `semantic_reopen` requires) and the
        cases are named in the approved scope; a fact that cannot be read closes it (FR-59), and the lead says so in ONE line (FR-42).
        The cases the question names are kept in `state["gate_a_dry"]`: one answer covers exactly that set."""
        wanted = {str(row.get("id")) for row in rows}
        why, cases = "", []
        try:
            import contract
            state = self.controller_state()
            scope = {str(item) for item in state.get("scope") or []}
            named = sorted(case for case, meta in contract.case_index(self.task_root).items()
                           if str((meta or {}).get("plan_row")) in wanted)
            cases = [case for case in named if case in scope]
            approved = any(d.get("gate") == "A" and d.get("status") == "approved" and d.get("source_revision") == state.get("source_revision")
                           for d in (state.get("decisions") or {}).values())
            running = self.no_move_facts({}).get("running")
        except Exception:
            named, approved, running = [], False, None
            why = "the factory could not read the story's state"
        if not why:
            why = ("this run records gates dry, so asking gate A again would skip the same step" if self.dry
                   else "a role is still working, and gate A can be asked again when it has stopped" if running is True
                   else "the factory could not establish that no role is working" if running is None
                   else "there is no approved gate A to ask again" if not approved
                   else "the factory could not name these cases in the approved plan" if not cases else "")
        shown = cases or named
        lead = (f"{len(shown) or len(rows)} case(s) an agent checks by hand cannot be checked: gate A was recorded without the step that "
                "makes them checkable.\n" + "\n".join(self.case_lines(shown))
                + (f"\nApproving gate A again is not offered now: {why}." if why else "")
                + "\n\nWhat I need from you is one of these:")
        options = ([] if why else [{"answer": "reapprove", "token": "reapprove",
                                    "slots": {"stages": "the case review of S4, gate A and the manual half of S6"},
                                    "says": "approve gate A again so that these cases can be checked by hand; the test design is reviewed "
                                            "again, gate A is asked again, and then they are checked"}])
        options += [{"answer": "go on", "token": "go on",
                     "says": "go on without checking them by hand; the report carries them as not checked, in your words"}, self.STOP_OPTION]
        self.state["gate_a_dry"] = {"cases": cases}
        person = self.site_seam_person("gate_a_dry", self.closed_question("s6.gate_a_dry", lead, options), "S6", block=self.GATE_A_DRY_BLOCK,
                                       details="The plan rows checked by an agent by hand: " + ", ".join(sorted(wanted)))
        person.holds = tuple(cases)            # RN1-24: the cases the question names wait; none named (`cases` empty) = it holds everything
        return person

    def manual_request_paths(self, cases: list) -> list:
        import manual_evidence as ME
        return [ME.request_path(self.task_root, case).relative_to(self.task_root).as_posix() for case in cases]

    def manual_close(self, cases: list, refused: list) -> None:
        """No block is left to dispatch (every case is done, or none could be prepared): the manual half closes with
        no runner - the receipt is `code_only`, written over a `run-report.json` the reducer has just written (the same
        order as the freshness branch of `stage_S6`), then `stage_done`. The words say how many were checked and which
        were not. A reducer that fails is a refusal: nothing is closed over a report nobody could build."""
        self.consumer_need_record("S6", "manual_close")             # X7-6: the manual half closes by the consumer's record (a no-op with no consumer)
        gone = self.manual_done()
        done = [case for case in cases if case in gone]
        # RN1-24: the cases a deferred question holds are closed over as NOT checked, in the safe default `left_unchecked` (no new value of
        # `by`), with the question's number in the reason; the answer, asked before gate B, decides what happens to them next (`retry`
        # sends them back to S6, `prepare` then writes their request again)
        for case, n in self.deferred_waiting(cases):
            held_reason = f"not checked yet: it waits for your answer to question {n}, asked before gate B"
            self.refuse_case(None, case, held_reason, "answer the question about this check that comes before gate B", "left_unchecked")
            refused = list(refused) + [(case, held_reason)]
        reason = (f"the manual half of S6: {len(done)} case(s) checked by an agent by hand, {len(refused)} not checked"
                  + (": " + ", ".join(case for case, _why in refused) if refused else ""))
        code, out = self.py("finalize_task.py", str(self.task_root))
        if code:
            raise Refusal(f"S6 manual half: finalize_task.py exit {code}: " + (out.splitlines()[-1] if out else ""))
        self.close_by_code("S6", reason, ["work/run-report.json"] + self.manual_request_paths([case for case, _ in refused]),
                           finalize=False, site="s6.manual_close")

    # --- the stand's sign-in account, asked BEFORE a block with a screen case is dispatched (t-292) -----------------------
    # TP1-15045 (cmp2r rehearsal, 02.10): a manual block of screen cases was dispatched with no usable test account,
    # and every capture photographed the sign-in page. The material is read by the capture's own reader
    # (`manual_capture.read_login`), so the gate and the capture see the same file; the question comes before any
    # block is registered or launched, and the person's word passes it like every other block (FR-4).
    STAND_LOGIN_BLOCK = waiver.STAND_LOGIN_MISSING_BLOCK       # the one definition (t-722 N5)

    def manual_policy(self, case: str) -> str:
        """The evidence policy of a case `manual_prepare` has just prepared (`ui`, `api`, ...), read from its request;
        "" when the request is unreadable, holds `refused`, or names no policy (an unknown). A seam: the rig stubs it
        the way it stubs `manual_prepare`."""
        import manual_evidence as ME
        request = _read_json(ME.request_path(self.task_root, case))
        if not isinstance(request, dict) or isinstance(request.get("refused"), dict):
            return ""
        return str(request.get("evidence_policy") or "")

    STAND_LOGIN_KEYS = ("Where the factory looks for the account: environment.env_files (the files) or environment.env_file (the file), environment.user_key "
                        "(the key of the account's name, default AUTH_USERNAME) and environment.secret_keys[0] (the key "
                        "of its password, default AUTH_PASSWORD) in the project's qa-factory/config.json. A project whose "
                        "screens need no sign-in at all sets manual_capture.login.ui to null there.")

    def _cases_all_on_driver(self, cfg, cases) -> bool:
        """True only when every case of `cases` is planned `manual-agent` on a profile whose surface row has `hands: driver`
        (`gate_preflight.stand_profiles`, `surfaces.row_for_profile`). ERROR DIRECTION: a doubt is False (no cases, a case no
        profile claims, a profile with no such row, a broken table, any exception) - the old question is asked, a question too
        many and never one too few."""
        if not cases:
            return False
        try:
            import gate_preflight as GP
            import surfaces
            of_case = {c: pid for pid, entry in GP.stand_profiles(cfg, self.task_root, ("manual-agent",)).items()
                       for c in entry.get("cases") or []}
            hands: dict = {}
            for case in cases:
                pid = of_case.get(case)
                if not pid:
                    return False
                if pid not in hands:
                    row = surfaces.row_for_profile(cfg, pid)
                    hands[pid] = surfaces.is_device_row(row)
                if not hands[pid]:
                    return False
            return True
        except Exception:
            return False

    def stand_login_problem(self, cases=None) -> tuple:
        """("", "") when the stand's test account can be read - or the project says it needs none (`manual_capture.
        login.ui: null`); else (kind, details): `no_file` (the settings name no file), `missing_file` (the file they
        name is not there - or the settings file itself cannot be loaded: its own text is the details), `unreadable`
        (the file is there but cannot be read: a folder in its place, no permission), `missing_key` (it lacks the
        account's name or password). The capture's own
        loader and reader (`manual_capture.load_config`, `read_login`), so the gate and the capture read the same file
        and resolve `env_file` against the same root. ERROR DIRECTION: toward "missing" - a question too many, never
        "present" when the capture would fail on the file. Wrong but present values pass: the landing proof of the
        capture catches them."""
        import manual_capture as MC
        try:
            cfg, root = MC.load_config(self.task_root)
        except ValueError as exc:
            # t-308 F6: a settings file that is absent or broken was shown as "the settings name no file" - false
            return "missing_file", f"{exc}\n\n{self.STAND_LOGIN_KEYS}"
        if MC.login_declared_none(cfg, "ui"):
            return "", ""
        # EP1-41f (N-18): a block whose cases are ALL on a device stand signs in with no default web account, so only that block
        # is skipped; the accounts the cases name are still asked for below. POSITION: after `login_declared_none`, before the
        # default account is read.
        # PK0-5 (AR-19): the default account is read only when the ONE rule of gate A says the story needs it
        # (`gate_preflight.default_login_needed`; a doubt is "needed"). POSITION: after `login_declared_none` and the device clause, before
        # `read_login` - a story that needs no default login is never refused over keys nothing will use.
        import gate_preflight as GP
        import stand_gaps
        on_driver = self._cases_all_on_driver(cfg, cases)
        asked_default = []

        def read_default() -> tuple:
            """("", "") or the refusal; read at most once (also for a case whose request cannot be read: its capture signs in as default)."""
            if asked_default:
                return "", ""
            asked_default.append(True)
            try:
                login = MC.read_login(cfg, root)
            except MC.LoginMaterialMissing as exc:
                kind = {"file": "missing_file", "unreadable": "unreadable"}.get(exc.part, "missing_key")
                return kind, f"{exc}\n\n{self.STAND_LOGIN_KEYS}"
            except ValueError as exc:
                return "missing_key", f"{exc}\n\n{self.STAND_LOGIN_KEYS}"
            if login is None:
                return "no_file", ("the project's settings name no file for the stand's login (environment.env_file)"
                                   f"\n\n{self.STAND_LOGIN_KEYS}")
            return "", ""
        if not on_driver and GP.default_login_needed(self.task_root, cfg):
            problem = read_default()
            if problem[0]:
                return problem
        # HF5-3: the accounts the screen cases of the block name in their requests (`manual_evidence.request_actors`, the one
        # reader of the field). POSITION: after the default account, and `cases` are the screen cases only - the caller
        # returns before this when there is none, so an http-only block asks nothing (its capture refuses by key name).
        # A `stand_account` role is read as `read_login(..., actor=role)` reads it; an account named by one `env` key must
        # have that key set in the env file (the pair is the capture's `--as env:U/S`; here the one key is read twice).
        # A request that is absent or unreadable adds nothing of its own: its capture signs in as the default account, which the loop
        # reads (once) for it when the rule above did not. The details name the case and the account, never a value.
        import config_contract
        import manual_evidence as ME
        chosen = stand_gaps.stand_name(self.task_root)       # loop-invariant: the chosen stand, the entry of that name (or None)
        chosen_stand = next((e for e in cfg.get("environments") or [] if isinstance(e, dict) and str(e.get("name") or "") == chosen), None)
        for case in cases or []:
            actors, why = ME.request_actors(self.task_root, case)
            if why or not ME.request_path(self.task_root, case).is_file():
                print(f"S6: {case}: {why or 'its prepared request is not there'}; the stand's default account is checked "
                      "for it", file=sys.stderr)
                if not on_driver:
                    problem = read_default()
                    if problem[0]:
                        return problem
            for actor in actors:
                check = actor.get("check") if isinstance(actor.get("check"), dict) else {}
                kind, value = next(iter(check.items()), ("", ""))
                if kind not in ("stand_account", "env"):
                    continue
                # GW1-27: the role is what the gate reads (`gate_preflight.account_role`): the value is trimmed, and a spelling
                # differing in case, `_`, `-` or spaces is read as `resolve_actor` reads it. PK0-5 (S11 c): the stand is the CHOSEN one
                # (`stand_gaps.stand_name`, the entry of that name, found above the loop) - an account answered for `dev` is never read
                # on `stage`, and no other stand is searched; a role with no chosen stand is refused with the reason, never read on a
                # guessed one. The reserved forms (`default`, `env:...`, `created:...`) need no stand: they are not refused for its absence.
                value = str(value).strip() if kind == "stand_account" else value
                as_actor = str(value) if kind == "stand_account" else f"env:{value}/{value}"
                stand = chosen_stand
                if kind == "stand_account" and not config_contract.reserved_role(value) and stand is None:
                    return "missing_key", (f"{case}: the story has no chosen stand, so the account {actor.get('id')} ({value}) cannot "
                                           f"be read on it\n\n{self.STAND_LOGIN_KEYS}")
                if value == "default":
                    stand = None
                try:
                    MC.read_login(cfg, root, actor=as_actor, stand=stand, task_root=self.task_root)
                except ValueError as exc:      # LoginMaterialMissing is one, and so is every refusal of `resolve_actor`
                    return "missing_key", (f"{case}: the account {actor.get('id')} ({kind} {value}) cannot be read: {exc}"
                                           f"\n\n{self.STAND_LOGIN_KEYS}")
        return "", ""

    STAND_LOGIN_REASONS = {"no_file": "the project's settings name no file for it",
                           "missing_file": "the file the settings name for it is not there",
                           "unreadable": "the file the settings name for it could not be read",
                           "missing_key": "the file the settings name does not hold the account's name or its password"}

    def case_lines(self, cases: list) -> list:
        """One line per case for a question: its title and id; a case with no title by a link to its case file on the same line (the
        stand-login question and the dry-gate question name their cases the same way)."""
        import contract
        try:
            index = contract.case_index(self.task_root)
        except Exception:
            index = {}
        lines = []
        for case in cases:
            entry = index.get(case) if isinstance(index, dict) else None
            path = Path(str((entry or {}).get("path") or "")) if entry and (entry or {}).get("path") else None
            try:
                title = " ".join(contract.case_title(path).split()) if path else ""
            except Exception:
                title = ""
            if title:
                lines.append(f"- {title} ({case})")
            elif path:
                try:
                    shown = path.resolve().relative_to(self.task_root.resolve()).as_posix()
                except ValueError:
                    shown = path.name
                lines.append(f"- [{case}]({shown})")
            else:
                lines.append(f"- {case}")
        return lines

    def stand_login_question_text(self, cases: list, kind: str) -> str:
        """The question (references/human-questions.md): what was done, why it cannot go on, one question, three closed
        answers with their prices. Each case by its title and id (`case_lines`)."""
        lines = self.case_lines(cases)
        reason = self.STAND_LOGIN_REASONS.get(kind, self.STAND_LOGIN_REASONS["no_file"])
        # RN1-24: when the question is going to be set aside (`holds_can_wait`: the same test `deferrable` makes for this question) the
        # other checks do NOT wait for it, and the text says which road it is on; otherwise the live text is unchanged
        others = (f"the other checks go on; these cases wait for your answer: {', '.join(str(case) for case in cases)}"
                  if self.holds_can_wait(cases) else "the other checks by hand wait for this answer too")
        lead = (f"The requirements, the test plan and the test cases for {self.task} are done, and the checks an agent "
                f"makes by hand are next. {len(cases)} of them look at the product's screens:\n" + "\n".join(lines)
                + f"\nTo open those screens the agent signs in to the stand with the project's test account, and I "
                f"cannot find that account: {reason}. I have not started any of these checks: without the account they "
                f"would only photograph the sign-in page, and {others}.\n\n"
                "What I need from you is one of these:")
        # C1-6b: the options carry their three price lines (the data row of `s6.stand_login`); the tokens are unchanged
        return self.closed_question("s6.stand_login", lead, [
            {"answer": "retry", "token": "retry", "slots": {"what": "put the account where the settings point"},
             "says": "put the test account where the project's settings point (or point the settings at the file that holds it; if "
                     "these screens need no sign-in at all, say so in the settings); I look again"},
            {"answer": "by hand", "token": "by hand", "slots": {"what": "the screen checks named above"},
             "says": "you will check these screens yourself; I leave them out and the report says so, in your words"},
            {"answer": "go on", "token": "go on",
             "says": "leave them unchecked; the report carries them as not checked, in your words"}])

    def stand_login_gate(self, plan: dict) -> None:
        """Before ANY block of `plan` is dispatched: when a ready case opens the product's screens (policy `ui`; an
        unknown policy counts as ui, with one printed line - ERROR DIRECTION toward asking: one answer for the person,
        against a role session spent photographing the sign-in page) and the stand's test account cannot be read, the
        person is asked (a `Person`, kind `stand_login`) - unless their word already passes the block `stand login
        missing` (`waiver.py --stage S6`, read ONLY while the material is missing: once it is there, the cases are
        dispatched even though a pass exists). A pass skips the screen cases, in the person's words: they join
        `plan["refused"]` (and their request.json says so), the other blocks are re-chunked - no second `prepare`.

        POSITION (the invariant): after `manual_plan` (the policy is known from the request it wrote) and before the
        controller registers or the runner launches anything: no block holding a screen case exists while the account
        is missing and no word passes it. Nothing is asked when no screen case remains (http-only stories, cases
        done or refused), and `run_manual_block`'s C4 rule holds: a skipped case is in `refused`, so the last block
        goes not-complete and the next entry closes the manual half code-only, naming it."""
        ready = [case for block in plan["blocks"] for case in block]
        screens = []
        for case in ready:
            policy = self.manual_policy(case)
            if not policy:
                print(f"S6: {case}: its prepared request ({self.manual_request_paths([case])[0]}) could not be read "
                      "or names no policy, so the case counts as one that opens the product's screens")
            if policy in ("ui", ""):
                screens.append(case)
        if not screens:
            return
        kind, details = self.stand_login_problem(screens)
        if not kind:
            return
        _blocking, passed = waiver.split_overridden([self.STAND_LOGIN_BLOCK], self.pipeline(), "S6")
        if not passed:
            # A7 (C1-6b): a seam question - `retry` / `go on` are carried out by the seam's own executors, `by hand` by the same pass
            # plus the site's typed record (`_take_stand_login_answer`)
            # remains: the stand-login question is a seam question (priced, `offered`): every token has an executor, other words go to the seam
            person = self.site_seam_person("stand_login", self.stand_login_question_text(screens, kind), "S6",
                                           block=self.STAND_LOGIN_BLOCK, details=details)
            person.login_cases = list(screens)       # read by `ask()`, which sets the flag - and clears it for every other Person
            # RN1-24: the screen cases wait for the answer; the other ready cases do not (`Driver.run` may set the question aside)
            person.holds = tuple(screens)
            raise person
        said = " ".join(str(passed[0].get("decision") or "").split())
        reason = ("not checked by an agent: the stand's sign-in account is not set up for the factory; the person said: "
                  f"\"{said}\"")
        door = "put the stand's test account in the project's settings; the next run checks it by hand"
        # A6: the TYPED carrier of the choice, never a token read out of the words: `by hand` -> `person_checks` (the delivery check
        # restates the case as handed to the person), anything else - `go on`, a pass the conductor recorded from free words, a pass
        # with no record of ours - -> `left_unchecked` (the safe default: no claim that the person checks it)
        choice = self.state.get("login_choice") or {}
        by = ("person_checks" if choice.get("token") == "by hand" and choice.get("words") == said.replace(self.BOM, "").strip()
              else "left_unchecked")      # the record is bound to THE pass it was made for: its words are the pass's words
        for case in screens:
            self.refuse_case(plan, case, reason, door, by)
            print(f"S6: {case}: not checked by hand — {reason}")
        left = [case for case in ready if case not in set(screens)]
        plan["blocks"] = manual_blocks(left, self.MANUAL_BLOCK_MAX)

    def manual_lane_plan(self, cases: list) -> tuple:
        """`(plan, waiting)` for the manual cases of S6 at this entry (t-2147 C1: the plan half of the old `run_manual_block`, unchanged): the
        cases a deferred question holds, the dry-gate note, `manual_plan`, the stand-login gate, the lanes cut again, the cases whose walk
        record was refused twice named beside the refused ones, and the lanes whose account has no pair refused. Its lines and its order are
        the old road's; `plan["blocks"]` are the lanes."""
        # RN1-24: the cases a deferred question holds are not prepared, not asked about again and not dispatched; the dry-gate note
        # is not raised a second time while ITS question waits (E11: one open question per case; `deferrable` read the same record).
        waiting = self.deferred_waiting(cases)
        if not any(item.get("kind") == "gate_a_dry" for item in self.deferred_items()):
            self.manual_gate_note()
        plan = self.manual_plan(cases, skip=[case for case, _n in waiting])
        for case, why in plan["refused"]:
            print(f"S6: {case}: not checked by hand — {why}")
        for case, why in plan.get("unprepared") or []:
            print(f"S6: {case}: unprepared - {why}; the manual agent walks it without a prepared request and records no result")
        self.stand_login_gate(plan)      # t-292: the account for the screen cases, BEFORE any block is registered
        # t-1957 N5s: the gate re-chunks what a pass leaves by the plain split; cut the cases that are left into lanes again (the same
        # function), and name the cases whose walk record was refused twice (closed `left_unchecked`) beside the refused ones
        plan["blocks"] = walk_lanes([case for lane in plan["blocks"] for case in lane],
                                    lane_keys(self.task_root, [case for lane in plan["blocks"] for case in lane]), self.MANUAL_BLOCK_MAX)
        for case, entry in (self.state.get("walk_retry") or {}).items():
            if case in cases and isinstance(entry, dict) and entry.get("refused", 0) > 1 and case not in [c for c, _w in plan["refused"]]:
                plan["refused"].append((case, str(entry.get("reason") or "the record of its walk was refused twice")))
        self.walk_refuse_gaps(plan)     # TR1-4: a lane whose account has no pair is not walked, and does not stop the next lane
        # TR3-10d item 1 (D.5): the account and record assignment is for the PARALLEL road only - more than one lane and `manual.walkers`
        # not 1. INVARIANT: on the old road no pool is read and no state key is written; a key left by an earlier entry is cleared (its
        # reservations settled) so that a lane never runs under an assignment that is not this entry's. POSITION: after `walk_refuse_gaps`
        # (a lane that cannot walk costs no handle) and before any dispatch of this entry is registered.
        if self.s6_walkers_cap() != 1 and len(plan["blocks"]) >= 2:
            self.walk_assign_step(plan)
        else:
            self.walk_assign_clear()
        return plan, waiting

    def walk_assign_clear(self) -> None:
        """TR3-10d L4 (AR-25): the assignment of an EARLIER entry goes before a new one is made, or when this entry makes none. A reserved walk
        id that no controller dispatch took was never walked: its records are settled `free` (`walk_settle_unopened`; no walker touched the
        account or the record); the five `walk_*` assignment keys of the state are dropped. A walk that a dispatch took is left to `walk_before`
        / the verdict (`settle_unopened` never moves a walk that has a record). ERROR DIRECTION: when the controller's dispatches cannot be read
        nothing is settled and nothing is dropped (an unknown is never a free). Reads nothing when the state holds no key (the old road)."""
        if not ("walk_assign" in self.state or "walk_assign_cases" in self.state or "walk_entities" in self.state
                or "walk_ids" in self.state or "walk_alone" in self.state):
            return
        try:
            dispatches = (self.controller_state() or {}).get("dispatches")
            if not isinstance(dispatches, dict):
                print("note: S6: the controller record holds no dispatches; the held records of the lanes stay as they are", flush=True)
                return
            taken = {str(k) for k in dispatches} | {str(v.get("id")) for v in dispatches.values() if isinstance(v, dict)}
            running = ({str(k) for k, v in dispatches.items() if isinstance(v, dict) and v.get("status") == "running"}
                       | {str(v.get("id")) for v in dispatches.values() if isinstance(v, dict) and v.get("status") == "running"})
        except Exception as exc:       # noqa: BLE001 - P1/FR-59: unreadable stays as it is (held, never free), with one note
            print(f"note: S6: the controller record could not be read ({type(exc).__name__}); the held records of the lanes stay as they are",
                  flush=True)
            return
        for did in [str(i) for i in (self.state.get("walk_ids") or {}).values() if i]:
            if did not in taken:
                self.walk_settle_unopened(did, "free")
            elif did not in running:
                # TR3-10d N3 (AR-25): a dispatch registered but no longer running whose walk has no record is the crash between the
                # registration and `walk_before`; the lane may have run on the recorder, so `dirty` (never free). A walk with a record is
                # not moved (`settle_unopened`), a running dispatch is left alone.
                self.walk_settle_unopened(did, "dirty")
        self.state.pop("walk_assign", None)
        self.state.pop("walk_assign_cases", None)
        self.state.pop("walk_entities", None)
        self.state.pop("walk_ids", None)
        self.state.pop("walk_alone", None)
        self.save_state()

    def walk_assign_step(self, plan: dict) -> dict:
        """TR3-10d item 1 (AR-13, AR-15, AR-28; the parallel road only): which account each lane signs in as and which record of an exclusive kind
        it uses, decided ONCE per entry before any dispatch. Reads `walk_supply` (the one reader; its notes said once), the doubts, a pool per key
        part (`walk_pool.pool_of`), `assign_lanes`, and `assign_entities` (the `in_use` records are written there, under the ids reserved here).
        State (all keyed by the lane number as text, re-made at every entry): `walk_assign` {n: {part: handle}} - ONLY a lane whose EVERY part has
        a handle (L3: any other lane keeps today's key-based holds and actor); `walk_assign_cases` {first case: n} for every lane; `walk_entities`
        {n: {item: [entry]}}; `walk_ids` {n: reserved walk id} (L1: `run_manual_lane` takes it, so the id the claims store holds is the id the
        walk opens under); `walk_alone` [first case, ...] - the lanes that run alone in the serial first round (item 7; ERROR DIRECTION toward
        alone: a lane whose request carries `walk_global`; with no data words, a lane that needs an exclusive kind with no free instance or with no
        pool at all; a claims store that cannot be used). Never raises (P1): a failure is one note and the lanes keep today's holds. Returns
        the facts the way question will need: `{"short": [(part, lanes waiting, pool size)], "alone_kinds": [kind text], "supply": the supply,
        "may_change": whether the stand may be changed}`. TR3-10 D3b: at its end it RAISES the one question owed (`walk_supply_raise`), the only
        `Person` that leaves it; walkers 1 or one lane never reach it (D.5)."""
        import config_contract as CC
        import manual_capture as MC
        import manual_evidence as ME
        import walk_pool as WP
        T = self.task_root
        facts: dict = {"short": [], "alone_kinds": [], "supply": {}}
        try:
            self.walk_assign_clear()
            supply, notes = CC.walk_supply(self.config)
            facts["supply"] = supply
            for note in notes:
                self.say_once("walk_supply", note)
            lanes = [[str(c) for c in lane] for lane in plan.get("blocks") or ()]
            flat = [case for lane in lanes for case in lane]
            keys = lane_keys(T, flat) if flat else {}
            doubts = MC.account_doubts(T)
            try:
                cfg, _root = MC.load_config(T)
            except ValueError:
                cfg = {}                # no stand records at all: no pool, today's refusals
            stand = WP._stand_of(cfg)
            pools: dict = {}
            for lane in lanes:
                key = keys.get(lane[0]) if lane else None
                for part in (key.split("+") if isinstance(key, str) else []):
                    if part and part not in pools:
                        pools[part], more = WP.pool_of(T, cfg, lane[0], part, supply, doubts)
                        notes.extend(more)
            may_change = MC._stand_may_change(stand, MC.spec()["safe_to_break_no"])
            facts["may_change"] = may_change
            obtain, more = WP.obtain_roles_of(supply, MC._roles_of(stand))
            notes.extend(more)
            failed = self.state.get("obtain_failed") or {}
            obtain = [role for role in obtain if not failed.get(role)]
            if obtain and not may_change:
                self.say_once("walk_obtain_stand", "note: S6: you said a walker may make its own user, but your settings do not mark this "
                                                   "stand as one that may be changed; walkers use the accounts that exist")
            assignment, more = WP.assign_lanes(lanes, pools, obtain, may_change, keys)
            notes.extend(more)
            requests: dict = {}
            for case in flat:
                try:
                    requests[case] = _read_json(ME.request_path(T, case))
                except ValueError:
                    requests[case] = {}
            # L1: one walk id per lane that needs a record, taken from the numbers no dispatch has; `run_manual_lane` takes it back
            dispatches = (self.controller_state() or {}).get("dispatches")
            if not isinstance(dispatches, dict):
                # an early exit, not a raise caught below: the same note, the lanes keep today's holds; no question is owed on this path
                # (`short` and `alone_kinds` are still empty, so `walk_supply_raise` would return None)
                print("note: S6: the accounts and records of the lanes were not assigned (ValueError: the controller record holds no "
                      "dispatches); the lanes run as before", flush=True)
                return facts
            needs = WP._needs(lanes, requests)
            start = len([d for d in dispatches.values() if isinstance(d, dict) and d.get("stage") == "S6" and d.get("role") == "qa-runner"]) + 1
            reserved: dict = {}
            for n in needs:
                reserved[n] = self.walk_next_id(dispatches, start, reserved.values())
            data = supply["data"]
            entities, more = WP.assign_entities(lanes, requests, data["pools"], T, reserved, data["may"])
            notes.extend(more)
            # the records are written now: their ids and the lanes' numbers go into the state at once, so a failure below can never leave a
            # held record that no entry will settle (the next entry's `walk_assign_clear` reads `walk_ids`)
            self.state["walk_assign_cases"] = {lane[0]: n for n, lane in enumerate(lanes, 1) if lane}
            self.state["walk_ids"] = {str(n): reserved[n] for n, found in entities.items() if found.get("state") == "given" and n in reserved}
            self.save_state()
            for note in dict.fromkeys(notes):
                self.say_once("walk_pool", note if note.startswith("note:") else f"note: S6: {note}")
            by_handle: dict = {}
            for n, parts in assignment.items():
                for handle in dict.fromkeys(parts.values()):
                    by_handle.setdefault(handle, []).append(n)
            for handle, numbers in by_handle.items():
                if len(numbers) > 1:
                    pool = next((p for p in pools.values() if handle in p), [handle])
                    role = getattr(pool, "role", "") or handle
                    self.say_once("walk_shared:" + handle, f"S6: {len(numbers)} lanes wait for each other: the project's list holds {len(pool)} "
                                                           f"account(s) for {role}")
            short, more = WP.short_parts(assignment, pools, supply, self.s6_walkers_cap())
            facts["short"] = short
            for note in more:
                self.say_once("walk_pool", f"note: S6: {note}")
            assigned: dict = {}
            for n, parts in assignment.items():
                key = keys.get(lanes[n - 1][0])
                wanted = [p for p in key.split("+") if p] or [""]
                if all(p in parts for p in wanted):
                    assigned[str(n)] = {p: parts[p] for p in wanted}
            known = bool(data["known"])
            store_failed = any(note.startswith("records were not assigned") for note in notes)
            alone, kinds = [], []
            for n, lane in enumerate(lanes, 1):
                if not lane:
                    continue
                state = (entities.get(n) or {}).get("state")
                wanted = [(k, t) for item in (needs.get(n) or {}).values() for k, t in item]
                nopool = [t for k, t in wanted if k not in data["pools"]]
                gone = [t for k, t in wanted if k in data["pools"]] if state in ("wait", "alone") else []
                every = any(isinstance(requests.get(c), dict) and isinstance(requests[c].get("walk_global"), str)
                            and requests[c]["walk_global"].strip() for c in lane)
                if every or (n in needs and store_failed) or (not known and (nopool or gone)):
                    alone.append(lane[0])
                    if not every and not known:
                        kinds.extend(k for k in nopool + gone if k not in kinds)
            facts["alone_kinds"] = kinds
            self.state["walk_assign"] = assigned
            self.state["walk_entities"] = {str(n): found["entries"] for n, found in entities.items() if found.get("state") == "given"}
            self.state["walk_alone"] = alone
            self.save_state()
        except Exception as exc:        # noqa: BLE001 - P1: the assignment informs, it never stops S6; the lanes keep today's holds
            print(f"note: S6: the accounts and records of the lanes were not assigned ({type(exc).__name__}: {' '.join(str(exc).split())[:200]}); "
                  "the lanes run as before", flush=True)
        # TR3-10 D3b (spec items 9 and 12; D.2, D.3, D.11): the way question or the data-change question, ONE per entry. POSITION: here, at the
        # end of the assignment step, before any dispatch of this entry is registered - the question is set aside (`no_hold`, it holds no
        # case) and the next entry runs the lanes in turn. INVARIANT: a `Person` leaves this step only here; any other failure of the raise
        # block is one note and the lanes go on (P1: a question never stops S6).
        try:
            # remains: the way question is the person's intent, set aside (`no_hold`) and raised once per entry by design (D.2, D.3); not a state with no move
            person = self.walk_supply_raise(facts)
        except Person:
            raise
        except Exception as exc:        # noqa: BLE001 - P1/D.11: the raise informs, it never stops S6
            print(f"note: S6: the question about test accounts and records was not raised ({type(exc).__name__}: "
                  f"{' '.join(str(exc).split())[:200]}); the lanes go on in turn", flush=True)
            person = None
        if person is not None:
            raise person
        return facts

    def walk_asked(self, kind: str) -> bool:
        """Is the S6 question `kind` already owed or asked in this story (D.3)? A deferred item of that kind, or its `<kind>_asked` row id in
        the state (set by the question's builder, kept for the story)."""
        row = self.state.get("walk_supply_asked") if kind == "walk_supply" else self.state.get("data_change_asked")
        return any(item.get("kind") == kind for item in self.deferred_items()) or bool(row)

    def walk_supply_raise(self, facts: dict):
        """The ONE question this entry owes, or None (items 9 and 12). Reads only `walk_assign_step`'s facts: `walk_supply` first - the short
        parts of a pool while `supply.accounts.known` is False, or a lane made alone by a data shortage while `supply.data.known` is False; else
        `data_change` - a lane made alone for lack of a free record while `supply.data.may_known` is False. Each is skipped when its question
        is already deferred or asked in this story (`walk_asked`); an answered half is `known` in the supply and never reaches here. The other
        question waits for the next entry (D.3: two questions never ask the same thing)."""
        supply, short, kinds = facts.get("supply") or {}, facts.get("short") or [], [str(k) for k in facts.get("alone_kinds") or [] if str(k).strip()]
        accounts, data = supply.get("accounts") or {}, supply.get("data") or {}
        if ((short and not accounts.get("known")) or (kinds and not data.get("known"))) and not self.walk_asked("walk_supply"):
            # remains: the way question is the person's intent with its three closed answers (L5), not a state with no move; `_answer_walk_supply` executes them
            return self.walk_ask_once("walk_supply", ["/manual/accounts_way", "/manual/data_way"],
                                      "how this project gets more test accounts and which records walkers may share",
                                      str(self.walk_supply_text(short)), lambda row: self.walk_supply_person(row, short))
        if kinds and not data.get("may_known") and not self.walk_asked("data_change"):
            may_change = bool(facts.get("may_change", True))
            # remains: the data-change question is the person's permission with its closed answers, not a state with no move; `_answer_data_change` executes them
            return self.walk_ask_once("data_change", ["/manual/data_way/may"],
                                      "whether the factory may make and remove records on the stand for the walkers' data pools",
                                      str(self.data_change_text(kinds, may_change)), lambda row: self.data_change_person(row, kinds, may_change))
        return None

    def walk_ask_once(self, kind: str, field_refs: list, essence: str, asked: str, build) -> "Person | None":
        """The ONE body of "open the registry row, then build the question" for the S6 supply questions (AR-15). `project_decisions.py add`
        (scope project, owner `user`; an open row of the same refs is returned and reused, FR-7); the row's id goes to `build(row_id)`, which
        keeps it in the state (`<kind>_asked`) - the state is saved BEFORE the person is returned to be raised. An `add` that exits non-zero or
        prints no row is one note, said once, and None: no question, the lanes go on in turn, the next story tries again (D.11, FR-59)."""
        args = ["--root", str(self.project), "add", *[a for ref in field_refs for a in ("--field-ref", ref)],
                "--essence", essence, "--asked", asked, "--scope", "project", "--owner", "user"]
        code, out = self.py("project_decisions.py", *args)
        row = None
        if not code:
            try:
                row = json.loads(out)
            except ValueError:
                row = None
        row_id = str(row.get("id") or "") if isinstance(row, dict) else ""
        if not row_id:
            self.say_once(kind + "_add", "note: S6: the question about test accounts and records could not be written to the project's decision "
                                         "registry, so it is not asked now; the checks go on in turn and the next story tries again")
            return None
        person = build(row_id)
        self.save_state()
        return person

    def run_manual_block(self, cases: list) -> None:
        """qa-runner for the manual-agent cases, ONE block per entry: the dispatch is registered in-process (FB-9: `story_step start
        --execution-kind manual --scope <block>` registers the same fields) because the driver keeps its own role prompt lines.

        C4 (the 13797-run-3 class): only the LAST block closes the stage, and only when nothing was refused - the
        controller completes S6 over its derived scope by ACCEPTED dispatches (`_s6_completion_problems`), a case that
        was never dispatched is outside that cover, and a completion over it is refused. When refused cases exist, the
        last block goes `--not-complete` and the next entry (no block left) closes the manual half code-only, as the
        edge of this change says for "no case could be prepared".

        t-2147 C1: with `manual.walkers` 1, one lane, or a serial reason (`s6_serial_reason`) this is the old road, one lane per entry
        (`run_manual_lane(None, lane)`: no thread, no new state key, no flag on the request). Otherwise the lanes go side by side on the
        window scheduler (`run_s6_lanes`); the lanes that meet a running or stopped dispatch, or whose account cannot be read, run first
        at one lane at a time and the stage re-enters for the rest (the F6 road of `stage_S5`, one round)."""
        plan, waiting = self.manual_lane_plan(cases)
        if not plan["blocks"]:
            self.manual_close(cases, plan["refused"])
            return
        lanes = plan["blocks"]
        walkers = self.s6_walkers_cap()
        self._s6_view = {"plan": plan, "waiting": waiting, "cases": [case for lane in lanes for case in lane]}
        try:
            if walkers != 1 and len(lanes) >= 2:
                reason = self.s6_serial_reason()
                if reason:
                    self.say_once("s6-lanes", f"note: S6 lanes run one at a time: {reason}")
                if not reason or reason == self.S6_SETTLE_RUNNING:
                    try:
                        first = self.s6_settling_lanes(lanes)
                    except Exception:       # noqa: BLE001 - unreadable: the unknown stays serial (FR-59; the S5 twin does the same)
                        first = []
                        reason = reason or "the lanes that settle first cannot be read"
                    if first:
                        return self.run_s6_lanes(plan, 1, first)       # the stage re-enters for the rest
                    if not reason:
                        return self.run_s6_lanes(plan, min(walkers, len(lanes)))
            self.run_manual_lane(None, lanes[0])
        finally:
            self._s6_view = None

    S6_SETTLE_RUNNING = "dispatches of S6 are running or stopped at entry; they settle first and the rest goes side by side after"

    def s6_walkers_cap(self) -> int:
        """`manual.walkers` through `config_contract.walkers` (the one reader, AR-13); a bad value reads the default with its note, said once."""
        import config_contract
        value, note = config_contract.walkers(self.config)
        if note:
            self.say_once("manual_walkers", note)
        return value

    def s6_serial_reason(self) -> str:
        """"" when the S6 lanes may run side by side, else the one reason they run one at a time (t-2147 C1 item 7; it tells, it never stops).
        ERROR DIRECTION: it may say serial needlessly on doubt, and must never let two lanes run where a row below holds. The project's own
        word (`manual.walkers: 1`) is not this function's: that is the old road itself. Reads the entry's plan through `_s6_view`."""
        import config_contract
        import dispatch_identity
        view = getattr(self, "_s6_view", None) or {}
        host_reason = self.host_window_reason()
        if host_reason:
            return host_reason
        try:
            mode = ((config_contract.effective_config(self.config).get("execution") or {}).get("parallel") or {}).get("mode")
        except Exception:       # noqa: BLE001
            mode = None
        if mode == "serial":
            return "the project asks for serial execution (`execution.parallel.mode: serial`), so one walker uses the stand at a time"
        if getattr(self, "_s6_cap_one", False):
            return "the model service limited one lane earlier in this run"
        try:
            ctl = self.controller_state()
            rows = dispatch_identity.records(ctl.get("dispatches") if isinstance(ctl, dict) else None)
        except Exception:       # noqa: BLE001
            return "the state of the S6 dispatches cannot be read"
        if any(r.get("stage") == "S6" and r.get("status") in ("running", "blocked", "paused") for r in rows):
            return self.S6_SETTLE_RUNNING
        if view.get("waiting"):
            return "a question about a check, asked before gate B, holds a case of the plan"
        try:
            self.s6_open_lanes(())
        except Exception:       # noqa: BLE001
            return "the state or the plan of the lanes cannot be read"
        return ""

    def s6_settling_lanes(self, lanes: list) -> list:
        """The lanes among `lanes` that run FIRST at one at a time (t-2147 C1 items 2b and 6): those whose cases meet a running, blocked or
        paused S6 dispatch at entry, then those whose account cannot be read from the request. Empty when a dispatch names no case (nothing
        is then known to settle). Raises with the readers (the caller treats that as nothing to settle)."""
        import dispatch_identity
        ctl = self.controller_state()
        rows = dispatch_identity.records(ctl.get("dispatches") if isinstance(ctl, dict) else None)
        scopes = [{str(c) for c in r.get("scope") or [] if c} for r in rows
                  if r.get("stage") == "S6" and r.get("status") in ("running", "blocked", "paused")]
        if any(not s for s in scopes):
            return []
        named = [lane for lane in lanes if any({str(c) for c in lane} & s for s in scopes)]
        unreadable = [lane for lane in lanes if lane not in named and self.s6_lane_account(lane) is None]
        # TR3-10d L2 (item 7): a lane the assignment marked ALONE joins the serial first round. INVARIANT: an alone lane never runs beside
        # another lane (the holds are intersection-only, so they cannot say "conflicts with everything")
        alone = {str(c) for c in self.state.get("walk_alone") or ()}
        loners = [lane for lane in lanes if lane not in named and lane not in unreadable and lane and str(lane[0]) in alone]
        return named + unreadable + loners

    def s6_lane_account(self, lane) -> "str | None":
        """The account key of a lane (its first case, `lane_keys`, the one reader): a string (`""` = guest) or None when it cannot be read.
        ONE spelling of unreadable for the S6 lanes (t-2239 F3)."""
        cases = [str(c) for c in lane or ()]
        if not cases:
            return None
        key = lane_keys(self.task_root, cases).get(cases[0])
        return key if isinstance(key, str) else None

    def s6_lane_holds(self, cases) -> set:
        """What a lane holds while its session runs (t-2147 C1 item 3): its cases and ONE `account:<part>` per part of its account key (the
        key joins parts with `+`; lanes whose part sets meet hold a common string, so they run in turn). A guest key (`""`) holds
        `account:guest`; a key that cannot be read holds `account:?<first case>`, which no other lane holds."""
        cases = [str(c) for c in cases or ()]
        if not cases:
            return set()
        key = self.s6_lane_account(cases)
        data: set = set()
        facts = self.walk_lane_facts(cases)
        if key is None:
            accounts = {"account:?" + cases[0]}
        elif facts["handles"]:
            # TR3-10d item 2/6: one hold per ASSIGNED handle (a guest lane's own `guest#<n>`, an obtain lane's own user): lanes whose handle
            # sets meet run in turn, lanes with distinct handles side by side; and one `data:<kind>:<instance>` per record given to the lane
            accounts = {"account:" + handle for handle in facts["handles"].values()}
            import walk_session as WS
            data = {f"data:{WS.fold_kind(entry['kind'])}:{entry['instance']}" for found in facts["entries"].values() for entry in found
                    if isinstance(entry, dict) and entry.get("how") == "existing"}
        else:
            accounts = {"account:" + part for part in key.split("+") if part} or {"account:guest"}
        return {"case:" + case for case in cases} | accounts | data

    def s6_chain_kind(self) -> "ChainKind":
        """What the scheduler's console and gate call an S6 chain (t-2147 C1 item 2): a lane (`[L<n>]`), holding a case or an account."""
        return ChainKind("S6", "lane", "a case or an account", lambda cases: self.s6_lane_holds(cases), tag="L")

    def s6_open_lanes(self, excluding=()) -> list:
        """The cases of this entry's S6 manual plan that are not accepted yet, other than those of the lane `excluding` (t-2147 C1 item 5;
        `manual_done_cases` is the one reader of the accepted ones, AR-13). Read fresh. RAISES when the plan of the entry or the controller's
        dispatches cannot be read (FR-59): the caller treats that as open and never as a close."""
        view = getattr(self, "_s6_view", None)
        if not isinstance(view, dict) or not isinstance(view.get("cases"), list):
            raise ValueError("the manual plan of this entry is not known")
        ctl = self.controller_state()
        if not isinstance(ctl, dict) or not isinstance(ctl.get("dispatches"), dict):
            raise ValueError("the controller record holds no dispatches")
        own = {str(c) for c in (excluding or ()) if c}
        done = manual_done_cases(ctl)
        return [case for case in view["cases"] if case not in done and case not in own]

    def s6_seam(self, records: list, cap: int) -> None:
        """The seam after the drain (t-2147 C1 item 8; AR-17): see `run_chains`. A model-service `limit` in one lane, with more than one lane
        allowed, is not a stop: the others finished and booked, and this run goes on at one lane at a time, said once. Any other kind stops."""
        pick = self.chain_pick(records, self.s6_chain_kind(), seam_rank)
        if pick is None:
            return
        exc = pick.exception
        if isinstance(exc, InfraStop) and exc.kind == "limit" and cap > 1 and not getattr(self, "_s6_cap_one", False):
            self._s6_cap_one = True
            print("note: the model service limited a lane; the others finished and are booked, and S6 goes on one lane at a time "
                  "for the rest of this run", flush=True)
            return
        self.adopt_chain(pick)
        raise exc

    def run_s6_lanes(self, plan: dict, cap: int, lanes=None) -> None:
        """The parallel road of the manual half of S6 (t-2147 C1 item 2): one chain per lane of `lanes` (default: every lane of the plan),
        `cap` at a time, on the generic scheduler. ONE lane is the old body (no thread, C.2). A lane does not start while a live lane holds
        one of its cases or its account (`chain_launchable`)."""
        lanes = list(plan["blocks"] if lanes is None else lanes)
        if len(lanes) == 1:
            return self.run_manual_lane(None, lanes[0])
        number = {tuple(lane): i + 1 for i, lane in enumerate(plan["blocks"])}
        items = [(number[tuple(lane)], list(lane), lane) for lane in lanes]
        self.run_chains(items, self.chain_launchable, self.run_manual_lane, max(1, min(int(cap), len(items))),
                        kind=self.s6_chain_kind(), seam=self.s6_seam)

    def run_manual_lane(self, record, lane: list) -> None:
        """One lane's dispatch, walk and role (the dispatch half of the old `run_manual_block`; t-2147 C1 item 4). `record` is the lane's
        chain record on the parallel road and None on the old road. The entry's plan comes through `_s6_view`. Differences of the parallel
        road only: the request carries `walk_lane` and `walk_actor`; `complete` is a callable read at the finish, under `_book`; a lane that
        ends before `run_role` closed its walk closes it here."""
        import acceptance
        self.boundary = "S6"
        self.stop_if_drained()      # C.7: a drained lane registers nothing (a no-op off a chain)
        view = getattr(self, "_s6_view", None) or {}
        plan, waiting = view["plan"], view["waiting"]
        parallel = record is not None
        block = lane
        if parallel:
            complete = None         # read at the finish (below)
            print(f"S6: manual block of {len(block)} case(s): {', '.join(block)}")
        else:
            complete = len(plan["blocks"]) == 1 and not plan["refused"] and not waiting      # a held case is outside the cover, as a refused one is
            if acceptance.consumer_of("S6"):
                # X7-6: the LAST block stops awaiting the consumer's acceptance (a refused or held case is then closed by `manual_close`, whose
                # site finds the record); an earlier block is not complete, as today.
                complete = self.consumer_awaits("S6", True) if len(plan["blocks"]) == 1 else False
            print(f"S6: manual block of {len(block)} case(s)" + (f", {len(plan['blocks']) - 1} more block(s) after it"
                                                                  if len(plan["blocks"]) > 1 else "")
                  + f": {', '.join(block)}")
        from controller import Controller
        import event_store
        # A lifecycle command, like every CLI main: it waits for an in-flight writer instead of
        # failing at once. Read at call time, so a test can shorten it.
        controller = Controller(self.task_root, wait_seconds=event_store.LIFECYCLE_WAIT_SECONDS)
        # t-2147 C1 (C.9, POSITIONAL): the count that names the id, the registration below and the walk record of `walk_before` follow one
        # another in ONE booked step - a chain holds `_book` from its start and gives it up only around a role's `claude` (`unbooked`), so
        # no other lane counts or registers between them. INVARIANT: two lanes never take one dispatch id, and the walk record is in place
        # before the role starts.
        state = controller.state()
        prior = [d for d in state.get("dispatches", {}).values() if d.get("stage") == "S6" and d.get("role") == "qa-runner"]
        # TR3-10d L1: the id `assign_entities` wrote into the claims store is the id this walk opens under; a lane with no reservation takes
        # the first number that no dispatch has and no other lane reserved (without any reservation this is `len(prior) + 1`, as before)
        facts = self.walk_lane_facts(block)
        reserved = {str(i) for i in (self.state.get("walk_ids") or {}).values() if i}
        if facts["id"] and facts["id"] not in state.get("dispatches", {}):
            dispatch_id = facts["id"]
        else:
            dispatch_id = self.walk_next_id(state.get("dispatches", {}), len(prior) + 1, reserved)
        assigned = facts["handles"] or None
        # t-289 (live S6 rehearsal, cmp2r): a story in `plan_contract_mode: new` has `prepare` itself demand the
        # `execution_kind` of a qa-runner packet and run `validate_manual_runner_block` over the block, so BOTH go in
        # with the options (they were added to the request only after `prepare`, which died with a ValueError and a
        # traceback). One try covers prepare and apply: whatever the controller refuses is the refusal below with its
        # own words (FR-1, P1) - the driver never dies on it. The fields stay on the request too, for a story in the
        # legacy mode, whose `prepare` copies neither.
        try:
            packet = controller.prepare({"stage": "S6", "role": "qa-runner", "id": dispatch_id, "scope": block,
                                         "execution_kind": "manual", "manual_case_ids": list(block)})
            request = dict(packet["dispatch_request"], execution_kind="manual", manual_case_ids=list(block),
                           purpose="manual")
            if parallel:
                # AR-22: `walk_lane` and `walk_actor` are read by `controller._lane_beside_running` (the admission of a lane beside a running
                # one); the actor is the lane's account key as a string (`""` = guest), a key that cannot be read is `?<case>` (never equal)
                # F3: an unreadable key puts neither on the request (the controller then admits nothing beside a running lane, FR-59)
                key = self.s6_lane_account(block)
                if isinstance(key, str):
                    # TR3-10d item 2: with an assignment the actor is the `+`-joined sorted handles (a guest lane's `guest#<n>`); the
                    # controller seam compares whole strings and the driver's holds keep the overlap of handle SETS unreachable
                    request.update(walk_lane=True, walk_actor="+".join(sorted(set(assigned.values()))) if assigned else key)
            controller.apply("dispatch", request)
        except Exception as exc:
            raise Refusal(f"S6 manual block dispatch refused: {type(exc).__name__}: {exc}")
        # G3 (C1-7b): the running record is written BEFORE the dispatch; a non-zero exit is a `Refusal` (the factory's own) and the
        # role is not started over a stage the record does not show as running (the guard and the dashboard read it). The refusal's
        # retry runs THIS function (B-4 ii, the G1 pattern; fix round F-2): a successful retry CONTINUES the rest of the step - the
        # role, with the manual-block instructions. The dispatch registered above stays `running` in the controller, so a retry that
        # reran only the record would leave it to `where` -> `wait_existing_job` -> `_act_wait_existing_job`, which starts the role
        # WITHOUT these lines (the execution kind, the prepared request paths, `role_lines`) and with `completion_for` instead of this
        # block's `complete`. INVARIANT: the registered dispatch is never left for that path without the instructions. A conductor's
        # `continue` (no retry) keeps the `where` road - the 13797-run-3 path, which the driver can run because it knows the record.
        # t-1957 N5s (E5s.4): the walk session is opened AFTER the dispatch is registered and BEFORE the role starts (the brief is written
        # with the walk record in place); a lane whose session did not open runs on today's road below, brief lines and all
        # TR3-10d N7: an ASSIGNED lane whose walk failed to open (`walking` False) falls back to the old road, which signs in with the CASE's
        # own account key, not the assigned handle. That is safe only because the recorder takes the stand lease EXCLUSIVE
        # (`manual_capture._hold_stand`, mode default) and so never runs beside a walk; a shared lease for the recorder would put two
        # lanes in one account - change it together with this site.
        walk = self.walk_before(block, dispatch_id, assigned) if assigned else self.walk_before(block, dispatch_id)
        walking = walk["walking"]
        if parallel:
            def run_complete(digest) -> object:
                """C.6, read at the finish under `_book` (the S6 twin of `s5_last_fn`): True only when this lane leaves no case of the entry's
                plan open, no refusal or held case stands and no walk record is waiting for a second walk; an unreadable state is open (FR-59)."""
                try:
                    base = ((not self.walk_pending(block) if walking else True)
                            and not self.walk_pending(view.get("cases") or block) and not self.s6_open_lanes(excluding=block))
                except Exception:       # noqa: BLE001 - FR-59: an unknown is never a close
                    base = False
                if acceptance.consumer_of("S6"):
                    # X7-6 (AR-25): the last lane awaits the consumer whatever is refused or held; `manual_close` closes those later, and its
                    # site finds the accept record
                    return self.consumer_awaits("S6", base)
                return base and not plan["refused"] and not waiting
        else:
            run_complete = (lambda _digest, base=complete: False if self.walk_pending(block) else base) if walking else complete

        def record_then_role() -> None:
            self.record_running("S6", "qa-runner", dispatch_id, retry=record_then_role)
            if walking:
                # the walker has the commands of its session in its brief; the driver closes it and builds the records (`walk_after`),
                # so no `finalize_task.py` line - unless no run report exists and none could be made (E5s.3)
                extra = [f"Execution kind: manual — walk the items of walk session {dispatch_id} (the `Walk:` line of your brief) with the "
                         "commands of your brief; the factory closes the session and builds the case records when you end."
                         + (f" Your last command: `finalize_task.py {self.task_root}` (no run report exists yet)."
                            if walk["report_last"] else "")]
                if assigned:
                    # TR3-10d item 4 (D.10): an ASSIGNED parallel lane only (walkers 1, one lane, a part with no handle: no new line, the
                    # prompt is as before). The sentences are the ones of `walk-charter.md`; the person's data words go whole, unless they look
                    # like a secret (an unreadable pattern list masks them too: FR-59, an unknown is never shown)
                    if any(str(h).startswith("obtain:") for h in assigned.values()):
                        extra.append("Before your first item, make your own user on the app's sign-up page with `fill-new-account` steps, then "
                                     "sign in with `fill-account <selector> created:<name> user|secret`. If that step is refused because the "
                                     "sign-up 'was not seen to land' but you saw the app accept it (a success message on the same page), say "
                                     "`account created:<name> confirmed \"<what you saw>\"` and sign in again. If the sign-up did not succeed, "
                                     "say `account created:<name> unconfirmed \"<what you saw>\"` and end without walking the items.")
                    extra.append("Before you change a record other walkers could also use, claim it: `walk_session.py claim --kind <what it is> "
                                 "--instance <its id>` (`--all` when your check reads the whole list); a claim held by another walker waits a "
                                 "little, then tells you what to do.")
                    import walk_pool as WP
                    extra.extend(WP.entity_lines(facts["entries"]))
                    try:
                        import config_contract as CC
                        import guard_secrets
                        import manual_capture as MC
                        data = CC.walk_supply(self.config)[0]["data"]
                        words = str(data.get("words") or "")
                        if data.get("known") and words.strip():
                            try:
                                cfg = MC.load_config(self.task_root)[0]
                            except ValueError:
                                cfg = {}
                            try:
                                hit = MC.secret_pattern_hit(words, {"secret_content_patterns": guard_secrets._patterns(
                                    cfg, "secret_content_patterns", list(guard_secrets.DEFAULT_SECRET_CONTENT_PATTERNS))}) is not None
                            except ValueError:
                                hit = True
                            extra.append("How this project handles shared records, in the person's words: \""
                                         + ("(not shown: they look like a secret)" if hit else words) + "\"")
                    except Exception:       # noqa: BLE001 - P1: a line the lane cannot have is no stop; the lane walks without it
                        pass
            else:
                extra = (["Execution kind: manual — execute the approved manual-agent cases in this block, "
                          "record each observation as manual evidence, then `finalize_task.py <task root>`.",
                          "Prepared requests, one per case (read the one of each case; never rebuild it): "
                          + ", ".join(self.manual_request_paths(block))]
                         + [f"{case}: unprepared - {why}; walk it yourself with the recorder (manual_capture.py) or the "
                            "browser and record every doubtful place; a seed the recorder cannot do by API is done through the "
                            "screens, and a capture the factory refuses for its own gap halts nothing; close the case with "
                            f"`manual_evidence.py unprepared --task-root {self.task_root} --case {case} "
                            "--observations-file <file>` (add `--not-walked \"<why>\"` when nothing was walked with the "
                            "recorder); record no pass or fail"
                            for case, why in plan.get("unprepared") or [] if case in block])
            self.run_role("S6", "qa-runner", scope=block, complete=run_complete, extra=extra + self.role_lines("S6", "qa-runner"),
                          rework={"id": dispatch_id, "scope": block, "reason": "manual block"})     # `run_role` owns the walk hook (F4)
        if not parallel:
            record_then_role()
            return
        try:
            record_then_role()
        except BaseException:       # noqa: BLE001 - C.3: a lane that ends before `run_role` closed its walk closes it here (idempotent, never raises)
            if walking:
                self.walk_after(block, dispatch_id, {})
            raise

    def failures_to_triage(self) -> str:
        report = _read_json(self.task_root / "work/run-report.json")
        status = report.get("execution_status")
        if status not in ("passed", "failed"):
            # t-305 N1 (Q19 a): `not_executed` is also what S6 leaves on purpose when it closes on a CODE-ONLY receipt
            # (nothing to execute, or everything handed to a person); S7 reads that report. Without the receipt it is
            # an S6 halt, and the refusal below stands word for word. The receipt is read only on this branch.
            import s7_pretriage
            if not (status == "not_executed" and s7_pretriage.s6_closed_by_code(self.task_root)):
                raise Refusal(f"S7 entry: run-report.json execution_status is `{status}` — nothing to triage yet; "
                              "the S6 halt that produced it stands")
        totals = report.get("current_totals") or report.get("totals") or {}
        reasons = []
        if int(totals.get("failed") or 0):
            reasons.append(f"failed={totals.get('failed')}")
        # t-309: the one definition of a failure that needs triage (contract.triage_targets), shared with the
        # reducer and the S7 handover check - a manual `inconclusive` or `error` is a failure here as there.
        import contract
        targets = contract.triage_targets(report)
        bad = sorted(targets["manual"]) + sorted(targets["unnamed_manual"])
        if bad:
            reasons.append("manual " + ",".join(bad))
        # P26 / RN1-10 (AR-28): a runner's observation, whatever its check's result, wants the analyst's verdict - a green check
        # with an observation dispatches the analyst; a report with none reads exactly as before
        if targets["observations"]:
            reasons.append("manual observations " + ",".join(sorted(targets["observations"])))
        # t-323 C2: a failed RESULT row with no id sits in `unnamed` beside the nameless manual checks, and was worded
        # "manual" with them - a failure of the automated run named as a manual check; it gets its own words
        nameless = sorted(targets["unnamed"] - targets["unnamed_manual"])
        if nameless:
            reasons.append(f"{len(nameless)} failed result row(s) with no id")
        if targets["results"] and not int(totals.get("failed") or 0):
            reasons.append("failed results " + ",".join(sorted(targets["results"])))
        manifest = _read_json(self.task_root / "work/automation-manifest.json")
        if "contradicts_requirement" in json.dumps(manifest.get("unresolved") or []):
            reasons.append("contradicts_requirement rows")
        return "; ".join(reasons)

    def stage_S7(self) -> None:
        state = self.controller_state()
        # P2 M3: an accepted INVESTIGATION is never a triage (case 1: with no triage file `analyst_done` would read True and a
        # re-triage of a story with no failure would start)
        import acceptance
        # X7-6: an analyst dispatch whose finish carried `stage_superseded` (S6's consumer REJECTED the runner's handoff) is stale work on
        # a handoff that was not accepted: it is not a triage, and a new analyst is owed after the runner's repair (E-24, AR-28). An accepted
        # INVESTIGATION is no triage either: `author_dispatches` is the one reading of both (M4 of t-1860).
        analyst_done = any(d.get("status") == "accepted" for d in acceptance.author_dispatches(state, acceptance.stage_def_of("S7")))
        awaiting = acceptance.awaits_acceptance(state, "S6", self.pipeline())      # the runner's last dispatch when S6 awaits its consumer
        if self.s7_closed_by_scribe(state):
            return
        if awaiting:
            if self.consumer_settled("S6", state, awaiting, analyst_done):
                return
        if analyst_done and not self.s7_fresh():
            # t-698 §20 N1 (FRESHNESS): an accepted analyst is only as fresh as the controller's staling, and a person-word rework of an
            # earlier stage does not stale an OPEN S7 (its stamp names completed stages only). A current failure with no row of the
            # triage is triaged again (a new analyst = a new life) and S7 is never closed over it. ONE re-triage per chain: a second
            # consecutive not-fresh triage asks the person through the seam (`s7_retriage_once`), never a third analyst (§22 FX-3).
            self.s7_retriage_once()
            print("S7: a failure of the current run report has no row in work/triage.json; the failure analyst triages again")
            analyst_done = False
        elif analyst_done and self.state.pop("s7_retriage", None):      # a fresh triage ends the chain
            self.save_state()
        if not analyst_done:
            reasons = self.failures_to_triage()
            if not reasons and not awaiting:
                # P2 M3 (the investigation before a close by code). POSITION INVARIANT: after `failures_to_triage` (a halted run raises
                # before any register write) and before the receipt (which hashes the register the pass wrote).
                self.s7_close_places(self.s7_gap_reason("no_failures"))      # t-1991 U3a: BEFORE the gate (a place is never both gaps)
                verdict, suffix = self.s7_investigation_gate()
                if verdict == "wait":
                    return
                register = ["work/exploratory-findings.jsonl"] if (self.task_root / "work" / "exploratory-findings.jsonl").is_file() else []
                self.close_by_code("S7", "no failures — nothing to triage" + suffix,
                                   ["work/run-report.json"] + register, site="s7.no_failures", finalize=False,
                                   tail=[["--event", "dispatch_skipped", "--task", self.task, "--reason", "S7: no failures to triage"]])
                return
            # t-305 N1 (Q23): code decides what the run already recorded BEFORE the analyst is asked (`s7_pretriage`:
            # a manual `inconclusive` whose own record says what stopped it; a red test is never pre-judged). POSITION
            # INVARIANT: after the entry refusal of `failures_to_triage` (a halted run is never triaged, so no row is
            # written over one) and before the analyst's dispatch (an analyst row is never written over, and the analyst
            # is never asked about a failure code answered). It runs on EVERY entry, so a row the analyst dropped is
            # restored; it does not run while an S7 dispatch is in flight (the analyst writes the same file). A pre-triage
            # that cannot run is one printed line and the analyst triages everything, as before (P1).
            import s7_pretriage
            pre = {}
            if not reasons:
                print("S7: no failure to triage; the failure analyst still judges the runner's handoff (S6 awaits its acceptance)")
            elif any(d.get("stage") == "S7" and d.get("status") == "running" for d in (state.get("dispatches") or {}).values()):
                print("S7: a triage dispatch is in flight; code writes no triage row while the analyst may be writing the file")
            else:
                try:
                    pre = s7_pretriage.pretriage(self.task_root)
                except Exception as exc:
                    print(f"S7: pre-triage could not run ({type(exc).__name__}: {exc}); the failure analyst triages every failure")
                for note in pre.get("notes") or []:
                    print("S7: " + note)
            if pre.get("closes") and not awaiting:
                said = f"every failure has a state the run already recorded: {len(pre['kept'])} written by code"
                # P2 M3. POSITION INVARIANT: after the pre-triage wrote its rows (the targets' triage context reads them), before the receipt.
                self.s7_close_places(self.s7_gap_reason("pretriaged"))       # t-1991 U3a: BEFORE the gate (a place is never both gaps)
                verdict, suffix = self.s7_investigation_gate()
                if verdict == "wait":
                    return
                register = ["work/exploratory-findings.jsonl"] if (self.task_root / "work" / "exploratory-findings.jsonl").is_file() else []
                self.close_by_code("S7", said + suffix, ["work/run-report.json", "work/triage.json"] + register, site="s7.pretriaged", finalize=False,
                                   tail=[["--event", "dispatch_skipped", "--task", self.task, "--reason",
                                          "S7: every failure has a state the run already recorded"]])
                return
            left = pre.get("left") or {}
            told = [f"Failures to triage: {reasons}"]
            if pre.get("kept") and (left.get("results") or left.get("manual") or left.get("unnamed")):
                # only the failures code left to the analyst are named, and the rows code wrote are named once, so the
                # analyst keeps them (they are listed under `not_for_repair` like any other row) or replaces one (Q10, Q11)
                told = ["Failures to triage: " + s7_pretriage.brief(
                            [("result", n) for n in left["results"]] + [("manual", n) for n in left["manual"]],
                            left["unnamed"], bool(pre.get("contradicted"))),
                        "Rows already written by code (keep them; you may replace one with your own): "
                        + ", ".join(pre["kept"])]
            complete = self.completion_for("S7", "qa-failure-analyst", {})
            if awaiting:
                # X7-6. POSITION: the record is written from the analyst's FINISH, BEFORE the controller accepts it as S7 work, and never by
                # the runner's own finish; the analyst is let in by the controller while S6 awaits (`awaits_acceptance`, one reader).
                complete = self.consumer_completion("S6", complete)      # the repair budget is read only if the verdict is a reject (B1)
            self.run_role("S7", "qa-failure-analyst", complete=complete,
                          extra=self.role_lines("S7", "qa-failure-analyst") + told
                          + ([f"You also accept or return the runner's handoff ({awaiting}): the verdict is `header.verdict` of your form, "
                              "and `inputs_read` names the runner's form work/handoffs/" + awaiting + ".yaml."] if awaiting else []))
            if awaiting:
                self.consumer_settled("S6", self.controller_state(), awaiting, True, ran=True)
                return          # S6 closes by the record (or the runner repairs) BEFORE S7's own repairs run
        self.s7_repairs()

    # --- X7-6b / X7-6c: S7 is accepted by its CONSUMER (the doc scribe of S8); the analyst's finish never closes it. The helpers shared with S6
    # are the `consumer_*` set above. ------------------------------------------------------------------------------------------------------
    def s7_closed_by_scribe(self, state: dict) -> bool:
        """X7-6b. POSITION: S7 closes HERE, by the consumer's (the doc scribe's) `accept` record of the analyst's LAST dispatch - never by the
        analyst's own finish (§3). INVARIANT: no record, a reject or a record for an earlier dispatch closes nothing; a failure of the current
        run report with no triage row (`s7_fresh`) closes nothing either and falls through to the re-triage. The close only CLOSES: the
        reduction ran when S7 went awaiting (`s7_await_scribe`, B3), so no second `finalize_task` (`finalize=False`)."""
        if not self.consumer_pending("S7"):
            return False
        reason, digest = self.consumer_close_words("S7")            # N4: who accepted, from the record (the scribe, or the person's word)
        return bool(self.close_by_code("S7", reason, ["work/triage.json", "work/run-report.json"],
                                       finalize=False, site="s7.accepted", digest=digest, fresh=self.s7_fresh))

    def s7_open_words(self, life: str) -> str:
        """The person's words of the recorded `close` answer to the open-work question of this life (`state["s7_open_work"][life]`, the file
        `_answer_open_work` kept); `""` when there is no such answer. A recorded answer whose file cannot be read still passes (its token is
        the word): the text then says so."""
        if not self.s7_open_answer(life):
            return ""
        rec = (self.state.get("s7_open_work") or {}).get(life) or {}
        try:
            text = (self.task_root / str(rec.get("words_file") or "")).read_text(encoding="utf-8", errors="replace") if rec.get("words_file") else ""
        except OSError:
            text = ""
        return text.strip() or "close (the answer to the open-work question; its words could not be read)"

    def s7_await_scribe(self, person_words: str = "") -> bool:
        """The end of S7's repairs under a consumer (X7-6b): with a consumer, an analyst dispatch that ran and NO accept record for its LAST one,
        S7 is left AWAITING the scribe. True = `s7_close` is done for this entry (nothing is closed, nothing is refused); False: no consumer, no
        analyst dispatch, S7 completed, or an accept record stands (a person's pass included: `person_words` - the recorded `close` answer - or a
        live waiver of `stage acceptance` is recorded as the accept by `consumer_person_pass`, M3, so the close goes on below).
        B3 (the Lead's decision): the reduction runs HERE, when S7 goes awaiting - BEFORE the marker and before S8 builds its ledger and report
        over it: `finalize_task`, then `s7_fresh`; a failure of the current run report with no triage row writes NO marker and S7 stays open for
        the re-triage (as at the close by code). The marker `pipeline["acceptance_awaits"]["S7"] = <the analyst's last dispatch>` (THE carrier
        `awaits_acceptance` reads; the controller, `next` and `rule_order` let the scribe in by it) is bound to a dispatch, so a scribe reject that
        reworks the analyst makes a NEW dispatch and this runs again at the next awaiting."""
        import acceptance
        if not acceptance.consumer_of("S7"):
            return False
        state = self.controller_state()
        if ((state.get("stages") or {}).get("S7") or {}).get("status") == "completed":
            return False
        author = acceptance.stage_author_dispatch(state, acceptance.stage_def_of("S7"))
        if not author or self.consumer_person_pass("S7", author, person_words):
            return False
        pipeline = self.pipeline()
        if acceptance.awaits_acceptance(state, "S7", pipeline) != author:
            code, out = self.py("finalize_task.py", str(self.task_root))
            if code:
                raise Refusal(f"S7 awaiting the scribe: finalize_task.py exit {code}: " + (out.splitlines()[-1] if out else ""))
            if not self.s7_fresh():
                print("S7: a failure of the current run report has no row in work/triage.json after the repairs; S7 stays open "
                      "and the failure analyst triages again on the next turn")
                return True
            from event_store import atomic_json
            pipeline = self.pipeline()
            marks = pipeline.get("acceptance_awaits") if isinstance(pipeline.get("acceptance_awaits"), dict) else {}
            pipeline["acceptance_awaits"] = dict(marks, S7=author)
            atomic_json(self.task_root / "pipeline.json", pipeline)
        print(f"S7: the repairs ended; S7 awaits the acceptance of {acceptance.consumer_of('S7')} for {author} (the scribe is let in; its record closes S7)")
        return True

    # --- S7 stays OPEN until its repairs end and is closed by code (C1-5b2, t-698 §18-§20) ----------------------------------------
    @staticmethod
    def s7_test_name(row: dict) -> str:
        case = str(row.get("case") or "").split("#")[0].split("::")[0]
        return str(row.get("test") or row.get("instance") or row.get("id") or case)

    def s7_listed_rows(self) -> list:
        """THE reader of the `triage` list of `work/triage.json` for the S7 loops (the repair rows and the re-judge rows both
        come through it, AR-13). A file that holds no list is a Refusal naming it - the analyst writes it again; nothing is guessed."""
        triage = _read_json(self.task_root / "work/triage.json")
        listed = triage.get("triage") if isinstance(triage, dict) else None
        if not isinstance(listed, list):
            raise Refusal("S7 repairs: work/triage.json holds no `triage` list, so the rows to repair are unknown; "
                          "the failure analyst writes it again")
        return listed

    def s7_rejudge_rows(self) -> list:
        """The triage rows S7 sends BACK TO THE RUNNER (HF8-19): the verdict `RUNNER_MISREAD_EVIDENCE`, no `fix_result` of `fixed` /
        `not_fixed`, not a `reorder` row, a non-empty `case`, and no problem of `contract.triage_contradiction_problems` (the one
        reader of the block, shared with the validator and the delivery check). A row that fails the selection starts nothing and
        is said in one line; the delivery check names it itself and the red stands. `s7_repair_rows` never sees this word (the S7
        contract's `repair_verdicts` is unchanged). ERROR DIRECTION: only toward NOT sending - a paid re-judge needs a row that
        passes every check. An unreadable list is the `Refusal` of `s7_listed_rows`."""
        import contract
        import s7_reorder
        out = []
        for row in self.s7_listed_rows():
            if not isinstance(row, dict) or row.get("verdict") != contract.TRIAGE_MISREAD_VERDICT:
                continue
            if str(row.get("fix_result", "")) in ("fixed", "not_fixed") or s7_reorder.wants_reorder(row) \
                    or not str(row.get("case") or "").strip():
                continue
            problems = contract.triage_contradiction_problems(row, self.task_root)
            if problems:
                print(f"S7: the row {self.s7_ident(row)} is {contract.TRIAGE_MISREAD_VERDICT} but is not sent back to the runner: "
                      f"{problems[0]}")
                continue
            out.append(row)
        return out

    def s7_repair_rows(self) -> list:
        """THE reader of the rows S7 repairs: the triage rows whose verdict is one of the S7 contract's own declaration
        (`null_outcome.scope.params.repair_verdicts`, data - FR-13; the word before the first colon, upper-cased) and that carry no
        `fix_result` of `fixed` / `not_fixed`. It filters by verdict and `fix_result` ONLY: the outcome skip of this life is applied
        in `s7_repairs` (at the analyst's finish there is no life yet). The analyst's finish (`s7_open_work`) and the loop both come
        through it. ERROR DIRECTION: a declaration or a triage list that cannot be read is a Refusal naming it - the finish then
        keeps S7 OPEN, and the entry refuses: a repair left undone is the one mistake this stage may not make."""
        import handoff
        declared = ((handoff.null_outcomes("s7-analyst-to-automator").get("scope") or {}).get("params") or {}).get("repair_verdicts")
        if not (isinstance(declared, list) and declared):
            raise Refusal("S7 repairs: handoffs/s7-analyst-to-automator.yaml carries no readable "
                          "`null_outcome.scope.params.repair_verdicts`, so the verdicts to repair are unknown; restore the "
                          "declaration (`null_outcomes.audit` names the contract) and enter S7 again",
                          close={"site": "s7.repair_verdicts", "stage": "S7", "step": "entry"})
        listed = self.s7_listed_rows()
        repair = {str(v).split(":")[0].strip().upper() for v in declared}
        import s7_reorder
        open_rows = [r for r in listed if isinstance(r, dict) and str(r.get("fix_result", "")) not in ("fixed", "not_fixed")]
        for r in open_rows:
            # a `reorder` request that cannot be executed is refused by name, never skipped (FR-1; the finish keeps S7 open)
            problems = s7_reorder.row_problems(r)
            if problems:
                raise Refusal("S7 repairs: " + problems[0] + " (work/triage.json; the failure analyst writes the row again)")
        # a row that asks for the reorder round is a repair whatever its verdict is (an APP_BUG whose later Thens stand behind
        # the red one): `reorder` is the analyst's request, `s7_reorder` the round (t-1508 R7)
        return [r for r in open_rows if s7_reorder.wants_reorder(r)
                or str(r.get("verdict", "")).split(":")[0].strip().upper() in repair]

    def s7_open_work(self):
        """What the analyst's finish does to S7 (`completion_for`): `OpenWork` while repair rows remain - or cannot be read - and
        `None` (today's road: the analyst closes S7) when there is nothing to repair. The reason is TIMELESS (it stays on the
        analyst's dispatch record after the close, where the dashboard lists it) and at most 300 characters: a longer list is cut
        with `…` and the path of the whole list."""
        try:
            rows = self.s7_repair_rows()
            rejudge = self.s7_rejudge_rows()        # HF8-19: one `try` - an unreadable list keeps S7 open for both
        except Refusal:
            return OpenWork("repairs_pending", "the failure analyst finished, but the factory could not read which verdicts are "
                            "repaired or the list of triage rows; S7 was kept open until it can")
        if not rows and not rejudge:
            # P2 M3, decision only. POSITION INVARIANT: after `s7_repair_rows` (repair rows outrank the investigation and `decision` is
            # not asked while one remains). This function never dispatches, projects or writes: it asks, the closers act.
            # What the role still decides: the investigation itself. An exception of the investigation code is one printed line and
            # today's road (P1, F-5).
            try:
                import investigation
                budget, _ = investigation.load_budget(self.plugin)
                word, why = investigation.decision(self.task_root, self.controller_state(), self.pipeline(), budget)
                if word == "none":
                    return None
                try:
                    open_ones = investigation.open_targets(self.task_root, budget)["unresolved"]
                except Exception:
                    open_ones = None
            except Exception as exc:
                print(f"S7: the observations the run left open could not be asked about ({type(exc).__name__}: {exc}); "
                      "S7 closes as it did without that")
                return None
            what = f"{len(open_ones)} observations" if open_ones is not None else "observations"
            head = f"the failure analyst finished; {what} the run left open are not investigated yet; "
            tail = {"dispatch": "S7 was kept open for one bounded read-only investigation",
                    "wait": "an investigation of them is running"}.get(
                word, f"before the close those only the factory has written are recorded as coverage gaps and those the analyst "
                      f"wrote are left as the analyst recorded them ({why})")
            return OpenWork("investigation_pending", open_work_reason(head + tail, "… [list: work/exploratory-findings.jsonl]"))
        # each sentence only for its own non-empty list (FR-10: the sentence about the TEST is never printed over a misread check)
        said = []
        if rows:
            said.append(f"the failure analyst found {len(rows)} failing test(s) whose fault is the test itself; "
                        f"S7 was kept open for their repairs: {', '.join(self.s7_test_name(r) for r in rows)}")
        if rejudge:
            said.append(f"the failure analyst found {len(rejudge)} manual check(s) whose record misreads its own captures; S7 was "
                        f"kept open until the runner judges them again: {', '.join(str(r.get('case')).strip() for r in rejudge)}")
        return OpenWork("repairs_pending", open_work_reason("; ".join(said), "… [list: work/triage.json]"))

    def s7_unbound(self):
        """The current failures of `work/run-report.json` that no row of `work/triage.json` answers, by THE binding
        (`contract.triage_failures` + `bind_triage`): their names, sorted, and one line for the failures with NO name at all (§21 iv:
        nothing can say they were triaged). `[]` is fresh; `None` - an unreadable report or list - is unknown, and unknown is not
        fresh (FR-41)."""
        import contract
        report = _read_json(self.task_root / "work/run-report.json")
        triage = _read_json(self.task_root / "work/triage.json")
        rows = triage.get("triage") if isinstance(triage, dict) else None
        if not (isinstance(report, dict) and report and isinstance(rows, list)):
            return None
        failures, unnamed = contract.triage_failures(report)
        bound = contract.bind_triage(failures, rows)["matched"]
        return sorted(key[1] for key in failures if not bound[key]) + ([f"{len(unnamed)} failure(s) with no name"] if unnamed else [])

    def s7_fresh(self) -> bool:
        """N1: every current failure of the run report is bound to a row of the triage (`s7_unbound` is empty). False - an unreadable
        report or list included - means the analyst's triage is not of this run: S7 is triaged again and never closed over it (allowed
        error: a needless triage; forbidden: a close over a failure nobody triaged)."""
        return self.s7_unbound() == []

    def s7_retriage_once(self) -> None:
        """The bound of N1's re-triage (t-698 §22 FX-3): ONE paid re-triage per chain of not-fresh triages. The record `s7_retriage`
        names the life the re-triage was started FROM; a not-fresh triage of a LATER life is the second consecutive one - the analyst
        has been asked again and the failure is still unbound, so the seam asks the person (`call=False`, no paid call; `retry` /
        `go on` / `stop`) and never a third analyst. A fresh triage ends the chain (`stage_S7` drops the record)."""
        life = self.s7_life()
        started = str((self.state.get("s7_retriage") or {}).get("from") or "")
        if started and started != life:
            unbound = self.s7_unbound()
            names = ("these failures still have no verdict from it: " + "; ".join(unbound)) if unbound else (
                "the factory could not read the run report or the analyst's list to say which failures have no verdict")
            self.no_move({"why": "threshold", "kind": "refusal", "call": False, "stage": "S7", "dispatch": life,
                          "lead": "The failure analyst has judged this story's failing tests twice, and " + names + ". The factory will "
                                  "not pay for a third go on its own, and it will not close this step over a failure nobody judged. "
                                  "Which of these should happen?",
                          "text": "Failures with no verdict from the analyst: " + ("; ".join(unbound) if unbound else "not known")})
        self.state["s7_retriage"] = {"from": life, "at": _now()}
        self.save_state()

    def s7_life(self) -> str:
        """The window life of the S7 repairs: the id of the latest ACCEPTED S7 `qa-failure-analyst` dispatch (new on every
        triage). `""` when none is readable: nothing is then written under it and no stored record is trusted (FR-59)."""
        import controller as CT
        found = [str(d.get("id") or key) for key, d in (self.controller_state().get("dispatches") or {}).items()
                 if isinstance(d, dict) and d.get("stage") == "S7" and d.get("role") == "qa-failure-analyst"
                 and d.get("status") == "accepted" and CT.s7_part_of(d) != "investigation"]       # P2 M3: an investigation is never the life
        return found[-1] if found else ""

    def s7_decided(self, life: str | None = None) -> dict:
        """The person's recorded decision on this life's analyst (`story_step._decision_of`, the one reader), `{}` when there is none -
        or none can be read: a stuck text asks it and must not fail (the error direction is today's wording)."""
        try:
            life = self.s7_life() if life is None else life
            import story_step
            return story_step._decision_of(self.task_root, life) if life else {}
        except Exception:
            return {}

    def s7_outcome(self, life: str, ident: str) -> str:
        """How this life ended the repairs of one test (`repaired` / `debt` / `no_progress`), `""` while it has not."""
        rec = ((self.state.get("s7_rows") or {}).get(life) or {}).get(ident) if life else None
        return str((rec or {}).get("outcome") or "")

    def s7_mark(self, life: str, ident: str, **fields) -> None:
        if not life:
            return
        rows = self.state.setdefault("s7_rows", {}).setdefault(life, {})
        rows[ident] = dict(rows.get(ident) or {}, at=_now(), **fields)
        self.save_state()

    def s7_ident(self, row: dict) -> str:
        """The identity of a triage row WITHIN a life (t-698 §22 FX-1): the row's OWN stable name (`contract.row_names`, the first).
        It is never rebuilt from `automation-manifest.json`: the repair round the loop dispatches is the automator, whose output IS
        that manifest, so a key read from it drifts under the loop's feet (a repaired row would be repaired again; the person's
        answer would not be found). A row with no name at all is `<its case>#<its index in the list of triage.json>` - stable within
        a life, since the list is fixed until the close's finalize."""
        import contract
        names = contract.row_names(row)
        if names:
            return names[0]
        listed = _read_json(self.task_root / "work/triage.json").get("triage") or []
        return f"{str(row.get('case') or '').strip()}#{listed.index(row) if row in listed else -1}"

    def s7_refs(self, row: dict) -> tuple:
        """`(tests, bound)`: the ledger refs of the manifest tests this triage row answers NOW (`ledger.triage_refs`, the reader the
        report's `Runs left failing` uses). A row no test is bound to is named `unbound:<its identity>`: that never equals a ledger ref,
        so it covers no other row, and `debt_key` keeps two apart. Read once per (life, row): `s7_tests` freezes it."""
        import ledger
        refs = ledger.triage_refs(self.task_root, row)
        return (refs, True) if refs else (["unbound:" + self.s7_ident(row)], False)

    def s7_tests(self, row: dict, ident: str, life: str) -> tuple:
        """`(tests, bound)` of a row, FROZEN per (life, row) at the first computation (t-698 §22 FX-1): the question, the debt entry and
        the answer read the frozen list, never a later reading of the manifest the repair round rewrites. Under life `""` nothing is
        written (`s7_mark`), so every call reads again."""
        kept = ((self.state.get("s7_rows") or {}).get(life) or {}).get(ident) if life else None
        if isinstance(kept, dict) and isinstance(kept.get("tests"), list) and kept["tests"]:
            return list(kept["tests"]), bool(kept.get("bound"))
        tests, bound = self.s7_refs(row)
        self.s7_mark(life, ident, tests=tests, bound=bound)
        return tests, bound

    def s7_plan(self, rows: list, life: str) -> list:
        """`[(row, ident, tests, bound)]` of the rows to repair, each keyed by its own name (`s7_ident`) with its frozen refs."""
        return [(row, ident, *self.s7_tests(row, ident, life)) for row, ident in ((row, self.s7_ident(row)) for row in rows)]

    def s7_repairs(self) -> None:
        """The repairs run INSIDE the open stage and end in exactly ONE of three ways: S7 closed by code (`s7_close`), the person asked
        (a `Person`) or a `Refusal` - a silent return with S7 open would repeat this entry on every `where`. The only returns are
        the person's recorded `close` (S7 is theirs to close), said in a printed line. Their recorded `open_work` ends in the closed
        question of `s7_open_work_ask` (t-698 §22 FX-2): the code does not close the stage over it, and `decide --close` is no door (it
        refuses an accepted dispatch), so the person's `close` is an answer to that question, read by `s7_open_answer`."""
        rows = self.s7_repair_rows()
        life = self.s7_life()
        decided = self.s7_decided(life)
        if "close" in decided:
            print("S7: the person's recorded decision closes S7; no repair round is dispatched")
            return
        plan = self.s7_plan(rows, life)
        for row, ident, tests, bound in plan:
            if not self.s7_outcome(life, ident):
                self.s7_repair_test(row, ident, tests, bound, life)
        # HF8-19: the checks a runner misread go back to the runner. POSITION INVARIANT: BELOW the person's recorded `close` (their
        # word is never answered by a paid round, P13), after the test repairs, and BEFORE `open_work` / `s7_close`: S7 is neither
        # closed nor is the person asked about its close while a selected row of this life has no `outcome`.
        plan_rejudge = [(row, self.s7_ident(row)) for row in self.s7_rejudge_rows()]
        for row, ident in plan_rejudge:
            self.s7_rejudge_round(row, ident, life)
        if "open_work" in decided and not self.s7_open_answer(life):
            self.s7_open_work_ask(plan, life, decided["open_work"])
        self.s7_close(plan, life, plan_rejudge)

    def s7_open_answer(self, life: str) -> bool:
        """The person answered `close` to the question of this life's `open_work` (`state["s7_open_work"][life]`). Under life `""` nothing is
        trusted (FR-59)."""
        return bool(life) and ((self.state.get("s7_open_work") or {}).get(life) or {}).get("token") == "close"

    def s7_open_work_ask(self, plan: list, life: str, decision: dict) -> None:
        """Every row of an `open_work` life has ended: ONE closed question names the person's open decision (their own words, quoted
        from the file `decide --open` kept) and asks whether to close S7 now (`close` -> `s7_close` on the next entry) or stop. No paid
        call, no round, no close here (P13: their word outranks the code's close); an entry with the question unanswered asks it again."""
        ended = [self.s7_outcome(life, ident) for _row, ident, _tests, _bound in plan]
        try:
            kept = (self.task_root / str(decision.get("words_ref") or "")).read_text(encoding="utf-8", errors="replace") if decision.get("words_ref") else ""
        except OSError:
            kept = ""
        quoted = f' (your words: "{self.s0_quote(kept)}")' if kept.strip() else ""
        lead = (f"You decided to keep {self.stage_place('S7')} open for more work{quoted}. The repairs of the failing tests it found are finished: "
                f"{ended.count('repaired')} repaired, {ended.count('debt')} left failing by your answer, {ended.count('no_progress')} stopped "
                "because a round changed nothing.\n\nShould the factory close this stage now, or hold it open?")
        self.state.setdefault("s7_open_work", {})[life] = {"token": "", "lead": lead, "at": _now()}
        self.save_state()
        print("S7: the repairs ended and the person's recorded decision keeps S7 open; the person is asked whether to close it")
        self.no_move({"why": "threshold", "kind": "open_work", "call": False, "stage": "S7", "dispatch": life, "lead": lead,
                      "site_doors": ("close",), "site_fallback": lambda said: self.s7_open_work_person(life, lead, said)})

    def s7_open_work_person(self, life: str, lead: str, said: str = "") -> Person:
        """The question from its words: `said` (an unread answer's lead) above the account, then the two priced answers of `s7.open_work`.
        ONE literal `closed_question` (the census of question ids reads it)."""
        lead = lead if not said.strip() or said.strip() == lead.strip() else said.strip() + "\n\n" + lead
        close = {"answer": "close", "token": "close", "slots": {},
                 "says": "the stage is closed now with one receipt written by the factory's own commands; nothing is run again and the "
                         "repairs stay as they ended"}
        return Person("open_work", self.closed_question("s7.open_work", lead, [close, dict(self.STOP_OPTION)]), "S7", life)

    def _answer_open_work(self, words: str, qtext: str, stage: str, dispatch: str) -> None:
        """The answer to the end-of-`open_work` question (FR-9: each token has an executor; FR-12: tokens only). `close` is kept for this
        life and the next entry closes S7 by code (`s7_repairs`); `stop` holds the question (it comes back on a rerun); any other word goes
        to the seam once, with this question as the one shown again."""
        rec = (self.state.get("s7_open_work") or {}).get(dispatch) or {}
        token = self.s0_normalize(words)
        if not rec or token not in ("close", "stop"):
            self.unread("open_work", stage, dispatch, qtext, words=words, doors=("close", "stop"), lead=self.unread_lead(words),
                        again=lambda said: self.s7_open_work_person(dispatch, rec["lead"], said) if rec else self.held_question(said))
            return
        self.answer_row(f"{stage} open work ({token}): ", words.strip(), what="your answer about the open work")
        if token == "stop":
            raise self.held_question(self.stop_held("If you want the factory to close the stage after all, answer `close`."))
        rec.update(token="close", words_file=self.answer_file(), answered=_now())
        self.save_state()
        print(f"{stage}: the person's answer `close` is recorded; the stage is closed on the next step")

    def s7_close(self, plan: list, life: str, rejudge: list = ()) -> None:
        """Every row ended in this life: finalize, then the receipt and the record, through `close_by_code` (the stage_done carries the
        analyst's digest and what happened to the repairs). A current failure with no triage row (checked after finalize, before the
        receipt) leaves S7 open for the next entry, which triages again (N1)."""
        # P2 M3: the investigation of what the run left open comes FIRST. POSITION INVARIANT: after every repair row of the life ended
        # (this is reached only from the end of `s7_repairs`), before the acceptance stop, finalize and the receipt. `wait`: no close, the next `where` resumes.
        # t-1991 U3a. POSITION INVARIANT: the places nobody settled are gapped BEFORE the investigation gate, so a place is never both a
        # settle gap and an investigation gap (`close_unsettled` never writes a plain open target; its `by` is outside `code:investigation.`).
        self.s7_close_places(self.s7_gap_reason())
        verdict, suffix = self.s7_investigation_gate()
        if verdict == "wait":
            return
        # X7-6b. POSITION INVARIANT: after the investigation (`author_dispatches` leaves it out: it is no triage), before the close by code: with a
        # consumer and no accept record the end of the repairs is «S7 awaits the scribe» (the reduction runs there, B3), never a close and never a
        # refusal; the record closes S7 at `s7.accepted` on the next entry. Both closing roads (the end of the repairs, the person's `close`
        # answer) come through here; a recorded `close` answer or a waiver is the person's pass (M3) and closes by the person's word below.
        if self.s7_await_scribe(self.s7_open_words(life)):
            return
        self.consumer_need_record("S7", "s7_close")        # the invariant: past this line a record stands (or there is no consumer); a bare close is refused
        ended = [self.s7_outcome(life, ident) for _row, ident, _tests, _bound in plan]
        debts = [self.s7_test_name(item[0]) for item, end in zip(plan, ended) if end == "debt"]
        fixed, stopped = ended.count("repaired"), ended.count("no_progress")
        reason = (f"repairs ended: {fixed} repaired; {len(debts)} left failing by your answer"
                  + (": " + ", ".join(debts) if debts else "") + f"; {stopped} stopped because a round changed nothing")
        sent = [self.s7_outcome(life, ident) for _row, ident in rejudge].count("rejudged")
        sent_back = f"{sent} manual check(s) were sent back to be judged again" if sent > 0 else ""
        if not plan:        # no repair row: the sentence above would say a repair happened (FR-10)
            reason = sent_back or "no failing test to repair; the failure analyst's triage stands"
        elif sent_back:
            reason += "; " + sent_back
        reason += suffix
        analyst = self.saved_done(life)
        digest = ((analyst or f"qa-failure-analyst S7 {self.task} done") + f"; repairs: fixed={fixed} not_fixed={len(debts)} stopped={stopped}"
                  + (f"; {sent_back}" if sent_back else "") + suffix)
        if not analyst:
            print("S7: the analyst's saved digest could not be read; the close carries a short digest")
        evidence = (["work/triage.json", "work/run-report.json"] + (["work/review-debts.json"] if debts else [])
                    + (["work/exploratory-findings.jsonl"] if (self.task_root / "work" / "exploratory-findings.jsonl").is_file() else []))
        if not self.close_by_code("S7", reason, evidence, site="s7.after_repairs", finalize=True, digest=digest, role="qa-failure-analyst", journal=True,
                                  fresh=self.s7_fresh):
            print("S7: a failure of the current run report has no row in work/triage.json after the repairs; S7 stays open "
                  "and the failure analyst triages again on the next turn")

    def s7_place_lines(self, dispatch) -> list:
        """t-1991 U3a (the analyst settles the places): the brief lines of the places of S7 - each place with its sources, state and the
        expectation the record names, the four answers and the four sources, the capture case `settle-<place id>`, the commands. The ONE
        formatter is `place_answers._list_lines` (what `place_answers.py list` prints); more places than `brief_places_max` are cut with
        a pointer. A list that could not be computed whole says so in the brief and in ONE printed line, never "none" (AR-28). The
        brief only TELLS the analyst an answer is owed; whether a place is answered is the register's business at the close (P1)."""
        base = f"qa-factory/artifacts/{self.task}/"
        py = '`python "${CLAUDE_PLUGIN_ROOT}/scripts/'
        try:
            import place_answers
            data = place_answers._data()
            found = place_answers.places(self.task_root)
            states = {p["id"]: place_answers.settled_answer(self.task_root, p["id"]) for p in found["places"]}
            listed = place_answers._list_lines(found, states)
        except Exception as exc:
            print(f"S7: the places to settle could not be listed ({type(exc).__name__}: {exc})")
            return [f"The list of places to settle could not be computed whole ({type(exc).__name__}: {exc}): run {py}place_answers.py\" list "
                    f"--task-root {base}` and settle what it lists."] + self.s7_session_line(dispatch)
        if found["unreadable"]:
            print("S7: the places to settle could not be computed whole: " + "; ".join(f"{rec}: {why}" for rec, why in found["unreadable"]))
        count = len(found["places"])
        if not count and not found["unreadable"]:
            return listed + self.s7_session_line(dispatch)      # "Places to settle: none in this run"
        head, rows = listed[:len(listed) - count], listed[len(listed) - count:]
        cap = int(data["brief_places_max"])
        lines = head + rows[:cap] + ([f"[and {count - cap} more: place_answers.py list]"] if count > cap else [])
        disp = str(dispatch) if dispatch else "<your dispatch id>"
        lines += ["An answer is owed for every place that is not settled: `answer` is one of " + ", ".join(f"`{a}`" for a in data["answers"])
                  + "; name beside it where your expectation comes from, `expectation.source` one of "
                  + ", ".join(f"`{s}`" for s in data["sources"]) + ".",
                  "The answer file is one JSON object: `place`; `answer`; `expectation` {`source`, `id`, `quote`}; `seen` {`capture`: the path "
                  "the recorder wrote, `quote`: words that capture holds}; and by answer `question` (requirement_silent), `why` (not_a_bug, "
                  "impossible), `draft` (bug: the file name of your draft under work/bug-drafts/, whose `reproduction` holds "
                  "`{kind: walk, evidence: evidence/place-answer-<place id>.json, observed: what you saw}` and whose `confirmation` is "
                  "`unconfirmed`). `place_answers.py write --help` lists the rest.",
                  f"Capture each place under its own case `settle-<place id>`: {py}manual_capture.py\" ui|http --task-root {base} "
                  "--case settle-<place id>` (`ui` also needs `--steps-file`, `http` needs `--method` and `--url`; the capture is the evidence "
                  "your answer quotes).",
                  f"Commands: {py}place_answers.py\" list --task-root {base}` prints the places with their states; {py}place_answers.py\" write "
                  f"--task-root {base} --dispatch {disp} --place <place id> --file <your answer, a JSON file>` records one answer "
                  "(`--replace` replaces an answer you gave)."]
        return lines + self.s7_session_line(dispatch)

    def s7_neighbour_lines(self, dispatch) -> list:
        """t-2187 N6: the brief lines of the neighbourhood hint of an S7 triage dispatch - the groups of failures, observations, rows and
        drafts that share a requirement, case, test file, code line or seen value, cut to `brief_neighbours_max` groups (the data row of
        `references/place-answers.json`) with the command for the rest. `bug_neighbours` formats and counts; this only hands it over (FR-15).
        A table that could not be computed whole says so in the brief and in ONE printed line, never "none" (AR-28). A hint: the brief
        does not ask the analyst to merge anything (AR-29)."""
        command = f'`python "${{CLAUDE_PLUGIN_ROOT}}/scripts/bug_neighbours.py" --task-root qa-factory/artifacts/{self.task}/`'
        try:
            import bug_neighbours
            import place_answers
            found = bug_neighbours.neighbours(self.task_root)
            shown = bug_neighbours.lines(found, int(place_answers._data()["brief_neighbours_max"]))
        except Exception as exc:
            print(f"S7: the neighbourhood table could not be computed ({type(exc).__name__}: {exc})")
            return [f"The neighbourhood table could not be computed whole ({type(exc).__name__}: {exc}): run {command} for it."]
        if found["unreadable"]:
            print("S7: the neighbourhood table could not be computed whole: " + "; ".join(f"{item[0]}: {item[1]}" for item in found["unreadable"]))
        return shown + [f"Command: {command} prints the whole table."]

    # --- t-1991 U3b: the walk session of an S7 triage dispatch (lane `settle`); opened and closed by `run_role` / `resume_role` -------------
    S7_SETTLE_ITEMS = "free"       # the item word when the run has no place at all (control walks only); otherwise the place ids
    S7_SETTLE_ACTOR = "guest"       # the spec names no account for a place: no sign-in by code is needed to open (returned as a question)

    def s7_is_triage(self, stage: str, role: str, dispatch: str, purpose: str = "") -> bool:
        """True for an S7 `qa-failure-analyst` dispatch that is NOT an investigation (`controller.s7_part_of` of its record, else the
        `purpose` of a request not yet a record). INVARIANT: an investigation never gets the place lines or the session; a record that
        cannot be read answers False (the investigation's side), with one printed line."""
        if stage != "S7" or role != "qa-failure-analyst" or purpose == "investigation":
            return False
        try:
            import controller as CT
            records = (self.controller_state().get("dispatches") or {}).items()
            record = next((d for key, d in records if isinstance(d, dict) and str(d.get("id") or key) == str(dispatch)), {})
            return CT.s7_part_of(record) != "investigation"
        except Exception as exc:
            print(f"S7: the kind of dispatch {dispatch} could not be read ({type(exc).__name__}: {exc}); it gets no place lines and no walk session")
            return False

    def s7_session_line(self, dispatch) -> list:
        """The brief line about the walk session of `dispatch` from `state["s7_walk"][dispatch]`: the session and its reopen door, or
        'no walk session: <why>' with the road that needs none. `[]` when no record exists (nothing was opened or tried)."""
        record = (self.state.get("s7_walk") or {}).get(str(dispatch)) if dispatch else None
        if not isinstance(record, dict):
            return []
        base = f"qa-factory/artifacts/{self.task}/"
        py = '`python "${CLAUDE_PLUGIN_ROOT}/scripts/'
        door = (f"capture with {py}manual_capture.py\" ui|http --task-root {base} --case settle-<place id>`")
        if record.get("failed"):
            return [f"no walk session: {record.get('why') or record['failed']}; capture with `manual_capture.py ui|http --case settle-<place>`"
                    f" ({py}manual_capture.py\" ui|http --task-root {base} --case settle-<place id>`), or answer `impossible` with that why."]
        if record.get("state") != "ready":
            return []                   # closed with its dispatch: nothing to offer
        items = ",".join(record.get("items") or [self.S7_SETTLE_ITEMS])
        skipped = [str(i) for i in record.get("skipped") or []]
        out = [f"The walk session `{dispatch}` is open (its items are the place ids: `{items}`): {py}walk_session.py\" step|look|final "
               f"--task-root {base} --walk {dispatch} --item <place id> --line \"<one step>\"` (or `--steps-file <file>`), one step or a short "
               f"obvious run per call; its captures are under settle-<place id>, where your answer's `seen.capture` points. If a call says "
               f"it ended: {py}walk_session.py\" open --task-root {base} --walk {dispatch} --place settle --items {items} "
               f"--actor {self.S7_SETTLE_ACTOR} --parent-pid {os.getpid()}` reopens it for the same walk; if it cannot open, {door}, or "
               "answer `impossible` with why 'the walk session could not be opened'."]
        if skipped:
            out.append("Places the session cannot carry (their id is no plain id): " + ", ".join(f"`{i}`" for i in skipped)
                       + f"; capture each with {py}manual_capture.py\" ui|http --task-root {base} --case settle-<place id>`.")
        return out

    def s7_settle_session(self, dispatch: str, resume: bool = False) -> bool:
        """Opens the settle walk session of an S7 triage dispatch (`walk_session.py open --place settle --walk <dispatch> --items <the place ids>`; `free` only when the run has no place)
        and records `state["s7_walk"][dispatch]` = `{"state": "ready"}` or `{"failed": "stand"|"session", "why"}` (`s7_gap_reason` reads
        it). Returns True when a session is ready and this call's caller must close it. NEVER raises (P1): a session that cannot open is
        a record and a printed line, and the role runs on the `manual_capture` road. `resume`: a server that is `ready` and alive is left
        alone (E3b.5); any other is reopened for the same walk. `stand` when `open`'s answer carries `cause: stand_busy` (the exit and the
        answer, never a word in the text; t-2027 F11), else `session`. Places whose id the lane cannot carry are left out of the session and
        named in the brief line (t-2027 F9)."""
        walks = self.state.setdefault("s7_walk", {})
        why, cause, skipped = "", "", []
        if resume and isinstance(walks.get(dispatch), dict):
            skipped = [str(i) for i in walks[dispatch].get("skipped") or []]
        try:
            if resume:
                record = _read_json(self.task_root / "state" / "walks" / f"{dispatch}.json")
                import walk_session as WS
                if isinstance(record, dict) and record.get("state") == "ready" and WS.alive(record):
                    walks[dispatch] = {"state": "ready", "items": [str(i) for i in record.get("items") or []]}
                    return True
                items = [str(i) for i in (record or {}).get("items") or []] if isinstance(record, dict) else []
            if not resume or not items:
                import place_answers
                found = place_answers.places(self.task_root)
                if found["unreadable"]:         # AR-28: a list not read whole opens no session (the place ids are the items)
                    why = "ValueError: the places to settle could not be listed whole: " + "; ".join(f"{r}: {w}" for r, w in found["unreadable"])
                else:
                    import walk_session as WS
                    ids = [p["id"] for p in found["places"]]
                    items = [i for i in ids if WS.lane_item_ok(i)] or [self.S7_SETTLE_ITEMS]
                    skipped = [i for i in ids if not WS.lane_item_ok(i)]
            if not why:
                code, text = self.py("walk_session.py", "open", "--task-root", str(self.task_root), "--walk", dispatch, "--place", "settle",
                                     "--items", ",".join(items), "--actor", self.S7_SETTLE_ACTOR)
                if code:
                    got = _read_answer(text) or {}
                    cause = str(got.get("cause") or "")
                    why = str(got.get("reason") or "").strip()[:300] or (text.splitlines() or [f"exit {code}"])[-1][:300]
        except Exception as exc:        # P1: code informs, it never stops the factory
            why = f"{type(exc).__name__}: {' '.join(str(exc).split())[:200]}"
        if why:
            walks[dispatch] = {"failed": "stand" if cause == "stand_busy" else "session", "why": why, **({"skipped": skipped} if skipped else {})}
            print(f"S7: {dispatch}: no walk session ({why}); the analyst captures with manual_capture.py or answers `impossible`")
        else:
            walks[dispatch] = {"state": "ready", "items": items, **({"skipped": skipped} if skipped else {})}
        try:
            self.save_state()
        except Exception as exc:
            print(f"note: the walk record of {dispatch} was not saved ({type(exc).__name__})")
        return not why

    def s7_settle_close(self, dispatch: str) -> None:
        """Closes the settle session of `dispatch` (`walk_session.py close`). Never raises: a server that did not close ends by itself
        (parent check, `max_s`); the failure is one printed line."""
        try:
            # remains: the exit is read on the next line and said; a server that did not close ends by itself (parent check, max_s)
            code, text = self.py("walk_session.py", "close", "--task-root", str(self.task_root), "--walk", dispatch)
            if code:
                print(f"note: walk_session.py close exit {code}: {(text.splitlines() or [''])[-1][:200]}; the server ends by itself")
        except Exception as exc:
            print(f"note: walk_session.py close raised {type(exc).__name__}; the server ends by itself")
        record =(self.state.get("s7_walk") or {}).get(dispatch)
        if isinstance(record, dict) and record.get("state") == "ready":
            record["state"] = "closed"

    def s7_gap_reason(self, kind: str = "") -> str:
        """t-1991 U3a: the text the driver gives `place_answers.close_unsettled` (`references/place-answers.json` `gap_reason_names`, five texts picked by name).
        `kind` `no_failures` / `pretriaged` -> those names (no analyst ran). Otherwise `unanswered` - true whether or not the dispatch was told -
        unless the record U3b writes for the last S7 triage dispatch (`state["s7_walk"][<id>]["failed"]`) names `stand` or `session`. `""` when the texts cannot be read: `close_unsettled` then refuses and `s7_close_places` prints one line."""
        try:
            import place_answers
            texts = place_answers._data()["gap_reason_names"]           # chosen by NAME: a reorder of the list cannot give a false text
            if kind in ("no_failures", "pretriaged"):
                return texts[kind]
            import controller as CT
            ids = [str(d.get("id") or key) for key, d in (self.controller_state().get("dispatches") or {}).items()
                   if isinstance(d, dict) and d.get("stage") == "S7" and d.get("role") == "qa-failure-analyst" and CT.s7_part_of(d) != "investigation"]
            walk = (self.state.get("s7_walk") or {}).get(ids[-1]) if ids else None
            failed = str((walk or {}).get("failed") or "") if isinstance(walk, dict) else ""
            return texts["stand"] if failed == "stand" else texts["session"] if failed == "session" else texts["unanswered"]
        except Exception as exc:
            print(f"S7: the reason for the places nobody settled could not be chosen ({type(exc).__name__}: {exc})")
            return ""

    def s7_close_places(self, why: str) -> list:
        """t-1991 U3a: ONE call at each of the three S7 code closers, BEFORE `s7_investigation_gate` (INVARIANT: a place is never both a settle
        gap and an investigation gap; `close_unsettled` never writes a plain `open` place, and its `by` is outside the investigation's
        prefix). The ids of the register lines written. The list that could not be read whole is one printed line and the close still runs
        on what was read; an exception is one printed line and S7 goes on - it never reads as "no places" (P1, AR-28)."""
        try:
            import place_answers
            found = place_answers.places(self.task_root)
            if found["unreadable"]:
                print("S7: the places to settle could not be computed whole: " + "; ".join(f"{rec}: {w}" for rec, w in found["unreadable"]))
            printed: list = []
            written = place_answers.close_unsettled(self.task_root, why, printed, found=found)
        except Exception as exc:
            print(f"S7: the places nobody settled could not be recorded as gaps ({type(exc).__name__}: {exc}); S7 goes on")
            return []
        for line in printed:
            print(f"S7: {line}")
        if written:
            print(f"S7: {len(written)} place(s) nobody settled were recorded as coverage gaps: {why}")
        return written

    def s7_places_scribe_line(self) -> list:
        """t-1991 U3a: the ONE line the S8 scribe gets about the places of S7 - settled ones with the answer and the source of its
        expectation (where `expectation.source` reaches a reader beside `answer_problems`), unsettled ones with their state. At most
        `scribe_line_max` characters (the data row of `references/place-answers.json`); more is cut with "[and <n> more: place_answers.py list]". Returning the triage
        for them is the scribe's judgment; this line only shows the facts."""
        try:
            import place_answers
            cap = int(place_answers._data()["scribe_line_max"])
            found = place_answers.places(self.task_root)
            rows = [(p["id"],) + tuple(place_answers.settled_answer(self.task_root, p["id"])) for p in found["places"]]
        except Exception as exc:
            print(f"S7: the places for the scribe could not be listed ({type(exc).__name__}: {exc})")
            return [f"Places of S7: the list could not be computed whole ({type(exc).__name__}: {exc}); run place_answers.py list"]
        if found["unreadable"]:
            print("S7: the places for the scribe could not be computed whole: " + "; ".join(f"{rec}: {why}" for rec, why in found["unreadable"]))
        if not rows and not found["unreadable"]:
            return ["Places of S7: none in this run"]
        done, left = [], []
        for pid, record, state, _why in rows:
            if state == "settled":
                src = (record.get("expectation") or {}) if isinstance(record, dict) else {}
                done.append(f"{pid}: {record.get('answer')} (expectation: {src.get('source') or 'none'}"
                            + (f" {src.get('id')}" if src.get("id") else "") + ")")
            else:
                left.append(f"{pid} ({state})")
        entries = done + left
        whole = f" (not computed whole: {', '.join(rec for rec, _w in found['unreadable'])[:200]})" if found["unreadable"] else ""

        def render(keep: int) -> str:
            shown_done, shown_left = done[:keep], left[:max(0, keep - len(done))]
            parts = ([f"settled {len(done)}" + (" — " + "; ".join(shown_done) if shown_done else "")] if done else []) \
                + ([f"not settled {len(left)}" + (": " + ", ".join(shown_left) if shown_left else "")] if left else [])
            text = f"Places of S7 ({len(rows)}){whole}: " + "; ".join(parts)
            return text + (f" [and {len(entries) - keep} more: place_answers.py list]" if keep < len(entries) else "")
        for keep in range(len(entries), -1, -1):
            if len(render(keep)) <= cap or keep == 0:
                return [render(keep)]
        return [render(0)]

    def s7_investigation_gate(self) -> tuple:
        """What S7 does about the observations the run left open BEFORE it closes by code (P2 M3): `(verdict, suffix)`, verdict
        `proceed` | `dispatched` | `wait`, suffix the text added to the close reason and digest (`""` when nothing happened). Called
        ONLY at the three code closers (`s7.no_failures`, `s7.pretriaged`, `s7.after_repairs`), never at the stage entry. `wait`: the
        caller returns WITHOUT a close (a running pass; the next `where` resumes it). A stage the controller holds `completed` is
        never worked on. An exception of the investigation code is one printed line and today's close (P1, F-5). The decision itself
        is `investigation.decision` (pure); the register is written only through `investigation.project` / `close_gaps`. What the
        role still decides: the investigation itself (targets worth a probe, what the probe shows, how it is recorded)."""
        held = ((self.controller_state().get("stages") or {}).get("S7") or {}).get("status")
        if held == "completed":
            return "proceed", ""
        try:
            import investigation
            budget, _ = investigation.load_budget(self.plugin)
        except Exception as exc:
            print(f"S7: the investigation could not be loaded ({type(exc).__name__}: {exc}); S7 closes as it did without it")
            return "proceed", ""
        try:
            investigation.project(self.task_root, "S7")
        except Exception as exc:
            print(f"S7: the observations the run left open could not be projected ({type(exc).__name__}: {exc}); "
                  "S7 goes on with what the register holds")
        try:
            word, why = investigation.decision(self.task_root, self.controller_state(), self.pipeline(), budget)
            targets = (investigation.open_targets(self.task_root, budget)["unresolved"] if word == "dispatch" else [])
        except Exception as exc:
            print(f"S7: the investigation could not be decided ({type(exc).__name__}: {exc}); S7 closes as it did without it")
            return "proceed", ""
        if word == "wait":
            print(f"S7: the investigation {why} is running; S7 is not closed over it")
            return "wait", ""
        if word == "none":
            if why:
                print(f"S7: {why}")
            return "proceed", ""
        printed: list = []
        if word == "gaps":
            try:
                if why == investigation.WHY_TEXTS[0]:
                    print("S7: the investigation budget cannot be used (" + "; ".join(investigation.budget_problems(budget)) + ")")
                g = len(investigation.close_gaps(self.task_root, why, printed, budget=budget))
            except Exception as exc:
                print(f"S7: the observations the run left open could not be recorded as gaps ({type(exc).__name__}: {exc}); "
                      "S7 closes as it did without it")
                return "proceed", ""
            for line in printed:
                print(f"S7: {line}")
            return "proceed", (f"; {g} observation(s) the run left open were not investigated: {why}" if g else "")
        # dispatch: ONE bounded read-only pass, synchronous like the triage; a halt, a question threshold or a Refusal of
        # `run_role` interrupts the gate and leaves the dispatch `running` (the next entry goes through `wait_existing_job`)
        print(f"S7: {len(targets)} observation(s) the run left open are not investigated; one bounded read-only investigation is dispatched")
        self.run_role("S7", "qa-failure-analyst", purpose="investigation", complete=False,
                      extra=self.role_lines("S7", "qa-failure-analyst", {"stage": "S7", "purpose": "investigation"}))
        try:
            g = len(investigation.close_gaps(self.task_root, investigation.WHY_TEXTS[1], printed, budget=budget))
            for line in printed:
                print(f"S7: {line}")
            import exploratory_findings
            chains = exploratory_findings.chains_of(exploratory_findings.read(self.task_root)["lines"])
            by_role = {t for t, chain in chains.items() if any(not investigation.is_code_line(line) for line in chain)}
            k = len({str(t["id"]) for t in targets} & by_role)
        except Exception as exc:
            print(f"S7: what the investigation recorded could not be counted ({type(exc).__name__}: {exc}); S7 closes without the count")
            return "dispatched", ""
        return "dispatched", (f"; {len(targets)} observation(s) the run left open were investigated read-only: {k} recorded by the "
                              f"analyst, {g} left as coverage gaps")

    def investigation_lines(self) -> list:
        """The dispatch lines of the read-only investigation (P2 M3), recomputed from the CURRENT state at every call (a relaunch after
        a first attempt lists only the targets still without an active line): the two honesty lines first, the targets whole (observed
        verbatim, FR-49) with their triage context, the caps of `references/investigation-budget.json`, the commands, the six end
        states and the form note. A target list that cannot be computed is one printed line and a line telling the role to ask for it.
        What the role still decides: which target to probe, what to ask the stand, how to record what it saw."""
        base = f"qa-factory/artifacts/{self.task}/"
        py = '`python "${CLAUDE_PLUGIN_ROOT}/scripts/'
        lines = ["This dispatch is an INVESTIGATION (purpose `investigation`), not a triage and not a rework: a `Rework reason: investigation` "
                 "line above, if any, is the controller's purpose word.",
                 "The triage judge line and `work/judge-triage.json`, if present, are not your input: the triage is done."]
        try:
            import investigation
            budget, problems = investigation.load_budget(self.plugin)
            found = investigation.open_targets(self.task_root, budget)
        except Exception as exc:
            print(f"S7: the targets of the investigation could not be listed ({type(exc).__name__}: {exc})")
            return lines + [f"The factory could not list the targets ({type(exc).__name__}: {exc}): run {py}investigation.py\" unresolved "
                            f"--task-root {base}` and investigate what it lists, within the caps of references/investigation-budget.json."]
        if found["unresolved"]:
            lines.append("Findings to investigate:")
            for target in found["unresolved"]:
                lines.append(f"- {target['id']}: Then: {target['then']} | observed (verbatim): {target['observed']} | before the change: "
                             f"{target['before_change']} | evidence: {', '.join(target['evidence']) or 'none'} | why inconclusive: "
                             f"{target['why_inconclusive']}")
                lines += [f"  S7 triage said (context, not a verdict): {ctx}" for ctx in found["context"].get(target["id"], [])]
        else:
            lines.append("Findings to investigate: none left — each target already has an active line; hand back the form")
        if problems:
            lines.append("The investigation budget cannot be used (" + "; ".join(problems) + "): every probe is refused - record nothing new "
                         "and hand back the form.")
        else:
            p, r, t = budget["probes_per_dispatch"], budget["reproductions_per_target"], budget["timebox_minutes"]
            try:                    # the probes the pass has made so far (a retry/relaunch continues the counts); never a stop (P1)
                import investigation_probe
                used = str(len(investigation_probe.capture_lines(self.task_root)))
            except Exception:
                used = "unknown"
            lines.append(f"Caps of this investigation: {p} probes per pass (used so far: {used}), {r} per target, {t} minutes from the first probe; at most "
                         f"{p // r} targets (P divided by R, rounded down) can reach `reproduced` - choose which ones.")
        lines += [f"Commands: {py}investigation_probe.py\" http --task-root {base} --dispatch <your dispatch id> --target <target id> --method GET "
                  f"--url <address>` sends ONE read-only request; {py}investigation_probe.py\" record --task-root {base} --dispatch <your "
                  "dispatch id> --target <target id> --kind <observation|unresolved_question|coverage_gap> --statement <what you saw> "
                  f"--why-not-a-bug <why> --status <status>` writes what you saw; {py}exploratory_findings.py\" list --task-root {base}` "
                  "shows the register.",
                  "End states of a target, exactly one active line each: `reproduced` / `not_reproduced` / `environment_event` / "
                  "`unverified` (k of R) / `unresolved_question` / `coverage_gap`.",
                  "Record what the product does; never compare it with an expected value; never write a bug or a triage row; only "
                  "`investigation_probe.py` reaches the stand.",
                  "The places of `place_answers.py list` were the triage's to settle; you do not walk the page for them and do not answer them.",
                  "Your hand-back is the usual S7 form `s7-analyst-to-automator` with `scope: []` and no `not_for_repair` rows, and it is checked "
                  "whole. Fill: the `inputs_read` row [0] for `work/run-report.json` with its `version` and `failures` (what you read); the "
                  "`inputs_read` row [1] the template lists (the runtime provenance record, its `path` and `version`); the three `claims.*` "
                  "keys (true or false, none blank); `header.verdict`. Leave `unresolved` as the template has it - the register "
                  "(`exploratory_findings.py list`) is the carrier of what you left `unverified`, not the form; `triage.json` is not yours "
                  "to change. Your DIGEST (the result you return) carries one line per item of this dispatch's scope - every TC-n in scope: "
                  "`passed` for the ones that passed, `unresolved` for the targets above - and without such a line for an item the "
                  "hand-over is refused as incomplete."]
        return lines

    def saved_done(self, dispatch: str) -> str:
        """The digest of an ACCEPTED dispatch from its saved result (`driver-runs/<id>.done.json`), `""` when it is unreadable."""
        found = _read_json(self.state_dir / "driver-runs" / f"{dispatch}.done.json") if dispatch else {}
        return self.digest_of(str(found.get("result") or "")) if isinstance(found, dict) and found.get("result") else ""

    def close_by_code(self, stage: str, reason: str, evidence: list, *, finalize: bool, site: str = "", digest: str = "", role: str = "",
                      journal: bool = False, tail=(), fresh=None) -> bool:
        """THE helper of "a stage closed by code after its post-role loop" (t-698 §18.5; S7's two closes and the close after its
        repairs, and the three S6 closes, which pass `finalize=False` after their own `finalize_task` call and its own refusal text;
        C2-8 marks every one with its `site`): `finalize_task` when `finalize` (BEFORE the receipt, so the receipt hashes what finalize
        wrote), the `code_only` receipt (`close_receipt`), then the `stage_done` record (`record_close`). A stage the controller holds
        `completed` already is NOT closed again (state is read first, never a refusal's words): no finalize, no second receipt. A
        `stage_done` refused after a successful `code_only` is a Refusal whose retry repeats `record_close` - the write AND its tail.
        `fresh`: a precondition checked after finalize, before the receipt; False records nothing and returns False."""
        held = ((self.controller_state().get("stages") or {}).get(stage) or {}).get("status")
        if held == "completed":
            print(f"{stage}: the controller holds it completed already; no second receipt is written")
            return True
        if finalize:
            code, out = self.py("finalize_task.py", str(self.task_root))
            if code:
                raise Refusal(f"{stage} close: finalize_task.py exit {code}: " + (out.splitlines()[-1] if out else ""))
        if fresh is not None and not fresh():
            return False
        receipt = self.close_receipt(site, stage, reason, evidence)
        self.file_passed_over(stage, receipt)
        self.record_close(site, stage, "--status", "done", *(["--role", role] if role else []),
                          "--digest", digest or reason, *([] if journal else ["--no-journal"]), tail=tail, receipt=receipt)
        return True

    def file_passed_over(self, stage: str, receipt) -> None:
        """TR1-9 B4 (AR-27): the work a code close passed over (`stages[stage].passed_over`, written by the controller's `code_only`
        receipt: `returned, never accepted`, `abandoned`, `stopped, never accepted`) is a FINDING, one per dispatch, idempotent by
        (task, stage, dispatch). Position: right after the receipt, before the stage record, so a refused record cannot lose the name;
        the report reads the same names from the stage entry (`report_facts._passed_over_gap`). An unreadable state files nothing here
        and the stage entry still carries the names."""
        state = self.controller_state()
        stages = state.get("stages") if isinstance(state, dict) else None
        entry = stages.get(stage) if isinstance(stages, dict) else None
        rows = state.get("dispatches") if isinstance(state, dict) and isinstance(state.get("dispatches"), dict) else {}
        named = entry.get("passed_over") if isinstance(entry, dict) else None
        for item in named if isinstance(named, list) else []:
            if not isinstance(item, dict) or not item.get("id"):
                continue
            ident = str(item["id"])
            who = str((rows.get(ident) or {}).get("role") or "a role") if isinstance(rows.get(ident), dict) else "a role"
            self.owe_row("project_decisions.py", "--root", str(self.project), "add-finding",
                         "--essence", f"{stage} was closed by code over the work of {who} ({ident}): {item.get('label') or 'never accepted'}"[:500],
                         "--scope", "local-calibration", "--witness", f"close receipt {receipt}",
                         "--idempotency-key", f"close-passed-over:{self.task}:{stage}:{ident}",
                         what="the finding about work a code close passed over", stage=stage)

    def s7_repair_test(self, row: dict, ident: str, tests: list, bound: bool, life: str) -> None:
        """The repair rounds of ONE failing test, until it is green, the count stops growing, or the repair limit is answered `debt`.
        At the limit (the cap is spent) or with no count the loop does not break in silence: the seam asks once per (test, count)
        and goes on by the person's answer (`s7_limit`, t-698 §4.4) - `round` runs exactly one more round, `debt` ends this test's
        loop with the failure recorded. The loop dispatches nothing at a count it cannot read (no round is guessed). The way it ends is
        recorded for this life (`s7_rows`), so a later entry never repairs the test again."""
        case = str(row.get("case") or "").split("#")[0].split("::")[0]
        test, spent = self.s7_test_name(row), None
        import s7_reorder
        reorder = s7_reorder.wants_reorder(row)
        # RD1-9b: whether the critic had REJECTED a test of this case is read BEFORE any round (the author's patch may rewrite the row)
        # and kept in the row's record, so a restart between the author and the critic still knows it (AR-25). Reorder has its own review.
        kept = (((self.state.get("s7_rows") or {}).get(life) or {}).get(ident) or {}) if life else {}
        was_rejected = False if reorder else (bool(kept["was_rejected"]) if "was_rejected" in kept else self.s7_was_rejected(case))
        if not reorder and "was_rejected" not in kept:
            self.s7_mark(life, ident, was_rejected=was_rejected)
            if was_rejected and not life:
                print(f"S7: {test} - no life: the repair review mark lives only in this run")
        if not reorder and self.s7_green_outside(life, ident, row, test, case, was_rejected):      # a reorder round's author digest is never read as repaired
            return
        while True:
            # the window's rounds are the controller's count, re-read every pass (B-007): the S7 repair
            # shares the cap with the S5 rounds of the same window, and a restart forgets nothing
            budget = self.budget_or_none("S5", "qa-automator", [case] if case else [])
            counted, cap = (budget or {}).get("counted"), (budget or {}).get("cap")
            owed = None
            if not self.repair_countable(budget) or counted >= cap:
                owed = self.s7_limit(test, ident, tests, bound, case, budget, life)      # the person's answer for this test at this count, or the question
                if owed.get("token") != "round" or owed.get("executed"):
                    print(f"S7: {test} - the person's answer `{owed.get('token')}` for this count is used; no further repair is dispatched")
                    self.s7_mark(life, ident, outcome="debt" if owed.get("token") == "debt" else "no_progress")
                    break
            elif spent is not None and counted <= spent:
                print(f"S7: {test} - the controller did not count the round just run ({counted} of {cap}); stopping the repairs of this test")
                self.s7_mark(life, ident, outcome="no_progress")
                break
            spent = counted
            if reorder:
                end = self.s7_reorder_turn(row, test, case, counted, cap, owed, life, ident)
                if end in ("repaired", "no_progress"):
                    self.s7_mark(life, ident, outcome=end)
                if end != "retry":
                    break               # "owed": the round never started, the person's round stays owed and nothing is marked
                continue                # one more round within the shared cap (the count decides; a round that was not counted stops above)
            digest = self.s7_round(row, test, case, counted, cap, owed, life, ident)
            import role_digest
            states = {r["state"] for r in role_digest.parse(digest).get("rows") or []}
            if states & {"green", "passed", "fixed"}:
                if not was_rejected:
                    self.s7_mark(life, ident, outcome="repaired")
                    break
                # position: the review comes AFTER the green author and BEFORE `repaired`; a test the critic rejected is never
                # `repaired` without the critic's word (RD1-9b)
                end = self.s7_review_repair(row, test, case, life, ident)
                if end in ("repaired", "no_progress"):
                    self.s7_mark(life, ident, outcome=end)
                    break
                continue                # "retry": one more round within the shared cap; the top meets `s7_limit` at the cap

    def s7_was_rejected(self, case: str) -> bool:
        """Did the critic REJECT any test of this case (`ledger.is_rejected`, the one reading) in the manifest as it stands now? An
        unreadable manifest or an empty case is False and says so: the review is then skipped, and RD1-9a's `blocked` still holds the
        rejected row out of `pass` (FR-59). `"REJECTED"` is not the critic's word: False."""
        try:
            import contract
            import ledger
            if not case:
                print("S7: a repair of a row with no case - the critic's earlier verdicts are not looked up")
                return False
            manifest = _read_json(self.task_root / "work/automation-manifest.json")
            return any(ledger.is_rejected(e) for e in contract.entries_for_case(contract.manifest_tests(manifest), case))
        except Exception as exc:
            print(f"S7: {case} - the manifest could not be read ({type(exc).__name__}: {exc}); no repair review for it")
            return False

    def s7_review_repair(self, row: dict, test: str, case: str, life: str, ident: str) -> str:
        """The critic's review of ONE repaired test the critic had rejected (RD1-9b; reason `S7 repair review: <test>`, cause
        `test_defect`, the cap is the window's). The round id goes into the record as `review_round` - NOT `round`, which is the
        author's (a critic's id there would read as a not-green digest and start another author round). The outcome is read through
        `s7_reorder_outcome` and so through `route_of` (AR-13). `ReworkRefused` at the spent cap returns `retry` (the loop's top meets
        `s7_limit`: a question to the person, no new stop, AR-17); any other refusal is raised, S7 stays open."""
        import s7_reorder
        try:
            digest, _next = self.rework("S5", "qa-code-critic", [case] if case else [], s7_reorder.REPAIR_REVIEW_REASON.format(test=test), cause="test_defect",
                                        on_request=lambda rid: self.s7_mark(life, ident, review_round=rid), extra=self.S5_CRITIC_BRIEF)
        except ReworkRefused:
            # t-593 F-5: the controller keeps a ledger and a cap PER ROLE (`budget_scope`), so the refusal of the critic's pass is
            # judged on the critic's own count as well as the author's: either one spent (or unreadable) is the cap, and `retry` goes
            # back to the loop (the author's rounds then reach the limit question); a refusal at neither is raised
            for role in ("qa-automator", "qa-code-critic"):
                budget = self.budget_or_none("S5", role, [case] if case else [])
                if not self.repair_countable(budget) or budget["counted"] >= budget["cap"]:
                    print(f"S7: {test} - the controller refused the repair review at the repair cap ({role}); the limit question decides")
                    return "retry"
            raise
        return self.s7_reorder_outcome(digest, test, case, what="repair review")

    def s7_reorder_turn(self, row: dict, test: str, case: str, counted: int, cap: int, owed: dict | None, life: str, ident: str) -> str:
        """One turn of a `reorder` test's loop and how it ended: `repaired` (the critic approved; the carried row is marked fixed -
        the one writer of that field, AR-14), `no_progress`, `retry` (one more round within the shared cap) or `owed` (the round never
        started and the person's `round` was taken back: the loop stops with nothing marked, so the person's round is still owed on
        the next entry). The author's digest is NEVER read as `repaired`: the round's outcome is `finish` (code) and the critic's review."""
        import s7_reorder
        try:
            digest = self.s7_round(row, test, case, counted, cap, owed, life, ident)
        except s7_reorder.ReorderRefused as exc:
            print(f"S7: {test} - the reorder round is not carried: {exc}")
            if exc.kind == "green":
                return "no_progress"
            return "owed" if owed and not owed.get("executed") else "retry"
        end = self.s7_reorder_outcome(digest, test, case)
        if end == "repaired":
            s7_reorder.mark_fixed(self.task_root, ident)
        elif end == "retry":
            s7_reorder.send_back(self.task_root, ident)      # the carried round was judged: it is never resumed as unjudged
        return end

    def s7_reorder_outcome(self, digest: str, test: str, case: str = "", what: str = "reorder") -> str:
        """How the critic's review of a reorder round ends it (and, with `what="repair review"`, the review of a repaired test the
        critic had rejected, `s7_review_repair`; only the printed words differ): `repaired`, `retry` (the review sends the window back to its author
        within the cap) or `no_progress` (a halting verdict, an `unverified` or `rejected` row on an approving verdict, a verdict this
        code does not know, a close over a seam reason). The review is read THROUGH `route_of` - the ONE reader of the critic's
        form for the S5 loop, the seam's gate and the close predicate (AR-13): `test_defect` / `mechanical` -> retry, a `close` over
        the spent cap (`cap`) -> retry too (the loop then meets the limit question, `s7.repair_limit`: another round or the limit
        answer, never a silent stop), any other `close` with a `code` (budget unknown, nobody's round) -> no_progress, a `close`
        without one and with no `rejected` row -> repaired. ERROR DIRECTION: only a
        clear approval repairs; a doubt stops the test, and the debt stays in the triage row (FR-59)."""
        import repair_route
        import role_digest
        thing, done = ("reorder", "reordered") if what == "reorder" else ("repair", "repaired")      # the default words stay byte for byte
        parsed = role_digest.parse(digest)
        if role_digest.is_halting(digest):
            print(f"S7: {test} - the critic of the {thing} round cannot go on; the round is stopped")
            return "no_progress"
        states = {r["state"] for r in parsed.get("rows") or []}
        if "unverified" in states:
            print(f"S7: {test} - the critic could not verify the {done} test; the round is stopped")
            return "no_progress"
        verdict = str((parsed.get("header") or {}).get("verdict") or "")
        if verdict not in ("ok", *repair_route.SEND_BACK):
            print(f"S7: {test} - the critic's review ({verdict or 'no verdict'}) does not approve the {thing}; the round is stopped")
            return "no_progress"
        route, _form = self.route_of(digest, self.budget_or_none("S5", "qa-automator", [case] if case else []))
        if route["action"] in ("test_defect", "mechanical"):
            print(f"S7: {test} - the critic sent the {thing} back ({route['reason']}); one more round")
            return "retry"
        if route["code"] == "untyped":      # F4 (e): no round on a cause nobody wrote; the debt stays in the triage row
            print(f"S7: {test} - the critic sent the {thing} back without a typed finding; the round is stopped")
            return "no_progress"
        if route["code"] == "cap":
            print(f"S7: {test} - the critic sent the {thing} back and the repair cap is spent; the limit question decides")
            return "retry"          # the loop's top meets counted >= cap: `s7_limit` asks the person (spec 5.7 p.4), never a silent stop
        if route["code"] or "rejected" in states:
            print(f"S7: {test} - the critic's review ({route['reason'] if route['code'] else 'a rejected row'}) does not approve the "
                  f"{thing} and no further round runs; the round is stopped")
            return "no_progress"
        return "repaired"


    def s7_green_outside(self, life: str, ident: str, row: dict | None = None, test: str = "", case: str = "", was_rejected: bool = False) -> bool:
        """E12: a round of this life that finished OUTSIDE the loop (a relaunch, `wait_existing_job`): its dispatch id was recorded
        before it started (`s7_round`); when the controller accepted it and its saved digest is green, the test is repaired. A
        relaunch gets a new id, so it is `not green` here - one more round below the cap, the question at it. RD1-9b: a test the
        critic had rejected (`was_rejected`) is repaired only by the critic's word. (a) A review of this life already ACCEPTED
        (`review_round`) is read once and decides; `retry` clears the mark and the loop goes on to the author (the read review is
        never read twice). (b) Else a green accepted author round leads to the review, not to `repaired`. A `review_round` that was
        not accepted is a new entry: a green `round` leads to a NEW review (a relaunch gets a new id)."""
        kept = (((self.state.get("s7_rows") or {}).get(life) or {}).get(ident) or {}) if life else {}
        review = str(kept.get("review_round") or "")
        if review and ((self.controller_state().get("dispatches") or {}).get(review) or {}).get("status") == "accepted":
            end = self.s7_reorder_outcome(self.saved_done(review), test, case, what="repair review")
            if end == "retry":
                self.s7_mark(life, ident, review_round="")
                return False
            self.s7_mark(life, ident, outcome=end)
            return True
        rid = str(kept.get("round") or "")
        if not rid or ((self.controller_state().get("dispatches") or {}).get(rid) or {}).get("status") != "accepted":
            return False
        import role_digest
        states = {r["state"] for r in role_digest.parse(self.saved_done(rid)).get("rows") or []}
        if not states & {"green", "passed", "fixed"}:
            return False
        if was_rejected:
            print(f"S7: the round {rid} finished green outside the loop; the critic reviews the repaired test")
            end = self.s7_review_repair(row or {}, test, case, life, ident)
            if end == "retry":
                return False
            self.s7_mark(life, ident, outcome=end)
            return True
        print(f"S7: the round {rid} finished green outside the loop; the test needs no further round")
        self.s7_mark(life, ident, outcome="repaired")
        return True

    def s7_round(self, row: dict, test: str, case: str, counted: int, cap: int, owed: dict | None, life: str = "", ident: str = "") -> str:
        """One S7 repair round of `test` (the author on its window); returns the author's digest. `owed`: the person's answer `round`
        at the repair limit - marked executed BEFORE the dispatch (a crash costs one round, never two), and taken back when the
        controller refused to START the round (no role ran, `last_dispatch` is unchanged): the person's round is then still owed
        (t-760 row 3, the same shape as `stage_S5`). The round's dispatch id is recorded for (life, test) the moment `rework`
        has it (N9), so a round that finishes outside the loop is found on re-entry (`s7_green_outside`)."""
        before = getattr(self, "last_dispatch", "")
        if owed:
            owed["executed"] = True
            self.save_state()
        import s7_reorder
        import s5_precheck
        if s7_reorder.wants_reorder(row):
            return self.s7_reorder_round(row, test, case, ident or self.s7_ident(row), owed, life, before)
        try:
            digest, _next = self.rework("S5", "qa-automator", [case] if case else [],
                                        f"{s5_precheck.S7_FIX_PREFIX}: {test} — verdict {row.get('verdict')}", cause="test_defect",
                                        on_request=lambda rid: self.s7_mark(life, ident, round=rid),
                                        extra=[f"Fix: {test} — verdict {row.get('verdict')}, mechanism "
                                               f"{row.get('mechanism') or 'n/a'} (FLAKY only)",
                                               f"triage.json: qa-factory/artifacts/{self.task}/work/triage.json · "
                                               f"automation-manifest.json: qa-factory/artifacts/{self.task}/work/automation-manifest.json",
                                               f"Round: {counted + 1} of {cap}. Retry annotations and sleeps are forbidden; the "
                                               "Then-lines before and after your fix must match. Re-run only the failed "
                                               f"test - `run_suite.py --mine {case or '<CASE>'} --node-id <test> --purpose "
                                               "repair_verify`; FLAKY confirmation per s7.md (at most 3 "
                                               "flaky_diagnostic runs, S7)."])
        except ReworkRefused:
            if owed and getattr(self, "last_dispatch", "") == before:
                owed["executed"] = False
                self.save_state()
            raise
        return digest

    def s7_rejudge_round(self, row: dict, ident: str, life: str) -> None:
        """One S7 re-judge round of a manual check the analyst found misread (HF8-19): the runner judges the SAME captures again
        (`manual_evidence.py rejudge`, nothing is captured again) through `rework` of S6 on the one case, inside the open S7 - the
        way back into S7 is this function returning (`rework` is synchronous; the stage `completed` S6 stays so, `set_stage` is
        monotonic). The result is not read from the digest: `s7_close` -> `finalize_task` -> `fresh` judge the new record.
        THE LIMIT (not the controller's: these rounds are `reviewer_error` rounds, which spend none of the controller's repair cap, though
        `qa-runner` is a `REPAIR_LOOP_ROLES` member since X7-6c; the cap that counts is the consumer's `test_defect` rounds):
        `repair_cycles` rounds per (case, ROOT of the attempt), counted in `state["s7_rejudge"]` ACROSS lives - a new analyst
        life is a new triage, not a new dispute over the same captures; a re-capture is a new attempt and counts from zero. At
        the limit no round and no question: `outcome="limit"`, the red stands (`failed:RUNNER_MISREAD_EVIDENCE`, `no`, owner the
        factory, FR-59). The count is written the moment `rework` has the dispatch id (a crash costs one round, never two)."""
        from runtime_policy import DEFAULT_LIMITS
        if self.s7_outcome(life, ident):
            return
        case = str(row.get("case") or "").strip()
        mine = ((self.state.get("s7_rows") or {}).get(life) or {}).get(ident) if life else None
        rid = str((mine or {}).get("round") or "")
        if rid and ((self.controller_state().get("dispatches") or {}).get(rid) or {}).get("status") == "accepted":
            print(f"S7: the re-judge round {rid} of {case} finished outside the loop; the check needs no further round")
            self.s7_mark(life, ident, outcome="rejudged")
            return
        attempt = re.sub(r"-r\d+$", "", str(row.get("attempt_id") or "").strip())
        key = f"{case}|{attempt}"
        spent = [str(x) for x in ((self.state.get("s7_rejudge") or {}).get(key) or [])]
        limit = DEFAULT_LIMITS["repair_cycles"]
        if len(spent) >= limit:
            print(f"S7: {case} - the runner has judged this check again {len(spent)} times; it stays failed and the factory's reason says so")
            self.s7_mark(life, ident, outcome="limit")
            return
        block = row.get("contradiction") if isinstance(row.get("contradiction"), dict) else {}
        command = (f"python \"${{CLAUDE_PLUGIN_ROOT}}/scripts/manual_evidence.py\" rejudge --task-root \"{self.task_root}\" --case {case}"
                   + (f" --of-attempt {attempt}" if attempt else "")
                   + " --result <pass|fail|inconclusive> --actual \"<what the captures show>\" --then-quote \"<n>=<words>\" "
                     "--reason \"<why the first verdict was wrong, or why it stands>\"")

        def registered(new_id: str) -> None:
            self.state.setdefault("s7_rejudge", {}).setdefault(key, []).append(new_id)
            self.s7_mark(life, ident, round=new_id)
            self.save_state()
        # `ReworkRefused` is raised before `on_request` (nothing is counted yet) and goes up to the seam as it is: no take-back needed
        self.rework("S6", "qa-runner", [case], f"S7 re-judge: {case}", cause="reviewer_error", complete=False,
                    on_request=registered,
                    extra=["Execution kind: manual — do not capture again unless the re-judge is refused",
                           f"S7 re-judge of {case}: the failure analyst found that your verdict on attempt {attempt or 'the latest'} "
                           "contradicts the text that attempt itself captured. Read those captures again and judge them; nothing "
                           "is captured again and the check is not run again.",
                           f"Then {block.get('then')}: you said — {block.get('runner_said')}",
                           f"The analyst's quote: {block.get('quote')} (file: {block.get('evidence')})",
                           "Record your judgment, then `finalize_task.py <task root>`: " + command,
                           "You decide: the analyst's reading is an input, not an order. When the captures still support your "
                           "verdict, record it again with the same command and say why."])
        self.s7_mark(life, ident, outcome="rejudged")

    def s7_reorder_round(self, row: dict, test: str, case: str, ident: str, owed: dict | None, life: str, before: str) -> str:
        """One S7 `reorder` round of `test` (t-1508 R7), the same steps the conductor runs by hand (`phases/s7.md`, Repair): the
        snapshot (`s7_reorder.start`), the author's rework (reason `S7 reorder: <test>`, cause `test_defect` - the cap is the
        window's, shared with the S5 rounds), `s7_reorder.finish` (shape of the edit, red run, carried row) and the critic of that
        one test (reason `S7 reorder review: <test>`). Returns the CRITIC's digest; `ReorderRefused` from `start` / `finish` goes
        to the loop, which stops on `green` and counts anything else. `ReworkRefused` is raised as in any round (the plan is not
        rolled back without a decision). A round already carried and not yet judged (the driver fell after `finish`) goes straight
        to its critic - no second author over the moved bytes (AR-25). A refusal BEFORE any role ran (`start`, or the author's
        registration) takes the person's owed round back, as in `s7_round` (F10)."""
        import s7_reorder
        cases = [case] if case else []

        def took_back() -> None:
            if owed and getattr(self, "last_dispatch", "") == before:
                owed["executed"] = False
                self.save_state()
        try:
            done = s7_reorder.carried_round(self.task_root, ident, self.project)
            started = {} if done else s7_reorder.start(self.task_root, ident, self.project)
        except s7_reorder.ReorderRefused:
            took_back()
            raise
        if done is None:
            red = s7_reorder.red_thens(self.task_root, row, ident)
            try:
                self.rework("S5", "qa-automator", cases, s7_reorder.AUTHOR_REASON.format(test=test), cause="test_defect",
                            on_request=lambda rid: self.s7_mark(life, ident, round=rid),
                            extra=s7_reorder.author_brief(test, s7_reorder.moved_thens(row), red))
            except ReworkRefused:
                took_back()
                raise
            done = s7_reorder.finish(self.task_root, ident, self.project)
        print(f"S7: {test} - the reorder is carried to attempt {done['attempt']}; the critic reviews that one test"
              + (f" (snapshot {started.get('snapshot')})" if started.get("snapshot") else ""))
        digest, _next = self.rework("S5", "qa-code-critic", [done["case"]] if done.get("case") else cases, done["critic"]["reason"],
                                    cause="test_defect", extra=done["critic"]["brief"])
        return digest

    # --- the S7 repair limit through the one seam (C1-5b2, t-698 §4.4) ----------------------------------------------------------
    # One question per (test, count, life): the answer is kept under a slot of that triple (`state["repair_limit_s7"]`, apart from the S5
    # windows' `repair_limit`, whose readers match a window by its cases). The question is the S5 one's machinery (`repair_limit_raise`,
    # `repair_limit_person`, `_answer_repair_limit`); the S7 answers are `round` / `debt` / `stop` - no `fixed` (re-running a test after
    # the person's own edit is S6's run, FR-9: it has no executor here) and no `review` (the person is not offered a review; a repair of a
# test the critic had rejected ends in a critic review of that one test, run by the loop itself: `s7_review_repair`).
    @staticmethod
    def s7_slot(ident: str, life: str, counted) -> str:
        """The slot of one test of one life at one count (`unknown` for no count): free of colons, so it can ride as the question's dispatch."""
        return ("S7-" + hashlib.sha256(f"{ident}|{life}".encode("utf-8")).hexdigest()[:12] + "-"
                + (str(counted) if isinstance(counted, int) else "unknown"))

    def s7_limit(self, test: str, ident: str, tests: list, bound: bool, case: str, budget, life: str) -> dict:
        """The person's answer for this test in this life (the kept record), or the question: ONCE per (test, life, count) - an answer
        recorded for the slot is returned on every later loop turn and every later entry, and nothing is asked again. A `debt` is FINAL
        for its test within a life: it is found before the count is read, so a sibling that moves the shared count never re-asks it.
        `ident`: the triage row's own name (`s7_ident`), the key of the record and of the slot. Under life `""` no record is trusted."""
        slot =self.s7_slot(ident, life, budget["counted"] if self.repair_countable(budget) else None)
        kept = list((self.state.get("repair_limit_s7") or {}).values()) if life else []
        found = next((r for r in kept if isinstance(r, dict) and r.get("life") == life and r.get("ident") == ident
                      and r.get("token") == "debt"), None) \
            or next((r for r in kept if isinstance(r, dict) and r.get("dispatch") == slot and r.get("life") == life), None)
        if found:
            return found
        ask = self.s7_limit_facts(slot, test, ident, tests, bound, case, budget, life)
        if ask["code"] == "cap" and not ask["passes"]:
            self.repair_older_controller("S7", slot, budget, "still fail after their repairs")
        self.repair_limit_raise(ask)

    def s7_limit_facts(self, slot: str, test: str, ident: str, tests: list, bound: bool, case: str, budget, life: str) -> dict:
        """The facts of the S7 question (the shape `repair_limit_person` and `_answer_repair_limit` read): the cap is spent (`cap`,
        with `round`) or the count cannot be read (`unknown`, no `round`: no round is started blind). The lead names the test and the
        count in words (A6: no id, no cause token). `tests` are the ledger refs of the debt entry; `bound` says whether a test of the
        plan answers this row (the `debt` words promise nothing about the report when none does, N5)."""
        countable = self.repair_countable(budget)
        counted, cap = (budget["counted"], budget["cap"]) if countable else (None, None)
        head, where = (f"For {case}: ", "the tests of this case") if case else ("", "this test")      # `For TC-1:` explains the id (human-questions.md)
        if countable:
            opening = (f"{head}{test} still fails in the test run, and the failure is in the test itself. The test writer has already "
                       f"repaired {where} {counted} times, the rounds after the critic's review included; the factory's limit for "
                       f"that is {cap} rounds, and it is used up.")
        else:
            opening = (f"{head}{test} still fails in the test run, and the failure is in the test itself. The factory could not count "
                       f"how many repair rounds the test writer has already had on {where}, so it will not start another on its own; "
                       "starting a round is left out of the answers below.")
        passes = self.repair_passes(budget) if countable else None
        return {"stage": "S7", "dispatch": slot, "cases": [case] if case else [], "tests": list(tests), "name": str(test), "life": life,
                "ident": ident, "bound": bound,
                "key": "s7.repair_limit", "offer": ["round", "debt", "stop"] if countable else ["debt", "stop"],
                "code": "cap" if countable else "unknown", "lead": opening + "\n\nWhich of these should happen?", "cause": "",
                "passes": passes or {}, "counted": counted, "cap": cap, "round_counted": counted, "round_cap": cap, "reason": "",
                "by_cause": (budget.get("by_cause") if isinstance(budget, dict) else None) or {}}

    def stage_S8(self) -> None:
        import acceptance
        # X7-6b: the analyst's last dispatch when S7 awaits its consumer (the one reader, AR-13). POSITION: the scribe is let in by the controller
        # while S7 awaits; a verdict (or a scribe that already worked) left by a restart is settled BEFORE the scribe is dispatched again.
        awaiting = acceptance.awaits_acceptance(self.controller_state(), "S7", self.pipeline())
        if awaiting and self.consumer_settled("S7", self.controller_state(), awaiting, True):
            return
        root = f"qa-factory/artifacts/{self.task}"
        # The three scripts, in this order (a later one reads an earlier one's product; a G refusal in the middle makes `retry` run the
        # WHOLE step again, E1). L1: check_traceability writes nothing (M1, t-1214: `walk` only reads; `main` only prints), and its exit 1
        # is a legitimate "gaps found" the decisions that need it (gate_preflight, check_delivery) read from the register themselves.
        # remains: L1 - a read-only check whose "no" (exit 1: gaps found) is an answer, never a conductor call (E2); nothing waits on its exit
        code, out = self.py("check_traceability.py", root)
        print(f"check_traceability.py: exit {code} — " + (out.splitlines()[-1] if out else ""))
        # G4: `work/ledger.json` and `work/ledger.md` are inputs of the scribe and of check_delivery; ledger.py exits 1 for "no such
        # directory" or a crash, never for a "no" (ledger.py:1078-1090)
        try:
            code, out = self.py("ledger.py", root, check=True, expect="work/ledger.json and work/ledger.md written")
        except Refusal as refusal:
            refusal.retry = self.stage_S8           # E1: the WHOLE step again - a later script reads this one's product
            raise
        print(f"ledger.py: exit {code} — " + (out.splitlines()[-1] if out else ""))
        # L2 / F4 (M2, t-1214: check_delivery.py REWRITES work/ledger.json, ledger.md, delivery-summary.* and evidence/index.json with the
        # verdict, and the scribe reads them): the record is read through `delivery_verdict.word_of`, never the exit code - 1 is a legitimate
        # `no` / `after_checks` (E2). A record with no readable word, a crash or a timeout (124) established nothing: a G refusal (the
        # factory's own) BEFORE the scribe reads a ledger the check did not write.
        code, out, word = self.delivery_record(root)
        print(f"check_delivery.py: exit {code} - the word it printed: {word or 'none'}")
        if word is None:
            raise gate_refusal("check_delivery.py", code, out, "work/ledger.json written with the delivery verdict (a readable word)",
                               retry=self.stage_S8)
        complete, extra = True, self.role_lines("S8", "qa-doc-scribe")
        if awaiting:
            # X7-6b. POSITION: the record is written from the scribe's FINISH, BEFORE the controller accepts it as S8 work, and never by the
            # analyst's own finish. `True` (today's close of S8) is the scribe's own completion on an accept.
            complete = self.consumer_completion("S7", True)      # the repair budget is read only if the verdict is a reject (B1)
            extra += [f"You also accept or return the analyst's handoff ({awaiting}): the verdict is `header.verdict` of your form (`ok` accepts it; "
                      "`concerns` sends it back and needs the section `stage_acceptance`), and `inputs_read` names the analyst's form "
                      "work/handoffs/" + awaiting + ".yaml. A concern about the report itself belongs in `unresolved`."]
            extra += self.s7_places_scribe_line()        # t-1991 U3a: settled / unsettled places, with the source of each expectation
        self.run_role("S8", "qa-doc-scribe", complete=complete, extra=extra)
        if awaiting and self.consumer_settled("S7", self.controller_state(), awaiting, True, ran=True):
            return          # the analyst repairs in a fresh context; the scribe's report is stale and is written again after the new accept
        # t-204 F6 (R-212.1): the code-owned blocks of the report are rendered right here, once the scribe has
        # returned and BEFORE gate B is asked (the next boundary reads the report to build its packet), so the
        # person reads a code-checked report and not the scribe's own arithmetic. POSITION INVARIANT: after the
        # scribe's finish and before `self.gate("B")` - what the rebuild never touches is the bug reporter,
        # which runs after gate B and has its own boundary. Its refusal or crash is ONE printed line and the
        # story goes on (P1, FR-3): S9's exit checks the report itself and names the doors. A story whose S8
        # ran before this change has no markers; its first `--write` converts the report (P7).
        self.rebuild_report()
        # RD1-20: the MR description quotes the report's "Left with you" section, and the scribe and the rebuild above have just
        # changed it - the summary is written again here, over the report as it stands now, whether or not the rebuild held (the
        # summary is its own record). POSITION INVARIANT: after the rebuild, so the quoted section is the one the person reads.
        # remains: a failure here is one line, S8 goes on and S9 writes the summary again
        code, out = self.py("delivery_summary.py", "--task-root", str(self.task_root))
        if code:
            print(f"delivery summary not rewritten after the report (exit {code}); S9 writes it again: "
                  + ((out or "").splitlines() or ["no output"])[-1][:160])

    def recompute_verdict(self) -> str:
        """The delivery verdict, computed again from what the person's gate B answers recorded (t-305 N8, F5, N-4), and the
        report brought up to it, BEFORE any act the verdict gates. The order is the position invariant - no verdict-gated act
        (the bug reporter, the MR, an outward write) reads a word, a head or a "Left with you" section older than the person's
        answers:
          (1) the answers were recorded at `take_answer` (`take_stand_gap_answers`: the typed waivers);
          (2) the three scripts of S8 run again over the story as it now stands (the ledger, the word W2, `left_items`);
          (3) `report_facts --write` renders the code-owned blocks from W2 and the typed items - the head, and the block
              "Added after gate B (from your answers)", one line per item an answer of theirs left with them;
          (4) `report_facts --check` must pass (it does by construction for the new items): a failure is a finding of the
              factory with the scribe's door, and the delivery does NOT run;
          (5) the head is the one `--write` just rendered (with the "Changed since gate B" notice when W1 differs);
          (6) the MR description is rebuilt from the report as it now stands (`delivery_summary`).
        Returns W2: `yes`, `after_checks`, `no`."""
        root = f"qa-factory/artifacts/{self.task}"
        # O5 (C1-7c), the two kinds of S8's loop as C1-7b built them (L1 and G4), and the same order (a later script reads an earlier
        # one's product). L: check_traceability writes nothing (M1, t-1214: `walk` only reads, `main` only prints), so no product is left
        # unwritten by it; its exit 1 is a legitimate "gaps found" that the decisions needing it (gate_preflight, check_delivery) read
        # from the register themselves; with no artifacts directory it prints one line and exits 1 and the ledger step below refuses.
        # remains: L - a read-only check whose "no" (exit 1: gaps found) is an answer, never a conductor call (E2); nothing waits on its exit
        code, out = self.py("check_traceability.py", root)
        print(f"gate B: check_traceability.py: exit {code} — " + (out.splitlines()[-1] if out else ""))
        # G: `work/ledger.json` / `ledger.md` are what `check_delivery` (the word W2) and the report read; ledger.py exits 1 for "no such
        # directory" or a crash, never for a "no" (ledger.py:1078-1090). A failed ledger is a `Refusal`; the delivery does NOT go on over
        # the ledger the answers did not rewrite. `retry` runs the WHOLE step again (E1): the caller of this function is `stage_S9`
        # (through `after_gate_B`), and a retry that reran only the ledger would end the step before the word, the report and the
        # delivery were reached
        try:
            code, out = self.py("ledger.py", root, check=True,
                                expect="work/ledger.json and work/ledger.md rewritten with the verdict row over the answers recorded at gate B")
        except Refusal as refusal:
            refusal.retry = self.stage_S9
            raise
        print(f"gate B: ledger.py: exit {code} — " + (out.splitlines()[-1] if out else ""))
        # F4 (FR-59): the verdict is the word the check PRINTS (`--json`), never its exit code: the check exits 1 for `no`,
        # for `after_checks` and on a crash alike. A check that crashes, times out or prints nothing parseable has
        # established nothing: the delivery does NOT go on over the word the ledger held before the answers (the ledger is
        # left as it was), and the driver stops with the factory's own reason in words.
        word = self.delivery_check_word(root)
        if not (self.task_root / "test-report.md").is_file():
            # nothing is stale where nothing is written: S8's own exit owns "there is a report" (FR-41: said, not silent)
            print("gate B: there is no test-report.md to bring up to the new verdict")
            return word
        self.rebuild_report()
        code, out = self.py("report_facts.py", "--task", self.task, "--check")
        lines = [line.strip() for line in (out or "").splitlines() if line.strip()]
        if code:
            if self.delivery_declined():        # the person said `no delivery` to this very question: nothing goes out, nothing asks again
                print("gate B: the report does not match your gate B answers; the delivery was declined, so the report stays as it is")
                return word
            # remains: the site's own closed question (`s8.report_match`: `no delivery` / `stop`, each with an executor in `_take_report_match_answer`)
            raise self.report_match_person(lines)
        # O6 (C1-7c, kind G): the MR description (`work/delivery-summary.json` / `.md`) is what the delivery sends out; the ledger step above
        # wrote it already (ledger.py:1065 `write_delivery_summary`) and this call writes it again over the report as it now stands. A
        # non-zero exit is a `Refusal`: the delivery does not go out over a description the answers did not rewrite. `retry`: the whole step
        try:
            self.py("delivery_summary.py", "--task-root", str(self.task_root), check=True,
                    expect="work/delivery-summary.json and work/delivery-summary.md rewritten from the report as it now stands (the MR description)")
        except Refusal as refusal:
            refusal.retry = self.stage_S9
            raise
        return word

    def delivery_declined(self) -> bool:
        """Did the person end the delivery (`no delivery`, `_decline_delivery`)? The two checks of S9 that would ask again do not."""
        return (self.state.get("delivery") or {}).get("action") == "declined_by_person"

    def report_match_person(self, lines: list) -> Person:
        """`s8.report_match` (C1-6c, S8 of the census): the report does not match the answers recorded at gate B. The factory's own gap
        reaches the person as `no delivery` / `stop` only, never as a choice to own the gap (A10, FR-3). `rebuild` is NOT offered: the
        controller refuses the scribe's rework it would run (see the handoff, Q1) and an option whose executor is refused is never
        offered (FR-9). The mismatch lines are the lead; the whole list is the details file. No command in the text (J3)."""
        shown = "; ".join(" ".join(line.split())[:200] for line in lines[:6])
        lead = ("The report does not match what your gate B answers recorded, so nothing was delivered: " + shown + ". This is the "
                "factory's own gap, not a choice of yours.\n\nWhat I need from you is one of these:")
        text = self.closed_question("s8.report_match", lead, [
            {"answer": "no delivery", "token": "no delivery", "says": "end the delivery here; nothing is sent out and the report stays as it is"},
            self.STOP_OPTION])
        return Person("report_match", text, "S8", details="\n".join(lines))

    # a script that must say something before the story can go on, and the seconds it has to say it (see `py`)
    PY_TIMEOUTS = {"check_delivery.py": 600}

    def delivery_record(self, root: str) -> tuple:
        """THE read of the delivery verdict (C1-7b fix round, F-1, FR-14; AR-13, AR-28): run `check_delivery.py --json` and return
        `(exit code, output, word)`. The word is the one the check PRINTED (`yes`, `after_checks`, `no`), read by
        `delivery_verdict.word_of` from the record `json_record` parsed - never from the exit code: exit 1 with a readable `no` is the
        word `no` (E2, a legitimate answer). The word is None - the caller refuses, a word is never guessed and never a pass - when
        the exit is outside {0, 1} (a crash, a usage error, 124 the timeout), there is no record, the record is unreadable or it holds
        no word of the three. It raises nothing itself (`py` is called without `check`); each caller words its own refusal."""
        import delivery_verdict as DV
        code, out = self.py("check_delivery.py", root, "--json")
        doc, _after = json_record(out)
        word = DV.word_of(doc) if code in (0, 1) and isinstance(doc, dict) and "delivery_verdict" in doc else None
        return code, out, (word if word in ("yes", "after_checks", "no") else None)

    def delivery_check_word(self, root: str) -> str:
        """Run `check_delivery.py --json` and return the word it PRINTED (`yes`, `after_checks`, `no`) - read by
        `delivery_record` (the one reader; C1-7b F-1), never from the exit code. Raises `Person` (`s8.delivery_check`: the
        driver asks, nothing is delivered, the ledger keeps its word, ONE defect is filed; C1-6c) when the check crashes, times
        out, prints nothing parseable or prints a record with no readable word (FR-59: a gate does not decide on an unknown). The
        text is the factory's own gap in words: no script name, flag or exit code in it; the operator's log line carries those."""
        code, _out, word = self.delivery_record(root)
        print(f"gate B: check_delivery.py: exit {code} - the word it printed: {word or 'none'}")
        if word is None:
            if self.delivery_declined():        # `no delivery` was the answer: a check that cannot answer is no pass (FR-59), and the verdict is `no`
                print("gate B: the delivery check could not answer; the delivery was declined, so the verdict is `no`")
                return "no"
            # C1-6c (S9 of the census): the factory's own gap is ONE defect (owner: factory) and a closed question, never a promise that
            # nobody carries out. A crash is never a pass (AR-28): nothing is delivered until the check answers or the person ends it.
            self.file_defect(self.boundary, "owner: factory — the delivery check could not say whether the story is ready after the "
                                            f"person's gate B answers (exit {code}, the word it printed: {word or 'none'})")
            lead = ("The delivery check could not say whether the story is ready after your answers (it stopped, or printed nothing the "
                    "factory can read), so nothing was delivered and the verdict the story had before your answers stands unchanged. "
                    "This is the factory's own gap, recorded as one, not a choice of yours.\n\nWhat I need from you is one of these:")
            # remains: the site's own closed question (`s8.delivery_check`: `retry` / `no delivery` / `stop`, each with an executor in `_take_delivery_check_answer`)
            raise Person("delivery_check", self.closed_question("s8.delivery_check", lead, [
                {"answer": "retry", "token": "retry", "says": "the check runs again now"},
                {"answer": "no delivery", "token": "no delivery", "says": "end the delivery here; nothing is sent out"},
                self.STOP_OPTION]), "S8")
        return word

    def after_gate_B(self) -> None:
        """What the person decided at gate B is carried out here, order by order (t-1509, GB-1b): the bug reporter for a `bugs`
        order that is due, the delivery for an `mr` order that is due, each order settled by the controller's one producer
        (`gate_b_orders`; the reporter's accept or release settles `bugs`, `settle_order` settles `mr`). Idempotent: an order
        that is not due is not touched, and a delivery that left its mark is never run again (t-017 D3)."""
        import controller as C
        # FIRST (t-305 N8): the verdict W2, from the answers just recorded - above the reporter dispatch and `delivery`
        self.recomputed_word = self.recompute_verdict()
        state = self.controller_state()
        latest = C.latest_gate_b(state) or {}
        decision = latest if latest.get("status") == "approved" else {}
        statuses = C.gate_b_orders(state)
        if statuses.get("bugs") == C.ORDER_DUE and "bugs" not in self.gate_b_ran:
            # once per process: a reporter that ran and left its order due is not sent again by the next pass (the seam is)
            self.gate_b_ran.add("bugs")
            self.run_bug_reporter(decision)
        # HF8-22 F-2: the reporter filed after the summary above was written, so the report and the MR description still say "chosen
        # at gate B, not filed yet" about a bug that is filed. Outside the once-per-process `if`: a resume repeats it. The verdict is
        # NOT computed again (only the text over the files as they now lie), and nothing is redone once the MR is open.
        self.refresh_after_reporter()
        self.settle_mr(decision, statuses)

    def refresh_after_reporter(self) -> None:
        """The report's code-owned blocks and the MR description (`work/delivery-summary.*`) rebuilt over the bug files the reporter just
        wrote - the same two scripts `recompute_verdict` ends with, minus the verdict. A refusal of the description is a `Refusal` that
        retries the whole S9 step, as there. Nothing to do without a report, or when the delivery already left its mark."""
        if self.state.get("delivery") or not (self.task_root / "test-report.md").is_file():
            return
        self.rebuild_report()
        try:
            self.py("delivery_summary.py", "--task-root", str(self.task_root), check=True,
                    expect="work/delivery-summary.json and work/delivery-summary.md rewritten over the bug files the reporter wrote")
        except Refusal as refusal:
            refusal.retry = self.stage_S9
            raise

    def run_bug_reporter(self, decision: dict) -> None:
        """The executor of the `bugs` order. The person's word is the authority, not the draft list: at gate B of TP1-13797
        the owner ordered a bug draft for the missed UI scope while S7 had left no drafts behind. Whether anything is to be
        filed is the reporter's own judgement, and "nothing to file" is a complete answer that costs one dispatch to hear; a
        phrase list in code decides it for the person. It runs after `no delivery` too (F-7, the owner 28.10.2026: "only the
        MR"): it writes a local file and nothing is sent out (agents/qa-bug-reporter.md)."""
        drafts = [d for d in (decision.get("selected_drafts") or []) if d]
        words = str(decision.get("authorization_source") or "")
        # An experiment's reporter is told, in its own dispatch, that the tracker is not a
        # channel it may propose for (t-017 D3, FR-36): the packet the person read said so too.
        experiment = (["This run is an experiment: treat the bugs channel as markdown and write "
                       "no proposal for a tracker."] if self.no_trace() else [])
        self.run_role("S8", "qa-bug-reporter", complete=False,
                      extra=(["Chosen drafts: " + ", ".join(str(d) for d in drafts)] if drafts else
                             ["S7 left no bug drafts, so nothing is pre-chosen: read the gate-B decision "
                              "below and file exactly what the person's own words order there — a local "
                              "proposal under qa-factory/bugs, grounded in the register and the report, "
                              "submitted nowhere. If their words order no bug, file none and say so in "
                              "your digest: that is a complete answer, not a gap."]) +
                            [f"Gate B decision: {words[:2000]}",
                             "Drafts the person called not a bug are neither filed nor deleted."] + experiment)

    def settle_mr(self, decision: dict, statuses: dict) -> None:
        """The `mr` order: the ONE place it is worked out (AR-14). A decision recorded before 0.10.5 carries no orders (B6): its
        delivery runs as it always did when no mark exists, and no order is tracked. For a decision with orders the delivery runs
        only while `mr` is due and no mark exists; the mark - however it was left, also by a process that died right after it -
        is then settled (`settle_mr_from_mark`), so the delivery never runs twice."""
        import controller as C
        # Any truthy mark is "done": since t-017 D3 the driver writes it only on `continue` (or the
        # experiment's null outcome), but a mark an older driver wrote on `ask_person`/`stop` has no
        # `done` key and is still truthy - that story is not delivered a second time (conservative).
        if not isinstance(decision.get("orders"), dict):
            if not self.state.get("delivery"):
                self.delivery(decision)
            return
        if statuses.get("mr") != C.ORDER_DUE:
            return
        if not self.state.get("delivery"):
            self.delivery(decision)
        self.settle_mr_from_mark()

    def settle_mr_from_mark(self) -> None:
        """Settle the `mr` order from the delivery mark (t-1509 B5, F-11). The mark is the delivery step's own record: `mr` is the
        link or id its verdict named (a field, never searched for in the prose of `did`, FR-12). `done` only with that record;
        a delivery that opened no MR, or went nowhere (an experiment), is called off with the factory's coded reason and the
        step's one-line record; the person's `no delivery` is called off with THEIR words (FR-8). A repeat is the same answer."""
        import controller as C
        mark = self.state.get("delivery") or {}
        if not mark:
            return
        action, did = mark.get("action"), " ".join(str(mark.get("did") or "").split())
        ref = f"--ref={did[:C.SETTLE_REF_MAX] or 'the delivery mark holds no record of what went out'}"
        mr = str(mark.get("mr") or "").strip()
        if action == "declined_by_person":
            path = str(mark.get("words_file") or "")
            if not path or not Path(path).is_file():
                raise Refusal("The delivery was declined by the person, but the file with their words is gone, so the merge request "
                              "order cannot be called off with them. The conductor writes their earlier words (`no delivery` and what they "
                              f"added) to a file and calls the order off: `controller.py --task-root {self.task_root} --operation "
                              "settle_order --order mr --outcome cancelled --words-file <that file>`.",
                              title="declined_words_missing")
            args, outcome = ["--outcome", "cancelled", "--words-file", path], "cancelled"
        elif action == "nothing_outward":
            args, outcome = ["--outcome", "cancelled", "--reason-code", "no_trace", ref], "cancelled"
        elif mr:
            args, outcome = ["--outcome", "done", f"--ref={mr[:C.SETTLE_REF_MAX]}"], "done"
        else:
            args, outcome = ["--outcome", "cancelled", "--reason-code", "delivered_without_mr", ref], "cancelled"
        self.controller("settle_order", "--order", "mr", *args)
        print(f"gate B: the merge request order is {outcome} ({action or 'delivery'})")

    def person_answers(self) -> list:
        """The person's answers recorded for this story, oldest first (the project journal's
        `human_answer` events, the same source the briefs read)."""
        try:
            import brief_pack
            return brief_pack.answers_of(self.task, self.project)
        except Exception:
            return []

    def no_trace(self) -> bool:
        """Is this run an experiment that leaves no trace? The record is `pipeline.no_trace`
        (read through `external_writes.closed_by_run`, the reader every other consumer shares);
        before pipeline.json exists, S0 has only the command line to go by. A flag absent from a
        later command line never reopens what pipeline.json closed.

        The launch record (`state["launch"]["no_trace"]`, kept by S0) closes too when pipeline.json
        cannot say: unreadable, or with no `no_trace` key at all - a damaged file must not reopen
        writes (Lead's decision Q6). A key that IS there and says false is the person's way out
        (`stage_done --set no_trace=false`, FR-40) and wins over the launch."""
        if (self.state.get("launch") or {}).get("no_trace") and "no_trace" not in self.pipeline():
            return True
        if (self.task_root / "pipeline.json").is_file():
            import external_writes
            return bool(external_writes.closed_by_run(self.task_root))
        return bool(getattr(self.flags, "no_trace", False))

    def accept_no_trace(self) -> None:
        """`--no-trace` on a story that was started without it (t-017 D3, owner decision F5):
        accepted from this stage on - closing outward writes is always the safe direction - and
        said so, because what an earlier stage already sent is not undone (FR-41).

        The flag is the command line's or the launch's (kept by S0) - the launch only while
        pipeline.json has no `no_trace` key, so an explicit false (the person's way out) is not
        re-closed on every run. And a delivery already recorded as nothing outward is said to stay
        so when the run is no longer an experiment: the flag does not reopen it (Lead's decision Q7)."""
        mark = self.state.get("delivery") or {}
        if mark.get("action") == "nothing_outward" and not self.no_trace():
            print(f"{self.task}: the delivery was already recorded as nothing outward while this run was an "
                  "experiment; it is not reopened by the flag being off now")
        pipeline = self.pipeline()
        launched = bool((self.state.get("launch") or {}).get("no_trace")) and "no_trace" not in pipeline
        if not (getattr(self.flags, "no_trace", False) or launched):
            return
        if not pipeline or pipeline.get("no_trace"):
            return
        stages = pipeline.get("stages") or {}
        stage = next((f"S{i}" for i in range(10)
                      if (stages.get(f"S{i}") or {}).get("status") not in ("done", "skipped")), "S9")
        self.py("stage_done.py", "--task", self.task, "--set", "no_trace=true", "--warn",
                f"experiment from {stage} on; earlier outward writes, if any, are not undone", check=True)
        print(f"{self.task}: --no-trace accepted from {stage} on; nothing more leaves the project, "
              "and anything sent before it is not undone")
        # t-261 (FR-37): through the layout, not by hand - a project onboarded after the two-folder layout keeps its
        # journal in `records/`, an older one in `state/`, and a path the person's own config names is honoured as written.
        import runtime_paths
        journal = runtime_paths.configured(self.project, self.config.get("journal_path"), "journal.jsonl")
        sent = 0
        if journal.is_file():
            for line in journal.read_text(encoding="utf-8", errors="replace").splitlines():
                try:
                    record = json.loads(line)
                except ValueError:
                    continue
                if record.get("event") == "external_write" and record.get("task") == self.task:
                    sent += 1
        if sent:
            print(f"{self.task}: the journal already holds {sent} external_write event(s) for this story "
                  "- they went out before the flag and stay where they are")

    def outward_rule(self) -> str:
        """The delivery prompt's line about writing outward. Since t-017 D3 it follows the run's
        record and the project's own channels, instead of the fixed sentence that named one
        tracker: the channels are `config.external_writes` unless the run is closed."""
        import external_writes
        closed = external_writes.closed_by_run(self.task_root)
        if closed:
            return (f"This run is closed for outward writes ({closed}): no tracker write and no "
                    "external_writes.py.")
        ext = self.config.get("external_writes") or {}
        named = [f"{kind}={ext[kind]}" for kind in ("bugs", "cases")
                 if str(ext.get(kind) or "markdown").strip() not in ("", "markdown", "none", "file")]
        return ("A tracker is written only through external_writes.py and only for the channels "
                "config.external_writes names (" + (", ".join(named) or "none: bugs and cases are markdown")
                + "); nothing else writes to a tracker.")

    def delivery(self, decision: dict) -> None:
        self.boundary = "S8:delivery"
        # INVARIANT (t-017 D3, delta 8b): a delivery with outward effects never runs twice. (1) The
        # mark `state["delivery"]` exists only after a `continue` verdict, or after the
        # experiment's null outcome below - `ask_person` and `stop` leave none, so the person's
        # answer re-enters this step; (2) at most ONE conductor call per driver process (the
        # refusal below); (3) every call carries every earlier attempt, verbatim - including a call
        # that was recorded as started and never reported back (`in_flight`, written before the call
        # and replaced by its verdict), so a process that died inside a call is not forgotten by the
        # next one. The residual risk - a conductor that repeats a step it was told already happened,
        # or one whose interrupted call left effects nobody recorded - is held by that prompt and by
        # nothing in code, and this comment says so (FR-41): it is not a guarantee.
        if self.no_trace():
            # The null outcome (FR-23): nothing goes out, the conductor is not called, external_writes
            # does not run, and that is recorded as the delivery's own state. FIRST in the step so
            # that no line below it - the conductor, the channels - is reachable in an experiment.
            did = "nothing outward (experiment): no branch, commit, push, merge request or tracker write"
            self.state["delivery"] = {"done": True, "at": _now(), "action": "nothing_outward", "did": did}
            self.save_state()
            self.journal_run({"kind": "delivery", "outcome": "nothing_outward"})
            print(f"delivery: {did}")
            return
        calls = getattr(self, "_delivery_calls", 0)
        if calls:
            raise Refusal(
                "The delivery - the branch, the commits, the push and the Draft merge request - was "
                "already handed to the conductor once in this run, and a second hand-over in the same run "
                "could create them twice, so nothing was repeated. To go on, answer `retry`: the delivery "
                "is asked again with the record of everything that already went out, and the conductor is "
                "asked to reuse it.", title="second_delivery")
        self._delivery_calls = calls + 1
        phase = self.plugin / "skills/qa-story/phases/s8.md"
        text = phase.read_text(encoding="utf-8", errors="replace") if phase.is_file() else ""
        start = text.find("## 4. Record, then execute verbatim")
        end = text.find("## Exit", start)
        section = text[start:end] if start >= 0 else text[:6000]
        conventions = json.dumps(self.config.get("git_conventions") or {})
        vcs = json.dumps((self.config.get("adapters") or {}).get("vcs") or {})
        suffix = self.flags.branch_suffix or ""
        prompt = "\n".join([
            f"Task: {self.task}. Project root: {self.project}. Plugin root: {self.plugin}. Task root: {self.task_root}.",
            "This is the DELIVERY after gate B: the bug reporter and the scribe are done; gate B is recorded.",
            # t-305 N8 (F5): the word is the one computed AFTER the person's gate B answers were recorded; on
            # `after_checks` the Draft MR is opened and its description carries the report's "Left with you" section
            f"Delivery verdict, recomputed after gate B: {getattr(self, 'recomputed_word', None) or self.delivery_word()}",
            f"Gate B decision, verbatim: {str(decision.get('authorization_source') or '')[:1500]}",
            # What the person said AFTER the gate belongs here too: a clarification recorded
            # as a human_answer was invisible to this step, and the delivery stopped on an
            # item the person had already settled (TP1-13797, driver run 3).
            "The person's answers recorded in this story, latest last: "
            + (" | ".join(self.person_answers()[-6:]) or "none recorded"),
            f"Delivery items recorded on the decision: {json.dumps({k: v for k, v in decision.items() if k in ('selected_drafts', 'action', 'deliver_with_risks', 'mr', 'items')}, ensure_ascii=False)[:800]}",
            f"git_conventions: {conventions}. VCS adapter: {vcs}. Branch name suffix to append: `{suffix}` (none when empty).",
            "Do exactly what the decision authorizes and nothing it does not: an MR is Draft. "
            + self.outward_rule() + " Commit by explicit path allowlists.",
            "Your job here is the delivery itself, in this order and nothing else: (1) the branch named by the "
            "conventions plus the suffix, (2) the commits by the decision's allowlist, (3) the push, (4) the Draft "
            "merge request. " + DELIVERY_RULE,
            "", "## The delivery section of phases/s8.md", section.strip(),
            "", "Answer with ONE JSON line last: {\"action\": \"continue|ask_person|stop\", \"did\": \"<what went out: commits, branch, MR url>\", "
                "\"question\": \"...\", \"why_person\": \"<a class of references/" + PO.FILE_NAME + ", with ask_person>\", "
                "\"mr\":\"<the Draft MR's url or id when one was opened or already exists; empty when none>\"}"])
        earlier = list(self.state.get("delivery_attempts") or [])
        if earlier:
            # What the earlier calls said went out, word for word: the only thing that keeps this
            # call from creating the branch or the merge request a second time. Every attempt is
            # listed (not the last), and an attempt that never reported back is listed as such.
            rows = [(f"{n}. a call started at {a.get('at')} and never reported back - what it did is unknown"
                     if a.get("in_flight") else
                     f"{n}. action: {a.get('action')} | did: {a.get('did') or 'nothing recorded'} | "
                     f"question: {a.get('question') or 'none'}") for n, a in enumerate(earlier, 1)]
            prompt += "\n\n## Earlier attempts at this delivery, oldest first, verbatim\n" + "\n".join(rows)
            if any(not a.get("in_flight") for a in earlier):
                prompt += ("\nThese already went out; verify the branch, commits and merge request that exist and "
                           "reuse them — create nothing twice.")
            if any(a.get("in_flight") for a in earlier):
                prompt += ("\nA previous call may have been interrupted and never reported what it did; verify the "
                           "branch, commits and merge request that exist and reuse them — create nothing twice.")
        else:
            prompt += "\n\nDelivery attempts so far: no attempt recorded."   # the line DELIVERY_RULE names (C1-2, C6)
        chosen = self.state.get("delivery_choice") or {}
        if chosen.get("choice") in ("go_on", "retry"):
            # A6: the typed record of the person's token (`_take_delivery_answer`), never a token read out of their prose
            prompt += ("\n\nThe person chose `" + chosen["token"] + "`: "
                       + ("deliver as it is." if chosen["choice"] == "go_on" else "they repaired what was undone themselves.")
                       + f" Their words are in {self.task_root / str(chosen.get('words_file') or '')}.")
        # The call is recorded BEFORE it is made and replaced by its verdict when it returns: a process
        # that dies inside the call (the conductor pushes, the driver is killed) leaves this line, and
        # the next process's first prompt says a call may have been interrupted (Lead's decision Q2).
        attempts = self.state.setdefault("delivery_attempts", [])
        attempts.append({"in_flight": True, "at": _now()})
        self.save_state()
        result = self.run_claude("conductor", prompt, stage="S8", tools="Bash,Read,Grep,Write",
                                 system_file=self.plugin / "references" / "conductor.md", max_turns=40,
                                 resume_key="S8:delivery")
        verdict = last_json_line(result["result"]) or {"action": "ask_person", "did": "", "question": result["result"][-1500:]}
        self.journal_conductor(stage="S8", refusal="delivery", action=verdict.get("action"), did=str(verdict.get("did") or "")[:1500],
                               question=str(verdict.get("question") or "")[:1000], session_id=result["session_id"],
                               total_cost_usd=result["total_cost_usd"], num_turns=result["num_turns"])
        action = verdict.get("action")
        # Every verdict is remembered as an attempt - what it said went out and what it asked - so the
        # next call can be told; the delivery MARK is written below, on `continue` only.
        attempts[-1] = {"at": _now(), "action": action, "did": str(verdict.get("did") or ""),
                        "question": str(verdict.get("question") or "")}
        self.state.pop("delivery_choice", None)      # the call that read the person's choice has answered: the choice is spent
        # The person's answer is read by code in `take_answer` (`_take_delivery_answer`: `go on` / `retry` / `no delivery` / `stop`
        # are tokens, any other words go to the seam). The flag is kept for its old readers (a state an older driver wrote).
        if action not in ("continue", "ask_person", "stop"):
            # An answer that is none of the three is treated as `ask_person` (Lead's decision, t-044):
            # no mark, the attempt is already kept with its did/question, and the person is asked in
            # words - no Refusal loop and no second conductor call. Their answer re-enters this step.
            self.state["delivery_question"] = True
            self.save_state()
            reported = str(verdict.get("question") or verdict.get("did") or "").strip()
            # remains: the site's own closed question (`s8.delivery.<word>`, four answers with executors in `_take_delivery_answer`)
            raise self.delivery_person("Delivery needs your word:\n\n" + (f"The delivery step reported: {reported}" if reported else
                                       "The delivery step came back with an answer I do not recognise."),
                                       why_person=verdict.get("why_person"))
        if action == "continue":
            # `mr` (t-1509, FR-14): the verdict's own field, the record the `mr` order is settled `done` with (`settle_mr_from_mark`);
            # kept only when it has the SHAPE of a record (`mr_record`): a link, an id token, a whole number; `none` / `N/A` /
            # `not opened` are no record, so the order is called off `delivered_without_mr` instead of closed as done
            mr = mr_record(verdict.get("mr"))
            self.state["delivery"] = {"done": True, "at": _now(), "did": verdict.get("did"), "action": action, "mr": mr}
        else:
            self.state["delivery_question"] = True
        self.save_state()
        if verdict.get("action") == "ask_person":
            # remains: the site's own closed question (see above)
            raise self.delivery_person(f"Delivery needs your word:\n\n{verdict.get('question')}", why_person=verdict.get("why_person"))
        if verdict.get("action") == "stop":
            # remains: the site's own closed question (see above)
            raise self.delivery_person(f"Delivery stopped:\n\n{verdict.get('question') or verdict.get('did')}", code=EXIT_GAVE_UP,
                                       why_person=verdict.get("why_person"))

    def delivery_person(self, said: str, *, code: int = EXIT_PERSON, why_person=None) -> Person:
        """`s8.delivery` (C1-6c, S11-S13 of the census): the delivery step's own words, then the priced answers. The key follows the
        verdict W2 the delivery is for (`yes` / `after_checks` / `no`, the word `recompute_verdict` returned): `go on` carries THAT
        word as its story line, never `yes` on `after_checks` (J4, P21), and on `after_checks` its person line is `your_checks`
        (the items in Left with you). `go on` and `retry` are two records (`delivery_choice`, FR-9): both re-enter the delivery step,
        which is first told what already went out. The delivery's own conductor session is NOT a seam call (F7); the question is."""
        options = [
            {"answer": "go on", "token": "go on", "slots": {"what": "the items in Left with you"},
             "says": "deliver as it is; the delivery step goes on with your words"},
            {"answer": "retry", "token": "retry", "slots": {"what": "the repair the delivery step named"},
             "says": "you repaired what was undone yourself; the delivery is asked again"},
            {"answer": "no delivery", "token": "no delivery", "says": "end the delivery here; nothing is sent out"},
            self.STOP_OPTION]
        # C-F2 (FR-10): the lead lists EVERY offered answer, read from `options` so it cannot drift from the priced section below it
        listed = ", ".join(f"`{o['token']}`" for o in options[:-1]) + f" or `{options[-1]['token']}`"
        lead = (said.rstrip() + "\n\nNothing is marked as delivered yet. When you say go on or retry, the delivery is first told what "
                                f"already went out and asked to reuse it. What I need from you: say to go on with the delivery, or to stop "
                                f"here. I take these answers: {listed}. To end the delivery here with nothing sent, answer `no delivery`; "
                                "any other words go to the delivery step as they are.\n\nThe answers are:")
        word = getattr(self, "recomputed_word", None) or self.delivery_word()
        # C-F2 (FR-59, AR-28): the unknown is never a `yes` - a word that is none of the two reads as the verdict `no` (not ready to ship).
        # The three ids stay LITERAL: the census of the conductor doors reads them (K15).
        if word == "after_checks":
            text = self.closed_question("s8.delivery.after_checks", lead, options)
        elif word == "yes":
            text = self.closed_question("s8.delivery.yes", lead, options)
        else:
            text = self.closed_question("s8.delivery.no", lead, options)
        person = Person("delivery", text, "S8", code=code)
        # RN1-9 (F5 a): RECORDED only - the delivery's own conductor session is no seam call, nothing is refused here
        person.source = "delivery"
        person.why_person = PO.as_class(why_person)
        return person

    def stage_S9(self) -> None:
        # GB-1b: the orders of gate B are carried out by `_act_execute_gate_b` BEFORE the story is closed; S9 runs on a closed
        # story only. This call stays (idempotent: an order that is not due is not touched) for a story decided before 0.10.5.
        self.after_gate_B()
        # R-212.1 (a): gate B is recorded, so the retro analyst and the S9 close see a report that carries its
        # gate B block, in every mode. `after_gate_B` is called here and by `_act_execute_gate_b`. (b), the
        # LAST write, is the mode's own: in `full` it is in `finish` (the retro role's return is what closes S9),
        # in `numbers` and `skip` it is right before `stage_done S9` below.
        self.rebuild_report()
        pipeline = self.pipeline()
        # `numbers` / `skip` are read only from a story an older version recorded (B-271, GW1-3); stage_done refuses them since 0.10.9.
        mode = pipeline.get("retro_mode") if pipeline.get("retro_mode") in ("full", "numbers", "skip") else "full"
        if mode == "skip":
            words = pipeline.get("retro_mode_words") or "skip"
            # W15 (C1-7b): the person's skip words are a journal row the retro and the report read; a refusal makes the row OWED
            self.owe_row("log_append.py", "--event", "escalated", "--agent", "qa-story", "--task", self.task,
                         "--reason", f"retro skipped by the person: {words}", what="your word to skip the retro")
            self.rebuild_report()
            self.record_close("s9.skip", "S9", "--status", "skipped", "--digest", f"retro skipped: {words}")
            return
        if not self.state.get("retro_asked"):
            raise Person("retro", S9_QUESTION, "S9")
        root = str(self.task_root)
        # G5 (C1-7b): its two files feed `--write-retro` and the retro analyst; a non-zero exit is a `Refusal` BEFORE `record_close` S9
        # (E3: the story is never recorded complete over an unwritten retro input)
        self.py("retro_numbers.py", "--task", self.task, "--output", f"{root}/work/retro-numbers.md",
                "--json-output", f"{root}/work/retro-numbers.json", check=True, expect="work/retro-numbers.md and work/retro-numbers.json written")
        if mode == "numbers":
            self.py("retro_numbers.py", "--task", self.task, "--write-retro", "--feedback",
                    self.state.get("retro_feedback") or "", check=True)
            # T6 (C1-7b): the estimate never raises, and the story's completion is never blocked by it (E3)
            self.py_trace("estimate_record.py", "--task", self.task, "--facts", f"{root}/work/estimate-facts.json",
                          why="the estimate feeds later stories' sizing; no decision of this story reads it")
            self.rebuild_report()
            self.record_close("s9.numbers", "S9", "--status", "done", "--digest", "retro: numbers only, on the person's word")
            return
        self.run_role("S9", "qa-retro-analyst", extra=self.role_lines("S9", "qa-retro-analyst"))

    # --- gates -----------------------------------------------------------------------------
    def gate_text(self, gate: str) -> str:
        parts = []
        code, brief = self.py("gate_brief.py", "--task", self.task, "--gate", gate)
        if code == 0:
            parts.append(brief)
        else:
            # t-370 (b): a person never reads a script name or an exit code. They read that the brief could not be built and the
            # brief's own first line (unless that line itself names a script, a flag or an exit code: then the line is not
            # shown); the code and the whole output go to the driver log.
            first = next((" ".join(row.split()) for row in brief.splitlines() if row.strip()), "")
            if any(p["rule"] in ("script_name", "flag", "exit_code") for p in human_text.problems(first, kind="report")):
                first = ""
            print(f"gate {gate}: the gate brief did not build (exit {code}): {' '.join(brief.split())[:400]}")
            parts.append("The gate brief could not be built" + (f" ({first})" if first else "") + ".")
        code, rehearsal = self.py("gate_preflight.py", "--task", self.task, "--gate", gate, "--text")
        # t-342: the heading used to name the script and its flag (`gate_preflight --gate B`): jargon in the body of a
        # question (human-questions.md, rule 5). What follows it is `gate_preflight --text`, whose own lines still
        # carry commands for the factory's findings - reported, not fixed here (another file's text).
        parts.append(f"## Rehearsal of gate {gate}\n" + rehearsal)
        # t-363 B1: `--list` is the PERSON form (one line per waiver, in words: stage, the block, their word whole,
        # the date) - this section used to carry the command's machine lines, with a script name and a timestamp. A
        # failed call (no readable pipeline.json) prints a sentence for whoever ran it: it is never a section.
        code, waivers = self.py("waiver.py", "--task", self.task, "--list")
        if code == 0 and waivers.strip():
            parts.append("## Blocks passed by your word so far\n" + waivers)
        if gate == "A":
            code, late = self.py("ticket_adapter.py", "review", "--output",
                                 f"qa-factory/artifacts/{self.task}/work/source-inventory.json", "--pending-only")
            if code == 0 and late.strip():
                parts.append("## Sources found after the S1 review\n" + late)
            word = self.approval_word("A")
            parts.append(
                (f"Approval is its own word: write `{word}` on the first line when the plan and the cases are approved as they "
                 "stand, then answer every item under 'After your approval' by name. To change something first, say what in your "
                 f"own words instead of `{word}`: nothing is approved, and you get the choices with what each costs; after a "
                 "change, this message comes again.") if word else
                ("Answer in your own words: say whether the plan and the cases are approved as they stand, then answer every "
                 "item under 'After your approval' by name."))
        else:
            # t-250 §4 (F10): what an agent checked BY HAND - the same block the report holds (FR-10: one renderer feeds
            # the report and this packet) - stands before the ledger and is never cut. Its writer is another task's
            # (`report_facts.manual_checks_text`), so a renderer that is not there yet, or one that fails, is ONE line
            # saying so (FR-41), never a missing section that reads like "nothing was checked by hand".
            parts.append(self.manual_checks_part())
            ledger = self.task_root / "work/ledger.md"
            if ledger.is_file():
                parts.append("## The checks ledger (work/ledger.md)\n" + ledger.read_text(encoding="utf-8", errors="replace")[:12000])
            report = self.task_root / "test-report.md"
            if report.is_file():
                parts += self.report_parts()
                parts.append(f"The whole report: qa-factory/artifacts/{self.task}/test-report.md")
            # An experiment opens no merge request (t-017 D3, FR-36): the instruction does not ask
            # whether one is opened, nor for a reason to deliver with known gaps - nothing is delivered.
            # t-342 (B-271, owner 02.10): the retro is ALWAYS full - the person is not offered a choice about it, so
            # the packet says nothing of it (its twin is phases/s8.md, item "The retro"). The `retro_mode` branches
            # in `stage_S9` stay for now; this is the sentence that offered them.
            # t-305 N8 (R6): the packet never offers an act the guard will refuse. The MR is offered on `yes` and on
            # `after_checks` (its description carries what is left with the person); on `no` the only item is
            # "deliver with known gaps" with its reason - and it is the MR's word only: a bug is filed from the numbers the
            # person answers (the driver records every gate B decision with `--bugs ordered`), never through that word.
            word = self.delivery_word()
            approve = self.approval_word("B")
            # C1-4b (FR-10): the approval line is prepended to EACH variant below, from the same word the check reads
            lead = (f"To approve, write `{approve}` on the first line of your answer; the rest of it is read as before. To have "
                    "something changed first — a test, the report, a case — write what, in your own words, instead of "
                    f"`{approve}`: nothing is recorded as approved, and you get the choices with what each costs. ") if approve else ""
            if self.no_trace():
                parts.append(lead + "Answer by number for the bugs to file.")
            elif word == "yes":
                parts.append(lead + "Answer by number for the bugs to file; say whether the MR is opened (Draft) or not; a "
                             "'deliver with known gaps' needs its reason.")
            elif word == "after_checks":
                parts.append(lead + "Answer by number for the bugs to file; say whether the MR is opened (Draft) - its "
                             "description carries what is left with you; a 'deliver with known gaps' needs its reason.")
            else:
                # HF8-23: the form is the one `gate_brief.risk_form` prints in the skill road's packet (one text, AR-19)
                import gate_brief
                form = gate_brief.risk_form()
                parts.append(lead + "Answer by number for the bugs to file. The checks do not say the delivery is ready, so no "
                             "MR is offered: to open one, " + (form + "." if form else "say 'deliver with known gaps' and give your reason."))
        return "\n\n".join(parts)

    def delivery_word(self) -> str:
        """The ledger's verdict word as the gates read it (`yes`, `after_checks`, else `no`: an absent, unreadable or
        inconsistent ledger offers nothing)."""
        import gate_brief
        return gate_brief.delivery_word(self.task_root)

    def report_parts(self) -> list:
        """The report's verdict block and its `## Left with you` section, WHOLE (t-305 N8, Q22): the packet used to find
        "section 3" by a regex no report matches and fell back to the first 4000 characters, so a Left with you that
        began later was never shown. A part that is absent is one line saying so (FR-41), never a silent gap. When a
        stand-gap answer below could change the verdict, ONE sentence says it was computed before the answer and is
        computed again before anything goes out (C7)."""
        import grammar as G
        import report_facts
        out = []
        try:
            text = (self.task_root / "test-report.md").read_text(encoding="utf-8-sig", errors="replace")
            verdict = G.find_blocks(text).get("verdict")
        except Exception:
            verdict = None
        out.append("## The verdict (test-report.md)\n" + (verdict[2].strip("\n") if verdict else
                                                           "the report holds no verdict block yet"))
        if self.verdict_may_change():
            out.append("This verdict was computed before your answer; an answer to a stand gap below can change it, "
                       "and it is computed again before anything goes out.")
        try:
            left = report_facts.left_with_you_text(self.task_root)
        except Exception:
            left = None
        out.append(left.rstrip("\n") if left else "## Left with you (test-report.md)\nthe report holds no such section yet")
        return out

    def verdict_may_change(self) -> bool:
        """Could an answer at this gate change the verdict word? Yes while a stand gap waits for a card answer, or an
        ENV_ISSUE has no closed decision (the ledger's own kind `env_undecided`)."""
        try:
            import gate_brief
            import contract as C
            if gate_brief.gate_b_gaps(self.task_root):
                return True
            ledger = C.load_json(C.artifact(self.task_root, "ledger.json"))
            return any(isinstance(r, dict) and r.get("kind") == "env_undecided" for r in ledger.get("reason_records") or [])
        except Exception:
            return False

    def manual_checks_part(self) -> str:
        """The block of what an agent checked by hand, as `report_facts.manual_checks_text(task_root)` renders it, whole.

        The import is guarded: until the renderer exists the line is "manual checks: renderer not installed". A render
        that raises, or prints nothing, is one line each - the packet is still shown (P1)."""
        try:
            import report_facts
            render = report_facts.manual_checks_text
        except (ImportError, AttributeError):
            return "manual checks: renderer not installed"
        try:
            text = render(self.task_root)
        except Exception as exc:
            return f"manual checks: could not be shown ({type(exc).__name__}: {' '.join(str(exc).split())[:160]})"
        if not isinstance(text, str) or not text.strip():
            return "manual checks: the renderer printed nothing"
        return text

    NOTE_QUOTE_LIMIT = 200

    def gate_rework_note(self, gate: str) -> str:
        """The line at the top of a gate asked AGAIN after a rework (I5, FR-7, H7): the person's words, the stage that was done again and
        the stages that ran again after it. Derived from EVERY accepted rework (`rework_of`) registered since this gate was last shown
        - not only the stamped ones - so a rework with nothing after it (an S8 scribe) still changes the text and an unchanged packet is
        never shown without a note. The ids shown are kept in `gate_noted[gate]` when the gate is raised; a gate never shown before
        (no key) says nothing and seeds the list, so the repair rounds of the stages before the first show are not "a rework". A rework
        of the B-364 road (`ticket_changed`) has its own note. Only a record marked `person_words` (the controller sets it for `--words-file`)
        is quoted as the person's words; any other rework is told neutrally, without its code-typed reason. Never raises: no note is better than no gate."""
        try:
            noted = self.state.setdefault("gate_noted", {})
            seen = noted.get(gate)
            made = [d for d in (self.controller_state().get("dispatches") or {}).values()
                    if isinstance(d, dict) and d.get("rework_of") and d.get("status") == "accepted"
                    and d.get("repair_cause") != "ticket_changed"]
            noted[gate] = list(dict.fromkeys(list(seen or []) + [str(d.get("id")) for d in made]))
            if seen is None:
                return ""
            names = self.stages()

            def label(stage: str) -> str:
                name = str((names.get(stage) or {}).get("name") or "").strip().lower()
                return f"{name} ({stage})" if name else stage
            sentences = []
            for d in made:
                if str(d.get("id")) in seen:
                    continue
                if d.get("person_words") is not True:
                    # t-694 F1: a rework the driver or the conductor asked for (a reason typed by code) is never shown as the
                    # person's words, and a record without the mark (an older controller wrote it) is treated the same way (FR-59).
                    cause = " ".join(str(d.get("repair_cause") or "test_defect").replace("_", " ").split())
                    sentences.append(f"{label(str(d.get('stage') or ''))} ran again after a repair round of the factory's own ({cause})")
                    continue
                words = " ".join(str(d.get("reason") or "").split())
                quote = words[:self.NOTE_QUOTE_LIMIT] + ("..." if len(words) > self.NOTE_QUOTE_LIMIT else "")
                later = [label(s) for s in (d.get("rerun_after") or {}).get("stages") or []] if isinstance(d.get("rerun_after"), dict) else []
                sentences.append(f"on your words \"{quote}\", {label(str(d.get('stage') or ''))} was done again"
                                 + (f", then {', '.join(later)} ran again" if later else ""))
            return f"Gate {gate} is asked again: " + "; and ".join(sentences) + "." if sentences else ""
        except Exception:
            return ""

    def gate(self, gate: str, top: str = "") -> None:
        """The gate question. `top` is the factory's own list of what it could not repair before asking
        (`gate_repair`, F5 b): it stands above the packet, so the person reads first that these are not theirs."""
        self.boundary = f"gate_{gate}"
        # B-364 R17: the line that says why this gate comes again, once, at the top. One carrier, `gate_note` (the writer is
        # `ticket_reopen_gate_a`; t-694 F4 renamed it from `ticket_gate_note`, the old key is no longer read).
        said = []
        held = self.state.get("gate_note")
        if isinstance(held, dict) and held.get(gate):
            said.append(held.pop(gate))
        again = self.gate_rework_note(gate)
        if again:
            said.append(again)
        if gate == "B":                       # the question lines of the findings this packet shows; a `open` one asked again says so (FR-7)
            left_open = self.keep_shown_exploratory()
            if left_open:
                said.append(left_open)
        if said:
            top = "\n\n".join(said) + ("\n\n" + top.strip() if top.strip() else "")
        head =f"# Gate {gate} — {self.task}\n\n" + (top.strip() + "\n\n" if top.strip() else "")
        # t-369 N-2: the doors this packet SHOWS, by finding id - the block and stage each id's door passes. An answer's
        # door line is read only against these (`read_finding_doors`): ids are ordinal and a message does not bind a block.
        # Best effort: a rehearsal that cannot run stores none, and then no door line is read by code (the conductor is).
        # The doors are those of the rehearsal the repair step just ran (`rehearse` keeps them): no second rehearsal is run for them.
        shown_doors = dict((self.state.get("last_rehearsal_doors") or {}).get(gate) or {})
        self.state.setdefault("shown_doors", {})[gate] = shown_doors
        # B-414 M12: the stand gaps (and the ones the environment record covered) of the rehearsal that built THIS packet - bound
        # to what the person is shown, like the doors: a later `rehearse()` (the answer's own) must not rewrite what they saw
        self.state.setdefault("shown_gaps", {})[gate] = dict((self.state.get("last_rehearsal_gaps") or {}).get(gate) or {})
        body = self.gate_text(gate)       # built first: the brief reads the PREVIOUS `shown_attachments` from disk, the line below replaces it
        if gate == "A":                   # S6 1c: the attachments this packet names, so a later gate A says what is new
            import gate_brief
            gate_brief.keep_shown_attachments(self.task_root, self.state)
        raise Person(f"gate_{gate}", head + body, "S4" if gate == "A" else "S8")

    # --- the gate-entry repair (t-211, F-cmp2-17) ------------------------------------------------
    # TP1-15045 (cmp2): S4 closed, the person was asked at gate A, and only then did the factory find
    # four times over what it had known since the S4 exit (8 design-review findings, 6 unpinned cases,
    # 1 question branch) - the rehearsal sat INSIDE the packet as advice. `stage_done` refuses to close the
    # stage over them, but story_step has accepted the stage in the controller before it calls stage_done, so
    # that refusal never stopped anything. This step is the gate on SHOWING the gate: the rehearsal runs
    # first, what a code move can repair is repaired by code, and the person is addressed once.
    #
    # `gate_preflight.run` is reused here in a more consequential role than it was written for: from text
    # in the packet (advice) to the trigger of paid dispatches and the condition of showing the gate. The
    # error direction that is allowed is toward SHOWING the gate (today's behaviour); never toward unbounded
    # spend (a round cap, a key set that may not repeat, a stop that outlives the process) and never toward a
    # gate withheld with no door (the conductor, then the person's word).
    def stage_completed(self, stage: str) -> bool:
        """Has the CONTROLLER accepted this stage (`completed`)? pipeline.json can say `done` over a stage
        the controller still holds open, and the other way round; this reads the controller's own record."""
        try:
            return (((self.controller_state().get("stages") or {}).get(stage) or {}).get("status")) == "completed"
        except Exception:
            return False

    def rehearse(self, gate: str) -> dict:
        """The gate's rehearsal as data: `gate_preflight.py --task T --gate X` (read-only, JSON). A seam: the
        tests replace it. Anything that is not a result raises, and the caller shows the gate without it."""
        code, out = self.py("gate_preflight.py", "--task", self.task, "--gate", gate)
        if code:
            raise RuntimeError(f"gate_preflight.py exited {code}: {' '.join(out.split())[-200:]}")
        try:
            data = json.loads(out[out.index("{"):out.rindex("}") + 1])
        except ValueError as exc:
            raise RuntimeError("gate_preflight.py printed no readable JSON") from exc
        if not isinstance(data, dict):
            raise RuntimeError("gate_preflight.py printed no JSON object")
        # t-369 N-2: the doors of THIS rehearsal by finding id, kept for `gate()` (the packet shown right after it)
        self.state.setdefault("last_rehearsal_doors", {})[gate] = {
            str(f["id"]): [d for d in f.get("waives") or [] if isinstance(d, dict)]
            for f in data.get("findings") or [] if isinstance(f, dict) and f.get("id")}
        # B-414 R8(c): the stand gaps of this rehearsal and the gaps the environment record covered (no card), kept for `gate()`;
        # `carry_environment_properties` reads them - it runs no rehearsal of its own
        try:
            import stand_gaps
            self.state.setdefault("last_rehearsal_gaps", {})[gate] = {
                "gaps": [{"id": str(g["id"]), "case_id": str(g.get("case") or ""), "cases": [str(c) for c in g.get("cases") or []]}
                         for g in data.get("stand_gaps") or [] if isinstance(g, dict) and g.get("id")],
                "covered": stand_gaps.covered_a(self.task_root, data)}
        except Exception:
            self.state.setdefault("last_rehearsal_gaps", {})[gate] = {"gaps": [], "covered": []}
        return data

    @staticmethod
    def fixable_findings(findings: list) -> list:
        """The `factory_fixable` findings, normalised: a finding that is no object, or has no `class`, or no
        text `check`, is not one of them (a story from an older build is shown as it always was)."""
        out = []
        for item in findings:
            if (isinstance(item, dict) and item.get("class") == FACTORY_FIXABLE
                    and isinstance(item.get("check"), str) and item["check"].strip()):
                out.append(dict(item, check=item["check"].strip(),
                                message=" ".join(str(item.get("message") or "").split())))
        return out

    @staticmethod
    def key_set(fixable: list) -> list:
        """The sorted, de-duplicated (check, message) pairs. NEVER the finding's positional `id`
        (`gate_decision-1` names the first finding of its check, whichever row it is about: a different
        row under the same id is a different finding), and never a count."""
        return [list(key) for key in sorted({(f["check"], f["message"]) for f in fixable})]

    @staticmethod
    def attempted_rounds(rounds) -> list:
        """The rounds that spent something: every record that is not a stop (a stop is `same_set`, `cap` or
        `no_move`; a `failed` round did try its move and counts)."""
        return [r for r in rounds if isinstance(r, dict) and (not r.get("stop") or r.get("stop") == "failed")]

    def gate_series(self, gate: str) -> dict:
        """The series of repair rounds of this gate, kept in `driver-state.json` (an exit-3 relaunch counts from
        the same place; the conductor's calls, kept in memory, do not survive one). A series is the factory's
        own bookkeeping of ONE story revision (C7): it is dropped when `source_revision` changed since it began
        (a reopen), or when the gate is approved at the current revision; the next one starts empty."""
        state = self.controller_state()
        revision = state.get("source_revision")
        approved = any(isinstance(d, dict) and d.get("gate") == gate and d.get("status") == "approved"
                       and d.get("source_revision") == revision for d in (state.get("decisions") or {}).values())
        held = self.state.get("gate_repair")
        if not isinstance(held, dict):
            held = self.state["gate_repair"] = {}
        series = held.get(gate)
        if isinstance(series, dict) and (series.get("source_revision") != revision or approved):
            held.pop(gate)
            series = None
        if not isinstance(series, dict) or not isinstance(series.get("rounds"), list):
            series = held[gate] = {"source_revision": revision, "rounds": []}
        return series

    def kept_answer(self, gate: str) -> dict:
        """The person's answer to this gate that was heard but not recorded (`record_by_code` failed and the
        words went to the conductor), or {}. Stamped with the revision it was given at (C3): an answer to a
        reopened story's old gate is not an answer to the new one."""
        kept = self.state.get("gate_answer_kept")
        if (isinstance(kept, dict) and kept.get("gate") == gate and str(kept.get("words") or "").strip()
                and kept.get("source_revision") == self.controller_state().get("source_revision")
                and (kept.get("approved_by") in ("option", "token") or self.gate_approval(f"gate_{gate}", str(kept["words"])))):
            return kept
        return {}

    def old_kept_answer(self, gate: str) -> str:
        """The words of a `gate_answer_kept` an OLDER driver wrote (any gate words, prose), dropped from the state and returned so the
        caller hands them to the seam once (C1-4b, H8): they were never an approval, so the controller never "refused" them and the
        person is not told it did. "" when there is none, it is an approval (`approved_by` or the approval word), it belongs to another
        gate, or it was given at another revision of the story (dropped silently: an answer to a reopened story's old gate)."""
        kept = self.state.get("gate_answer_kept")
        if not isinstance(kept, dict) or kept.get("gate") != gate or not str(kept.get("words") or "").strip():
            return ""
        if kept.get("approved_by") in ("option", "token") or self.gate_approval(f"gate_{gate}", str(kept["words"])):
            return ""
        self.state.pop("gate_answer_kept", None)
        self.save_state()
        return str(kept["words"]) if kept.get("source_revision") == self.controller_state().get("source_revision") else ""

    def design_reviews(self, gate: str) -> list:
        """The design reviews the controller would bind into this gate's decision (`build_gate_decision`, which
        writes nothing: the rehearsal reads the same). [] when they cannot be built - then no move applies."""
        try:
            from controller import Controller
            request = Controller(self.task_root).build_gate_decision(gate, "<the words the person is about to say>")
            reviews = request.get("design_reviews")
            return [r for r in reviews if isinstance(r, dict)] if isinstance(reviews, list) else []
        except Exception:
            return []

    def accept_order(self) -> dict:
        """dispatch id -> the position of its `accept` event in `state/events.jsonl` (the order work was
        accepted in; dispatch numbers and registration order say nothing about it). The one reader is
        `Controller.accept_order`; this only delegates (AR-13)."""
        from controller import Controller
        return Controller(self.task_root).accept_order()

    def pin_precondition(self, gate: str, findings: list, *, pin_planned: bool = False, rounds=()):
        """`case_versions`: no precondition. The gate approves what is on disk, and pinning is idempotent."""
        return {"pins": True}

    def review_precondition(self, gate: str, findings: list, *, pin_planned: bool = False, rounds=()):
        """`gate_decision`: which role goes back, read from the controller's own design reviews and the order of
        the `accept` events - never from a finding's wording (FR-12).

        (1) a designer accepted AFTER the critic reviewed (the rework changed what the critic saw): the critic
            reviews again, over the cases that designer reworked. The review is bound to the pinned case
            versions, so the round re-pins first; `pin_planned` says it is about to.
        (2) otherwise a critic whose declared verdict is not approving, with no designer round after it: the
            designer reworks the cases of the critic dispatch's own scope - but only while a round is left for
            the critic that must follow it (the series cap) AND the designer's own repair cap has room; if not,
            this is `direct`: the person is told, once, at the gate (F2 c).
        None when neither holds, or the scope is empty (F8: a rework with an empty scope passes every later
        check, so it is never registered)."""
        reviews = self.design_reviews(gate)
        if not reviews:
            return None
        dispatches = self.controller_state().get("dispatches") or {}
        order = self.accept_order()
        from controller import Controller
        later = []
        for review in reviews:
            # the one staleness predicate (AR-13): `Controller.review_is_stale`, not a second loop of the same rule
            author = str(review.get("author_dispatch_id") or "")
            if Controller.review_is_stale(review, order) and author not in later:
                later.append(author)

        def scope_of(ids) -> list:
            return sorted({str(c) for i in ids for c in ((dispatches.get(i) or {}).get("scope") or [])})
        if later:
            scope = scope_of(later)
            if not pin_planned:
                pinned = set(self.pinned_cases())
                scope = [c for c in scope if c in pinned]
            return {"kind": "critic", "scope": scope, "authors": later} if scope else None
        refusing = [r for r in reviews if str(r.get("verdict") or "accepted") != "accepted"]
        if not refusing:
            return None
        critics = sorted({str(r.get("reviewer_dispatch_id")) for r in refusing if r.get("reviewer_dispatch_id")})
        scope = scope_of(critics)
        if not scope:
            return None
        if all(r.get("verdict_basis") == "round_word_rule" for r in refusing):
            # HF4-11: the critic's word contradicts its own cells - the cases are fine, only the `Verdict:` line is
            # wrong, and only the critic can rewrite it. A designer round would have nothing to fix. The invariant: no
            # designer round for a refusal that is not about a case; the cap still ends at the person (`direct`), and a
            # round of the critic needs no round after it, so one round of the series is enough. A mixed set (some row
            # refused for another reason) keeps the designer route below - that round is followed by the critic anyway.
            if len(self.attempted_rounds(rounds)) + 1 > GATE_REPAIR_CAP:
                return {"direct": True, "why": "no round is left for the critic to rewrite its `Verdict:` line"}
            return {"kind": "critic", "scope": scope, "authors": critics, "rule": "round_word_rule"}
        if len(self.attempted_rounds(rounds)) + 2 > GATE_REPAIR_CAP:
            return {"direct": True, "why": "no round is left for the critic that would follow a designer round"}
        budget = self.budget_or_none("S4", "qa-case-designer", scope) or {}
        counted, cap = budget.get("counted"), budget.get("cap")
        if not (isinstance(counted, int) and isinstance(cap, int) and counted < cap):
            return {"direct": True, "why": "the designer's repair cap is spent (or could not be read)"}
        return {"kind": "designer", "scope": scope, "critics": critics, "counted": counted, "cap": cap}

    def repair_plan(self, gate: str, fixable: list, rounds) -> tuple:
        """(plan, direct): the table's rows whose check is among the findings and whose precondition holds, in
        the table's order; and the findings that go straight into the list at the top of the gate (a check
        only a person's word can pass, or a critic that did not approve with no round left). Reads state,
        writes nothing."""
        plan, direct = [], [f for f in fixable if f["check"] in GATE_DIRECT_CHECKS]
        pin_planned = False
        for row_gate, check, precondition, move in GATE_REPAIRS:
            mine = [f for f in fixable if f["check"] == check]
            if row_gate != gate or not mine:
                continue
            found = getattr(self, precondition)(gate, mine, pin_planned=pin_planned, rounds=rounds)
            if not found:
                continue
            if found.get("direct"):
                direct += mine
                continue
            plan.append((precondition, move, mine, found))
            pin_planned = pin_planned or bool(found.get("pins"))
        return plan, direct

    def pin_move(self, gate: str, findings: list, found: dict, record: dict) -> None:
        try:
            self.pin_cases()
        except Refusal as exc:
            record["moves"].append("pin_cases (failed)")
            raise RepairFailed("case_versions.py --all, then --verify", exc.text) from exc
        record["moves"].append("pin_cases")
        print(f"gate {gate} repair: the cases are pinned again at their current bytes")
        # C11 (t-214 C1): the controller's approved scope follows the pinned cases, exactly as stage_S4 does it
        # (`pin_cases()` then `revise_plan()`). A designer round at the gate may add or drop a case; without
        # this the gate decision binds the OLD scope and the person approves a scope without that case.
        try:
            self.revise_plan()
        except Refusal as exc:
            record["moves"].append("revise_plan (failed)")
            raise RepairFailed("controller.py --operation revise_plan", exc.text) from exc
        record["moves"].append("revise_plan")

    def review_move(self, gate: str, findings: list, found: dict, record: dict) -> None:
        scope = found["scope"]
        if found["kind"] == "critic" and found.get("rule") == "round_word_rule":
            authors = ", ".join(found["authors"])
            print(f"gate {gate} repair: the case critic rewrites the `Verdict:` line of {authors} "
                  f"(no case fails; the cases are unchanged): {', '.join(scope)}")
            role, move = "qa-case-critic", "critic_rework"
            reason = (f"gate {gate} repair: your round's Verdict line contradicts your own cells (no failing case); "
                      f"rewrite the Verdict line - the cases were not changed ({authors})")
            extra = ["Write a new round on top of the findings file with the Verdict line your cells earn "
                     "(`approve_with_concerns` when no case fails); earlier rounds are never edited."]
        elif found["kind"] == "critic":
            authors = ", ".join(found["authors"])
            print(f"gate {gate} repair: the case critic reviews again the {len(scope)} case(s) the designer "
                  f"reworked in {authors}: {', '.join(scope)}")
            role, move = "qa-case-critic", "critic_rework"
            reason = (f"gate {gate} repair: the case designer reworked these cases after your review ({authors}); "
                      "review them again at their pinned versions")
            extra = ["Review only the pinned versions; your roll-call names every case in scope."]
        else:
            critics = ", ".join(found["critics"])
            print(f"gate {gate} repair: the case designer reworks the {len(scope)} case(s) the critic did not "
                  f"approve in {critics}: {', '.join(scope)} (designer round {found['counted'] + 1} of {found['cap']})")
            findings_file = self.s4_findings()
            role, move = "qa-case-designer", "designer_rework"
            reason = ("critic round: " + findings_file.read_text(encoding="utf-8", errors="replace")[:1200]
                      if findings_file else
                      f"gate {gate} repair: the case critic ({critics}) did not approve these cases; "
                      "its findings are in the case folder")
            extra = [f"Repair round {found['counted'] + 1} of {found['cap']}: the critic's findings are in "
                     + (findings_file.relative_to(self.task_root).as_posix() if findings_file else "the case folder")
                     + "; change only what they name."]
        record["moves"].append(move)
        try:
            # `cause` is the controller's own default for a round about the test (the only one that spends
            # the repair cap, and no value of REPAIR_CAUSES names "a second review"): a critic round over
            # reworked cases is a round of the same repair, so it is counted as one.
            self.rework("S4", role, scope, reason, cause="test_defect", extra=extra)
        except ReworkRefused as exc:
            record["moves"][-1] = move + " (refused)"
            raise RepairFailed(f"controller.py --operation rework --stage S4 --role {role}", exc.text) from exc

    def raise_precondition(self, gate: str, findings: list, *, pin_planned: bool = False, rounds=()):
        """`unraised_questions`: no precondition beyond the finding itself - `critic_rollcall.py --apply-fixes` is
        idempotent (a Then already raised is keyed by (case, then) and raises nothing twice). It re-pins what it
        writes, so a pin is planned (the critic's scope is cut by the pinned cases)."""
        return {"pins": True}

    def raise_move(self, gate: str, findings: list, found: dict, record: dict) -> None:
        """The S4 exit's own command, run for a Then that reached gate A with no question to ask the person (t-227 O4).

        Exit 0: every `raise` is now a question id. Exit 1 is the command's own word for "some could not be raised
        or fixed" - it printed which, and the finding it leaves is judged again by the next rehearsal (the same set
        is a recorded stop, FR-4: nothing is repeated blindly). Anything else is a failed move."""
        code, out = self.py("critic_rollcall.py", "--apply-fixes", "--task-root", str(self.task_root))
        if code not in (0, 1):
            record["moves"].append("critic_rollcall --apply-fixes (failed)")
            raise RepairFailed("critic_rollcall.py --apply-fixes", f"(exit {code})\n{out}")
        record["moves"].append("critic_rollcall --apply-fixes")
        print(f"gate {gate} repair: the questions the designer could only name are raised by code"
              + ("" if code == 0 else f" (some could not be: {' '.join(out.split())[-160:]})"))
        try:
            self.pin_cases()
        except Refusal as exc:
            record["moves"].append("pin_cases (failed)")
            raise RepairFailed("case_versions.py --all, then --verify", exc.text) from exc
        record["moves"].append("pin_cases")

    def probe_precondition(self, gate: str, findings: list, *, pin_planned: bool = False, rounds=()):
        """`s5_runtime_probe`: the rehearsal derived a probe, proved the stand against it and put the exact command
        that registers it in the finding's `argv` FIELD (a list of strings; FR-12: the sentence is never read). A
        finding with no such field has no move here - it is left to the conductor and the top of the gate."""
        argvs = [(str(f.get("profile") or ""), list(f["argv"])) for f in findings
                 if isinstance(f.get("argv"), list) and f["argv"] and all(isinstance(a, str) and a for a in f["argv"])]
        return {"argvs": argvs} if argvs else None

    UNKNOWN_TOKEN_RE = re.compile(r"\{[A-Za-z_][\w-]*\}")

    def run_argv(self, argv: list) -> tuple:
        """Run one command line as it is written, from the project root: (exit code, stdout+stderr). A seam: the
        tests replace it. `py` runs the plugin's own scripts by name; the argv of a registered probe is any command
        line (an older config holds an absolute one), so it is run as given."""
        done = subprocess.run([str(a) for a in argv], capture_output=True, text=True, encoding="utf-8",
                              errors="replace", cwd=str(self.project), env=self.env)
        return done.returncode, (done.stdout + ("\n" + done.stderr if done.stderr.strip() else "")).strip()

    def probe_move(self, gate: str, findings: list, found: dict, record: dict) -> None:
        """Register the probes the rehearsal derived: `runtime_probe.resolve_argv(argv)` FIRST (the config's portable
        form - `{python}`, `{plugin_root}` - means this machine's interpreter and plugin; a legacy ABSOLUTE argv has no
        token and runs as written), then the command. INVARIANT: an argv that still holds a `{token}` after that is NOT
        executed - it would run with a brace word as an argument - and is refused naming the two tokens that exist."""
        self.typed_argv_move(gate, found["argvs"], record, "runtime_probe --suggest --write", "runtime_probe.py --suggest --write",
                             "probe", lambda profile: f"the probe the stand proved is registered for `{profile}`")

    def typed_argv_move(self, gate: str, pairs: list, record: dict, move: str, command: str, what: str, done) -> None:
        """Run the typed `argv` of each `(profile, argv)` a finding carried - ONE implementation for the two code-only rows that run one
        (`probe_move`, `adapt_move`): `runtime_probe.resolve_argv` first, an argv that still holds a `{token}` is refused unrun, a non-zero exit
        is a `RepairFailed` (the conductor gets the command and its last lines), a success is one line. `move` is what the round records,
        `command` what a failure names, `what` the noun of the refusal, `done(profile)` the success line. The config is read again after:
        both moves change it."""
        import runtime_probe
        for profile, argv in pairs:
            resolved = [str(a) for a in runtime_probe.resolve_argv(argv)]
            unknown = sorted({m for a in resolved for m in self.UNKNOWN_TOKEN_RE.findall(a)})
            if unknown:
                record["moves"].append(f"{move} {profile} (refused)")
                raise RepairFailed(
                    command,
                    f"the command for the `{profile}` {what} holds {', '.join(unknown)}, which is not one of the two words "
                    f"this factory fills in ({runtime_probe.PY_TOKEN} for the interpreter, {runtime_probe.PLUGIN_TOKEN} "
                    "for the plugin folder), so it was not run")
            code, out = self.run_argv(resolved)
            if code:
                record["moves"].append(f"{move} {profile} (failed)")
                raise RepairFailed(f"{command} --profile {profile}", f"(exit {code})\n{out}")
            record["moves"].append(f"{move} {profile}")
            print(f"gate {gate} repair: {done(profile)}")
        try:
            import hooklib
            self.config = hooklib.load_config() or self.config
        except Exception:
            pass

    def adapt_precondition(self, gate: str, findings: list, *, pin_planned: bool = False, rounds=()):
        """`s5_reporter` (B-416 N4, N6): a finding that carries the typed `argv` of the one `report_adapt.py kind` command (exactly one reader
        fits and the declared kind is empty) has a code move; one without it is left to the conductor and the top of the gate."""
        argvs = [(str(f.get("profile") or ""), list(f["argv"])) for f in findings
                 if isinstance(f.get("argv"), list) and f["argv"] and all(isinstance(a, str) and a for a in f["argv"])]
        return {"argvs": argvs} if argvs else None

    def adapt_move(self, gate: str, findings: list, found: dict, record: dict) -> None:
        """Run `report_adapt.py kind` for the findings that carry it: the same typed-argv mechanism (and the same refusal of an unknown `{token}`)
        as `probe_move`. A refusal of `kind` itself (a kind a person recorded, bytes that moved) is a `RepairFailed`: the conductor gets the
        output and the door `understood`."""
        self.typed_argv_move(gate, found["argvs"], record, "report_adapt kind", "report_adapt.py kind", "report adaptation",
                             lambda profile: f"the report of `{profile}` is read as the one reader that fits it, recorded by the helper")

    def gate_entry_steps(self, gate: str) -> None:
        """What the stage in front of this gate still owes, when its refused finish skipped it (C10): the
        row `gate_stage` lets that finish go on, and the code after it in `stage_S4` (the case appendix) and
        `stage_S8` (the report rebuild, t-204's position: after the scribe, before the gate packet) never ran."""
        owed = self.state.get("gate_entry_owed")
        stage = GATE_STAGE_OF.get(gate, "")
        if not isinstance(owed, dict) or not owed.pop(stage, None):
            return
        self.save_state()
        if gate == "A":
            self.render_appendix()
        else:
            self.rebuild_report()

    def finding_counts(self, fixable: list) -> str:
        counts: dict = {}
        for item in fixable:
            counts[item["check"]] = counts.get(item["check"], 0) + 1
        return ", ".join(f"{CHECK_WORDS.get(check, check.replace('_', ' '))} {counts[check]}" for check in sorted(counts))

    def unrepaired_text(self, gate: str, fixable: list) -> str:
        """The block at the top of the gate packet (F5 b): what the factory could not repair, stated as its
        own (FR-3) - the person is told, not asked. At most GATE_TOP_LIMIT lines; the rest is counted."""
        seen, lines = set(), []
        # what only a person's word passes (question branches) first: a long list must not cut it off
        for item in sorted(fixable, key=lambda f: f["check"] not in GATE_DIRECT_CHECKS):
            if item["message"] not in seen:
                seen.add(item["message"])
                lines.append(item["message"])
        shown = lines[:GATE_TOP_LIMIT]
        out = ["## What the factory could not repair before asking you", "",
               "These are the factory's own to repair, not questions for you: it tried every move it has, and they "
               "are still open. Your answer does not depend on them, and your word passes them - it is recorded "
               "as the reason the story carries.", ""]
        out += [f"- {line}" for line in shown]
        if len(lines) > len(shown):
            out.append(f"- (and {len(lines) - len(shown)} more in the rehearsal below)")
        if gate == "A" and any(item["check"] == "gate_decision" for item in fixable):
            # the case critic reviews at gate A only (at B the same check id is about the delivery decision)
            findings_file = self.s4_findings()
            if findings_file:
                out += ["", "The case critic's own findings: "
                        f"qa-factory/artifacts/{self.task}/{findings_file.relative_to(self.task_root).as_posix()}"]
        return "\n".join(out)

    KEPT_REFUSAL_LIMIT = 2000

    def kept_answer_text(self, kept: dict) -> str:
        """The block at the top of a gate asked AGAIN over a kept answer (t-214 C3, FR-7): when their words were
        given, the first 200 characters of them, and the controller's refusal verbatim (cut at KEPT_REFUSAL_LIMIT
        characters, and it says so). The packet differs from the one they answered, and says why."""
        words = " ".join(str(kept.get("words") or "").split())
        said = words[:200] + ("..." if len(words) > 200 else "")
        if self.question_lines_note:
            # GW1-34 F4: the kept approval was held on lines about register questions, not refused by the controller - say so, and
            # let a plain `approve` be a knowing pass (FR-4). The note is told once (F5).
            shown, self.question_lines_note = self.question_lines_shown, ""
            first = shown.split(":", 1)[0].strip() or "Q1"
            return "\n".join(["## Your approval is kept, and it waits for your word on these lines", "",
                              f"You answered this gate at {kept.get('at') or 'an earlier time'}: \"{said}\"", "",
                              f"These lines about open questions could not be read, so nothing is recorded yet: {shown}.", "",
                              f"Answer `{self.approval_word(str(kept.get('gate') or '')) or 'approve'}` with each of them as `{first}: <letter>`, "
                              f"`{first}: not needed` or `{first}: until the report` on its own line; or `approve as is` to approve and leave them open."])
        refusal = str(self.gate_refusal or "").strip() or "(the controller printed nothing)"
        cut =len(refusal) > self.KEPT_REFUSAL_LIMIT
        items = self.gate_open_items(self.gate_refusal)
        record, _ = json_record(str(self.gate_refusal or ""))
        if items:
            # RH1-6 (A-AC5): the refusal is the ITEMS' - the approval stands and waits for the person's word on each; it is not
            # the factory's to repair (the owner is named from the field, never from the sentence). The factory's OWN sentences, when
            # the same record holds some, are told apart by the controller's `item_problems_from` and printed under their own owner
            # line, never as the person's (FR-10, FR-3); `approve as is` is offered only when there are none (it does not pass them).
            import gate_brief
            factory, listed = self.gate_refusal_parts(self.gate_refusal)
            as_is = "" if factory else gate_brief.as_is_word_of(str(kept.get("gate") or ""))
            out = ["## Your approval is kept, and it waits for your word on the items below", "",
                   f"You answered this gate at {kept.get('at') or 'an earlier time'}: \"{said}\""]
            if factory:
                out += ["", "First, the factory's own to repair, not questions for you:", ""]
                out += [f"- {line}" for line in factory] + [""]
            out += ["Your approval is kept. The factory records a gate A approval only over the items you have worded; these have no "
                    "word of yours yet, so nothing is recorded as approved:", ""]
            out += [f"- {line}" for line in listed] or [refusal[:self.KEPT_REFUSAL_LIMIT]]
            out += ["", "Word each item in your own words" + (f", or answer `{as_is}` to approve over all of them, each recorded with your words."
                                                             if as_is else ".")]
            return "\n".join(out)
        # A refusal this driver can READ as the controller's own record, with no open items, is the factory's (an older controller never
        # refuses over items either); text it cannot read names no owner (FR-41).
        owner = ("That is the factory's to repair, not a question for you; what it said, word for word"
                 if isinstance(record, dict) and isinstance(record.get("problems"), list)
                 else "It is not known whose to repair this is; what it said, word for word")
        out = ["## Your earlier answer is kept, and it did not record", "",
               f"You answered this gate at {kept.get('at') or 'an earlier time'}: \"{said}\"",
               "The factory kept your words, tried to record them as the decision, and its own check refused. "
               + owner + (f" (cut at {self.KEPT_REFUSAL_LIMIT} characters)" if cut else "") + ":", "",
               refusal[:self.KEPT_REFUSAL_LIMIT], "",
               self.kept_answer_close(str(kept.get("gate") or ""))]
        return "\n".join(out)

    def approval_word(self, gate: str) -> str:
        """The word that approves gate `gate`, as the data file spells it (`gate_brief.approval_words`, the one reader); "" when the
        file cannot be read - then no packet text names a word (FR-10: the line and the check read the same source)."""
        import gate_brief
        words = gate_brief.approval_words(gate)
        return words[0] if words else ""

    def kept_answer_close(self, gate: str) -> str:
        """The last line of a gate asked again over a kept approval: an approval is its own word, a change is the person's own words."""
        word = self.approval_word(gate)
        if not word:
            return "Answer this gate again in your own words."
        return (f"If your approval still stands, answer `{word}` again; to change something first, say what in your own words.")

    def conductor_text(self, gate: str, why: str, rest: list, tried: str) -> str:
        """What the conductor is handed for a list code could not repair (FR-1): what is unrepaired, what was
        tried and with what output, and the doors. At most 20 findings; the rest is counted."""
        out = [f"Gate {gate} is about to be shown to the person, and the driver's own rehearsal still lists "
               f"{len(rest)} finding(s) of class factory_fixable that its code moves did not repair ({why}). The "
               "person has NOT been asked, and nothing here is theirs to decide: these are the factory's own.", "",
               "What the driver tried: " + (tried or "nothing - no code move applies to these checks") + ".", "",
               "The findings:"]
        for item in rest[:20]:
            line = f"- [{item.get('id') or item['check']}] {item['check']}: {item['message']}"
            if str(item.get("fix") or "").strip():
                line += "\n    fix: " + " ".join(str(item["fix"]).split())
            # t-364: the `fix` is words for a person; the block a person's word passes is the finding's `waives`
            # (gate_preflight), printed here for the conductor and for nobody else
            for door in item.get("waives") or []:
                if isinstance(door, dict) and door.get("block"):
                    line += (f"\n    a person's word passes block `{door['block']}` at {door.get('stage') or 'its stage'} "
                             f"(word option `{door.get('option')}`)")
            out.append(line)
        if len(rest) > 20:
            out.append(f"- (and {len(rest) - 20} more: `gate_preflight.py --task {self.task} --gate {gate} --text`)")
        out += ["", "Repair what you can with the factory's own commands (each finding's `fix` names its door), then "
                "answer `continue`: the driver shows the gate once, with whatever is left stated at its top as the "
                "factory's own. Answer `ask_person` only for a finding that needs a decision of theirs."]
        return "\n".join(out)

    def record_round(self, gate: str, series: dict, record: dict) -> None:
        """Round bookkeeping goes to the state file (the cap outlives the process) and to the driver journal."""
        if not any(r is record for r in series["rounds"]):
            series["rounds"].append(record)
        self.save_state()
        self.journal_run({"kind": "gate_repair", "gate": gate,
                          "round": next(i for i, r in enumerate(series["rounds"], 1) if r is record),
                          "keys": len(record["keys"]), "moves": record["moves"], "outcome": record["outcome"],
                          "stop": record["stop"]})

    def gate_repair(self, gate: str) -> dict:
        """The step in front of the gate packet. Returns {"ran": True} when a repair round was run (the loop goes
        back to `where`, which rehearses again), else {"ran": False, "top": <text>} - the caller shows the gate.

        POSITION INVARIANTS (t-211): (i) Person(gate_X) is never raised while the rehearsal holds an unwaived
        `factory_fixable` finding that a move can still address in this series - what no move addresses is
        shown, stated, at the top (F5 b); (ii) a round whose key set equals that of any earlier round of the
        series is refused; (iii) nothing is repaired under an open question about this gate (the packet a
        person is reading never changes under them); (iv) nothing is repaired after the person has spoken
        (a kept, unrecorded answer is recorded again, never asked again - FR-7). Every failure to rehearse
        shows the gate, as before."""
        shown = {"ran": False, "top": ""}
        self.boundary = f"gate_{gate}"
        if self.dry:
            print(self.gate_repair_would(gate))
            return shown
        asked = self.state.get("asked") or {}
        if asked.get("kind") == f"gate_{gate}" and self.question_path().is_file():
            print(f"gate {gate}: a question about this gate is already open — nothing is repaired under it")
            return shown
        old = self.old_kept_answer(gate)
        if old:
            # H8 (temporal): an answer kept by the driver before C1-4b holds prose that was never an approval. It goes to the seam
            # ONCE, whole, from its own words file; nothing says the controller refused it.
            print(f"gate {gate}: an answer kept by an older driver is not an approval - it goes to the conductor once")
            self._answer = {"text": old, "rel": None}
            try:
                self.unread(f"gate_{gate}", GATE_STAGE_OF.get(gate, ""), "", self.generic_prompt(f"gate_{gate}", GATE_STAGE_OF.get(gate, ""), ""), words=old)
            finally:
                self._answer = None
            return dict(shown, ran=True)
        kept = self.kept_answer(gate)
        if kept:
            print(f"gate {gate}: the person's answer is already kept ({len(str(kept['words']))} characters) - "
                  "nothing is repaired under it; the decision is recorded again with those words")
            self.gate_refusal = ""
            # H4: the mark that made the kept words an approval (`option`: the person chose it; `token`: the approval word) travels with them
            marks = {"approved_by": kept["approved_by"]} if kept.get("approved_by") else {}
            if kept.get("apply"):                    # a second answer's decision: its card lines are the new answer's alone (t-891 F-2)
                marks["apply_words"] = str(kept["apply"])
            if self.record_by_code(f"gate_{gate}", GATE_STAGE_OF.get(gate, ""), str(kept["words"]), again=True, **marks):
                self.save_state()
                shown["ran"] = True
                return shown
            # t-214 C3 (FR-7): the gate is asked again, but never with the SAME packet: the person is told their
            # words are kept, which they were, and why they did not record - the controller's refusal verbatim.
            return dict(shown, top=self.kept_answer_text(kept))

        if gate == "A" and self.apply_question_answers("A")["opened"]:
            # HF2-7 (M5, H28): an answer recorded after the last stop reaches the plan HERE, before the rehearsal reads it. POSITION
            # INVARIANT: after the open-packet return (iii) and the kept-answer branch (iv) - a packet the person is reading, or an answer
            # already given, never sees the plan move (F-13) - and before `gate_entry_steps` and the rehearsal. A rework that is owed
            # ends the call as a repair round does: the loop goes back to `where`, the step runs it, the gate is rehearsed again.
            return dict(shown, ran=True)
        if gate == "A":
            # t-2142 PK0-3 (AR-21, AR-28): a role the strategist named that the project does not know yet is recorded as noticed, not
            # confirmed. POSITION INVARIANT: after the open-packet return (iii) and the kept-answer returns (iv) - nothing is written
            # once the person has spoken - and before the rehearsal that builds the packet, which shows the noticed rows. Never raises.
            try:
                import project_knowledge
                project_knowledge.notice_from_handoff(self.project, self.task_root, str(self.pipeline().get("ticket") or self.task))
            except Exception as exc:
                print(f"project_knowledge: noticed roles were not recorded ({type(exc).__name__}: {str(exc)[:120]})", file=sys.stderr)
        self.gate_entry_steps(gate)
        try:
            result = self.rehearse(gate)
            findings = result.get("findings") if isinstance(result, dict) else None
            if not isinstance(findings, list):
                raise ValueError("the rehearsal's `findings` is not a list")
        except Exception as exc:
            print(f"gate {gate} rehearsal could not run ({type(exc).__name__}: {' '.join(str(exc).split())[:160]}); "
                  "the gate is shown without it")
            return shown
        fixable = self.fixable_findings(findings)
        if not fixable:
            print(f"gate {gate} rehearsal: nothing the factory has to repair — the gate is shown")
            return shown
        series, stage = self.gate_series(gate), GATE_STAGE_OF.get(gate, "")
        rounds, keys = series["rounds"], self.key_set(fixable)
        if any(isinstance(r, dict) and r.get("stop") for r in rounds):
            # B-416 N4: a series that has stopped only LISTS what is left - but a test report the conductor has not had its turn for is
            # handed over ONCE (the driver's own row after the call ends the bound); the person's card follows the next rehearsal.
            unread = self.unadapted_reporters(fixable)
            if unread:
                print(f"gate {gate} repair: the series has stopped, but {len(unread)} test report(s) the code could not read have not "
                      "had the helper's turn - handed to the conductor once")
                return self.hand_to_conductor(gate, stage, "a test report the code could not read", unread, [], "", fixable)
            # C6: once a series has stopped, whatever its key set the gate is shown with the list (the bound
            # does not depend on `conductor_calls`, which lives in memory and is reset by a relaunch).
            print(f"gate {gate} repair: the series has stopped — the gate is shown with {len(fixable)} thing(s) "
                  "the factory could not repair stated at its top")
            return dict(shown, top=self.unrepaired_text(gate, fixable))
        spent = self.attempted_rounds(rounds)
        plan, direct = self.repair_plan(gate, fixable, rounds)
        same = next((i for i, r in enumerate(spent) if r.get("keys") == keys), None)
        if same is not None:
            reason = "same_set"
        elif len(spent) >= GATE_REPAIR_CAP:
            reason = "cap"
        elif not plan:
            reason = "no_move"
        else:
            reason = ""
        if reason:
            return self.gate_stop(gate, series, stage, fixable, direct, keys, reason, same)
        number = len(spent) + 1
        print(f"gate {gate} rehearsal: {len(fixable)} thing(s) the factory repairs before anyone is asked "
              f"({self.finding_counts(fixable)}) — repair round {number} of {GATE_REPAIR_CAP}")
        before = list(rounds)       # what the preconditions count: this round is not spent yet
        record = {"at": _now(), "keys": keys, "moves": [], "outcome": "started", "stop": ""}
        self.record_round(gate, series, record)
        # The plan was made BEFORE the first move; each precondition is read again at its turn, because the
        # moves before it change what it reads (the re-pin makes the reworked cases pinned, which the
        # critic's scope is cut by).
        for precondition, move, mine, _planned in plan:
            found = getattr(self, precondition)(gate, mine, pin_planned=False, rounds=before)
            if not found or found.get("direct"):
                continue
            try:
                getattr(self, move)(gate, mine, found, record)
            except RepairFailed as failure:
                # A failed repair is never silent and never repeated blindly: it is printed, recorded as the
                # round's outcome (the series stops), and the conductor gets the command and the last 20
                # lines of its output.
                code = re.search(r"\(exit (\d+)\)", failure.text)
                what = f"{failure.what} failed" + (f" (exit {code.group(1)})" if code else "")
                print(f"gate {gate} repair: {what} — its output goes to the conductor")
                record.update(outcome="failed", stop="failed")
                self.record_round(gate, series, record)
                tried = (f"{what}; the last lines of its output:\n"
                         + "\n".join(failure.text.splitlines()[-20:]))
                rest = [f for f in fixable if f not in direct]
                return self.hand_to_conductor(gate, stage, "a repair command failed", rest, direct, tried, fixable)
        rest = [f for f in fixable if f not in direct]
        if not record["moves"]:
            # every precondition that held at planning time no longer held at its turn: nothing was done
            record.update(outcome="to_conductor" if rest else "shown", stop="no_move")
            self.record_round(gate, series, record)
            return self.hand_to_conductor(gate, stage, "no code move applied when its turn came", rest, direct,
                                          "", fixable)
        record["outcome"] = "repaired"
        self.record_round(gate, series, record)
        # t-214 C2: the moves changed what the stage's closing step rendered (the case appendix embeds the
        # pinned cases; the report block follows the facts), so the next gate entry renders it again, AFTER them.
        self.state.setdefault("gate_entry_owed", {})[stage] = _now()
        self.save_state()
        shown["ran"] = True
        return shown

    def gate_stop(self, gate: str, series: dict, stage: str, fixable: list, direct: list, keys: list,
                  reason: str, same) -> dict:
        """The series stops (F4, C12): the stop is a record of its own, with its reason; what is not `direct`
        goes to the conductor ONCE (a following await_gate shows the gate: C6); what is `direct` is only listed."""
        rest = [f for f in fixable if f not in direct]
        spent = self.attempted_rounds(series["rounds"])
        if reason == "same_set":
            print(f"gate {gate} repair: round {len(spent)} left the same {len(fixable)} thing(s) as round "
                  f"{same + 1} — the list goes to the conductor; no further round")
            why = f"round {len(spent)} left the same findings as round {same + 1}"
        elif reason == "cap":
            print(f"gate {gate} repair: the cap of {GATE_REPAIR_CAP} rounds is spent with {len(fixable)} thing(s) "
                  "left — the list goes to the conductor; no further round")
            why = f"the cap of {GATE_REPAIR_CAP} repair rounds is spent"
        else:
            print(f"gate {gate} repair: {len(fixable)} thing(s) no code move repairs — "
                  + ("the list goes to the conductor" if rest else "the gate is shown with them at its top"))
            why = "no code move applies to them"
        tried = "; ".join(f"round {i}: " + (", ".join(r.get("moves") or []) or "no move") + f" ({r.get('outcome')})"
                          for i, r in enumerate(spent, 1))
        record = {"at": _now(), "keys": keys, "moves": [], "outcome": "to_conductor" if rest else "shown",
                  "stop": reason}
        self.record_round(gate, series, record)
        return self.hand_to_conductor(gate, stage, why, rest, direct, tried, fixable)

    def hand_to_conductor(self, gate: str, stage: str, why: str, rest: list, direct: list, tried: str,
                          fixable: list) -> dict:
        """The list goes to the conductor through `conductor_round` - the call an unmatched refusal gets - and
        NOT through `handle_refusal`: that matches its table anywhere in the text, and a finding that holds
        `already completed` or `expected_revision` would turn into `continue` or `retry`. Nothing for the
        conductor (only `direct` findings): the gate is shown, with them stated at its top."""
        if not rest:
            return {"ran": False, "top": self.unrepaired_text(gate, fixable)}
        self.boundary = f"gate_{gate}"
        try:
            self.conductor_round(Refusal(self.conductor_text(gate, why, rest, tried)), stage)
        finally:
            self.close_reporter_bound(rest)       # B-416 N4: the bound is the CALL - it runs whatever the conductor did or raised
        return {"ran": True, "top": ""}

    def unadapted_reporters(self, fixable: list) -> list:
        """The `s5_reporter` findings of a list that have NO countable row of the helper's yet (B-416 N4): the test reports the conductor has
        not had its one turn for. A finding whose bound could not be recorded (`adapt_handed`) is left to the top of the gate, never handed
        again and again."""
        import report_adapt
        stuck = set(self.state.get("adapt_handed") or [])
        return [f for f in fixable if f.get("check") == "s5_reporter" and f.get("profile") and f.get("argv_digest")
                and f"{f['profile']}|{f['argv_digest']}" not in stuck
                and report_adapt.countable(self.project, str(f["profile"]), str(f["argv_digest"]))["state"] == "none"]

    def close_reporter_bound(self, findings: list) -> None:
        """B-416 N4 (G5, G10): after the conductor's turn, an `s5_reporter` finding with still no countable row gets the driver's own
        `not_adapted` row (`by: driver`, "the helper was called and recorded nothing"), so the NEXT rehearsal cards the person - exactly one
        conductor call per command since its last proof, whatever the conductor wrote, hit or did not. A row the conductor did write
        (`kind`, `understood`) is left alone; an unreadable record reads as a row (FR-59) and gets none. A failed append is printed and
        remembered (`adapt_handed`): it is not tried again and the finding stays at the top of the gate. Never raises."""
        try:
            import report_adapt
            for finding in [f for f in findings if f.get("check") == "s5_reporter" and f.get("profile") and f.get("argv_digest")]:
                profile, digest = str(finding["profile"]), str(finding["argv_digest"])
                key = f"{profile}|{digest}"
                if report_adapt.countable(self.project, profile, digest)["state"] != "none":
                    self.state["adapt_handed"] = [k for k in self.state.get("adapt_handed") or [] if k != key]
                    continue
                row, problem = report_adapt.append(self.project, {"kind": "not_adapted", "by": "driver", "profile_id": profile,
                                                                  "argv_digest": digest, "story": self.task,
                                                                  "understood": report_adapt.NOT_CALLED_TEXT})
                if row is None:
                    print(f"gate repair: the helper's turn for `{profile}` could not be recorded ({problem}); the report stays at the top of the gate")
                    self.state["adapt_handed"] = list(dict.fromkeys(list(self.state.get("adapt_handed") or []) + [key]))
                else:
                    print(f"gate repair: the helper recorded nothing for `{profile}`: {row['id']} - the person is asked about it at the gate")
            self.save_state()
        except Exception as exc:
            print(f"gate repair: the helper's turn could not be closed ({type(exc).__name__}: {' '.join(str(exc).split())[:120]})")

    def gate_repair_would(self, gate: str) -> str:
        """`--dry-run`: what the step would do, from the rehearsal alone. Writes nothing and dispatches
        nothing; preconditions that read the controller are not evaluated (they are read at their turn)."""
        try:
            result = self.rehearse(gate)
            findings = result.get("findings") if isinstance(result, dict) else None
            if not isinstance(findings, list):
                raise ValueError("the rehearsal's `findings` is not a list")
        except Exception as exc:
            return (f"would: rehearse gate {gate}, which could not run now ({type(exc).__name__}: "
                    f"{' '.join(str(exc).split())[:120]}); the gate would be shown without it")
        fixable = self.fixable_findings(findings)
        if not fixable:
            return f"would: rehearse gate {gate}, then show the gate: nothing the factory has to repair"
        moves = []
        for row_gate, check, _pre, move in GATE_REPAIRS:
            if row_gate == gate and any(f["check"] == check for f in fixable):
                moves.append(f"{check}: {move.replace('_', ' ')}")
        left = sorted({f["check"] for f in fixable} - {check for g, check, _p, _m in GATE_REPAIRS if g == gate})
        if left:
            moves.append("to the conductor or the top of the gate: " + ", ".join(left))
        return (f"would: rehearse gate {gate}, then repair: " + "; ".join(moves)
                + f" (at most {GATE_REPAIR_CAP} rounds)")

    # --- the loop --------------------------------------------------------------------------
    # t-2181 PC-7, the arrival road (§3.2): one road for "a side became real". Position 1 `arrival_keep` (before the freshness look, resumed
    # stories only), position 2 `arrival_record` (after `accept_no_trace`, before the loop; on the answer run of the changed-ticket question,
    # BEFORE `ticket_rework_step`), then `arrival_rework_step` in the loop turns (step 2, 3 and 5 of §3.2; step 4 is PC-8's).
    ARRIVAL_TOKENS = ("re-ground", "ignore", "stop")       # the three answers of `arrival.not_waiting`; `_answer_arrival_not_waiting` reads them
    ARRIVAL_STAGES = ["S1", "S2", "S5"]                    # data on the record: FL-6 changes the list by cause, not the step
    ARRIVAL_STAGES_FIRST_LOOK = ["S1", "S2"]               # t-2277 FL-6: the list of an arrival after `first_look_stop` (S3 on, no bind round)

    def arrival_keep(self) -> None:
        """Position 1: keeps this command line's launch word - `--mr/--branch/--commit` and `--side <s>=real` - through
        `s0_keep_late_launch`, and records what is NEW as a pending arrival in `launch["arrival"]` (`{source, side}`; it lives until
        `arrive` is written, so it outlives a question asked in this process). A source flag is new when the story is held (awaiting or
        stopped) or the value differs from the one kept. `--side <s>=real` is an arrival word only for a side the story RECORDED and that
        is not real yet (F2): any other name - an unrecorded one, a case variant, a side already real - is said in one line and kept as
        nothing. A STOPPED story given no word prints its line and ends the run (`_act_awaiting_stopped` raises `Stop`, exit 0)."""
        if not (self.task_root / "pipeline.json").is_file():
            return
        import contract
        ns, launch, pipeline = self.flags, self.state.setdefault("launch", {}), self.pipeline()
        hold, sides = contract.awaiting(pipeline), contract.story_sides(pipeline)
        held = hold["state"] != "none"
        source = {key: getattr(ns, key) for key in ("mr", "branch", "commit")
                  if getattr(ns, key, None) and (held or getattr(ns, key) != launch.get(key))}
        side = {}
        for name, word in dict(getattr(ns, "side", None) or ()).items():
            if word != "real":
                continue
            if name in sides and sides[name]["reality"] != "real":
                side[name] = word
            else:
                print(f"{self.task}: `{name}` is not a part of this story's product that was waiting; nothing changed for it")
        self.s0_keep_late_launch()
        if source or side:
            pending = launch.setdefault("arrival", {})
            pending["source"] = {**(pending.get("source") or {}), **source}
            pending["side"] = {**(pending.get("side") or {}), **side}
            self.save_state()
        if hold["state"] == "stopped" and not launch.get("arrival"):
            self._act_awaiting_stopped({"action": "awaiting_stopped", "cause": hold["cause"], "held_from": hold["held_from"],
                                        "at": (hold.get("stopped") or {}).get("at"), "words": (hold.get("stopped") or {}).get("words")})

    @staticmethod
    def side_set_args(name: str, **attrs) -> list:
        """`["sides.<name>.<attr>=<value>", ...]` - the `stage_done.py --set` items of ONE side's record (the one spelling for the arrival
        and for the S1 `not built yet` answer; the twin of `s0_sides_sets`, which applies the same keys before `pipeline.json` exists)."""
        return [f"sides.{name}.{attr}={value}" for attr, value in attrs.items()]

    def sides_reread(self) -> None:
        """t-2181 PC-1b (E-U1, AR-25): a relaunch re-reads the project's record of sides when S0 could not (`pipeline.sides_unknown`).
        Nothing happens for a story that is not marked (no `pipeline.json`, or no mark). The registry is read for the story's own stand
        (`pipeline.environment`); a read that still fails or holds a malformed row keeps the mark and says why in one line. A clean
        read clears the mark and, when the story has no `pipeline.sides` yet, records the registry's non-real or referenced sides
        (`source: registry`) in the SAME `stage_done` call, so the clear and the record land together. The Thens proven while the mark
        stood keep their stamp (PC-5 owns that). INVARIANT: an unreadable registry is never read as real, and the mark never clears
        without a clean read."""
        if not (self.task_root / "pipeline.json").is_file():
            return
        pipeline = self.pipeline()
        if not pipeline.get("sides_unknown"):
            return
        import contract
        read = contract.registry_sides(self.project, pipeline.get("environment"))
        if read["problem"]:
            print(f"{self.task}: the project's sides are still unknown ({read['problem']})")
            return
        sets, now = ["sides_unknown="], _now()
        if not pipeline.get("sides"):
            entries = {}
            for name, row in sorted(read["sides"].items()):
                if row["reality"] and (row["reality"] != self.SIDE_REAL or row["reference"]):
                    entries[name] = row
            if entries:
                if not read["product_rows"]:
                    entries.setdefault("product", {"reality": self.SIDE_REAL, "deliverable": True, "settles_by": "", "reference": None})
                for name, row in entries.items():
                    attrs = {"reality": row["reality"], "source": "registry", "at": now}
                    if row["deliverable"] is not None:
                        attrs.update(deliverable="true" if row["deliverable"] else "false")
                        if row.get("settles_by"):
                            attrs.update(settles_by=row["settles_by"])
                    if row["reference"]:
                        attrs.update(reference=row["reference"])
                    sets += self.side_set_args(name, **attrs)
        self.py("stage_done.py", "--task", self.task, *[part for item in sets for part in ("--set", item)], check=True)
        print(f"{self.task}: the project's sides were read again; the mark `sides_unknown` is cleared")

    def arrival_record(self) -> None:
        """Position 2: a pending arrival is recorded - `implementation_source` and the sides through `stage_done.py --set`
        (`source: arrival`), then the controller event `arrive`, which clears the hold - and the rework it owes is put on the record
        (`state["arrival_rework"]`, §3.2 steps 2, 3, 5) in the SAME save that spends the pending word, so a crash anywhere replays from
        one of the two records. A bare source flag makes real the sides that are `absent` and this story's own; `--side` names the
        others. A story with every side real and nothing held asks `arrival.not_waiting` first (E-A5 b): the flag is never silently
        dropped and never silently re-grounds a finished story; the answer is read from `launch["arrival"]["answer"]`, which
        `_answer_arrival_not_waiting` writes (FR-7: the question is not asked again with the same text). `becomes` and the hold's
        `since` are stored on the pending word BEFORE the first write (F3), so a replay after a partial crash records the same sides
        under the same key."""
        if not (self.task_root / "pipeline.json").is_file():
            return
        import contract
        launch, pipeline = self.state.setdefault("launch", {}), self.pipeline()
        hold, sides = contract.awaiting(pipeline), contract.story_sides(pipeline)
        pending = launch.get("arrival")
        if not pending:
            return
        source, named = dict(pending.get("source") or {}), dict(pending.get("side") or {})
        if "becomes" not in pending and hold["state"] == "none" and all(s["reality"] == "real" for s in sides.values()) and not named:
            # E-A5 (b): nothing is held, every side is real. A word recorded here (`becomes`) is past this question: a replay never asks it.
            answer = str(pending.get("answer") or "")
            if answer == "ignore":
                launch.pop("arrival", None)
                self.save_state()
                return
            if answer == "stop":
                launch.pop("arrival", None)
                self.save_state()
                raise Stop(EXIT_DONE, f"{self.task}: stopped at your word; nothing was run and nothing was changed")
            if answer != "re-ground":
                raise Person("arrival_not_waiting", self.closed_question(
                    "arrival.not_waiting",
                    f"You started {self.task} again with the code that is to be tested ({', '.join(sorted(source))} given), but the story "
                    "was not waiting for code: every part of the product it tests is already real, and it has been tested against "
                    "what existed. Nothing has been run for this word yet.\n\nWhat should the code you named do?",
                    [{"answer": "re-ground", "token": "re-ground", "slots": {"stages": "the reading of the code, the requirements and the tests"},
                      "says": "treat it as new code for this story: the story is read again against it"},
                     {"answer": "ignore", "token": "ignore",
                      "says": "drop the word and go on with the story as it stands"},
                     {"answer": "stop", "token": "stop", "says": "stop here: nothing runs now and the story stays as it is"}]), "S0")
        if "becomes" not in pending:
            # the sides that become real: the ones named (`--side <s>=real`), else - a bare source flag - the absent sides this story delivers
            pending["becomes"] = sorted(named) or sorted(name for name, s in sides.items()
                                                         if s["reality"] == contract.PARKING_REALITY and s["deliverable"] is True)
            pending["since"] = str(hold.get("since") or "")
            pending["cause"] = str(hold.get("cause") or "")        # t-2277 FL-6: stored with `becomes`, so a replay owes the same stages
            self.save_state()
        becomes, since = list(pending["becomes"]), str(pending.get("since") or "")
        sets, now = [], _now()
        for name in becomes:
            sets += self.side_set_args(name, reality="real", source="arrival", at=now)
        if source:
            sets.append("implementation_source=diff")
        if sets:
            self.py("stage_done.py", "--task", self.task, *[part for item in sets for part in ("--set", item)], check=True)
        self._arrive(becomes, source, [becomes, source, since])
        # §3.2 steps 2, 3, 5: the stages that were made without the code are made again - S1 and S2 over it, then the bind round of S5.
        # Written with the spend of the pending word in ONE save; `before` holds the earlier `source_arrived` reworks, so a second
        # arrival is owed its own. The stage list is data on the record (FL-6 selects it by cause).
        reason = ("the code this story waits for has arrived (" + ", ".join(f"{key} {value}" for key, value in sorted(source.items()))
                  + (", " if source and becomes else "") + (", ".join(becomes) + " now real" if becomes else "")
                  + "): read the story again against it")
        # t-2277 FL-6 (B2): the code that arrives after the first look stopped the story re-reads the story (S1, S2) and goes on from S3 -
        # no bind round (S5 never ran) and no affected rows (steps 4-5 of §3.2 do not apply); the stage list is data chosen by the hold's cause
        import controller as CT
        stages = list(self.ARRIVAL_STAGES_FIRST_LOOK if pending.get("cause") == CT.FIRST_LOOK_STOP else self.ARRIVAL_STAGES)
        self.state["arrival_rework"] = {
            "stages": stages, "reason": reason, "at": _now(),
            "before": sorted(self.rework_dispatches(self.controller_state().get("dispatches") or {}, "source_arrived", by_person=False))}
        launch.pop("arrival", None)             # the record is written: the pending word is spent
        self.save_state()
        print(f"{self.task}: the code arrived ({', '.join(becomes) or 'no side named'} real); "
              + ("the hold is lifted" if hold["state"] != "none" else "recorded") + "; the stages that ran without it are made again from it")

    def arrival_rework_step(self) -> bool:
        """One move of the rework the arrival owes (`state["arrival_rework"]`, §3.2 steps 2, 3, 5), or False when none is owed. Run each
        turn of the loop right AFTER `ticket_rework_step` (a changed ticket stays first, E-A2) and before `seam_rework_step`. The shape
        of `ticket_rework_step`, one stage per turn, by cause `source_arrived`: the stage's primary role (`stages.json`) goes back over
        its accepted work (S1, S2 with `complete=True`; S5 with `purpose="bind"`: the round that settles the provisional rows and runs the
        pending instances). A stage with no accepted work of its role gets one line and is skipped; one set aside before it was accepted
        ends the list with one line. After the last stage the record is dropped and `where` reads on (E-A3: a side still absent parks the
        story again). True: this turn moved something, ask `where` on the next one. Step 4 (the affected rows) is PC-8's: an absent
        `affected` list of the tester reads as none affected, said once in the line that ends the list."""
        owed = self.owed_rework("arrival_rework")
        if owed is None:
            return False
        pending, dispatches = owed
        import controller as C
        set_aside = C.DISCOUNTED - {C.NEVER_STARTED}
        stages = list(pending.get("stages") or [])
        while stages:
            stage = stages[0]
            role = str((self.stages().get(stage) or {}).get("role") or "")
            mine = [d for did, d in self.rework_dispatches(dispatches, "source_arrived", by_person=False, stage=stage).items()
                    if did not in (pending.get("before") or [])]
            status = mine[-1].get("status") if mine else None
            if status == "accepted":
                stages.pop(0)
                pending["stages"] = stages
                self.save_state()
                continue
            if mine and status in set_aside:
                print(f"{self.task}: the re-run of {stage} for the arrived code was set aside before it was accepted; nothing more is "
                      "made again for it")
                stages = []
                pending["stages"] = stages
                self.save_state()
                break
            if mine:
                return False
            if not any(d.get("stage") == stage and d.get("role") == role and d.get("status") == "accepted" for d in dispatches.values()):
                print(f"{self.task}: {stage} has no accepted work to make again for the arrived code; skipped")
                stages.pop(0)
                pending["stages"] = stages
                self.save_state()
                continue
            if self.dry:
                print("dry run: the rework the arrival owes is not started")
                return False
            reason = str(pending.get("reason") or "the code this story waits for has arrived: read the story again against it")
            if stage == "S5":
                self.rework(stage, role, [], reason, cause="source_arrived", purpose="bind")
            else:
                self.rework(stage, role, [], reason, cause="source_arrived", complete=True)
            return True
        print(f"{self.task}: the stages are made again for the arrived code; the tester's list of the rows it affects is not read here "
              "(a later step), so no row is reopened and gate A stands")
        self.drop_record("arrival_rework")
        return True

    def _arrive(self, sides: list, source: dict, key_parts: list) -> None:
        """t-2562 F-2 (AR-13, AR-15): THE `arrive` request of the driver - the sides that become real or substituted, the source flags, the
        revision of now and an idempotency key over `key_parts` (each caller owns its parts, so a replay finds the same key). The hold's
        `since` is read by the callers through `contract.awaiting`, never from the raw controller state."""
        state = self.controller_state()
        self.controller("arrive", input_data={"sides": sides, "source": source, "expected_revision": state.get("revision", 0),
                                              "idempotency_key": "arrive:" + hashlib.sha256(
                                                  json.dumps(key_parts, sort_keys=True).encode()).hexdigest()[:16]})

    def _act_await_implementation(self, action: dict) -> None:
        """`await_implementation` (S5 is done and a side this story delivers is absent: record the wait) and `awaiting_implementation`
        (the wait is recorded; E-A4: a relaunch with no flag re-prints and dispatches nothing). The packet `interim-report.md` is
        assembled by code from data (`interim_packet.py`, rebuilt each time: a ticket rework while waiting may have rewritten tests)
        and printed; the run then ends with exit 0. No gate B, no verdict, no bug (D2). The packet is chosen by the cause (t-2277 FL-6):
        `first_look_stop` prints `first_look_packet` (what the stand showed), any other cause the S5 packet. A bare relaunch of a
        `first_look_stop` hold first asks `first_look_code_look` whether the code moved: True = the arrival is recorded and the loop goes on
        (INVARIANT: no role of a stage from S3 on starts before an arrival or a `continue`)."""
        import contract
        import controller as CT
        import interim_packet
        first_look = action.get("cause") == CT.FIRST_LOOK_STOP
        if first_look and action.get("action") == "awaiting_implementation" and self.first_look_code_look(action):
            return
        waiting = {name for name, side in contract.story_sides(self.pipeline()).items()
                   if side["reality"] == contract.PARKING_REALITY and side["deliverable"] is True}
        write = interim_packet.write_first_look if first_look else interim_packet.write
        path = write(self.task_root, self.continue_command(drop_absent=waiting))         # F7: no `--side <s>=absent` beside `--branch`
        if action.get("action") == "await_implementation":
            state = self.controller_state()
            # F8: the S5 dispatch the wait is about is the newest ACCEPTED one (a superseded, stale or rejected round is no basis)
            s5 = [did for did, d in (state.get("dispatches") or {}).items()
                  if isinstance(d, dict) and d.get("stage") == "S5" and d.get("status") == "accepted"]
            # (e): the cause and the place the hold starts at travel from the action when it names them (the controller emits them)
            self.controller("await", input_data={"packet": path.name, "s5_dispatch": s5[-1] if s5 else None,
                                                 **{key: action[key] for key in ("cause", "held_from") if action.get(key)},
                                                 "expected_revision": state.get("revision", 0),
                                                 "idempotency_key": f"await:{state.get('revision', 0)}"})
        print(path.read_text(encoding="utf-8"))
        if not first_look and waiting:
            # t-2559 (W2 B3, t-2562 B-1/B-2): on BOTH actions (the hold was just recorded, or it is met again) the factory says what it waits
            # for and asks whose a missing side is, ONE question per side not yet answered for THIS hold (`_absent_side_next`, keyed by the
            # hold's `opened`), so the `not ours` door the packet and `next` name exists on every road (a crash, a lost question file,
            # a bare relaunch). FR-7 is kept by a changed lead, never by silence.
            # remains: a closed question over the story's own state (the `first_look.same_code` shape); every answer has an executor (`_answer_absent_side`)
            person = self._absent_side_next(waiting, str(action.get("held_from") or "S6"))
            if person is not None:
                raise person
        raise Stop(EXIT_DONE, f"{self.task} is waiting for the code; nothing runs until it arrives "
                              f"(the report is qa-factory/artifacts/{self.task}/{path.name})")

    def _act_awaiting_stopped(self, action: dict) -> None:
        """`awaiting_stopped`: the person ended the wait; nothing is relaunched. Prints the stopped line with the doors and ends the run
        with exit 0 (E-W1). A relaunch with the code (`arrive`) or a rework of the stages before `held_from` with words is the way out."""
        held = str(action.get("held_from") or "S6")
        said = " ".join(str(action.get("words") or "").split())[:200]
        import controller as CT
        if action.get("cause") == CT.FIRST_LOOK_STOP:
            # t-2277 FL-6 (J-9 does not apply: the person ended this wait): the line names the first look, not a missing side
            print(f"{self.task}: this story was stopped on {str(action.get('at') or '')[:10] or 'an earlier day'} after the first look, "
                  "when the feature did not work" + (f": \"{said}\"" if said else "") + ". Nothing runs. To check new code, start the story "
                  "again with --mr <link>, --branch <name> or --commit <sha>.")
            # remains: the person ended this wait (J-9 does not apply); the line is the answer and the run ends with exit 0, as the stop below
            raise Stop(EXIT_DONE, f"{self.task} is stopped; no stage runs")
        print(f"{self.task}: the wait for the code was ended on {str(action.get('at') or '')[:10] or 'an earlier day'}"
              + (f" at your word: \"{said}\"" if said else "") + f". Nothing from {self.stage_place(held)} on runs. "
              "To take it up again, start the story again and name where the code is, or ask for the earlier stages to be made again, "
              "with your words.\n\nHow to start it again: --mr <link>, --branch <name> or --commit <sha>; for one part of the product "
              "only, --side <name>=real.")
        raise Stop(EXIT_DONE, f"{self.task} is stopped; no stage runs")

    # --- the code look of a story held after the first look (t-2277 FL-6, J-9 (b), N3) ----------------------------------------------
    def first_look_code_look(self, action: dict) -> bool:
        """A relaunch with NO flag of a story held for `first_look_stop`: did the code move since the first look? True = it did (or the
        manifest names an implementation the record does not): the arrival is recorded with the earlier source (`arrival_record`, the road of
        a flag) and the caller returns, so the loop owes S1, S2 and then S3. False = nothing more is owed here: the caller prints the packet
        and ends the run (exit 0). Otherwise the closed question `first_look.same_code` is raised (`Person`).
        RULE (N3, FR-59, AR-28): ANY repository moved (recorded and live are both commits and differ) or a NEW entry -> arrive; else a
        repository whose recorded or live head is not a commit (`unmeasured`, network, checkout, timeout) or that the story no longer names ->
        the question with ONE line per such repository, never "moved"; else (all equal) the question with no such line. The person
        decided in THIS process (`answer_kind`): the `stop` of `first_look.dead` ends at once (False); `wait` ends with the packet (False),
        `source` prints the restart command and ends (Stop) - the question is not asked again over the answer just taken (FR-7)."""
        import first_look as FL
        kind = self.answer_kind
        if kind == "first_look_dead":
            return False
        if kind == "first_look_same_code":
            said = [row for row in _read_jsonl(self.state_dir / "driver-answers.jsonl") if row.get("kind") == "first_look_same_code"]
            if said and said[-1].get("token") == "source":      # the FIRST line of the answer: `_same_code_answer` records it so
                import contract
                import interim_packet
                waiting = {n for n, s in contract.story_sides(self.pipeline()).items() if s["reality"] == contract.PARKING_REALITY and s["deliverable"] is True}
                print("\n".join(interim_packet.restart_lines(self.continue_command(drop_absent=waiting))))
                # remains: the person chose `source` - the restart command is the whole answer and the run ends with exit 0 (the hold stands)
                raise Stop(EXIT_DONE, f"{self.task} waits for the code; nothing runs until it arrives")
            return False
        found = self._first_look_heads(FL)
        if found["moved"] or found["new"]:
            launch = self.state.setdefault("launch", {})
            pending = launch.setdefault("arrival", {})
            pending["source"] = {**(pending.get("source") or {}), **{key: launch[key] for key in ("mr", "branch", "commit") if launch.get(key)}}
            pending.setdefault("side", {})
            self.save_state()
            print(f"{self.task}: the code changed since the first look ({', '.join(found['moved'] + found['new'])}); it arrives")
            self.arrival_record()
            return True
        # remains: a closed question over the story's own state (the `first_look.dead` shape): every answer has an executor (`_same_code_answer`)
        raise self._first_look_same_code_person(FL, found)

    def _first_look_heads(self, FL) -> dict:
        """The comparison the rule of `first_look_code_look` stands on, for EVERY repository of the first look's record: `{moved, new,
        same, unknown: [(repo, why)], recorded, record, details}`. The record is read through `first_look.read` (one reader, AR-13), the
        implementation entries through `first_look.source_entries` (the one naming of them). Every `why` is plain words (human-questions.md);
        the factory's own words behind it (git's refusal, a stored value) are in `details`, which the question carries as its details file.
        A merge request's live head is asked by `git ls-remote origin refs/merge-requests/<number>/head` in the checkout of that repository
        (`repo_of_project`, `ls_remote_head`), a branch's the same way with `refs/heads/<branch>`; a commit does not move. Nothing raises:
        a doubt is a line."""
        record = FL.read(self.task_root)
        out = {"moved": [], "new": [], "same": [], "unknown": [], "recorded": dict(record["source_head"]), "record": record, "details": []}
        entries = FL.source_entries(self.task_root)
        if record["problem"] and not record["source_head"]:
            out["unknown"].append(("the repositories", "the record of the first look cannot be read"))
            out["details"].append(f"the record of the first look: {record['problem'][:160]}")
            return out
        for key, was in sorted(out["recorded"].items()):
            entry = entries.get(key)
            if entry is None:
                out["unknown"].append((key, "the story's record of the code no longer names this repository" if entries
                                       else "the story's record of the code is empty or cannot be read"))
                continue
            live, why, raw = self._first_look_live_head(entry, key)
            if not live:
                out["unknown"].append((key, why))
                out["details"] += [f"{key}: {raw}"] if raw else []
            elif not FL.COMMIT.fullmatch(was):
                out["unknown"].append((key, "the first look did not record which commit it saw"))
                out["details"].append(f"{key}: the recorded head is `{was[:120]}`")
            elif live != was:
                out["moved"].append(key)
            else:
                out["same"].append(key)
        out["new"] = [key for key in entries if key not in out["recorded"]]
        return out

    def _first_look_live_head(self, entry: dict, key: str) -> tuple:
        """`(commit, "", "")` or `("", why, raw)`: the head the source of ONE implementation entry has NOW. `why` is plain words for the
        person, `raw` the factory's own words behind it (for the details file). A merge request (`mr`: a number or a link) is asked of the
        remote in the repository's one checkout (`ls_remote_head`, `refs/merge-requests/<n>/head`); when that gives nothing, the entry's own
        `branch` is asked the same way (a link no number can be read from goes straight to the branch); a `commit` alone is itself. An entry
        that names a merge request or a branch NEVER falls back to its `commit`: the commit is what was seen, it cannot say the code is
        unchanged (AR-28). Any failure is the reason, never a move."""
        import first_look as FL
        import vcs_evidence
        mr, branch, commit = (str(entry.get(name) or "").strip() for name in ("mr", "branch", "commit"))
        iid = vcs_evidence.mr_iid(mr)       # AR-13: the one reader of the manifest's `mr` (the base slice reads its receipt by the same number)
        if iid or branch:
            unusable: list = []
            found = self.repo_of_project(str(entry.get("repo_id") or entry.get("repo") or key), why=unusable)
            if not found:
                return "", "no checkout of it is set up on this machine", "; ".join(unusable) or f"no local checkout of `{key}` is configured"
            asks = ([(f"merge request {iid}", f"refs/merge-requests/{iid}/head", "the merge request is not listed there")] if iid else []) \
                + ([(f"branch {branch}", f"refs/heads/{branch}", "the branch is not listed there")] if branch else [])
            raws = []
            for label, ref, missing in asks:
                head, raw = self.ls_remote_head(found[1], ref, missing)
                if head:
                    return head, "", ""
                raws.append(f"{label}: {raw}")
            return "", f"the remote did not give the current commit of its {'merge request' if iid else 'branch'}", "; ".join(raws)
        if mr:
            return "", "the link to its merge request is not one this machine can read", f"no merge request number in `{mr[:120]}`"
        if FL.COMMIT.fullmatch(commit):
            return commit, "", ""
        return "", "the story's record names no merge request, branch or commit to ask about", ""

    def _first_look_same_code_person(self, FL, found: dict) -> "Person":
        """The closed question `first_look.same_code` as a `Person` (kind `first_look_same_code`, held from S3): the day the story stopped, the
        counts of the record, the heads by repository and, for each repository whose head could not be established, one line saying so
        (FR-59). After an earlier `wait` the text carries its day - read from the rows of answered questions the driver keeps
        (`driver-answers.jsonl`, the carrier `already_answered` reads); a row that does not read gives a question without the line."""
        import contract
        import interim_packet
        pipeline = self.pipeline()
        hold = contract.awaiting(pipeline)
        since = str(hold.get("since") or "")[:10] or "an earlier day"
        record = found["record"]
        lines = []
        if record["problem"] and not record["rows"]:
            lines.append(f"You stopped this story on {since} after the first look at the stand. The record of that look cannot be read now.")
        else:
            share = FL.share(self.task_root, self.config)
            lines.append(f"You stopped this story on {since} after the first look at the stand `{record.get('stand') or pipeline.get('environment')}`: "
                         f"it showed {share['reachable']} of {share['counted']} requirements"
                         + (f" ({share['share']}%)" if share["share"] is not None else "")
                         + f". Every requirement, by what the stand answered: {interim_packet.status_counts(record['rows'])}.")
        waits = [row for row in _read_jsonl(self.state_dir / "driver-answers.jsonl")
                 if row.get("kind") == "first_look_same_code" and row.get("token") == "wait"]
        day = str(waits[-1].get("ts") or "")[:10] if waits else ""
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}", day):
            lines.append(f"On {day} you chose to wait" + ("." if found["unknown"] else "; the code has not changed since."))
        heads = [f"{repo} {interim_packet.short_head(was)}" for repo, was in sorted(found["recorded"].items())]
        lines.append("The code the first look was about, by repository: " + ("; ".join(heads) if heads else "none is recorded") + ".")
        lines += [f"I could not find out whether the code in {repo} has changed: {why}." for repo, why in found["unknown"]]
        lines.append("What I need from you is one of these:")
        options = [{"answer": "wait", "token": "wait",
                    "says": "keep the story stopped and show you the same summary again; nothing runs"},
                   {"answer": "source", "token": "source",
                    "says": "tell me where the new code is: I print the command that starts the story again with it"},
                   {"answer": "continue", "token": "continue",
                    "says": "go on with the plan as it is; the plan reads what the stand showed as an observation, not as the truth"}]
        return Person("first_look_same_code", self.closed_question("first_look.same_code", "\n\n".join(lines), options), "S3",
                      details="\n".join(found["details"]), answer_note="Write `wait`, `source`, `continue`, or your own words (the conductor reads them).")

    ABSENT_SIDE_TOKENS = ("not ours", "relaunch")        # the two answers of `awaiting.absent_side`; `_answer_absent_side` reads them
    SIDE_SUBSTITUTED = "substituted"                      # a word of side-realities.json (the writer refuses any other)

    def _absent_side_next(self, waiting: set, held_from: str) -> "Person | None":
        """t-2562 (B-1, B-2): the question of the hold's next absent side, or None. The answers are kept per hold in
        `state["absent_side_answers"]` = {opened, sides: {name: {token, at}}}; `opened` is the hold's identity (`contract.awaiting`, the
        `await` event's number; a record without it reads as the empty key, so the hold still asks). A side with no answer for this hold is
        asked, the first by name (a crash before the question file was written leaves no answer, so it is asked again). Every side answered
        `relaunch`: in the process of that answer nothing is asked (the exit 0 of old); in a LATER process the first is offered again with
        a lead that names the earlier answer (FR-7: never the same text twice). INVARIANT: a side the person called not ours is never
        waiting, so it is never asked; no waiting side, no question."""
        import contract
        hold = contract.awaiting(self.pipeline())
        opened = "" if hold.get("opened") is None else str(hold["opened"])
        record = self.state.get("absent_side_answers")
        if not (isinstance(record, dict) and record.get("opened") == opened and isinstance(record.get("sides"), dict)):
            record = {"opened": opened, "sides": {}}
            self.state["absent_side_answers"] = record
            self.save_state()
        answers = record["sides"]
        fresh = [name for name in sorted(waiting) if name not in answers]
        if fresh:
            return self._absent_side_person(fresh[0], held_from)
        if getattr(self, "_absent_answered_here", False):
            return None
        again = [name for name in sorted(waiting) if isinstance(answers.get(name), dict) and answers[name].get("token") == "relaunch"]
        if not again:
            return None
        return self._absent_side_person(again[0], held_from, earlier=str(answers[again[0]].get("at") or ""))

    def _absent_side_person(self, name: str, held_from: str, earlier: str = "") -> "Person":
        """t-2559 (W2 B3): the closed question `awaiting.absent_side` as a `Person` (kind `absent_side`) over the side `name`: what the
        factory waits for, and whose the side is. The name is kept in `state["absent_side"]` for the executor (never read back out of the
        question's text, FR-12). `earlier` (the date of an earlier `relaunch` for this hold) changes the lead (FR-7). Plain words only
        (human-questions.md): no stage code, field or path."""
        self.state["absent_side"] = name
        self.save_state()
        if earlier:
            lead = (f"On {earlier} you said you would start {self.task} again when the code exists; the code for the part of the product "
                    f"called `{name}` is still not named, and the story still waits for it. Nothing has been delivered. Whether `{name}` is "
                    f"this team's to make or another team's decides whether the story keeps waiting.\n\nWhat should happen with `{name}`?")
        else:
            lead = (f"The tests for {self.task} are written and reviewed, but the part of the product called `{name}` does not exist yet, and "
                    f"this story is the one that delivers it, so the story waits for its code. Nothing has been delivered. Whether `{name}` is "
                    f"this team's to make or another team's decides whether the story keeps waiting.\n\nWhat should happen with `{name}`?")
        options = [{"answer": "not ours", "token": "not ours",
                    "says": f"`{name}` is another team's: the story does not wait for it, the tests go on against a stand-in for it "
                            "(mocks), and the report lists what was not checked against the real one"},
                   {"answer": "relaunch", "token": "relaunch",
                    "says": "you start the story again when the code exists and say where it is; until then nothing runs"}]
        return Person("absent_side", self.closed_question("awaiting.absent_side", lead, options), held_from,
                      answer_note="Write `not ours`, `relaunch`, or your own words (the conductor reads them).")

    def until_reached(self, action: dict) -> bool:
        if not self.until:
            return False
        stage = str(action.get("stage") or "")
        # F1 (PC-7 critic): `await_implementation`, `awaiting_implementation` and `awaiting_stopped` are NOT here. Their handlers
        # already end the run with exit 0 (`Stop(EXIT_DONE)`), and checked here BEFORE the dispatch they would end `--until gate_B`
        # without the packet and without the `await` record (the story would read "not awaiting" to every reader).
        return (stage in UNTIL_PAST[self.until] or action.get("action") in ("stop", "complete"))

    def dispatch_action(self, action: dict) -> None:
        """One handler per action kind (t-667 D15). The `kind == "..."` forms stay literal: the census of
        `refusal_every_action_has_a_move` reads them. A handler returns what its branch returned (None); `Driver.gate` ends in
        `raise Person`, so `_act_await_gate` never returns normally past the gate. An action with no move reaches the last line."""
        kind = action.get("action")
        if kind == "prepare_stage":
            return self._act_prepare_stage(action)
        if kind == "await_gate":
            return self._act_await_gate(action)
        if kind == "closed":
            return self._act_closed(action)
        if kind == "execute_gate_b":
            return self._act_execute_gate_b(action)
        if kind == "wait_existing_job":
            return self._wait_then_critic(action)
        if kind == "resume_checkpoint":
            return self._act_resume_checkpoint(action)
        if kind == "relaunch":
            return self._act_relaunch(action)
        if kind == "resolve_return":
            return self._act_resolve_return(action)
        if kind == "await_implementation":
            return self._act_await_implementation(action)
        if kind == "awaiting_implementation":
            return self._act_await_implementation(action)
        if kind == "awaiting_stopped":
            return self._act_awaiting_stopped(action)
        if kind == "observe_environment_job":
            self.environment_job(action)
            return
        if kind in ("handoff_ready", "rollover_pending"):
            self.orchestrator_rollover(action)
            return
        raise Refusal(f"the driver has no move for `{kind}`: {json.dumps(action)[:800]}")

    def _act_prepare_stage(self, action: dict) -> None:
        stage = action["stage"]
        self.boundary = stage
        if stage == "S0":
            if (self.task_root / "pipeline.json").is_file():
                self.code_only("S0", "preflight green: S0 closed on a task initialized before it", ["pipeline.json"])
            else:
                self.s0()
        elif stage == "S1":
            self.stage_simple(stage)
        elif stage == "S2":
            self.stage_S2()
        elif stage == "S3":
            self.stage_S3()
        else:
            getattr(self, f"stage_{stage}")()

    def _act_await_gate(self, action: dict) -> None:
        # t-211: the rehearsal comes BEFORE the person. Everything it lists that code can repair is
        # repaired first (a round is dispatched and the loop comes back through `where`); the gate is
        # shown only when nothing is left to repair, or with the remainder stated at its top.
        if action["gate"] == "B":
            # B-364 R18 (F10 c): the person decides gate B knowing whether the requirements moved since a look
            # older than the freshness window - the position phases/s8.md section 2b gives. BEFORE the rehearsal,
            # because a `ticket_changed` question (the new text re-runs S2-S3 and gate A) makes the rehearsal's
            # findings moot; gate A gets no pre-check (s8.md names gate B). Every gate of the entry applies (no
            # controller, ticket not needed, a closed story, another question open) and a failed look is a line.
            self.ticket_freshness_entry()
            # RN1-24 POSITION INVARIANT: after the freshness look (a changed ticket is asked first) and BEFORE the rehearsal and the
            # gate: gate B is never shown while a question about a manual case is unanswered
            self.deferred_step()
        shown = self.gate_repair(action["gate"])
        if shown["ran"]:
            return
        self.gate(action["gate"], top=shown["top"])

    def _act_closed(self, action: dict) -> None:
        # A closed story is not a story with nothing left: the controller says so in its own
        # words — "the retro is the one stage that still runs on a closed story, so its id
        # travels with the answer" — and sends `stage` and `retro_pending` inside the action.
        # The driver had no branch for `closed` at all, so live TP1-13797 run 5 reached
        # the person as "this story is closed, do you want to reopen it?" with gate B just
        # decided and S9 never started. The person's reason then had nowhere to go either,
        # and the same question was asked twice: four conductor calls, $0.45, no move.
        held = [item for item in action.get("held") or [] if isinstance(item, dict) and item.get("dispatch_id")]
        if held:
            # B-331 (C1-6a): work that never started is not started on a closed story without a person's word. The question
            # comes BEFORE the retro (edge 3: the retro reads the story's final state, so it runs after the answer). A story a
            # person reopened for PART of that work asks about the rest the same way (`reopened_at` on the action, B1).
            # remains: the site's own closed question (`run again` / `leave` / `stop`, each with an executor in `_take_closed_held_answer`)
            raise self.closed_held_person(held, reopened=bool(action.get("reopened_at")))
        if action.get("retro_pending") and action.get("stage"):
            self.boundary = str(action["stage"])
            getattr(self, f"stage_{action['stage']}")()
            return
        # A8: a finished story with nothing held says so and nothing more - no promised reopen: the road back to a closed story
        # exists only as the `closed_held` question above, and as a person's own rework through the conductor.
        import story_step
        # Every terminal exit of this method that ends the story keeps `give_back_config` before its Stop (a new terminal branch gets the same call).
        if story_step.give_back_config(self.project, self.task_root, self.task):      # HF5-6: S9 is recorded, the story ends here (a second call reverts nothing: the copy is marked)
            self.rebuild_report()       # F4: the report's "where to look" block carries the revert line (read from the copy); once, a second call has no line
        raise Stop(EXIT_DONE, f"{self.task}: the story is finished; nothing is pending.")

    def _act_execute_gate_b(self, action: dict) -> None:
        """`execute_gate_b` (t-1509, GB-1b): gate B is decided and what the person ordered there is not carried out yet. The
        orders are carried out by `after_gate_B`; the controller then says `closed` (every order done or called off) or says
        this again. A pass that moved no order is NOT repeated blindly (AR-17, FR-48): the first one is looked at again by the
        loop, the second goes to the one seam `no_move` - the conductor, with the person behind it - never a third pass."""
        import controller as C
        self.boundary = "S8:gate_b_orders"
        before = [str(o.get("order")) for o in action.get("orders") or [] if isinstance(o, dict)]
        self.after_gate_B()
        after = C.orders_due(self.controller_state())
        if set(before) - set(after):                    # an order that was due is not any more: something moved
            self.gate_b_idle = 0
            return
        self.gate_b_idle += 1
        if self.gate_b_idle < 2:
            return
        self.gate_b_idle = 0
        words = {"bugs": "the bug reports", "mr": "the merge request"}
        named = " and ".join(words.get(o, o) for o in after or before) or "what gate B decided"
        self.no_move({"why": "threshold", "kind": "refusal", "stage": "S8", "dispatch": "",
                      "lead": f"What you decided at gate B is not carried out yet ({named}), and the factory tried twice without moving it. "
                              "Which of these should happen?",
                      "text": json.dumps({"orders": action.get("orders"), "still_due": after}, ensure_ascii=False)[:2000]})

    def closed_held_person(self, held: list, reopened: bool = False) -> "Person":
        """The `closed.held` question (B-331, C1-6a): a CLOSED story whose work never started. `run again` / `leave` / `stop`, each
        with its executor (`_take_closed_held_answer`, FR-9). The ids the question NAMES are kept in `state["closed_held"]`: one answer
        covers exactly that set (edge 4), whatever `next` lists when the answer arrives. `reopened`: the story was already reopened
        for other work (a partial `run again`), and this is the question about the rest."""
        def piece(item: dict) -> str:
            why = " ".join(str(item.get("reason") or "").split())[:200]
            return f"{self.stage_place(str(item.get('stage') or ''))}, {item.get('role') or ''}" + (f" - {why}" if why else "")
        n = len(held)
        opening = (f"{self.task} was reopened for other work." if reopened
                   else f"{self.task} is finished (gate B is decided, S8 is done).")
        lead = (f"{opening} {n} piece(s) of work never started: "
                + "; ".join(piece(item) for item in held) + ". Starting it "
                + ("needs your words." if reopened else "reopens the story with your words.") + "\n\n"
                "What I need from you is one of these:")
        roles = " and ".join(dict.fromkeys(str(item.get("role") or "") for item in held if item.get("role")))
        text = self.closed_question("closed.held", lead, [
            {"answer": "run again", "token": "run again", "slots": {"role": roles or "the role"},
             "says": "start the work that never started; the story is reopened with your words, and each piece runs, one at a time"},
            {"answer": "leave", "token": "leave",
             "says": "leave it as it is (also when you finish it yourself); the work that never started is recorded as left "
                     "with your words, and nothing asks for it again"},
            self.STOP_OPTION])
        self.state["closed_held"] = {"dispatch_ids": [str(item["dispatch_id"]) for item in held]}
        return Person("closed_held", text, str(held[0].get("stage") or ""),
                      details="The work that never started, as the factory recorded it:\n"
                              + "\n".join(f"{item['dispatch_id']}: {item.get('stage')} {item.get('role')} - {item.get('reason') or ''}"
                                          for item in held))

    def _wait_then_critic(self, action: dict) -> None:
        """`_act_wait_existing_job`, then the stage critic's route over a finished ticket re-run (`ticket_rerun_critic`). The one entry of
        the `wait_existing_job` action and of its `retry`."""
        self._act_wait_existing_job(action)
        self.ticket_rerun_critic(str(action.get("dispatch_id") or ""))

    def ticket_rerun_critic(self, dispatch: str) -> None:
        """The restart route of a ticket re-run of S2/S3 (AR-25, AR-28): the stage has an acceptor, so the author's re-run no longer closes
        it (`completion_for` answers None) and the stage stays `completed` from its first run - nothing would ever enter its critic route
        again, and the re-run would go unreviewed. When the dispatch just finished is that author's accepted `ticket_changed` re-run, the
        stage critic's route runs now and its verdict closes (`stage_critic_completion`). A dispatch still running, another cause, the
        critic's own dispatch or a stage without an acceptor does nothing. Runs AFTER the finish, never before: the critic reads the accepted re-run."""
        record = (self.controller_state().get("dispatches") or {}).get(dispatch) or {}
        stage, role = str(record.get("stage") or ""), str(record.get("role") or "")
        if (record.get("status") != "accepted" or record.get("repair_cause") != "ticket_changed" or stage not in ("S2", "S3")
                or not self.stage_acceptor(stage) or role == self.stage_acceptor(stage)):
            return
        rows = [d for d in (self.controller_state().get("dispatches") or {}).values() if isinstance(d, dict) and d.get("stage") == stage]
        ids = [str(d.get("id")) for d in rows]
        if dispatch in ids and any(d.get("role") == self.stage_acceptor(stage) for d in rows[ids.index(dispatch) + 1:]):
            return          # the critic of this re-run is registered already (a retry that came back here): never a second one
        self.stage_critic_route(stage, role)

    def _act_wait_existing_job(self, action: dict) -> None:
        dispatch = action.get("dispatch_id", "")
        state = self.controller_state()
        record = (state.get("dispatches") or {}).get(dispatch) or {}
        stage, role = str(record.get("stage") or ""), str(record.get("role") or "")
        self.boundary = f"{stage}:{dispatch}"
        words = self.state["pending_words"].get(dispatch)
        if words:
            self.resume_role(stage, role, dispatch, words, complete=self.completion_for(stage, role, record))
            return
        asked = self.state.get("asked") or {}
        if asked.get("dispatch") == dispatch and asked.get("kind") == "questions" \
                and self.question_path().is_file():
            # INVARIANT (t-113 B2, edge x): a threshold stop that nobody has answered is asked again,
            # and is never finished from the role's saved result below - that result is the very
            # handoff the stop held back, so finishing it would close the stage over the questions.
            text = self.question_path().read_text(encoding="utf-8", errors="replace")
            raise Person("questions", QUESTION_HEAD_RE.sub("", ANSWER_BLOCK_RE.sub("", text), count=1).strip(),
                         stage, dispatch)
        saved_path = self.state_dir / "driver-runs" / f"{dispatch}.json"
        saved = _read_json(saved_path)
        if saved.get("result") and self.retire_infra_result(saved_path, saved, role=role, stage=stage,
                                                             dispatch=dispatch):
            saved = {}   # not a result: the interruption is recorded and the branch below continues it
        if saved.get("result"):
            return self._finish_saved_result(saved, role, stage, dispatch, record)
        if (self.state.get("interrupted") or {}).get(dispatch):
            # A call an infrastructure failure cut off: the SAME role goes on, in the session that did
            # work or fresh with a note (`run_claude` decides which). It comes after the person's words
            # and after a valid saved result - both are newer facts than the interruption - and before
            # the `asked` check, which is about a question, and there is none here.
            print(f"{dispatch}: was cut off by an infrastructure failure - continuing it")
            self.run_role(stage, role, scope=list(record.get("scope") or []),
                          extra=self.s3_record_lines(stage, role, record),
                          complete=self.completion_for(stage, role, record),
                          rework={"id": dispatch, "scope": list(record.get("scope") or []),
                                  "line": "Not a rework: continue this dispatch after an infrastructure "
                                          "interruption"})
            return
        asked = self.state.get("asked") or {}
        if asked.get("dispatch") == dispatch and asked.get("kind") in ("halt", "s1_review"):
            text = (self.state_dir / "driver-question.md").read_text(encoding="utf-8", errors="replace")
            raise Person(asked["kind"], text.split("\n", 6)[-1], stage, dispatch)
        if dispatch and dispatch not in self.state["sessions"]:
            # A dispatch this driver never launched (the conductor registered it while
            # lifting a block, TP1-13797 run 3: the manual half of S6). The driver is
            # the only executor here, so the answer to "nobody is running it" is to run it.
            print(f"{dispatch}: registered but never launched by this driver — running it now")
            if stage in self.STAND_STAGES:      # this STARTS a role on the stand: the same check as the stage's entry
                self.stand_check(stage, str(record.get("execution_kind") or ""))
                self.build_check(stage, str(record.get("execution_kind") or ""), cases=list(record.get("scope") or []))
            # F-2 (t-1252, AR-24): this is the road of a conductor's `continue` over a dispatch that a G site registered and did not
            # record (G3 `run_manual_block`, O4 `_act_relaunch`). It starts the role the way the site would have: the `running` record
            # first (`record_running`; a refusal's `retry` is this whole branch), the standing role lines, and - for a relaunched
            # packet - the relaunch reason (the fresh_line and the person's release words, whole). INVARIANT: the packet is registered
            # ONCE (nothing here dispatches); the record comes after the stand and build checks above, so a refused check leaves
            # nothing recorded as running.
            import controller as CT
            labelling = CT.s3_window_of(record) == "labelling"
            scope = list(record.get("scope") or [])
            relaunched = bool(record.get("relaunch_of"))
            self.record_running(stage, role, dispatch, retry=lambda: self._wait_then_critic(action), relaunched=relaunched,
                                rework_of=str(record.get("rework_of") or ""))
            # The registered record's own `reason` is what the role is told (FR-8): the person's words of a conductor rework, whole.
            # `purpose` ("repair_verify") is a word of the controller's, not a reason (C1-2, F3). Window 1 of S3 is not a rework
            # (G1-11): the word `s3_labelling` is never shown as a reason. The role lines are the record-aware ones (G1-11: the S3
            # strategist's window lines ride on its record; merge of C1-7c over G1-11, 21.10).
            reason = (self.relaunch_reason(record, action) if relaunched
                      else str(record.get("reason") or (record.get("purpose") if not labelling else "")
                               or "registered dispatch"))
            self.run_role(stage, role, scope=scope, extra=self.role_lines(stage, role, record),
                          complete=self.completion_for(stage, role, record),
                          rework={"id": dispatch, "scope": scope, "reason": reason,
                                  **({"line": "Not a rework: window 1 of S3 registered and never launched"} if labelling else {})})
            return
        self._liveness_refusal(action, dispatch, record)

    def _finish_saved_result(self, saved: dict, role: str, stage: str, dispatch: str, record: dict) -> None:
        """t-667 D15: the role's saved result finishes the dispatch (the tail `run_role` twins). Returns None (the branch's `return`)."""
        # t-2022 N6: a walk dispatch gets its `after` on THIS road too (a driver killed after the saved result was written and before `walk_after`
        # ended comes back here): idempotent (`after.json`), BEFORE `handoff` and `finish` like `run_role`'s, so the form has its values
        lane, _ = self.walk_reopen(dispatch, reopen=False)          # the items of the walk record only; nothing is opened
        if lane:
            self.walk_after(lane, dispatch, saved)
        digest = self.handoff(role, stage, dispatch, saved)
        # The saved result may be one a refusal resumed (t-217 `resume_on_refusal`) and the role halted in
        # its answer: `run_role` hears a halt before `finish`, and so must the entry that finishes a saved
        # result - a halted role is the person's, and `finish` would close its dispatch over the halt.
        import story_step
        if story_step._declared_halt(self.task_root, story_step.FORM_REL.format(dispatch_id=dispatch), digest):   # CX1-14 (B-2): the one reader
            # O3 (C1-7c, kind T as T1 and O1): the same record, the same invariant (`HALT_RECORD_WHY`); the role is not run again
            self.py_trace("stage_done.py", "--task", self.task, "--stage", stage, "--status", "halted", "--role", role, "--digest", digest,
                          why=HALT_RECORD_WHY)
            raise Person("halt", self.halt_text(stage, role, digest), stage, dispatch,
                         details=str(digest or "").strip() or "the role's final message was empty")
        self.repair_limit_gate(stage, role, dispatch, digest, record.get("scope"), recovering=True)      # t-698 A4: no answer asks
        self.finish(dispatch, digest, complete=self.completion_for(stage, role, record), role=role, stage=stage)

    def _liveness_refusal(self, action: dict, dispatch: str, record: dict) -> None:
        """t-667 D15: the last word of `wait_existing_job` - nothing to resume, finish or ask - always raises a Refusal."""
        # Say what is known about the agent, in the word the evidence supports. The action
        # itself carries no verdict (`next` does not pay for one on every boundary), and
        # the driver prints `liveness=None`, which reads as "nothing is wrong" - while the
        # honest answer is often "nobody can tell". FR-41: the no-evidence state has its own
        # word and it is printed. Five of run 5's first nine questions to a person were this
        # boundary.
        verdict = {"state": "unknown", "evidence": ["liveness could not be read"]}
        try:
            import dispatch_liveness
            verdict = dispatch_liveness.state(self.project, self.task, dict(record, id=dispatch))
        except Exception as exc:
            verdict["evidence"] = [f"{type(exc).__name__}: {exc}"]
        told = {"unknown": "nobody can tell whether its agent is running: this host keeps no "
                            "evidence either way",
                "alive": "its agent is working",
                "abandoned": "its agent is gone",
                "never_started": "its agent never started",
                "returned": "its agent returned"}.get(str(verdict.get("state")), str(verdict.get("state")))
        raise Refusal(f"wait_existing_job {dispatch}: {told} — " +
                      "; ".join(str(item) for item in (verdict.get("evidence") or [])[:3]) +
                      f". The driver holds no result and no question for it: {json.dumps(action)[:500]}",
                      dispatch=dispatch)

    def _act_resume_checkpoint(self, action: dict) -> None:
        dispatch = action.get("dispatch_id", "")
        record = (self.controller_state().get("dispatches") or {}).get(dispatch) or {}
        words = self.state["pending_words"].get(dispatch)
        stage, role = str(record.get("stage") or ""), str(record.get("role") or "")
        self.boundary = f"{stage}:{dispatch}"
        if words:
            # FB-4 (the driver's side of the ONE `resume`, AR-19/AR-15): a dispatch stopped for a person (`blocked` / `paused`) and
            # continued by its own session is made `running` in the controller BEFORE the session goes on, by the command the
            # skill road runs - `story_step.py resume` - so `finish` accepts it and no `S<n>-<role>-2` retry supersedes the role.
            # POSITION INVARIANT: before `resume_role` (it records the stage `running` and runs the session): a role is never
            # resumed over a record the controller did not move; a refusal is a `Refusal` carrying the dispatch and `retry`
            # (this whole step, the G3 pattern of `record_running`), and the words stay in `pending_words`. No known session, or
            # another status (`incomplete`: its agent is gone, the road is the retry packet): nothing is run and the road is as
            # it was - the driver never invents an agent.
            sid = self.session_of(stage, dispatch)      # TR3-6: on a chain the dispatch's own session only
            if record.get("status") in ("blocked", "paused") and sid:
                try:
                    self.py("story_step.py", "resume", "--task", self.task, "--dispatch-id", dispatch, "--agent-id", sid,
                            check=True, expect=f"{dispatch} resumed")
                except Refusal as refusal:
                    refusal.dispatch = dispatch
                    refusal.retry = lambda: self._act_resume_checkpoint(action)
                    raise
            self.resume_role(stage, role, dispatch, words, complete=self.completion_for(stage, role, record))
            return
        raise Refusal(f"resume_checkpoint {dispatch}: {json.dumps(action)[:800]}", dispatch=dispatch)

    def _act_relaunch(self, action: dict) -> None:
        request = action.get("dispatch_request") or {}
        stage, role = str(action.get("stage") or request.get("stage") or ""), str(action.get("role") or request.get("role") or "")
        scope = list(request.get("scope") or [])
        # POSITION INVARIANT: the stand and build checks come BEFORE the packet is dispatched and before
        # the no-packet fallback starts a role - a relaunch on a stand stage registers no dispatch and
        # starts no role until both pass; a refused check leaves the controller's record as it was.
        if stage in self.STAND_STAGES:          # a relaunch STARTS a role on the stand: the same check as the stage's entry
            self.stand_check(stage, str(request.get("execution_kind") or action.get("execution_kind") or ""))
            self.build_check(stage, str(request.get("execution_kind") or action.get("execution_kind") or ""),
                             cases=scope)
        if not request.get("id"):
            # An older controller state names no packet. A fresh `story_step start` is all
            # that is left, and it starts a NEW dispatch: say so, because what the closed one
            # was opened for (its binding, cause, lineage, reason) does not travel with it.
            print(f"relaunch {action.get('closed_dispatch_id') or '?'}: the controller's action "
                  "carries no dispatch_request, so a fresh dispatch is started and the lineage "
                  "(relaunch_of, case versions, repair cause, rework_of, reason) is not carried")
            if (stage, role) == ("S3", "qa-test-strategist"):
                self.stage_S3()             # G1-11: S3 decides its own window (a one-window start here would skip the labelling)
                return
            self.run_role(stage, role, scope=scope, extra=self.role_lines(stage, role),
                          complete=self.completion_for(stage, role, {}))
            return
        if (stage, role) == ("S3", "qa-test-strategist") and not request.get("rework_of"):
            self.s3_check_packet(request)
        # The controller's own packet is the dispatch: it names the closed one (`relaunch_of`)
        # and carries its original binding, cause, lineage and reason. `story_step start`
        # built a new request from the stage and the scope and lost all of it. A refusal of
        # the packet is the controller's word and travels as every other controller refusal
        # of this driver: no fallback to a fresh start, which would be the same work with
        # the contract thrown away.
        self.controller("dispatch", input_data=dict(request))
        # O4 (C1-7c, kind G as G3): the running record is written BEFORE the dispatch's role starts; a non-zero exit is a `Refusal` (the
        # factory's own) and the role is not started over a stage the record does not show as running. The packet above is already
        # registered, so `retry` is record-then-role (the G1/G3 pattern, F-2 of C1-7b): the retry itself registers nothing (the replay
        # of a failed retry reaches `controller("dispatch")` again, and the store returns the existing event for the same key), and
        # the registered dispatch is not left to `where` -> `wait_existing_job` without the relaunch lines on a retry. A conductor's
        # `continue` takes that road, and its never-launched branch (`_act_wait_existing_job`) starts the role WITH the same lines (F-2
        # of t-1252). The refusal carries the dispatch id (E-c8). A rework of accepted work writes no record (`rework_of`: what `start`
        # does after it registers a dispatch, a rework of an accepted stage does not - its stage is already settled), which
        # `record_running` knows with the controller's `completed`.
        def record_then_role() -> None:
            self.record_running(stage, role, request["id"], retry=record_then_role, relaunched=True,
                                rework_of=str(request.get("rework_of") or ""))
            record = (self.controller_state().get("dispatches") or {}).get(request["id"]) or {}
            # t-2277 batch 2b D (critic t-2513 F1, axis 5): the person's `rework S1` reaches the driver as this relaunch; the scout's rework
            # leaves S1 open and the reference window follows it, the same road as `rework()` (None for any other dispatch or no reference)
            window = self.s1_window_owed(stage, role) if request.get("rework_of") else None
            self.run_role(stage, role, scope=scope, extra=self.role_lines(stage, role, record),
                          complete=False if window else self.completion_for(stage, role, record),
                          rework={"id": request["id"], "scope": scope, "reason": self.relaunch_reason(request, action)})
            if window:
                self.s1_reference_window(stage, window)
        record_then_role()

    def s3_record_lines(self, stage: str, role: str, record: dict) -> list:
        """The window lines of an S3 strategist dispatch finished through a recovery branch (the lines the live road gave it); other
        roles get none, as before - except an S7 INVESTIGATION dispatch (P2 M3), which gets the lines of its live road (its targets, caps and
        form note)."""
        import controller as CT
        if (stage, role) == ("S3", "qa-test-strategist") or ((stage, role) == ("S7", "qa-failure-analyst")
                                                             and CT.s7_part_of(record) == "investigation"):
            return self.role_lines(stage, role, record)
        return []

    def s3_check_packet(self, request: dict) -> None:
        """Before the controller's S3 strategist packet is dispatched again (G1-11): a labelling packet prepares the table; a window-2 packet
        (diff world, a table on disk) is held to step 8. A window-2 packet over a table step 8 would send back to window 1 is refused to the
        conductor with `release` as the door (the packet is fixed; window 1 is the driver's next move once it is released)."""
        import controller as CT
        import grounding_table as GT
        import launch_card
        if request.get("purpose") == CT.S3_LABELLING:
            self.s3_prepare()
            return
        if request.get("purpose") == "repair_verify":
            return
        if GT.source_state(self.task_root)[0] != "diff" or not (self.task_root / "work" / "grounding.yaml").is_file():
            return                          # off the diff, or a story that never had a table: nothing to hold the packet to
        back = self.s3_fresh_for_window2()
        if back:
            raise Refusal(f"S3: the window-2 packet {request.get('id')} was never launched, and the table it would plan over is no longer "
                          f"current ({back}). The packet is fixed, so it is not dispatched. Way on: the conductor releases the packet "
                          f"({launch_card.release_door(self.task_root, request.get('id'))}); the driver then runs window 1 again (P22).",
                          dispatch="")
        self.s3_between_windows()           # the same slot `stage_S3` runs: a packet over an unanswered stop does not go out (G2-2, AR-19)

    def relaunch_reason(self, request: dict, action: dict) -> str:
        """What a relaunched role is told about WHY it starts again. A dispatch the person set aside over the exit gate's refusal
        (`fresh`, t-764 A8) says so - the check's lines, the files that stay readable, the person's own words (read once, from the
        controller's record of the release) - and OUTRANKS the packet's `reason` (`reason` is a binding key the controller copies
        into the packet, so it would win otherwise); the packet's own reason follows. Any other relaunch: the packet's reason, else
        the old line."""
        closed = str(request.get("relaunch_of") or action.get("closed_dispatch_id") or "")
        original = str(request.get("reason") or "").strip()
        line = str(((self.state.get("exit_limit") or {}).get(closed) or {}).get("fresh_line") or "")
        released = str(((self.controller_state().get("dispatches") or {}).get(closed) or {}).get("released_by_person") or "").strip()
        if line or released:
            # a release by a person's word of ANY road (the conductor's `restart` too) carries those words: "never reached an agent"
            # is false for a released dispatch
            return ((line or f"The previous attempt at this step ({closed}) was set aside by the person before it was accepted.")
                    + (f"\n\nThe person's words, whole:\n{released}" if released else "")
                    + (f"\n\nThe reason this dispatch carried before:\n{original}" if original else ""))
        return original or f"{closed} never reached an agent; this repeats it"

    def _act_resolve_return(self, action: dict) -> None:
        # A role that stopped without acceptance. `relaunch` has a move and
        # `resume_checkpoint` has a move; this one had none, so the driver raised the
        # packet at the conductor, the conductor has no command for it either (its `did`
        # came back empty), the person was asked, and their words landed on this same
        # line again. Live TP1-13797, run 5: the S5 critic looped person -> conductor
        # -> person with the identical JSON until the loop was read from the code.
        # The person's word decides accept/checkpoint/rework, but only the ROLE can write
        # its own digest, so the move is the one `resume_checkpoint` already makes: hand
        # the words back to the role and let it close itself.
        if self.resume_with_filed_words(action.get("dispatch_id", ""), self.completion_for):
            return
        raise self.resolve_return_refusal(action)

    def resume_with_filed_words(self, dispatch: str, complete_for) -> bool:
        """The ONE move on a returned dispatch whose person's words are filed (TR4-10 B1): hand the words back to the role so it closes its own
        window. Called by `_act_resolve_return` (the controller offered the return) and by `stage_S5` (the controller hides it behind later S5
        work). `complete_for(stage, role, record)` answers the completion rule of the resume. True when the role was resumed (`resume_role`
        spends the words); False when no words are filed for `dispatch` (empty text counts as none, a blank one as words - as before), or
        its record is gone, or names no stage or role: nothing ran and the caller takes its refusal."""
        record = (self.controller_state().get("dispatches") or {}).get(dispatch) or {}
        words = self.state["pending_words"].get(dispatch)
        stage, role = str(record.get("stage") or ""), str(record.get("role") or "")
        self.boundary = f"{stage}:{dispatch}"
        if words and stage and role:
            print(f"{dispatch}: returned without acceptance — resuming the role with the "
                  f"person's words so it closes its own window")
            self.resume_role(stage, role, dispatch, words, complete=complete_for(stage, role, record))
            return True
        return False

    @staticmethod
    def resolve_return_refusal(action: dict) -> "Refusal":
        """The `resolve_return` packet as a Refusal naming the dispatch: ONE builder for `_act_resolve_return` (no words filed) and for
        `stage_S5` (a window held open by a returned last round, TR4-10 D3)."""
        return Refusal(f"resolve_return: {json.dumps(action)[:1200]}", dispatch=action.get("dispatch_id", ""))

    # --- the three actions that are about somebody else's machinery -------------------------
    def environment_job(self, action: dict) -> None:
        """A recorded stand preparation: observe it, never start a second one.

        `observe_environment_job` is the controller's FIRST branch, so an unsettled job
        outranks every other action — and the driver had no move for it at all, which on any
        project that records a stand preparation means the whole loop falls into "the driver
        has no move for X" -> conductor -> a question to a person, while the action's own
        `reason` already says what to do (run 5 never met it only because its stand was
        prepared by hand). `EnvironmentJobs.observe` is the door: it reuses a finished job,
        confirms a live one, and settles an orphan as `blocked` without relaunching it."""
        job_id = str(action.get("job_id") or "")
        self.boundary = f"{action.get('stage') or 'S5'}:environment:{job_id or 'unknown'}"
        receipt = str(action.get("receipt_ref") or "")
        jobs_dir = self.task_root / "state" / "environment-jobs"
        key = str(_read_json(self.task_root / receipt).get("idempotency_key") or "") if receipt else ""
        if not key:
            raise Refusal(
                f"observe_environment_job {job_id or '(no job_id)'}: the job record "
                f"`{receipt or 'state/environment-jobs/<job>.json'}` carries no `idempotency_key`, "
                "and without it the job cannot be observed and must not be started again. "
                "Either repair that file's identity or settle the job by hand: "
                f"`environment_preparation.py status --jobs {jobs_dir} --key <key>`.")
        for attempt in range(1, ENV_JOB_LOOKS + 1):
            code, out = self.py("environment_preparation.py", "observe", "--jobs", jobs_dir, "--key", key)
            try:
                seen = json.loads(out[out.index("{"):out.rindex("}") + 1])
            except (ValueError, TypeError):
                raise Refusal(f"environment_preparation.py observe --key {key} (exit {code}) printed "
                              f"no readable JSON:\n{out[-600:]}")
            status, job = str(seen.get("status") or "unknown"), (seen.get("job") or {})
            if seen.get("settled"):
                print(f"environment job {job_id or key}: settled as `{status}` — the story goes on")
                return
            if seen.get("uncertain_process"):
                # The one state code may not settle: the outcome is unknown and relaunching is
                # forbidden. Saying "still running" here would be the exact thing FR-41 names.
                last = (job.get("steps") or [{}])[-1] if job.get("steps") else {}
                # By hand (C1-1, P31): the person's work is an OPTION with a token; the command that settles the job leaves the
                # body for the answer block (human-questions.md rule 5) and stays there as the way out (FR-57).
                self.no_move({
                    "why": "by_hand", "kind": "environment", "stage": str(action.get("stage") or "S5"), "dispatch": "",
                    "lead": f"The stand preparation `{job_id or key}` stopped without a result and the "
                            f"process that owned it is gone, so nobody can say whether it finished.\n\n"
                            f"- last step: {str(last.get('name') or 'unknown')} "
                            f"({str(last.get('status') or 'unknown')}), phase `{job.get('phase') or 'unknown'}`\n"
                            f"- the record: qa-factory/artifacts/{self.task}/{receipt}\n"
                            f"- I did NOT start it again: a second run of the same preparation is what the "
                            f"job's identity exists to prevent.\n\n"
                            "A read-only probe of the stand settles it; only you know which probe says whether the stand is up. "
                            "Or say in your own words that the stand is not available, and S5 carries it as `env_blocked` "
                            "instead of waiting.",
                    "keep": [f"qa-factory/artifacts/{self.task}/{receipt}"],
                    "answer_note": "To settle the job with a probe: python " + str(self.scripts / "environment_preparation.py")
                                   + f" reconcile --jobs {jobs_dir} --key {key} --probe <probe.json>",
                    "text": f"{job_id or key}: uncertain_process, phase {job.get('phase') or 'unknown'}, record {receipt}"}, None)
                return                  # the conductor took a move: back to `where`, which observes the job again
            print(f"environment job {job_id or key}: `{status}`, its process is alive "
                  f"(look {attempt} of {ENV_JOB_LOOKS}) — waiting, not starting a second one", flush=True)
            time.sleep(ENV_JOB_WAIT_SECONDS)
        self.no_move({
            "why": "threshold", "kind": "environment", "stage": str(action.get("stage") or "S5"), "dispatch": "",
            "lead": f"The stand preparation `{job_id or key}` has been running for "
                    f"{ENV_JOB_LOOKS * ENV_JOB_WAIT_SECONDS // 60} minutes and its process is still alive, so "
                    "I have neither a result to use nor a dead job to settle.\n\n"
                    f"- the record: qa-factory/artifacts/{self.task}/{receipt}\n"
                    "- I did not stop it and did not start a second one.\n\n"
                    "The choice is to keep waiting, or to carry the stand as `env_blocked` and go on.",
            "keep": [f"qa-factory/artifacts/{self.task}/{receipt}"],
            "text": f"{job_id or key}: alive after {ENV_JOB_LOOKS} looks, record {receipt}"}, None)

    def orchestrator_rollover(self, action: dict) -> None:
        """The window counters belong to a model session; this driver has none.

        `handoff_ready` and `rollover_pending` exist for an LLM orchestrator whose context
        window is filling up. A code driver has no window to roll over, so the honest move is
        to take the lease and clear the counters — the takeover the record is asking for is
        the one that already happened. When the takeover is not safe yet, the action names
        what is unsettled and so does the refusal."""
        wait_for = action.get("wait_for") or {}
        blocking = [f"{kind}: {json.dumps(rows)[:200]}"
                    for kind, rows in (("running jobs", wait_for.get("running_jobs")),
                                       ("external writes with no recorded result",
                                        wait_for.get("unknown_external_writes")),
                                       ("running dispatches", wait_for.get("running_dispatches")))
                    if rows]
        if action.get("action") == "rollover_pending" or blocking:
            raise Refusal(
                "the orchestrator window is full and the takeover is blocked by work nobody has "
                "settled:\n- " + "\n- ".join(blocking or ["(the record names nothing)"]) +
                "\nThis driver has no context window, so the rollover itself costs it nothing — what "
                "has to move is the list above. A durable run job is settled with `run_suite.py "
                "--recover <KEY> --task " + self.task + "`, a proposal with `external_writes.py "
                "--record <proposal.json> --external-id <ID>`, and a dispatch through `where`.")
        state = self.controller_state()
        lease = (state.get("leases") or {}).get("orchestrator") or {}
        session = f"driver:{self.task}:{state.get('revision', 0)}"
        print(f"orchestrator rollover: {', '.join(action.get('reasons') or ['window'])} — the driver "
              f"has no context window; taking the lease from `{lease.get('owner_session_id') or 'nobody'}`")
        self.controller("handoff", input_data={
            "owner_session_id": lease.get("owner_session_id") or session,
            "host_capability": "manual_continuation",
            "reason": "the code driver continues this story; it has no context window to roll over",
            "lease": {"owner_session_id": session,
                      "generation": int(lease.get("generation") or 0) + 1},
            "expected_revision": state.get("revision", 0),
            "idempotency_key": f"handoff:driver:{state.get('revision', 0)}"})

    def completion_for(self, stage: str, role: str, record: dict):
        if stage == "S8" and role == "qa-doc-scribe":
            return True
        if stage == "S1" and role == "qa-runner" and (record.get("request_binding") or {}).get("purpose") == "reference_walk":
            # t-2181 PC-9b (critic t-2513 F2, axis 5): the S1 reference window closes the stage - the live road (`stage_simple`) finishes the
            # runner with `complete=True`; the recovery roads (`wait_existing_job`, `resume_role`) get the same answer here, or "the stage's
            # last role closes it" would make the scout the last role and leave S1 open for a SECOND window. POSITION: before every rule below
            return True
        if stage == "S1" and self.s1_window_owed(stage, role):
            # t-2277 batch 2b D (critic t-2548 F2): the S1 scout of a story with a reference does NOT close S1 on any road that finishes it -
            # a relaunch with no `rework_of`, the no-packet fallback, `wait_existing_job` over a saved result, `resume_role`: S1 stays open and
            # the next `where` -> `stage_simple` skips the accepted scout and runs the window (its `complete=True` closes S1). POSITION: after the
            # runner's own rule above (the window closes the stage), before every other rule. A story with no reference gets None here: unchanged
            return False
        if stage in ("S2", "S3") and record.get("repair_cause") == "ticket_changed":
            # B-364 (F12 / Change 10): the ticket re-run of S2 and S3 closes as COMPLETE, which re-captures the plan baseline.
            # Finished through `wait_existing_job` (the restart route) it must say so too: the `rework_of` rule at the end
            # answers False for every rework, and S3's baseline would stay the old plan's - the re-run's changes would later
            # count as the person's overrides. Placed before that rule; nothing else of the order changes.
            # S3 (G1-11) closes through the same callable as the live road (`s3_ticket_completion`: project, refresh, True).
            # X2-7: with an acceptor (`acceptance_by`) the author no longer closes the stage - the stage critic's accept does; the plan
            # baseline is then taken by that closing accept (B-364), and the side steps of S3 stay on the author's finish.
            if self.stage_acceptor(stage):
                return self.s3_ticket_completion(closes=False) if stage == "S3" else None
            return self.s3_ticket_completion() if stage == "S3" else True
        if stage in ("S2", "S3") and role == self.stage_acceptor(stage):
            # X2-7: the recovery road closes S2/S3 by the SAME rule the live route applies (`stage_critic_completion`), the budget read again.
            # POSITION INVARIANT: after the `ticket_changed` branch, BEFORE the `rework_of` rule below (whose silent False would leave the
            # critic's finish refused by the controller for a record the driver owns).
            budget = self.budget_or_none(stage, self.stages()[stage]["roles"][0], []) or {}
            # t-1815 F1: the dispatch is the RECORD's (a fresh process never ran `run_role`, `last_dispatch` is empty or another role's)
            return self.stage_critic_completion(stage, self.stages()[stage]["roles"][0], [], budget.get("counted"), budget.get("cap"),
                                                dispatch_id=str(record.get("id") or ""))
        if stage == "S6" and role == "qa-runner" and str(record.get("id") or getattr(self, "last_dispatch", "")) in {
                str(x) for ids in (self.state.get("s7_rejudge") or {}).values() if isinstance(ids, list) for x in ids}:
            # HF8-19 (t-909 F-4 class): an S7 RE-JUDGE dispatch finished through `wait_existing_job` closes like the live road
            # (`s7_rejudge_round`: `complete=False`). POSITION INVARIANT: BEFORE the S6 qa-runner rule below, which answers `True`
            # for a manual dispatch when no block is left to run - a re-judge writes no S6 completion and is not "the last block".
            return False
        if stage == "S6" and role == "qa-runner":
            # t-261 (C4, the same recovery class as S5 below): a saved result finished through `wait_existing_job` got no
            # answer here, so it took the controller's default and closed S6 over a half nobody had run. The rule is the
            # one `stage_S6` applies when it dispatches: the automation runner closes the stage only when no manual half
            # is left; a manual block closes it only when no other case could still be dispatched. A refused case stops
            # the close only WITHOUT a consumer (the controller refuses a completion over a case no accepted dispatch
            # carried); under a consumer the stage awaits it and manual_close closes the refused case later (X7-6).
            try:
                scope = self.stage_scope("S6", "manual").get("scope") or []
                if record.get("execution_kind") == "manual":
                    mine = [str(c) for c in record.get("manual_case_ids") or record.get("scope") or []]
                    if self.walk_pending(mine):
                        # t-2022 N5: the SAME guard the live road has (`run_manual_block`: `walk_pending(block)`): a case of this lane whose walk
                        # record the build refused is walked once more or closed `left_unchecked`, and the lane that carried it never closes the
                        # stage. POSITION INVARIANT: BEFORE `manual_plan(skip=mine)`, which skips the lane's own cases and so cannot see them
                        return False
                    plan = self.manual_plan(scope, skip=mine)
                    # X7-6: with a consumer the last block stops AWAITING the acceptance (as the live `run_manual_block` does)
                    # t-2239 B1 (X7-6): a refused case does not keep the last block from awaiting; `manual_close` closes it later
                    import acceptance
                    return self.consumer_awaits("S6", not plan["blocks"] and (True if acceptance.consumer_of("S6") else not plan["refused"]))
                return self.consumer_awaits("S6", not scope)
            except Exception:
                return False       # a doubt never closes a stage
        if stage == "S5":
            # The critic of the LAST window closes S5 - the same rule stage_S5 applies when it
            # dispatches. On the recovery path (a saved result finished through
            # `wait_existing_job`) this returned False for every dispatch, so every window was
            # accepted and the stage stayed open forever (TP1-13797, driver run 3).
            if role != "qa-code-critic":
                return False
            try:
                windows = self.stage_scope("S5").get("windows") or []
            except Exception:
                return False
            mine = set(record.get("scope") or [])
            if self.s5_parallel_cap() != 1:
                # TR3-6: other windows through `s5_open_windows` (a running dispatch, an owed round or a live chain keep a window open as
                # well as a missing acceptance); unreadable is open, never a close (FR-59). `mine == scope` is still skipped there.
                try:
                    if self.s5_open_windows(excluding=mine):
                        return False
                except Exception:       # noqa: BLE001
                    return False
            else:
                for window in windows:
                    if set(window.get("scope") or []) == mine:
                        continue
                    if "qa-code-critic" not in (window.get("accepted_by") or {}):
                        return False
            # t-698 A4/L6: the last critic closes S5 only by the SAME rule the loop applies - the route of ITS review (read after the
            # role wrote the form: `finish` evaluates the callable) and the person's answer for THIS critic dispatch.
            cases, dispatch = list(record.get("scope") or []), str(record.get("id") or getattr(self, "last_dispatch", ""))

            def closes(digest: str) -> bool:
                route, _form = self.route_of(digest, self.budget_or_none("S5", "qa-automator", cases, ref=dispatch), dispatch)
                return self.s5_window_closed(route, self.repair_answer(cases, dispatch))
            return closes
        if stage == "S4" and role == "qa-case-critic":
            # C2-4 (t-909 F-4): the recovery road closes S4 by the SAME rule the live stage applies (`s4_critic_completion`). POSITION
            # INVARIANT: BEFORE the `rework_of` rule below, as S7's: a saved critic result finished through `wait_existing_job`
            # must not close S4 over `concerns` with a round left, nor leave a silent `False` for the controller to refuse.
            cases = [str(c) for c in record.get("scope") or []]
            budget = self.budget_or_none("S4", "qa-case-designer", cases) or {}
            return self.s4_critic_completion(cases, budget.get("counted"), budget.get("cap"), dispatch_id=str(record.get("id") or ""))
        import controller as CT
        if stage == "S7" and role == "qa-failure-analyst" and CT.s7_part_of(record) == "investigation":
            # P2 M3. POSITION INVARIANT: BEFORE the S7 branch below (whose callable runs `s7_open_work` and could close S7 over a running
            # pass) and so before the `rework_of` rule: a saved / interrupted / never-launched / resumed / relaunched investigation never
            # closes S7. The purpose is read through `s7_part_of(record)` (the record's binding), never `record.get("purpose")`.
            return False
        if stage == "S7" and role == "qa-failure-analyst":
            # t-698 §18 (C1-5b2): S7 stays OPEN while repair rows remain. POSITION INVARIANT: BEFORE the `rework_of` rule below, whose
            # silent False would let a reworked analyst be refused by the controller (or close S7 over rows): no finish of the S7
            # closing role closes S7 while `s7_repair_rows()` is non-empty (or unreadable).
            # X7-6b: with a consumer (the doc scribe) the analyst's finish that WOULD close S7 stops AWAITING its acceptance instead.
            return lambda digest: self.consumer_awaits("S7", self.s7_open_work())
        if (stage == "S3" and role == "qa-test-strategist" and not record.get("rework_of")
                and record.get("purpose") != "repair_verify"):
            # G1-11 (t-909 F-4 class): the recovery road decides an S3 strategist dispatch by the SAME function as the live stage.
            # POSITION INVARIANT: after the `ticket_changed` branch (its own callable) and BEFORE the `rework_of` rule below, whose silent
            # False would make a saved window-1 result close nothing and a window 2 never close S3.
            return self.s3_window_completion(record)
        if record.get("repair_cause") == "question_answer":
            # HF2-7 (N1, H39): a rework the person's recorded answers opened closes by the stage's own rule on this road too - S3 by
            # its one close rule (the projection, outcome None: `s3_window_completion`), S4's designer by no flag (it is not the stage's
            # last role). POSITION INVARIANT: after the `ticket_changed` branch and the S4-critic / S5-S7 branches, BEFORE the `rework_of`
            # rule below, whose silent False would leave S3 with no closing role (the controller refuses that, `controller.py:3899`).
            return self.s3_window_completion(record) if stage == "S3" else None
        if record.get("rework_of") or record.get("purpose") == "repair_verify":
            # RN1-2 (B-1): an S3 strategist rework projects the plan too. POSITION INVARIANT: the answer stays `False` (the callable
            # returns it); only the projection is added, so nothing that closes a stage changes.
            return self.s3_rework_completion() if stage == "S3" and role == "qa-test-strategist" else False
        return None

    def run(self) -> int:
        self.run_started = _now()       # TR4-11: when THIS process began; the stop record names it (`since`)
        self.progress_line()            # the log header: where the story stands as this process starts
        if not self.state.get("asked"):
            self.state.pop("stuck_pending", None)       # B-20 F6: a mark left by a process that died in the conductor belongs to no open question
        # TR4-11 (F-3): the OUTER try. Ctrl-C reaches here from the loop AND from the run-level handlers of the inner try (a `Refusal` handed
        # to `funnel` can be a paid conductor call): a sibling `except` of the inner try would not see the second kind.
        try:
            return self._run_guarded()
        except KeyboardInterrupt:
            self.person_stop_record()
            raise

    def person_stop_record(self) -> None:
        """TR4-11: the person stopped the run (Ctrl-C, either road): ONE row of `driver-runs.jsonl`, through `journal_run`, so that the
        collector tells the calls THIS process cut off from a driver that died on its own (`collect_stall` K3).

        `{"kind": "stopped_by_person", "who": "person", "at", "since": <run_started>, "cut": [<call id>...]}`; a call id is
        `<dispatch_id or call>@<started_at>` of a `launched` row this process wrote and has seen no end row for (`journal_run` keeps
        the set), so K3 clears exactly those rows and no row of any other process. No `dispatch`, `session_id`, cost, `exit_code`,
        `is_error` or `infra`: every reader that binds sessions, prices or outcomes passes the row by, as it passes a `launched` row.

        Edges: no story folder yet -> nothing is written (Ctrl-C never creates it, and no call was launched); a failed write -> one
        `note:` line; a second Ctrl-C while writing -> the row may be absent (K3 then reads a dead driver: the safe side), the first
        interrupt still goes on. Nothing is printed otherwise; the caller re-raises."""
        try:
            if not self.state_dir.is_dir():
                return
            cut = sorted(f"{key}@{at}" for key, at in list(once_on(self, "_open_calls", set)))
            self.journal_run({"kind": "stopped_by_person", "who": "person", "at": _now(), "since": self.run_started, "cut": cut})
        except OSError as exc:
            print(f"note: the stop by the person could not be journalled ({type(exc).__name__}); it goes on", flush=True)
        except KeyboardInterrupt:
            pass

    def _run_guarded(self) -> int:
        try:
            repaired = self.reconcile_question()
            if repaired:
                print(f"{self.task}: {repaired}")
            if self.flags.answer:
                self.take_answer(Path(self.flags.answer))
            # C1-7a (B-1): the rows the journal refused are written again BEFORE the first step that could build a brief (the changed-ticket
            # rework below dispatches a role). POSITION INVARIANT: after the answer is taken (its own rows are owed by then), before every
            # pre-loop step; the loop's first step is the same call (S2: no brief is built while a row of the person's words is owed).
            self.owed_rows_step()
            self.adopt_legacy_snapshot()
            # B-014: after the answer is taken (a person's word for the switch is recorded there) and
            # before anything is dispatched; a story with no pipeline yet has no mode to switch.
            self.check_run_mode()
            self.report_gap_class_problem()
            self.skip_sources_late()
            # t-2181 PC-7 POSITION (S11): the launch word of a RESUMED story is kept here - after `skip_sources_late`, BEFORE the freshness
            # branch below. INVARIANT: a source word given on this command line survives a question asked in this same process (the
            # changed-ticket question: the answer run carries `--answer`, not `--branch`, and still arrives); a stopped story given no
            # word ends here with its line (`Stop`, exit 0), so no freshness look and no dispatch happen for it.
            resumed = (self.task_root / "pipeline.json").is_file()
            if resumed:
                self.arrival_keep()
            if not resumed:
                print(f"{self.task}: fresh story — S0 by code")
                import story_step
                story_step.keep_config_copy(self.project, self.task_root, self.task)
                self.guarded(self.s0, {"action": "prepare_stage", "stage": "S0"})
            elif self.answer_kind == "ticket_changed":
                # B-364 R4/R12: the run that carries the answer to the changed-ticket question does not look at the
                # ticket again (the person has just chosen); what they chose starts here, as it does at the top of
                # every loop turn below.
                # B4 POSITION INVARIANT (S11): the arrival is recorded BEFORE this rework opens. The answer just taken wrote
                # `ticket_rework` (S2/S3 owed), and `ticket_rework_step` runs the S2 tester on the new text; run first, it would put a
                # role on the story while `pipeline.sides` still says absent and `implementation_source` is not the diff. The person's
                # ticket answer is already taken, so "no role before the ticket answer" still holds; the call after `accept_no_trace`
                # below is then a no-op (the pending word is spent).
                self.guarded(self.arrival_record, {"action": "arrival"})
                self.guarded(self.ticket_rework_step, {"action": "ticket_rework"})
            else:
                # B-364 R4 (D-0027): a resumed story is the one most likely to have been overtaken by an edit in the
                # tracker, so the ticket is looked at ONCE here - after the person's answer was recorded (FR-8: their
                # words come before any new question) and before the next step - and never in a process that just ran
                # S0 (the S0 branch above; K11: an S0 resume does not ask the tracker and leaves the snapshot's hash
                # alone). Whether the baseline is old enough is the adapter's rule, not a decision made here.
                self.guarded(self.ticket_freshness_entry, {"action": "ticket_freshness"})
            # `--no-trace` on a story that has no such record yet (t-017 D3): accepted from here on. A
            # story S0 has just written with the flag already carries it, and this is a no-op.
            self.boundary = "no_trace"
            self.guarded(self.accept_no_trace, {"action": "accept_no_trace"})
            # t-2181 PC-7 POSITION (S11): the arrival is recorded AFTER the freshness branch and `accept_no_trace`, BEFORE the loop.
            # INVARIANT: a changed ticket is asked first (one road: `ticket_changed` and `ticket_rework_step`); no role is dispatched on the
            # new code before the person's answer about a changed ticket is taken; the arrival is on the record before any rework opens,
            # so a crash in between replays from the record (the kept word stays pending until `arrive` is written).
            self.guarded(self.arrival_record, {"action": "arrival"})
            self.guarded(self.sides_reread, {"action": "sides_reread"})   # PC-1b E-U1: a relaunch re-reads the sides S0 could not read
            repeats, previous = 0, None
            for _ in range(self.max_boundaries):
                # B-364 R12: a ticket rework the person chose is owed BEFORE anything `where` could say - the loop
                # would otherwise go on to gate B on stages built from the old text. The step says so when it moved
                # (a stage ran, or the gate was reopened): the turn is spent and `where` is asked on the next one.
                # A refusal the guard handled leaves `moved` empty: the same, the step reads the state again.
                self.owed_rows_step()           # C1-7a (B-1): the first step of every turn - before anything that can dispatch or resume a role
                moved: list = []
                self.guarded(lambda: moved.append(self.ticket_rework_step()), {"action": "ticket_rework"})
                if not moved or moved[0]:
                    continue
                # t-2181 PC-7 (§3.2 steps 2, 3, 5): the rework the ARRIVAL owes comes right after the ticket's (a changed ticket stays
                # first, E-A2) and before the seam's, by the same rule
                arrived: list = []
                self.guarded(lambda: arrived.append(self.arrival_rework_step()), {"action": "arrival_rework"})
                if not arrived or arrived[0]:
                    continue
                # t-722 C2-6: the rework the person chose at the seam is owed right after the ticket's and before `where`, by the same rule
                seamed: list = []
                self.guarded(lambda: seamed.append(self.seam_rework_step()), {"action": "seam_rework"})
                if not seamed or seamed[0]:
                    continue
                # HF2-7: the rework the person's recorded answers owe (the plan rows or cases that still follow the other reading) is
                # opened by code right after the person's chosen rework, by the same rule (P22), before `where` and before a stage is closed
                answered: list = []
                self.guarded(lambda: answered.append(self.answer_rework_step()), {"action": "answer_rework"})
                if not answered or answered[0]:
                    continue
                # C2-8: the record of a stage the code closed (receipt written, `stage_done` refused) is owed after any rework the person
                # chose (it may open the stage again: then the record is dropped, I4) and before `where` reads on from the receipt
                written: list = []
                self.guarded(lambda: written.append(self.code_close_step()), {"action": "code_close"})
                if not written or written[0]:
                    continue
                # B-20: the person's `stage acceptance` word for a stage that awaits its consumer is recorded from any position, after the
                # reworks above (a rework may change the author the word binds to) and before `where` (the router sees the record this turn)
                worded: list = []
                self.guarded(lambda: worded.append(self.consumer_word_step()), {"action": "consumer_word"})
                if not worded or worded[0]:
                    continue
                try:
                    action = self.where()
                except Refusal as refusal:
                    self.boundary = "where"
                    self.handle_refusal(refusal)
                    continue
                signature = json.dumps(action, sort_keys=True)
                repeats = repeats + 1 if signature == previous else 0
                previous = signature
                if repeats >= STUCK_REPEATS:
                    # `where` said the same `STUCK_REPEATS` times: the seam (one call under the cap), then the loop looks again
                    # `keep` (Q2): the place the stuck text names goes above the conductor's prose when that prose drops it. The cap
                    # site below (`call: False`) has none: `keep` is read only on the conductor's road (G15).
                    # B-20 N5 (AR-22, AR-17, FR-7): the lead carries the facts code can read about the earlier open stages (`stuck_facts`)
                    # and, when the person already answered THIS step, says so instead of putting the same question again. The record
                    # `stuck_asked[signature]` is written by `take_answer` from `stuck_pending`, which lives only while the question is open.
                    stuck_stage = str(action.get("stage") or "")
                    told = (self.state.get("stuck_asked") or {}).get(signature)
                    told = told if isinstance(told, dict) and told.get("answer") else None
                    facts, raw_facts = self.stuck_facts_for(stuck_stage)    # the person's lines / the factory's lines (F3: ids stay out of the lead)
                    keep = [self.stage_place(stuck_stage)] + ([str(told["answer"])] if told else [])
                    self.state["stuck_pending"] = {"signature": signature, "stage": stuck_stage, "kind": "refusal"}
                    try:
                        self.no_move({"why": "threshold", "kind": "refusal", "stage": stuck_stage, "dispatch": "",
                                      "lead": self.stuck_text(stuck_stage, waits_on_person=(
                                          action.get("stage") == "S7" and "open_work" in self.s7_decided()), facts=facts, answered=told),
                                      "text": signature + ("\n\nWhat the factory can read, with its own ids and words:\n"
                                                           + "\n".join(f"- {line}" for line in raw_facts) if raw_facts else ""),
                                      "keep": keep})
                    except Person:
                        raise               # the question is open: `stuck_pending` waits for its answer (`take_answer`)
                    except BaseException:
                        self.state.pop("stuck_pending", None)
                        raise
                    self.state.pop("stuck_pending", None)       # the conductor moved: no question is open
                    repeats, previous = 0, None
                    continue
                if action.get("action") in ("stop", "complete"):
                    import story_step
                    story_step.give_back_config(self.project, self.task_root, self.task)      # HF5-6: the story ends here, with or without `--until`
                if self.until_reached(action):
                    print(f"{self.task}: --until {self.until} reached at {json.dumps(action)}")
                    self.deferred_note()        # RN1-24 E9: a deferred question is never left unsaid
                    self.progress_line()        # the end of this run
                    return EXIT_DONE
                if action.get("action") == "stop":
                    print(f"{self.task}: {action.get('reason')}")
                    self.progress_line()
                    return EXIT_DONE
                if action.get("action") == "complete":
                    self.py_trace("factory_dashboard.py", why="the story is complete; no step of it reads the dashboard, and a failure here is "
                                                              "journalled in driver-runs.jsonl")
                    print(f"{self.task} — the story is complete. Documents: qa-factory/artifacts/{self.task}/test-report.md · retro.md")
                    self.progress_line()
                    return EXIT_DONE
                try:
                    self.boundary_step(action)
                except Person as person:
                    # RN1-24: a question about SOME manual cases does not hold the work that does not depend on them; anything else is asked now
                    if not self.deferrable(person):
                        raise
                    self.defer_question(person)
                    repeats, previous = 0, None         # the step comes again with fewer cases: not "the same action four times"
            print(f"{self.task}: paused after {self.max_boundaries} boundaries (--max-boundaries); run again to go on")
            self.deferred_note()                # RN1-24 E9
            self.progress_line()
            return EXIT_DONE
        except Person as person:
            return self.ask(person)
        except Refusal as refusal:
            # Raised OUTSIDE `guarded` (a `py(check=True)` inside `take_answer`): a traceback is a stalled run (P22), so the
            # seam asks. `call=False` makes `no_move` ALWAYS raise `Person`, and a `Person` raised inside an `except` is not
            # caught by the sibling clause above: it is handed to `ask()` here (D1/E1). No `asked` is passed (F1).
            # The answer being taken (if the refusal came out of `take_answer`) is on the record before the question comes back:
            # its words file named in `asked`, its row in driver-answers.jsonl - the person's word is not lost to the refusal.
            # An answer whose words file is set is NEW words (D-0041): the funnel lets them reach the conductor (`funnel`).
            file = self.settle_unread_answer()
            return self.funnel({"why": "refusal", "kind": "conductor", "text": refusal.text, "words_file": file,
                                "lines": self.refusal_lines(refusal),
                                "words": str((self._answer or {}).get("text") or "") if file else "",
                                "lead": self.question_from_refusal(refusal, self.boundary.split(":")[0])})
        except Stop as stop:
            print(f"story_run: stopped — {stop.reason}")
            if stop.code == EXIT_GAVE_UP and not isinstance(stop, InfraStop):
                # The conductor's `stop` of a gate / the S1 review (exit 4): the priced question with no paid call and no gate
                # branch (F1/F2). `ask` prints the progress line itself (t-323 B1).
                return self.funnel({"why": "stop", "kind": "conductor", "text": stop.reason, "lead": stop.reason,
                                    "dispatch": self.boundary_dispatch()})   # the free answer is filed for this dispatch
            self.progress_line()
            return stop.code

    # --- a stage closed by code with no role (conductor/2 C2-8, t-745; class K3) --------------------------------------------------
    def running_tail(self) -> "list | None":
        """The stages of `pipeline.json` other than S9 whose status is exactly `running` (the predicate `stage_done` uses for its `still
        running` door); `None` when `pipeline.json` holds no readable stage table (an unknown is not an empty tail, FR-59). The one
        caller (`code_close`) hands the value to `code_close_block`, which reads `None` as "no block established"."""
        stages = self.pipeline().get("stages")
        if not isinstance(stages, dict):
            return None
        return [s for s, held in stages.items() if s != "S9" and isinstance(held, dict) and held.get("status") == "running"]

    def code_close_block(self, site: str, tail, passed=()) -> str:
        """The waivable block of an S9 record, read from the STATE (never from the refusal's words): `still running` when a stage is
        left marked so; `no accepted controller stage` at the numbers-only retro of a controller-managed story whose S9 the controller
        has not completed; else `""`. An unreadable state is `""` too: no `go on` is offered over what was not established. A block the
        person's word already PASSED (`passed`) is not the block of the next refusal: `stage_done` reads the pass and goes on to its next
        door, so the second block of one record is shown as its own question (spec 3.6(3); the pass stays in the offer rule)."""
        if site not in ("s9.skip", "s9.numbers") or tail is None:
            return ""
        if tail and NM.BLOCK_RUNNING not in passed:
            return NM.BLOCK_RUNNING
        if site == "s9.numbers":
            held = self.controller_state()
            stages = held.get("stages") if isinstance(held, dict) else None
            if isinstance(held.get("dispatches"), dict) and isinstance(stages, dict) \
                    and (stages.get("S9") or {}).get("status") != "completed":
                return NM.BLOCK_NO_STAGE
        return ""

    def code_close(self, refusal: Refusal) -> str:
        """The seam for a refusal at a place where the CODE closes a stage (`refusal.close`): the question with what lets the story go on,
        no paid call (I2). On S9 the stage left `running` is settled by code first, once (`controller recover`, I8). Returns `retry`
        after that move; otherwise raises the `Person` through `no_move(call=False)`."""
        mark = refusal.close
        stage, site, step = mark["stage"], mark["site"], mark["step"]
        rec = self.state.setdefault("code_close", {}).setdefault(stage, {})
        for name, empty in (("passed", []), ("refused", []), ("filed", []), ("recovered", False), ("recover_failed", ""), ("pending", None)):
            rec.setdefault(name, empty)
        rec.update(site=site, step=step, key=("code_close.factory_file" if step in ("evidence", "entry") else
                                              "code_close.closed_story" if stage == "S9" else "code_close.stage"))
        tail = self.running_tail() if stage == "S9" else []
        if stage == "S9" and tail and not rec["recovered"]:
            rec["recovered"] = True
            self.save_state()
            try:
                self.controller("recover")
                print("S9: a step still marked as in progress was settled by the factory; the retro is recorded again")
                return "retry"
            except Refusal as again:
                rec["recover_failed"] = again.text[:2000]
        rec["block"] = self.code_close_block(site, tail, rec["passed"])
        if step == "record" and stage in ("S6", "S7"):
            rec["pending"] = rec["pending"] if (rec["pending"] or {}).get("receipt") == mark.get("receipt") else {
                "site": site, "args": list(mark.get("args") or []), "tail": list(mark.get("tail") or []),
                "receipt": str(mark.get("receipt") or ""), "idle": 0}
        # B-20 (t-1988 N3, AR-25/AR-9/AR-17): the close is refused because an EARLIER stage is not closed - not the factory's defect and no
        # word of the person's to refuse. POSITION: after the S9 `recover` above (unchanged) and BEFORE `file_defect`; INVARIANT: the
        # driver never closes a stage over an open earlier stage, and never says "no word of yours passes" when the earlier stage accepts
        # a word. The refusal is the controller's own fixed message; WHICH stage is behind comes ONLY from `code_close_facts` (the one
        # reading), never from the words. Another conflict (running work, already completed) and an unreadable state keep today's road.
        ctl = self.controller_state()
        if (rec["key"] != "code_close.factory_file" and "required prior logical stage incomplete" in refusal.text
                and isinstance(ctl, dict) and isinstance(ctl.get("stages"), dict) and isinstance(ctl.get("dispatches"), dict)):
            import acceptance
            from controller import code_close_facts
            facts = code_close_facts(ctl, stage)
            # B2: "is something still running" is the CONTROLLER's verdict (it reads the liveness of each row), carried by its sentence; the
            # default facts here read every `running` row as holding, so a dead row would put the close on the defect road again
            if facts["behind"] and "checkpoint active work" not in refusal.text and not facts["completed"]:
                behind = facts["behind"][0]
                waits = acceptance.awaits_acceptance(ctl, behind, self.pipeline())
                at = f"{behind}@{ctl.get('revision')}"
                held = rec.get("behind_seen") if isinstance(rec.get("behind_seen"), dict) else {}
                nth = (int(held.get("n") or 0) if held.get("at") == at else 0) + 1       # this refusal, counted per (behind, revision)
                rec.update(key="code_close.behind", behind=behind, awaits=bool(waits), block="", behind_seen={"at": at, "n": nth})
                if not waits and nth < CODE_CLOSE_IDLE_CAP:
                    # (a) the earlier stage waits for nobody: the driver's own move - go back to it (`where` routes there). The bound is
                    # the seam's `CODE_CLOSE_IDLE_CAP` (F3): refusal 1 of a revision is a silent retry, refusal 2 at the SAME revision
                    # (nothing moved) is asked below.
                    self.save_state()
                    print(f"{stage}: closed after {behind}, which is not closed yet; the factory goes back to it")
                    return "retry"
                return self.code_close_ask(stage, rec, refusal.text, lines=self.refusal_lines(refusal))
        found = f"{site}:{finding_key(refusal.text.splitlines())}"
        if found not in rec["filed"]:
            rec["filed"].append(found)
            self.file_defect(stage, f"owner: factory — {site}: the factory's own close of {stage} was refused at its {step}")
        details = refusal.text + (("\n\n## `controller.py --operation recover` was run for it and refused too\n" + rec["recover_failed"])
                                  if rec["recover_failed"] else "")
        return self.code_close_ask(stage, rec, details, lines=self.refusal_lines(refusal))

    def code_close_ask(self, stage: str, rec: dict, details: str, *, lines=None, cap: bool = False) -> str:
        """Fix the options of the question from the facts (`NM.code_close_offer`), keep them and the lead in the state (the answer reads them),
        and raise the question through the seam."""
        tokens, absent = NM.code_close_offer(rec["key"], {"block": rec["block"], "passed": rec["passed"], "refused": rec["refused"],
                                                           "idle_cap": cap, "awaits": bool(rec.get("awaits"))})
        rec.update(offer=tokens, lead=self.code_close_lead(stage, rec, absent, cap), details=details, at=_now())
        self.save_state()
        return self.no_move({"why": "refusal", "kind": "code_close", "call": False, "stage": stage, "dispatch": "", "lead": rec["lead"],
                             "text": details, "block": rec["block"], **({"lines": lines} if lines else {}),
                             "site_fallback": lambda said: self.code_close_person(stage, said)})

    def code_close_lead(self, stage: str, rec: dict, absent: list, cap: bool) -> str:
        """The words above the options (human-questions.md items 1-6): what is decided, why the factory cannot, what the person can do."""
        what = (self.consumer_close_words(stage)[0] if rec["site"] in ("s6.accepted", "s7.accepted")       # N4: who accepted, from the record
                else CODE_CLOSE_SITES[rec["site"]][1])
        place = self.stage_place(stage)
        said = "".join(line + "\n" for line in absent)
        if rec["key"] == "code_close.behind":
            behind = str(rec.get("behind") or "")
            route = self.CONSUMER_ROUTES.get(behind) or {}
            bplace = self.stage_place(behind)
            head = (f"The story is at {place}. No role works at this step: the factory closes it by itself ({what}), but {bplace} is not "
                    "closed yet, and the factory closes the stages in order. ")
            if rec.get("awaits"):
                return (head + f"{bplace[:1].upper() + bplace[1:]} is finished on the factory's side and waits for one thing: the "
                        f"{route.get('who', 'next role')} has not "
                        f"yet accepted {route.get('what', 'its handoff')}. A word of yours can give that acceptance in the "
                        f"{route.get('who', 'next role')}'s place. Which of these should happen?")
            return (head + f"The factory went back to {bplace} and nothing moved.\n{said}The factory cannot finish this step by itself. "
                    "Which of these should happen?")
        if rec["key"] == "code_close.factory_file":
            cause = ("its own description of which failed tests to repair cannot be read, and going past it would leave failed tests "
                     "unrepaired" if rec["step"] == "entry" else f"the file that shows that {what} is not on disk")
            return (f"The story is at {place}. No role works at this step, and the factory cannot do it: {cause}. This is the factory's "
                    f"own defect and it is filed.\n{said}The factory cannot go past it by itself. Which of these should happen?")
        owner = ("The factory tried to record it twice and something of its own kept the record from finishing; it is filed as a defect "
                 "of ours." if cap else
                 "Another step of this story is still marked as in progress" + (", and the factory could not settle that by itself"
                                                                                 if rec["recover_failed"] else "")
                 + "; a finished story must not leave a step marked so." if rec["block"] == NM.BLOCK_RUNNING else
                 "The factory can record the retro as finished only after the retro analyst's own work, or on your word."
                 if rec["block"] == NM.BLOCK_NO_STAGE else
                 "The reason is the factory's own; it is filed as a defect of ours, and the factory's own words are in the file named below.")
        return (f"The story is at {place}. No role works at this step: the factory closes it by itself ({what}), and its own record of "
                f"that close was refused. {owner}\n{said}The factory cannot finish this step by itself. Which of these should happen?")

    def code_close_person(self, stage: str, said: str = "") -> Person:
        """The question from its facts (the state keeps them across processes): `said` (an unread answer's lead) above the lead, then the
        priced answers of the key. One literal `closed_question` per key (the census of question ids reads them)."""
        rec = (self.state.get("code_close") or {}).get(stage) or {}
        lead = rec["lead"] if not said.strip() or said.strip() == rec["lead"].strip() else said.strip() + "\n\n" + rec["lead"]
        factory_file = rec["key"] == "code_close.factory_file"
        says = {"retry": (("once the factory's own file is repaired by whoever maintains the factory (not within this story), the factory "
                           "tries this step again", {"what": "the factory's own file repaired by whoever maintains the factory"})
                          if factory_file else
                          ("you settle what is in the way, then the factory records the retro again", {}) if stage == "S9" else
                          ("you deal with what is in the way, then the factory records the close again", {})),
                "go on": ("the retro is recorded as closed as it is, on your word; your words are kept as the reason", {}),
                "full retro": ("the retro analyst does the retro of this story after all, and its finish closes this step",
                               {"role": "the retro analyst"})}
        if rec["key"] == "code_close.behind":
            route = self.CONSUMER_ROUTES.get(str(rec.get("behind") or "")) or {}
            who = route.get("who", "next role")
            says = {"retry": ((f"you deal with what is in the way, or the {who} accepts {route.get('what', 'its handoff')}, then the factory "
                               "records the close again" if rec.get("awaits") else
                               "you deal with what is in the way, then the factory records the close again"), {}),
                    "go on": (f"your word accepts {route.get('what', 'its handoff')} in the {who}'s place, your words are kept as the reason, "
                              "and the factory records the close again", {})}
        options = [dict(self.STOP_OPTION) if t == "stop" else {"answer": t, "token": t, "says": says[t][0], "slots": says[t][1]}
                   for t in rec["offer"]]
        if rec["key"] == "code_close.behind":
            text = self.closed_question("code_close.behind", lead, options)
        elif rec["key"] == "code_close.closed_story":
            text = self.closed_question("code_close.closed_story", lead, options)
        elif factory_file:
            text = self.closed_question("code_close.factory_file", lead, options)
        else:
            text = self.closed_question("code_close.stage", lead, options)
        return Person("code_close", text, stage, "", details=rec.get("details", ""))

    def _answer_code_close(self, words: str, qtext: str, stage: str, dispatch: str, *, words_file: str = "") -> bool:
        """The answer to a `code_close` question - the one executor of its tokens, whoever asked it (FR-9; FR-12: only a whole token).
        `retry` lets the step run again; `go on` records the pass through the writer of passes and files the finding (FR-4); `full retro`
        sets the retro to its role; `stop` holds the question. Any other word goes back to the question (`doors`, `again`). True = a token."""
        held = self.state.get("code_close") or {}
        rec = held.get(stage) or {}
        token = self.s0_normalize(words)
        if not rec:                    # the facts are lost (a state from before this record): the conductor reads the words (FR-59)
            self.unread("code_close", stage, "", self.generic_prompt("code_close", stage, qtext), words=words)
            return False
        if ((self.pipeline().get("stages") or {}).get(stage) or {}).get("status") in ("done", "skipped"):
            self.after_close(stage, words)      # no executor runs on a stage already closed
            held.pop(stage, None)
            self.save_state()
            return token in rec.get("offer", ())
        if token not in rec.get("offer", ()):
            self.unread("code_close", stage, "", qtext, words=words, block=rec.get("block", ""), doors=tuple(rec.get("offer") or ("stop",)),
                        lead=self.unread_lead(words), again=lambda said: self.code_close_person(stage, said))
            return False
        file = words_file or self.answer_file()
        self.answer_row(f"{stage} code close ({token}): ", words.strip(), what="your answer about the closed stage")
        if token == "stop":
            # remains: `stop` holds the question that was asked (the person's own word); it is no state without a move
            raise self.held_question(self.stop_held("If you want the factory to go on after all, answer one of the other answers."))
        if token == "retry":
            rec["recovered"] = False
            if rec.get("pending"):
                rec["pending"]["idle"] = 0
            print(f"{stage}: nothing is passed; the step runs again")
        elif token == "go on" and rec.get("key") == "code_close.behind":
            # B-20 (N3): the person's word accepts the EARLIER stage in its consumer's place - recorded by the one path every such pass takes
            # (`consumer_person_pass`: the driver accept `by: person` and its finding) - and then the close runs again, as after `retry`.
            import acceptance
            behind = str(rec.get("behind") or "")
            author = acceptance.awaits_acceptance(self.controller_state(), behind, self.pipeline())
            lead = "Your word could not be recorded as the acceptance, so nothing was passed."
            try:
                passed = self.consumer_person_pass(behind, author, answer=words) if author else True      # nothing waits any more: just try again
            except Refusal as refusal:       # a state with no move of its own: the seam asks the same question again, with the facts (AR-17)
                self.no_move({"why": "refusal", "kind": "code_close", "call": False, "stage": stage, "dispatch": "", "lead": lead,
                              "text": refusal.text, "block": rec.get("block", ""),
                              "site_fallback": lambda said: self.code_close_person(stage, said)})
            if not passed:
                self.no_move({"why": "refusal", "kind": "code_close", "call": False, "stage": stage, "dispatch": "", "lead": lead,
                              "text": lead, "block": rec.get("block", ""),
                              "site_fallback": lambda said: self.code_close_person(stage, said)})
            rec["recovered"] = False
            rec.pop("behind_seen", None)       # the record stands now (the pass is a record, the controller revision may not move): the next refusal is a fresh count
            if rec.get("pending"):
                rec["pending"]["idle"] = 0
            print(f"{stage}: going on on the person's word for {behind}; the step runs again")
        elif token == "go on":
            block = rec["block"]
            try:
                self.pass_block(stage, block, file, "Your word could not be recorded as the pass, so nothing was passed.")
            except Person:
                rec["refused"].append(block)
                self.save_state()
                raise
            rec["passed"].append(block)
            quoted = self.s0_quote((self.task_root / file).read_text(encoding="utf-8", errors="replace") if (self.task_root / file).is_file() else words)
            self.owe_row("project_decisions.py", "--root", str(self.project), "add-finding",
                         "--essence", f"{stage} {block} passed by the person's word: {quoted}", "--scope", "local-calibration",
                         "--witness", f"{stage} code close", "--idempotency-key", f"code-close-pass:{self.task}:{stage}:{block}",
                         what="the finding about the closed stage you passed", stage=stage)
            print(f"{stage}: going on on the person's word; recorded")
        else:                                           # `full retro`
            code, out = self.py("stage_done.py", "--task", self.task, "--set", "retro_mode=full")
            if code:
                # remains: the person's choice could not be written; the question comes back with the writer's own words (FR-1)
                raise self.held_question("Your choice could not be recorded, so nothing was changed.", out)
            held.pop(stage, None)
            print(f"{stage}: the retro analyst does the retro of this story")
        self.save_state()
        return True

    def code_close_step(self) -> bool:
        """The deferred record of a stage the code closed (S6/S7), one step of the loop (C2-8 M2/M4): the receipt stands in the controller and
        the record was refused. True when it wrote (the turn is spent). INVARIANT (I4): written only while the receipt this record was
        deferred for still stands in the controller - a stage opened again is never closed behind the person's back; an unreadable state
        writes nothing (FR-59). At most `CODE_CLOSE_IDLE_CAP` idle turns, then the person is asked (`retry` / `stop`)."""
        held = self.state.get("code_close") or {}
        stage = next((s for s, r in held.items() if isinstance(r, dict) and r.get("pending")), "")
        if not stage:
            return False
        rec = held[stage]
        pending = rec["pending"]
        self.boundary = stage                      # a known refusal that asks (`story_budget`) asks at THIS stage, not at `no_trace`
        stages = self.pipeline().get("stages")
        if isinstance(stages, dict) and (stages.get(stage) or {}).get("status") == "done":
            rec["pending"] = None
            self.save_state()
            print(f"{stage}: the record is on file already; the deferred record is dropped")
            return False
        ctl = self.controller_state()
        mine = (ctl.get("stages") or {}).get(stage) if isinstance(ctl, dict) else None
        if not isinstance(stages, dict) or not isinstance(mine, dict):
            pending["idle"] += 1
            self.save_state()
            return False
        if mine.get("status") != "completed" or not pending["receipt"] or mine.get("receipt_id") != pending["receipt"]:
            rec["pending"] = None
            self.save_state()
            print(f"{stage}: the receipt this record waited for no longer stands; the deferred record is dropped")
            return False
        if pending["idle"] >= CODE_CLOSE_IDLE_CAP:
            self.code_close_ask(stage, rec, rec.get("details", ""), cap=True)
        if self.dry:
            print(f"dry run: the deferred record of {stage} is not written")
            return True
        pending["idle"] += 1
        self.save_state()
        self.record_close(pending["site"], stage, *pending["args"], tail=pending["tail"], receipt=pending["receipt"])
        held.pop(stage, None)
        self.save_state()
        return True

    def unread(self, kind: str, stage: str, dispatch: str, text: str, words: str = "", block: str = "", *,
               doors=None, lead: str = "", again=None) -> str:
        """An answer none of the branches of `take_answer` read (or one a question offered no token for): the seam, with the
        words verbatim and the file that holds them whole (C1-1: `why=unread_answer`). Returns `continue` / `retry` after a
        conductor move, else raises the Person with the priced options. EVERY `--answer` is new words (D-0041): this always calls
        the conductor (under the cap); the question without a call is the site's own, raised by a rerun with no `--answer`.

        A CLOSED question that reads only its own words (S0, `package`, `ticket_changed`; C1-3) passes `doors` - a TUPLE of its
        tokens (a dict gives its keys) - so the conductor may offer them back (`retry` / `go on` as the moves they are, any other
        as `site_door`), `lead` - the one sentence that says the answer was not read - and `again(lead)` - the Person that
        shows the SAME question again, which the seam raises when the conductor cannot answer. `stop` is always a door."""
        state = {"why": "unread_answer", "kind": kind, "stage": stage, "dispatch": dispatch, "text": text,
                 "words": words, "words_file": self.answer_file(), "block": block}
        if doors is None:
            return self.no_move(state, None)
        tokens = [self.s0_normalize(token) for token in doors]
        moves = [NM.TOKEN_MOVES[token] for token in NM.TOKEN_MOVES if token in tokens or token == "stop"]
        state.update(lead=lead, site_doors=tuple(token for token in tokens if token not in NM.TOKEN_MOVES), site_fallback=again)
        return self.no_move(state, moves)

    @staticmethod
    def generic_prompt(kind: str, stage: str, qtext: str, items_text: str = "") -> str:
        """The conductor's prompt for an answer of kind `kind` that no branch of `take_answer` read.

        `items_text` (RH1-6): a gate's APPROVAL that the controller refused over open items - the prompt then says the approval was heard
        and kept (`open_items_text`), not "words that are not the approval word" (which would be a lie about whose refusal it is)."""
        if kind in GATE_KINDS and items_text:
            return items_text + " " + MOVES_RULE + " " + OWN_TOKEN_RULE + " " + GATE_RULE + "\n\n## The question\n" + qtext[:8000]
        if kind in GATE_KINDS:
            # C1-4b: a gate answer that is not the approval word. The conductor PROPOSES and never records the gate decision (I6);
            # the options it may offer carry the moves of the gate (`approve` / `rework` / `retry`), each executed by the driver.
            return (f"The person answered the driver's question of kind `{kind}` at {stage} with words that are not the approval "
                    "word of the gate, so nothing is recorded as approved. " + MOVES_RULE + " " + OWN_TOKEN_RULE + " " + GATE_RULE
                    + "\n\n## The question\n" + qtext[:8000])
        return (f"The person answered the driver's question of kind `{kind}` at {stage}. Record "
                "their words with the factory's own commands (waiver.py --block/--remark for items, "
                "stage_done --set for "
                "story facts, release for a dead dispatch, log_append for anything else) so the "
                "block stands lifted and the loop continues. "
                # Every kind that lands here may be answered with a token of the conductor's own options (C1).
                + MOVES_RULE + " " + OWN_TOKEN_RULE
                + "\n\n## The question\n" + qtext[:8000])

    @staticmethod
    def seam_tokens(asked: dict) -> dict:
        """`{token: move}` of the options a seam question offered (`asked.options`): THE reading of what a token of that question is,
        for `take_seam_answer` and for the test `take_answer` makes of an answer at a gate (C2-7 §5.3)."""
        return {str(o.get("token")): str(o.get("move")) for o in asked.get("options") or [] if isinstance(o, dict)}

    def take_seam_answer(self, words: str, asked: dict, qtext: str, stage: str, dispatch: str) -> bool:
        """The answer to a question the seam raised (`asked.offered`): True when it was one of the offered tokens (the words are
        then NOT filed for a role), False when it was anything else (the seam again, `unread_answer`, the words whole).

        A token is read against THIS question's `options` only, and it dispatches on its move (`options[token].move`), never
        on the token text: `retry` -> look again, `stop` -> held (the question comes back changed, exit 3), `go on` with a
        block code knows -> `waiver.py` by code, any other offered token -> the seam (`why=chosen`) with the original words'
        file. A stage that is already done is never reopened by a token (edge 8): the words are recorded and the loop goes on.

        At a GATE (C1-4b, H2) the stage in front of the gate (S4 / S8) is always done when the gate is asked, so the done-stage
        short-circuit does not apply to the gate kinds: `done and kind not in GATE_KINDS` short-circuits as before; a non-gate kind
        whose stage is done is never reopened by a token. At a gate `approve` (move `approve_gate`) is recorded by code from the
        words file of the original answer, `retry` shows the gate again, `rework` goes to the conductor with that file."""
        kind, token = asked.get("kind", ""), self.s0_normalize(words)
        by_token = self.seam_tokens(asked)
        if kind == "code_close":
            # C2-8: every answer to a question of this kind - the site's or the conductor's options - has the ONE executor, BEFORE the
            # general "stage done" short-circuit (it sees `done` only; the executor knows `skipped` too) and before the general unread road
            # (no doors) and the `else` below (a conductor call for `full retro`, which no conductor executes).
            return self._answer_code_close(words, qtext, stage, dispatch, words_file=str(asked.get("words_file") or ""))
        # C1-7a: the question about the journal's rows is about the story's journal, not about a stage: its `go on` is executed whether or
        # not the stage it names is done (POSITION INVARIANT: before the "stage done" short-circuit, which would write a row and pass
        # nothing - the question would be asked for ever).
        done = bool(stage) and (self.pipeline().get("stages") or {}).get(stage, {}).get("status") == "done" \
            and str(asked.get("block") or "") != JOURNAL_ROWS_BLOCK
        if done and kind not in GATE_KINDS:
            self.after_close(stage, words)
            return token in by_token
        if kind == "exit_limit":
            # t-764 A7 (F5): every word of this kind - a token of the conductor's options (`go on`, `stop` too) or not - has the ONE
            # reader, BEFORE the `by_token` test (t-781 M1): its tokens are the SITE's (`round` / `fresh` / `go on` / `stop`), `round` /
            # `fresh` carry the person's ORIGINAL words (`asked.words_file`), never the file that holds only the token, and words that
            # are none of them go back to the SITE's question (`doors`, `again`) - never to the generic call with every move open, whose
            # `restart` / `retry` this kind cannot execute (FR-9), nor to a floor that offers a `go on` the site withdrew (A1).
            return self._answer_exit_limit(words, qtext, stage, dispatch, words_file=str(asked.get("words_file") or ""))
        if token not in by_token:
            self.unread(kind, stage, dispatch, self.generic_prompt(kind, stage, qtext), words=words, block=str(asked.get("block") or ""))
            return False
        move = by_token[token]
        self.answer_file()          # the token's own words file: the audit trail row of driver-answers.jsonl names it (E6)
        self.answer_row(f"{stage} ({token}): ", words.strip(), what="your answer to the question")
        if move == "approve_gate" and kind in GATE_KINDS:
            self.approve_by_option(kind, stage, asked)
        elif move == "person_does":
            print(f"{stage}: nothing is passed; the step runs again" if kind not in GATE_KINDS
                  else f"gate {kind[-1]}: nothing is recorded; the gate is shown again")
        elif move == "stop_here":
            others = " or ".join(f"`{offered}`" for offered in asked.get("offered") or () if offered != token)
            raise self.held_question(self.stop_held(f"If you want the factory to go on after all, answer {others}." if others else ""))
        else:
            self.seam_chosen(move, token, asked, qtext, stage, dispatch)
        return True

    def seam_chosen(self, move: str, token: str, asked: dict, qtext: str, stage: str, dispatch: str) -> None:
        """Every chosen token whose move is not `approve` / `retry` / `stop` (t-722 §4.2-4.6): the ORIGINAL words (`original_words`) go
        to the executor, never the file that holds only the token (FR-8). By code: `go on` with a block (`waiver.py`), `restart`
        (`waiver.run_release`), `rework` whose option carries "args" (the record `seam_rework`, run by `seam_rework_step`). Every other
        move goes to the conductor WITH the words and what the option says. Words named but not on file: held for every one of them."""
        given = self.original_words(asked)
        if given is None:
            # remains: the person's own question comes back with the reason (t-722 §4.6, the C1-4b `approve_by_option` pattern), not a state with no move
            raise self.held_question("Your choice could not be carried out: the words it is about are not on file, so nothing was done. "
                                     "Answer again, in your own words or with one of the words offered.")
        rel, said = given
        option = next((o for o in asked.get("options") or [] if isinstance(o, dict) and str(o.get("token")) == token), {})
        block = str(asked.get("block") or "")
        gap_cases = [str(c) for c in asked.get("probe_gap_cases") or () if str(c).strip()]
        judged_cases = [str(c) for c in asked.get("probe_judgment_cases") or () if str(c).strip()]    # t-1968 N5; absent in an `asked` of any other question (E5.7)
        if move == "go_on_as_is" and (block or gap_cases or judged_cases):
            # POSITION INVARIANT (B-16, E1.6): only the token the person chose records anything; the existing `block` pass runs FIRST
            if block:
                self.pass_block(stage, block, rel or self.answer_file(), "Your word could not be recorded as the pass, so nothing was passed.")
                if block == JOURNAL_ROWS_BLOCK:
                    self.mark_rows_word(asked, stage)       # B-1: AFTER the pass is recorded, and only the rows of THIS question
                print(f"{stage}: going on on the person's word; recorded")
            import contract as C   # late, as every other site of this module
            for case in gap_cases:
                # the keys come from the question (`probe_gap_cases` of the window record), never typed here; a refusal is HELD (E1.4)
                self.pass_block(stage, f"{C.PROBE_GAP_MATCH_PREFIX} {case}", rel or self.answer_file(),
                                f"Your word could not be recorded as the probe gap of {case}, so nothing more was passed.")
            if gap_cases:
                print(f"{stage}: the probe gap of {', '.join(gap_cases)} is recorded on your word")
            for case in judged_cases:
                # one `probe not proved: <case key>` word per case the question named, never a `probe gap:` word (E5.1); a refusal is
                # HELD (E5.5): the words recorded before it stay (append-only), the later ones are not tried, nothing is printed as recorded
                self.pass_block(stage, f"{C.PROBE_NOT_PROVED_PREFIX} {case}", rel or self.answer_file(),
                                f"Your word could not be recorded as not proved for {case}, so nothing more was passed.")
            if judged_cases:
                print(f"{stage}: {', '.join(judged_cases)} stay not proved on your word")
        elif move == "release_and_restart":
            self.restart_by_option(stage, dispatch, rel or self.answer_file())
        elif move == "rework_stage" and isinstance(option.get("args"), dict):
            self.record_seam_rework(option["args"], rel)
        else:
            details = self.state_dir / "driver-question-details.md"
            if move == "rework_stage" and not rel:          # a rework without words has nothing to instruct with (§4.2 p.6)
                raise self.held_question(self.NO_REWORK_WORDS)  # remains: the person's own question comes back with the reason (t-722 §4.2 p.6)
            self.no_move({"why": "chosen", "kind": asked.get("kind", ""), "stage": stage, "dispatch": dispatch, "token": token, "move": move,
                          "says": str(option.get("says") or ""), "words": said,
                          "text": (details.read_text(encoding="utf-8", errors="replace") if details.is_file() else qtext[:6000]),
                          "words_file": rel, "block": block}, None)

    def restart_by_option(self, stage: str, dispatch: str, file: str) -> None:
        """`restart` (move `release_and_restart`): the dispatch the question is about is released BY CODE through `waiver.run_release`
        - the one caller of the controller's `release` (N4) - with the person's words by file; `where` then gives `relaunch` and the
        new session is told the words (`relaunch_reason`). A refusal of the controller is held with its words, nothing is released."""
        if not dispatch:
            # remains: the person's own question comes back with the reason (t-722 §4.4), not a state the driver has no move for
            raise self.held_question("Your choice to start that step again could not be carried out, so nothing was released.",
                                     "the question named no step")
        code, answer = waiver.run_release(self.task_root, dispatch, words_file=str(self.task_root / file), env=self.env)
        if code:
            # remains: the controller refused the release the person chose; the question comes back with its words (t-722 §4.4, FR-1)
            raise self.held_question("Your choice to start that step again could not be carried out, so nothing was released.", answer)
        print(f"{stage}: {dispatch} is released on the person's word; the driver starts it again")

    def original_words(self, asked: dict) -> "tuple[str, str] | None":
        """THE reader of the words a seam question is about (t-722 §4.1): `(rel, text)` of `asked.words_file`, read by the package's one
        words-file reader (`person_words.read`: bytes, CRLF kept, FR-8). Three outcomes: no file named (the question was raised without
        an answer: the token is everything said) -> `("", "")`; a file with text -> `(rel, text)`; a file named but missing, unreadable,
        not UTF-8 or empty -> None (the words are lost: the reader's refusal is the reason, and nobody acts on words nobody can read)."""
        rel = str(asked.get("words_file") or "")
        if not rel:
            return "", ""
        try:
            return rel, person_words.read(None, str(self.task_root / rel), "--words")
        except person_words.WordsRefused:
            return None

    EARLIER_ANSWER = EARLIER_ANSWER_MARK

    def combine_gate_words(self, asked: dict, raw: str, words: str) -> str:
        """The COMBINED words of a second answer at a gate (t-891 F-1..F-3): this answer, then `Earlier answer at this gate:` and the
        original answer of the question the seam raised. They are what the gate's decision keeps (FR-8, FR-9), and the same text is
        the answer's ONE words file (`self._answer`), so a token on the NEXT question - `approve`, `rework`, `go on` - reads both
        answers from `asked.words_file`. The tail is never read for the cards: the plan takes this answer's lines alone (`record_by_code`
        `apply_words`). No words file named on the question -> this answer alone, no tail. A file that is NAMED and lost is the held road
        of `approve_by_option` (t-722 4.6): the new answer is put on the record first, nothing is recorded, the person is told (FR-8)."""
        earlier = self.original_words(asked)
        if earlier is None:
            self.answer_file()
            self.record_answer_row("")
            # remains: the question comes back with the reason (t-722 4.6, the same held road as `approve_by_option`), not a move the driver lacks
            raise self.held_question("Your answer could not be taken: the words of your earlier answer at this gate are not on file, so "
                                     "nothing was recorded. Answer this gate again.")
        tail = earlier[1].strip()
        if not tail:
            return words
        if self._answer is not None and self._answer.get("rel") is None:        # the file of this answer is not written yet: it holds both
            self._answer["text"] = raw.rstrip() + self.EARLIER_ANSWER + tail
        return words + self.EARLIER_ANSWER + tail

    def approve_by_option(self, kind: str, stage: str, asked: dict) -> None:
        """The person chose `approve` from the options the seam raised at a gate (move `approve_gate`): the gate decision is recorded
        by code with the words of the ORIGINAL answer (`asked.words_file`, whole - FR-8), the card answers applied first (FR-9), and
        `approved_by="option"` says the choice, not the words, is the approval. The conductor never records a gate (I6). A controller
        refusal keeps the answer with that mark, so the kept road re-records it as an approval (H4) and the gate comes back with the
        refusal at its top (FR-7)."""
        words = (self.original_words(asked) or ("", ""))[1]
        if not words.strip():
            raise self.held_question("Your choice to approve could not be recorded: the words it is about are not on file, so "
                                     "nothing was approved. Answer this gate again.")
        # t-891 F-2 on the token road: a file that holds a second answer is `<new answer><EARLIER_ANSWER><earlier>` (`combine_gate_words`); the
        # card lines are read from the HEAD (the new answer) alone, the record keeps the whole. No tail -> nothing passed, as before.
        head, tail_mark, _earlier = words.partition(self.EARLIER_ANSWER)
        apply = {"apply_words": head} if tail_mark else {}
        if self.record_by_code(kind, stage, words, approved_by="option", **apply):
            return
        self.state["gate_answer_kept"] = {"gate": kind[-1], "words": words, "at": _now(), "approved_by": "option",
                                          "source_revision": self.controller_state().get("source_revision"),
                                          **({"apply": head} if tail_mark else {})}
        self.save_state()

    def gate_approval(self, kind: str, words: str) -> bool:
        """Is this answer the gate's APPROVAL WORD? Its first non-empty line, read with the one normalizer (`s0_normalize`: BOM, quotes,
        one full stop, case and spaces only), equals a word of `gate_brief.approval_words(gate)` read the same way. Never a phrase
        (FR-12): `approve, but fix the export test`, `I approve`, `approved`, `do not approve`, a first line that is a code fence, or the
        word on a later line are NOT approvals. The allowed error is not approving (the words go to the conductor); the forbidden one is
        approving words that are not the word. An unreadable word list approves nothing (FR-59). The rest of the answer is not read here:
        the cards of gate A and the stand-gap lines are read by their own readers, and the words are kept whole by the decision."""
        if kind not in GATE_KINDS:
            return False
        import gate_brief
        wanted = {self.s0_normalize(word) for word in gate_brief.approval_words(kind[-1])} - {""}
        if not wanted:
            if not getattr(self, "_approval_words_reported", False):      # ONE defect per process: every gate answer meets this
                self._approval_words_reported = True
                self.file_defect(self.boundary, "owner: factory — the approval words of the gates could not be read "
                                                "(references/gate-approval-words.json): no gate is recorded by code, every gate "
                                                "answer goes to the conductor")
            return False
        return self.first_line(words) in wanted

    def gate_lines_over_approval(self, kind: str, words: str, stand: dict, asked_unread) -> bool:
        """GW1-33: may the gate's approval be put to the controller although `stand["unread"]` holds lines nobody could read? Yes
        exactly when the gate is A (only gate A's controller call refuses an approval over an open item: `open_gate_items` returns
        nothing for gate B), the answer IS the approval (`gate_approval`), there is such a line, none of them is held for the
        conductor (`stand["hold"]`: a record the story REFUSED, an `ask again`, a line with `?` - understood but not carried out, or
        a question, never consent) and none is the exploratory reader's (`asked_unread`: a `bug` beside `approve` is a
        contradiction the conductor resolves, FR-12; on gate A this is always empty - kept for a word about gate B). The allowed
        error is NOT recording: this only lets the caller ASK the controller, which refuses an approval over an item still open,
        and then the whole answer stays kept for the conductor (`_unread_kept_gate`). An unread line removes no item."""
        return bool(kind == "gate_A" and self.gate_approval(kind, words) and isinstance(stand, dict)
                    and stand.get("unread") and not stand.get("hold") and not asked_unread)

    def first_line(self, words) -> str:
        """The first non-empty line of an answer, read with the one normalizer (`s0_normalize`) - THE one reader of "the word the person
        said" for `gate_approval` and `as_is_word` (M4, AR-13)."""
        first = next((line for line in str(words or "").replace(self.BOM, "").splitlines() if line.strip()), "")
        return self.s0_normalize(first)

    def as_is_word(self, kind: str, words: str) -> bool:
        """Is this answer a gate's `approve as is`? The same first-line reading as `gate_approval` (`first_line`), against
        `gate_brief.as_is_words(gate)` - the words whose data row says `passes_open_items`. False for gate B (no such row) and for
        an unreadable list (FR-59). Never a phrase (FR-12): `approve as is, but fix X` is not the word and goes to the conductor."""
        if kind not in GATE_KINDS:
            return False
        import gate_brief
        wanted = {self.s0_normalize(word) for word in gate_brief.as_is_words(kind[-1])} - {""}
        return bool(wanted) and self.first_line(words) in wanted

    @staticmethod
    def gate_refusal_parts(refusal_text):
        """`(the factory's own sentences, the items' sentences)` of a gate decision's refusal, each a whitespace-normalised list. The
        controller marks where the items' sentences start (`item_problems_from`); a record without the mark (an older controller) holds
        no factory sentence in front of the items. Nothing is sliced by a count of items."""
        doc, _ = json_record(str(refusal_text or ""))
        problems = [" ".join(str(p).split()) for p in (doc.get("problems") or []) if str(p).strip()] if isinstance(doc, dict) else []
        start = doc.get("item_problems_from") if isinstance(doc, dict) else 0
        start = start if isinstance(start, int) and not isinstance(start, bool) and 0 <= start <= len(problems) else 0
        return problems[:start], problems[start:]

    @staticmethod
    def gate_open_items(refusal_text):
        """The open items a gate decision's refusal carries (`open_items` of the controller's `{"recorded": false, ...}` record), as a
        list of dicts; None when the text holds no such record or no list under that key (unreadable - the caller names no owner,
        FR-41). Read by FIELD from the one JSON reader (`json_record`, AR-13/axis 16), the first object in the joined stdout and
        stderr: a line the controller printed before it does not hide it."""
        doc, _ = json_record(str(refusal_text or ""))
        items = doc.get("open_items") if isinstance(doc, dict) else None
        if not isinstance(items, list) or not all(isinstance(i, dict) and str(i.get("id") or "").strip() for i in items):
            return None
        return items

    def open_items_text(self, items: list, words: str, factory=()) -> str:
        """What the conductor is handed over a kept approval that waits for the person's word on open items (RH1-6, A-AC5): that the
        approval word was HEARD and kept - the refusal is the items', not a mistake of the answer - every item with its id, message and
        what it needs, the RECORDING COMMAND for each item the conductor can read (a `line` or `words` block; the file holds
        `accept - the person wrote: <their words>`, the form `_record_door_lines` writes, so the first word is the option), `approve as
        is` for one it cannot name a block for, and the person's whole words. `factory`: the factory's own sentences of the same refusal
        (`gate_refusal_parts`) - listed under their own owner, and `approve as is` is then not offered (the controller skips it while
        they stand)."""
        import gate_brief
        as_is = "" if factory else gate_brief.as_is_word_of("A")
        out = ["The person's approval word was heard and kept. The factory records a gate A approval only over items the person has "
               "worded, and these items have no recorded word, so nothing is recorded as approved yet. Their words, whole:",
               "", str(words or "").strip() or "(empty)", ""]
        if factory:
            out += ["The factory's own problems, not the person's to word (they stand first, and no word of the person passes them):"]
            out += [f"- {line}" for line in factory] + [""]
        out += [f"Open items ({len(items)}):"]
        for item in items:
            door = item.get("door") if isinstance(item.get("door"), dict) else {}
            out.append(f"- [{item.get('id')}] {' '.join(str(item.get('message') or '').split())} - needs: {door.get('says') or 'their word'}")
            if door.get("kind") in ("line", "words") and str(door.get("block") or "").strip():
                command = person_words.door(f"python {self.scripts / 'waiver.py'} --task {self.task} --stage {door.get('stage') or 'S5'} "
                                            f"--block \"{door['block']}\"")
                out.append(f"  record their word on it: {command}  (the file starts `accept - the person wrote: ` and holds their words "
                           "about this item; `run` instead of `accept` when they said they will run it themselves, if the item offers that)")
            else:
                out.append("  no block can be named for it: " + (f"only the person's `{as_is}` passes it" if as_is
                                                                  else "ask the person for their word on it, in a closed question"))
        out += ["", "When every item has a word, the kept approval records on its own. If their words are not about an item, ask a "
                "closed question for it (references/human-questions.md); never record `--block \"*\"` for these items."]
        return "\n".join(out)

    def funnel(self, state: dict) -> int:
        """The run()-level handler of the seam: `call=False` (no paid call, `no_move` always raises) unless the state carries the
        words file of an answer being taken - those words are new (D-0041, t-671 Q12), so the conductor reads them like any other
        unread answer. The Person the seam raises is handed to `ask()` (the exit code). A conductor `continue` / `retry` leaves the
        answer on the record and the refusal standing in the story's state: the free question comes back, nothing is lost. The
        handlers raise only `Person`, so nothing escapes an `except` clause."""
        free = dict(state, call=False)
        try:
            self.no_move(state if state.get("words_file") else free, None)
            self.no_move(free, None)
        except Person as person:
            return self.ask(person)
        raise AssertionError("no_move(call=False) returned: the seam always raises a Person here")   # not a code path

    def boundary_step(self, action: dict) -> None:
        """One action, with the refusal loop around it."""
        self.guarded(lambda: self.dispatch_action(action), action)

    def guarded(self, move, action: dict) -> None:
        attempts = 0
        while True:
            try:
                move()
                self.drop_standing()            # E2: the step went through, so the refusal does not stand (and does not outlive its stage)
                return
            except Refusal as refusal:
                attempts += 1
                if attempts > REFUSALS_PER_BOUNDARY:
                    self.no_move({"why": "cap", "kind": "refusal", "call": False, "stage": str(action.get("stage") or ""),
                                  "dispatch": self.refusal_dispatch(refusal), "lead": self.refused_text(str(action.get("stage") or "")),
                                  "lines": self.refusal_lines(refusal),       # the last refusal's lines, not the "N refusals in a row" head
                                  "text": f"{attempts} refusals in a row at {self.boundary}; the last:\n\n{refusal.text}"})
                outcome = self.handle_refusal(refusal)
                if outcome == "retry" and refusal.retry:
                    try:
                        refusal.retry()
                        self.drop_standing()    # E2, the retried step went through
                        return
                    except Refusal as again:
                        refusal = again
                        continue
                return  # `continue`: back to `where`

    # --- the person's answer -----------------------------------------------------------------
    def judged_reply(self, qtext: str, words: str, kind: str) -> str:
        """What the judge reads in the person's own words, as a pre-filled option (J6).

        `gate_reply_intent` and `gate_stand_gap_option` were in the registry, calibrated at 0.9,
        and called only by an orchestrator a phase file instructs - in a driver run nothing asked
        them, so every answer in a person's own words went to a conductor session that spent its
        first turns deciding which option that was. This asks for them at the boundary, in code.

        It records NOTHING. A gate decision is the person's authority and their verbatim words are
        what gets written, by the conductor, with the factory's own command; the judge only saves
        the turns spent asking "did you mean approve or approve with edits". That line is the
        plan's own (section 10.6): the judge does not pass a gate, does not lift a block and does
        not authorise a write. What it buys is that the reading is printed back to the person here,
        in the log, where a misread is visible at once instead of after the write.
        """
        try:
            import judge_reply
        except Exception:                                # pragma: no cover - broken install
            return ""
        try:
            if "stand" in kind or "stand gap" in qtext.lower()[:2000]:
                got = judge_reply.stand_gap_option(words, ticket=self.task, stage=self.boundary)
            else:
                got = judge_reply.intent(qtext, words, ticket=self.task, stage=self.boundary)
        except Exception as exc:
            return f"the judge could not be asked ({type(exc).__name__}); decide from the words"
        if got.get("status") != "ok":
            return ""
        value, leaning = got.get("value"), got.get("leaning")
        read = value or leaning
        if not read:
            return ""
        line = (f"{read} (confidence {got.get('confidence')}, {got.get('judgment')}, "
                + ("decided" if got.get("decided") and value else "a leaning only") + ")")
        print(f"the judge reads their answer as: {line}")
        return line

    def report_attribution(self, gate: str, words: str) -> dict:
        """Which items of the gate packet the answer names, and which it does not — printed.

        P3's second half. The decision keeps the whole answer, and that is not the same as
        knowing what it settled: on TP1-15045 the six readings the person signed lived in
        `stage_overrides[]` and nothing checked that each item of the packet had a record. It
        worked because the wordings happened to match the cards. What is not named is printed as
        not named — never dropped, and never read as settled (FR-41).
        """
        try:
            import gate_brief
            items = gate_brief.packet_items(self.task_root, gate)
            said = gate_brief.attribute(items, words)
        except Exception as exc:                         # pragma: no cover - a broken checkout
            print(f"gate {gate}: the answer could not be read against the packet "
                  f"({type(exc).__name__}: {exc})")
            return {}
        if said["named"]:
            print(f"gate {gate}: their answer names {', '.join(said['named'])}")
        if said["not_named"]:
            print(f"gate {gate}: NOT named in their answer, so nothing here is settled by it: "
                  + ", ".join(said["not_named"][:20]))
        self.answer_row(f"gate {gate} decision recorded with {len(words)} characters; items "
                        f"named: {', '.join(said['named']) or 'none'}; not named: "
                        f"{', '.join(said['not_named']) or 'none'}", "", what=f"the note of your gate {gate} decision", extra=("--by", "driver"))
        return said

    def shown_packet(self, kind: str) -> str:
        """The text of the gate question the driver SHOWED the person ("" when there is none to read).

        t-291 (t-279 F5): `state/driver-question.md` while the question is open and is this gate's. The kept-answer
        retry in `gate_repair` runs after the file was filed as answered, and holds none: it gets "" and the answers
        are recorded against the row as it stands, as they always were."""
        try:
            if (self.state.get("asked") or {}).get("kind") != kind:
                return ""
            path = self.question_path()
            return path.read_text(encoding="utf-8", errors="replace") if path.is_file() else ""
        except OSError:
            return ""

    def gate_question_lines_note(self, words: str) -> str:
        """GW1-34: the note for the conductor when the gate A words hold a line about an open register question that no reader
        understood, or when the register cannot be read (an unknown is never a pass, FR-59); "" when there is none."""
        import question_register as QR
        self.question_lines_shown = ""
        tail = "the lines about its questions were not checked, so the approval is not recorded."
        try:
            view = QR.load(self.task_root)
        except Exception as exc:                 # F6: `load` can raise; not knowing is the conductor's, the driver does not stop (FR-59)
            return f"\n\nThe question register could not be read ({type(exc).__name__}: {exc}); {tail}"
        if view["skipped"]["unreadable_file"] or (view["problems"] and not view["questions"]):
            why = (view["problems"] or ["the answers file could not be read"])[0]
            return f"\n\nThe question register could not be read ({why}); {tail}"
        lines = QR.question_lines_unread(words, view["questions"])
        if not lines:
            return ""
        shown = "; ".join(f"{item['id']}: \"{item['line']}\"" for item in lines)
        self.question_lines_shown = shown        # F4: the person's text for these lines (no commands), read by `kept_answer_text`
        # GW1-42: a line that seems to answer with one letter (`Q1: a (see the ticket)`) is named with that letter, so the closed question
        # to the person is `confirm Q1 - a?`; the letter is a hint, the code records nothing (FR-12). A line cut for display is not read.
        letters = {q["id"]: q.get("letters") for q in view["questions"] if isinstance(q, dict)}
        near = []
        for item in lines:
            found = QR._TOKEN.fullmatch(item["line"])
            letter = None if item["line"].endswith("...") or not found else QR.near_answer(found.group("value"), letters.get(item["id"]))
            if letter:
                near.append(f"{item['id']} - {letter}")
        hint = (" Seems to answer with one letter: " + "; ".join(near) + ". Ask the person \"confirm "
                + "?\" / \"confirm ".join(near) + "?\" as a closed question; record the letter only on their yes.") if near else ""
        return ("\n\nLines about questions the code could not read: " + shown + "." + hint + " Record each with `question_register.py --answer <id> "
                "--reading <letter>` (ask the person a closed question where the words are unclear) or keep it open (`--defer`), then the "
                "kept approval records.")

    def record_by_code(self, kind: str, stage: str, words: str, again: bool = False, approved_by: str = "", apply_words: str = "") -> bool:
        """The person's words, put on the record by the command the boundary already implies.

        A GATE is recorded here only as an approval (C1-4b, I1): `approved_by == "option"` (the person chose `approve` from the
        seam's own options; `words` are the original answer's) or `approved_by == "token"` (the answer was read as the approval word
        when it was kept, `gate_approval`), or the words themselves are the gate's approval word (`gate_approval`). Any other words
        return False before anything is applied or written - the position invariant: nothing at a gate is stamped as an approval
        that is not one, whichever caller (`take_answer`, the kept road of `gate_repair`) comes here.

        Each gate A answer is recorded against the fingerprint its card carried in the packet the person was
        shown (`shown_packet`, `gate_brief.shown_hashes`), so a row that changed between the card and the answer
        reads `changed_since_answer`.

        TP1-13797, 26.09: of seventeen conductor calls, six were exactly this — running
        `waiver.py --remark`, `accept-gap` or `story_step finish` with words the driver was
        already holding ($3.18), and seven more ended `ask_person` with an empty `did` ($6.05).
        The conductor is a helper for a problem; a recording is not a problem. A gate keeps the
        whole answer, not its first sentence: `authorization_source` came out 215 characters long
        while the readings the person signed lived only in stage overrides.

        `apply_words` (t-891 F-2): the part of `words` the card lines are read from ("" = all of `words`). A second answer at a gate
        carries the earlier one as a tail of `words` (the decision keeps both); the plan takes the NEW answer's lines alone, so a
        correction `Q5: a` after `Q5: b` applies `a` and is no conflict for `parse_choices`."""
        if kind in ("gate_A", "gate_B"):
            gate = kind[-1]
            if approved_by not in ("option", "token") and not self.gate_approval(kind, words):
                return False
            # GW1-34: the decision SEALS the plan, so a line about a register question that no reader understood (`Q1:`, `Q1: a (note)`)
            # is read BEFORE it is recorded - by the conductor, who asks the person a closed question where the words are unclear. The
            # code never guesses the letter. Position invariant: after `gate_approval` (only an approval gets here) and before the
            # controller call (nothing is recorded); `approve as is` (the person's words are stronger) and a dry run do not return.
            self.question_lines_note = ""
            self.gate_refusal = ""               # F5: an older refusal gives no items to this call
            if gate == "A" and not self.dry and not self.as_is_word(kind, words):
                self.question_lines_note = self.gate_question_lines_note(apply_words or words)
                if self.question_lines_note:
                    print(f"gate {gate}: lines about questions the code could not read; the conductor takes the answer")
                    return False
            # DC1-19: what the person's answers DECIDE is recorded and applied by the ONE executor, `controller.py --operation
            # gate-decision`, the same call the conductor makes (AR-15): gate A lays them over the plan BEFORE the decision is built,
            # gate B records them and touches no plan. This call hands over what only the driver holds, BY FILE: the NEW answer's lines
            # without the earlier answer it keeps (`apply_words`; a correction `Q5: a` after `Q5: b` is no conflict), the stand gaps
            # the person ACCEPTED, a LEVEL accept's remedy per case, and the card hashes the person was shown (t-279 F5).
            # A dry run records no answer (`--no-answers`). The controller's answer is printed (P1).
            try:
                import gate_brief
                shown = gate_brief.shown_hashes(self.shown_packet(kind))
            except Exception:                    # a broken checkout: the answers are still recorded, unfingerprinted
                shown = {}
            # t-364: a stand gap the person ACCEPTED at this gate (`<case id>: accept`, read by `take_stand_gap_answers`) is handed to
            # the executor in its own token, so the waiver and the `blocked_by_env` row are two records of ONE read line; a token the
            # person wrote themselves is not repeated
            lines = apply_words or words
            accepted = [] if gate != "A" else [case for case in self.state.get("stand_accept_cases") or []
                                               if not re.search(r"^\s*(?:[-*•]\s+)?`?" + re.escape(case) + r"`?\s*:\s*accept as blocked",
                                                                lines, re.IGNORECASE | re.MULTILINE)]
            # B-414 F19 (a): a LEVEL accept blocks each of its cases by the level gap's own remedy (`{case: remedy}`) - the
            # executor's `_stand_remedy` derives one from the case's own preconditions and blocks nothing for a case
            # whose preconditions are all met. REACH (M6 iv): `acceptance.blocked_instances` blocks a row that names no
            # instance only for a single-instance case whose instance proves no other case; a test proving two level-
            # accepted cases is skipped silently (`outside`), and a multi-instance case is refused to the automator.
            remedies = (self.state.get("stand_accept_remedies") or {}) if gate == "A" else {}
            answer_args = ["--no-answers"] if self.dry else [
                "--answers-by", "driver",
                *(["--answers-file", str(self.words_file(lines + "".join(f"\n{case}: accept as blocked" for case in accepted), f"answers{gate}"))]
                  if lines.strip() else []),
                *(["--shown-file", str(self.json_file(shown, f"shown{gate}"))] if shown else []),
                *(["--remedies-file", str(self.json_file(remedies, f"remedies{gate}"))] if remedies else [])]
            # RH1-6: `approve as is` (a closed data word of gate A, `gate_brief.as_is_words`) is declared to the controller by a flag; the
            # controller then records one waiver per open item with these words (never `*`) before the decision. Any other approval
            # records only over items the person has already worded.
            code, out = self.py("controller.py", "--task-root", str(self.task_root),
                                "--operation", "gate-decision", "--gate", gate,
                                *(["--as-is"] if self.as_is_word(kind, words) else []),
                                # gate B: the bug reporter runs on the person's words even with no draft chosen (13797), so the
                                # driver's decision orders it (`--bugs ordered`, t-1509 GB-1b); gate A has no orders
                                *(["--bugs", "ordered"] if gate == "B" else []),
                                *answer_args, *self.words_args(words, f"gate{gate}"))
            self.gate_answer_told(gate, out)
            if code:
                self.gate_refusal = out
                # `again`: the words are already kept (`gate_repair`, C3) and the conductor has had them once.
                print(f"gate {gate}: the decision did not record by code ({out[-200:]}); "
                      + ("the gate is shown again" if again else "the conductor takes it"))
                return False
            # B3: the stand-gap state is consumed only by a call that RECORDED. A refused call applied none of the tokens and the kept
            # road re-sends only the person's words, so what `take_stand_gap_answers` read from them must still be here
            if not self.dry:
                self.state.pop("stand_accept_cases", None)
                self.state.pop("stand_accept_remedies", None)
            print(f"gate {gate}: recorded by code, {len(words)} characters of the person's own words")
            # t-211: this gate's series of repair rounds and the kept answer are over with its decision.
            self.state.pop("gate_answer_kept", None)
            if isinstance(self.state.get("gate_repair"), dict):
                self.state["gate_repair"].pop(gate, None)
            self.report_attribution(gate, words)
            return True
        # Everything else — a block lifted, a contract changed, a dead dispatch released — is a
        # judgement about WHICH block the words pass, and that is what the conductor is for.
        return False

    def take_stand_gap_answers(self, kind: str, words: str, qtext: str, stage: str, dispatch: str, keep_earlier: bool = False) -> dict:
        """Gate B (t-342, B-272): run the recording of a person's stand-gap answers FOR them.

        The card shows four answers in words and one form, `<case id>: <word>` (`gate_brief.gate_b_card_lines`,
        the words in `references/question-vocabulary.json`). A line that form reads is recorded here with the
        command the card used to print for the person to type - `waiver.py --stage S9 --block "stand gap: <id>"` -
        with the person's own line as the words (P13), so `contract.stand_gap_decisions` reads the same record as
        before (its option is the decision's first word). The command is the DRIVER's (FR-9: the decision has an
        executor; FR-48: a routine command runs from code) and is never shown to the person.

        Returns {} for any other question, or {"recorded": [...], "unread": [...], "note": str}. `unread` are lines
        that look like the form and cannot be read (an id that is no stand gap of this gate, a word outside the
        closed list, an id two gaps share); the caller sends the answer to the conductor with `note`, which names
        them - never silently dropped. A line that is not the form at all stays in the person's words, which the
        gate decision keeps whole.

        EDGES: two lines for one gap - the last counts, and the line printed says so; a story with no stand gaps -
        nothing is read and nothing is printed; a recording that fails raises a Person in words (the record's own
        text goes to the details file), the lines that did record stay recorded, and an answer sent again records
        them again harmlessly (`waiver.py` replaces the entry of the same block).

        `keep_earlier` (C2-7 §5.3, t-722 finding 6): this answer is a SECOND answer at the gate (a non-token to a question the seam
        raised); `stand_accept_cases` / `stand_accept_remedies` an EARLIER answer set are not dropped, so they reach `record_by_code`
        with the cases and remedies this answer adds (merged where they are set)."""
        # t-364: the SAME reader serves gate A (stage S5, the cards of `gate_brief.stand_gap_cards(.., "A")`) and the
        # `<check id>: accept` door of a rehearsal finding (`read_finding_doors`, both gates). Gate B's own lines are
        # read exactly as before.
        if kind not in ("gate_A", "gate_B") or self.dry:
            return {}
        gate = kind[-1]
        default_stage = "S5" if gate == "A" else "S9"
        if not keep_earlier:
            self.state.pop("stand_accept_cases", None)   # gate A: the cases whose every gap was accepted (read by `record_by_code`)
            self.state.pop("stand_accept_remedies", None)   # ... and the remedy each of them is blocked by when a LEVEL accepted it
        try:
            # B-426 D7: `C` is bound HERE, in the try, as it always was - an import that fails ends the reading
            # with the line below; the helpers import what they read themselves (`gate_brief` for the form line of the
            # refusal and the note)
            import contract as C
            read =self._stand_gap_lines(kind, gate, words, qtext)
        except Exception as exc:
            print(f"gate {gate}: the stand-gap lines of the answer could not be read ({type(exc).__name__}: "
                  f"{' '.join(str(exc).split())[:160]}); the answer is recorded whole, as it always was")
            return {}
        if read is None:
            return {}
        gaps, found, doors = read["gaps"], read["found"], read["doors"]
        forms, rehearsal = read["forms"], read["rehearsal"]
        if gate == "A":
            # `<case id>: accept as blocked` is the token of ANOTHER reader (`planning_contract.apply_gate_answers`, run by
            # `record_by_code`: the none card and every case with no gap card): not an unreadable stand-gap line. GW1-33 F7: the same
            # for `manual` / `automate` - the controller applies those case tokens too (`question_register.is_case_decision`)
            import question_register as QR
            found["unread"] = [item for item in found["unread"]
                               if not ((m := re.search(r":\s*([^:]+)$", item["line"])) and QR.is_case_decision(m.group(1).lower()))]
        if gate == "B":
            # P4 (id overlap): `<case id>: intended|bug|open` on a case that ALSO has a stand-gap card is the exploratory reader's
            # (`take_exploratory_answers`), not an unreadable stand-gap line. INVARIANT: only a line whose word is one of the
            # exploratory words AND whose id is a question line shown leaves this list; a stand-gap line that is really unread stays.
            import gate_brief
            cases = {gate_brief._id_key(s.get("case")) for s in self.state.get("shown_exploratory") or [] if isinstance(s, dict) and s.get("case")}
            index = gate_brief.exploratory_word_index()
            found["unread"] = [item for item in found["unread"]
                               if not ((m := gate_brief._FORM_LINE_RE.match(item["line"])) and gate_brief._id_key(m.group("id")) in cases
                                       and gate_brief._word_key(m.group("word")) in index)]
        revoked = self.revoke_environment_properties(gate, found.get("revokes") or [])
        found["unread"] = found["unread"] + doors["unread"] + revoked
        out = {"recorded": [], "unread": [item["line"] for item in found["unread"]], "note": "", "probed": []}
        failed = []
        failed_cases = set()      # B-361: the case of every gap whose own record failed (no carry is written for it)
        decided = {}
        try:
            decided = C.stand_gap_decisions(json.loads((self.task_root / "pipeline.json").read_text(encoding="utf-8")))
        except Exception:
            pass
        # every gap record, then every door record - the order the comment below depends on; each helper returns what it
        # recorded and what failed, and the lists grow here, in that order (S2)
        for recorded, bad, bad_cases in (self._record_gap_lines(gate, found["read"], forms, default_stage),
                                         self._record_door_lines(gate, doors["read"], gaps, default_stage)):
            out["recorded"] += recorded
            failed += bad
            failed_cases |= bad_cases
        # the container a person named on a which-container card (`read_finding_doors` `probes`): the read-only check runs FIRST
        # (`gate_preflight.Rehearsal._probe_verdict`, the verdict as the probe wrote it, never a sentence read here, FR-12) and the
        # write command runs ONCE, through `probe_move`, ONLY on `matched` (a write's exit 0 says nothing of the check: AR-28, FR-59).
        # Any other verdict, a timeout, an unreadable answer or a refused write joins `failed` with the verdict in words and writes
        # nothing, so another name stays answerable (AR-25). No waiver is recorded (nothing is passed: the next rehearsal proves the
        # stand with the registered probe's own check), the gate stays open, the person is not asked again (FR-3), nothing is retried.
        for entry in doors.get("probes") or []:
            if entry["replaced"]:
                print(f"gate {gate}: {entry['id']} was answered more than once; the last line counts: {entry['line']}")
            try:
                import gate_preflight
                said = gate_preflight.Rehearsal.named_container_said(Path(self.project), entry["name"], entry["probe"])
                if said:
                    failed.append((entry["id"], entry["line"], said))
                    continue
                self.probe_move(gate, [], {"argvs": [(entry["profile"], entry["argv"])]}, {"moves": []})
            except RepairFailed as exc:
                failed.append((entry["id"], entry["line"], f"the check matched, but registering it was refused ({exc.what}): {exc.text}"))
                continue
            except Exception as exc:
                failed.append((entry["id"], entry["line"], f"{type(exc).__name__}: {exc}"))
                continue
            out["probed"].append(entry)
            print(f"gate {gate}: {entry['id']}: the check of the stand's container `{entry['name']}` matched, and the probe is registered "
                  f"for `{entry['profile']}` on the person's word ({entry['line']})")
        if gate == "A":
            # F1 (FR-10): an `accept` on a card pointer's door (`case_preconditions-1: accept`) passes the block of THAT gap -
            # it is the same word as `<case id>: accept`, so it feeds the `accept as blocked` row the same way
            prefix = C.STAND_GAP_MATCH_PREFIX + " "
            by_gap = {str(g.get("id")): g for g in gaps}
            via_door = [{"gap": by_gap[str(e["door"]["block"])[len(prefix):]], "option": "accept", "line": e["line"]}
                        for e in doors["read"] if e["word"] == "accept" and e["door"].get("option") == "any"
                        and str(e["door"]["block"]).startswith(prefix) and str(e["door"]["block"])[len(prefix):] in by_gap]
            # B-361 (D-0026, FR-7): the gate A word travels under the CASE key, so the gate B card and the delivery check
            # find it (`stand_gaps.gate_b_answers`, `check_delivery.gather`). Both steps (R1b, then `carry_environment_
            # properties`, which also carries what the environment record covers) run AFTER every gap record of this
            # answer was written, and BEFORE the `failed` raise below: a case whose own gap record failed gets no carry (the
            # answer is asked again whole), and a revoke never follows the re-carry of the same answer. Neither step raises
            # (FR-3): what cannot be written is told, and gate B asks.
            self._revoke_changed_carries(found, gaps, default_stage)
            # R1 (`stand_gaps.write_carries`) and R8(c): the accepted cases, their remedies, the carries - the person's own lines
            # and what the environment record covers, in one call
            self.carry_environment_properties("A", gaps, found["read"] + via_door, decided, failed_cases)
        failure = ""
        if failed:
            # C1-4b (G22, FR-3): a record the story refused is the FACTORY's to repair, not a reason to make the person send their whole
            # answer again. The failed lines join `unread` (so the gate is not recorded by code over them), and the refusal text goes
            # whole into the note: the answer reaches the conductor ONCE with the failed line and what the record said.
            failure = ("\n\n## Lines of the answer the story's record REFUSED (the factory's to repair; the person is not asked to "
                       "send them again; what the driver could record is recorded)\n"
                       + "\n".join(f"- {shown} (\"{line}\"): {' '.join(str(text).split())[:600]}" for shown, line, text in failed))
        out["note"] = failure + self._relay_note(out, found, RelayCtx(forms, gaps, rehearsal, gate, default_stage))
        out["unread"] += [line for _shown, line, _text in failed]      # after the note: the relay note lists only lines nobody could read
        # GW1-33 F2: lines the code UNDERSTOOD but did not carry out, or that ask: they hold the approval for the conductor
        # (`gate_lines_over_approval`); a plain unread line may ride it. The refused record's text lives only in `note`.
        out["hold"] = ([line for _shown, line, _text in failed] + [item["line"] for item in revoked]
                       + [line for line in out["unread"] if "?" in line])
        return out

    EXPLORATORY_REWORK = {"stage": "S7", "role": "qa-failure-analyst", "cause": "question_answer"}

    def keep_shown_exploratory(self) -> str:
        """Gate B is being shown: keep the question lines of the findings it shows (`state["shown_exploratory"]`, from the function
        that renders them), so an answer is read against what the person SAW (a line corrected since is unread, never answered).
        Returns the sentence for the top of the packet when a question the person left `open` at their last answer is asked again
        (FR-7: the same boundary is not re-asked with the same text); "" otherwise. Never raises: no map, no answer read by code."""
        try:
            import gate_brief
            shown = gate_brief.exploratory_shown(self.task_root)
        except Exception:
            shown = []
        self.state["shown_exploratory"] = shown
        left = self.state.get("exploratory_open")
        ids = {s["line"] for s in shown}
        kept = {line: case for line, case in (left if isinstance(left, dict) else {}).items() if line in ids}
        self.state["exploratory_open"] = kept
        cases = sorted({case for case in kept.values() if case})
        return ("Still open from your last answer: " + ", ".join(cases) + " - you left "
                + ("it" if len(cases) == 1 else "them") + " open, nothing was recorded for "
                + ("it" if len(cases) == 1 else "them") + ", so the question is asked again.") if cases else ""

    def take_exploratory_answers(self, kind: str, words: str, qtext: str) -> dict:
        """Gate B (P2 fix round, critic t-1579 M1): carry out the person's answers to the QUESTION LINES of the findings
        (`<case id>: intended|bug|open`, `gate_brief.read_exploratory_answers`, read against `shown_exploratory`). Executors, in
        this order (the re-run S7 must see the confirmations): every `intended` (the line is corrected to `person_confirmed` by the
        person's word and, for a line with a question, the question is answered with the reading `now`), every `open` (a line with
        a question is `deferred_to_report`, one without is remembered so the next gate B says it is asked again), then ONE rework of
        S7 for all `bug` lines together with the person's whole words (the seam's record, run by `seam_rework_step`). A `bug`
        beside the gate's approval word is applied NOT (FR-12: the factory does not choose between contradicting words); both go to the
        conductor. Returns {} for another question, a dry run or nothing to read, else {"recorded", "unread", "note"}: a line that
        cannot be read or whose executor failed is `unread`, so the gate is not recorded by code over it and the answer reaches the
        conductor with the lines named (FR-3: the factory's failure never asks the person to send it again)."""
        if kind != "gate_B" or self.dry:
            return {}
        try:
            import gate_brief
            import exploratory_findings as EF
            shown = self.state.get("shown_exploratory") or []
            if not shown or not any(gate_brief._FORM_LINE_RE.match(raw) for raw in str(words or "").splitlines()):
                return {}
            register = EF.read(self.task_root)
            by_id = {line["id"]: line for line in register["lines"]}
            # live = the live line of each chain, and a line the person's own `intended` already replaced (the same word again is a
            # no-op, E11, not "the finding changed")
            live = {line["id"] for line in register["active"].values()} | {
                line["id"] for line in register["lines"] if line.get("_status") == "superseded"
                and (by_id.get(line.get("_next")) or {}).get("oracle_status") == EF.PERSON_CONFIRMED}
            try:
                gaps, covered = gate_brief.gate_b_split(self.task_root)
                card_ids = set(gate_brief._ids_of(list(gaps) + list(covered)))      # the ids a stand-gap card answers (m-6)
            except Exception:
                card_ids = set()                 # unknown: a word of another reader is read by nobody here, so it goes to the conductor
            found = gate_brief.read_exploratory_answers(words, shown, live, card_ids=card_ids)
        except Exception as exc:
            print(f"gate B: the question lines of the answer could not be read ({type(exc).__name__}: "
                  f"{' '.join(str(exc).split())[:160]}); the answer is recorded whole, as it always was")
            return {}
        unread = list(found["unread"])
        recorded, failed, bugs = [], [], []
        approval = self.gate_approval(kind, words)
        for entry in sorted(found["read"], key=lambda e: gate_brief.EXPLORATORY_OPTIONS.index(e["option"])):
            if entry["option"] == "bug":
                if approval:
                    unread.append({"line": entry["line_text"], "why": "a bug answer and the approval word in one answer; neither is applied"})
                else:
                    bugs.append(entry)
                continue
            try:
                done = (self._confirm_exploratory(entry, by_id.get(entry["line"]), words) if entry["option"] == "intended"
                        else self._leave_exploratory_open(entry, words))
            except Exception as exc:
                failed.append({"line": entry["line_text"], "why": ' '.join(str(getattr(exc, "text", "") or exc).split())[:300]})
                continue
            if done:
                recorded.append(entry["line_text"])
                print(f"gate B: {entry['case']}: {entry['option']} is carried out on the person's word ({entry['line_text']})")
        if bugs:
            args = dict(self.EXPLORATORY_REWORK, cases=sorted({e["case"] for e in bugs}))
            try:
                facts = self.no_move_facts({"kind": kind})
                clean, rule = NM.check_args(args, facts)
                if clean is None:
                    raise ValueError(rule)
                self.record_seam_rework(clean, self.answer_file(), self._bug_preface(bugs, by_id))
                recorded += [e["line_text"] for e in bugs]
                print(f"gate B: {', '.join(args['cases'])}: bug - the failure analysis is sent back, with your words, on its next step")
            except Exception as exc:
                failed += [{"line": e["line_text"], "why": ' '.join(str(getattr(exc, "text", "") or exc).split())[:300]} for e in bugs]
        out = {"recorded": recorded, "unread": [item["line"] for item in unread + failed], "note": ""}
        if recorded or unread or failed:
            out["note"] = ("\n\n## Question lines of the findings in this answer (the driver read them by code)\n"
                           + "".join(f"- recorded by code, do not record again: {line}\n" for line in recorded)
                           + "".join(f"- not read: {item['line']} ({item['why']})\n" for item in unread)
                           + "".join(f"- the factory could not carry it out: {item['line']} ({item['why']}); this is the factory's to repair, "
                                     "the person is not asked to send it again\n" for item in failed))
        return out

    def _question_row(self, qid: str):
        """The question register's row `qid`, or None: the ONE lookup of the exploratory executors (`question_register.load`, which
        raises on an unreadable register - the caller's line then fails to the conductor, never a silent pass)."""
        import question_register as QR
        return next((q for q in QR.load(self.task_root)["questions"] if q["id"] == qid), None) if qid else None

    def _bug_preface(self, bugs: list, by_id: dict) -> list:
        """One line per `bug` answer for the front of the rework's reason (critic t-1592 M-a, F10 (b)): the case, the finding's
        statement - what was seen - and before/now when the question row knows them (`report_facts.exploratory_bug_preface`). A
        line whose statement cannot be read says `not recorded`; the person's words travel whole either way."""
        import report_facts
        return [report_facts.exploratory_bug_preface(e["case"], by_id.get(e["line"]) or {}, self._question_row(e.get("qid")))
                for e in bugs]

    def _confirm_exploratory(self, entry: dict, line, words: str) -> bool:
        """`intended`: the question is answered with the reading `now` when the question says which reading that is (one writer,
        `question_register.record`), then the line is corrected to `person_confirmed` with the person's line (one writer,
        `exploratory_findings.append`). A line already confirmed is skipped (repeating words writes nothing); a line that is not the
        live line of its chain raises (the finding changed). False when nothing was written."""
        import contract as C
        import exploratory_findings as EF
        import question_register as QR
        if isinstance(line, dict) and line.get("_status") == "superseded":
            newer = next((l for l in EF.read(self.task_root)["lines"] if l.get("id") == line.get("_next")), {})
            if newer.get("oracle_status") == EF.PERSON_CONFIRMED and newer.get("_status") == "active":
                return False                  # the person's own word was carried out already: repeating it writes nothing
        if not isinstance(line, dict) or line.get("_status") != "active":
            raise ValueError("the finding changed since you saw it")
        if line.get("oracle_status") == EF.PERSON_CONFIRMED:
            return False
        if entry.get("qid"):
            row = self._question_row(entry["qid"])
            index = C.claim_reading_index(row, "now") if row else None
            if index is not None:
                QR.record(self.task_root, entry["qid"], "answered", words, "gate B", self.QUESTION_ANSWER_BY,
                          entry.get("row_hash") or row["row_hash"], reading=QR.LETTERS[index])
        fresh = {key: line[key] for key in ("kind", "title", "statement", "refs", "probe", "verification_status", "question",
                                            "owner_role", "missing_prerequisite") if key in line}
        fresh.update(op="correct", oracle_status=EF.PERSON_CONFIRMED,
                     why_not_a_bug=f'you said at gate B: "{entry["line_text"]}"',
                     evidence_refs=[{"path": ref["path"]} for ref in line.get("evidence_refs") or [] if isinstance(ref, dict) and ref.get("path")],
                     corrects={"id": line["id"], "reason": "confirmed as intended by the person at gate B"})
        if isinstance(line.get("origin"), dict):
            fresh["origin"] = line["origin"]
        EF.append(self.task_root, fresh, by=self.QUESTION_ANSWER_BY)
        return True

    def _leave_exploratory_open(self, entry: dict, words: str) -> bool:
        """`open`: a line with a question is `deferred_to_report` (not asked again, listed by the report - the question register's own
        state and its own way out, `--reopen`); a line without one is remembered, and the next gate B says it is asked again. The
        findings register is not written. False when nothing was written."""
        import question_register as QR
        if entry.get("qid"):
            row = self._question_row(entry["qid"])
            if row is not None and row.get("status") == QR.DEFERRED and not QR.is_open(row):
                return False
            QR.record(self.task_root, entry["qid"], QR.DEFERRED, words, "gate B", self.QUESTION_ANSWER_BY,
                      entry.get("row_hash") or (row or {}).get("row_hash", ""))
            return True
        self.state.setdefault("exploratory_open", {})[entry["line"]] = entry["case"]
        return True

    def _stand_gap_lines(self, kind: str, gate: str, words: str, qtext: str) -> dict | None:
        """B-426 D7: the READING half of `take_stand_gap_answers`, run inside its `try` (an exception here prints the
        "could not be read" line and returns {} there). None means "return {}": no line of the form in the words. Otherwise
        the gaps, what `read_stand_gap_answers` found, the rehearsal's doors, the form ids and the rehearsal itself."""
        import gate_brief
        if not any(gate_brief._FORM_LINE_RE.match(raw) for raw in str(words or "").splitlines()):
            if gate == "A":
                self.carry_environment_properties("A")   # no line to read - what the environment record decided still carries
            return None                     # no line of the form `<id>: <something>`: nothing to read, nothing to ask for
        rehearsal = None
        if gate == "A" or any(self._FINDING_LINE_RE.match(raw) for raw in str(words or "").splitlines()):
            rehearsal = self.rehearse(gate)          # ONE rehearsal serves the gaps (gate A) and the doors
        covered = []
        if gate == "A":
            import stand_gaps
            gaps = stand_gaps.collect(self.task_root, "A", rehearsal=rehearsal)
            covered = [g for g in (self.state.get("shown_gaps") or {}).get("A", {}).get("covered") or [] if isinstance(g, dict)]
        else:
            gaps, covered = gate_brief.gate_b_split(self.task_root)
        findings = [f for f in (rehearsal or {}).get("findings") or [] if isinstance(f, dict) and f.get("id")]
        # t-364 attempt 2, F3: a door line is read only against the packet the person was SHOWN (`qtext`, the question
        # file the answer belongs to - the text `shown_packet(kind)` reads): finding ids are ordinal per check, so a
        # rehearsal that changed since the packet could otherwise pass a block the person never saw under that id
        doors = (self.read_finding_doors(words, findings, qtext or self.shown_packet(kind),
                                         (self.state.get("shown_doors") or {}).get(gate))
                 if rehearsal is not None else {"read": [], "unread": []})
        found = gate_brief.read_stand_gap_answers(words, gaps, covered=covered)
        forms = gate_brief.stand_gap_form_ids(list(gaps) + covered)
        # F1: a line whose id is a finding of THIS rehearsal is the door reader's, never an unreadable stand-gap line
        finding_ids = {str(f["id"]) for f in findings}
        found["unread"] = [item for item in found["unread"]
                           if not ((m := self._FINDING_LINE_RE.match(item["line"])) and m.group("id") in finding_ids)]
        return {"gaps": gaps, "found": found, "doors": doors, "forms": forms, "rehearsal": rehearsal}

    def _record_gap_lines(self, gate: str, entries: list, forms: dict, default_stage: str) -> tuple:
        """B-426 D7: write the record (`waiver.py`) of every stand-gap line the reader read, in order. Returns
        (recorded ids, failed [(shown, line, text)], the cases of the gaps whose own record failed)."""
        import contract as C
        recorded, failed, failed_cases = [], [], set()
        # twin of _record_door_lines kept on purpose (t-666 F-4): four of eight steps differ; one loop would need a kind switch
        for entry in entries:
            gap, option = entry["gap"], entry["option"]
            shown = forms.get(str(gap.get("id")), str(gap.get("id")))
            if entry["replaced"]:
                print(f"gate {gate}: {shown} was answered more than once; the last line counts: {entry['line']}")
            # t-364 attempt 2, F4 (FR-7): a word the person gave at the OTHER gate for the same case is not a reason to
            # skip this one - each gate's card reads its own gap id, so ONE word is written as TWO records, and the card
            # the person just answered (and the dashboard) shows it answered
            # the decision's FIRST word is the option (`contract.stand_gap_decisions` reads it from there); the rest is
            # the person's own line, and - when they wrote the gap twice - the earlier lines this one replaces
            said = C.person_decision(option, entry["line"], entry["replaced"])
            code, text = self.py("waiver.py", "--task", self.task, "--stage", str(gap.get("stage") or default_stage),
                                 "--block", f"{C.STAND_GAP_MATCH_PREFIX} {gap.get('id')}", "--decision", said, *self.waiver_road())
            if code:
                failed.append((shown, entry["line"], text))
                import stand_gaps
                failed_cases.update(stand_gaps.gap_cases(gap))
                continue
            recorded.append(shown)
            print(f"gate {gate}: stand gap {shown}: recorded on the person's word, as {option} ({entry['line']})")
            if entry.get("lasting"):
                # B-414 R8(b): `accept always` - the story's answer above, and ONE row in the project's environment record, with
                # the person's line whole. A failure is printed, never added to `failed` (FR-3: it is the factory's, not a reason to
                # ask the person to send the whole answer again)
                import stand_gaps
                stand_gaps.record_lasting(self.project, entry, self.task, print)
        return recorded, failed, failed_cases

    def _record_door_lines(self, gate: str, entries: list, gaps: list, default_stage: str) -> tuple:
        """B-426 D7: write the record of every rehearsal-finding door the reader read, in order; the same return as
        `_record_gap_lines`."""
        import contract as C
        recorded, failed, failed_cases = [], [], set()
        # twin of _record_gap_lines kept on purpose (t-666 F-4): four of eight steps differ; one loop would need a kind switch
        for entry in entries:
            # a rehearsal finding's door (`<check id>: accept` and the person's reason): the block and the stage are the
            # finding's own `waives` (gate_preflight), the person's line is quoted whole as the decision
            door, line = entry["door"], entry["line"]
            if door.get("option") == "product_gap":
                # D1-C2 (Q1-d): a product gap is the person's word about a requirement, recorded by its ONE writer and never a
                # waiver - so it can never become a `stage_overrides[]` row that `_plan_decision` files as "your words at gate A"
                import product_gaps
                path = self.words_file(line, "productgap")
                try:
                    ref = path.relative_to(self.task_root).as_posix() if path is not None else ""
                except ValueError:
                    ref = str(path)
                reqs, problem = product_gaps.record(self.task_root, str(door.get("row") or ""), line, ref, gate)
                if problem:
                    failed.append((entry["id"], line, problem))
                    continue
                recorded.append(entry["id"])
                print(f"gate {gate}: {entry['id']}: recorded as a product gap of {', '.join(reqs)} - the product has no such function, "
                      f"on the person's word ({line})")
                continue
            said = C.person_decision(entry["word"], line, entry["replaced"])
            code, text = self.py("waiver.py", "--task", self.task, "--stage", str(door.get("stage") or default_stage),
                                 "--block", str(door["block"]), "--decision", said, *self.waiver_road())
            shown = entry["id"]
            if code:
                failed.append((shown, line, text))
                if gate == "A" and str(door["block"]).startswith(C.STAND_GAP_MATCH_PREFIX + " "):
                    import stand_gaps
                    failed_cases.update(c for g in gaps if str(g.get("id")) == str(door["block"])[len(C.STAND_GAP_MATCH_PREFIX) + 1:]
                                        for c in stand_gaps.gap_cases(g))
                continue
            recorded.append(shown)
            print(f"gate {gate}: {shown}: the block `{door['block']}` is passed on the person's word ({line})")
        return recorded, failed, failed_cases

    def _revoke_changed_carries(self, found: dict, gaps: list, default_stage: str) -> None:
        """B-426 D7 (gate A only): R1b - take back, with `waiver.py --revoke`, the case-level `accept` an earlier answer
        carried for a gap whose word CHANGED in this answer. Prints one line per case; never raises on a failed revoke."""
        import contract as C
        import stand_gaps
        gap_cases = stand_gaps.gap_cases          # N6: ONE expansion of a gap to its cases (a level gap names several)
        # R1b: a gap's word CHANGED in this answer takes back the case-level `accept` an earlier answer carried (else gate
        # B settles on a word the person has since replaced). The cases: every case of the gap plus every case of every
        # gap with that id
        try:
            overrides = json.loads((self.task_root / "pipeline.json").read_text(encoding="utf-8")).get("stage_overrides")
        except Exception:
            overrides = []
        live = {C.stand_gap_id(o.get("match")): str(o.get("match")) for o in overrides if isinstance(o, dict)
                and str(o.get("stage") or "") == default_stage and not o.get("revoked_at")} if isinstance(overrides, list) else {}
        for entry in found["read"]:
            if entry["option"] == "accept":
                continue
            for case in dict.fromkeys(gap_cases(entry["gap"]) + [c for g in gaps if str(g.get("id")) == str(entry["gap"].get("id"))
                                                                 for c in gap_cases(g)]):
                if case not in live:
                    continue
                code, text = self.py("waiver.py", "--revoke", "--task", self.task, "--stage", default_stage, "--block", live[case],
                                     *stand_gaps.words_args(self.words_file, f"the person changed their answer at gate A: {entry['line']}", "revoke"), *self.waiver_road(False))
                print(f"gate A: {case}: the earlier acceptance of the whole case is taken back, you changed a word of it ({entry['line']})"
                      if not code else
                      f"gate A: {case}: the earlier acceptance could not be taken back ({' '.join(text.split())[-160:]}); gate B will ask again")
                live.pop(case, None)

    def _relay_note(self, out: dict, found: dict, ctx: RelayCtx) -> str:
        """B-426 D7: the note the conductor reads - what the driver already recorded, and the lines it could not read
        with everything the conductor needs to record them (critic t-346 F4/F3). Prints the one line about the unread
        lines. The note is "" when nothing was recorded and nothing was unread."""
        import gate_brief
        note = ""
        # critic t-346 F4: whenever ANY line was recorded the conductor is told so - the gate decision can still fail to
        # record by code and the words then reach it, with these lines already on the record.
        if out["recorded"]:
            note += ("\n\n## Stand-gap lines of this answer the driver has already recorded: "
                     + ", ".join(out["recorded"]) + " - do not record those again")
        if out.get("probed"):
            # not stand-gap lines: a container the person named, checked read-only (`matched`) and then registered; no waiver, no gate passed
            note += ("\n\n## Containers the person named on a runtime-probe card, already checked and registered by the driver (these are not "
                     "stand-gap lines and pass no gate; do not check or register them again): "
                     + "; ".join(f"{p['id']} = `{p['name']}` for profile `{p['profile']}` (the check said `matched`)" for p in out["probed"]))
        if out["unread"]:
            # critic t-346 F3 (FR-7: a guessed word reads back as "" and the gap is asked again): the note carries what
            # the conductor needs to record a gap in the form the reader reads - the block key, the stage and the
            # word -> option map, the last from the data file (`stand_gap_words`), never from prose.
            options = "; ".join(f"`{row['option']}` for " + ", ".join(f"`{w}`" for w in [row["word"], *row["synonyms"]])
                                for row in gate_brief.stand_gap_words())
            # t-409 H3 (FR-10, axis 5): the options are PER CARD. A card that carries `remedy.offers` (the reporter card) takes
            # ONLY those; a card with none takes all four, as every card did before. The line says which, in the same words
            # `skills/qa-story/phases/s4.md` says them, and never lets the map above speak for a card that does not take a word.
            keys = "\n".join(gate_brief.relay_card_line(g, ctx.forms.get(str(g.get("id")), g.get("id")), ctx.default_stage)
                             for g in ctx.gaps)
            # t-364: the doors of the rehearsal's findings, for a line `<check id>: accept` the driver could not read
            # (a finding with no door is a gap of the factory's own: the conductor says so, never passes it silently)
            door_keys = "\n".join(
                f"- {f['id']}: block `{d['block']}`, stage {d.get('stage') or ctx.default_stage}, word option `{d.get('option')}`"
                for f in (ctx.rehearsal or {}).get("findings") or [] if isinstance(f, dict) and f.get("id")
                for d in f.get("waives") or [] if isinstance(d, dict) and d.get("block"))
            # F3: a door line whose id no longer names the message the person read goes whole to the conductor, with the
            # CURRENT list, so it can ask what they meant (the same class as `shown_hashes` on a card)
            changed = ""
            if any(str(item.get("why") or "").startswith("the checks changed") for item in found["unread"]):
                changed = ("\n\nThe checks changed since the person read them; here is the current list (id and message) - "
                           "pass nothing by an id the person did not see with this message:\n"
                           + "\n".join(f"- [{f['id']}] {' '.join(str(f.get('message') or '').split())}"
                                       for f in (ctx.rehearsal or {}).get("findings") or [] if isinstance(f, dict) and f.get("id")))
            note += ("\n\n## Lines of the answer the driver could not read as a stand-gap answer (read each one "
                     "and record what the person means with the factory's own commands; the lines the driver "
                     "did read are already recorded"
                     + (f": {', '.join(out['recorded'])}" if out["recorded"] else "")
                     + " - do not record those again)\n"
                     + "\n".join(f"- {item['line']}  [{item['why']}]" for item in found["unread"])
                     + "\n\nTo record a stand gap run waiver.py --task <T> --stage <stage> --block "
                       "\"<block>\" --decision \"<option> - the person wrote: <their line>\": the decision's "
                       "FIRST word must be the option, or the reader reads it back as no answer and the gap is "
                       "asked again. Options and the words that mean them (a gap below that says it takes ONLY some "
                       "options takes only those: record nothing for another word, and tell the person the words "
                       "that apply to that card): " + options
                     + ". A lasting word (`accept always`) and `ask again` have their commands in "
                       "references/conductor-actions.json. The gaps of this gate:\n" + keys
                     + ("\n\nThe findings of this gate's rehearsal a person's word can pass (a line `<check id>: "
                        "accept` and their reason; a finding that is not listed has no door - say so, pass "
                        "nothing for it):\n" + door_keys if door_keys else "")
                     + changed)
            print(f"gate {ctx.gate}: " + str(len(out["unread"])) + " line(s) of the answer look like a stand-gap answer and "
                  "could not be read: " + "; ".join(out["unread"])[:300])
        return note

    def carry_environment_properties(self, gate: str, gaps=None, read=(), decided=None, failed_cases=()) -> None:
        """B-414 R8(c) (D-0029): what a person accepted ONCE for this environment reaches THIS story as if they had said it here.

        Reads what the packet the person saw kept (`shown_gaps`: its open gaps and the gaps the environment record covered) and
        runs no rehearsal. For each covered gap with no live record in this story: the gap's own override, `--by environment-
        record`, the record's words quoted (`stand_gaps.write_environment_overrides`; none when its id is shared with, or the start
        of, another gap's); then, over the open gaps AND the covered ones together, the cases whose EVERY stand gap is accepted -
        by the person's lines of this answer (`gaps`/`read`, given by the tail of `take_stand_gap_answers`) or by the record -
        become `stand_accept_cases` (merged into what is there) with each LEVEL gap's own remedy as `stand_accept_remedies`
        (F19), and get their carry (`stand_gaps.write_carries`). A case with another OPEN gap gets neither (E12), and one
        printed line names the gap. With no covered gap and no lines this changes nothing. Never raises (FR-3)."""
        import contract as C
        import stand_gaps
        shown = (self.state.get("shown_gaps") or {}).get(gate) or {}
        covered = [g for g in shown.get("covered") or [] if isinstance(g, dict) and isinstance(g.get("property"), dict)]
        reopened = [g for g in shown.get("reopened") or [] if isinstance(g, dict)]     # taken back by `ask again` in this answer
        if gaps is None and not covered:
            return
        open_gaps = [g for g in (shown.get("gaps") if gaps is None else gaps) or [] if isinstance(g, dict)] + reopened
        try:
            if decided is None:
                decided = C.stand_gap_decisions(json.loads((self.task_root / "pipeline.json").read_text(encoding="utf-8")))
            failed = set(failed_cases)
            for gid in stand_gaps.write_environment_overrides(self.task_root, self.task, covered,
                                                              [str(g.get("id")) for g in open_gaps + covered], self.py,
                                                              self.words_file, print):
                failed |= {c for g in covered if str(g.get("id")) == gid for c in stand_gaps.gap_cases(g)}
            everything, entries = open_gaps + covered, list(read) + stand_gaps.covered_entries(covered)
            cases = self.accepted_cases(everything, entries, decided)
            accepted_ids = {str(e["gap"].get("id")) for e in entries if e.get("option") == "accept"}
            for case in dict.fromkeys(c for g in covered for c in stand_gaps.gap_cases(g)):
                still = [str(g.get("id")) for g in open_gaps if case in stand_gaps.gap_cases(g)
                         and str(g.get("id")) not in accepted_ids and (decided.get(str(g.get("id"))) or {}).get("option") != "accept"]
                if case not in cases and still:
                    print(f"gate {gate}: {case}: not blocked and not carried - its stand gap {', '.join(still)} is still open")
            if cases:
                self.state["stand_accept_cases"] = list(dict.fromkeys(list(self.state.get("stand_accept_cases") or []) + cases))
                remedies = self._level_remedies(everything, cases)
                if remedies:
                    self.state["stand_accept_remedies"] = dict(self.state.get("stand_accept_remedies") or {}, **remedies)
            stand_gaps.write_carries(self.task_root, self.task, everything, entries, cases, decided, failed, self.py,
                                     self.words_file, print)
        except Exception as exc:
            print(f"gate {gate}: what the answer accepts could not all be carried ({type(exc).__name__}: "
                  f"{' '.join(str(exc).split())[:160]}); gate B will ask what is left")

    @staticmethod
    def _level_remedies(everything: list, cases: list) -> dict:
        """t-667 D16: the remedy each LEVEL gap carries, by case, for the cases that are accepted (F19): the first gap that names a
        case wins (`setdefault`); a gap that is not a level gap, or whose remedy is not valid, gives none. Pure - the caller keeps
        the `try` (FR-3: `carry_environment_properties` never raises) and the write to `stand_accept_remedies`."""
        import contract as C
        import stand_gaps
        remedies = {}
        for gap in everything:
            if not (gap.get("scope") == "level" and isinstance(gap.get("remedy"), dict) and not C.remedy_errors(gap["remedy"])):
                continue
            for case in stand_gaps.gap_cases(gap):
                if case in cases:
                    remedies.setdefault(case, dict(gap["remedy"]))
        return remedies

    def revoke_environment_properties(self, gate: str, revokes: list) -> list:
        """B-414 R8(d) (E8, FR-48, FR-57): `<name>: ask again` for a gap the environment record covers. The driver takes the row
        back (`environment_record.py revoke`), then this story's own records that rest on it (`stand_gaps.revoke_environment_
        overrides`), and drops the gap's cases from the cases about to be blocked. Returns the `unread` lines for the conductor
        ("show them its card"): the gate decision is not recorded by code over them, so the card is asked again through the
        channel that already exists. A failed revoke is printed and changes nothing."""
        import stand_gaps
        out, gone_ids = [], set()
        for entry in revokes:
            gap = entry["gap"]
            row = gap.get("property") if isinstance(gap.get("property"), dict) else {}
            name = stand_gaps._label(gap)
            registry = bool(stand_gaps.pk_property_of(gap))      # PK0-9: a row of the project-knowledge registry, taken back by its own tool
            code, text = self.py("project_knowledge.py" if registry else "environment_record.py", "revoke", "--id", str(row.get("id")),
                                 *stand_gaps.words_args(self.words_file, entry["line"], "ask-again"))
            if code:
                why = " ".join(text.split())[-160:]
                held = "its entry in the record of earlier answers" if registry else "its record for the environment"
                print(f"gate {gate}: {name}: " + ("the entry in the record of earlier answers" if registry
                                                  else "the record for this environment") + f" could not be taken back ({why})")
                out.append({"line": entry["line"], "why": f"the person asked for this again, and {held} "
                                                          f"could not be taken back ({why}): nothing was changed"})
                continue
            stand_gaps.revoke_environment_overrides(self.task_root, self.task, gap, self.py, self.words_file, print)
            cases = set(stand_gaps.gap_cases(gap))
            if self.state.get("stand_accept_cases"):
                self.state["stand_accept_cases"] = [c for c in self.state["stand_accept_cases"] if c not in cases]
            if isinstance(self.state.get("stand_accept_remedies"), dict):
                self.state["stand_accept_remedies"] = {c: r for c, r in self.state["stand_accept_remedies"].items() if c not in cases}
            gone_ids.add(str(gap.get("id")))
            print(f"gate {gate}: {name}: taken back from the {'record of earlier answers' if registry else 'environment record'} "
                  f"({row.get('id')}); it is asked again")
            out.append({"line": entry["line"], "why": "the person asked for this again; its " + (
                "entry in the record of earlier answers" if registry else "record for the environment") + " is taken back: show them its card"})
        shown = (self.state.get("shown_gaps") or {}).get(gate)
        if gone_ids and isinstance(shown, dict):
            # a gap taken back is an OPEN gap of this story again (no word, so none of its cases is blocked or carried)
            shown["reopened"] = list(shown.get("reopened") or []) + [g for g in shown.get("covered") or [] if str(g.get("id")) in gone_ids]
            shown["covered"] = [g for g in shown.get("covered") or [] if str(g.get("id")) not in gone_ids]
        return out

    # t-364 -- the readers `take_stand_gap_answers` leans on. A rehearsal finding's id is `<check>-<n>` or `<check>-<subject>` (`case_environment-TS-23`), starting lower case; membership decides.
    from gate_preflight import FINDING_ID_PATTERN as _FINDING_ID_PATTERN  # the id form the rehearsal WRITES (`_id_token`) is the one read here (AR-18, F5)
    _FINDING_LINE_RE = re.compile(r"^\s*(?:[-*•]\s+)?`?(?P<id>" + _FINDING_ID_PATTERN + r")`?\s*:\s*(?P<rest>\S.*?)\s*$")

    def read_finding_doors(self, words: str, findings: list, shown: str = "", shown_doors: dict | None = None) -> dict:
        """The line `<check id>: accept <the person's reason>` for a finding of the gate's rehearsal: {"read", "unread", "probes"}.

        `probes`: a line `<check id>: <container name>` that names exactly one container of a which-container card (the finding's
        `container_answers`) - it passes the same packet, door and `?` checks as a door line, and is NEVER in `read` (it records no
        waiver); `take_stand_gap_answers` runs its write command once.

        The door a finding names in words (`gate_preflight.Rehearsal.waiver_command`) is READ here, by form: the id of a
        finding of THIS rehearsal AS THE PERSON SAW IT (`shown`: the packet carries `[<id>] <the current message>`, else
        the line is unread - ids are ordinal per check and renumber when the rehearsal changes), then either the WHOLE text
        after the colon is a word or synonym of the closed list (the t-342 rule), or its FIRST word is the canonical `word`
        of an option and the rest is the person's reason, kept whole inside the decision (P13). A synonym as a first word
        is never read (`blocked, why? what does this mean` is a question, not consent). The finding's own `waives`
        ([{block, stage, option}]) says what the word passes: `accept` (or `any`, the card pointers) takes `accept`;
        `handed` takes `run`. A door that asks for a reason (`accept` on a check) is unread without one.
        Never read: a finding with NO `waives` (a gap of the factory's own), a word the door does not take, an unknown
        word. Unread lines are named, never dropped. The person's LAST line for an id decides it: a readable line
        followed by an unreadable one is set aside with it. An id that is no finding of this rehearsal is not this
        reader's line at all (a case, a question, a bug number).

        t-369 N-1: a `?` ANYWHERE in the line sends it to the conductor whole - a question is never consent.
        N-2: `shown_doors` is {id: waives} as the packet SHOWED them (`gate()` stores it when the gate is asked); a line is
        read only when the current rehearsal's `waives` for that id EQUAL the stored ones - the message alone does not bind
        the block (same id, same words, another block is another door); no stored entry reads as changed."""
        import gate_brief

        def container_choice(finding: dict, text: str):
            """The closed answer of a which-container card (`gate_preflight._probe_which_container`): the WHOLE text after the colon,
            trimmed, is exactly one of the finding's own `container_answers` (case-sensitive) and that name has a write command in
            `answer_probes` (the read-only check) and `answer_argvs` (the write): {"profile", "name", "probe", "argv"}, else None.
            Nothing is run here and no pass is recorded by it."""
            names = finding.get("container_answers")
            name = str(text or "").strip()
            pair = []
            for key in ("answer_probes", "answer_argvs"):
                argvs = finding.get(key)
                argv = argvs.get(name) if isinstance(argvs, dict) else None
                if not (isinstance(argv, list) and argv and all(isinstance(a, str) and a for a in argv)):
                    return None
                pair.append(list(argv))
            if not (isinstance(names, list) and name in names):
                return None
            return {"profile": str(finding.get("profile") or ""), "name": name, "probe": pair[0], "argv": pair[1]}

        index = gate_brief.stand_gap_word_index()
        stored_doors = shown_doors if isinstance(shown_doors, dict) else {}
        canonical = {gate_brief._word_key(row["word"]): row["option"] for row in gate_brief.stand_gap_words()}
        door_words = gate_brief.finding_door_words()
        # the packet's lines, whitespace-normalised: a finding is SHOWN when a line ENDS with `[<id>] <the message>` (a message
        # that only starts like the one shown is another message)
        packet = [" ".join(row.split()) for row in str(shown or "").splitlines()]
        by_id = {str(f.get("id")): f for f in findings if isinstance(f, dict) and f.get("id")}
        seen: dict = {}
        for raw in str(words or "").splitlines():
            hit = self._FINDING_LINE_RE.match(raw)
            if not hit or hit.group("id") not in by_id:
                continue
            fid, rest, line = hit.group("id"), hit.group("rest"), " ".join(raw.split())
            option, reason = index.get(gate_brief._word_key(rest), ""), ""
            first = re.match(r"([^\s,;:.\-—–]+)[\s,;:.\-—–]*(.*)", rest, re.DOTALL)
            if not option and first:
                option, reason = canonical.get(gate_brief._word_key(first.group(1)), ""), first.group(2).strip()
            if not option:
                # D1-C2 (Q1-b): the words a finding's OWN door takes (`finding_door_words`), tried only AFTER the stand-gap words, so no
                # existing word changes meaning. The word alone (or a synonym alone) is read; the word followed by a separator and the
                # person's reason is read with the reason kept; the word followed by a letter (`product gaps`) is not the word
                option, reason = gate_brief.finding_door_option(rest, door_words)
            doors = [d for d in by_id[fid].get("waives") or [] if isinstance(d, dict) and d.get("block")]
            message = " ".join(str(by_id[fid].get("message") or "").split())
            if not any(row == f"[{fid}] {message}" or row.endswith(f" [{fid}] {message}") for row in packet):
                status = ("unread", "the checks changed since the person read them: this id does not name that message in the "
                                    "packet they were shown")
            elif fid not in stored_doors or json.dumps(stored_doors[fid], sort_keys=True) != json.dumps(
                    [d for d in by_id[fid].get("waives") or [] if isinstance(d, dict)], sort_keys=True):
                status = ("unread", "the checks changed since the person read them: the door this id showed is not the one "
                                    "it has now")
            elif "?" in line:
                status = ("unread", "the line asks a question, and a question is never consent")
            elif (choice := container_choice(by_id[fid], rest)):
                status = ("probe", choice)
            elif not option:
                status = ("unread", "the word is not one of the answers a finding's door takes")
            elif not doors:
                status = ("unread", "this finding records no door (a gap of the factory's own): nothing is passed for it")
            else:
                fit = [d for d in doors if d.get("option") == option or (d.get("option") == "any" and option == "accept")]
                if len(fit) != 1:
                    status = ("unread", "the door of this finding does not take that word" if not fit
                              else "this finding has more than one door for that word")
                elif option == "accept" and fit[0].get("option") == "accept" and not reason:
                    status = ("unread", "the door of this check asks for the person's reason with `accept`, and there is none")
                else:
                    status = ("read", {"door": fit[0], "option": option, "reason": reason})
            seen.setdefault(fid, []).append((line, status))
        out: dict = {"read": [], "unread": [], "probes": []}
        for fid, lines in seen.items():
            line, (state, payload) = lines[-1]
            earlier = [l for l, _s in lines[:-1]]
            if state == "probe":
                out["probes"].append(dict(payload, id=fid, line=line, replaced=earlier))
            elif state == "read":
                out["read"].append({"id": fid, "line": line, "word": payload["option"], "door": payload["door"],
                                    "reason": payload["reason"], "replaced": earlier})
            else:
                out["unread"].append({"line": line, "why": payload})
                out["unread"].extend({"line": l, "why": "an earlier line for this finding, set aside: its last line could "
                                                        "not be read, so the person's last word is unread"} for l in earlier)
        return out

    @staticmethod
    def accepted_cases(gaps: list, read: list, decided: dict) -> list:
        """The cases whose EVERY gap at this gate is accepted - by this answer (at least one of them) or an earlier one.

        `accept` on a card says "it stays blocked and is reported as not run": the waiver is the person's decision, and
        the `blocked_by_env` row that makes S5 report it is `planning_contract.apply_gate_answers`'s effect of it. Both
        come from the ONE line read here (`record_by_code` hands that line to the executor in its own token), so the
        two records cannot disagree. A case with a gap that is NOT accepted is never blocked as a whole (the error
        direction of the executor: toward not applying).

        B-414 (R8(a), R16): a gap's cases are `stand_gaps.gap_cases` (a LEVEL gap names several, and each of them is counted),
        and a case that got a word OTHER than `accept` for any of its gaps in THIS answer is never returned, whatever an older
        `decided` says (rev1 guard iii: the stale-`decided` fallback no longer lets a changed word through). `read` may hold the
        entries of covered gaps (`stand_gaps.covered_entries`): an `accept` that the environment record gave."""
        import stand_gaps
        now = {str(e["gap"].get("id")) for e in read if e.get("option") == "accept"}
        reworded = {c for e in read if e.get("option") != "accept" for c in stand_gaps.gap_cases(e["gap"])}
        by_case: dict = {}
        for gap in gaps:
            for case in stand_gaps.gap_cases(gap):
                by_case.setdefault(case, []).append(str(gap.get("id")))
        return [case for case, ids in by_case.items()
                if case not in reworded and any(i in now for i in ids)
                and all(i in now or (decided.get(i) or {}).get("option") == "accept" for i in ids)]

    def take_package_answer(self, words: str, qtext: str, stage: str, dispatch: str) -> None:
        """The answer to a `package` question (B-014 / FR-4 / FR-9: a check stops a silent pass, never an informed one, and what a
        person decides has an executor). The answer is one of a CLOSED set of tokens (the S0 stop's pattern; the code reads a token,
        never a meaning - FR-12): `go on` passes the ONE thing asked about (the root pair, or the mode switch at that stage) and is
        recorded; `retry` (hooks) or `desktop` (mode) and `stop` are recorded and END the run without running or spending anything
        - the question stays open, the same door. Anything else is NEW words the code cannot read: the seam (D-0041), with the
        question's own words as its doors; a conductor `continue` / `retry` RETURNS from here - nothing is recorded or passed,
        `package_question` is kept and the check runs again (G1). `package_question` is popped only by an answer that lets the run
        go on."""
        pending = self.state.get("package_question") or {}
        is_mode = pending.get("what") == "mode"
        token = self.s0_normalize(words)
        said = "run mode switch" if is_mode else "package copies differ between the driver and the hooks"
        own = "desktop" if is_mode else "retry"
        base = str(pending.get("text") or QUESTION_HEAD_RE.sub("", ANSWER_BLOCK_RE.sub("", qtext), count=1)).strip()
        details = str(pending.get("details") or "")
        if token not in ("go on", "stop", own):
            self.answer_row(f"package ({said}): not one of the answers, asked again: ", words.strip(), what="your answer about the package copies")
            lead = self.unread_lead(words)
            self.unread("package", stage, dispatch, base + "\n\n" + details, words=words, doors=(own, "go on"), lead=lead,
                        again=lambda said_lead: Person("package", f"{said_lead}\n\n{base}", stage, dispatch, details=details))
            return
        if token in ("stop", "desktop"):
            self.answer_row(f"package ({said}): ", words.strip(), what="your answer about the package copies")
            held = (self.stop_held() if token == "stop" else
                    "You said you will finish this story in the desktop app. The story waits for it; "
                    "nothing runs here meanwhile.")
            raise Person("package", f"{held} If you want the driver to go on after all, answer `go on`.\n\n{base}",
                         stage, dispatch, details=details)
        self.state.pop("package_question", None)
        ref = dispatch or str(pending.get("session") or "") or self.task
        self.answer_row(f"package ({said}): ", words.strip(), what="your answer about the package copies")
        if token == "retry":
            print(f"{stage}: nothing is passed; the step runs again and the copies are compared again")
        elif is_mode:
            # Q3 (C1-7a): a switch that was not recorded is the person's own question back, not a print (B-3). POSITION INVARIANT: the
            # `package_question` is popped above, so a held question raised from here would make the NEXT `go on` read as the
            # package-copies pass (`pending` empty, FR-9): the question is put back before it is raised, and only a recorded switch
            # leaves it popped.
            try:
                self.pass_block(str(pending.get("stage") or stage), waiver.MODE_SWITCH_BLOCK, self.answer_file(),
                                "Your word could not be recorded as the mode switch, so nothing was switched.")
            except Person:
                self.state["package_question"] = pending
                raise
            print(f"{stage}: the mode switch is recorded on the person's word")
        else:
            self.state["package_pass"] = {"driver_root": pending.get("driver_root") or "",
                                          "hook_roots": list(pending.get("hook_roots") or []),
                                          "words": words, "ts": _now()}
            print(f"{stage}: the person's word passes this pair of package copies; the step runs again")
        if token == "go on" and not is_mode:
            # A mismatch of the factory's own copies is a defect of ours, filed in the person's
            # words. A run-mode switch is the person's choice, not a defect: waiver + human_answer only.
            self.py_trace("log_append.py", "--event", "defect_found", "--task", self.task, "--ref", ref,
                          "--by", "driver", "--notes", _answer_note(
                              f"owner: factory — {said}; passed on the person's words: ", words.strip()),
                          why="the pass itself is on the record (package_pass and the human_answer row above); this defect line is the "
                              "finding about it, and a defect filer cannot file its own failure")

    def take_answer(self, path: Path) -> None:
        raw = path.read_bytes().decode("utf-8", "replace")      # the bytes as given (CRLF kept): the words file is written from them
        words = raw.replace("\r\n", "\n").replace("\r", "\n").strip()
        question = self.state_dir / "driver-question.md"
        asked = self.state.get("asked") or {}
        if not words:
            raise Stop(EXIT_ERROR, f"{path} is empty")
        if not asked.get("kind"):
            raise Stop(EXIT_ERROR, "no question is open (state/driver-state.json has none asked)")
        self._answer = {"text": raw, "rel": None}               # ONE words file per answer, written on first use (`answer_file`)
        seam_token = False                                      # the answer was a token of a question the seam raised
        kind, stage, dispatch = asked.get("kind", ""), asked.get("stage", ""), asked.get("dispatch", "")
        self.boundary = f"{stage}:{dispatch or kind}:answer"
        self.answer_kind = kind
        print(f"answer for {kind} ({stage}{' ' + dispatch if dispatch else ''}): {words[:200]}")
        qtext = question.read_text(encoding="utf-8", errors="replace") if question.is_file() else ""
        self._answer.update(kind=kind, stage=stage, dispatch=dispatch, question_sha=question_body_sha(qtext), words=words)
        # t-342 (B-272): a gate B answer's stand-gap lines are recorded here, BEFORE the branches below; {} for any
        # other question. `stand["unread"]` (a line that looks like the form and cannot be read) keeps the gate
        # decision from being recorded by code: those lines go to the conductor, with the lines named (FR-8).
        # C1-4b (H3, FR-9): NOT for an answer to a question the seam raised (`offered`): that answer is a token of an option (`approve`),
        # and the stand-gap keys of the ORIGINAL answer (`stand_accept_cases`, `stand_accept_remedies`) must survive to `record_by_code`.
        # C2-7 (F-7c, K6): a word that is NOT a token of the options of a question the seam raised AT A GATE is a new answer of the gate
        # (cmp3 17:17: `approve` to a `retry` / `stop` question went round the seam). POSITION INVARIANT: the whole answer is compared
        # (a card line beside `approve` is no token); a token reads as before (`take_seam_answer`, the stand keys of the original
        # answer live on to `record_by_code`); every non-gate kind is untouched. Such an answer reads its card lines like a first answer
        # (`keep_earlier`: the keys of the earlier one are kept), is an approval only as `gate_approval` reads it, and is never
        # silent: what is neither goes whole to the conductor (`_unread_kept_gate`). The decision keeps everything said at the gate.
        seam_gate_words = (kind in GATE_KINDS and bool(asked.get("offered"))
                           and self.s0_normalize(words) not in self.seam_tokens(asked))
        gate_words, apply = words, {}
        if seam_gate_words:
            gate_words = self.combine_gate_words(asked, raw, words)
            if gate_words != words:
                apply = {"apply_words": words}          # the cards are read from this answer alone, never from the tail (t-891 F-2)
        asked_unread: list = []
        stand = ({} if asked.get("offered") and not seam_gate_words
                 else self.take_stand_gap_answers(kind, words, qtext, stage, dispatch, keep_earlier=seam_gate_words))
        if not (asked.get("offered") and not seam_gate_words):
            # P2 fix round (M1) POSITION INVARIANT: right AFTER the stand-gap reader, BEFORE every kind branch below. Its unread lines
            # join `stand["unread"]`, so no branch records gate B by code over a line nobody could read; the note names them.
            asked_lines = self.take_exploratory_answers(kind, words, qtext)
            if asked_lines:
                # GW1-33: the exploratory reader's unread lines are kept apart BEFORE the merge: they stay the conductor's
                # (`bug` beside `approve` is a contradiction), while the stand-gap reader's unread lines may ride an approval
                asked_unread = list(asked_lines["unread"])
                stand = {"recorded": stand.get("recorded", []) + asked_lines["recorded"],
                         "unread": stand.get("unread", []) + asked_lines["unread"],
                         "note": stand.get("note", "") + asked_lines["note"],
                         "hold": stand.get("hold", [])}
        # Set by `delivery()` alone, when it raises one of its three questions; consumed by whatever
        # answer comes next, so it cannot outlive its question (t-037's lesson about `stand_question`).
        # (a question the seam raised at S8 carries `offered`: the flag of an earlier delivery question cannot capture its answer)
        delivery_asked = bool(self.state.pop("delivery_question", None)) and kind == "conductor" and stage == "S8" \
            and not asked.get("offered")
        if delivery_asked and self.s0_normalize(words) == "no delivery":
            # The one answer to a delivery question that code reads (Lead's decision Q1, FR-9: a
            # person's "no delivery" has an executor): the delivery is closed as declined - a mark like
            # the one `continue` writes, so the story goes on to the retro - with no conductor call.
            # Every other word re-enters the delivery through the "S8 is done" branch below.
            self._decline_delivery(words)
        elif kind == "retro":
            self.state["retro_asked"] = True
            self.state["retro_feedback"] = "declined" if words.lower() in ("skip", "-", "no") else words
            self.owe_row("log_append.py", "--event", "escalated", "--agent", "qa-story", "--task", self.task,
                         "--reason", f"retro feedback: {self.state['retro_feedback']}", what="your feedback on the retro")
        elif kind == "package":
            self.take_package_answer(words, qtext, stage, dispatch)
        elif kind == "repair_limit":
            # t-698 (C1-5b1): the site's own question at an S5 repair limit - its tokens have executors (`_answer_repair_limit`), any
            # other word goes to the seam once. Raised by the gate in front of a critic's finish, so it carries no `offered`.
            self._answer_repair_limit(words, qtext, stage, dispatch)
        elif kind == "walk_supply":
            # TR3-10 D (item 14): the way question - its three tokens have executors (`_answer_walk_supply`), any other word goes to the
            # conductor once. POSITION INVARIANT: before the generic `offered` branch below (these questions carry no `offered`: L5);
            # the site's executors run, never the generic offered road.
            self._answer_walk_supply(words, qtext, stage, dispatch)
        elif kind == "data_change":
            # TR3-10 D (item 14): the data-change question - same position and invariant as `walk_supply` above (no `offered`: L5).
            self._answer_data_change(words, qtext, stage, dispatch)
        elif kind == "walk_account":
            # TR3-10 D (item 14): the account question - `by hand` / `go on` have executors (`_answer_walk_account`), `added` and any other
            # word go to the conductor once. POSITION INVARIANT: right after `walk_supply`, before the generic `offered` branch below
            # (this question carries no `offered`: L5); the site's executors run, never the generic offered road.
            self._answer_walk_account(words, qtext, stage, dispatch)
        elif kind == "open_work":
            # t-698 §22 FX-2 (C1-5b2): the site's own question at the end of an S7 `open_work` life - `close` / `stop` have executors
            # (`_answer_open_work`), any other word goes to the seam once (the `repair_limit` shape: this kind carries no `offered`).
            self._answer_open_work(words, qtext, stage, dispatch)
        elif kind == "exit_limit" and not asked.get("offered"):
            # t-764 (C1-5d2): the site's own question over an exit-gate refusal that survived the resume limit - its tokens have
            # executors (`_answer_exit_limit`), any other word goes to the conductor once. POSITION INVARIANT: after the closed
            # questions with their own executors, BEFORE the `offered` branch below (an exit-limit question carries no `offered`;
            # the conductor's options of this kind are read by `take_seam_answer`, which hands every token to the same executor).
            # A token sets `seam_token`: it is not words for a role (`_file_words`).
            seam_token = self._answer_exit_limit(words, qtext, stage, dispatch)
        elif kind == "code_close" and not asked.get("offered"):
            # C2-8 (t-745): the site's own question when the CODE closes a stage with no role and its record was refused - the tokens have
            # ONE executor (`_answer_code_close`); the conductor's options of this kind reach the same executor by `take_seam_answer`.
            # POSITION INVARIANT: after the closed questions with their own executors, before the `offered` branch (this question
            # carries no `offered`). A token sets `seam_token`: it is not words for a role (`_file_words`).
            seam_token = self._answer_code_close(words, qtext, stage, dispatch)
        elif kind == "ticket_changed":
            # B-364 R3 / FR-9: the changed-ticket question has three tokens, each with an executor (the S0 stop's
            # and the `package` question's pattern): code reads a token, never a meaning (FR-12) and calls no conductor.
            self.take_ticket_answer(words, qtext, stage, dispatch)
        elif kind == "ticket_auth":
            # The freshness check lost the tracker login (G3): `retry` / `go on` / `stop` have their executors in this method and
            # the rest goes to the seam. POSITION INVARIANT: only kind `ticket_auth` (raised by `ticket_look_failed` alone), before
            # the generic seam branch below, so an answer to it is never recorded as another question's token.
            self.take_ticket_auth_answer(words, qtext, stage, dispatch)
        elif kind == "arrival_not_waiting":
            # t-2181 PC-7 B2 (FR-9, FR-7, AR-22): the code was named for a story that was not waiting for it - `re-ground` / `ignore` /
            # `stop` have ONE executor (`_answer_arrival_not_waiting`: the token goes to `launch.arrival.answer`, read by `arrival_record`
            # in this same process), any other word goes to the conductor once. POSITION INVARIANT: only kind `arrival_not_waiting`
            # (raised by `arrival_record` alone, no `offered`), before the generic `offered` branch. A token sets `seam_token`.
            seam_token = self._answer_arrival_not_waiting(words, qtext, stage)
        elif kind == "first_look_dead":
            # t-2277 FL-5 (FR-9, FR-12, AR-24): the first look's `continue` / `stop` have ONE executor (`_first_look_answer`: the keys of now to
            # `first_look_continue`, the controller `await` for `stop`), any other word goes to the conductor once. POSITION INVARIANT: only kind
            # `first_look_dead` (raised by `first_look_step` alone, no `offered`), before the generic `offered` branch, so its tokens are never
            # read as another question's. A token sets `seam_token`.
            seam_token = self._first_look_answer(words, qtext, stage)
        elif kind == "first_look_same_code":
            # t-2277 FL-6 (FR-9, FR-12, AR-24): `wait` / `source` / `continue` have ONE executor (`_same_code_answer`; `continue` is the
            # operation of `first_look.dead`), any other word goes to the conductor once. POSITION INVARIANT: only kind
            # `first_look_same_code` (raised by `first_look_code_look` alone, no `offered`), before the generic `offered` branch. A token
            # sets `seam_token`: the answers row keeps it, and the code look of this process reads it (`wait` / `source`).
            seam_token = self._same_code_answer(words, qtext, stage)
        elif kind == "absent_side":
            # t-2559 (W2 B3, FR-9, FR-12, AR-24, AR-25): `not ours` / `relaunch` have ONE executor (`_answer_absent_side`), any other word goes
            # to the conductor once. POSITION INVARIANT: only kind `absent_side` (raised by `_act_await_implementation` alone, no `offered`),
            # before the generic `offered` branch, so its tokens are never read as another question's. A token sets `seam_token`.
            seam_token = self._answer_absent_side(words, qtext, stage)
        elif kind == "closed_held":
            # B-331 (C1-6a): the closed story's never-started work - `run again` / `leave` / `stop` have executors
            # (`_take_closed_held_answer`), any other word goes to the seam once. POSITION INVARIANT: only kind `closed_held`
            # (raised by `closed_held_person` alone), before the generic `offered` branch: the seam's own Person of this kind
            # carries `offered`, and its answers must reach the same executor. A token sets `seam_token`: it is not words
            # for a role (`_file_words`).
            seam_token = self._take_closed_held_answer(words, qtext, stage)
        elif kind == "environment" and stage in self.STAND_STAGES and self.state.get("stand_question") == stage:
            # The answer to `stand_check`'s question - and only to it: `stand_question` is set by `stand_check` alone, so the
            # questions of `environment_job` (kind `environment` too) never carry it and go on to the final `else` as before.
            # C1-6b (A7): the question is a seam question (it carries `offered`), so this branch stands BEFORE the generic `offered`
            # branch: the stand's NAME is the site's own door, `retry` / `go on` are carried out by `take_seam_answer`
            # (`_take_stand_answer`). A token sets `seam_token`: it is not words for a role (`_file_words`).
            seam_token = self._take_stand_answer(kind, stage, dispatch, qtext, words)
        elif kind == "stand_login" and self.state.get("login_question"):
            # The answer to `stand_login_gate`'s question - and only to it: `login_question` is set by `ask()` alone, from that
            # Person (t-037's lesson, as for the branch above). POSITION INVARIANT (as above): before the generic `offered` branch,
            # because the question carries `offered`; the typed record of `by hand` is written here, the pass by the seam's executor.
            seam_token = self._take_stand_login_answer(kind, stage, dispatch, qtext, words)
        elif kind == "gate_a_dry":
            # The answer to the `s6.gate_a_dry` question (`manual_gate_note`, raised by that site alone): `reapprove` has the site's
            # executor (`semantic_reopen`), `go on` / `stop` the seam's. POSITION INVARIANT: before the generic `offered` branch (the
            # question carries `offered`: `reapprove` is a word only this branch reads). A token sets `seam_token`.
            seam_token = self._take_gate_a_dry_answer(kind, stage, dispatch, qtext, words)
        elif kind in ("report_match", "delivery_check", "delivery"):
            # C1-6c (S8-S13 of the census): the delivery's own closed questions - tokens have executors, any other word goes to the
            # seam once. POSITION INVARIANT: only these kinds (each raised by its own builder alone), before the generic `offered` branch
            # and after the old `delivery_asked` branch above, which keys on kind `conductor` (a state an older driver wrote).
            seam_token = {"report_match": self._take_report_match_answer, "delivery_check": self._take_delivery_check_answer,
                          "delivery": self._take_delivery_answer}[kind](words, qtext, stage)
        elif kind == "s1_review" and self.record_review(words):
            self.state["pending_words"][dispatch] = words
        elif kind == "s1_gap" and self._answer_s1_gap(words, asked, qtext, stage, dispatch):
            self.state["pending_words"][dispatch] = words      # C2-9: the tokens and the fence have their executor; free words fall through
        elif (stage == "S0" and kind in ("halt", "refusal") and self.state.get("s0_block")
              and (not (self.task_root / "pipeline.json").is_file()
                   or self.state.get("s0_block") == "source_list")):
            # A stop of S0's own, answered before the story has a pipeline.json (`_keep_s0_words`: the words wait for the
            # next S0 step, no conductor and no judge). INVARIANT: this position keeps every
            # answer on today's paths the moment pipeline.json exists, and gate, retro and s1
            # kinds never reach it - it is `halt`/`refusal` at S0 with an open S0 block, only.
            # The ONE exception after pipeline.json exists is the `source_list` block: the person's list
            # of sources not to read, given on a command line of a story whose sources were already
            # collected (t-172 C1), is asked at S0 and read by `skip_sources_late`, not by a conductor.
            self._keep_s0_words(words)
        elif asked.get("offered") and not seam_gate_words:
            # A question the seam (`no_move`) raised, and only such a question: `ask()` writes `offered` from its Person alone, so
            # no other question's answer is captured here (`s1_review` never carries it). POSITION INVARIANT:
            # after the branches of the closed questions with their own executors above, before the plain "stage is done" branch.
            # At a gate only a TOKEN of the options comes here; any other word falls to the gate branches below (C2-7, `seam_gate_words`).
            seam_token = self.take_seam_answer(words, asked, qtext, stage, dispatch)
        elif kind in ("conductor", "refusal") and stage and \
                (self.pipeline().get("stages") or {}).get(stage, {}).get("status") == "done":
            # The stop was passed before the person answered (the conductor closed the stage
            # itself and still asked): the words go on the record, the loop goes on.
            self.after_close(stage, words)
        elif kind in ("conductor", "refusal") and self.s1_exit_gate(qtext) and self.record_s1(qtext, words):
            dispatch = self.s1_exit_gate(qtext)
            self.state["pending_words"][dispatch] = words
        elif kind == "questions":
            # A threshold stop (t-113 B2, R17): tokens are recorded by code and the words go to the
            # role's own session - no conductor, no judge. Only this kind reaches it.
            self.take_question_answer(stage, dispatch, words)
        elif kind == "halt" and stage == "S1" and self.s0_normalize(words) == "not built yet" and self.s1_has_no_diff():
            # t-2181 PC-7 B3 (FR-9, AR-19): the `not built yet` answer of `s1.no_diff` - the twin of the `s0.no_change` answer - records the
            # side before the words go to the scout. POSITION INVARIANT: only kind `halt` at S1 with the manifest's `none` source, the WHOLE
            # answer (`not built yet please` is other words and takes the unread road below); before `judged_reply` / `unread`, so the
            # story parks after S5 instead of reading the default `product: real`.
            self._answer_s1_not_built(words, dispatch)
        elif kind == "halt" and self.s0_normalize(words) == "stop":
            # The halt question's one token (`halt` / `s1.no_diff` of question-prices.json). POSITION INVARIANT: only kind `halt`,
            # the WHOLE answer, and BEFORE `judged_reply` / `unread` - the conductor is not called and the words are not filed
            # for the role (no `pending_words`): `stop please` is other words and takes the unread road below, as today.
            self.answer_row(f"{stage} halt (stop): ", words.strip(), what="your answer at the halt")
            raise self.held_question(self.stop_held("If you want the role to go on after all, answer in your own words."))
        elif kind in ("halt", "s1_review"):
            self._unread_halt_or_review(kind, stage, dispatch, qtext, words)
        elif (kind in ("gate_A", "gate_B")
              and (not stand.get("unread") or self.gate_lines_over_approval(kind, gate_words, stand, asked_unread))
              and self.record_by_code(kind, stage, gate_words, **apply)):
            # A gate decision is one command with the person's words in it — not a problem, so not
            # a conductor session. What the gate packet's items still need is decided by the loop:
            # a block that outlives the decision comes back as its own refusal, with its own owner.
            # GW1-33 POSITION INVARIANT: lines nobody could read ride an APPROVAL only through `gate_lines_over_approval` (gate A
            # only), and the gate A controller still refuses an approval over an open item (then this branch is not taken: the old
            # road, the whole answer kept for the conductor). Gate B and held lines never ride. The unread lines are told as "not understood", whole in the answer's row, never as accepted.
            self.state["pending_words"].pop(dispatch, None)
            if stand.get("unread"):
                lines = [str(line) for line in stand["unread"]]
                print(f"gate {kind[-1]}: recorded by code; {len(lines)} line(s) of the answer were not understood and are not applied:")
                print("\n".join(f"  - {line}" for line in lines[:20]) + (f"\n  ... and {len(lines) - 20} more" if len(lines) > 20 else ""))
                self.answer_row(f"{stage} {kind} lines not understood: ", "\n".join(lines), what="the lines of your answer that were not understood")
        elif kind == "stand_identity" and self.state.get("build_question"):
            # The answer to `build_check`'s question - and only to it (t-300 N1b): `build_question` is set by `ask()` alone,
            # from that Person, so no other question's answer comes here (t-037's lesson, as for the two branches above).
            # The closed forms are read and executed by code, the rest goes to the conductor: `take_build_answer`.
            self.take_build_answer(words, qtext, stage, dispatch)
        else:  # gate_A, gate_B, conductor, refusal — a block that outlived the recording
            self._unread_kept_gate(kind, stage, dispatch, qtext, gate_words, stand.get("note", ""), **apply)
        # POSITION INVARIANT (t-217 / F-cmp2-22, FR-16, FR-7, FR-8): after every branch above. A person's words are resumed (the
        # `pending_words` consumers) only into the dispatch the question was about - the FIELD `asked.dispatch`, never an id read
        # out of the question's text - and when unsure they are filed to NO dispatch: the boundary then asks again, with ask()'s
        # FR-7 block, never to a wrong one. `dispatch` is the one the s1_exit_gate branch may have reassigned (E4); the seam token
        # reaches `_file_words` (a token of a seam question is not words for a role).
        self._file_words(kind, dispatch, asked, words, qtext, seam_token)
        self.record_answer_row(self.s0_normalize(words) if seam_token else "", dispatch)
        if asked.get("deferred_n") is not None:
            # RN1-24 (E10, E12): the answer to a DEFERRED question was read above by the original question's own executors. Its stage (S6)
            # is closed already, so a `retry` (the move `person_does`, read from `asked.options`, never from the word) found no step to
            # run again there: it is carried out here as the seam's rework of exactly the held cases (`record_seam_rework`; S7 and
            # gate B follow it again). POSITION INVARIANT: after every branch and the filing of the words, BEFORE `asked` is cleared, so
            # a rework that cannot be recorded brings the question back (`held_question`) with the item still owed, never a lost answer.
            item = next((i for i in self.deferred_items() if i["n"] == asked["deferred_n"]), None)
            closed = (self.pipeline().get("stages") or {}).get(stage, {}).get("status") == "done"
            move, token = self.seam_tokens(asked).get(self.s0_normalize(words)), self.s0_normalize(words)
            if item and closed and move == "go_on_as_is":
                # `go on` / `by hand` after the stage is closed: `after_close` only recorded the words; the decision is carried out here
                # (the held cases' request.json, the pass). A `retry` whose cause is not fixed is the branch below, unchanged.
                self.deferred_decision(item, token, words, asked, stage, self.answer_file())
            if item and closed and move == "person_does":
                clean, rule = NM.check_args({"stage": "S6", "role": "qa-runner", "cases": list(item.get("holds") or []),
                                             "cause": "question_answer"}, self.no_move_facts({"kind": kind}))
                if clean is None:
                    # remains: the person's own question comes back with the reason and the item stays owed (the `record_seam_rework` pattern)
                    raise self.held_question("Your choice to check these again could not be carried out, so nothing was sent back.", rule)
                self.record_seam_rework(clean, self.answer_file())
            self.state["deferred"] = [i for i in self.deferred_items() if i["n"] != asked["deferred_n"]]
            if not self.state["deferred"]:
                self.state.pop("deferred_round", None)
        # Cleared the way it was opened: the flag, then the file. Between the two the question
        # reads as answered-but-not-filed, which is the half `reconcile_question` files; the
        # other order would re-ask a question already recorded.
        # B-20 N5 (AR-22): the producer of `stuck_asked`; its reader is the stuck seam of the loop. Only the answer to the stuck question itself
        # (same stage, same kind) is recorded under its step's signature; any other answer drops a stale pending mark.
        pending = self.state.pop("stuck_pending", None)
        if isinstance(pending, dict) and pending.get("stage") == stage and pending.get("kind") == kind:
            self.state.setdefault("stuck_asked", {})[str(pending.get("signature") or "")] = {
                "answer": " ".join(words.split())[:100], "at": _now()}
        self.state["asked"] = {}
        self.save_state()
        self.drop_standing()                   # E3: the question about the refusal is closed (the answer was read above)
        if question.is_file():
            question.replace(self.question_path(answered=True))

    # t-667 D14: the BODIES of `take_answer`'s branches. The ladder, its side-effecting conditions and its order stay in
    # `take_answer`; a body runs only when its condition holds there, and returns nothing.
    def _decline_delivery(self, words: str) -> None:
        """t-667 D14: a person's "no delivery" (Lead's decision Q1, FR-9: it has an executor): the delivery is closed as declined -
        a mark like the one `continue` writes, so the story goes on to the retro - with no conductor call."""
        said = self.s0_quote(words)
        did = f"nothing outward: the person declined the delivery ({said})"
        # the person's words, whole, in a file of their own: the `mr` order is called off WITH them (`settle_mr_from_mark`, FR-8, F-7)
        path = self.words_file(words, "delivery")
        self.state["delivery"] = {"done": True, "at": _now(), "action": "declined_by_person", "did": did,
                                  "words_file": str(path) if path else ""}
        self.answer_row("S8 delivery: ", words.strip(), what="your answer about the delivery")
        self.journal_run({"kind": "delivery", "outcome": "declined_by_person"})
        print(f"delivery: {did}")

    def _keep_s0_words(self, words: str) -> None:
        """t-667 D14: a stop of S0's own, answered before the story has a pipeline.json: there is no `waiver.py` to write into,
        so a conductor could only read the words and hand back the same block (S0 "promised `go on` and never read the answer").
        The words wait for the next S0 step, which reads them against the tokens the stop offered (`s0_read_word`); no
        conductor and no judge."""
        block = self.state["s0_block"]
        self.state["pending_words"]["S0"] = words
        self.answer_row(f"S0 {block}: ", words, what="your answer at the start of the story")
        print(f"S0 {block}: the answer is kept and read in the next S0 step")

    def _answer_arrival_not_waiting(self, words: str, qtext: str, stage: str) -> bool:
        """t-2181 PC-7 B2: the answer to `arrival.not_waiting` (FR-9: each token has an executor; FR-12: code reads a token, never a
        meaning). The FIRST non-empty line is the token (`s0_normalize`); the whole answer is the person's words, by FILE. A token is
        written to `launch["arrival"]["answer"]` and `arrival_record` carries it out in the same process (`re-ground`: the arrival and the
        rework it owes; `ignore`: the word is dropped; `stop`: nothing runs, exit 0) - the question is never asked again with the same
        text (FR-7). A token with no pending word (nothing waits for it any more) is said and taken. Any other answer is new words:
        the seam, with `re-ground` / `ignore` as its doors. True = a token was taken."""
        first = next((line for line in str(words).splitlines() if line.strip()), "")
        token = self.s0_normalize(first)
        if token not in self.ARRIVAL_TOKENS:
            self.unread("arrival_not_waiting", stage, "", qtext, words=words, doors=("re-ground", "ignore"),
                        lead=self.unread_lead(words), again=lambda said: self.held_question(said))
            return False
        pending = (self.state.get("launch") or {}).get("arrival")
        if not isinstance(pending, dict):
            print(f"{self.task}: no word about the code is waiting any more; your answer ({token}) changes nothing")
            return True
        pending["answer"] = token
        self.save_state()
        return True

    def _first_look_answer(self, words: str, qtext: str, stage: str) -> bool:
        """t-2277 FL-5: the answer to `first_look.dead` (FR-9: each token has an executor; FR-12: code reads a token, never a meaning). The
        FIRST non-empty line is the token (`s0_normalize`), the whole answer is the person's words, by FILE. `continue`: `controller.py
        --operation first_look_continue --words-file <the words> --source-head H --register-hash R` with `(H, R) =
        first_look.current_keys` - the keys of NOW, so a later head or register asks again (FR-7). `stop`: the controller `await` with cause
        `first_look_stop` held from S3, through the one body of the hold (`_act_await_implementation`, which prints the first look's own
        packet for that cause, FL-6); its `Stop` is taken here (take_answer files the answer and clears the question first) and the loop's next `where` answers
        `awaiting_implementation` and ends the run, exit 0. Any other answer is new words for the conductor, once (`unread`). A command the
        controller refuses brings the question back with its words (`held_question`). True = a token was taken. ANY answer marks the walk as
        asked (`first_look.mark_asked`): the question is not put again for this walk, whatever the words were (B3, FR-7) - it is marked HERE and
        not when it is raised, so a question nobody has answered yet still comes back after a restart (AR-25)."""
        import first_look as FL
        FL.mark_asked(self.task_root)
        token = self.s0_normalize(next((line for line in str(words).splitlines() if line.strip()), ""))
        if token not in ("continue", "stop"):
            self.unread("first_look_dead", stage, "", qtext, words=words, doors=("continue", "stop"),
                        lead=self.unread_lead(words), again=lambda said: self.held_question(said))
            return False
        self.answer_row(f"{stage} first look ({token}): ", words.strip(), what="your answer about the first look")
        try:
            if token == "continue":
                self._first_look_continue(stage)
            else:
                try:
                    self._act_await_implementation({"action": "await_implementation", "cause": "first_look_stop", "held_from": "S3"})
                except Stop:
                    pass
        except Refusal as refusal:
            # remains: the person's own question comes back with the reason (a refused carrying-out); nothing was changed
            raise self.held_question("Your answer could not be carried out, so nothing changed.", refusal.text)
        return True

    def _same_code_answer(self, words: str, qtext: str, stage: str) -> bool:
        """t-2277 FL-6: the answer to `first_look.same_code` (FR-9: each token has an executor; FR-12: code reads a token, never a meaning).
        The FIRST non-empty line is the token (`s0_normalize`), the whole answer is the person's words, by FILE. `continue` is the SAME
        operation as the `continue` of `first_look.dead` (`first_look_continue` with the keys of now, PC-6); `wait` and `source` change
        nothing here: `first_look_code_look` of this same process reads the row this answer leaves in `driver-answers.jsonl` and prints
        the packet / the restart command (exit 0). Any other answer is new words for the conductor, once (`unread`). A command the
        controller refuses brings the question back with its words (`held_question`). True = a token was taken. The row of the answer
        carries that first-line token (F1, critic t-2528), so a second line of the person's words changes nothing about the executor."""
        token = self.s0_normalize(next((line for line in str(words).splitlines() if line.strip()), ""))
        if token not in ("wait", "source", "continue"):
            self.unread("first_look_same_code", stage, "", qtext, words=words, doors=("wait", "source", "continue"),
                        lead=self.unread_lead(words), again=lambda said: self.held_question(said))
            return False
        self.answer_row(f"{stage} first look, the code ({token}): ", words.strip(), what="your answer about the code")
        # F1: the row carries the token THIS executor read (the first line), never the whole normalized answer: `first_look_code_look`
        # and the date line of the next question read the row by that token, so `source` + a second line still prints the command
        self.record_answer_row(token)
        if token == "continue":
            try:
                self._first_look_continue(stage)
            except Refusal as refusal:
                # remains: the person's own question comes back with the reason (the `_first_look_answer` pattern); nothing was changed
                raise self.held_question("Your answer could not be carried out, so nothing changed.", refusal.text)
        return True

    def _answer_absent_side(self, words: str, qtext: str, stage: str) -> bool:
        """t-2559 (W2 B3): the answer to `awaiting.absent_side` (FR-9: each token has an executor; FR-12: code reads a token, never a
        meaning). The FIRST non-empty line is the token (`s0_normalize`), the whole answer is the person's words, by FILE. `relaunch`: nothing
        changes - the hold stands and the loop's next `where` prints the packet and ends with exit 0, as before. `not ours`: `_side_not_ours`.
        Any other answer is new words for the conductor, once (`unread`). A refused carrying-out brings the question back with its words
        (`held_question`), nothing half-done is lost (every step is repeatable). True = a token was taken."""
        token = self.s0_normalize(next((line for line in str(words).splitlines() if line.strip()), ""))
        if token not in self.ABSENT_SIDE_TOKENS:
            self.unread("absent_side", stage, "", qtext, words=words, doors=self.ABSENT_SIDE_TOKENS,
                        lead=self.unread_lead(words), again=lambda said: self.held_question(said))
            return False
        self.answer_row(f"{stage} absent side ({token}): ", words.strip(), what="your answer about the missing part")
        self.record_answer_row(token)
        name = str(self.state.get("absent_side") or "")
        if token == "not ours":
            try:
                self._side_not_ours(name, words.strip())
            except Refusal as refusal:
                # remains: the person's own question comes back with the reason (the `_same_code_answer` pattern); nothing was lost
                raise self.held_question("Your answer could not be carried out, so nothing changed.", refusal.text)
        else:
            # `relaunch` (t-2562 B-1/B-2): recorded for THIS hold only, so the loop's next `where` asks the next side with no answer and a
            # later process re-offers with a changed lead; nothing else changes. This process asks nothing more once every side answered.
            record = self.state.get("absent_side_answers")
            if isinstance(record, dict) and isinstance(record.get("sides"), dict) and name:
                record["sides"][name] = {"token": token, "at": _now()[:10]}
            self._absent_answered_here = True
        self.state.pop("absent_side", None)
        return True

    def _side_not_ours(self, name: str, words: str) -> None:
        """t-2559 (W2 B3): the side `name` is another team's. In THIS order, each step repeatable on a replay: (1) the project's record
        through `_keep_sides_answer` (the one writer of the registry row, by the person's words; `--no-trace` keeps it in the story only, an
        unreadable registry is said in words and the answer stays in the story, AR-28); (2) the story's record - `deliverable false`, reality
        `substituted`, `source person` through ONE `stage_done.py` call (the writer of `pipeline.sides`, AR-14), which also carries the
        lines of (1) as `--warn`, so the report and gate A read them (t-2562 F-1, AR-22); the story no longer parks;
        (3) the hold is lifted by the controller's own `arrive` naming this side (no source: no code arrived). Other sides are untouched (they
        park the story again on the next `where`, one question each). A write that is refused is a `Refusal`."""
        if not name:
            raise Refusal("the part of the product this answer is about is not recorded, so nothing was changed; start the story again")
        import contract
        since = str(contract.awaiting(self.pipeline()).get("since") or "")
        lines = self._keep_sides_answer(name, "another team's", words=words, where="the answer to the question about the missing side after S5")
        sets = self.side_set_args(name, reality=self.SIDE_SUBSTITUTED, deliverable="false", source="person", at=_now())
        self.py("stage_done.py", "--task", self.task, *[part for item in sets for part in ("--set", item)],
                *[part for line in lines for part in ("--warn", line)], check=True)
        self._arrive([name], {}, ["not ours", name, since])
        print(f"{self.task}: `{name}` is another team's at your word; the wait is over and the tests go on against a stand-in for it")

    def _first_look_continue(self, stage: str) -> None:
        """THE `continue` of the first look (FR-9, AR-15), for both of its questions (`first_look.dead`, `first_look.same_code`): the
        controller operation `first_look_continue` with the person's words (by FILE) and the keys of NOW (`first_look.current_keys`), so a
        later head or register asks again (FR-7). A missing words file or a refusal of the controller is a `Refusal` the caller turns into the
        held question."""
        import first_look as FL
        file = self.answer_file()
        if not file:
            raise Refusal("first look: the answer has no words file, so `continue` was not recorded; the question stays")
        heads, register = FL.current_keys(self.task_root)
        self.controller("first_look_continue", "--words-file", str(self.task_root / file), "--source-head", heads, "--register-hash", register)
        print(f"{stage}: first look: your `continue` is recorded for these heads and this register")

    def _answer_s1_not_built(self, words: str, dispatch: str) -> None:
        """t-2181 PC-7 B3: the `not built yet` answer of `s1.no_diff`, the twin of the `s0.no_change` one (AR-19). The side `product` is
        recorded absent, deliverable, `source: person` through `stage_done.py --set` (the writer of `pipeline.sides`, AR-14; the keys of
        `s0_sides_sets`), so the story parks after S5; then the words go to the scout as on every halt (`pending_words`): it goes on with
        the requirements only. A refused write is a `Refusal` (the seam asks), and nothing was filed for the scout."""
        import contract
        sets = self.side_set_args("product", reality=contract.PARKING_REALITY, deliverable="true", source="person", at=_now())
        self.py("stage_done.py", "--task", self.task, *[part for item in sets for part in ("--set", item)], check=True)
        self.state["pending_words"][dispatch] = words

    def _unread_halt_or_review(self, kind: str, stage: str, dispatch: str, qtext: str, words: str) -> None:
        """t-667 D14: the answer to a halt or an S1 source review that no executor of code reads: the conductor records it, the
        words are filed for the role.

        HF2-7 (B2): a halt at S2-S4 over a register that holds questions is answered BY LINES (the halt text shows the open questions
        and how to answer them by id), so the lines are recorded by CODE first (`question_register.record_answers`, the ONE writer
        of answers, AR-14) and the words are journalled as the person's (`human_answer`) in the same move. When every line was a
        token and none was left unread (H31) the conductor is not called and the judge is not asked - the words wait for the
        role (`pending_words`) and nothing else is owed (FR-48, FR-55). Otherwise the conductor reads what code could not, and is
        told what was already recorded (it must not record it again) and which command records an answer to a question."""
        recorded = self.record_halt_words(stage, words) if kind == "halt" else None
        if recorded is not None and recorded["all_tokens"] and not recorded["unread"]:
            self.state["pending_words"][dispatch] = words
            return
        read = self.judged_reply(qtext, words, kind)
        commands = ("assess / accept-gap / review --record / log_append human_answer|escalated / stage_done --set / waiver.py"
                    if recorded is None else "assess / accept-gap / review --record / question_register.py / stage_done --set / waiver.py")
        self.unread(kind, stage, dispatch, "The person answered a " + ("source review" if kind == "s1_review" else "halt") +
                                 f" of dispatch {dispatch} at {stage}. Record what they decided with the "
                                 f"factory's own commands ({commands}), nothing else; the role "
                                 "itself is resumed by the driver afterwards."
                                 + ("" if recorded is None else
                                    " The factory read their lines against the register's questions by code - recorded by code: "
                                    + (", ".join(recorded["recorded"] + [f"{q} (until the report)" for q in recorded["deferred"]]) or "nothing")
                                    + "; do not record these again, and do not journal their words again (the driver did). "
                                    + ("Not read, still open: " + "; ".join(recorded["unread"] + recorded["unknown_ids"]) + ". "
                                       if recorded["unread"] or recorded["unknown_ids"] else "")
                                    + f"An answer they gave to a question in other words is recorded with question_register.py "
                                    f"(--answer QID --reading <letter> | --not-needed QID | --defer QID, with --words-file, --where \"{stage} stop\", "
                                    "--by conductor and the --register-hash that --show prints).")
                                 # `s1_review` gets no options: `record_review` records ANY words as the S1 review before
                                 # the conductor sees them (C1-3 owns that text); a `halt` re-raises as a `halt` (C1-2, C1).
                                 + ("" if kind == "s1_review" else " " + MOVES_RULE + " " + OWN_TOKEN_RULE)
                                 + "\n\n## The question\n" + qtext[:6000]
                                 + (PRE_FILLED + read if read else ""),
                                 words=words)
        self.state["pending_words"][dispatch] = words

    def _delivery_token(self, kind: str, stage: str, qtext: str, words: str, doors: tuple, reenter: bool = False) -> str:
        """The token of an answer to one of the delivery's closed questions, or '' (C1-6c). The FIRST non-empty line is the token
        (`s0_normalize`, A6: a typed carrier, never a token read out of prose); the whole answer is the person's words, by FILE. `stop`
        holds the question; `no delivery` is today's declined mark (`_decline_delivery`); any other word is new words: they go on the
        journal (the delivery step reads them) and then, by default, to the seam, which offers `doors` back (D-0041, edge 7).
        `reenter` (the delivery question alone, F7): the delivery step IS a conductor session that reads their words, so the words
        re-enter it as they always did and no second session reads them first."""
        first = next((line for line in str(words).splitlines() if line.strip()), "")
        token = self.s0_normalize(first)
        if token not in (*doors, "stop"):
            # C-F3 (t-1228): the journal row is the ONLY road of these words to the delivery session (`person_answers`, `reenter`), so a
            # failed write is OWED (`answer_row`): `owed_rows_step` writes it again before the delivery step is built, a second failure
            # is the seam's question - the words never reach a session that cannot read them
            self.answer_row(f"S8 {kind}: ", words.strip(), what="your words about the delivery")
            if not reenter:
                self.unread(kind, stage, "", qtext, words=words, doors=doors, lead=self.unread_lead(words),
                            again=lambda said: self.held_question(said))
            return ""
        self.answer_file()
        self.record_answer_row(token)
        if token == "stop":
            # remains: `stop` holds the question as every closed question does (`stop_held`, FR-7); nothing runs
            raise self.held_question(self.stop_held(self.delivery_stop_door(doors)))
        if token == "no delivery":
            self._decline_delivery(words)
        else:
            self.answer_row(f"S8 {kind} ({token}): ", words.strip(), what="your answer about the delivery")    # owed on a failed write (C-F3)
        return token

    @staticmethod
    def delivery_stop_door(doors: tuple) -> str:
        """C-F1 (FR-2, FR-10): the sentence after `stop` on a delivery question names each door for what it does - the doors that carry
        the delivery on, then `no delivery`, which ENDS it (never listed as a way to get the delivery). A question with no carrying door
        (the report that does not match) names only the one that ends it."""
        carry = [d for d in doors if d != "no delivery"]
        end = "to end the delivery here with nothing sent, answer `no delivery`."
        return ("To carry on, answer " + " or ".join(f"`{d}`" for d in carry) + "; " + end) if carry else end[0].upper() + end[1:]

    def _take_delivery_answer(self, words: str, qtext: str, stage: str) -> bool:
        """`s8.delivery`: `go on` and `retry` are TWO records (`delivery_choice`: go_on | retry, FR-9) and both re-enter the delivery
        step (it is first told what already went out); `no delivery` / `stop` as every delivery question."""
        token = self._delivery_token("delivery", stage, qtext, words, ("go on", "retry", "no delivery"), reenter=True)
        if token in ("go on", "retry"):
            self.state["delivery_choice"] = {"choice": token.replace(" ", "_"), "token": token, "words_file": self.answer_file(), "at": _now()}
            print(f"delivery: {token} - the delivery step goes on with your words")
        return bool(token)

    def _take_delivery_check_answer(self, words: str, qtext: str, stage: str) -> bool:
        """`s8.delivery_check`: `retry` records nothing - the next step of the loop runs the check again; `no delivery` / `stop` as above."""
        token = self._delivery_token("delivery_check", stage, qtext, words, ("retry", "no delivery"))
        if token == "retry":
            print("delivery: the check runs again")
        return bool(token)

    def _take_report_match_answer(self, words: str, qtext: str, stage: str) -> bool:
        """`s8.report_match`: `no delivery` is the declined mark (the report stays as it is); `stop` holds the question. `rebuild` is
        not offered (handoff Q1): any word that is not a door goes to the seam."""
        return bool(self._delivery_token("report_match", stage, qtext, words, ("no delivery",)))

    CLOSED_HELD_TOKENS = ("run again", "leave", "stop")

    def _take_closed_held_answer(self, words: str, qtext: str, stage: str) -> bool:
        """The answer to the `closed.held` question (C1-6a, FR-9: each token has an executor, FR-12: code reads a token, never a
        meaning). The FIRST non-empty line of the answer is the token (`s0_normalize`); the whole answer is the person's words, by
        FILE. `run again` - the controller's `reopen_story` for exactly the dispatches the question named (the existing `next` ->
        `relaunch` loop then starts them, one at a time, behind the stand and build checks); `leave` - `leave_unlaunched` for the
        same set; `stop` - nothing runs, the question is held. Anything else is new words: the seam, with `run again` / `leave` as
        its doors. A refusal of the controller (the work started meanwhile, the story was reopened) is said and the loop asks again
        from `next`: the question comes back CHANGED (edge 9), never a move on a false precondition. True = a token was taken."""
        record = self.state.pop("closed_held", None) or {}
        ids = [str(item) for item in record.get("dispatch_ids") or []]
        first = next((line for line in str(words).splitlines() if line.strip()), "")
        token = self.s0_normalize(first)
        if token not in self.CLOSED_HELD_TOKENS:
            self.state["closed_held"] = record
            self.unread("closed_held", stage, "", qtext, words=words, doors=("run again", "leave"),
                        lead=self.unread_lead(words), again=lambda said: self.held_question(said))
            return False
        # A6: the typed carrier - the audit row holds the TOKEN (`run again` / `leave` / `stop`), never the whole answer read back;
        # the words file is made first, so the row names the file that holds the whole answer (the row is written once)
        self.answer_file()
        self.record_answer_row(token)
        # remains: the journal row of the person's words (FR-8); the answer is carried out whatever the row does
        self.py("log_append.py", "--event", "human_answer", "--task", self.task,
                "--notes", _answer_note(f"closed story, work that never started ({token}): ", words.strip()))
        if token == "stop":
            self.state["closed_held"] = record
            # remains: `stop` holds the question as every closed question does (`stop_held`, FR-7); nothing runs
            raise self.held_question(self.stop_held("If you want the work to run or be left after all, answer `run again` or `leave`."))
        if not ids:
            # an older state names no set: nothing is guessed (FR-41) - the next entry builds the question from `next`
            print("closed story: the question named no dispatches; it is asked again from the controller's own list")
            return True
        operation = "reopen_story" if token == "run again" else "leave_unlaunched"
        try:
            got = self.controller(operation, "--dispatch", ",".join(ids), "--words-file", str(self.task_root / self.answer_file()))
        except Refusal as refusal:
            print(f"closed story: your choice ({token}) could not be carried out and nothing was changed; the question comes back "
                  f"as the story stands now ({refusal.text[-300:]})")
            return True
        print(f"closed story: {'the story is reopened and the work starts' if token == 'run again' else 'the work is left'} "
              f"({', '.join(got.get('dispatch_ids') or ids)})")
        return True

    def _words_door(self, stage: str, block: str) -> str:
        """The command the conductor is told to record a person's free words with, for `block` at `stage`: the words by FILE (the file of
        the answer being read, `answer_file`), never typed inline (axis 5; the S5 class of the inline `--decision`). The command is the
        site's own; the file part is `person_words.door`, the one renderer of the words door (no second text of the option here)."""
        return person_words.door(f"python {self.scripts / 'waiver.py'} --task {self.task} --stage {stage} --block \"{block}\"",
                                 path=str(self.task_root / self.answer_file()))

    def _take_stand_answer(self, kind: str, stage: str, dispatch: str, qtext: str, words: str) -> bool:
        """The answer to `stand_check`'s question (t-667 D14; C1-6b A7). The code reads only what it can name (FR-12): a configured
        stand's NAME (the site's own door: the next entry probes it), `retry` and `go on` - the tokens the question offers, carried
        out by the seam's own executors (`take_seam_answer`: `person_does`; `go_on_as_is` + the block `stand not confirmed`, which S5 and
        S6 both read, as `waiver.py --words-file`) - and anything else, which is the person's own words and goes to the conductor with
        the command to record them if they mean it (FR-4). True = the answer was a name or a token."""
        self.state.pop("stand_question", None)
        asked = self.state.get("asked") or {}
        if not asked.get("offered"):      # a question an older driver asked (temporal, edge 13): the same tokens with the same moves
            asked = dict(asked, options=[{"token": t, "move": self.SITE_MOVES[t]} for t in ("retry", "go on")], block=waiver.STAND_NOT_CONFIRMED_BLOCK)
        token = self.s0_normalize(words)
        named = next((name for name in self.stand_names() if self.s0_normalize(name) == token), "")
        if named:
            self.py("stage_done.py", "--task", self.task, "--set", f"environment={named}",
                    "--set", "environment_pending=true", check=True)
            self.answer_row(f"stand at {stage}: ", words, what=f"the person's words naming the stand at {stage}")
            print(f"{stage}: the stand is `{named}`; it is checked when the stage starts")
            return True
        if token in self.seam_tokens(asked):
            return self.take_seam_answer(words, asked, qtext, stage, dispatch)
        self.unread(
            kind, stage, dispatch,
            f"The person answered the driver's question about the stand at {stage}: no stand "
            "is confirmed for the story, and their words are below. If they say to go on "
            "without a stand, record them with exactly this one command and nothing else:\n"
            f"{self._words_door(stage, waiver.STAND_NOT_CONFIRMED_BLOCK)}\n"
            + MOVES_RULE + " " + OWN_TOKEN_RULE + "\n\n## The question\n" + qtext[:6000],
            words=words, block=waiver.STAND_NOT_CONFIRMED_BLOCK)
        return False

    def _take_stand_login_answer(self, kind: str, stage: str, dispatch: str, qtext: str, words: str) -> bool:
        """The answer to `stand_login_gate`'s question (t-667 D14; C1-6b A6/A7). `retry` and `go on` are carried out by the seam's own
        executors; `by hand` is the same pass (`go_on_as_is` + the block `stand login missing`) plus the site's TYPED record of the
        choice (`state["login_choice"]`: the token and the words it was made with), which `stand_login_gate` reads to write
        `refused.by: person_checks` - `go on` and every pass the conductor recorded from free words leave `left_unchecked`. Anything else
        is the person's own words and goes to the conductor with the command to record them (FR-4). True = a token was taken."""
        self.state.pop("login_question", None)
        asked = self.state.get("asked") or {}
        if not asked.get("offered"):      # a question an older driver asked (temporal, edge 13): the same tokens with the same moves
            asked = dict(asked, options=[{"token": t, "move": self.SITE_MOVES[t]} for t in ("retry", "by hand", "go on")], block=self.STAND_LOGIN_BLOCK)
        token = self.s0_normalize(words)
        if token in ("by hand", "go on") and token in self.seam_tokens(asked):
            self.state["login_choice"] = {"token": token, "words": " ".join(words.replace(self.BOM, "").split()), "at": _now()}
        elif token in self.seam_tokens(asked):
            return self.take_seam_answer(words, asked, qtext, stage, dispatch)
        else:
            self.state.pop("login_choice", None)
            self.unread(
                kind, stage, dispatch,
                f"The person answered the driver's question about the stand's sign-in account at {stage}: the "
                "checks an agent makes by hand on the product's screens cannot start without it, and their words "
                "are below. If they say they will check those screens themselves, or to go on without them, record "
                "their words with exactly this one command and nothing else:\n"
                f"{self._words_door('S6', self.STAND_LOGIN_BLOCK)}\n"
                + MOVES_RULE + " " + OWN_TOKEN_RULE + "\n\n## The question\n" + qtext[:6000],
                words=words, block=self.STAND_LOGIN_BLOCK)
            return False
        return self.take_seam_answer(words, asked, qtext, stage, dispatch)

    def _take_gate_a_dry_answer(self, kind: str, stage: str, dispatch: str, qtext: str, words: str) -> bool:
        """The answer to the `s6.gate_a_dry` question (C1-6b, §3.3; FR-9: each token has an executor, FR-12: a token, never a meaning).
        `reapprove` (offered only when it can run) - the controller's `semantic_reopen` with the person's words as its reason and the
        cases the question named as its scope: S4 goes back to pending and the gate A decision on those cases is stale, so gate A is asked
        again and its `approve` applies the card answers. A refusal of the controller (a role runs, no current gate A) is said, nothing
        was changed, the question comes back. `go on` / `stop`: the seam's executors (`waiver.py --words-file` for the block
        `gate A recorded dry`; `stop_held`). Any other word is new words: the seam, with `reapprove` offered back as its door."""
        asked = self.state.get("asked") or {}
        offered = [str(item) for item in asked.get("offered") or ()]
        token = self.s0_normalize(words)
        if token == "reapprove" and "reapprove" in offered:
            scope = [str(case) for case in (self.state.get("gate_a_dry") or {}).get("cases") or []]
            self.answer_file()
            self.record_answer_row(token)
            self.answer_row("gate A recorded dry (reapprove): ", words.strip(), what="the person's choice to approve gate A again")
            if not scope:
                # remains: the person's own question comes back with the reason; nothing was changed (an older state names no cases)
                raise self.held_question("Your choice to approve gate A again could not be carried out: the question named no cases, so "
                                         "nothing was changed.")
            try:
                self.controller("semantic_reopen", input_data={
                    "reason": words.replace(self.BOM, "").strip(), "affected_scope": scope,
                    "idempotency_key": f"semantic_reopen:gate_a_dry:{self.answer_file()}",
                    "expected_revision": self.controller_state().get("revision", 0)})
            except Refusal as refusal:
                # remains: the controller refused the reopening the person chose (a role runs, no current gate A); the question comes back with its words (FR-1)
                raise self.held_question("Your choice to approve gate A again could not be carried out, so nothing was changed.",
                                         refusal.text)
            print("S6: gate A is asked again; the test design is reviewed first, and the cases are checked by hand after your approval")
            return True
        if token in offered or "reapprove" not in offered:
            return self.take_seam_answer(words, asked, qtext, stage, dispatch)
        self.unread(kind, stage, dispatch, self.generic_prompt(kind, stage, qtext), words=words, block=self.GATE_A_DRY_BLOCK,
                    doors=tuple(offered), lead=self.unread_lead(words), again=lambda said: self.held_question(said))
        return False

    def _unread_kept_gate(self, kind: str, stage: str, dispatch: str, qtext: str, words: str, stand_note: str, apply_words: str = "") -> None:
        """t-667 D14: gate_A, gate_B, conductor, refusal - a block that outlived the recording: an approval that was heard and
        not recorded is kept, then the words go to the conductor. `stand_note` is the note of the stand-gap lines that could not
        be read (`take_stand_gap_answers`), "" for any other answer. `apply_words`: the part of `words` the card lines are read from
        (a second answer's tail is not, t-891 F-2); kept beside the words as `apply` for the recording that comes back."""
        if kind in ("gate_A", "gate_B") and self.gate_approval(kind, words):
            # t-211 / C3 (FR-7): an APPROVAL that was heard and not recorded (the controller refused it, or a stand-gap line did
            # not record). It is kept BEFORE the conductor sees it (a conductor that asks a question ends this process), so the
            # loop coming back to await_gate finds it and records the decision again instead of repairing or asking again.
            # C1-4b (I2): words that are NOT the approval word are never kept as one - they reach the seam, whole, and nothing else.
            self.state["gate_answer_kept"] = {"gate": kind[-1], "words": words, "at": _now(), "approved_by": "token",
                                              "source_revision": self.controller_state().get("source_revision"),
                                              **({"apply": apply_words} if apply_words and apply_words != words else {})}
            self.save_state()
        read = self.judged_reply(qtext, words, kind)
        lines_note, self.question_lines_note = getattr(self, "question_lines_note", ""), ""      # GW1-34: told once, to this call
        # RH1-6 (A-AC5): the controller refused this APPROVAL over open items: the conductor is told whose refusal it is, and given the
        # recording command for each item - not "words that are not the approval word". Items unreadable: today's prompt (FR-41).
        items = self.gate_open_items(self.gate_refusal) if kind == "gate_A" and self.gate_approval(kind, words) else None
        items_text = self.open_items_text(items, words, self.gate_refusal_parts(self.gate_refusal)[0]) if items else ""
        if lines_note and not items_text:
            items_text = "The person said the gate's approval word; it is kept, and nothing is recorded yet."
        self.unread(kind, stage, dispatch,
                    self.generic_prompt(kind, stage, qtext, items_text) + stand_note + lines_note + (PRE_FILLED + read if read else ""),
                    words=words)

    def _file_words(self, kind: str, dispatch: str, asked: dict, words: str, qtext: str, seam_token: bool) -> None:
        """t-667 D14: the words belong to the dispatch the refusal itself names, even when the question header carried none. Live
        TP1-13797 run 5: a `resolve_return` packet names its `dispatch_id`, the question header does not, so nothing filed
        the answer, the controller asked again and the identical packet reached the person three times. A boundary the person
        has answered must never be re-asked with the same text. t-217 / F-cmp2-22 (FR-16, FR-7, FR-8): WHOSE answer it is is a
        FIELD (`asked.dispatch`, set when the question was raised), never an id read out of the question's text. Two runs filed a
        person's words for the wrong dispatch that way: a gate-A packet that quotes "the S2 handoff of S2-qa-requirements-tester-1"
        (cmp2-18) and a probe's hint "--dispatch <critic id>" (cmp2-26). The field outranks the text; `seam_token` (the answer was
        a token of a question the seam raised) is never filed as words for a role."""
        if kind in ("gate_A", "gate_B"):
            # The gate's keeper is `gate_answer_kept` (`record_by_code` / the kept answer), never `pending_words`.
            print(f"gate {kind[-1]}: the answer is "
                  + ("kept for the gate" if self.state.get("gate_answer_kept")
                     else "recorded by code" if self.gate_approval(kind, words)
                     else "taken through the options of the question" if seam_token else "with the conductor")
                  + " and filed for no dispatch")
        elif dispatch:
            if kind in ("conductor", "refusal"):
                # The kinds a refusal raises: their words were once filed by the id the text happened to name
                # (a `resolve_return` packet, run 5), and the field now says it. Every other kind with a dispatch
                # (a halt, a review, a threshold stop) filed its own words in its own branch above, and a package or
                # retro answer is not words for a role at all. A TOKEN of a seam question is not words for a role either:
                # `retry` / `restart` resuming the role with the token as its instruction was the hole (F6).
                if seam_token:
                    print("the answer is a token of the question's own options: it is not filed for a role")
                else:
                    self.state["pending_words"][dispatch] = words
                    print(f"the answer is filed for {dispatch}, the dispatch the question is about")
        elif "blocks" in asked or kind not in ("conductor", "refusal"):
            # t-217 O2 (critic t-244): the text reading below is for the two kinds an OLDER driver raised from a refusal.
            # This driver's questions of every other kind (an `environment` stop quoting `--dispatch S6-qa-test-runner-1`
            # in its own words) carry no dispatch on purpose, and their words are not words for a role.
            print("the answer is filed for no dispatch: the question names none")
        else:
            # A question an OLDER driver asked (no `blocks` key): its text is all there is. The two spellings a
            # refusal wrote a dispatch in survive, and a capture counts only when it IS a dispatch id by shape and
            # is the only one the text names (`<critic id>`, a placeholder, is not one).
            named = sorted({m for m in (re.findall(r'"dispatch_id":\s*"([^"]+)"', qtext or "")
                                        + re.findall(r'--dispatch\s+(\S+)', qtext or ""))
                            if DISPATCH_ID_RE.fullmatch(m)})
            if len(named) == 1:
                self.state["pending_words"][named[0]] = words
                print(f"the answer is filed for {named[0]}, named by the refusal itself")
            else:
                print("the answer is filed for no dispatch: the question names none"
                      if not named else "the answer is filed for no dispatch: the question names more than one")

    # --- dry run -------------------------------------------------------------------------------
    def describe(self) -> int:
        print(f"story_run --dry-run: task {self.task}, project {self.project}, plugin {self.plugin}, "
              f"model {self.model}"
              + (f" ({'named' if self.model_explicit else 'default_model.codex of references/driver-infra.json'})"
                 if self.host == "codex" else "")
              + f", {self.host} {' '.join(self.claude) or '<not found>'}")
        print(f"until: {self.until or 'end'}; stand remedy: {self.stand_remedy()}")
        if self.flags.answer:
            asked = self.state.get("asked") or {}
            if asked.get("kind") == "questions":
                print(f"would record the answers in {self.flags.answer} by code, per open question, and resume the "
                      "role's own session with the words (no conductor)")
            else:
                print(f"would route the answer in {self.flags.answer} to the conductor as kind `{asked.get('kind')}`"
                      if asked else "no question is open: the answer would be refused")
        if not (self.task_root / "pipeline.json").is_file():
            print("pipeline.json is absent: would run S0 by code — ticket_adapter get --raw-dir (the tracker by REST; a read "
                  "that fails is asked of the person, a lost login stops the run, no model is called; a dry run asks "
                  "nothing and reads nothing), environment_selection, "
                  "readiness --write --probe-vcs / --require, env_probe, pipeline.json, stage_done S0, controller initialize")
            return EXIT_DONE
        try:
            action = self.where()
        except Refusal as exc:
            print("where refused:\n" + exc.text)
            known = route_known(exc)
            print(f"would: {'known refusal ' + known[0] + ' -> ' + known[1] if known else 'call the conductor'}")
            return EXIT_DONE
        print("where: " + json.dumps(action, ensure_ascii=False))
        if self.until_reached(action):
            print(f"would stop: --until {self.until} reached")
            return EXIT_DONE
        kind, stage = action.get("action"), str(action.get("stage") or "")
        stages = self.stages()
        example = self.claude_cmd("<prompt>", agent="<role>", system_file=Path("<state/driver-tmp/<dispatch>.system.md>"))
        if kind == "prepare_stage":
            if stage == "S5":
                scope = self.stage_scope("S5")
                todo = [w for w in scope.get("windows") or [] if "qa-code-critic" not in (w.get("accepted_by") or {})]
                print(f"S5 windows left: {json.dumps(todo, ensure_ascii=False)[:1500]}")
                print("would: story_step start qa-automator --scope <window> -> claude -p -> bind -> finish --not-complete; "
                      "then qa-code-critic the same; concerns -> rework --cause test_defect (cap from repair_budget). At the cap, "
                      "when the count cannot be read, or when the critic's findings are nobody's round: ONE closed question to "
                      "the person (round / debt / fixed / stop, or review for the critic's own doubt) BEFORE the critic's finish; "
                      "nothing is dispatched or closed over it")
            elif stage == "S6":
                print("would: stage-scope automation / manual -> qa-runner per block -> finalize_task.py")
            elif stage == "S7" and self.s7_life():
                try:
                    waiting = len(self.s7_repair_rows()) + len(self.s7_rejudge_rows())
                except Refusal:
                    waiting = 0
                print(f"the failure analyst's triage is accepted; S7 stays open for the repairs of {waiting} test(s): would run their "
                      "rounds (S5 qa-automator rework per test, cap from repair_budget; at the cap ONE closed question per test), then "
                      "close S7 by code (finalize_task, code_only S7, stage_done)")
            elif stage == "S7":
                try:
                    print("failures to triage: " + (self.failures_to_triage() or "none -> code_only S7 + stage_done"))
                except Refusal as exc:
                    print("S7 entry: " + exc.text)
            elif stage == "S9":
                print("would: bug reporter (chosen drafts) + delivery conductor call once, then the retro "
                      f"(retro_mode {self.pipeline().get('retro_mode') or 'full'}; question asked: {bool(self.state.get('retro_asked'))})")
            else:
                roles = stages.get(stage, {}).get("roles") or []
                print(f"would: story_step start {stage} {' then '.join(roles)} -> claude -p -> bind -> handoff check -> finish")
        elif kind == "await_gate":
            print(self.gate_repair_would(str(action.get("gate") or "A")))
            print(f"would: write state/driver-question.md from gate_brief --gate {action.get('gate')} + gate_preflight, exit 3")
        else:
            print(f"would: {kind} -> " + ("resume the saved session" if self.state["pending_words"] else "known table / conductor"))
        print(f"{self.host} command shape: " + " ".join(example))
        return EXIT_DONE


def main() -> int:
    # FR-43 (t-363 B2, B-253 g): the driver's log is read WHILE it runs, and stdout to a file is block-buffered, so on
    # 02.10 the log of a driver that died silently was empty. Line-buffered from the first line; a stream with no
    # `reconfigure` (a StringIO in a test, a pipe under an old Python) is skipped without a word (the `except`).
    try:
        import console_io
        console_io.utf8_stdio(line_buffering=True)
    except ImportError:
        pass
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawTextHelpFormatter)
    ap.add_argument("--task", required=True)
    ap.add_argument("--answer", help="a file with the person's words for the open question")
    ap.add_argument("--until", choices=["gate_A", "gate_B", "end"], default="end")
    ap.add_argument("--dry-run", action="store_true", help="print the actions for the current state, run nothing")
    ap.add_argument("--model", default=None,
                    help="the model the roles run under: claude - default sonnet; codex - default "
                         "`default_model.codex` of references/driver-infra.json")
    ap.add_argument("--host", choices=list(HOSTS), default=None,
                    help="the CLI the roles run under: claude (`claude -p`, the default) or codex (`codex exec`); "
                         "absent, `driver.host` of config.json, else claude")
    ap.add_argument("--plugin-dir", help="plugin root (default: this script's own)")
    ap.add_argument("--project", help="project root (default: the nearest qa-factory/config.json above cwd)")
    ap.add_argument("--mr")
    ap.add_argument("--branch")
    ap.add_argument("--commit")
    ap.add_argument("--ungrounded", action="store_true")

    def pair(value: str, what: str, door: str) -> tuple:
        """`<name>=<word>` as a pair, or an argparse refusal that names the form (FR-1, FR-2: the door is the corrected flag)."""
        name, sep, word = str(value).partition("=")
        name, word = name.strip(), word.strip()
        if not (sep and name and word) or "." in name:
            raise argparse.ArgumentTypeError(f"`{value}` is not {what}. {door}")
        return name, word

    def side_flag(value: str) -> tuple:
        name, word = pair(value, "a side and its reality", "Give --side <name>=<reality>, the name without a dot.")
        import stage_done      # the ONE reader of the reality words (`references/side-realities.json`) is the writer's own check
        try:
            stage_done.coerce_value(f"sides.{name}.reality", word)
        except ValueError as exc:
            raise argparse.ArgumentTypeError(f"--side {value}: {exc}. Start again with --side {name}=<one of those words>.")
        return name, word

    def reference_flag(value: str) -> tuple:
        return pair(value, "a side and the stand that runs its old version", "Give --reference <side>=<stand>, the side without a dot.")

    ap.add_argument("--side", action="append", type=side_flag, metavar="NAME=REALITY",
                    help="a side of the product that is not real on this stand, e.g. backend=substituted (repeatable); "
                         "the words are those of references/side-realities.json")
    ap.add_argument("--reference", action="append", type=reference_flag, metavar="SIDE=STAND",
                    help="the stand that still runs the OLD version of a side, to be walked as the reference (repeatable)")
    ap.add_argument("--ticket-file")
    ap.add_argument("--env")
    ap.add_argument("--branch-suffix", default="")
    ap.add_argument("--no-trace", action="store_true", dest="no_trace",
                    help="experiment: nothing leaves the project (P8)")
    ap.add_argument("--skip-sources", dest="skip_sources", metavar="FILE",
                    help="a text file, one source per line and why it is left out: read when a story STARTS, "
                         "before anything is fetched (B-231)")
    ap.add_argument("--max-boundaries", default=80)
    ns = ap.parse_args()
    if ns.skip_sources:
        # The driver changes into the project root (`Driver.__init__`), so a path the person typed
        # relative to THEIR folder would point somewhere else from then on.
        ns.skip_sources = str(Path(ns.skip_sources).resolve())
    try:
        driver = Driver(ns)
    except SystemExit as exc:  # hooklib.require_project refused
        return int(exc.code or EXIT_ERROR)
    except Stop as stop:       # the host cannot start (`Driver.host_refusal`): the reason, the code, no traceback
        print(f"story_run: stopped — {stop.reason}", flush=True)
        return stop.code
    if ns.dry_run:
        return driver.describe()
    return driver.run()


if __name__ == "__main__":
    sys.exit(main())
